/* ФиксАР — разговор через публичный шлюз.
 *
 * Адрес строго тот, что перечислен в connect-src зоны: любое другое имя
 * браузер вырежет молча, в журнале сервера будет пусто, а Safari скажет
 * только «Load failed». Так 08.08 лёг портал.
 *
 * Токен анонимной сессии живёт в localStorage: перезагрузка страницы не должна
 * терять дело. Он же уедет с человеком, когда тот войдёт — вход привязывает
 * второй канал к тому же субъекту, и переносить ничего не придётся.
 */
(function () {
  "use strict";

  /* ── Язык оболочки ───────────────────────────────────────────────────
     Словарь и выбор языка живут в lang.js, подключённом ДО этого файла.
     Здесь только короткое имя, чтобы не писать window.ЯЗЫК.T на каждом шагу.

     Запасной вариант — тождество: если lang.js не доехал до хранилища,
     страница обязана открыться по-русски, а не упасть на первом же слове.

     ГДЕ ПЕРЕВОД ПРИМЕНЯЕТСЯ. На ГРАНИЦЕ ВЫВОДА — там, где значение уже стало
     текстом для человека (el, say, render, textContent, title, placeholder), а
     не у литералов. Причина не в лени: часть русских строк здесь — служебные
     значения, которые потом сравнивают (`{вид:"идёт"}` … `if (что.вид ===
     "идёт")`). Переведи их у литерала — и сравнение молча перестанет
     совпадать. На границе рождается НОВАЯ строка для экрана, а само значение
     остаётся русским и сравнивается как прежде.

     Исключение — куски, склеиваемые с переменной: их результат в словаре не
     найдёшь, поэтому они обёрнуты T() поимённо. */
  var T = (window.ЯЗЫК && window.ЯЗЫК.T) || function (с) { return с; };

  /* СЛОВО-ПОДТВЕРЖДЕНИЕ сверяем в ОБОИХ написаниях.

     Преграды «наберите слово, чтобы подтвердить» переводятся вместе с
     остальной оболочкой: англичанину показывают delete. А сверка стояла с
     русским «удалить» — и набранное им никогда бы не совпало. Преграда,
     задуманная как «убедись, что имеешь в виду именно это», превратилась бы в
     «этого не сделать вовсе», причём молча: кнопка просто не оживает.

     Ровно этим уже оборачивалось длинное тире в названии дела (см. заведение
     удаления ниже) — тот же класс поломки, вторая встреча.

     Службе при этом уходит РУССКОЕ слово: контракт /vault/erase ждёт именно
     «удалить», и переводить его значило бы сломать стирание на сервере. */
  function сходится(введено, эталон) {
    var в = String(введено == null ? "" : введено).trim().toLowerCase();
    var э = String(эталон == null ? "" : эталон).trim();
    return в === э.toLowerCase() || в === String(T(э)).trim().toLowerCase();
  }

  /* Первая вынесенная граница. Адреса и сам fetch принадлежат core-модулям,
     а не этому файлу. Падаем сразу, если HTML нарушил порядок скриптов:
     частично работающая оболочка опаснее явной ошибки загрузки. */
  var CORE = window.FixarCore;
  if (!CORE || !CORE.config || !CORE.http) {
    throw new Error("FixarCore config and http must load before app.js");
  }
  var API = CORE.config.apiOrigin;
  var HTTP = CORE.http;
  /* Свой сайт — для ссылок, которые человек СКОПИРУЕТ и унесёт наружу
     (страница подбора). Не location.origin: оболочку открывают и с
     b-cdn.net-зеркала, и с localhost при отладке, а на визитке должен стоять
     тот адрес, который человек назовёт вслух. */
  var САЙТ = CORE.config.siteOrigin;
  var KEY = "fixar.token";
  /* Какое дело открыто. Переживает перезагрузку, но НЕ подставляется вслепую:
     после выхода из аккаунта ключ остаётся в браузере, а дело — у прежнего
     владельца, и открылось бы чужое. Поэтому восстановление проверяет, что
     дело всё ещё в списке этого человека. */
  var CASE_KEY = "fixar.case";
  /* Незавершённая отправка: идентификатор сообщения и ровно тот payload,
     который уехал. По контракту Inbox повтор — это ТОТ ЖЕ идентификатор с ТЕМ
     ЖЕ payload; изменённый payload под тем же идентификатором сервер обязан
     считать конфликтом, а не новым сообщением. Поэтому храним пару целиком и
     переживаем перезагрузку: иначе повтор после падения вкладки стал бы
     вторым сообщением.

     Ключ ИМЕННОЙ — с суффиксом субъекта: после смены аккаунта неотправленный
     текст прежнего человека оставался лежать бессрочно и доставался
     следующему. У дела (CASE_KEY) владелец проверяется при восстановлении, у
     отправки не проверялся ничем.

     ХРАНЯТСЯ СПИСКОМ ПО client_message_id, а не одним слотом. Одним слотом
     было так: вкладка А ведёт дело А, отправка зависла (предел 60 секунд); в
     хранилище лежит её запись. Человек пишет в дело Б во второй вкладке —
     beginSend видит другое дело и МОЛЧА перезаписывает чужую запись, а
     endSend вкладки Б потом сносит ключ целиком, не глядя, чья это запись.
     Дальше вкладку А достаточно перезагрузить: записи нет, тот же текст
     получит НОВЫЙ идентификатор, ключ (владелец, канал, client_message_id) в
     службе дел не совпадёт — и вместо повтора выйдет второе сообщение или
     второе дело. Механизм, построенный ровно против этого, ломался тем, что
     человек открыл вторую вкладку.

     У каждой записи есть имя вкладки. Своя находится после перезагрузки
     (sessionStorage переживает F5), чужая — только когда остыла, то есть
     когда её вкладка заведомо уже не ждёт ответа. */
  var SENT_PREFIX = "fixar.sent";

  /* Номер общего разговора. ЗАЧЕМ ОН ВООБЩЕ ПОЯВИЛСЯ.

     Разговор без дела не существовал как предмет НИГДЕ: у службы разбора нет
     базы, в ответе `/inbox/messages` идентификатора нет, память — переменная
     в этом браузере. Следствие вышло наружу дважды. Человек 31.08.2026
     попросил «дай номер этого разговора» и не получил ничего — назвать было
     нечего. А жалоба через `/ошибка` на этот же разговор приходила оператору
     с пустым делом: прочитать её он мог, а найти сам разговор — нет.

     Номер НЕ ЗАВОДИТ РАЗГОВОР НА СЕРВЕРЕ, и это намеренно: хранить его там
     значило бы завести дело, не спросив человека, — ровно то, чего он не
     просил, и о чём написано в самой службе. Это имя для журналов: службы
     пишут его строкой, и по нему найдётся, что происходило.

     Именной, как слоты отправок: в браузере бывает не один человек. */
  var TALK_PREFIX = "fixar.talk";

  /* ИМЯ ЭТОЙ ВКЛАДКИ.

     sessionStorage — единственное хранилище, которое переживает перезагрузку
     И при этом не общее у вкладок: копия заводится при ОТКРЫТИИ вкладки, а не
     при загрузке страницы. Ровно это здесь и нужно: своя незавершённая работа
     обязана найтись после F5, чужая — не обязана найтись никогда.

     Ни localStorage (общий на браузер), ни переменная в памяти (умирает от
     перезагрузки) этого не дают. */
  var ВКЛАДКА = (function () {
    var имя = "t" + Date.now().toString(36) + "-" +
              Math.random().toString(36).slice(2, 8);
    try {
      var было = sessionStorage.getItem("fixar.tab");
      if (было) return было;
      sessionStorage.setItem("fixar.tab", имя);
    } catch (e) {
      /* Приватный режим без sessionStorage: имя живёт только в памяти, и
         перезагрузка выглядит как открытие новой вкладки. Своя запись тогда
         не найдётся сразу — она станет доступна как осиротевшая, через
         ЧУЖОЕ_ОСТЫЛО_МС. Хуже, но не опасно: потери нет, есть задержка. */
    }
    return имя;
  })();

  /* Сколько ждать, прежде чем счесть чужую запись брошенной.

     Предел запроса — 60 секунд (api(..., 60000)); дольше него незавершённая
     отправка не живёт ни у кого. Запас сверх этого нужен на то, чтобы вкладка
     успела дописать исход. Взять меньше значит отобрать работу у живой
     вкладки; взять больше — заставить человека ждать возврата своей же
     записи после падения браузера. */
  var ЧУЖОЕ_ОСТЫЛО_МС = 90000;

  /* Записи не копятся вечно. Сутки — предел, после которого повтор всё равно
     бессмыслен: ответа на тот запрос уже не будет, а служба дел о нём помнит
     по своему ключу. Число записей ограничено сверху отдельно — на случай
     вкладки, падающей в цикле. */
  var ОТПРАВКА_ЖИВЁТ_МС = 24 * 60 * 60 * 1000;
  var ОТПРАВОК_ПРЕДЕЛ = 20;
  /* Подтверждение, которое ушло и не получило ответа. Это единственный вызов
     оболочки, СОЗДАЮЩИЙ данные, и единственный, про который нельзя сказать
     «ничего не создано»: сервер мог завести дело и не успеть ответить.
     Хранится подпись предложения и та же отправка целиком, чтобы повтор был
     повтором, а не вторым делом. */
  var CONFIRM_PREFIX = "fixar.confirm";

  /* Именной ключ хранилища. Без имени субъекта запись переживает смену
     аккаунта и достаётся чужому человеку. */
  function slot(prefix) {
    return prefix + "." + (state.principal || "anon");
  }

  /* Номер этого разговора: заводится при первом обращении и живёт, пока не
     сменился человек. Не пережил хранилище (приватный режим) — работаем без
     него: разговор от этого не ломается, теряется только возможность его
     потом найти, и врать про это не надо. */
  function номерРазговора() {
    var ключ = slot(TALK_PREFIX);
    var есть = null;
    try { есть = localStorage.getItem(ключ); } catch (e) { return ""; }
    if (есть) return есть;
    var новый = "talk_" + Math.random().toString(36).slice(2, 10)
                        + Math.random().toString(36).slice(2, 6);
    try { localStorage.setItem(ключ, новый); } catch (e) { return ""; }
    return новый;
  }

  /* Прибрать чужие слоты того же вида: в браузере остаётся ровно один
     человек — тот, кто вошёл сейчас. */
  function dropOtherSlots(prefix) {
    try {
      var mine = slot(prefix), drop = [], i, k;
      for (i = 0; i < localStorage.length; i++) {
        k = localStorage.key(i);
        if (k && k.indexOf(prefix + ".") === 0 && k !== mine) drop.push(k);
      }
      drop.forEach(function (key) { localStorage.removeItem(key); });
      // Слот прежнего формата — без имени — тоже чужой: чей он, узнать нечем.
      localStorage.removeItem(prefix);
    } catch (e) { /* приватный режим — переживём */ }
  }

  var state = { token: null, principal: null, caseId: null,
                // Название открытого дела — для строки «где идёт разговор».
                // Идентификатор там показывать нечестно: человек не узнаёт по
                // нему своё дело.
                caseTitle: null,
                // Открыт ли общий разговор. null — ещё не выясняли, true —
                // Inbox отвечает, false — путь закрыт флагом раскатки, и
                // работаем по-старому, через дело.
                inbox: null,
                domain: null, agent: null, busy: false,
                // Сценарий рабочего места: как человеку удобнее начать.
                // Живёт НА СУБЪЕКТЕ (сервер), не во вкладке: выбор обязан
                // пережить устройство. null — ещё не спрашивали службу,
                // пустая строка — спросили, человек не выбирал.
                scenario: null,
                // Прошёл ли первый разговор. null — не знаем (служба не
                // ответила), и тогда онбординг НЕ показывается: лучше не
                // спросить один раз, чем спрашивать при каждом сбое сети.
                onboarded: null,
                // Сколько у человека дел. Ноль — значит терять нечего, и
                // совет привязать второй вход преждевременен.
                caseCount: 0,
                // Последний прочитанный список дел: по нему решается, можно
                // ли восстановить сохранённое дело. Рядом — признак того, что
                // список ВООБЩЕ прочитан: пустой список и несостоявшийся
                // запрос выглядят одинаково, а решения по ним разные.
                cases: [], casesOk: false };

  var log = document.getElementById("log");
  var chips = document.getElementById("chips");
  var caseBody = document.getElementById("casebody");
  var casePane = document.getElementById("casepane");
  var badge = document.getElementById("badge");
  var casedrop = document.getElementById("casedrop");

  /* Отметка состояния и пилюля удаления показываются ВМЕСТЕ.
     Порознь их прятали бы в четырёх местах, и однажды одно из них забыли бы:
     кнопка «Удалить» осталась бы висеть над пустым экраном, где удалять
     нечего, — а нажатие ушло бы в последнее открытое дело. */
  function отметкаДела(видна) {
    badge.hidden = !видна;
    if (casedrop) casedrop.hidden = !видна;
  }
  var stateEl = document.getElementById("state");
  var notice = document.getElementById("notice");
  var input = document.getElementById("input");
  var sendBtn = document.querySelector(".send");

  /* Направления, с которых можно начать. Список короткий намеренно: выбор из
     девяти на первом экране — это не выбор, а препятствие. */
  var START = [
    { domain: "renovation", agent: "planner",      title: "Ремонт квартиры" },
    { domain: "realty",     agent: "guest_helper", title: "Снять жильё" },
    { domain: "medicine",   agent: "triage",       title: "Здоровье" },
    { domain: "education",  agent: "tutor_planner", title: "Обучение" }
  ];

  function el(t, c, txt) {
    var n = document.createElement(t);
    if (c) n.className = c;
    if (txt != null) n.textContent = T(txt);
    return n;
  }

  function bubble(side, who) {
    var m = el("div", "msg " + side);
    m.appendChild(el("div", "who", who));
    var b = el("div", "bubble");
    m.appendChild(b);
    log.appendChild(m);
    log.scrollTop = log.scrollHeight;
    return b;
  }

  /* Ответ модели приходит с разметкой: заголовки, таблицы, списки, жирный.
     Показывать её сырой — рассыпать таблицу на палки; вставлять через
     innerHTML — пускать вывод модели в разметку страницы. Поэтому разбираем
     сами и строим узлы: что бы модель ни написала, это станет текстом. */

  /* Адрес из ответа модели — недоверенная строка, и в href она попадает
     только через этот разбор.

     Схемы разрешены СПИСКОМ, а не запретом javascript:. Запрет обходится и
     обходится буднично: JaVaScript:, java\tscript:, перевод строки внутри
     слова, %6aavascript — каждый из этих способов старше нас. Разрешение не
     обходится ничем: чего нет в списке, того не будет в href.

     Возврат null означает «это не адрес» — тогда вызывающий покажет текст
     как текст. Молча пропустить нельзя: человек должен увидеть, что модель
     что-то написала, даже если по этому нельзя перейти. */
  function адрес(raw) {
    var u = String(raw == null ? "" : raw).trim();
    if (/^(https?:\/\/|mailto:)[^\s]+$/i.test(u)) return u;
    // Свой путь и якорь: ведут внутрь оболочки, схемы не несут. Двойной слэш
    // в начале исключён — это чужой хост без объявленной схемы.
    if (/^\/(?!\/)[^\s]*$/.test(u) || /^#[^\s]*$/.test(u)) return u;
    return null;
  }

  function жирным(target, text) {
    String(text).split(/\*\*/).forEach(function (part, i) {
      if (!part) return;
      if (i % 2) {
        var b = document.createElement("strong");
        b.textContent = part;
        target.appendChild(b);
      } else {
        target.appendChild(document.createTextNode(part));
      }
    });
  }

  /* Разметка ссылки [текст](адрес) и голый https://… раньше доезжали до
     человека палками текста: адрес видно, перейти нельзя, скопировать из
     пузыря неудобно. Теперь это узел <a>, построенный вручную — тем же
     способом, что и всё остальное здесь, и по той же причине: innerHTML
     пустил бы вывод модели в разметку страницы.

     Открывается в соседней вкладке: разговор с агентом — не то, что стоит
     терять, уйдя по ссылке. Отсюда же rel: без noopener открытая страница
     получает ссылку на наше окно и может увести его на свой адрес, а
     noreferrer не отдаёт ей, откуда пришли. */
  var РАЗМЕТКА = /\[([^\]]*)\]\(([^()\s]*)\)|(https?:\/\/[^\s<>"'\u00ab\u00bb]+)/g;
  //: Хвостовая пунктуация к адресу не относится: «зайти на https://x.ru.» —
  //: точка здесь от предложения, а не от домена. Скобка закрывающая тоже:
  //: голый адрес внутри (…) иначе съел бы её.
  var ХВОСТ = /[.,;:!?)\]\u00bb]+$/;

  function ссылкой(target, текст, сырой) {
    var url = адрес(сырой);
    if (!url) {                      // не адрес — показываем как написано
      жирным(target, текст ? "[" + текст + "](" + сырой + ")" : String(сырой));
      return;
    }
    var a = document.createElement("a");
    a.href = url;
    a.className = "mdlink";
    a.target = "_blank";
    a.rel = "noopener noreferrer";
    жирным(a, текст || url);
    target.appendChild(a);
  }

  function inline(target, text) {
    var s = String(text == null ? "" : text), последний = 0, m;
    РАЗМЕТКА.lastIndex = 0;
    while ((m = РАЗМЕТКА.exec(s)) !== null) {
      if (m.index > последний) жирным(target, s.slice(последний, m.index));
      if (m[3] != null) {
        var голый = m[3].replace(ХВОСТ, "");
        ссылкой(target, "", голый);
        последний = m.index + голый.length;
        РАЗМЕТКА.lastIndex = последний;
      } else {
        ссылкой(target, m[1], m[2]);
        последний = m.index + m[0].length;
      }
    }
    if (последний < s.length) жирным(target, s.slice(последний));
  }

  function cells(tr, list, head) {
    list.forEach(function (c) {
      var td = document.createElement(head ? "th" : "td");
      inline(td, c.trim());
      tr.appendChild(td);
    });
  }

  function render(box, text) {
    var lines = String(text).replace(/\r/g, "").split("\n");
    var i = 0, list = null, para = null;

    while (i < lines.length) {
      var line = lines[i];

      if (/^\s*\|/.test(line) && /^\s*\|[\s:|-]+\|?\s*$/.test(lines[i + 1] || "")) {
        list = null; para = null;
        var t = el("table", "md"), head = document.createElement("tr");
        cells(head, line.split("|").slice(1, -1), true);
        t.appendChild(head);
        i += 2;
        while (i < lines.length && /^\s*\|/.test(lines[i])) {
          var tr = document.createElement("tr");
          cells(tr, lines[i].split("|").slice(1, -1), false);
          t.appendChild(tr);
          i++;
        }
        var wrap = el("div", "tablewrap");
        wrap.appendChild(t);
        box.appendChild(wrap);
        continue;
      }

      var h = line.match(/^(#{1,4})\s+(.*)$/);
      if (h) {
        list = null; para = null;
        var hd = el("div", "mdh");
        inline(hd, h[2]);
        box.appendChild(hd);
        i++; continue;
      }

      var li = line.match(/^\s*(?:[-*\u2022]|\d+[.)])\s+(.*)$/);
      if (li) {
        para = null;
        if (!list) { list = el("ul", "md"); box.appendChild(list); }
        var item = document.createElement("li");
        inline(item, li[1]);
        list.appendChild(item);
        i++; continue;
      }

      if (!line.trim()) { list = null; para = null; i++; continue; }

      list = null;
      if (!para) { para = el("p"); box.appendChild(para); }
      else para.appendChild(document.createElement("br"));
      inline(para, line);
      i++;
    }
  }

  function say(side, who, text) {
    /* Перевод берём ЦЕЛОЙ строкой. Ответ модели длинный и в словаре не
       найдётся — пройдёт насквозь нетронутым; служебная фраза короткая и
       совпадёт точно. Разбирать её на куски нельзя: тогда под перевод попал бы
       и кусок чужого текста. */
    var b = bubble(side, T(who));
    render(b, T(text));
    log.scrollTop = log.scrollHeight;
    // Читаем только то, что сказали человеку, а не то, что сказал он сам.
    if (side === "bot" || side === "system") озвучить(b, text, side === "bot");
    return b;
  }

  /* СРЫВ — НЕ РЕПЛИКА АГЕНТА.

     Жалоба `rep_a719601b8cd54697` звалась «странные сообщения которые не
     должен видеть пользователь». Слова починены 02.09.2026 в `reason`, но
     оставалась вторая половина беды: их произносил АГЕНТ. `say("bot", "Ф", …)`
     рисует пузырь с его подписью и зовёт `озвучить` — то есть человек ещё и
     СЛЫШИТ голосом помощника, что «служба не ответила». Помощник этого не
     говорил: сорвалась дверь, и сказать об этом должна страница.

     ОТКАЗ ПО СУЩЕСТВУ ОСТАЁТСЯ ЕГО РЕПЛИКОЙ, и это не непоследовательность.
     «Дело не заведено: недостаточно кредитов» — ответ ЧЕЛОВЕКУ НА ЕГО
     ДЕЙСТВИЕ, и голос тут верный. 5xx же и оборванная связь — про нас.

     РАЗВИЛКА ЖИВЁТ ЗДЕСЬ ОДНА. Двадцать восемь мест звали `say` напрямую;
     оставь решение каждому — и они разойдутся при первой же правке.

     Приставка и хвост приходят УЖЕ ПЕРЕВЕДЁННЫМИ: `T(...)` остался ровно там,
     где стоял. Второй раз через словарь их не гоним, и причину не гоним
     вовсе — она от службы, и каждая новая оседала бы в `ЯЗЫК.пропущенные()`
     ложным промахом (тот же довод, что у `перечислитьКоманды`). Поэтому
     заметка собирается `textContent`, а не третьим доводом `el`. */
  function сорвалось(приставка, e, хвост) {
    // `e` может не быть вовсе: часть срывов известна нам БЕЗ ошибки — «файл не
    // скачался: связь оборвалась», «список дел не пришёл». Им тоже не место в
    // голосе помощника, а заводить ради них второй помощник значило бы завести
    // второе имя, которого не знают чужие вырезки (см. пояснение выше).
    var слова = (e ? reason(e) : "") + (хвост || "");
    if (e && e.status && e.status < 500) {
      say("bot", "Ф", приставка + слова);
      return;
    }
    var узел = el("div", "casenote");
    узел.textContent = приставка + слова;
    log.appendChild(узел);
    log.scrollTop = log.scrollHeight;
  }

  /* ── Чтение вслух ────────────────────────────────────────────────────

     Читает голосом устройства, а не моделью. Это не экономия — это
     единственное, что говорит по-русски.

     MiMo действительно мультимодальна: у неё есть mimo-v2.5-tts, клонирование
     и конструирование голоса. Но голоса там китайские и английские
     (mimo_default, Bingtang, Moli, Suda, Baihua, Mia, Chloe, Milo, Dean), и
     кириллицу она проговаривает чужими слогами. Проверено кругом: русская
     фраза, пропущенная через синтез и обратно через распознавание, вернулась
     как «De lo por now after, the last duna pre cotavie busque stress da»;
     та же связка на английском вернула текст дословно, а настоящая русская
     речь тем же распознавателем узналась по-русски. Прибор исправен — не
     говорит именно синтез. Появятся русские голоса — сюда добавится ветка,
     и весь остальной обвяз (кнопка, очередь, чистка разметки) останется.

     ГОЛОС ПРЕДПОЧИТАЕМ МЕСТНЫЙ. speechSynthesis в Chrome бывает сетевым: у
     таких голосов localService === false, и текст реплики уезжает к чужому
     поставщику ради того, чтобы прозвучать. Для дела с родом сведений
     medical или legal это ровно то, что закрыто в case_worker воротами
     наружу_нельзя. Поэтому местный голос берём первым, а если в системе
     только сетевой — читаем, но говорим об этом вслух в подписи. Молчать
     об этом нельзя: человек считает, что звук родился на его машине. */

  var РЕЧЬ = {
    голос: null,      // выбранный голос
    сетевой: false,   // он сетевой? тогда предупреждаем
    узел: null,       // пузырь, который читается прямо сейчас
    кусочки: [],
    шаг: 0,
    авто: false,
    искали: false
  };

  var РЕЧЬ_КЛЮЧ = "aios.speak.auto";

  function речьЕсть() {
    return typeof window !== "undefined" &&
           "speechSynthesis" in window &&
           typeof window.SpeechSynthesisUtterance === "function";
  }

  /* Список голосов приходит асинхронно и в разных браузерах по-разному:
     Safari отдаёт сразу, Chrome — после voiceschanged, иногда дважды.
     Поэтому пересобираем при каждом событии, а не один раз на старте. */
  function подобратьГолос() {
    if (!речьЕсть()) return null;
    var все = [];
    try { все = window.speechSynthesis.getVoices() || []; } catch (e) { все = []; }
    var наши = все.filter(function (v) {
      return /^ru($|[-_])/i.test(String(v && v.lang || ""));
    });
    if (!наши.length) { РЕЧЬ.голос = null; return null; }
    var местные = наши.filter(function (v) { return v.localService; });
    РЕЧЬ.голос = местные[0] || наши[0];
    РЕЧЬ.сетевой = !РЕЧЬ.голос.localService;
    return РЕЧЬ.голос;
  }

  /* Разметку, которую render() превращает в узлы, для речи разбираем иначе:
     таблица вслух — это не палки и не колонки, а «ячейка, ячейка.»; ссылка —
     подпись, а не адрес; заголовок — фраза с точкой, иначе голос въезжает в
     следующий абзац без паузы. Куски кода не читаем вовсе: вслух они звучат
     как поломка. */
  function подРечь(текст) {
    var s = String(текст == null ? "" : текст).replace(/\r/g, "");
    s = s.replace(/```[\s\S]*?```/g, " ");
    s = s.replace(/`([^`]*)`/g, "$1");
    s = s.replace(/\[([^\]]*)\]\(([^()\s]*)\)/g, "$1");
    s = s.replace(/https?:\/\/\S+/g, " ссылка ");
    var готово = [];
    s.split("\n").forEach(function (л) {
      if (/^\s*\|[\s:|-]+\|?\s*$/.test(л)) return;          // разделитель таблицы
      if (/^\s*\|/.test(л)) {
        л = л.split("|").slice(1, -1).map(function (c) { return c.trim(); })
             .filter(Boolean).join(", ");
      }
      л = л.replace(/^\s*(#{1,4})\s+/, "");
      л = л.replace(/^\s*(?:[-*•]|\d+[.)])\s+/, "");
      л = л.replace(/\*\*([^*]+)\*\*/g, "$1").replace(/__([^_]+)__/g, "$1");
      л = л.replace(/\*([^*]+)\*/g, "$1");
      л = л.replace(/^\s*[-—–]{3,}\s*$/, "");
      л = л.trim();
      if (!л) return;
      if (!/[.!?…:,;]$/.test(л)) л += ".";                  // пауза между строками
      готово.push(л);
    });
    return готово.join(" ").replace(/\s+/g, " ").trim();
  }

  /* Режем на короткие куски. Не ради красоты: длинную реплику Chrome
     обрывает примерно на пятнадцатой секунде и молчит дальше — известная
     повадка движка. Короткие фразы в очереди этого не встречают. */
  function накусочки(текст) {
    var предел = 180, куски = [], тек = "";
    String(текст).split(/\s+/).forEach(function (сл) {
      if (!сл) return;
      if ((тек + " " + сл).trim().length > предел) {
        if (тек.trim()) куски.push(тек.trim());
        тек = сл;
      } else {
        тек = тек ? тек + " " + сл : сл;
      }
      if (/[.!?…]$/.test(сл) && тек.length > 60) {
        куски.push(тек.trim());
        тек = "";
      }
    });
    if (тек.trim()) куски.push(тек.trim());
    return куски;
  }

  function пометить(узел, читается) {
    if (!узел) return;
    var к = узел.querySelector && узел.querySelector(".sayit");
    if (!к) return;
    к.textContent = T(читается ? "◼" : "🔊");
    к.title = T(читается ? "Остановить чтение"
                       : (T("Прочитать вслух") + (РЕЧЬ.сетевой ? T(" (голос сетевой)") : "")));
    к.setAttribute("aria-pressed", читается ? "true" : "false");
  }

  function замолчать() {
    if (!речьЕсть()) return;
    РЕЧЬ.кусочки = [];
    РЕЧЬ.шаг = 0;
    try { window.speechSynthesis.cancel(); } catch (e) { /* уже молчит */ }
    var был = РЕЧЬ.узел;
    РЕЧЬ.узел = null;
    пометить(был, false);
  }

  function дальше() {
    if (РЕЧЬ.шаг >= РЕЧЬ.кусочки.length) { замолчать(); return; }
    var кусок = РЕЧЬ.кусочки[РЕЧЬ.шаг++];
    var у = new window.SpeechSynthesisUtterance(кусок);
    if (РЕЧЬ.голос) { у.voice = РЕЧЬ.голос; у.lang = РЕЧЬ.голос.lang; }
    else у.lang = "ru-RU";
    у.rate = 1;
    у.onend = function () { if (РЕЧЬ.узел) дальше(); };
    // Ошибку молчанием не глотаем: голос мог отвалиться посреди чтения,
    // и кнопка обязана вернуться в исходное, а не остаться квадратом.
    у.onerror = function () { замолчать(); };
    try { window.speechSynthesis.speak(у); } catch (e) { замолчать(); }
  }

  function прочитать(текст, узел) {
    if (!речьЕсть()) return;
    if (!РЕЧЬ.голос && !подобратьГолос()) return;
    var чистый = подРечь(текст);
    if (!чистый) return;
    замолчать();
    РЕЧЬ.кусочки = накусочки(чистый);
    РЕЧЬ.шаг = 0;
    РЕЧЬ.узел = узел || null;
    пометить(РЕЧЬ.узел, true);
    /* Будильника движку здесь нет намеренно. Расхожее средство от засыпания
       speechSynthesis — resume() по таймеру, но в оболочке setInterval
       запрещён (при медленном ответе он строит очередь), и главное — он тут
       не нужен: от обрыва длинной реплики спасает нарезка, а цепочка
       start → end → start на живом движке проходит все куски сама. */
    дальше();
  }

  /* Вешает кнопку на пузырь. Текст берём ИСХОДНЫЙ, до разбора в узлы:
     из готовой разметки его пришлось бы собирать обратно, и таблица
     склеилась бы в кашу. */
  function озвучить(b, текст, сам) {
    if (!речьЕсть() || !b || !b.parentNode) return;
    if (!РЕЧЬ.голос && !подобратьГолос()) return;   // русского голоса нет — кнопки нет
    var чистый = подРечь(текст);
    if (!чистый) return;
    var стр = b.parentNode;
    if (стр.querySelector(".sayit")) return;
    var к = el("button", "sayit", "🔊");
    к.type = "button";
    к.title = T(T("Прочитать вслух") + (РЕЧЬ.сетевой ? T(" (голос сетевой)") : ""));
    к.setAttribute("aria-pressed", "false");
    к.addEventListener("click", function (ev) {
      ev.preventDefault();
      ev.stopPropagation();
      if (РЕЧЬ.узел === стр) { замолчать(); return; }
      прочитать(текст, стр);
    });
    стр.appendChild(к);
    /* Сам собой читается только ОТВЕТ. Служебные извещения — про кредиты, про
       заявку — кнопку получают, а голос нет: это уведомления, и зачитывать их
       вслух подряд значит превращать ленту в диктора.

       Новый ответ обрывает предыдущий намеренно. При открытии дела реплики
       идут очередью; дочитывать старую, пока пришли две новые, — отставать от
       экрана. Кто хочет прежнюю, нажмёт на ней кнопку. */
    if (сам && РЕЧЬ.авто) прочитать(текст, стр);
  }

  function речьТумблер() {
    var т = document.getElementById("speak");
    if (!т) return;
    if (!речьЕсть() || (!РЕЧЬ.голос && !подобратьГолос())) { т.hidden = true; return; }
    т.hidden = false;
    т.setAttribute("aria-pressed", РЕЧЬ.авто ? "true" : "false");
    т.classList.toggle("on", !!РЕЧЬ.авто);
    т.title = T((РЕЧЬ.авто ? T("Читать ответы вслух: включено") : T("Читать ответы вслух: выключено")) +
              (РЕЧЬ.сетевой ? T(" · голос сетевой, текст уходит поставщику голоса")
                            : T(" · голос местный, текст с устройства не уходит")));
  }

  function речьЗавести() {
    if (!речьЕсть()) return;
    try { РЕЧЬ.авто = localStorage.getItem(РЕЧЬ_КЛЮЧ) === "1"; } catch (e) { РЕЧЬ.авто = false; }
    подобратьГолос();
    речьТумблер();
    try {
      window.speechSynthesis.onvoiceschanged = function () {
        подобратьГолос();
        речьТумблер();
      };
    } catch (e) { /* Safari отдаёт список сразу */ }
    var т = document.getElementById("speak");
    if (т) т.addEventListener("click", function () {
      РЕЧЬ.авто = !РЕЧЬ.авто;
      try { localStorage.setItem(РЕЧЬ_КЛЮЧ, РЕЧЬ.авто ? "1" : "0"); } catch (e) { /* приватный режим */ }
      if (!РЕЧЬ.авто) замолчать();
      речьТумблер();
    });
    // Уход со страницы обязан гасить голос: вкладку закрыли, а он дочитывает.
    window.addEventListener("pagehide", замолчать);
    document.addEventListener("visibilitychange", function () {
      if (document.hidden) замолчать();
    });
  }

  /* ── Индикатор работы: штангенциркуль ────────────────────────────────

     Раньше здесь стояло многоточие в пузыре. Знак честный ровно до тех пор,
     пока ответ приходит быстро; на этой связке он идёт от восьми секунд, и
     неподвижное «…» неотличимо от оборванного соединения — человек сидит и
     гадает, ждать ему или перезагружать.

     Циркуль обмеряет тело, тело меняет форму, циркуль перемеряет заново.
     Движение видно краем глаза и означает буквально то, что происходит:
     разбираются с размером вопроса.

     Разметка и числа взяты из присланной сцены как есть — те же формы, те же
     доли секунды, тот же ход губок. Переписано на голый SVG, потому что
     исходник — компонент на React с JSX, а здесь ни сборки, ни React нет, и
     CSP зоны (default-src 'self') не пустила бы ни то ни другое. */

  var ЦИКЛ = 14.8;                       // 12.8 обмера плюс 2 с на букву
  var МЕТКИ = { куб: 3, кубДержим: 4.1, тре: 7.1, треДержим: 8.2, шар: 11.2 };
  var ТОЧЕК = 72;                        // делится на 3 и на 4: углы
  var РАДИУС = 150;                      // треугольника и квадрата попадают
  var УГЛЫ = [];                         // ровно в отсчёты, а не между ними
  for (var _i = 0; _i < ТОЧЕК; _i++) УГЛЫ.push((_i * 2 * Math.PI) / ТОЧЕК);

  function правильный(сторон, апофема, сдвиг) {
    var шаг = (2 * Math.PI) / сторон;
    return УГЛЫ.map(function (ф) {
      var a = (((ф - сдвиг) % шаг) + шаг) % шаг;
      return апофема / Math.cos(a - шаг / 2);
    });
  }
  var КРУГ = УГЛЫ.map(function () { return РАДИУС; });
  var ФОРМЫ = [КРУГ, правильный(4, РАДИУС * 0.82, 0),
               правильный(3, РАДИУС * 0.6, -Math.PI / 2), КРУГ];

  function плавно(t) {
    t = Math.max(0, Math.min(1, t));
    return t < 0.5 ? 4 * t * t * t : 1 - Math.pow(-2 * t + 2, 3) / 2;
  }

  /* Пропорции инструмента пересчитаны под малый размер, формы и тайминги —
     нет. В исходнике это герой 1920×1080: тело занимает четверть кадра, а
     циркуль вокруг него огромен, и балка при обороте заметает круг 900×900
     при теле в 300. Ужми это до бейджа — тело станет пятном в треть высоты,
     губки истончатся до полупикселя, точки касания исчезнут совсем
     (проверено замером: r=7 при рамке 900 даёт 0.7 px).

     Поэтому инструмент придвинут к телу и утолщён: балка ближе, губки шире,
     раскрытие меньше. Оборот СОХРАНЁН — без него композиция валится набок:
     балка висит под телом, и в неподвижном кадре это читается поломкой, а не
     обмером. Проверено рядом двух вариантов в браузере. */
  /* ЗНАК СКЛАДЫВАЕТСЯ В БУКВУ F — В ТУ ЖЕ, ЧТО И НА ПУСКОВОМ ЭКРАНЕ.

     Это не совпадение и не находка: штангенциркуль И ЕСТЬ F. Стойка со
     шкалой — стержень буквы, два плеча-губки — её перекладины. Инструмент,
     которым отмеряют, начерчен той же рукой, что и первая буква имени.
     Поэтому оба знака оболочки — ожидание в разговоре и сборка имени на
     пуске — сложены ОДНИМ инструментом и приходят к ОДНОЙ букве. Разница
     только в работе: здесь обмеряют меняющееся тело, там собирают слово.

     Губки берут тело СВЕРХУ И СНИЗУ, между верхним и средним плечом — как
     в FIX они берут заготовку. Оттого и мерится высота тела вдоль оси
     инструмента: у шара она при любом угле одна, у квадрата гуляет от
     апофемы к диагонали, у треугольника сильнее всего. Ради этого циркуль
     и обходит тело.

     Оборот ЗАКАНЧИВАЕТСЯ РОВНО: к концу круга инструмент тормозит и встаёт
     прямо, тело к этому времени снова шар. Дальше знак наливается в букву —
     стойка и плечи толстеют и заполняются латунью, шкала со слайдером
     гаснут, тело уходит. Держится F две секунды, ради которых цикл удлинён
     с 12.8 до 14.8. */

  var ОБОРОТОВ = 3;                      // кругов за цикл, как в исходнике
  var РАСКРЫТИЕ = 40;                    // насколько губки размыкаются на
                                         // перетекании; в исходнике 76 —
                                         // половина радиуса тела, много
  var ДЕРЖИМ_Ф = 2.0;                    // секунды, пока буква стоит
  var ЗАЗОР_ТЕЛА = 10;                   // просвет между телом и стойкой

  // Инструмент и буква — одни и те же имена, что в сцене FIX, и близкие
  // числа: это один предмет, показанный в двух местах.
  var ЗНАК = { th: 30, плечо: 250, стойка: 620, серединаБуквы: 0.46 };
  var ЗНАК_Б = { th: 62, плечо: 250, стойка: 620 };

  /* Оборот заканчивается ЦЕЛЫМ числом кругов ровно к началу выдержки —
     иначе буква вставала бы под случайным углом. До последнего перехода
     скорость постоянная, на нём — торможение. */
  function узелSVG(имя, поля) {
    var n = document.createElementNS("http://www.w3.org/2000/svg", имя);
    Object.keys(поля).forEach(function (k) { n.setAttribute(k, поля[k]); });
    return n;
  }

  function поворот(T) {
    var работа = ЦИКЛ - ДЕРЖИМ_Ф;
    if (T >= работа) return 0;
    var доля;
    if (T <= МЕТКИ.шар) {
      доля = T / работа;
    } else {
      var к = (T - МЕТКИ.шар) / (работа - МЕТКИ.шар);
      доля = МЕТКИ.шар / работа + (1 - МЕТКИ.шар / работа) * (1 - Math.pow(1 - к, 3));
    }
    return 2 * Math.PI * ОБОРОТОВ * доля;
  }

  function кадрЦиркуля(ч, T) {
    var s;
    if (T < МЕТКИ.куб) s = 0;
    else if (T < МЕТКИ.кубДержим) s = (T - МЕТКИ.куб) / (МЕТКИ.кубДержим - МЕТКИ.куб);
    else if (T < МЕТКИ.тре) s = 1;
    else if (T < МЕТКИ.треДержим) s = 1 + (T - МЕТКИ.тре) / (МЕТКИ.треДержим - МЕТКИ.тре);
    else if (T < МЕТКИ.шар) s = 2;
    else if (T < ЦИКЛ - ДЕРЖИМ_Ф) s = 2 + (T - МЕТКИ.шар) / (ЦИКЛ - ДЕРЖИМ_Ф - МЕТКИ.шар);
    else s = 3;                          // выдержка: тело уже шар

    var i0 = Math.min(2, Math.floor(s));
    var доля = плавно(s - i0);
    var радиусы = ФОРМЫ[i0].map(function (v, i) {
      return v + (ФОРМЫ[i0 + 1][i] - v) * доля;
    });

    // Губки расходятся на время перетекания и снова сходятся: мерить то,
    // что на глазах меняется, инструмент не может.
    var переходы = [[МЕТКИ.куб, МЕТКИ.кубДержим], [МЕТКИ.тре, МЕТКИ.треДержим],
                    [МЕТКИ.шар, ЦИКЛ - ДЕРЖИМ_Ф]];
    var раскрыт = 0;
    for (var t = 0; t < переходы.length; t++) {
      var a = переходы[t][0], b = переходы[t][1];
      var до = 0.45, после = 0.45, упреждение = 0.15;
      var окно = b + после - (a - до);
      var тау = (((T - (a - до)) % ЦИКЛ) + ЦИКЛ) % ЦИКЛ;
      if (тау <= окно) {
        var вверх = плавно(тау / (до + упреждение));
        var вниз = плавно((тау - (окно - (упреждение + после))) / (упреждение + после));
        раскрыт = Math.max(раскрыт, Math.min(вверх, 1 - вниз));
      }
    }
    var зазор = РАСКРЫТИЕ * раскрыт;
    var оборот = поворот(T);

    // Полурост тела ВДОЛЬ оси инструмента (её и меряют плечи) и полуширина
    // ПОПЕРЁК (на неё отодвигается стойка, чтобы не легла на тело).
    var вдоль = 0, поперёк = 0;
    for (var i = 0; i < ТОЧЕК; i++) {
      var а = УГЛЫ[i] - оборот;
      var в = радиусы[i] * Math.abs(Math.sin(а));
      var ш = радиусы[i] * Math.abs(Math.cos(а));
      if (в > вдоль) вдоль = в;
      if (ш > поперёк) поперёк = ш;
    }
    var h = вдоль + зазор;
    var касание = Math.max(0, 1 - зазор / 14);

    // НАЛИВАНИЕ В БУКВУ, тем же приёмом, что в FIX: два знака одной
    // системы обязаны собираться одинаково.
    var буква = плавно((T - (ЦИКЛ - ДЕРЖИМ_Ф + 0.15)) / 0.85);
    var th = ЗНАК.th + (ЗНАК_Б.th - ЗНАК.th) * буква;
    var стойка = ЗНАК.стойка;

    // Плечо обязано ПЕРЕКРЫТЬ тело, а не заканчиваться на его середине:
    // иначе губка висит сбоку и хват не читается вовсе. Считаем от
    // поперечного размера тела, а к букве уводим к её собственной длине.
    var охват = поперёк + ЗАЗОР_ТЕЛА;
    var плечоРаб = охват * 2 + th + 40;
    var плечо = плечоРаб + (ЗНАК_Б.плечо - плечоРаб) * буква;
    var x0Б = -ЗНАК_Б.плечо / 2;          // у буквы стойка своя

    // Стойка стоит слева от тела и НЕ короче, чем нужно букве: её низ
    // отсчитывается от середины буквы, а не от нижней губки — иначе под
    // перекладиной остаётся обрубок вместо ножки. Та же правка, что уже
    // сделана на пусковом экране.
    var верх = -(h + th);
    var x0 = -охват - th;
    x0 = x0 + (x0Б - x0) * буква;

    ч.стойка.setAttribute("x", x0.toFixed(1));
    ч.стойка.setAttribute("y", верх.toFixed(1));
    ч.стойка.setAttribute("width", th.toFixed(1));
    ч.стойка.setAttribute("height", стойка);
    ч.верхнее.setAttribute("x", x0.toFixed(1));
    ч.верхнее.setAttribute("y", верх.toFixed(1));
    ч.верхнее.setAttribute("width", плечо);
    ч.верхнее.setAttribute("height", th.toFixed(1));
    ч.среднее.setAttribute("x", x0.toFixed(1));
    ч.среднее.setAttribute("y", h.toFixed(1));
    ч.среднее.setAttribute("width", (плечо * 0.8).toFixed(1));
    ч.среднее.setAttribute("height", th.toFixed(1));
    [ч.стойка, ч.верхнее, ч.среднее].forEach(function (n) {
      n.setAttribute("fill-opacity", буква.toFixed(3));
    });

    /* Готовая буква обязана встать ПО СЕРЕДИНЕ рамки. Рамка отцентрована
       по телу, а буква вырастает влево и вниз от него — и в кадре сидела
       углом. Считаем её собственную середину по тем же числам, которыми она
       начерчена, и подводим ровно на неё, по мере наливания. */
    var серX = x0 + плечо / 2, серY = верх + стойка / 2;
    var подводX = -серX * буква, подводY = -серY * буква;

    ч.циркуль.setAttribute("transform",
      "translate(" + подводX.toFixed(1) + "," + подводY.toFixed(1) + ") " +
      "rotate(" + ((оборот * 180) / Math.PI).toFixed(2) + ")");
    ч.тело.setAttribute("points", radiusPts(радиусы));
    ч.тело.setAttribute("opacity", (1 - буква).toFixed(3));
    ч.мелочь.setAttribute("opacity", (1 - буква).toFixed(3));

    // Шкала держится за стойку, слайдер — за среднюю губку: у циркуля
    // ездит именно она.
    for (var к = 0; к < ч.штрихи.length; к++) {
      var yш = верх + 46 + к * 30;
      ч.штрихи[к].setAttribute("x1", (x0 + th).toFixed(1));
      ч.штрихи[к].setAttribute("x2", (x0 + th + (к % 3 === 0 ? 24 : 14)).toFixed(1));
      ч.штрихи[к].setAttribute("y1", yш.toFixed(1));
      ч.штрихи[к].setAttribute("y2", yш.toFixed(1));
      ч.штрихи[к].setAttribute("opacity", yш < верх + стойка - 20 ? "0.7" : "0");
    }
    ч.слайдер.setAttribute("x", (x0 - 11).toFixed(1));
    ч.слайдер.setAttribute("y", (h - 15).toFixed(1));
    ч.слайдер.setAttribute("width", (th + 22).toFixed(1));
    ч.слайдер.setAttribute("height", (th + 30).toFixed(1));

    // Точки касания — там, где губка ДЕЙСТВИТЕЛЬНО трогает тело: по его
    // середине, а не у края плеча.
    ч.точкаВ.setAttribute("cx", "0");
    ч.точкаВ.setAttribute("cy", (-h).toFixed(1));
    ч.точкаН.setAttribute("cx", "0");
    ч.точкаН.setAttribute("cy", h.toFixed(1));
    ч.точкаВ.setAttribute("opacity", ((1 - буква) * касание).toFixed(2));
    ч.точкаН.setAttribute("opacity", ((1 - буква) * касание).toFixed(2));
  }

  function radiusPts(радиусы) {
    var вых = [];
    for (var i = 0; i < ТОЧЕК; i++) {
      вых.push((радиусы[i] * Math.cos(УГЛЫ[i])).toFixed(1) + "," +
               (радиусы[i] * Math.sin(УГЛЫ[i])).toFixed(1));
    }
    return вых.join(" ");
  }

  function циркуль() {
    var svg = узелSVG("svg", {
      // Рамка квадратная и снята замером: при обходе инструмент бывает в
      // каждой стороне, и она обязана вместить его во всех.
      "class": "calip", viewBox: "-400 -400 800 800",
      role: "img", "aria-label": "Обдумываю ответ"
    });
    var корень = узелSVG("g", {});
    svg.appendChild(корень);

    var циркуль = узелSVG("g", { transform: "rotate(0)" });
    корень.appendChild(циркуль);

    var стойка = узелSVG("rect", { "class": "cbeam", x: 0, y: 0, width: 0, height: 0,
                                   rx: 4, "fill-opacity": 0 });
    циркуль.appendChild(стойка);
    // Шкала и слайдер — в своей группе: на выдержке гаснут разом, потому
    // что у буквы их быть не может.
    var мелочь = узелSVG("g", {});
    циркуль.appendChild(мелочь);
    var штрихи = [];
    for (var i = 0; i < 18; i++) {
      var л = узелSVG("line", { "class": "ctick", x1: 0, y1: 0, x2: 0, y2: 0, opacity: 0 });
      штрихи.push(л); мелочь.appendChild(л);
    }
    var слайдер = узелSVG("rect", { "class": "cslide", x: 0, y: 0, width: 0, height: 0, rx: 7 });
    мелочь.appendChild(слайдер);

    var верхнее = узелSVG("rect", { "class": "cjaw", x: 0, y: 0, width: 0, height: 0,
                                    rx: 3, "fill-opacity": 0 });
    var среднее = узелSVG("rect", { "class": "cjaw", x: 0, y: 0, width: 0, height: 0,
                                    rx: 3, "fill-opacity": 0 });
    циркуль.appendChild(верхнее); циркуль.appendChild(среднее);

    // Тело — ВНЕ вращающейся группы: оно неподвижно и опознаётся сразу.
    var тело = узелSVG("polygon", { "class": "cbody", points: "" });
    корень.appendChild(тело);

    var точкаВ = узелSVG("circle", { "class": "cdot", r: 15, cx: 0, cy: 0 });
    var точкаН = узелSVG("circle", { "class": "cdot", r: 15, cx: 0, cy: 0 });
    циркуль.appendChild(точкаВ); циркуль.appendChild(точкаН);

    var ч = { тело: тело, циркуль: циркуль, стойка: стойка, верхнее: верхнее,
              среднее: среднее, слайдер: слайдер, штрихи: штрихи, мелочь: мелочь,
              точкаВ: точкаВ, точкаН: точкаН };

    var тихо = window.matchMedia &&
               window.matchMedia("(prefers-reduced-motion: reduce)").matches;
    if (тихо) { кадрЦиркуля(ч, ЦИКЛ - 0.4); return svg; }   // готовая буква

    var начало = null;
    function шаг(now) {
      // Цикл кончается сам, когда узел ушёл с экрана: вызывающий снимает
      // пузырь как умеет, а мы это замечаем.
      if (!svg.isConnected) return;
      if (начало === null) начало = now;
      кадрЦиркуля(ч, (((now - начало) / 1000) % ЦИКЛ + ЦИКЛ) % ЦИКЛ);
      requestAnimationFrame(шаг);
    }
    кадрЦиркуля(ч, 0);
    requestAnimationFrame(шаг);
    return svg;
  }




  /* ── Пусковой экран: FIX ──────────────────────────────────────────────

     Вторая присланная сцена. Инструмент обмеряет заготовки и складывает из
     них имя: сам циркуль в конце становится буквой F. Место ей — пуск
     оболочки: там восемь запросов подряд, и всё это время экран пуст.
     Смысл совпадает буквально — собирается рабочее место, и на экране
     собирается имя.

     Показывается ТОЛЬКО если пуск затянулся дольше полусекунды. Быстрый
     пуск не должен мигать заставкой: вспышка на двести миллисекунд хуже,
     чем ничего.

     Чего здесь НЕТ и намеренно: строки «ОБМЕР ДЕТАЛИ 2/3» из исходника. В
     сцене она описывает саму анимацию, а на пуске читалась бы как отчёт о
     ходе загрузки — то есть враньём про несуществующий счётчик. Осталась
     одна честная строка о том, что действительно происходит. */

  var ФЦИКЛ = 14.8;
  var ФМЕТКИ = { ставимI: 3, обмер2: 4.3, ставимX1: 6.5, обмер3: 7.8,
                 ставимX2: 9.6, сборка: 10.9, сброс: 13.3 };
  var ДЕТАЛЬ_H = 220, ДЕТАЛЬ_W = 44, ЗАСЕЧКА_W = 100, ЗАСЕЧКА_H = 20;
  var СТАНОК = { x: 900, y: 400 };
  /* Стойка инструмента ФИКСИРОВАНА по длине, а не отсчитывается вниз от
     нижней губки. У героя было второе: высота = разъём + 84, — и среднее
     плечо садилось на 71–76% стойки, а под ним оставался обрубок в 84.
     Буквой F это не читалось: у F перекладина стоит примерно на середине,
     а стойка идёт до низа. Замер по готовой букве в этой же сцене — 45%.

     Заодно так честнее к самому инструменту: у штангенциркуля линейка
     жёсткая, а губка ездит по ней. Растущая вместе с раскрытием стойка —
     это линейка, которая удлиняется, когда разводишь губки.

     560 подобрано под покой (разъём 250): среднее плечо встаёт на 45%,
     ножка под ним — 280. На раскрытых губках плечо уезжает до 66%, но это
     доли секунды перехода. */
  var ИНСТР = { x0: 700, th: 30, плечо: 240, высота: 560 };
  var БУКВА = { x0: 710, верх: 700, th: 44, плечо: 132, просвет: 100, высота: 220 };
  var ГНЁЗДА = [{ x: 910, y: 810, rot: 0, sy: 1, sw: ЗАСЕЧКА_W },
                { x: 1104, y: 810, rot: 26, sy: 0.99, sw: 64 },
                { x: 1104, y: 810, rot: -26, sy: 0.99, sw: 64 }];
  var ОЧЕРЕДЬ = [{ x: 170, y: 250 }, { x: 170, y: 490 }, { x: 170, y: 730 }];

  function зажать(v, a, b) { return v < a ? a : v > b ? b : v; }
  function межд(a, b, t) { return a + (b - a) * t; }
  function осадка(t) { t = зажать(t, 0, 1); return 1 - Math.pow(1 - t, 4); }
  function ход(T, a, b) { return плавно((T - a) / (b - a)); }

  /* Заготовка — двутавр: стойка с засечками сверху и снизу. Ширина засечки
     меняется по ходу: у буквы I она полная, у палочек X — усечённая. */
  function контурДетали(sw) {
    var в = ЗАСЕЧКА_H, п = (sw - ДЕТАЛЬ_W) / 2, h = ДЕТАЛЬ_H / 2;
    return "M" + (-sw / 2) + "," + (-h) + " h" + sw + " v" + в +
           " h" + (-п) + " V" + (h - в) + " h" + п + " v" + в +
           " h" + (-sw) + " v" + (-в) + " h" + п + " V" + (-h + в) + " h" + (-п) + " Z";
  }

  function кадрФикс(ч, T) {
    // Губки: сходятся на обмере, расходятся, когда деталь уносят в гнездо.
    var c0 = ход(T, 1.0, 2.0), o0 = ход(T, ФМЕТКИ.ставимI - 0.4, ФМЕТКИ.ставимI + 0.05);
    var c1 = ход(T, ФМЕТКИ.обмер2 + 0.8, ФМЕТКИ.обмер2 + 1.7),
        o1 = ход(T, ФМЕТКИ.ставимX1 - 0.4, ФМЕТКИ.ставимX1 + 0.05);
    var c2 = ход(T, ФМЕТКИ.обмер3 + 0.7, ФМЕТКИ.обмер3 + 1.5),
        o2 = ход(T, ФМЕТКИ.ставимX2 - 0.4, ФМЕТКИ.ставимX2 + 0.05);
    var раскрыт = зажать(1 - c0 + o0 - c1 + o1 - c2 + o2, 0, 1);
    var касание = зажать(c0 * (1 - o0) + c1 * (1 - o1) + c2 * (1 - o2), 0, 1);
    // m — превращение инструмента в букву и обратно.
    var m = зажать(ход(T, ФМЕТКИ.сборка + 0.25, ФМЕТКИ.сборка + 1.7) -
                   ход(T, ФМЕТКИ.сброс + 0.05, ФМЕТКИ.сброс + 1.15), 0, 1);

    var верхДетали = СТАНОК.y - ДЕТАЛЬ_H / 2;
    var th = межд(ИНСТР.th, БУКВА.th, m);
    var плечо = межд(ИНСТР.плечо, БУКВА.плечо, m);
    var разъём = ДЕТАЛЬ_H + ИНСТР.th + 118 * раскрыт;
    var просвет = межд(разъём, БУКВА.просвет, m);
    var высота = межд(ИНСТР.высота, БУКВА.высота, m);
    var x0 = межд(ИНСТР.x0, БУКВА.x0, m);
    var верх = межд(верхДетали - ИНСТР.th, БУКВА.верх, m);
    var наклон = (1 - m) * 1.6 * Math.sin((T / ФЦИКЛ) * 2 * Math.PI * 2);
    var серед = верх + просвет;

    ч.стойка.setAttribute("x", x0); ч.стойка.setAttribute("y", верх);
    ч.стойка.setAttribute("width", th); ч.стойка.setAttribute("height", высота);
    ч.верхнее.setAttribute("x", x0); ч.верхнее.setAttribute("y", верх);
    ч.верхнее.setAttribute("width", плечо); ч.верхнее.setAttribute("height", th);
    ч.среднее.setAttribute("x", x0); ч.среднее.setAttribute("y", серед);
    ч.среднее.setAttribute("width", плечо * межд(0.82, 0.76, m));
    ч.среднее.setAttribute("height", th);
    [ч.стойка, ч.верхнее, ч.среднее].forEach(function (n) {
      n.setAttribute("fill-opacity", m.toFixed(3));
    });
    ч.буква.setAttribute("transform",
      "rotate(" + наклон.toFixed(2) + " " + x0.toFixed(1) + " " + СТАНОК.y + ")");

    ч.слайдер.setAttribute("opacity", (1 - m).toFixed(3));
    ч.короб.setAttribute("x", x0 - 13); ч.короб.setAttribute("y", серед - 17);
    ч.короб.setAttribute("width", th + 26); ч.короб.setAttribute("height", th + 34);
    for (var i = 0; i < ч.рифли.length; i++) {
      ч.рифли[i].setAttribute("x1", x0 - 6); ч.рифли[i].setAttribute("x2", x0 + th + 6);
      ч.рифли[i].setAttribute("y1", серед + 4 + i * 9);
      ч.рифли[i].setAttribute("y2", серед + 4 + i * 9);
    }

    // Шкала на стойке. Шаг вдвое реже исходного: на заставке в четыреста
    // пикселей сорок штрихов сливаются в штриховку.
    for (var к = 0; к < ч.штрихи.length; к++) {
      var yш = верх + 6 + к * 23.2;
      var виден = (к * 23.2 < высота - 8) && m < 0.98;
      ч.штрихи[к].setAttribute("opacity", виден ? "0.7" : "0");
      ч.штрихи[к].setAttribute("x1", x0); ч.штрихи[к].setAttribute("x2", x0 - (к % 3 === 0 ? 15 : 9));
      ч.штрихи[к].setAttribute("y1", yш); ч.штрихи[к].setAttribute("y2", yш);
    }

    ч.касЛ.setAttribute("opacity", ((1 - m) * касание).toFixed(3));
    ч.касП.setAttribute("opacity", ((1 - m) * касание).toFixed(3));
    ч.касЛ.setAttribute("cx", СТАНОК.x); ч.касЛ.setAttribute("cy", верхДетали);
    ч.касП.setAttribute("cx", СТАНОК.x); ч.касП.setAttribute("cy", верхДетали + ДЕТАЛЬ_H);

    var сроки = [
      { подача: [0.15, 1.0], установка: [ФМЕТКИ.ставимI, ФМЕТКИ.ставимI + 1.15] },
      { подача: [ФМЕТКИ.обмер2, ФМЕТКИ.обмер2 + 0.8], установка: [ФМЕТКИ.ставимX1, ФМЕТКИ.ставимX1 + 1.15] },
      { подача: [ФМЕТКИ.обмер3, ФМЕТКИ.обмер3 + 0.7], установка: [ФМЕТКИ.ставимX2, ФМЕТКИ.ставимX2 + 1.15] }
    ];
    for (var k = 0; k < 3; k++) {
      var p1 = ход(T, сроки[k].подача[0], сроки[k].подача[1]);
      var p2 = ход(T, сроки[k].установка[0], сроки[k].установка[1]);
      var проявка = ход(T, 0.1, 0.5);
      var прочь = ход(T, ФМЕТКИ.сброс + 0.1 + 0.12 * k, ФМЕТКИ.сброс + 0.9 + 0.12 * k);
      var г = ГНЁЗДА[k];
      var x = межд(межд(ОЧЕРЕДЬ[k].x, СТАНОК.x, p1), г.x, p2);
      var дуга = -80 * Math.sin(Math.PI * p2);
      var y = межд(межд(ОЧЕРЕДЬ[k].y, СТАНОК.y, p1), г.y, p2) + дуга - 46 * прочь;
      var пов = межд(межд(90, 0, p1), г.rot, p2);
      var sy = межд(1, г.sy, p2);
      var sw = межд(ЗАСЕЧКА_W, г.sw, p2);
      var плотн = осадка((p2 - 0.28) / 0.55);
      var д = ч.детали[k];
      д.группа.setAttribute("transform", "translate(" + x.toFixed(1) + "," + y.toFixed(1) +
        ") rotate(" + пов.toFixed(1) + ") scale(1," + sy.toFixed(3) + ")");
      д.группа.setAttribute("opacity", (проявка * (1 - прочь)).toFixed(3));
      д.контур.setAttribute("d", контурДетали(sw));
      д.контур.setAttribute("fill-opacity", плотн.toFixed(3));
      д.контур.setAttribute("fill", плотн > 0.02 ? "currentColor" : "none");
    }

    var камера = (1 + 0.02 * Math.sin((T / ФЦИКЛ) * 2 * Math.PI)) * (1 + 0.2 * m);
    var фокус = межд(540, 800, m);
    /* Доводка камеры на сборке. В исходнике кадр 1920 широкий, и собранное
       имя стоит ровно по его середине (x=960). Наша рамка обрезана слева по
       настоящим границам рисунка, её середина — 635, и то же имя оказывалось
       правее и ниже центра: проверено на снимке. Уводим камеру ровно на эту
       разницу и только по мере превращения, поэтому на обмере кадр остаётся
       авторским, а к концу имя встаёт в середину. */
    var сдвигX = -325 * m, сдвигY = -117 * m;
    ч.камера.setAttribute("transform",
      "translate(" + сдвигX.toFixed(1) + "," + сдвигY.toFixed(1) + ") " +
      "translate(960," + фокус.toFixed(1) + ") scale(" + камера.toFixed(4) +
      ") translate(-960," + (-фокус).toFixed(1) + ")");
  }

  function фикс() {
    var svg = узелSVG("svg", { // Рамка снята замером границ по всему циклу (x 60..1210, y 198..1193
      // с учётом наезда камеры на сборке), а не подобрана: первая
      // догадка срезала нижнюю треть вместе с готовым именем.
      "class": "fixan", viewBox: "40 180 1190 1030",
      role: "img", "aria-label": "Собираю рабочее место" });
    var камера = узелSVG("g", {});
    svg.appendChild(камера);

    [[710, 132], [860, 100], [1010, 200]].forEach(function (g) {
      камера.appendChild(узелSVG("line", { "class": "fguide",
        x1: g[0], y1: 932, x2: g[0] + g[1], y2: 932 }));
    });

    var детали = [];
    for (var k = 0; k < 3; k++) {
      var гр = узелSVG("g", {});
      var к = узелSVG("path", { "class": "fbar", d: "" });
      гр.appendChild(к); камера.appendChild(гр);
      детали.push({ группа: гр, контур: к });
    }

    var буква = узелSVG("g", {});
    камера.appendChild(буква);
    var штрихи = [];
    for (var i = 0; i < 22; i++) {
      var л = узелSVG("line", { "class": "ftick", x1: 0, y1: 0, x2: 0, y2: 0, opacity: 0 });
      штрихи.push(л); буква.appendChild(л);
    }
    var стойка = узелSVG("rect", { "class": "fpart", x: 0, y: 0, width: 0, height: 0 });
    var верхнее = узелSVG("rect", { "class": "fpart", x: 0, y: 0, width: 0, height: 0 });
    var среднее = узелSVG("rect", { "class": "fpart", x: 0, y: 0, width: 0, height: 0 });
    буква.appendChild(стойка); буква.appendChild(верхнее); буква.appendChild(среднее);

    var слайдер = узелSVG("g", {});
    var короб = узелSVG("rect", { "class": "fslide", rx: 6, x: 0, y: 0, width: 0, height: 0 });
    слайдер.appendChild(короб);
    var рифли = [];
    for (var r = 0; r < 3; r++) {
      var рл = узелSVG("line", { "class": "ftick", x1: 0, y1: 0, x2: 0, y2: 0 });
      рифли.push(рл); слайдер.appendChild(рл);
    }
    буква.appendChild(слайдер);
    var касЛ = узелSVG("circle", { "class": "fdot", r: 7, cx: 0, cy: 0 });
    var касП = узелSVG("circle", { "class": "fdot", r: 7, cx: 0, cy: 0 });
    буква.appendChild(касЛ); буква.appendChild(касП);

    var ч = { камера: камера, детали: детали, буква: буква, стойка: стойка,
              верхнее: верхнее, среднее: среднее, слайдер: слайдер, короб: короб,
              рифли: рифли, штрихи: штрихи, касЛ: касЛ, касП: касП };

    var тихо = window.matchMedia &&
               window.matchMedia("(prefers-reduced-motion: reduce)").matches;
    if (тихо) { кадрФикс(ч, ФМЕТКИ.сброс - 0.4); return svg; }   // сложенное имя

    var начало = null;
    function шаг(now) {
      if (!svg.isConnected) return;
      if (начало === null) начало = now;
      кадрФикс(ч, ((now - начало) / 1000) % ФЦИКЛ);
      requestAnimationFrame(шаг);
    }
    кадрФикс(ч, 0);
    requestAnimationFrame(шаг);
    return svg;
  }

  /* Заставка пуска. Возвращает функцию «убрать»: вызывающий не обязан знать,
     успела она появиться или пуск обогнал порог. */
  function пусковойЭкран() {
    var узел = null;
    var таймер = setTimeout(function () {
      узел = el("div", "boot");
      var к = el("div", "bootin");
      к.appendChild(фикс());
      к.appendChild(el("div", "bootsay", "Собираю рабочее место"));
      узел.appendChild(к);
      document.body.appendChild(узел);
      // Кадр на включение прозрачности: без него переход не наступает,
      // потому что узел добавлен и покрашен в одном и том же кадре.
      requestAnimationFrame(function () { if (узел) узел.classList.add("on"); });
    }, 600);
    return function убрать() {
      clearTimeout(таймер);
      if (!узел) return;
      var у = узел; узел = null;
      у.classList.remove("on");
      // Ждём затухание, но не полагаемся на событие: если переход не
      // наступил (reduced-motion, фон вкладки), заставка обязана уйти всё
      // равно — иначе она останется поверх рабочего экрана навсегда.
      setTimeout(function () { if (у.parentNode) у.remove(); }, 420);
    };
  }

  /* Пузырь ожидания. Возвращает тот же узел, что и say(), — вызывающие
     снимают его привычным thinking.parentNode.remove(). */
  function думает() {
    var b = bubble("bot", "Ф");
    b.className = "bubble think";
    b.appendChild(циркуль());
    log.scrollTop = log.scrollHeight;
    return b;
  }

  //: Сказали ли уже, что занято. Иначе каждое нажатие класть в ленту по
  //: коробу: человек, который жмёт трижды, получит три одинаковых упрёка.
  var сказалиПроЗанятость = false;

  function busy(on) {
    state.busy = on;
    if (!on) сказалиПроЗанятость = false;
    sendBtn.disabled = on;
    input.disabled = on;
    sendBtn.textContent = T(on ? "…" : "Отправить");
    // busy(false) и означает «ход закончился». Ход мог стоить кредитов, и
    // остаток на экране обязан это отразить — иначе число врёт до следующей
    // перезагрузки. Одна точка вместо пяти: ходы кончаются в разных местах
    // (общий разговор, дело, выбранный путь, подтверждение предложения), а
    // здесь они сходятся все.
    if (!on) refreshCredits();
  }

  /* Необязательный предел ожидания. Нужен там, где контракт предписывает
     повтор тем же идентификатором: без предела вкладка ждёт вечно, и человек
     не узнает, что повторять уже можно. Для загрузки файлов предел не ставим —
     шестьдесят мегабайт едут дольше любого разумного числа. */
  /* ВХОД МОГ КОНЧИТЬСЯ, ПОКА ВКЛАДКА БЫЛА ОТКРЫТА.

     Токен лежит в localStorage, общем на браузер, а `state.token` — копия в
     памяти вкладки. Стоит человеку войти почтой или телефоном в СОСЕДНЕЙ
     вкладке, как служба входа гасит прежнего субъекта и переносит его дела на
     нового. Соседняя вкладка про это не знает и продолжает слать старую
     строку — каждый её запрос упирается в 401 «токен неизвестен».

     Прежде обработчика 401 не было ВООБЩЕ (грепом — ноль совпадений). Поэтому
     человек видел не «вы вышли», а россыпь разных отказов на каждое действие:
     список дел не пришёл, кредиты не прочитались, отправка не отправилась, — и
     решал, что сломался сервис. Хуже не бывает: беда была понятной и
     поправимой, а выглядела как авария.

     ЧТО ДЕЛАЕМ. Перечитываем токен из хранилища. Если там ДРУГОЙ — рядом
     вошли, и это тот же человек: подхватываем и перерисовываем шапку. Если тот
     же — вход действительно кончился, и об этом говорим ОДИН раз, а не на
     каждый запрос.

     ПОВТОРЯЕМ ТОЛЬКО ЧТЕНИЕ. GET безобиден. Для остального повтор мог бы
     удвоить сделанное: шлюз отвечает 401 из своей проверки, ДО обращения к
     службе (public_gateway/app.py:1466 и 1469), но 401 от самой службы он
     пропускает насквозь (app.py:83) — то есть отличить «ничего не произошло»
     от «произошло и отказано» здесь нечем. Поэтому запись не повторяем, а
     говорим словами: повторите последнее действие. */
  var входПропал = false;

  var КЛЮЧИ_СЕССИИ = [KEY, "fixar.start.token", "aios_token"];
  var КЛЮЧ_РОТАЦИИ = "fixar.session.rotation";

  function новыйСессионныйТокен() {
    if (typeof crypto === "undefined" || !crypto.getRandomValues) return "";
    var bytes = new Uint8Array(32);
    crypto.getRandomValues(bytes);
    var token = "";
    for (var i = 0; i < bytes.length; i++) token += bytes[i].toString(16).padStart(2, "0");
    return token;
  }

  function ожидающаяРотация(старый) {
    try {
      var row = JSON.parse(localStorage.getItem(КЛЮЧ_РОТАЦИИ) || "null");
      return row && row.old === старый && row.replacement ? row : null;
    } catch (e) { return null; }
  }

  function сохранитьРотацию(row) {
    try { localStorage.setItem(КЛЮЧ_РОТАЦИИ, JSON.stringify(row)); }
    catch (e) { /* без записи не начинаем замену анонимного ключа */ }
    return ожидающаяРотация(row.old);
  }

  function закончитьРотацию(старый, новый) {
    заменитьСессию(старый, новый);
    try {
      var row = ожидающаяРотация(старый);
      if (row && row.replacement === новый) localStorage.removeItem(КЛЮЧ_РОТАЦИИ);
    } catch (e) { /* новый токен уже в памяти */ }
  }

  function заменитьСессию(старый, новый) {
    КЛЮЧИ_СЕССИИ.forEach(function (ключ) {
      try {
        if (localStorage.getItem(ключ) === старый) localStorage.setItem(ключ, новый);
      } catch (e) { /* приватный режим: держим новый токен в памяти */ }
    });
    if (state.token === старый) state.token = новый;
  }

  async function спроситьСессию(токен) {
    var r = await fetch(API + "/entry/whoami", {
      headers: { "Authorization": "Bearer " + токен }
    });
    if (!r.ok) return null;
    var who = await r.json();
    return who && who.principal_id ? who : null;
  }

  async function прочитатьСессию(токен, ожидаемыйСубъект) {
    if (!токен) return null;
    var pending = ожидающаяРотация(токен);
    if (pending) {
      var recovered = await спроситьСессию(pending.replacement);
      if (recovered && recovered.principal_id === pending.principal_id) {
        закончитьРотацию(токен, pending.replacement);
        recovered.session_token = pending.replacement;
        return recovered;
      }
    }

    var who = await спроситьСессию(токен);
    if (!who) return null;
    if (ожидаемыйСубъект && who.principal_id !== ожидаемыйСубъект) return null;

    if (who.session_rotation_required) {
      pending = pending || сохранитьРотацию({
        old: токен,
        replacement: новыйСессионныйТокен(),
        principal_id: who.principal_id
      });
      if (!pending || !pending.replacement) {
        who.session_token = токен;
        return who;
      }
      var rr = null;
      try {
        rr = await fetch(API + "/entry/session/rotate", {
          method: "POST",
          headers: {
            "Authorization": "Bearer " + токен,
            "Content-Type": "application/json"
          },
          body: JSON.stringify({replacement_token: pending.replacement})
        });
      } catch (e) { /* ниже проверим известный клиенту новый токен */ }
      if (rr && rr.ok) {
        var rotated = await rr.json();
        закончитьРотацию(токен, pending.replacement);
        токен = pending.replacement;
        who.session_rotation_required = false;
        who.session_version = rotated.session_version;
      } else {
        var completed = await спроситьСессию(pending.replacement);
        if (completed && completed.principal_id === who.principal_id) {
          закончитьРотацию(токен, pending.replacement);
          completed.session_token = pending.replacement;
          return completed;
        }
      }
      if (rr && rr.status === 404) {
        /* Другая вкладка могла успеть первой. Берём только новое значение
           НАШЕГО ключа; чужой аккаунт из соседнего ключа не подхватываем. */
        var сосед = null;
        try { сосед = localStorage.getItem(KEY); } catch (e) { return null; }
        if (!сосед || сосед === токен) return null;
        return прочитатьСессию(сосед, who.principal_id);
      }
      if (rr && rr.status === 409) {
        try { localStorage.removeItem(КЛЮЧ_РОТАЦИИ); } catch (e) { /* повтор позже */ }
      }
    }
    who.session_token = токен;
    return who;
  }

  async function подхватитьТокен() {
    var лежит = null;
    try { лежит = localStorage.getItem(KEY); } catch (e) { return false; }
    if (!лежит || лежит === state.token) return false;
    // Спрашиваем ДО того, как заменить свой токен: мёртвая строка в хранилище
    // бывает тоже, и менять рабочий вход на неё нельзя.
    var who = null;
    try { who = await прочитатьСессию(лежит); } catch (e) { return false; }
    if (!who || !who.principal_id) return false;
    state.token = who.session_token || лежит;
    // refreshWho перечитает уровень входа, перерисует шапку и панель входа:
    // иначе вверху осталось бы прежнее имя, а это прямая ложь о том, кто ты.
    await refreshWho();
    входПропал = false;
    return true;
  }

  function сказатьПроВход(подхватили) {
    if (подхватили) {
      say("bot", "Ф", "Вход в этой вкладке обновился: рядом вошли в аккаунт. " +
          "Дела читаются уже от нового входа — повторите последнее действие, " +
          "оно не выполнено.");
      return;
    }
    // Один раз. Иначе вернётся та же россыпь, только одинаковыми словами.
    if (входПропал) return;
    входПропал = true;
    say("bot", "Ф", "Этот вход больше не действует — похоже, в другой вкладке " +
        "вышли или вошли заново. Обновите страницу: она подхватит текущий " +
        "вход. Ничего не потеряно, дела на месте.");
  }

  async function api(method, path, body, ms, повтор) {
    var opts = { method: method, headers: { "Content-Type": "application/json" } };
    if (state.token) opts.headers["Authorization"] = "Bearer " + state.token;
    if (body !== undefined) opts.body = JSON.stringify(body);
    var ctl = null, timer = null;
    if (ms && window.AbortController) {
      ctl = new AbortController();
      opts.signal = ctl.signal;
      timer = setTimeout(function () { ctl.abort(); }, ms);
    }
    var r;
    try {
      r = await HTTP.fetchApi(path, opts);
    } catch (e) {
      // Оборванная связь и наш собственный предел для fetch неотличимы, и
      // решение по ним одно: сообщение могло дойти, поэтому повторять его
      // нужно тем же идентификатором, а не отправлять заново как новое.
      var te = new Error(ctl && ctl.signal.aborted
        ? "ответ не пришёл за отведённое время"
        : "связь оборвалась");
      te.timeout = true;
      запомнитьОтказ(path, 0, te.message);   // в кольцо для жалобы
      throw te;
    } finally {
      if (timer) clearTimeout(timer);
    }
    var text = await r.text();
    var data;
    try { data = text ? JSON.parse(text) : {}; } catch (e) { data = { detail: text }; }
    if (r.status === 401 && !повтор) {
      var подхватили = await подхватитьТокен();
      // Чтение повторяем сами: человеку незачем знать, что мы перечитали
      // токен, если после этого всё получилось.
      if (подхватили && method === "GET") return api(method, path, body, ms, true);
      сказатьПроВход(подхватили);
    }
    if (!r.ok) {
      // Тоже в кольцо, и ДО разбора причины: код и путь нужны в жалобе даже
      // тогда, когда тело отказа непонятно нам самим.
      запомнитьОтказ(path, r.status,
        (data && data.detail && data.detail.reason) || "");
      var err = new Error(data.detail || ("HTTP " + r.status));
      // Тело отказа нужно целиком, а не одной строкой: у 403 важно, чужое ли
      // это дело, а у 429 — через сколько можно повторить. Без этого «не
      // получилось» становится единственным, что мы умеем сказать.
      err.status = r.status;
      err.data = data;
      // СРОК БЕРЁМ И ИЗ ЗАГОЛОВКА. `Retry-After` — то место, где про срок
      // говорят по правилам HTTP, и model-service отвечает именно им: 5 с на
      // переполненную очередь, 10 с на исчерпанную квоту, НИЧЕГО на похожую
      // петлю (там повторять нечего, и выдумывать срок нельзя).
      //
      // Тело же несёт `retry_after` только у двери. Без этой склейки человек
      // на отказ модели читал бы «сделайте паузу» вместо «подождите 10 с» —
      // служба срок назвала, а мы его теряли по дороге.
      if (r.status === 429 && err.data && !err.data.retry_after) {
        var изЗаголовка = parseInt(r.headers.get("Retry-After") || 0, 10);
        if (изЗаголовка > 0) err.data.retry_after = изЗаголовка;
      }
      throw err;
    }
    return data;
  }

  /* Причина отказа словами. В detail приходит то строка, то предмет (у 429
     там ещё и через сколько повторять), а Error(предмет) превращается в
     «[object Object]» — и человек читает заглушку вместо причины. */
  /* Отказ двери «файлы после подтверждения» — особый: он не про поломку и не
     про права на этот файл, а про то, что человек ещё никто. Поэтому и текст
     другой, и рядом путь: панель учётной записи, где сказано, чем подтвердить.

     Запрет стоит НА СЕРВЕРЕ (public_gateway, min_assurance у маршрута).
     Спрятать здесь кнопку было бы не запретом, а видимостью: ручка осталась бы
     открытой всякому, кто знает её адрес. */
  function нуженВход(e) {
    var d = (e && e.data) ? e.data.detail : null;
    return !!(d && typeof d === "object" && d.reason === "assurance_required");
  }

  function позватьПодтвердиться(куда) {
    var кнопка = document.getElementById("me");
    if (куда) {
      куда.textContent = T("Файлы — после подтверждения входа. " +
        "Нажмите своё имя вверху: подтвердить можно Telegram или СМС.");
    }
    if (кнопка && !кнопка.hidden) kнопкаМигнёт(кнопка);
  }

  function kнопкаМигнёт(кнопка) {
    kнопкаМигнёт.таймер && clearTimeout(kнопкаМигнёт.таймер);
    кнопка.setAttribute("data-nudge", "1");
    kнопкаМигнёт.таймер = setTimeout(function () {
      кнопка.removeAttribute("data-nudge");
    }, 2600);
  }

  /* ПОЛОМКА — НЕ ОТКАЗ, И СЛОВА У НЕЁ ЧУЖИЕ.

     Жалоба rep_a719601b8cd54697 от 01.09.2026 — «странные сообщения которые
     не должен видеть пользователь». Разобрано: на 5xx в `detail` приходит
     строка, написанная службой ДЛЯ СЛУЖБЫ, и уезжала она человеку дословно.
     Предел жанра — «внутренний service credential не настроен»
     (`shared/internal_auth.py`): английская ругань посреди разговора, да ещё
     произнесённая от лица агента и прочитанная вслух.

     ЧИНИТЬ НАДО ЗДЕСЬ. `reason` зовут восемьдесят семь раз, и двадцать четыре
     из них печатают её как реплику агента. Правка в месте вызова закрыла бы
     один путь из двадцати четырёх и разошлась бы с остальными.

     ЧТО ПРОПУСКАЕМ НА 5xx: только `detail.message` — поле, которое служба
     ЗАВЕЛА ДЛЯ ЧЕЛОВЕКА. Так отвечает model-service («модель занята»,
     «не настроена»), и сторож на это поле стоит с 18.08
     (`test_failure_naming`). Голая строка и код причины — не для человека:
     их место в кольце отказов, откуда они уедут в жалобу, и в консоли.

     СПИСОК В `detail` — ЭТО FastAPI, А НЕ СЛУЖБА: на 422 он кладёт туда
     разбор полей (`[{loc, msg, type}]`), и `JSON.stringify` вываливал его
     человеку целиком. То же странное сообщение, только на другом коде.

     Код в скобках оставляем НАМЕРЕННО: он ничего не рассказывает о нашем
     устройстве, зато человек называет его в жалобе, и по нему видно, одна это
     беда или разные. */
  /* ОДНОЙ ФУНКЦИЕЙ, БЕЗ ПОМОЩНИКОВ РЯДОМ, и это требование проверок, а не
     вкус. Наборы вроде `test_ops_panels_ask_once` выдирают функции из app.js
     ПО ИМЕНИ и гонят в голом node. Вынесенный помощник в чужую вырезку не
     попадает — и `reason` падает там `ReferenceError`, роняя пять проверок
     разом, в файле, который к отказам отношения не имеет. Проверено: именно
     так и вышло 02.09.2026. */
  function reason(e) {
    var d = (e && e.data) ? e.data.detail : null;
    var код = (e && e.status) || 0;
    var человеку = "";
    var внутрь = null;   // сырое: оператору нужно, человеку — нет

    if (код >= 500) {
      if (d && typeof d === "object" && !Array.isArray(d) && d.message) {
        человеку = String(d.message);
      } else {
        внутрь = d;
        человеку = T("служба не ответила") + " (" + код + ")";
      }
    } else if (Array.isArray(d)) {
      внутрь = d;
      человеку = T("запрос не принят — мы составили его неверно");
    } else if (d && typeof d === "object") {
      человеку = d.message || d.reason || "";
      if (!человеку) { внутрь = d; человеку = T("причина не названа"); }
    } else {
      человеку = (e && e.message) || "причина не названа";
    }

    if (внутрь !== null) {
      // Сырое НЕ ПРОПАДАЕТ. Кольцо отказов уже приняло путь и код — они уедут
      // в жалобу; сюда кладём тело, чтобы разбирать поломку было по чему.
      try {
        if (typeof console !== "undefined" && console.warn) {
          console.warn("[отказ] " + код + ":",
                       typeof внутрь === "string"
                         ? внутрь : JSON.stringify(внутрь || {}));
        }
      } catch (пусть) { /* консоли может не быть — молчим */ }
    }
    return человеку;
  }

  /* Размер по-человечески. Предел хранилища человек видит теми же словами,
     что и размер своего файла, — иначе сравнить их нельзя. */
  /* Срок ожидания словами. «Подождите 95 с» требует от человека счёта в уме
     ровно в тот момент, когда он раздражён отказом. */
  function сколько(сек) {
    // ВВЕРХ, а не к ближайшему. Округлив 89 с до «1 мин», мы советуем
    // вернуться раньше срока — человек послушается и получит отказ снова,
    // теперь уже по нашей вине.
    сек = Math.max(1, Math.ceil(Number(сек) || 0));
    if (сек < 60) return сек + T(" с");
    var м = Math.ceil(сек / 60);
    if (м < 60) return м + T(" мин");
    return Math.ceil(м / 60) + " ч";
  }

  function human(n) {
    if (n < 1024) return n + T(" Б");
    if (n < 1048576) return (n / 1024).toFixed(n < 10240 ? 1 : 0) + T(" КБ");
    return (n / 1048576).toFixed(1) + T(" МБ");
  }

  /* Когда это было. Точное время в списке дел не нужно и мешает: важно
     «сегодня или в прошлом месяце». Даты приходят от службы в ISO. */
  function when(iso) {
    var t = Date.parse(iso || "");
    if (!t) return "";
    var d = Math.floor((Date.now() - t) / 1000);
    if (d < 0) d = 0;
    if (d < 90) return "только что";
    if (d < 3600) return Math.floor(d / 60) + T(" мин назад");
    if (d < 86400) return Math.floor(d / 3600) + T(" ч назад");
    if (d < 604800) return Math.floor(d / 86400) + T(" дн назад");
    return new Date(t).toLocaleDateString("ru-RU");
  }

  /* ── Дело справа ──────────────────────────────────────────────────── */

  var fieldsEl = null;
  function field(name, value, sub) {
    if (!fieldsEl) {
      caseBody.innerHTML = "";
      fieldsEl = el("dl", "fields");
      caseBody.appendChild(fieldsEl);
      отметкаДела(true);
      casePane.classList.add("live");
    }
    var row = el("div");
    row.appendChild(el("dt", null, name));
    var dd = el("dd", null, value);
    if (sub) {
      dd.appendChild(document.createElement("br"));
      dd.appendChild(el("span", "sub", sub));
    }
    row.appendChild(dd);
    fieldsEl.appendChild(row);
    return row;
  }

  /* Панель дела без дела. Раньше строчка «Дело появится, как только вы
     начнёте» оставалась на экране и тогда, когда дело уже шло: её никто не
     переписывал, потому что состояний было одно. Теперь их два, и оба
     называются вслух. */
  function showEmpty(text) {
    fieldsEl = null;
    caseBody.innerHTML = "";
    caseBody.appendChild(el("div", "empty", text));
    отметкаДела(false);
    casePane.classList.remove("live");
    document.getElementById("crew").hidden = true;
    document.getElementById("files").hidden = true;
  }

  /* ── Вход ─────────────────────────────────────────────────────────── */

  async function ensureSession() {
    var saved = null;
    try { saved = localStorage.getItem(KEY); } catch (e) { /* приватный режим */ }
    if (saved) {
      try {
        var who = await прочитатьСессию(saved);
        if (who.principal_id) {
          state.token = who.session_token || saved;
          state.principal = who.principal_id;
          // Уровень входа берём ЗДЕСЬ ЖЕ, из того же ответа. Прежде он
          // ставился только в refreshWho, а тот зовётся после входа кнопкой —
          // и вернувшийся назавтра человек оставался с assurance undefined.
          // Видно это было не отказом, а пустотой: кабинет практики прячется
          // при уровне ниже второго, и весь раздел просто не появлялся. То
          // есть кабинет работал ровно один раз — в ту сессию, где входили.
          state.assurance = who.assurance || 0;
          return who;
        }
      } catch (e) { /* токен протух — заведём новый */ }
    }
    var me = await api("POST", "/entry/anon", { label: "web" });
    state.token = me.token;
    state.principal = me.principal_id;
    state.assurance = me.assurance || 0;
    try { localStorage.setItem(KEY, me.token); } catch (e) { /* пусть будет на сессию */ }
    return me;
  }

  /* ── Вход: кнопки строятся из того, что настроено ─────────────────── */

  /* Показать кнопку поставщика, ключей которого нет в окружении, — значит
     обещать вход, который ответит 503. Поэтому список приходит от службы, а
     не лежит в разметке: /auth/providers знает, что настроено на самом деле. */

  var BRAND = {
    google: { letter: "G", cls: "g", title: "Google" },
    yandex: { letter: "Я", cls: "y", title: "Яндекс" },
    vk:     { letter: "V", cls: "vk", title: "VK ID" },
    sber:   { letter: "С", cls: "s", title: "Сбер ID" },
    tbank:  { letter: "Т", cls: "t", title: "Т-Банк" },
    // НЕ поставщик OAuth, и кнопки входа отсюда не берётся: `setupSignin`
    // рисует только то, что назвал `cfg.oauth`, а телеграма там нет и не
    // будет. Название нужно двум другим местам — списку входов и шапке, —
    // где канал иначе показывался человеку сырым словом «tg».
    tg:     { letter: "T", cls: "tg", title: "Телеграм" }
  };

  /* Кто вошёл — в шапке. Имя и то, ЧЕМ вошёл: два входа — это потенциально
     два разных аккаунта с разными делами, и человек должен видеть, в котором
     он сейчас, а не гадать, куда делись его дела. */
  /* ── Насколько твёрдо подтверждён вход, и чем это поднять ───────────

     Уровень доверия решает, дадут ли человеку агента, который работает с ЕГО
     бумагами: такие объявлены с min_assurance 2, и анониму отвечают отказом.
     Отказ этот приходил без объяснения — что именно подтвердить и как, нигде
     не было сказано. Отсюда панель.

     ГОВОРИТ ТОЛЬКО ПРО ТО, ЧТО СИСТЕМА УМЕЕТ. Паспорта и ОГРН у нас нет —
     ни ручки, ни таблицы, — и рисовать их пунктами меню значит обещать
     проверку, которой не существует. Названы они здесь потому, что спросить
     про них естественно, и молчание прочиталось бы как «скоро будет». */

  var ДОВЕРИЕ = {
    0: ["вы анонимно", "устройство запомнено, личность не подтверждена"],
    1: ["учётная запись привязана", "но ни телефон, ни почта не подтверждены"],
    2: ["подтверждён", "этого хватает агентам, работающим с вашими бумагами"],
    3: ["подтверждён твёрдо", "passkey или корпоративный вход"]
  };

  function closeMePanel(вернутьФокус) {
    var b = document.getElementById("me");
    var p = document.getElementById("mepanel");
    if (p) p.hidden = true;
    if (b) b.setAttribute("aria-expanded", "false");
    if (вернутьФокус && b) b.focus();
  }

  function addMePanelClose(панель) {
    var закрыть = document.createElement("button");
    закрыть.type = "button";
    закрыть.className = "meclose";
    закрыть.textContent = "×";
    закрыть.setAttribute("aria-label", T("Закрыть"));
    закрыть.addEventListener("click", function (e) {
      e.stopPropagation();
      closeMePanel(true);
    });
    панель.appendChild(закрыть);
  }

  async function renderMePanel() {
    var панель = document.getElementById("mepanel");
    if (!панель) return;
    панель.innerHTML = "";
    addMePanelClose(панель);

    var входы = [];
    var беда = "";
    try {
      входы = (await api("POST", "/entry/logins", {})).входы || [];
    } catch (e) {
      беда = reason(e);
    }
    var есть = {};
    входы.forEach(function (v) { есть[v.канал] = v; });
    // Уровень — наибольший из подтверждённых каналов. Пусто и отказ службы —
    // РАЗНОЕ: во втором случае мы просто не знаем и так и говорим.
    var уровень = null;
    if (!беда) {
      уровень = 0;
      входы.forEach(function (v) {
        if (typeof v.доверие === "number" && v.доверие > уровень) уровень = v.доверие;
      });
    }

    var слова = ДОВЕРИЕ[уровень] || ["не знаю", ""];
    панель.appendChild(el("h4", "", беда
      ? "Уровень доверия сейчас не выяснить"
      : T("Доверие ") + уровень + " — " + слова[0]));
    панель.appendChild(el("div", "sub", беда
      ? беда + T(". Это не значит, что подтверждения нет, — значит, служба не ответила.")
      : слова[1]));

    /* ── Кто вы для площадки ───────────────────────────────────────────
       ВТОРАЯ ОСЬ, И НАЗВАНА ОНА ИНАЧЕ НАМЕРЕННО.

       Выше в этой же панели написано «Доверие 2» — и это уровень КАНАЛА
       ВХОДА: насколько твёрдо подтверждено, что вход ваш. Здесь другое: кто
       вы. Человек с ключом безопасности имеет уровень 3 и остаётся полностью
       неизвестным; человек с проверенным паспортом может входить по одной
       почте. Назвать оба «доверием» значило бы склеить их в голове читателя
       ровно так, как мы отказались склеивать в коде.

       Блока нет вовсе, пока службе нечего сказать: пустая строка «репутация:
       —» читается как «у вас её отняли», а на деле её просто ещё нет. */
    var д = (state.trust && typeof state.trust.score === "number") ? state.trust : null;
    if (д) {
      панель.appendChild(el("h4", "", "Кто вы для площадки"));
      var подпись = д.label;
      if (д.reviews) {
        подпись += " · " + д.stars + T(" из 5 по ") + д.reviews + " " +
          plural(д.reviews, "отзыву", "отзывам", "отзывам");
      }
      if (д.endorsements) {
        подпись += T(" · за вас ручаются: ") + д.endorsements;
      }
      панель.appendChild(el("div", "sub", подпись));
      var проверено = д.verified || [];
      способ("Личность", проверено.indexOf("identity") >= 0
        ? "проверена" : "не проверена", null, null);
      способ("Организация", проверено.indexOf("legal") >= 0
        ? "проверена" : "не проверена", null, null);
      панель.appendChild(el("h4", "", "Входы"));
    }

    function способ(имя, примечание, кнопка, действие) {
      var row = el("div", "way");
      row.appendChild(el("span", "wn", имя));
      if (кнопка) {
        var b = el("button", "addone", кнопка);
        b.type = "button";
        b.addEventListener("click", действие);
        row.appendChild(b);
      } else {
        row.appendChild(el("span", "wnote", примечание));
      }
      панель.appendChild(row);
    }

    ["google", "yandex", "vk"].forEach(function (p) {
      var имя = (BRAND[p] || {}).title || p;
      if (есть[p]) способ(имя, "подтверждён", null, null);
      else способ(имя, "", "Привязать", function () { goLink(p); });
    });

    // Телефон привязать к нынешней записи система не умеет: привязка второго
    // входа сделана только для OAuth (Google, Яндекс, VK ID), а
    // /auth/phone/verify связывает номер с той сессией, что запросила код.
    // Кнопка «Привязать телефон» звала бы ручку, которой нет.
    if (есть.phone) способ("Телефон", "подтверждён", null, null);
    else способ("Телефон", "только как отдельный вход", null, null);

    /* Телеграм. Ручки привязки жили в службе с самого канала, а кнопки к ним
       не было — и это ровно то, чем человек разложился на четырёх субъектов:
       вход ботом заводил своего, вход Google своего, и склеить их с сайта
       было нечем. Вход Телеграмом без этой строки только добавил бы четвёртую
       дверь к четвёртой записи. */
    if (есть.tg) способ("Телеграм", "подтверждён", null, null);
    else способ("Телеграм", "", "Привязать", function () { linkTelegram(панель); });

    var не = el("div", "cant");
    не.innerHTML = "";
    не.appendChild(el("b", "", "Чего мы пока не умеем."));
    не.appendChild(document.createTextNode(
      " Паспорт не проверяем: такой ручки в системе нет вовсе — «паспорт» " +
      "сейчас встречается только как то, что ЗАТИРАЕТСЯ в текстах перед " +
      "отправкой модели. ОГРН тоже не проверяем, и это не просто пробел: " +
      "уровень профессионала — другая ось. Он приходит с площадки-партнёра и " +
      "намеренно не превращается в доверие к личности, потому что говорит про " +
      "юрлицо, а не про человека."));
    if (!есть.phone) {
      не.appendChild(document.createTextNode(
        " Номер к этой записи тоже не привяжешь: привязка второго входа " +
        "сделана для Google, Яндекса и VK ID, а вход по телефону заводит свою запись."));
    }
    панель.appendChild(не);
  }

  function showMe(who) {
    // Доверие запоминается ЗДЕСЬ, потому что сюда сходятся оба пути: и пуск
    // оболочки, и обновление после входа. Разложи мы это по двум местам —
    // одно однажды забудут, и панель начнёт показывать вчерашнее.
    state.trust = (who && who.trust) || null;
    var box = document.getElementById("me");
    if (!who || !who.signed_in) {
      box.hidden = true;
      closeMePanel();
      return;
    }
    box.hidden = false;
    box.innerHTML = "";
    // Имени может не быть: Яндекс отдаёт его не всегда, и выдумывать «Пользователь»
    // за человека мы не будем — тогда показываем, чем он вошёл.
    var name = (who.display_name || "").trim();
    box.appendChild(el("span", "nm", name || "вы вошли"));
    var via = (who.providers || []).map(function (p) {
      return (BRAND[p] || {}).title || p;
    }).join(" + ");
    if (via) box.appendChild(el("span", "via", via));

    if (!box.dataset.panelWired) {
      box.dataset.panelWired = "1";
      box.addEventListener("click", async function (e) {
        e.stopPropagation();
        var панель = document.getElementById("mepanel");
        if (!панель.hidden) { closeMePanel(); return; }
        панель.hidden = false;
        box.setAttribute("aria-expanded", "true");
        панель.textContent = "";
        addMePanelClose(панель);
        панель.appendChild(el("div", "sub", T("смотрю…")));
        await renderMePanel();
        // ВХОДЫ И ВЫХОД — В ТОЙ ЖЕ ПАНЕЛИ, вторым заходом. Раздельно, потому
        // что это две разные ручки: `renderMePanel` спрашивает доверие и
        // роль, `renderLogins` — каналы входа. Свалить их в один вызов
        // значило бы, что отказ одной ручки гасит и вторую.
        await renderLogins();
      });
      // Щелчок мимо закрывает: панель перекрывает разговор, и оставлять её
      // висеть значит отнимать место у того, ради чего сюда пришли.
      document.addEventListener("click", function (e) {
        var панель = document.getElementById("mepanel");
        if (!панель || панель.hidden) return;
        if (!панель.contains(e.target) && e.target !== box) closeMePanel();
      });
      document.addEventListener("keydown", function (e) {
        if (e.key === "Escape") {
          e.preventDefault();
          closeMePanel(true);
        }
      });
    }
  }

  /* ── Когда совет уместен, а когда это шум ─────────────────────────── */

  /* Совет привязать второй вход правдив всегда, а нужен — редко. Висящий
     постоянно, он перестаёт читаться, и вместе с ним перестают читаться
     соседние строки, где написано важное. Поэтому три условия сразу:

       — есть что терять: хотя бы одно дело. Пустому аккаунту второй вход не
         нужен, терять нечего;
       — привязан ровно один поставщик: при двух совет исполнен;
       — не отказывались недавно. «Не сейчас» — это ответ, а не отсрочка до
         следующей перезагрузки.

     Отказ помнится месяц. Меньше — человек увидит то же самое на неделе и
     решит, что его не слышат. */

  var NAG_KEY = "fixar.nag.link";
  var NAG_QUIET_DAYS = 30;

  function shouldNag(who) {
    if (((who && who.providers) || []).length !== 1) return false;
    if (!state.caseCount) return false;
    try {
      var until = parseInt(localStorage.getItem(NAG_KEY) || "0", 10);
      // Дата берётся у браузера: сервер про «когда мне надоело» знать не
      // должен, это не сведения о человеке, а настройка его экрана.
      if (until && Date.now() < until) return false;
    } catch (e) { /* приватный режим — показываем */ }
    return true;
  }

  function nagLater() {
    try {
      localStorage.setItem(NAG_KEY,
        String(Date.now() + NAG_QUIET_DAYS * 864e5));
    } catch (e) { /* не запомнили — покажем ещё раз, это не потеря */ }
    document.getElementById("signin").hidden = true;
  }

  /* Вход рисуется по двум вещам сразу: что настроено на сервере и вошёл ли
     человек уже. Показывать «Войти» тому, кто вошёл, — предлагать сделать
     то, что уже сделано; он решит, что вход не сработал. */
  async function setupSignin(who) {
    var box = document.getElementById("signin");
    var oauths = document.getElementById("oauths");
    var note = document.getElementById("signnote");
    var mail = document.getElementById("bymail");
    var phone = document.getElementById("byphone");
    var tg = document.getElementById("bytg");
    var head = box.querySelector("h3");
    var why = box.querySelector(".signwhy");
    var cfg;
    try {
      cfg = await api("GET", "/auth/providers");
    } catch (e) {
      // Не рисуем вход, которого не понимаем: неработающая кнопка входа
      // отпугивает сильнее, чем её отсутствие.
      box.hidden = true;
      return;
    }

    var ready = Object.keys(cfg.oauth || {}).filter(function (k) {
      return cfg.oauth[k] && BRAND[k];
    });
    var signed = !!(who && who.signed_in);
    var have = (who && who.providers) || [];
    // Вошедшему предлагаем только то, чего у него ещё нет: кнопка «войти
    // Яндексом» тому, кто вошёл Яндексом, ничего не делает и только путает.
    var offer = signed ? ready.filter(function (k) {
      return have.indexOf(k) < 0;
    }) : ready;

    oauths.innerHTML = "";
    mail.hidden = true;
    phone.hidden = true;
    if (tg) tg.hidden = true;
    note.hidden = true;

    if (signed) {
      if (!offer.length || !shouldNag(who)) {
        // Либо привязывать нечего, либо сейчас не время. Совет, висящий
        // постоянно, перестают читать — и вместе с ним перестают читать
        // соседние строки, которые важны.
        box.hidden = true;
        return;
      }
      head.textContent = T("Привязать ещё один вход");
      why.textContent = T("Это тот же аккаунт и те же дела — просто зайти в " +
        "него можно будет и так. Без привязки вход другим способом заведёт " +
        "отдельного человека: сличение идёт по поставщику, а не по вам.");
    } else {
      head.textContent = T("Войти");
      why.textContent = T("Разговор не потеряется: вход привязывает второй " +
        "канал к тому же субъекту. Без входа нельзя подписывать обязательства " +
        "и звать людей в дело.");
      if (cfg.email) mail.hidden = false;
      // Телеграм отвечает своим признаком: у службы он значит «бот есть И
      // опрос включён». Токен без опроса — бот, который молчит.
      if (cfg.telegram && tg) tg.hidden = false;
      // Поля phone в ответе может не быть вовсе — служба этого пока не
      // умеет. Тогда формы нет: пустое поле, за которым 404, выглядит как
      // сломанный вход, а не как «ещё не сделали».
      if (cfg.phone) {
        phone.hidden = false;
        // Каналы приходят от службы, она — от провайдера. Своего списка тут
        // нет намеренно: он разошёлся бы с настройкой шлюза молча, и человек
        // выбрал бы канал, которого нет.
        var сел = document.getElementById("phonechan");
        var каналы = cfg.phone_channels || [];
        if (сел && каналы.length > 1) {
          сел.innerHTML = "";
          каналы.forEach(function (k) {
            var o = document.createElement("option");
            o.value = k.code;
            o.textContent = T(k.title + (k.free ? "" : T(" (платно)")));
            сел.appendChild(o);
          });
          // Первый в списке — предпочтительный: службa отдаёт их в порядке
          // нашей выгоды, телеграм раньше СМС.
          сел.value = каналы[0].code;
          сел.hidden = false;
        }
      }
    }

    box.hidden = false;
    offer.forEach(function (k) {
      var b = el("button", "oauth");
      b.type = "button";
      b.appendChild(el("i", BRAND[k].cls, BRAND[k].letter));
      b.appendChild(el("span", null, (signed ? T("Добавить ") : "") + BRAND[k].title));
      b.addEventListener("click", function () { goOAuth(k); });
      oauths.appendChild(b);
    });
    // Кнопка живёт вне #oauths, который перерисовывается, поэтому убираем
    // прежнюю руками: иначе на втором вызове их станет две.
    var old = document.getElementById("later");
    if (old) old.remove();
    if (signed) {
      // Отказаться должно быть так же просто, как согласиться. Совет без
      // «не сейчас» — не совет, а требование.
      var later = el("button", "addone", "Не сейчас");
      later.type = "button";
      later.id = "later";
      later.addEventListener("click", nagLater);
      box.appendChild(later);
    }

    if (!signed && !ready.length && !cfg.email && !cfg.phone) {
      note.hidden = false;
      note.textContent = T("Способы входа ещё не настроены на сервере. " +
        "Разговор при этом идёт — дело уже ваше.");
      return;
    }
    // Говорим прямо, чего нет, вместо мёртвой кнопки.
    var missing = Object.keys(cfg.oauth || {}).filter(function (k) {
      return !cfg.oauth[k];
    }).map(function (k) {
      return (BRAND[k] || {}).title || k;
    });
    // Телефон называем, только когда служба о нём сказала «нет». Молчание
    // ответа — это «служба этого не умеет», а не «скоро подключим»: обещать
    // за неё мы не будем.
    if (cfg.phone === false) missing.push("вход по телефону");
    if (missing.length) {
      note.hidden = false;
      note.textContent = T(T("Пока не подключены: ") + missing.join(", ") + ".");
    }
  }

  /* Адрес возврата прописан в ТРЁХ местах сразу: в кабинете Google, в
     кабинете Яндекса и в OAUTH_REDIRECTS службы. Совпадать он обязан
     буквально, поэтому берётся не из location, а отсюда — и меняется вместе с
     теми тремя, а не молча вслед за адресом страницы.

     Сначала здесь стояло location.origin + "/", и вход отвечал «адрес
     возврата не в списке разрешённых»: разрешён /auth/callback. */
  var REDIRECT = CORE.config.oauthRedirect;

  async function goOAuth(provider) {
    try {
      var r = await api("POST", "/auth/start", {
        provider: provider,
        redirect_uri: REDIRECT,
        // Анонимный токен едет с человеком: вход привязывает второй канал к
        // тому же субъекту, и разговор не переносится, потому что был его.
        anon_token: state.token || ""
      });
      try {
        if (sessionStorage.getItem("fixar.v2.login.return") === "1") {
          localStorage.setItem("fixar.login.state", r.state);
          localStorage.setItem("fixar.login.back", "/v2/");
        }
      } catch (e) { /* возврат в v2 необязателен для самого входа */ }
      location.href = r.authorize_url || r.url;
    } catch (e) {
      сорвалось(T("Вход через ") + ((BRAND[provider] || {}).title || provider) +
                T(" сейчас не работает: "), e);
    }
  }

  /* ── Второй вход в ту же учётную запись ───────────────────────────── */

  /* Зачем это вообще. Пока каналы не связаны, вход гуглом и вход яндексом —
     ДВА РАЗНЫХ человека для системы: у каждого свои дела, свои кредиты, своя
     память. Человек этого не ждёт и узнаёт случайно — по пустому списку дел
     после входа «не тем» способом.

     Привязка идёт от имени вошедшего и возвращается сюда же: состояние
     помечается в хранилище, чтобы страница возврата отличила её от обычного
     входа. Личность второй стороны придёт от поставщика — оболочка её не
     называет и назвать не может. */
  var LINK_KEY = "fixar.link.state";

  async function goLink(provider) {
    try {
      var r = await api("POST", "/auth/link/start", {
        provider: provider, redirect_uri: REDIRECT,
      });
      // Пометка ОБЯЗАТЕЛЬНА, и её неудача — повод не уходить. Без неё
      // возврат от поставщика обработается как обычный вход, а состояние
      // заведено для привязки: служба ответит отказом, и человек увидит
      // непонятную ошибку вместо ясного «так нельзя». Молча уйти — значит
      // отправить его в тупик.
      try {
        localStorage.setItem(LINK_KEY, r.state);
      } catch (e) {
        say("bot", "Ф", "Не могу запомнить, что мы уходим привязывать вход — " +
            "браузер не даёт писать в хранилище (приватный режим?). " +
            "Без этого возврат не отличить от обычного входа, поэтому не иду.");
        return;
      }
      location.href = r.authorize_url;
    } catch (e) {
      сорвалось(T("Привязать ") + ((BRAND[provider] || {}).title || provider) +
          T(" не вышло: "), e);
    }
  }

  /* ═══ ВХОДЫ И ВЫХОД ЖИВУТ В ПИЛЮЛЕ ШАПКИ ═══

     РЕШЕНИЕ ВЛАДЕЛЬЦА 04.09.2026: «всё, что связано с аккаунтом (входы,
     выходы), должно вываливаться из пилюли в шапке, а не болтаться внизу
     боковой панели».

     И это чинит давнюю беду, записанную прямо здесь ниже. Панелей со списком
     входов было ДВЕ — эта и `renderMePanel` у имени в шапке, — и 02.09.2026
     строку «Телеграм» положили в шапку, а человек её не нашёл, потому что
     смотрел сюда. Вывод тогда сделали неверный: «одна другую не заменяет»,
     и строку продублировали. Правильный вывод — что место у аккаунта должно
     быть ОДНО, и оно там, где написано имя вошедшего.

     Боковой короб `#logins` больше не показывается. Разметка его оставлена:
     он скрыт и пуст, и удалять её отдельной правкой — лишний повод задеть
     соседние панели в файле, который правят из нескольких мест. */
  async function renderLogins() {
    var rows = document.getElementById("mepanel");
    var старый = document.getElementById("logins");
    if (старый) старый.hidden = true;
    if (!rows || !state.principal || !state.token) return;
    var данные;
    try {
      данные = await api("POST", "/entry/logins", {});
    } catch (e) {
      return;
    }
    // Дописываем В КОНЕЦ панели, а не затираем её: выше `renderMePanel`
    // уже написал уровень доверия и кто человек для площадки. Затри мы её —
    // порядок вызовов стал бы несущим, а он ничем не закреплён.
    var прежние = rows.querySelectorAll(".loginwrap");
    var i;
    for (i = 0; i < прежние.length; i++) прежние[i].remove();
    var короб = el("div", "loginwrap");
    короб.appendChild(el("h4", "", T("Входы в эту учётную запись")));
    rows.appendChild(короб);
    rows = короб;
    var есть = {};
    (данные.входы || []).forEach(function (v) { есть[v.канал] = v; });

    ["google", "yandex"].forEach(function (p) {
      var b = BRAND[p] || {};
      var row = el("div", "loginrow");
      row.appendChild(el("span", "lname", b.title || p));
      var v = есть[p];
      if (v) {
        row.appendChild(el("span", "lnote", "привязан"));
      } else {
        var btn = el("button", "addone", "Привязать");
        btn.type = "button";
        btn.addEventListener("click", function () { goLink(p); });
        row.appendChild(btn);
      }
      rows.appendChild(row);
    });

    // Каналы, которых нет в кнопках, всё равно показываем: человек должен
    // видеть ВСЁ, чем в его учётную запись можно войти, а не только то, что
    // мы умеем привязать из оболочки.
    Object.keys(есть).forEach(function (k) {
      // `tg` исключён вместе с кнопочными: ниже у него СВОЯ строка, с
      // привязкой. Оставь его здесь — привязанный телеграм нарисовался бы
      // дважды, а непривязанный не нарисовался бы вовсе.
      if (k === "google" || k === "yandex" || k === "tg") return;
      var row = el("div", "loginrow");
      row.appendChild(el("span", "lname", (BRAND[k] || {}).title || k));
      row.appendChild(el("span", "lnote", "привязан"));
      rows.appendChild(row);
    });

    // Номер телефона — такой же вход, как остальные. Здесь стояло обратное:
    // «подтверждён, а не привязан; войти по нему нельзя — двери такой нет».
    // Дверь есть: /auth/phone/request и /auth/phone/verify открыты наружу и
    // работают, код приходит телеграмом или СМС. Надпись осталась от той
    // поры, когда вход по номеру был выключен намеренно, и с тех пор она
    // говорит человеку неправду о его же учётной записи — а он по ней решает,
    // хватит ли ему одного номера, чтобы вернуться.
    var номера = данные["подтверждённые_номера"] || [];
    var строка = el("div", "loginrow");
    строка.appendChild(el("span", "lname", "Телефон"));
    if (номера.length) {
      строка.appendChild(el("span", "lnote",
                            T("вход по ") + номера[0]["номер"]));
    } else {
      var кнп = el("button", "addone", "Подтвердить");
      кнп.type = "button";
      кнп.addEventListener("click", function () { startPhoneVerify(строка); });
      строка.appendChild(кнп);
    }
    rows.appendChild(строка);

    /* ТЕЛЕГРАМ. Панель теперь ОДНА — та, что у имени в шапке, — и вопрос
       «в какой из двух положить» отпал вместе со второй. */
    var тгСтрока = el("div", "loginrow");
    тгСтрока.appendChild(el("span", "lname", BRAND.tg.title));
    if (есть.tg) {
      тгСтрока.appendChild(el("span", "lnote", T("привязан")));
    } else {
      var кнт = el("button", "addone", T("Привязать"));
      кнт.type = "button";
      // Ход привязки пишется В ЭТУ ЖЕ строку: уйди он в соседнюю панель,
      // человек нажал бы кнопку и не увидел ни кода, ни отказа.
      кнт.addEventListener("click", function () { linkTelegram(тгСтрока); });
      тгСтрока.appendChild(кнт);
    }
    rows.appendChild(тгСтрока);

    // Выход — последней строкой и отдельно от входов: это единственное здесь
    // действие, которое не прибавляет, а заканчивает. Стоять ему среди
    // «Привязать» нельзя — там его нажмут не глядя.
    //
    // И ТОЛЬКО ТОМУ, У КОГО ЕСТЬ ЧЕМ ВЕРНУТЬСЯ. У анонима ключ этой сессии
    // единственный: «выйти» для него значит не выйти, а потерять свои дела
    // навсегда. Служба такой выход и отклоняет, но кнопка, отвечающая
    // отказом, — это обещание, которого мы не держим. Выйти из учётной
    // записи может тот, у кого она есть.
    if (!(данные.входы || []).length) return;

    /* КЛЮЧ ДЛЯ ПРОГРАММ — до «Выйти», потому что это добавление, а не конец.

       ЗАЧЕМ ЭТА КНОПКА. Замер пути разработчика 31.08.2026 нашёл стену в самом
       начале: получить программный доступ можно было ТОЛЬКО войдя человеком,
       открыв консоль браузера и достав токен из localStorage руками. Ручка
       `POST /keys` была открыта наружу всё это время — не хватало кнопки.

       КЛЮЧ ПОКАЗЫВАЕТСЯ ОДИН РАЗ. В базе лежит отпечаток, а не значение:
       показать повторно нечего, и обещать «посмотрю потом» нельзя. */
    var ключиСтрока = el("div", "loginrow");
    ключиСтрока.appendChild(el("span", "lname", T("Ключ для программ")));
    [["read"], ["read", "write"]].forEach(function (права) {
      var пишет = права.length > 1;
      var кк = el("button", "addone", пишет ? T("Чтение и запись")
                                            : T("Только чтение"));
      кк.type = "button";
      кк.title = пишет
        ? T("Публиковать паки, ставить их и класть секреты")
        : T("Только смотреть: списки, состояния, история");
      кк.addEventListener("click", function () {
        создатьКлюч(кк, rows, права);
      });
      ключиСтрока.appendChild(кк);
    });
    rows.appendChild(ключиСтрока);

    /* КЛЮЧИ ДЛЯ ПАКОВ — хранилище секретов арендатора.

       ЗАЧЕМ ЭКРАН. Положить ключ можно только человеком у экрана: маршрут
       требует подтверждённой личности (`min_assurance=2`), а ключ доступа
       уровня доверия НЕ НАСЛЕДУЕТ — так решено в самой таблице ключей
       («подтверждение личности — про человека у экрана, а не про программу,
       которая ходит от его имени»). Значит `curl` тут бесполезен по устройству.

       А экрана не было: замок стоял, двери не было. Владелец наткнулся на это
       01.09.2026, пытаясь положить ключ двери Авито.

       ЗНАЧЕНИЕ НИГДЕ НЕ ОСЕДАЕТ. Поле очищается сразу после отправки, в
       `state` и localStorage не попадает, в списке его нет и быть не может:
       служба отдаёт только приметы. */
    var секреты = el("div", "loginrow");
    секреты.appendChild(el("span", "lname", T("Ключи для паков")));
    var кпоказать = el("button", "addone", T("Показать"));
    кпоказать.type = "button";
    кпоказать.addEventListener("click", function () {
      показатьСекреты(кпоказать, rows);
    });
    секреты.appendChild(кпоказать);
    rows.appendChild(секреты);

    var выход = el("div", "loginrow");
    выход.appendChild(el("span", "lname", "Эта сессия"));
    var кв = el("button", "addone danger", "Выйти");
    кв.type = "button";
    кв.addEventListener("click", function () { выйти(кв); });
    выход.appendChild(кв);
    rows.appendChild(выход);
  }

  /* Выйти из учётной записи.

     ПОЧЕМУ ЭТО НЕ «СТЕРЕТЬ КЛЮЧ У СЕБЯ». Токен — строка в базе службы, и
     срока у неё нет. Стерев ключ только в браузере, мы оставили бы сессию
     годной навсегда: всякий, кому ключ достался, входит как хозяин. Поэтому
     сперва служба, и только потом уборка.

     ПОЧЕМУ УБОРКА ИДЁТ ДАЖЕ ПРИ ОТКАЗЕ СЛУЖБЫ. Выходят чаще всего с чужого
     или общего устройства, и там опаснее всего именно ЭТОТ браузер. Оставить
     в нём рабочий ключ, потому что не дозвонились до службы, значит защитить
     от дальнего и не защитить от ближнего. Убираем — но говорим прямо, что
     на стороне службы сессия могла уцелеть, и это надо повторить.

     ПОЧЕМУ ПОТОМ ПЕРЕЗАГРУЗКА. В памяти вкладки остаётся всё: открытое дело,
     картотека, кабинет, недогруженные ответы. Разбирать это по кусочку —
     способ однажды показать следующему человеку чужую строку. Перезагрузка
     начинает с чистого и ничего не помнит. */
  /* Выдать ключ доступа и показать его ОДИН раз.

     ПРАВА СПРАШИВАЕМ, И ЭТО ИСПРАВЛЕНИЕ. Первая редакция прав не называла и
     молча брала умолчание службы — только чтение. Само умолчание верное
     («забытое „только чтение“ человек заметит сразу, забытое „и запись“ —
     никто, пока чужая программа не перепишет дело»), но кнопка с надписью
     «ключ для программ» выдавала ключ, которым нельзя ни опубликовать пак, ни
     положить секрет. Владелец наткнулся на это первой же командой:
     `scope_required`.

     Поэтому не одна кнопка с умолчанием, а ДВЕ с названными правами: молча не
     выдаётся ничего, и человек видит, что берёт. Срок по-прежнему не
     спрашиваем — у него разумное умолчание, и ошибиться им нельзя.

     ПОЧЕМУ ЗНАЧЕНИЕ НЕ ОСЕДАЕТ НИГДЕ. Оно живёт ровно в узле, который его
     показывает, и умирает вместе с перерисовкой строки. Ни `state`, ни
     localStorage его не видят: ключ — доступ, а не настройка экрана. */
  var ключИдёт = false;
  async function создатьКлюч(кнопка, куда, права) {
    if (ключИдёт) return;
    ключИдёт = true;
    var подпись = кнопка ? кнопка.textContent : "";
    if (кнопка) { кнопка.disabled = true; кнопка.textContent = T("Создаю…"); }
    var итог = null, беда = "";
    try {
      итог = await api("POST", "/keys", {
        label: T("Ключ для программ"),
        scopes: права || ["read"],
      });
    } catch (e) {
      беда = (e && e.message) || T("не вышло");
    }
    ключИдёт = false;
    if (кнопка) { кнопка.disabled = false; кнопка.textContent = подпись; }

    var поле = el("div", "loginrow");
    if (беда || !итог || !итог.key) {
      поле.appendChild(el("span", "lname danger",
        T("Ключ не выдан") + (беда ? ": " + беда : "")));
      куда.appendChild(поле);
      return;
    }
    // ЗНАЧЕНИЕ — В ПОЛЕ, А НЕ В ТЕКСТЕ. Из текста его копируют мышью и теряют
    // пробелом; поле выделяется целиком одним щелчком.
    var вход = document.createElement("input");
    вход.type = "text";
    вход.readOnly = true;
    вход.value = итог.key;
    вход.className = "keyout";
    вход.addEventListener("focus", function () { вход.select(); });
    поле.appendChild(вход);
    куда.appendChild(поле);
    var сказ = el("div", "loginrow");
    сказ.appendChild(el("span", "lname",
      T("Сохраните сейчас: ключ больше не будет показан. Потеряете — отзовите этот и создайте новый.")
      + " " + T("Права:") + " " + (итог.scopes || []).join(", ")));
    куда.appendChild(сказ);
    вход.focus();
  }

  /* Отказ «нужно подтвердить личность» отличается от поломки и от нехватки
     прав: человек не сделал ничего плохого, он просто ещё никто для площадки.

     Проверка своя, а не общая с той, что у файлов (`нуженВход` выше): у той
     текст про файлы, и она в другой области видимости. Две строки предиката
     дешевле, чем перестройка замыкания в файле на пятнадцать тысяч строк. */
  function нужноПодтвердить(e) {
    var d = (e && e.data) ? e.data.detail : null;
    return !!(d && typeof d === "object" && d.reason === "assurance_required")
        || !!(e && e.data && e.data.reason === "assurance_required");
  }

  function сказатьПроПодтверждение(куда) {
    куда.appendChild(el("span", "lname danger",
      T("Ключ кладёт человек, а не программа: нужно подтвердить личность. "
        + "Нажмите своё имя вверху — Telegram или СМС.")));
  }

  var секретыИдут = false;
  async function показатьСекреты(кнопка, куда) {
    if (секретыИдут) return;
    секретыИдут = true;
    var подпись = кнопка ? кнопка.textContent : "";
    if (кнопка) { кнопка.disabled = true; кнопка.textContent = T("Смотрю…"); }
    var список = null, беда = "";
    try {
      список = await api("GET", "/secrets/" + encodeURIComponent(state.principal));
    } catch (e) {
      беда = (e && e.message) || T("не вышло");
    }
    секретыИдут = false;
    if (кнопка) { кнопка.disabled = false; кнопка.textContent = подпись; }
    if (беда) {
      var строкаБеды = el("div", "loginrow");
      строкаБеды.appendChild(el("span", "lname danger",
        T("Ключи не показались") + ": " + беда));
      куда.appendChild(строкаБеды);
      return;
    }
    (список.secrets || []).filter(function (с) { return с.alive; })
      .forEach(function (с) {
        var р = el("div", "loginrow");
        // НОМЕР ВИДЕН: им ключ привязывают к установке, и без него человеку
        // придётся спрашивать его у нас.
        р.appendChild(el("span", "lname",
          с.title + " · " + с.id + " · " + T("брали") + " " + с.taken));
        var кп = el("button", "addone danger", T("Погасить"));
        кп.type = "button";
        кп.addEventListener("click", function () { погаситьСекрет(с.id, кп, куда); });
        р.appendChild(кп);
        куда.appendChild(р);
      });
    положитьФорму(куда);
  }

  function положитьФорму(куда) {
    var форма = el("div", "loginrow");
    var имя = document.createElement("input");
    имя.type = "text";
    имя.placeholder = T("Для чего этот ключ");
    имя.className = "keyin";
    // ЗНАЧЕНИЕ — ПОЛЕ ПАРОЛЯ: через плечо его читают чаще, чем перехватывают.
    var знач = document.createElement("input");
    знач.type = "password";
    знач.placeholder = T("Само значение");
    знач.className = "keyin";
    var кп = el("button", "addone", T("Положить"));
    кп.type = "button";
    кп.addEventListener("click", function () {
      положитьСекрет(имя, знач, кп, куда);
    });
    форма.appendChild(имя);
    форма.appendChild(знач);
    форма.appendChild(кп);
    куда.appendChild(форма);
  }

  var кладём = false;
  async function положитьСекрет(имя, знач, кнопка, куда) {
    if (кладём) return;
    var title = (имя.value || "").trim();
    var value = знач.value || "";
    if (title.length < 2 || !value) {
      куда.appendChild(el("div", "loginrow")).appendChild(
        el("span", "lname danger",
          T("Нужны и название, и значение: ключ без названия через месяц "
            + "не отличить от другого")));
      return;
    }
    кладём = true;
    var подпись = кнопка.textContent;
    кнопка.disabled = true; кнопка.textContent = T("Кладу…");
    var итог = null, беда = null;
    try {
      итог = await api("POST", "/secrets", { title: title, value: value });
    } catch (e) {
      беда = e;
    }
    // ОЧИЩАЕМ СРАЗУ, до всякого показа: значение больше не нужно никому, а
    // поле остаётся на экране открытым.
    знач.value = "";
    value = "";
    кладём = false;
    кнопка.disabled = false; кнопка.textContent = подпись;

    var строка = el("div", "loginrow");
    if (беда) {
      if (нужноПодтвердить(беда)) сказатьПроПодтверждение(строка);
      else строка.appendChild(el("span", "lname danger",
        T("Ключ не положен") + ": " + ((беда && беда.message) || T("не вышло"))));
      куда.appendChild(строка);
      return;
    }
    имя.value = "";
    строка.appendChild(el("span", "lname",
      T("Положен") + ": " + итог.id + " — "
      + T("этим номером ключ привязывают к установке")));
    куда.appendChild(строка);
  }

  async function погаситьСекрет(id, кнопка, куда) {
    кнопка.disabled = true; кнопка.textContent = T("Гашу…");
    var беда = null;
    try {
      await api("POST", "/secrets/" + encodeURIComponent(id) + "/revoke",
                { note: T("погашен владельцем с экрана") });
    } catch (e) {
      беда = e;
    }
    var строка = el("div", "loginrow");
    if (беда) {
      кнопка.disabled = false; кнопка.textContent = T("Погасить");
      if (нужноПодтвердить(беда)) сказатьПроПодтверждение(строка);
      else строка.appendChild(el("span", "lname danger",
        T("Не погашен") + ": " + ((беда && беда.message) || T("не вышло"))));
    } else {
      кнопка.textContent = T("Погашен");
      строка.appendChild(el("span", "lname",
        T("Погашен навсегда. Установки, которые на него ссылались, ключа "
          + "больше не получат.")));
    }
    куда.appendChild(строка);
  }

  var выходИдёт = false;
  async function выйти(кнопка) {
    if (выходИдёт) return;
    выходИдёт = true;
    if (кнопка) { кнопка.disabled = true; кнопка.textContent = T("Выхожу…"); }
    var беда = "";
    try {
      await api("POST", "/entry/logout", { token: state.token || "" });
    } catch (e) {
      беда = reason(e);
    }
    // Убираем ВСЁ, что принадлежит человеку: ключ, открытое дело, кабинет,
    // незавершённые отправки. Отправки лежат под именными ключами, и мели их
    // мы поимённо — остались бы чужие от прежних входов; поэтому по началу
    // имени, а не по своему.
    try {
      localStorage.removeItem(KEY);
      localStorage.removeItem(CASE_KEY);
      localStorage.removeItem(LINK_KEY);
      localStorage.removeItem(NAG_KEY);
      localStorage.removeItem(АКТИВНЫЙ);
      var лишние = [];
      for (var i = 0; i < localStorage.length; i++) {
        var k = localStorage.key(i);
        if (k && (k.indexOf(SENT_PREFIX) === 0 || k.indexOf(CONFIRM_PREFIX) === 0)) {
          лишние.push(k);
        }
      }
      лишние.forEach(function (k) { localStorage.removeItem(k); });
      // Складки разделов не трогаем: это вкус браузера, а не сведения о
      // человеке, и сбрасывать их значит без нужды перетряхнуть экран.
      if (беда) {
        // Пережить перезагрузку должно только это — чтобы сказать словами.
        localStorage.setItem("fixar.logout.warn", беда);
      }
    } catch (e2) { /* приватный режим: писать нельзя, но и не осталось чего */ }
    state.token = "";
    state.principal = "";
    location.reload();
  }

  /* Подтверждение номера в два шага прямо в строке.

     Отдельного экрана нет намеренно: человек пришёл в «Входы» посмотреть, чем
     он входит, и уводить его отсюда ради четырёх цифр — терять его на полпути.
     Форма живёт в той же строке и исчезает, когда закончила. */
  function startPhoneVerify(строка) {
    строка.innerHTML = "";
    строка.appendChild(el("span", "lname", "Телефон"));
    var поле = document.createElement("input");
    поле.type = "tel";
    поле.className = "lphone";
    поле.placeholder = T("+7 900 000-00-00");
    var кн = el("button", "addone", "Выслать код");
    кн.type = "button";
    var подпись = el("span", "lnote", "");
    строка.appendChild(поле);
    строка.appendChild(кн);
    строка.appendChild(подпись);
    поле.focus();

    кн.addEventListener("click", async function () {
      var номер = (поле.value || "").trim();
      if (!номер) { подпись.textContent = T("введите номер"); return; }
      кн.disabled = true;
      подпись.textContent = T("отправляю…");
      try {
        var r = await api("POST", "/phone/verify/request", { phone: номер });
        // Дешёвые каналы выключены у провайдера, остался платный. Ничего не
        // отправлено: тратить чужие деньги молча нельзя, и решение здесь не
        // наше. Показываем цену выбора словами и ждём нажатия.
        if (r["нужно_согласие"]) {
          подпись.textContent = "";
          кн.textContent = T(T("Отправить ") + (r["платные"] || []).join(", ") + T(" (платно)"));
          кн.disabled = false;
          кн.onclick = async function () {
            кн.disabled = true;
            подпись.textContent = T("отправляю…");
            try {
              var r2 = await api("POST", "/phone/verify/request",
                                 { phone: номер, "платно": true });
              askPhoneCode(строка, номер, r2.code_length || 4, r2.delivery || "");
            } catch (e2) {
              кн.disabled = false;
              подпись.textContent = T((e2 && e2.detail) ? e2.detail : "не вышло отправить");
            }
          };
          return;
        }
        askPhoneCode(строка, номер, r.code_length || 4, r.delivery || "");
      } catch (e) {
        кн.disabled = false;
        // Причину показываем как есть: «номер уже подтверждён другой записью»
        // человеку понятнее любого нашего пересказа.
        подпись.textContent = T((e && e.detail) ? e.detail : "не вышло отправить");
      }
    });
  }

  function askPhoneCode(строка, номер, длина, доставка) {
    строка.innerHTML = "";
    строка.appendChild(el("span", "lname", T("Код из ") + длина + T(" цифр")));
    var поле = document.createElement("input");
    поле.type = "text";
    поле.inputMode = "numeric";
    поле.maxLength = длина;
    поле.className = "lphone";
    var кн = el("button", "addone", "Подтвердить");
    кн.type = "button";
    // Чем дошёл код — говорим: человек ищет его не там, где мы послали, и
    // молчание про канал стоит ему минуты растерянности.
    var подпись = el("span", "lnote", доставка === "ok" ? "" : доставка);
    строка.appendChild(поле);
    строка.appendChild(кн);
    строка.appendChild(подпись);
    поле.focus();

    кн.addEventListener("click", async function () {
      var код = (поле.value || "").trim();
      if (код.length !== длина) { подпись.textContent = T(T("нужно ") + длина + T(" цифр")); return; }
      кн.disabled = true;
      подпись.textContent = T("проверяю…");
      try {
        await api("POST", "/phone/verify/confirm", { phone: номер, code: код });
        renderLogins();
      } catch (e) {
        кн.disabled = false;
        подпись.textContent = T((e && e.detail) ? e.detail : "код не подошёл");
      }
    });
  }

  /* ── Кабинет практики ──────────────────────────────────────────────

     Кабинет — не роль и не право: из него не следует доступ ни к одному
     чужому делу. Он заводит принадлежности профессионала — личную базу
     знаний, календарь сроков — и открывает разделы, которых человеку с
     одним своим делом не нужно.

     Кнопка включения рисуется только подтверждённому входу: дверь ответит
     403 уровню ниже второго, и кнопка, которая всегда отказывает, хуже
     отсутствующей. */
  /* Направления, у которых есть кабинет. Список приходит от службы: пакеты
     читает landscape-service, и второй их список здесь разошёлся бы с первым
     на первом же новом направлении. Пакет без блока practice кабинетов не
     обслуживает — предлагать его значит обещать пустую оболочку. */
  async function chooseDomain(уже) {
    var паки;
    try {
      паки = (await api("GET", "/packs")).packs || [];
    } catch (e) {
      сорвалось(T("Список направлений не пришёл: "), e);
      return null;
    }
    // Спрашиваем КАБИНЕТ, а не направление. У направления их бывает
    // несколько: у недвижимости риелтор и собственник, у спецтехники дилер,
    // лизинг-брокер и владелец парка. Подставить первый значит завести
    // человеку чужую картотеку — и заметит он это только по тому, что
    // клиенты называются не так.
    var годные = [];
    паки.forEach(function (p) {
      var виды = (p.practice && p.practice.kinds) || [];
      виды.forEach(function (k) {
        годные.push({ domain: p.id, kind: k.id,
                      title: (p.title || p.id) + " — " + (k.title || k.id) });
      });
    });
    // Уже включённое не предлагаем: повторное включение вернуло бы тот же
    // кабинет, и человек прочёл бы «включено» там, где ничего не изменилось.
    var есть = {};
    (уже || []).forEach(function (p) { есть[p.domain + "/" + (p.kind || "")] = true; });
    годные = годные.filter(function (k) { return !есть[k.domain + "/" + k.kind]; });

    if (!годные.length) {
      say("bot", "Ф", (уже || []).length
        ? "Все кабинеты, какие есть, у вас уже включены."
        : "Ни одно направление пока не обслуживает кабинеты.");
      return null;
    }
    if (годные.length === 1) return годные[0];
    var подсказка = годные.map(function (k, i) {
      return (i + 1) + ") " + k.title;
    }).join("\n");
    var ответ = window.prompt(T("Какой кабинет включаем?\n") + подсказка, "1");
    var n = parseInt(ответ, 10);
    return (n >= 1 && n <= годные.length) ? годные[n - 1] : null;
  }

  /* ── Кабинеты: какой из них сейчас ведём ────────────────────────────

     Кабинетов у человека бывает несколько, и это не редкость: риелтор с
     собственным жильём, преподаватель, который ещё и консультирует поездки.
     Пока их было по одному на направление, «активного» не требовалось —
     подставлялся единственный. С появлением видов подстановка первого стала
     ошибкой: картотека риелтора показывалась собственнику, и заметить это
     можно было только по тому, что клиенты называются не так.

     Выбор ЗАПОМИНАЕТСЯ. Иначе он сбрасывался бы на каждой перезагрузке, и
     человек, ведущий два кабинета, каждый раз попадал бы не в тот.

     Хранится идентификатор кабинета, а не его место в списке: список
     приходит с сервера и порядок в нём не обещан, а «второй сверху» после
     включения третьего означает уже другой кабинет.
  */
  var АКТИВНЫЙ = "fixar.practice";

  function активныйКабинет(список) {
    if (!список || !список.length) return null;
    var сохранён = null;
    try { сохранён = localStorage.getItem(АКТИВНЫЙ); } catch (e) { /* приватный режим */ }
    var найден = сохранён
      ? список.filter(function (p) { return p.id === сохранён; })[0]
      : null;
    // Сохранённого может не быть: кабинет выключили, или это чужая запись
    // после смены входа. Тогда берём первый — но НЕ запоминаем его молча:
    // запомненным должно быть только выбранное человеком.
    return найден || список[0];
  }

  function выбратьКабинет(p) {
    state.practice = p;
    try { localStorage.setItem(АКТИВНЫЙ, p.id); } catch (e) { /* переживём */ }
  }

  // Как называется человеку каждое состояние базы знаний.
  //
  // Четыре, а не два: «мы не спросили» и «спросили, и корпуса нет» — разные
  // вещи. Первое чинится связью, второе — заведением корпуса заново, и
  // одно слово на оба отправило бы человека чинить не то.
  //
  // Слова для потери намеренно называют номер: без него «база знаний
  // потеряна» нечего показать тому, кто будет разбираться.
  var СЛОВА_БАЗЫ = {
    live:    function () { return "база знаний подключена"; },
    none:    function () { return "база знаний пока не подключена"; },
    lost:    function (p) { return "база знаний потеряна: корпуса " +
                                   p.corpus_id + " в хранилище нет"; },
    unknown: function () { return "база знаний: проверить не удалось"; }
  };

  function деталиБазы(p) {
    // Состояние неизвестного вида (служба старше оболочки) — это тоже
    // «не проверено», а НЕ «подключено»: подставлять сюда обещание значит
    // вернуть ровно ту ошибку, ради которой поле и заведено.
    var что = СЛОВА_БАЗЫ[p.corpus_state] ? p.corpus_state : "unknown";
    // Потеря выделена так же, как отказы в операторских панелях: она значит
    // больше, чем объём, и бледнеть ей нельзя.
    return el("span", "pnote" + (что === "lost" ? " bad" : ""),
              СЛОВА_БАЗЫ[что](p));
  }

  /* СТРАНИЦА ПОДБОРА И ЗАЯВКИ С НЕЁ.

     Показывается только тому направлению, где она объявлена пакетом: страница
     открывает объявления анонимам, и включаться сама она не должна нигде.
     Признак приезжает вместе с кабинетом — второго списка направлений в
     оболочке не заводим, он разошёлся бы с пакетом на первой же правке. */

  /* ПАРТНЁРСКИЕ ССЫЛКИ КАБИНЕТА.
     Показывает ДВА списка порознь: что можно рекомендовать за долю и что я
     уже взял. Слить их в один значило бы скрыть разницу между «есть что
     рекомендовать» и «я это уже взял», а для человека это разные состояния.

     ЧИСЛА ЗДЕСЬ ТОЛЬКО ПРО ПЕРЕХОДЫ. Доля начисляется с подтверждённой
     покупки, приёма отчёта программы ещё нет — и оговорка стоит рядом с
     числами, а не внизу мелким. Показать переходы рядом с долей и промолчать
     значит дать человеку посчитать доход, которого не будет. */
  /* СТРАНИЦЫ КЛИЕНТАМ. Практик размещает лендинг СВОЕМУ клиенту, заявки с
     него падают сюда же, в кабинет.

     ВЁРСТКУ НЕ ПРОСИМ. Поля — заголовок, описание, что входит, текст
     согласия; страницу собирает служба. Барьер «принеси html» отсекал почти
     всех, ради кого это заводилось: риелтора, юриста, психолога. */
  async function renderSites() {
    var короб = document.getElementById("sites");
    var строки = document.getElementById("siterows");
    if (!короб || !строки) return;
    var кабинет = state.practice;
    if (!кабинет) { короб.hidden = true; return; }

    var данные;
    try {
      данные = await api("GET", "/practice/sites?domain=" +
                         encodeURIComponent(кабинет.domain));
    } catch (e) {
      короб.hidden = false;
      строки.innerHTML = "";
      строки.appendChild(el("div", "casenote",
        T("Страницы не спросились: ") + reason(e) +
        T(". Это про связь — размещённое никуда не делось.")));
      return;
    }

    var сайты = данные.sites || [];
    короб.hidden = false;
    строки.innerHTML = "";
    /* ЗАГОЛОВОК СТАВИМ ИЗ JS. Текст, написанный прямо в разметке, словарь не
       видит: он ищет по русской фразе в вызовах T(), а по статичным узлам
       никто не ходит. На английской версии такой заголовок остаётся русским,
       и заметить это можно только глазами. */
    var шапка = document.getElementById("siteshead");
    if (шапка) шапка.textContent = T("страницы клиентам");

    сайты.forEach(function (с) {
      var ряд = el("div", "prow");
      ряд.appendChild(el("span", "pname", с.title || с.slug));
      /* СОСТОЯНИЕ СЛОВОМ, А НЕ ЦВЕТОМ. Цвет не читается голосом и не
         переживает чёрно-белую печать, а «снят» надо понять с первого раза. */
      var слово = с.state === "published" ? T("открыта")
                : с.state === "suspended" ? T("снята")
                : T("черновик");
      ряд.appendChild(el("span", "pnum", слово));
      строки.appendChild(ряд);

      /* АДРЕС СОБИРАЕТ СЛУЖБА, а не мы: базовое имя живёт в её настройке.
         Собранный здесь, он повёл бы в никуда в день, когда имя переменится,
         оставаясь похожим на рабочий. */
      var сс = el("div", "casenote");
      var поле = document.createElement("input");
      поле.type = "text"; поле.readOnly = true;
      поле.value = с.address;
      поле.style.width = "100%";
      поле.addEventListener("focus", function () { поле.select(); });
      сс.appendChild(поле);
      строки.appendChild(сс);

      /* ПРИЧИНА СНЯТИЯ — ОБЯЗАТЕЛЬНО. Без неё практик пойдёт чинить то, что
         снято намеренно. */
      if (с.state === "suspended" && с.suspend_reason) {
        строки.appendChild(el("div", "casenote",
          T("Снята: ") + с.suspend_reason));
      }
      if (с.state === "published" && с.paid_until) {
        строки.appendChild(el("div", "casenote",
          T("Размещение оплачено до ") + с.paid_until.slice(0, 10) + "."));
      }
      /* КНОПКА ЕСТЬ У ЧЕРНОВИКА И У СНЯТОГО ЗА ДОЛГ. Второе — не мелочь:
         снятие за неоплату задумано обратимым, и если кабинет не даёт кнопки,
         обратимость остаётся только в базе. Снятому ПО ЖАЛОБЕ кнопки нет: ему
         служба откажет, и предложить нажатие значило бы обмануть. */
      var можно = (с.state === "draft" ||
                   (с.state === "suspended" && с.suspended_for_debt));
      if (можно && с.last_version) {
        /* ЦЕНА НАЗЫВАЕТСЯ ДО НАЖАТИЯ. Отказ «не хватает кредитов» человек
           прочтёт как поломку, а не как счёт. Молчим, только если служба
           сама не назвала ставку: выдуманное число хуже молчания. */
        if (данные.month_price) {
          строки.appendChild(el("div", "casenote",
            T("Размещение стоит ") + данные.month_price +
            T(" кредитов в месяц. Спишем при публикации.")));
        }
        var кн = document.createElement("button");
        кн.className = "mini";
        кн.textContent = с.state === "suspended"
          ? T("Оплатить и вернуть") : T("Опубликовать");
        кн.addEventListener("click", function () { публиковатьСайт(с, кн); });
        строки.appendChild(кн);
      }
      /* ВЫКЛЮЧАТЕЛЬ ПЛАТЫ, а не удобство: размещение помесячное, и без этой
         кнопки опубликованная однажды страница списывала бы кредиты вечно,
         а прекратить это можно было бы только разговором с нами. */
      if (с.state === "published") {
        var снять = document.createElement("button");
        снять.className = "mini";
        снять.textContent = T("Убрать из эфира");
        снять.addEventListener("click", function () { снятьСайт(с, снять); });
        строки.appendChild(снять);
      }
    });

    /* СЧИТАЕМ ТЕМ ЖЕ ЧИСЛОМ, ЧТО И СЛУЖБА. Список отобран по направлению
       кабинета, а предел у службы — по субъекту: сравнивая длину показанного
       с пределом, оболочка врала в обе стороны. У практика с сайтами в двух
       направлениях она обещала завести одиннадцатый, а служба отказывала;
       тому, у кого десять в одном, — прятала кнопку без объяснимой причины. */
    var всего = (данные.total != null) ? данные.total : сайты.length;
    if (всего >= (данные.limit || 10)) {
      строки.appendChild(el("div", "casenote",
        T("Это предел числа страниц (") + всего + T(" из ") +
        (данные.limit || 10) +
        T("). Снимите ненужную или напишите нам.")));
    } else {
      строки.appendChild(создатьКоробСайта());
    }
  }

  /* Публикация ПЛАТНАЯ, и сказать об этом надо ДО нажатия, а не после
     отказа: 402 «не хватает кредитов» человек прочтёт как поломку. */
  async function публиковатьСайт(сайт, кнопка) {
    кнопка.disabled = true;
    var прежний = кнопка.textContent;
    кнопка.textContent = T("Публикуем…");
    try {
      await api("POST", "/practice/sites/" + encodeURIComponent(сайт.id) +
                "/publish", { version_id: сайт.last_version });
      await renderSites();
    } catch (e) {
      кнопка.disabled = false;
      кнопка.textContent = прежний;
      alert(T("Не опубликовалось: ") + reason(e));
    }
  }

  /* Убрать из эфира. СПРАШИВАЕМ, потому что страница у практика видна его
     клиентам: нажатие мимо гасит чужую воронку, и узнает он об этом от
     клиента. Срок при этом не сгорает — вернуть внутри оплаченного месяца
     можно бесплатно, и об этом говорим прямо в вопросе. */
  async function снятьСайт(сайт, кнопка) {
    var оплачено = сайт.paid_until ? сайт.paid_until.slice(0, 10) : "";
    if (!confirm(T("Убрать страницу из эфира? Клиенты перестанут её видеть, "
                   + "и плата за размещение прекратится.")
                 + (оплачено
                    ? " " + T("Оплачено до ") + оплачено +
                      T(" — вернуть в эфир до этого дня можно бесплатно.")
                    : ""))) return;
    кнопка.disabled = true;
    var прежний = кнопка.textContent;
    кнопка.textContent = T("Убираем…");
    try {
      await api("POST", "/practice/sites/" + encodeURIComponent(сайт.id) +
                "/unpublish", {});
      await renderSites();
    } catch (e) {
      кнопка.disabled = false;
      кнопка.textContent = прежний;
      alert(T("Не убралось: ") + reason(e));
    }
  }

  /* КОРОБ ЗАВЕДЕНИЯ. Семь полей вместо вёрстки.

     ТЕКСТ СОГЛАСИЯ — ОТДЕЛЬНОЕ ПОЛЕ, а не галочка в нашей форме: он попадёт
     на страницу рядом с чекбоксом клиента И в запись о заявке. Написать его
     за практика мы не можем — обрабатывать данные будет он. */
  function создатьКоробСайта() {
    var короб = el("div", "casenote");
    var поля = {};
    [["slug", T("Имя в адресе, латиницей"), "remont-pod-kluch"],
     ["title", T("Заголовок страницы"), T("Ремонт под ключ в Москве")],
     ["subtitle", T("Подзаголовок"), T("Смета за день, работы по договору")],
     ["about", T("О чём страница"), ""],
     ["points", T("Что входит, по строке на пункт"), ""],
     ["consent_text", T("Текст согласия на обработку контакта"),
      T("Согласен на обработку телефона для ответа по заявке")]
    ].forEach(function (п) {
      var ярл = el("div", "casenote", п[1]);
      var ввод = document.createElement(п[0] === "about" || п[0] === "points"
                                        ? "textarea" : "input");
      if (ввод.tagName === "INPUT") ввод.type = "text";
      ввод.placeholder = п[2];
      ввод.style.width = "100%";
      поля[п[0]] = ввод;
      короб.appendChild(ярл);
      короб.appendChild(ввод);
    });
    var кн = document.createElement("button");
    кн.className = "mini";
    кн.textContent = T("Завести страницу");
    кн.addEventListener("click", function () { завестиСайт(поля, кн); });
    короб.appendChild(кн);
    return короб;
  }

  async function завестиСайт(поля, кнопка) {
    var кабинет = state.practice;
    if (!кабинет) return;
    /* ПУСТОЕ ОБЯЗАТЕЛЬНОЕ ПОЛЕ НАЗЫВАЕМ САМИ. Иначе служба отвечает 422 по
       схеме, а человек читает «мы составили запрос неверно» — фразу про НАШУ
       ошибку, из которой не следует, что заполнить. Порог согласия тот же,
       что у службы и у конструктора: короче двадцати знаков — это галочка, а
       не согласие. */
    var пусто = [];
    if (!(поля.slug.value || "").trim()) пусто.push(T("имя в адресе"));
    if ((поля.title.value || "").trim().length < 2) пусто.push(T("заголовок"));
    if ((поля.consent_text.value || "").trim().length < 20) {
      пусто.push(T("текст согласия — не короче 20 знаков"));
    }
    if (пусто.length) {
      alert(T("Заполните: ") + пусто.join(", ") + ".");
      return;
    }
    кнопка.disabled = true;
    var прежний = кнопка.textContent;
    кнопка.textContent = T("Заводим…");
    try {
      await api("POST", "/practice/sites", {
        slug: (поля.slug.value || "").trim().toLowerCase(),
        domain: кабинет.domain,
        title: поля.title.value,
        page: {
          title: поля.title.value,
          subtitle: поля.subtitle.value,
          about: поля.about.value,
          /* Пункты — по строке. Разбираем ЗДЕСЬ, чтобы служба принимала
             список, а не разбирала чужой формат вторым местом. */
          points: (поля.points.value || "").split("\n")
                    .map(function (с) { return с.trim(); })
                    .filter(function (с) { return с; }),
          consent_text: поля.consent_text.value
        }
      });
      await renderSites();
    } catch (e) {
      кнопка.disabled = false;
      кнопка.textContent = прежний;
      alert(T("Не завелось: ") + reason(e));
    }
  }

  async function renderAffiliate() {
    var короб = document.getElementById("affil");
    var строки = document.getElementById("affilrows");
    if (!короб || !строки) return;
    var кабинет = state.practice;
    if (!кабинет) { короб.hidden = true; return; }

    var данные;
    try {
      данные = await api("GET", "/practice/affiliate?domain=" +
                         encodeURIComponent(кабинет.domain));
    } catch (e) {
      короб.hidden = false;
      строки.innerHTML = "";
      строки.appendChild(el("div", "casenote",
        T("Ссылки не спросились: ") + reason(e) +
        T(". Это про связь — взятое никуда не делось.")));
      return;
    }

    var офферы = данные.offers || [];
    var мои = данные.mine || [];
    /* Нечего рекомендовать и нечего показать — панели не место на экране.
       Пустой раздел «партнёрские ссылки» читается как поломка. */
    if (!офферы.length && !мои.length) { короб.hidden = true; return; }

    короб.hidden = false;
    строки.innerHTML = "";

    мои.forEach(function (м) {
      var ряд = el("div", "prow");
      ряд.appendChild(el("span", "pname", м.program || м.target_url));
      /* ЯРЛЫК С ДВОЕТОЧИЕМ, А НЕ СОГЛАСОВАНИЕ. «1 переходов» неверно
         по-русски, а перевод потребовал бы своего правила множественного
         числа — которого в словаре «фраза → фраза» выразить нечем. */
      ряд.appendChild(el("span", "pnum",
        T("переходов: ") + м.clicks));
      строки.appendChild(ряд);

      /* Адрес строится от API, а не от САЙТ: переход живёт на API-домене.
         Собранный от сайта он вёл бы в никуда, оставаясь похожим на рабочий. */
      var сс = el("div", "casenote");
      var поле = document.createElement("input");
      поле.type = "text"; поле.readOnly = true;
      поле.value = API + м.path;
      поле.style.width = "100%";
      поле.addEventListener("focus", function () { поле.select(); });
      сс.appendChild(поле);
      строки.appendChild(сс);

      /* ДВЕ МОДЕЛИ ВОЗНАГРАЖДЕНИЯ, И ИХ НЕЛЬЗЯ ПОКАЗЫВАТЬ ОДИНАКОВО.
         Доля от сделки — проценты, фикс за действие — рубли. Показать фикс
         процентами значит соврать в разы, а не в оформлении. */
      if (м.share_bps != null && м.commission_bps != null) {
        строки.appendChild(el("div", "casenote",
          T("Комиссия площадки: ") + (м.commission_bps / 100) +
          T("% со сделки. Ваша доля от неё: ") + (м.share_bps / 100) + "%."));
      } else if (м.share_bps != null && м.commission_fixed_kopecks != null) {
        /* Копейки в рубли — целыми: доли копейки у такого вознаграждения не
           бывают, а «2500.0000001 ₽» выглядит поломкой. */
        var всего = Math.round(м.commission_fixed_kopecks / 100);
        var моё = Math.round(всего * м.share_bps / 10000);
        строки.appendChild(el("div", "casenote",
          T("Платят фиксом: ") + всего + T(" ₽ за действие. Ваша доля: ")
          + моё + " ₽."));
      }
      if (м.target_action) {
        /* ЗА ЧТО ПЛАТЯТ — рядом с числом. Без этого практик посчитает доход
           по переходам, а платят за совсем другое. */
        строки.appendChild(el("div", "casenote",
          T("Засчитывается: ") + м.target_action +
          (м.hold_days ? T(". Ждать выплаты: ") + м.hold_days + T(" дней") : "")
          + "."));
      }
    });

    офферы.forEach(function (о) {
      if (мои.some(function (м) { return м.program === о.source_id; })) return;
      var ряд = el("div", "prow");
      ряд.appendChild(el("span", "pname", о.title));
      if (!о.ready) {
        строки.appendChild(ряд);
        строки.appendChild(el("div", "casenote", о.why_not));
        return;
      }
      var кн = el("button", "", T("Взять ссылку"));
      кн.addEventListener("click", async function () {
        busy(true);
        try {
          var взял = await api("POST", "/practice/affiliate",
                               { domain: кабинет.domain, source_id: о.source_id });
          /* РАСКРЫТИЕ ПОКАЗЫВАЕТСЯ СРАЗУ, а не прячется в справку: практик
             должен увидеть текст, который обязан показать клиенту, в ту же
             минуту, когда получил ссылку. */
          alert(взял.disclosure);
          await renderAffiliate();
        } catch (e) {
          alert(T("Ссылка не взялась: ") + reason(e));
        } finally { busy(false); }
      });
      ряд.appendChild(кн);
      строки.appendChild(ряд);
    });

    /* НАЧИСЛЕННОЕ — ОТДЕЛЬНЫМ ЗАПРОСОМ И ПОСЛЕ ССЫЛОК.
       Деньги живут в журнале кредитов (identity), а ссылки в ландшафте: одна
       ручка на оба ответа означала бы вызов через полплатформы ради строки,
       которой у большинства пока нет.

       Отказ здесь НЕ ломает панель: ссылки уже показаны, и человек не должен
       терять их из-за того, что молчит соседняя служба. */
    try {
      var деньги = await api("GET", "/credits/affiliate");
      if (деньги && (деньги.credited || (деньги.conversions || []).length)) {
        var шапка = el("div", "prow");
        шапка.appendChild(el("span", "pname", T("Начислено за продажи")));
        шапка.appendChild(el("span", "pnum", деньги.credited + T(" кр.")));
        строки.appendChild(шапка);
        строки.appendChild(el("div", "casenote",
          T("Зачтённых продаж: ") + деньги.confirmed + ". " + (деньги.about || "")));
      }
    } catch (e) {
      /* Молчим в панели, но не в консоли: «начисленного нет» и «не спросили»
         для человека одинаковы на вид, а для разбора — нет. */
      console.warn("начисленное не спросилось:", e);
    }

    if (данные.about) {
      строки.appendChild(el("div", "casenote", данные.about));
    }
  }


  async function renderPickPage() {
    var короб = document.getElementById("pickpage");
    var строки = document.getElementById("pickrows");
    if (!короб || !строки) return;
    var кабинет = state.practice;
    if (!кабинет || !кабинет.lead_template) { короб.hidden = true; return; }

    var данные;
    try {
      данные = await api("GET", "/practice/page?domain=" +
                         encodeURIComponent(кабинет.domain));
    } catch (e) {
      короб.hidden = false;
      строки.innerHTML = "";
      строки.appendChild(el("div", "casenote",
        "Страница не спросилась: " + reason(e) +
        ". Это про связь — включённое никуда не делось."));
      return;
    }

    короб.hidden = false;
    строки.innerHTML = "";
    var включена = данные.state === "on" && данные.page_token;

    if (включена) {
      var адрес = САЙТ + "/podbor/#" + данные.page_token;
      var ряд = el("div", "prow");
      ряд.appendChild(el("span", "pname", "Страница включена"));
      строки.appendChild(ряд);

      /* ССЫЛКА — ОНА ЖЕ КЛЮЧ, и это сказано прямо. У публичной страницы входа
         нет и быть не может: кому переслали адрес, тот и видит витрину. */
      var сс = el("div", "casenote");
      сс.appendChild(el("span", "pname", "Ссылка (она же ключ — на визитку "
                                       + "можно, в общий чат не надо):"));
      var поле = document.createElement("input");
      поле.type = "text"; поле.readOnly = true; поле.value = адрес;
      поле.style.width = "100%";
      поле.addEventListener("focus", function () { поле.select(); });
      сс.appendChild(поле);
      строки.appendChild(сс);
    } else {
      строки.appendChild(el("div", "casenote",
        "Страница выключена. Включите — получите ссылку, которую можно дать "
        + "клиенту или напечатать на визитке. На ней он увидит ваши "
        + "опубликованные объявления и сможет оставить заявку."));
    }

    var кн = el("button", "addone", включена ? "Выключить" : "Включить страницу");
    кн.type = "button";
    кн.addEventListener("click", async function () {
      кн.disabled = true;
      try {
        await api("POST", "/practice/page",
                  { domain: кабинет.domain, on: !включена,
                    intro: данные.intro || "", contact: данные.contact || "" });
        await renderPickPage();
      } catch (e) {
        кн.disabled = false;
        строки.appendChild(el("div", "casenote", "Не вышло: " + reason(e)));
      }
    });
    строки.appendChild(кн);

    if (включена) {
      var новый = el("button", "addone danger", "Сменить ссылку");
      новый.type = "button";
      новый.addEventListener("click", async function () {
        /* ЦЕНА НАЗЫВАЕТСЯ ДО, А НЕ ПОСЛЕ. Смена ключа убивает всё, где старый
           адрес напечатан, и узнать об этом человек должен прежде, чем нажал,
           а не из отчёта об успехе. */
        if (!window.confirm(
              "Прежняя ссылка перестанет работать немедленно. Всё, где она "
              + "напечатана — визитки, объявления, подпись в письмах, — будет "
              + "вести в никуда. Сменить?")) return;
        новый.disabled = true;
        try {
          await api("POST", "/practice/page/rotate", { domain: кабинет.domain });
          await renderPickPage();
        } catch (e) {
          новый.disabled = false;
          строки.appendChild(el("div", "casenote", "Не вышло: " + reason(e)));
        }
      });
      строки.appendChild(новый);
    }
  }

  var СОСТОЯНИЕ_ЗАЯВКИ = {
    new: "новая", in_work: "в работе", archived: "в архиве",
    withdrawn: "отозвана человеком"
  };

  async function renderLeads() {
    var короб = document.getElementById("leads");
    var строки = document.getElementById("leadrows");
    var шапка = document.getElementById("leadshead");
    if (!короб || !строки) return;
    var кабинет = state.practice;
    if (!кабинет || !кабинет.lead_template) { короб.hidden = true; return; }

    var данные;
    try {
      данные = await api("GET", "/practice/leads?domain=" +
                         encodeURIComponent(кабинет.domain));
    } catch (e) {
      короб.hidden = true;
      return;
    }
    var список = данные.leads || [];
    if (!список.length) { короб.hidden = true; return; }

    короб.hidden = false;
    if (шапка) шапка.textContent = "Заявки: " + список.length;
    строки.innerHTML = "";

    список.forEach(function (з) {
      var ряд = el("div", "prow");
      var отозвана = з.state === "withdrawn";

      /* У ОТОЗВАННОЙ ПОКАЗЫВАТЬ НЕЧЕГО, и это не бедность выдачи: человек
         забрал контакт обратно. Строка остаётся, чтобы звонивший вчера
         понимал, что за разговор у него был, — но ни имени, ни телефона. */
      ряд.appendChild(el("span", "pname",
        отозвана ? "заявка отозвана" : (з.display_name || "без имени")));
      if (!отозвана) {
        ряд.appendChild(el("span", "pnote", з.contact || ""));
        var что = Object.keys(з.answers || {})
          .filter(function (к) { return з.answers[к]; })
          .map(function (к) {
            return ({ city: "город", rooms: "комнат", budget: "бюджет" }[к] || к)
                 + ": " + з.answers[к];
          }).join(" · ");
        if (что) ряд.appendChild(el("span", "pnote", что));
      }
      ряд.appendChild(el("span", "pnote" + (отозвана ? " bad" : ""),
                         СОСТОЯНИЕ_ЗАЯВКИ[з.state] || з.state));
      строки.appendChild(ряд);

      /* ОСНОВАНИЕ ЗВОНКА — ПОД РУКОЙ У ХОЗЯИНА ТОЖЕ. Спросят «почему вы мне
         звоните» — ответ должен быть здесь, а не в чужой базе. */
      if (!отозвана && з.consent_text) {
        строки.appendChild(el("div", "casenote",
          "Согласие от " + (з.consent_at || "").slice(0, 10) + ": «"
          + з.consent_text + "»"));
      }
    });
  }

  async function renderPractice() {
    var box = document.getElementById("practice");
    if (!box || !state.principal || !state.token) return;
    var rows = document.getElementById("practicerows");
    var данные;
    try {
      данные = await api("GET", "/practice");
    } catch (e) {
      // Раздел не гасим МОЛЧА. Прежде любой отказ двери прятал кабинет
      // целиком — вместе с кнопкой включения, — и человек видел не «сейчас
      // не спросилось», а «кабинетов не бывает». Это разные сообщения, и
      // второе он запоминает надолго.
      box.hidden = false;
      var rows0 = document.getElementById("practicerows");
      rows0.innerHTML = "";
      rows0.appendChild(el("div", "casenote",
        T("Кабинеты сейчас не спросились: ") + reason(e) +
        T(". Это про связь — включённое никуда не делось.")));
      return;
    }
    var список = данные.practices || [];
    // Нечего показывать и нечего предложить — раздела нет вовсе.
    if (!список.length && (state.assurance || 0) < 2) { box.hidden = true; return; }
    box.hidden = false;
    rows.innerHTML = "";

    // Активный кабинет: от него зависит картотека, календарь и строка «за кем
    // дело». Без списка он null — и это состояние тоже осмысленное.
    state.practice = активныйКабинет(список);

    список.forEach(function (p) {
      var row = el("div", "prow" + (state.practice && p.id === state.practice.id
                                    ? " on" : ""));
      // Строка целиком — кнопка переключения. Отдельная кнопка «выбрать»
      // рядом с названием заняла бы место и ничего бы не добавила: выбирают
      // здесь ровно одно.
      var кн = el("button", "pname", p.kind_title || p.title || "кабинет");
      кн.type = "button";
      // Направление называем, когда кабинетов больше одного: «Кабинет
      // риелтора» и «Кабинет консультанта» сами по себе не говорят, где они.
      if (список.length > 1) {
        кн.appendChild(el("span", "pdom", " · " + (p.domain_title || p.domain)));
      }
      кн.addEventListener("click", async function () {
        if (state.practice && p.id === state.practice.id) return;
        выбратьКабинет(p);
        await renderPractice();
        await renderClients();
        renderObjects();
        renderPickPage();
        renderLeads();
        // Строка «за кем дело» тоже смотрит на активный кабинет — иначе
        // после переключения она показывала бы картотеку прежнего.
        if (state.caseId) await renderCaseClient(state.caseId);
      });
      row.appendChild(кн);
      // Про базу знаний говорим словами и ПО ПРОВЕРКЕ, а не по наличию поля.
      //
      // Прежде здесь стояло `p.corpus_id ? "подключена" : "пока не
      // подключена"`. Номер корпуса переживает сам корпус: 20.08.2026 все
      // восемь корпусов, на которые ссылался прод, в kb-forge удалили, номера
      // остались, и до 25.08 каждый из четырёх кабинетов показывал человеку
      // «база знаний подключена», пока поиск и загрузка молча получали 404.
      // Поэтому состояние теперь приезжает с сервера, который РЕАЛЬНО спросил
      // хранилище, а оболочка только называет его словами.
      row.appendChild(деталиБазы(p));
      rows.appendChild(row);
    });

    // Кнопка включения стоит ВСЕГДА, а не только при пустом списке.
    //
    // Прежде она пряталась, как только появлялся первый кабинет, — и риелтор,
    // у которого есть своё жильё, второй кабинет завести не мог никак. Пока
    // кабинет был один на направление, это было почти незаметно; с видами
    // стало запретом на половину задуманного.
    if ((state.assurance || 0) >= 2) {
      var добавить = el("div", "prow");
      добавить.appendChild(el("span", "pname",
        список.length ? "Веду дела ещё где-то" : "Веду дела своих"));
      var btn = el("button", "addone",
                   список.length ? "Включить ещё кабинет" : "Включить кабинет");
      btn.type = "button";
      btn.addEventListener("click", async function () {
        // Направление СПРАШИВАЕМ, а не подставляем. Прежде здесь стояло
        // зашитое «legal»: юрист получал свой кабинет, а преподаватель —
        // юридический, и понять это можно было только по тому, что картотека
        // отказывалась заводить учеников.
        var где = await chooseDomain(список);
        if (!где) { return; }
        btn.disabled = true;
        try {
          var новый = await api("POST", "/practice",
                                { domain: где.domain, kind: где.kind,
                                  title: где.title });
          // Только что включённый и становится активным: человек включил его
          // затем, чтобы в нём работать, и заставлять его после этого ещё и
          // выбирать — просить подтвердить только что сделанное.
          if (новый && новый.id) выбратьКабинет(новый);
          await renderPractice();
          await renderClients();
        renderObjects();
        } catch (e) {
          // Причина отказа приходит от двери словами — показываем её, а не
          // «попробуйте ещё раз»: у отказа по уровню входа есть лечение,
          // и человек прочтёт, какое именно.
          btn.disabled = false;
          rows.appendChild(el("div", "casenote", T("Кабинет не включился: ") + reason(e)));
        }
      });
      добавить.appendChild(btn);
      rows.appendChild(добавить);
    }
  }

  /* ── Чьё это дело ──────────────────────────────────────────────────

     Служба это умела с самого начала: PUT /cases/{id}/client, дверь сверяет
     владение, служба сверяет, что карточка лежит в ландшафте того же
     человека. Не умела ОБОЛОЧКА — и картотека от этого была витриной:
     карточки заводились, дела заводились, а связать их было нечем. У всех
     дел стояло «клиент не назван», и кабинет показывал «дел нет» у каждого
     клиента, сколько бы их ни вели.

     Место выбрано не случайно. Клиент — свойство ДЕЛА («для кого оно»), а не
     карточки, поэтому строка живёт в панели дела, рядом с названием и
     областью. В картотеке ей было бы не место: там список, и связывать
     оттуда значило бы спрашивать «а какое из дел?».

     Один клиент на дело: смена — замена, а не второй рядом. Вести в одном
     деле двух клиентов значит представлять обе стороны, и служба это
     запрещает; здесь то же самое видно глазом — выпадающий список, а не
     набор галочек. */
  async function renderCaseClient(caseId) {
    if (!caseId || !fieldsEl) return;
    // ТОЖДЕСТВО, А НЕ «НЕПУСТО». Ниже четыре ожидания подряд, и за это время
    // человек успевает открыть другое дело: панель пересобирается заново, а
    // fieldsEl — переменная модуля, и она снова непуста. Прежняя проверка
    // `if (!fieldsEl)` это пропускала, и строка дела A дописывалась в панель
    // дела B — с картотекой по направлению A и обработчиком, замкнутым на
    // caseId = A. Человек выбирал имя и записывал клиента делу, которого на
    // экране уже нет, не получив ни одного отказа.
    var панель = fieldsEl;
    var дело = caseId;
    // Кабинет спрашиваем САМИ, а не ждём, пока его положат в state.
    //
    // Панель дела собирается раньше боковых панелей, а state.practice
    // заполняет renderPractice — то есть при первом открытии дела его там
    // ещё нет, и строка молча не появлялась. Зависимость от порядка вызовов
    // тем и плоха, что ошибается через раз: у того, кто открыл дело вторым,
    // всё работало, и поломка выглядела случайной.
    // Кабинет берём ПО НАПРАВЛЕНИЮ ДЕЛА, а не первый попавшийся. Кабинетов у
    // человека бывает несколько, и в разных направлениях: у психолога один, у
    // риелтора два в недвижимости. Взять первый значит предложить связать дело
    // о жилье с картотекой психолога — и картотека послушно её примет, потому
    // что дверь проверяет владение, а не осмысленность.
    var кабинеты;
    try {
      кабинеты = (await api("GET", "/practice")).practices || [];
    } catch (e) { return; }
    if (!кабинеты.length) return;         // кабинета нет — строке неоткуда взяться

    var домен = "";
    try {
      домен = ((await api("GET", "/cases/" + encodeURIComponent(caseId))) || {}).domain || "";
    } catch (e) { /* направление неизвестно — решим по числу кабинетов */ }

    // НАПРАВЛЕНИЕ ДЕЛА ОБЯЗАТЕЛЬНО. Пусто оно бывает буднично: у только что
    // заведённого дела его ещё не проставили, а запрос за делом мог и не
    // ответить. Прежде в этом случае брались ВСЕ кабинеты, и активный —
    // скажем, психолога — предлагался делу о ремонте. Картотека выглядела
    // законно, и привязка проходила: чужой она станет только на глаз того,
    // кто откроет её месяцем позже.
    if (!домен) return;
    var подходящие = кабинеты.filter(function (k) { return k.domain === домен; });
    if (!подходящие.length) return;

    // Активный кабинет решает двусмысленность. Раньше при двух кабинетах
    // одного направления (риелтор и собственник) строка молчала: показать
    // не ту картотеку хуже, чем не показать никакой. Теперь человек сказал
    // сам — переключателем, — и молчать больше не за чем.
    var каб = null;
    if (state.practice) {
      каб = подходящие.filter(function (k) { return k.id === state.practice.id; })[0];
    }
    // Активный не из этого направления — берём единственный подходящий.
    // Если их несколько, по-прежнему молчим: гадать не станем.
    if (!каб) {
      if (подходящие.length !== 1) return;
      каб = подходящие[0];
    }

    var карточки, текущий = "";
    try {
      карточки = (await api("GET", "/practice/clients?domain=" +
                            encodeURIComponent(каб.domain) + "&kind=" +
                            encodeURIComponent(каб.kind || ""))).clients || [];
      var дела = (await api("GET", "/practice/" +
                            encodeURIComponent(state.principal) + "/cases")).cases || [];
      var это = дела.filter(function (d) { return d.id === caseId; })[0];
      текущий = (это && это.party_id) || "";
    } catch (e) {
      // Кабинет не отвечает — строки просто нет. Показать пустой список
      // значило бы предложить связать дело неизвестно с чем.
      return;
    }

    if (fieldsEl !== панель || state.caseId !== дело) return;
    var кого = каб.client_title || "Клиент";
    var row = el("div");
    row.appendChild(el("dt", null, кого));
    var dd = el("dd");
    var sel = document.createElement("select");
    sel.className = "clientsel";

    var пусто = document.createElement("option");
    пусто.value = "";
    пусто.textContent = T("— не назван —");
    sel.appendChild(пусто);
    карточки.forEach(function (c) {
      var o = document.createElement("option");
      o.value = c.party_id;
      o.textContent = c.display_name;
      sel.appendChild(o);
    });
    // Завести карточку прямо отсюда: дело чаще заводят НА новом клиенте, и
    // отправлять человека в другую панель ради одного имени — лишний шаг,
    // на котором связь и теряется.
    var новый = document.createElement("option");
    новый.value = "\u0000новый";
    новый.textContent = T("+ завести карточку…");
    sel.appendChild(новый);
    sel.value = текущий;

    var было = текущий;
    sel.addEventListener("change", async function () {
      var выбран = sel.value;
      sel.disabled = true;
      try {
        if (выбран === "\u0000новый") {
          var имя = window.prompt(кого + T(": как зовут?"));
          if (!имя || !имя.trim()) { sel.value = было; return; }
          var c = await api("POST", "/practice/clients",
                            { domain: каб.domain, kind: каб.kind || "",
                              display_name: имя.trim() });
          выбран = c.party_id || c.id || "";
          if (!выбран) throw new Error("карточка заведена без идентификатора");
        }
        if (!выбран) {
          // Снять клиента отдельной ручки нет, и придумывать её здесь не
          // за чем: «не назван» — это состояние до первой привязки, а не
          // действие. Возвращаем список к тому, что есть на сервере.
          sel.value = было;
          note.textContent = T("Убрать клиента у дела пока нельзя — только заменить.");
          return;
        }
        await api("PUT", "/cases/" + encodeURIComponent(caseId) + "/client",
                  { party_id: выбран });
        было = выбран;
        note.textContent = T("Дело записано за клиентом. Оно появилось в картотеке.");
        await renderClients();
        renderObjects();
      } catch (e) {
        sel.value = было;
        note.textContent = T(T("Не вышло связать: ") + reason(e));
      } finally {
        sel.disabled = false;
      }
    });

    dd.appendChild(sel);
    var note = el("div", "sub", карточки.length
      ? "дело видно в картотеке у того, за кем записано"
      : "картотека пуста — заведите карточку здесь же");
    dd.appendChild(note);
    row.appendChild(dd);
    // ЗАМЕНА, А НЕ ДОПИСЫВАНИЕ. Переключение кабинета зовёт эту отрисовку
    // заново, и прежняя строка оставалась на экране — живая, с картотекой
    // прежнего кабинета и своим обработчиком. Выбор в ней привязывал дело к
    // клиенту ЧУЖОГО кабинета, и служба это принимала: она сверяет, что
    // карточка лежит в ландшафте владельца дела, а вид кабинета не смотрит.
    // Три переключения давали четыре списка, и все, кроме последнего, врали.
    var прежняя = панель.querySelector(".clientrow");
    if (прежняя) прежняя.remove();
    row.className = "clientrow";
    панель.appendChild(row);
  }

  /* ── Картотека клиентов ────────────────────────────────────────────

     Две двери, а не одна: карточки отдаёт кабинет (landscape), дела —
     служба дел. Свести их в один ответ значило бы завести второе место,
     отвечающее «какие у меня дела», и однажды эти два места разойдутся.
     Сводит их здесь экран, и это дешевле расхождения.

     Дело без клиента показано отдельной строкой, а не спрятано: только что
     заведённому делу клиента ещё не назвали, и пропасть оно не должно. */
  /* Объекты кабинета — то, вокруг чего он собран.

     Кабинет собственника был построен наоборот: единственная кнопка заводила
     карточку ГОСТЯ. Гость съезжает, карточка с его ФИО и контактом остаётся
     навсегда, потому что привязана ни к чему. Квартира же переживает всех
     своих жильцов: она сдавалась двадцать раз, и каждый наём — отдельное
     дело со своим сроком.

     Кабинет без объекта (юрист, психолог) раздел не показывает вовсе: у них
     первичен не предмет, а само дело, и выдумывать им «объект» значило бы
     навязывать чужую форму. */
  /* ── Ландшафт: ВСЕ объекты человека, а не колонка кабинета ─────────

     ЗАЧЕМ ОТДЕЛЬНО ОТ renderObjects. Тот показывает объекты КАБИНЕТА и
     выходит на первой строке, если кабинета нет: `if (!каб ||
     !каб.object_type ...) return`. А кабинет есть у единиц. Сверх того он
     спрашивает объекты С ФИЛЬТРОМ по одному виду — то есть даже у владельца
     кабинета видна одна колонка его ландшафта, а не ландшафт.

     Замер, ради которого это и делается: 02.09.2026 на проде тринадцать
     объектов у двенадцати субъектов, и показать их человеку было НЕГДЕ.
     Служба при этом всё умеет: `GET /principals/{}/entities` без параметров
     отдаёт ландшафт целиком, пустой — пустым списком, а не отказом.

     ГРУППИРОВКА ПО НАПРАВЛЕНИЮ, а не по области жизни: области у объекта
     сегодня нет (она есть у дела), и рисовать «Я / Семья / Работа» было бы
     обещанием раскладки, которой в данных не существует. Появится поле —
     появится и раскладка.

     НАЗВАНИЯ НАПРАВЛЕНИЙ И ВИДОВ БЕРЁМ У СЛУЖБЫ (`/packs`), а не держим свой
     список: своя копия разошлась бы с настоящим на первом переименовании —
     ровно как это уже было с формой объекта. Не пришли — показываем
     служебный ключ, и это честнее выдуманного названия. */
  async function renderLandscape() {
    var короб = document.getElementById("landscape");
    if (!короб) return;
    var cnt = document.getElementById("landscapecnt");
    var rows = document.getElementById("landscaperows");
    if (!state.principal) { короб.hidden = true; return; }

    var объекты;
    try {
      объекты = await api("GET", "/principals/" +
                          encodeURIComponent(state.principal) + "/entities");
    } catch (e) {
      // Отказ — не пустота. Скрыть короб значило бы сказать «объектов нет».
      короб.hidden = false;
      rows.innerHTML = "";
      cnt.textContent = T("ландшафт") + ": " + T("не прочитан");
      rows.appendChild(el("div", "casenote",
        T("Ландшафт не пришёл: ") + reason(e) +
        T(". Это не значит, что он пуст.")));
      return;
    }
    if (!Array.isArray(объекты)) объекты = [];

    // ПУСТОЙ ЛАНДШАФТ НЕ ПРЯЧЕМ. Человек должен знать, что место есть и оно
    // пока пусто, — иначе первый объект ему просто негде будет ждать. Раздел
    // без объяснения «а что тут будет» был бы пустой полкой без подписи.
    короб.hidden = false;
    rows.innerHTML = "";
    cnt.textContent = T("ландшафт") + (объекты.length ? ": " + объекты.length : "");
    if (!объекты.length) {
      rows.appendChild(el("div", "casenote",
        T("Пока пусто. Сюда встают ваши объекты — дом, машина, техника, " +
          "продукт: дела и бумаги собираются вокруг них. Назовите предмет в " +
          "разговоре, и я предложу поставить его сюда.")));
      return;
    }

    // Человеческие имена направлений и видов — у службы.
    var имена = {};
    try {
      (await направления()).forEach(function (p) {
        имена[p.id] = { title: p.title || p.id, виды: {} };
        (p.entity_types || []).forEach(function (t) {
          имена[p.id].виды[t.type] = t.title || t.type;
        });
      });
    } catch (e) { /* без имён покажем ключи — это честнее выдумки */ }

    /* ОДИН УРОВЕНЬ: НАПРАВЛЕНИЕ. Область жизни на экран не выходит.

       Здесь было два уровня — область жизни, внутри неё направление, — и
       область стояла сверху как «ось человека». Владелец снял её с экрана
       03.09.2026: «эти три сферы не должны быть снаружи — они для агента
       (его внутреннее знание)», и следом «и они задают температуру чата».

       Ось жива и лежит там же, где лежала (`cases.scope`,
       `landscape_entities.scope`). Изменилось, КТО ЕЮ ПОЛЬЗУЕТСЯ: не человек,
       выбирающий вкладку, а агент, держащий по ней регистр разговора.

       Оставить заголовки «на всякий случай» было бы хуже, чем убрать: у
       большинства предметов область пуста, и человек видел бы один заголовок
       «Не отнесены» над всем своим ландшафтом. */
    var по_направлению = {};
    объекты.forEach(function (о) {
      (по_направлению[о.domain || ""] = по_направлению[о.domain || ""] || []).push(о);
    });
    /* ПО ЧИСЛУ ПРЕДМЕТОВ, при равенстве по имени — та же ось и тот же порядок,
       что на новом экране (`_ветви` в start.js). Алфавит сам по себе ставит
       «Автомобиль» перед «Недвижимостью» у человека с одной машиной и восемью
       квартирами. Безымянное направление — последним и названо вслух. */
    Object.keys(по_направлению).sort(function (a, b) {
      if (!a) return 1;
      if (!b) return -1;
      var ра = по_направлению[b].length - по_направлению[a].length;
      if (ра) return ра;
      var иа = (имена[a] && имена[a].title) || a;
      var иб = (имена[b] && имена[b].title) || b;
      return иа.localeCompare(иб, "ru");
    }).forEach(function (дом) {
      var группа = по_направлению[дом];
      var имя = (имена[дом] && имена[дом].title) || дом || T("без направления");
      rows.appendChild(el("div", "crsep", имя + " · " + группа.length));
      _деревом(группа).forEach(function (пара) {
        rows.appendChild(_строкаОбъекта(пара.о, имена, пара.уровень));
      });
    });
  }

  /* Разложить плоский список деревом: родитель, под ним дети.

     СЛУЖБА ОТДАЁТ ПЛОСКО, И ЭТО ВЕРНО: дерево — способ показать, а не способ
     хранить, и собирать его на сервере значило бы решать за оболочку, как
     она будет рисовать.

     СИРОТУ НЕ ТЕРЯЕМ. Родитель может быть снят с поля (`active=false`) или
     лежать в другом направлении — тогда его нет в этой группе. Ребёнок при
     этом обязан остаться видимым, пусть и на верхнем уровне: пропавшего не
     ищут, и человек решит, что объект исчез.

     ПРЕДЕЛ ГЛУБИНЫ ЗДЕСЬ ТОЖЕ, а не только в службе. Кольцо может лежать в
     данных — от правки руками в базе или от старой ошибки, — и обход без
     ограничителя повесил бы вкладку намертво. Служба кольца не пускает, но
     оболочка обязана пережить и то, чего быть не должно. */
  var ПРЕДЕЛ_ВЛОЖЕННОСТИ = 6;

  function _деревом(список) {
    var свои = {};
    список.forEach(function (о) { свои[о.id] = о; });

    var дети = {};
    var корни = [];
    список.forEach(function (о) {
      var р = о.parent_id;
      if (р && свои[р] && р !== о.id) {
        (дети[р] = дети[р] || []).push(о);
      } else {
        // Родителя нет в этой группе — показываем как корень, а не прячем.
        корни.push(о);
      }
    });

    var вышло = [];
    var видели = {};
    function обойти(о, уровень) {
      if (видели[о.id] || уровень > ПРЕДЕЛ_ВЛОЖЕННОСТИ) return;
      видели[о.id] = true;
      вышло.push({ о: о, уровень: уровень });
      (дети[о.id] || []).forEach(function (д) { обойти(д, уровень + 1); });
    }
    корни.forEach(function (о) { обойти(о, 0); });
    // Кого не обошли — всё равно покажем: потеряться не должен никто.
    список.forEach(function (о) {
      if (!видели[о.id]) вышло.push({ о: о, уровень: 0 });
    });
    return вышло;
  }

  /* ══ ПОЛЕ ЛАНДШАФТА ══════════════════════════════════════════════════

     Изометрия СЧИТАЕТСЯ формулой, а не поворачивается css-трансформой всей
     плоскости. Повёрнутая плоскость поворачивает и подписи: имя объекта
     уезжает под 45° и перестаёт читаться, а крутить каждую подпись обратно
     значит получить дрожь при масштабировании. Здесь место считается, а
     подписи стоят прямо.

     ПОЛЕ НЕ ЗАМЕНЯЕТ СПИСОК, а стоит рядом. Список работает на узком экране,
     читается голосом и не требует наведения; поле — нет. Заменить один
     другим значило бы отнять ландшафт у того, кто пришёл с телефона.

     ЧЕГО ЗДЕСЬ НЕТ И ПОЧЕМУ. Перетаскивания нет: в модели НЕТ КООРДИНАТ —
     ни x, ни y, только `position` (порядок среди соседей). Расставляем
     сами, поэтому «перетащил и оставил» сохранять некуда, а движение,
     которое не переживёт перезагрузку, хуже его отсутствия: человек решит,
     что расстановка потерялась. Появятся координаты — появится и оно. */

  //: Размер клетки в пикселях. Ширина вдвое больше высоты — та самая
  //: изометрия «2:1», при которой клетка читается ромбом, а не щелью.
  //: Клетка ШИРЕ, чем кажется нужным, и это подписи, а не вкус. Фигурка
  //: рисуется в 72 пикселя, но под ней стоит имя объекта — «Дом · Ольховая,
  //: 12» это полторы сотни. Клетка в 132 давала налезание подписей соседних
  //: рядов друг на друга, и поле переставало читаться ровно тем, ради чего
  //: заведено: именами.
  var КЛЕТКА_Ш = 210, КЛЕТКА_В = 108;

  function _вЭкран(x, y) {
    return { x: (x - y) * КЛЕТКА_Ш / 2, y: (x + y) * КЛЕТКА_В / 2 };
  }

  /* РАССТАНОВКА ДЕТЕРМИНИРОВАННАЯ, А НЕ СЛУЧАЙНАЯ. Случайная переставляла бы
     фигурки при каждом обновлении, и человек терял бы то, что уже нашёл
     глазами. Здесь порядок задан самим списком, а он отсортирован службой. */
  function _местаНаПоле(объекты) {
    var ряд = Math.max(2, Math.ceil(Math.sqrt(объекты.length)));
    return объекты.map(function (о, i) {
      return { о: о, gx: i % ряд, gy: Math.floor(i / ряд) };
    });
  }

  /* Силуэты. Форма, А НЕ ЦВЕТ, отличает фигурки: на сорока пикселях цвет
     читается хуже силуэта, а у человека с цветовой слепотой не читается
     вовсе. Цвет здесь — только состояние (есть срок или нет). */
  /* НАЗВАНО `СИЛУЭТЫ`, А НЕ `ФОРМЫ`, И ЭТО НЕ ВКУС.
     `ФОРМЫ` в этом файле УЖЕ ЗАНЯТО — так зовётся набор фигур заставки
     (app.js:728). Оболочка целиком лежит в одном самовызове, то есть в одной
     области видимости: второе `var ФОРМЫ` не заводит новую переменную, а
     переприсваивает ту же. Заставка после моей правки читала бы объект
     силуэтов вместо своего массива и сломалась бы — молча и в месте, никак
     не связанном с ландшафтом. */
  var СИЛУЭТЫ = {
    /* ═══ ПЛОСКОЕ ПРОТИВ ИЗОМЕТРИЧЕСКОГО ═══
       Почти всё здесь плоское, и это замер, а не вкус. Изометрический объём
       держится на гранях, а на сорока пикселях грани сливаются: дом, башня и
       навесное были тремя почти одинаковыми кубами, и различить их было
       нельзя. Читается ОЧЕРТАНИЕ и один-два опознавательных знака внутри —
       скат крыши, колесо, ковш, окна рядами.
       Объём оставлен ровно одному силуэту — `box`, и по обратной причине:
       у «помещения» лица нет, и безликость здесь смысл, а не недоделка. */

    // дом: двускатная крыша и дверь
    house: "M-25,17 L-25,-4 L0,-24 L25,-4 L25,17 Z M-7,17 L-7,1 L7,1 L7,17",

    /* помещение — ЕДИНСТВЕННОЕ геометрическое тело в наборе, и это нарочно.
       Прямоугольником его делать нельзя: он сольётся и с башней, и с бытовой
       техникой — обе прямоугольные. Куб остаётся ни на что не похожим. */
    box:   "M0,-24 L26,-9 L26,9 L0,24 L-26,9 L-26,-9 Z",

    // здание: два ряда окон и дверь внизу. Окна — то, чем здание отличается
    // от коробки, и без них оно ею и было.
    tower: "M-17,20 L-17,-28 L17,-28 L17,20 Z"
         + " M-10,-22 L-10,-15 M0,-22 L0,-15 M10,-22 L10,-15"
         + " M-10,-8 L-10,-1 M0,-8 L0,-1 M10,-8 L10,-1 M-5,20 L-5,8 L5,8 L5,20",

    // бытовая техника и навесное: панель сверху и круглый люк
    gear:  "M-16,-17 L16,-17 L16,18 L-16,18 Z M-16,-8 L16,-8"
         + " M0,5 a9,9 0 1,0 0.1,0 M-11,-13 L-5,-13",

    /* машина — СБОКУ, и это проверено глазами. Прежний силуэт был низким
       изо-корпусом без колёс и читался приплюснутым шестиугольником: от
       `box` его отличал только наклон. Нарисовано семь вариантов и
       просмотрено в настоящем размере — читается то, у чего есть КОЛЁСА и
       ступенька «капот ниже крыши». */
    car:   "M-30,2 L-28,-7 L-13,-7 L-5,-18 L9,-18 L17,-7 L30,-6 L30,2 Z"
         + " M-3,-16 L-3,-7 M-1,-16 L8,-16 L13,-8"
         + " M-17,2 a6,6 0 1,0 0.1,0 M16,2 a6,6 0 1,0 0.1,0",

    // спецтехника: гусеницы, кабина, стрела с ковшом. Гусеница и ковш —
    // два знака, которых нет ни у чего другого в наборе.
    rig:   "M-26,18 L14,18 L18,12 L-22,12 Z"
         + " M-18,12 L-18,-4 L-2,-4 L-2,12 M-14,-4 L-14,-16 L-4,-16 L-4,-4"
         + " M-2,-2 L14,-14 L22,-6 L14,2 Z",

    // участок, место: плоскость с флажком
    plot:  "M0,-8 L28,6 L0,20 L-28,6 Z M0,-8 L0,-30 L14,-26 L0,-22",

    // человек — контрагент, член семьи, бригада
    person:"M0,-30 a6,6 0 1,0 0.1,0 M0,-22 L0,-4 M-9,-14 L9,-14 M0,-4 L-8,10 M0,-4 L8,10",

    // произведение: продукт, проект, курс, статья — лист с загнутым углом
    work:  "M-20,-16 L14,-16 L22,-8 L22,14 L-20,14 Z M14,-16 L14,-8 L22,-8",

    /* МАРШРУТ, А НЕ ЛОДКА. Здесь была лодка с парусом, и ею помечен
       `travel.route` — то есть ПУТЬ. Силуэт не просто плохо читался, он врал:
       поездка на поезде получала парусник. Теперь тропа от точки отправления
       к булавке назначения — это и есть маршрут, чем бы по нему ни ехали. */
    route: "M-22,17 C-4,17 -12,1 4,1 C18,1 14,-9 22,-11"
         + " M-22,17 m-4,0 a4,4 0 1,0 8,0 a4,4 0 1,0 -8,0"
         + " M22,-11 m-6,-6 a6,6 0 1,0 12,0 a6,6 0 1,0 -12,0 M22,-11 L22,-4",

    /* неизвестное: щербатый обломок. НАМЕРЕННО НЕ ПОХОЖ НИ НА ЧТО — свободный
       вид человек назвал сам, и подсовывать ему чужой силуэт значит соврать о
       том, что система его узнала. Прежний правильный пятиугольник на мелком
       размере сливался с шестиугольником `box`; неровный не спутать. */
    unknown:"M-2,-24 L16,-14 L12,-2 L20,6 L6,18 L-10,14 L-16,0 L-12,-14 Z"
  };

  /* ТИП → СИЛУЭТ, и таблица собрана ПО НАСТОЯЩИМ ПАКЕТАМ, а не по памяти.
     Первая редакция была написана на глаз, и разбор поймал её на выдумке:
     пять ключей (`realty.home`, `realty.plot`, `realty.space`,
     `newbuild.property`, `psychology.person`) не существуют НИ В ОДНОМ
     пакете, а покрыто было 15 типов из 51. На живом ландшафте это поле из
     одинаковых гранёных камней — что я и увидел на пробе, наполовину
     списав на заглушку.

     Своя копия здесь ВРЕМЕННАЯ, и правильное место для силуэта — сам пакет
     (поле у entity_type): типы растут там, а не тут, и следующий новый вид
     снова окажется камнем. Пока поля нет, таблица живёт здесь и покрывает
     ВСЕ объявленные виды, которые вообще ставятся на поле. */
  var СИЛУЭТ_ПО_ТИПУ = {
    // жильё и строения
    "realty.property": "house", "household.home": "house",
    "legal.property": "house", "construction.building": "house",
    "newbuild.unit": "box", "renovation.space": "box",
    "newbuild.project": "tower", "administration.venue": "tower",
    "administration.practice": "tower",
    // земля
    "construction.plot": "plot", "excavation.site": "plot", "auto.bay": "plot",
    // транспорт и техника
    "auto.vehicle": "car",
    "machinery.machine": "rig", "excavation.machine": "rig",
    "excavation.attachment": "gear", "household.appliance": "gear",
    // сделанное человеком
    "software.product": "work", "software.stand": "work", "it.bot": "work",
    "it.project": "work", "renovation.project": "work",
    "it.course": "work", "education.subject": "work",
    "education.material": "work",
    // люди
    "medicine.person": "person", "construction.crew": "person",
    "renovation.crew": "person",
    // путь
    "travel.route": "route"
  };

  /* ЧТО ВООБЩЕ НЕ СТАВИТСЯ НА ПОЛЕ.

     Из 51 объявленного вида фигуркой бывают 28. Остальные — бумаги (полис,
     штраф, выписка, договор), события (запись о ремонте, срок, приём) и
     окна времени: они не предметы, а то, что ЛЕЖИТ ВНУТРИ предмета. Поставь
     их на поле — и рядом с домом встанет его же выписка, а рядом с машиной
     её полис; поле перестанет быть описью имущества и станет свалкой всего.

     Четыре исключения названы поимённо: лекарство (расходное и мелкое,
     живёт у человека), ученик и запрос (это лица и поводы, не предметы),
     и `legal.matter` — это ДЕЛО, ему место в списке дел.

     СВОБОДНЫЙ ВИД СТАВИТСЯ ВСЕГДА. Человек назвал его сам, и решать за него,
     предмет это или бумага, нам нечем. */
  var НЕ_НА_ПОЛЕ = {
    "realty.inventory": 1, "newbuild.application": 1, "auto.policy": 1,
    "auto.fine": 1, "machinery.offer": 1, "administration.voucher": 1,
    "legal.contract": 1, "travel.booking": 1,
    "auto.service_record": 1, "auto.due": 1, "software.release": 1,
    "medicine.study": 1, "education.slot": 1,
    "household.slot": 1, "machinery.slot": 1, "legal.slot": 1,
    "medicine.slot": 1, "psychology.slot": 1,
    "medicine.medication": 1, "education.student": 1,
    "psychology.request": 1, "legal.matter": 1,
    /* Вопрос О САМОЙ ПЛОЩАДКЕ предметом не бывает: на поле стоят вещи и дела
       человека, а не его разговор с нами. Список держится в ДВУХ местах —
       здесь и в start.js, — и сторож требует их совпадения. */
    "platform.question": 1,
    /* Бюджет и трата на поле не стоят. Поле показывает ВЕЩИ человека — жильё,
       машину, технику, — у которых есть силуэт и которые можно показать
       пальцем. Бюджет это запись внутри дела, а трата — строка в ней; рядом
       по той же причине уже лежат `legal.matter` и `psychology.request`. */
    "finance.budget": 1, "finance.expense": 1
  };

  function _наПоле(о) {
    if (о.type_source === "free") return true;
    return !НЕ_НА_ПОЛЕ[(о.domain || "") + "." + (о.type || "")];
  }

  function _силуэт(о) {
    if (о.type_source === "free") return "unknown";
    return СИЛУЭТ_ПО_ТИПУ[(о.domain || "") + "." + (о.type || "")] || "unknown";
  }

  var полеОткрыто = false;

  function закрытьПоле() {
    var к = document.getElementById("landfield");
    if (к) к.hidden = true;
    var с = document.getElementById("landfieldcard");
    if (с) с.hidden = true;
    полеОткрыто = false;
  }

  async function открытьПоле() {
    var к = document.getElementById("landfield");
    var пл = document.getElementById("landfieldplane");
    var зам = document.getElementById("landfieldnote");
    if (!к || !пл || !state.principal) return;
    к.hidden = false;
    полеОткрыто = true;
    пл.innerHTML = "";
    зам.textContent = T("читаю…");

    var объекты;
    try {
      объекты = await api("GET", "/principals/" +
                          encodeURIComponent(state.principal) + "/entities");
    } catch (e) {
      зам.textContent = T("ландшафт не пришёл: ") + reason(e) +
                        T(". Это не значит, что он пуст.");
      return;
    }
    if (!Array.isArray(объекты)) объекты = [];
    // Бумаги, события и окна на поле не ставим — они внутри предмета. Но
    // МОЛЧА их не прячем: число сказано в шапке, иначе «объектов 8» на
    // экране против 14 в списке читается как потеря.
    var всего = объекты.length;
    объекты = объекты.filter(_наПоле);
    var спрятано = всего - объекты.length;
    if (!объекты.length) {
      зам.textContent = "";
      пл.appendChild(el("div", "casenote",
        T("На поле пока никого. Назовите предмет в разговоре — я предложу " +
          "поставить его сюда.")));
      return;
    }
    зам.textContent = T("объектов: ") + объекты.length +
      (спрятано ? T(" · не на поле: ") + спрятано +
                  T(" (бумаги, события, окна — они внутри предметов)") : "");

    var места = _местаНаПоле(объекты);
    var ряд = Math.max(2, Math.ceil(Math.sqrt(объекты.length)));
    // СДВИГ СЧИТАЕМ ПО СЕТКЕ, А НЕ ПО ФИГУРКАМ. У изометрии левая половина
    // уходит в минус, и самая левая точка — нижний угол ПЛОСКОСТИ, который
    // левее любой фигурки. Посчитав по фигуркам, я обрезал сетке левый край:
    // фигурки стояли верно, а плоскость под ними была срезана и уезжала
    // вправо-вниз.
    var рядов = Math.ceil(объекты.length / ряд);
    var сдвигX = -_вЭкран(0, рядов + 1).x + 60;

    // СЕТКА ПОД ФИГУРКАМИ. Без неё фигурки висят в пустоте и изометрия не
    // читается: глаз не видит плоскости и не понимает, что предметы стоят
    // РЯДОМ, а не одни над другими. Рисуем ровно под теми клетками, что
    // заняты, плюс один ряд запаса — поле размером с ландшафт, а не с экран.
    пл.appendChild(_сетка(ряд + 1, рядов + 1, сдвигX, 110));

    места.forEach(function (м) {
      var p = _вЭкран(м.gx, м.gy);
      пл.appendChild(_фигурка(м.о, p.x + сдвигX, p.y + 110));
    });
    // Плоскости нужна высота: она из потока выпала, и без этого прокрутка
    // не доедет до нижнего ряда.
    var низ = места.length
      ? _вЭкран(места[места.length - 1].gx, места[места.length - 1].gy).y + 240
      : 240;
    var распорка = el("div");
    распорка.style.height = низ + "px";
    распорка.style.width = "1px";
    пл.appendChild(распорка);
  }

  /* Плоскость под фигурками — одним SVG, а не сотней узлов: клеток бывает
     под сотню, и каждая отдельным div'ом делает прокрутку заметно тяжелее
     ровно на том экране, где объектов много. */
  function _сетка(колонок, рядов, сдвигX, сдвигY) {
    var НС = "http://www.w3.org/2000/svg";
    var svg = document.createElementNS(НС, "svg");
    var уг = _вЭкран(колонок, рядов);
    var лев = _вЭкран(0, рядов);
    var прав = _вЭкран(колонок, 0);
    svg.setAttribute("width", Math.round(прав.x - лев.x + 2 * сдвигX));
    svg.setAttribute("height", Math.round(уг.y + сдвигY + 60));
    svg.style.position = "absolute";
    svg.style.left = "0"; svg.style.top = "0";
    svg.style.pointerEvents = "none";
    function линия(a, b) {
      var l = document.createElementNS(НС, "line");
      l.setAttribute("x1", a.x + сдвигX); l.setAttribute("y1", a.y + сдвигY);
      l.setAttribute("x2", b.x + сдвигX); l.setAttribute("y2", b.y + сдвигY);
      l.setAttribute("stroke", "var(--hair)");
      l.setAttribute("stroke-width", "1");
      svg.appendChild(l);
    }
    for (var i = 0; i <= колонок; i++) линия(_вЭкран(i, 0), _вЭкран(i, рядов));
    for (var j = 0; j <= рядов; j++) линия(_вЭкран(0, j), _вЭкран(колонок, j));
    return svg;
  }

  function _фигурка(о, x, y) {
    var b = el("button", "lfig");
    b.type = "button";
    b.style.left = Math.round(x) + "px";
    b.style.top = Math.round(y) + "px";
    b.setAttribute("aria-expanded", "false");

    var НС = "http://www.w3.org/2000/svg";
    var svg = document.createElementNS(НС, "svg");
    svg.setAttribute("width", "72"); svg.setAttribute("height", "72");
    svg.setAttribute("viewBox", "-36 -56 72 72");
    var g = document.createElementNS(НС, "path");
    g.setAttribute("d", СИЛУЭТЫ[_силуэт(о)] || СИЛУЭТЫ.unknown);
    g.setAttribute("fill", "var(--panel-2)");
    g.setAttribute("stroke", "var(--ink-2)");
    g.setAttribute("stroke-width", "1.4");
    g.setAttribute("stroke-linejoin", "round");
    svg.appendChild(g);
    b.appendChild(svg);

    b.appendChild(el("span", "lname", о.title || T("Без названия")));
    b.addEventListener("click", function (e) {
      e.stopPropagation();
      _карточкаОбъекта(о, b);
    });
    return b;
  }

  /* Карточка объекта: операции и дела по нему.

     ЧЕГО ЗДЕСЬ НЕТ ИЗ ДИЗАЙНА, И ЭТО НАЗВАНО ВСЛУХ. «Клонировать» и
     «Передать» не показаны: ни ручки, ни механики для них не существует, а
     кнопка, которая ответит отказом, хуже отсутствующей — человек нажмёт и
     решит, что сломан сервис. Появятся ручки — появятся пункты. */
  async function _карточкаОбъекта(о, кнопка) {
    var карт = document.getElementById("landfieldcard");
    var пл = document.getElementById("landfieldplane");
    if (!карт || !пл) return;

    [].forEach.call(пл.querySelectorAll(".lfig[aria-expanded=\"true\"]"),
      function (e) { e.setAttribute("aria-expanded", "false"); });
    кнопка.setAttribute("aria-expanded", "true");

    карт.hidden = false;
    карт.innerHTML = "";
    карт.style.left = (parseInt(кнопка.style.left, 10) + 46) + "px";
    карт.style.top = (parseInt(кнопка.style.top, 10) - 40) + "px";

    карт.appendChild(el("div", "lct", о.title || T("Без названия")));
    var приписка = [];
    if (о.type_source === "free") приписка.push(T("свой вид"));
    else if (о.type) приписка.push(о.type);
    Object.keys(о.fields || {}).slice(0, 2).forEach(function (k) {
      var v = String((о.fields || {})[k] == null ? "" : о.fields[k]).slice(0, 22);
      if (v) приписка.push(v);
    });
    карт.appendChild(el("div", "lcs", приписка.join(" · ")));

    function пункт(имя, действие, вид) {
      var b = el("button", вид || null, имя);
      b.type = "button";
      b.addEventListener("click", function (e) { e.stopPropagation(); действие(b); });
      карт.appendChild(b);
      return b;
    }

    пункт(T("Завести дело"), function () {
      // НЕ ЗАВОДИМ САМИ. Дело без согласия не заводится — это решение старше
      // этого экрана. Кладём предмет в намерение и закрываем поле: человек
      // напишет, о чём дело, и увидит, что получилось, прежде чем это чего-то
      // будет стоить.
      закрытьПоле();
      var вх = document.getElementById("input");
      if (вх) {
        вх.value = (вх.value ? вх.value + " " : "") +
                   T("по объекту «") + (о.title || "") + "»: ";
        вх.focus();
      }
    });

    var делаКн = пункт(T("Дела по объекту"), function (b) {
      b.disabled = true;
      b.textContent = T("Дела по объекту") + " …";
    });
    var убрать = пункт(T("Убрать с ландшафта"), function (b) {
      b.disabled = true;
      b.textContent = T("убираю…");
      // Своей ручки «снять с поля» у владельца ещё нет — её ставит только
      // оператор. Говорим об этом прямо, а не молчим и не делаем вид.
      var зам = el("div", "casenote",
        T("Пока не могу: снять объект с ландшафта умеет только оператор " +
          "площадки. Своей ручки у владельца ещё нет — это следующий шаг."));
      карт.appendChild(зам);
      b.textContent = T("Убрать с ландшафта");
    }, "warn");
    void убрать;

    // Дела спрашиваем СРАЗУ: карточка без них — это меню без содержимого, а
    // ради дел её и открывают.
    var дела = null;
    try {
      дела = (await api("GET", "/entities/" + encodeURIComponent(о.id) +
                        "/cases")).cases || [];
    } catch (e) { дела = null; }
    делаКн.disabled = false;
    if (дела === null) {
      делаКн.textContent = T("Дела по объекту");
      делаКн.appendChild(el("span", "lcn", T("не пришли")));
    } else if (!дела.length) {
      делаКн.textContent = T("Дел по объекту ещё не было");
    } else {
      делаКн.textContent = T("Дела по объекту");
      делаКн.appendChild(el("span", "lcn", String(дела.length)));
      дела.slice(0, 6).forEach(function (d) {
        пункт(" · " + (d.title || T("Дело")), function () {
          закрытьПоле();
          openCase(d.id);
        });
      });
    }
  }

  (function () {
    var откр = document.getElementById("landfieldopen");
    if (откр) откр.addEventListener("click", function () { открытьПоле(); });
    var закр = document.getElementById("landfieldclose");
    if (закр) закр.addEventListener("click", закрытьПоле);
    // Esc закрывает поле — тем же жестом, что колокольчик и кредиты. Три
    // короба в одной оболочке, закрывающиеся по-разному, человек считает
    // разными по устройству.
    document.addEventListener("keydown", function (e) {
      if (e.key === "Escape" && полеОткрыто) закрытьПоле();
    });
    // Щелчок мимо фигурки убирает карточку, но не поле: закрывать всё разом
    // значило бы терять поле от промаха.
    var пл = document.getElementById("landfieldplane");
    if (пл) пл.addEventListener("click", function () {
      var к = document.getElementById("landfieldcard");
      if (к) к.hidden = true;
      [].forEach.call(пл.querySelectorAll(".lfig[aria-expanded=\"true\"]"),
        function (e) { e.setAttribute("aria-expanded", "false"); });
    });
  })();

  /* Строка объекта и раскрытие в дела. Вынесено отдельно, потому что тем же
     самым занят и кабинет: две копии разошлись бы при первой правке. */
  function _строкаОбъекта(о, имена, уровень) {
    var row = el("div", "doc1");
    // Отступом, а не значками: значок «папка» обещал бы, что внутри что-то
    // лежит, и у бездетной фигурки врал бы. Отступ говорит ровно то, что есть.
    if (уровень) row.style.paddingLeft = (12 * Math.min(уровень, 6)) + "px";
    var имя = el("span", "dn", о.title || T("Без названия"));
    имя.style.cursor = "pointer";
    имя.title = T("Показать дела об этом объекте");
    row.appendChild(имя);

    // Приписка: вид словами и первые поля. Вид ПЕРВЫМ — по нему человек
    // узнаёт фигурку, а поля уточняют.
    var куски = [];
    var вид = имена[о.domain] && имена[о.domain].виды[о.type];
    if (вид) куски.push(вид);
    var поля = о.fields || {};
    Object.keys(поля).slice(0, 2).forEach(function (k) {
      var v = String(поля[k] == null ? "" : поля[k]).slice(0, 24);
      if (v) куски.push(v);
    });
    if (куски.length) row.appendChild(el("span", "dst", куски.join(" · ")));

    /* КНОПОК «ОТНЕСТИ К ОБЛАСТИ» ЗДЕСЬ НЕТ. Область жизни снята с экрана
       (03.09.2026): человек не раскладывает свои вещи по Я/Дому/Работе — это
       читает агент, и по этому же он держит регистр разговора. */

    /* История объекта — то, ради чего ландшафт и заводился: третье дело по
       этой квартире начинается не с нуля. Спрашиваем ПО НАЖАТИЮ: у
       собственника объектов бывает три десятка, и тридцать запросов ради
       строки под каждым — плата ни за что. */
    var раскрыто = false;
    имя.addEventListener("click", async function () {
      var прежний = row.nextSibling;
      if (раскрыто && прежний && прежний.className === "objcases") {
        прежний.remove(); раскрыто = false; return;
      }
      имя.textContent = (о.title || T("Без названия")) + " …";
      var дела;
      try {
        дела = (await api("GET", "/entities/" + encodeURIComponent(о.id) +
                          "/cases")).cases || [];
      } catch (e) {
        дела = null;
      } finally {
        имя.textContent = о.title || T("Без названия");
      }
      var под = el("div", "objcases");
      if (дела === null) {
        под.appendChild(el("div", "casenote",
          T("Дела об объекте не пришли. Это не значит, что их нет.")));
      } else if (!дела.length) {
        под.appendChild(el("div", "casenote", T("Дел об этом объекте пока не было.")));
      } else {
        дела.forEach(function (d) {
          var с = el("div", "objcase");
          var t = el("span", "dn", d.title || T("Дело"));
          t.style.cursor = "pointer";
          t.addEventListener("click", function () { openCase(d.id); });
          с.appendChild(t);
          с.appendChild(el("span", "dst", d.state || ""));
          под.appendChild(с);
        });
      }
      row.parentNode.insertBefore(под, row.nextSibling);
      раскрыто = true;
    });
    return row;
  }

  (function () {
    var b = document.getElementById("landscaperefresh");
    if (b) b.addEventListener("click", function () { renderLandscape(); });
  })();

  async function renderObjects() {
    var head = document.getElementById("objectshead");
    var cnt = document.getElementById("objectscnt");
    var rows = document.getElementById("objectrows");
    if (!head || !rows) return;
    var каб = state.practice;
    if (!каб || !каб.object_type || !state.principal) {
      head.hidden = true; rows.hidden = true;
      return;
    }
    head.hidden = false; rows.hidden = false;

    var объекты;
    try {
      объекты = await api("GET", "/principals/" + encodeURIComponent(state.principal) +
                          "/entities?domain=" + encodeURIComponent(каб.domain || "") +
                          "&type=" + encodeURIComponent(каб.object_type));
    } catch (e) {
      rows.innerHTML = "";
      rows.appendChild(el("div", "casenote",
        T("Объекты не пришли: ") + reason(e) + T(". Это не значит, что их нет.")));
      return;
    }

    var как = (каб.object_plural || "объекты").toLowerCase();
    cnt.textContent = T(объекты.length ? как + ": " + объекты.length : как);
    rows.innerHTML = "";
    if (!объекты.length) {
      rows.appendChild(el("div", "casenote",
        T("Пока пусто. Заведите ") + (каб.object_title || T("объект")).toLowerCase()
        + T(" — дела и жильцы собираются вокруг него.")));
      return;
    }
    объекты.forEach(function (о) {
      var row = el("div", "doc1");
      var имя = el("span", "dn", о.title || "Без названия");
      имя.style.cursor = "pointer";
      имя.title = T("Показать дела об этом объекте");
      row.appendChild(имя);
      var поля = о.fields || {};
      var подпись = Object.keys(поля).slice(0, 2)
        .map(function (k) { return String(поля[k]).slice(0, 24); })
        .filter(Boolean).join(" · ");
      if (подпись) row.appendChild(el("span", "dst", подпись));
      rows.appendChild(row);

      /* История объекта — то, ради чего ландшафт и заводился: третье дело по
         этой квартире начинается не с нуля. Спрашиваем по нажатию, а не
         заранее: у собственника объектов бывает три десятка, и тридцать
         запросов ради строки под каждым — плата ни за что. */
      var раскрыто = false;
      имя.addEventListener("click", async function () {
        var прежний = row.nextSibling;
        if (раскрыто && прежний && прежний.className === "objcases") {
          прежний.remove(); раскрыто = false; return;
        }
        имя.textContent = T((о.title || T("Без названия")) + " …");
        var дела;
        try {
          дела = (await api("GET", "/entities/" + encodeURIComponent(о.id) + "/cases")).cases || [];
        } catch (e) {
          дела = null;
        } finally {
          имя.textContent = T(о.title || "Без названия");
        }
        var под = el("div", "objcases");
        if (дела === null) {
          под.appendChild(el("div", "casenote",
            "Дела об объекте не пришли. Это не значит, что их нет."));
        } else if (!дела.length) {
          под.appendChild(el("div", "casenote",
            "Дел об этом объекте пока не было."));
        } else {
          дела.forEach(function (d) {
            var с = el("div", "objcase");
            var t = el("span", "dn", d.title || "Дело");
            t.style.cursor = "pointer";
            t.addEventListener("click", function () { openCase(d.id); });
            с.appendChild(t);
            с.appendChild(el("span", "dst", d.state || ""));
            под.appendChild(с);
          });
        }
        row.parentNode.insertBefore(под, row.nextSibling);
        раскрыто = true;
      });
    });
  }

  /* Заведение объекта. ФОРМА РИСУЕТСЯ ПО ОПИСАНИЮ, пришедшему с сервера.

     ЧТО БЫЛО. Кнопка спрашивала одно название и слала пустые поля. У объекта
     недвижимости три поля обязательны — тип, город, адрес, — и служба честно
     отвечала «поле 'kind' (Тип) обязательно». Форма при этом не показывала ни
     одного поля, так что человеку было нечего исправить: завести объект
     нельзя было ни разу, а отказ выглядел придиркой к тому, чего не спросили.

     Прежний замысел — «спрашивать всё сразу верный способ не завести ничего» —
     остаётся в силе: обязательные поля стоят открыто, остальные спрятаны за
     «ещё поля» и заполняются потом и по делу. Спорным было не количество
     полей, а их отсутствие.

     ПОЧЕМУ НЕ ПИШЕМ ФОРМУ РУКАМИ. Список полей живёт в описании направления и
     приезжает готовым (object_fields). Вписать их сюда значило бы завести
     второй список: у гостиницы «номер», у экскаватора «марка» — и каждый
     новый кабинет требовал бы правки оболочки, ради которой всё это и
     выносилось в пакеты. */

  //: Один вход по описанию поля. Род поля решает, чем его вводят.
  function контрольПоля(поле) {
    var вх;
    if (поле.kind === "enum") {
      вх = el("select", "ofield");
      // Пустой первый пункт даже у обязательного: подставленный первый
      // вариант человек примет за свой выбор и не заметит, что выбрал не он.
      вх.appendChild(el("option", "", поле.required ? "— выберите —" : "—"));
      (поле.options || []).forEach(function (o) {
        var opt = el("option", "", o); opt.value = o; вх.appendChild(opt);
      });
    } else if (поле.kind === "bool") {
      вх = el("input", "ofield obool"); вх.type = "checkbox";
    } else {
      вх = el("input", "ofield");
      вх.type = поле.kind === "number" || поле.kind === "money" ? "number"
              : поле.kind === "date" ? "date" : "text";
      if (поле.kind === "geo") вх.placeholder = T("широта, долгота");
    }
    вх.name = поле.key;
    return вх;
  }

  function строкаПоля(поле) {
    var box = el("div", "orow");
    var под = el("label", "olabel", поле.title + (поле.unit ? ", " + поле.unit : ""));
    if (поле.required) под.appendChild(el("span", "oreq", " — обязательно"));
    var вх = контрольПоля(поле);
    под.setAttribute("for", "of_" + поле.key);
    вх.id = "of_" + поле.key;
    box.appendChild(под);
    box.appendChild(вх);
    // Образец объясняем словами. Сам regexp человеку не говорит ничего, а
    // проверяет его служба: правда о поле одна, и живёт она в описании.
    if (поле.pattern_hint) box.appendChild(el("div", "ohint", поле.pattern_hint));
    return box;
  }

  /* Сбор и проверка вынесены из обработчика НАМЕРЕННО: внутри него они
     заперты вместе с сетью и состоянием, и проверить их можно было бы только
     живым кабинетом. Здесь это две чистые функции над описанием полей —
     читатель значения передаётся снаружи. */

  //: Чего не хватает. Возвращает ЧЕЛОВЕЧЕСКИЕ названия, а не ключи: человек
  //: видит на экране «Город», и «city» ему не поможет.
  function незаполненные(поля, читать) {
    return поля.filter(function (п) { return п.required; })
               .filter(function (п) {
                 var з = читать(п);
                 if (п.kind === "bool") return false;   // «нет» — это ответ
                 return !String((з && з.value) || "").trim();
               })
               .map(function (п) { return п.title; });
  }

  //: Что отправлять службе.
  function значенияПолей(поля, читать) {
    var из = {};
    поля.forEach(function (п) {
      var з = читать(п);
      if (!з) return;
      if (п.kind === "bool") { if (з.checked) из[п.key] = true; return; }
      var v = String(з.value == null ? "" : з.value).trim();
      // Незаполненное необязательное НЕ отправляем. Пустая строка в поле
      // числа или даты — это не «не знаю», а мусор: служба сохранит её и
      // потом покажет человеку как значение.
      if (v) из[п.key] = v;
    });
    return из;
  }

  (function () {
    var b = document.getElementById("objectadd");
    if (!b) return;

    function закрыть() {
      var ф = document.getElementById("objectform");
      if (ф) ф.remove();
      b.textContent = T("Добавить");
    }

    b.addEventListener("click", function () {
      if (document.getElementById("objectform")) { закрыть(); return; }
      var каб = state.practice || {};
      var как = каб.object_title || "Объект";
      var поля = каб.object_fields || [];
      var rows = document.getElementById("objectrows");
      if (!rows) return;

      var ф = el("form", "oform"); ф.id = "objectform";
      ф.appendChild(el("div", "oname", как));

      // Название — не поле пакета, а имя самой записи: по нему объект узнают
      // в списке. Поэтому стоит первым и всегда.
      var шапка = el("div", "orow");
      var подп = el("label", "olabel", "Название");
      подп.appendChild(el("span", "oreq", " — обязательно"));
      подп.setAttribute("for", "of__title");
      var имявх = el("input", "ofield"); имявх.id = "of__title";
      имявх.placeholder = T("например, «Студия на Искровском»");
      шапка.appendChild(подп); шапка.appendChild(имявх);
      ф.appendChild(шапка);

      /* СВОЙ ВИД — то, чего в пакете нет.
         Кабинет собран вокруг одного вида (квартира, машина), и всё, что в
         него не лезет, человеку завести было нечем: дверь отвечала 422, и
         он решал, что такие вещи система не держит. Теперь держит — только
         без формы и без подбора, и об этом сказано ЗДЕСЬ, до нажатия, а не
         отказом после.

         СВЁРНУТО ПО УМОЛЧАНИЮ. Обычный ход — завести объект кабинета; свой
         вид нужен изредка, и выставленный напоказ он превращал бы простую
         форму в развилку на каждый раз. */
      var свойВид = null;
      var свойПер = el("button", "omore", T("это другой вид →"));
      свойПер.type = "button";
      var свойКор = el("div", "ohidden"); свойКор.hidden = true;
      var свойРяд = el("div", "orow");
      var свойПодп = el("label", "olabel", T("Назовите вид"));
      свойПодп.setAttribute("for", "of__freetype");
      свойВид = el("input", "ofield"); свойВид.id = "of__freetype";
      свойВид.placeholder = T("например, «прицеп-коневоз»");
      свойРяд.appendChild(свойПодп); свойРяд.appendChild(свойВид);
      свойКор.appendChild(свойРяд);
      // ЦЕНА НАЗВАНА ДО НАЖАТИЯ. Иначе человек узнаёт о ней, когда объект уже
      // заведён и не ищется в подборе, — и считает это поломкой.
      свойКор.appendChild(el("div", "casenote",
        T("У своего вида не будет формы и подбора: чем эта вещь является, " +
          "знаете пока только вы. Название, свои поля, дела и бумаги по нему " +
          "— всё остальное работает как обычно.")));
      свойПер.addEventListener("click", function () {
        свойКор.hidden = !свойКор.hidden;
        свойПер.textContent = T(свойКор.hidden
          ? "это другой вид →" : "нет, обычный " + как.toLowerCase());
        if (!свойКор.hidden) свойВид.focus();
      });
      ф.appendChild(свойПер);
      ф.appendChild(свойКор);

      var обяз = поля.filter(function (п) { return п.required; });
      var прочие = поля.filter(function (п) { return !п.required; });
      обяз.forEach(function (п) { ф.appendChild(строкаПоля(п)); });

      if (прочие.length) {
        var ещё = el("button", "omore", T("ещё поля: ") + прочие.length);
        ещё.type = "button";
        var скрытые = el("div", "ohidden"); скрытые.hidden = true;
        прочие.forEach(function (п) { скрытые.appendChild(строкаПоля(п)); });
        ещё.addEventListener("click", function () {
          скрытые.hidden = !скрытые.hidden;
          ещё.textContent = T(скрытые.hidden ? T("ещё поля: ") + прочие.length : "свернуть");
        });
        ф.appendChild(ещё);
        ф.appendChild(скрытые);
      }

      var низ = el("div", "obtns");
      var ок = el("button", "osubmit", "Завести"); ок.type = "submit";
      var нет = el("button", "ocancel", "Отмена"); нет.type = "button";
      нет.addEventListener("click", закрыть);
      низ.appendChild(ок); низ.appendChild(нет);
      ф.appendChild(низ);
      var беда = el("div", "casenote"); беда.hidden = true;
      ф.appendChild(беда);

      ф.addEventListener("submit", async function (ev) {
        ev.preventDefault();
        беда.hidden = true;
        var имя = имявх.value.trim();
        // Обязательное проверяем и здесь — чтобы не гонять человека на сервер
        // за тем, что видно на месте. Но правда о поле всё равно на сервере:
        // здесь мы только избавляем от лишнего круга.
        // Свой вид назван — поля пакета не спрашиваем: они описывают ДРУГУЮ
        // вещь, и требовать «пробег» у коневоза значит не пустить его вовсе.
        var свой = !свойКор.hidden && свойВид.value.trim();
        var читать = function (п) { return ф.querySelector("#of_" + п.key); };
        var пусто = свой ? [] : незаполненные(поля, читать);
        if (!имя) пусто.unshift("Название");
        if (пусто.length) {
          беда.textContent = T(T("Не заполнено: ") + пусто.join(", ") + ".");
          беда.hidden = false;
          return;
        }
        var значения = значенияПолей(поля, читать);
        ок.disabled = true;
        try {
          await api("POST", "/principals/" + encodeURIComponent(state.principal) + "/entities",
                    свой
                      ? { domain: каб.domain, type: свой, title: имя,
                          fields: значения, free_type: true }
                      : { domain: каб.domain, type: каб.object_type,
                          title: имя, fields: значения });
          закрыть();
          await renderObjects();
        } catch (e) {
          беда.textContent = T(как + T(" не завёлся: ") + reason(e));
          беда.hidden = false;
        } finally {
          ок.disabled = false;
        }
      });

      rows.parentNode.insertBefore(ф, rows);
      b.textContent = T("Свернуть");
      имявх.focus();
    });
  })();


  /* ── Мои объявления ──────────────────────────────────────────────────────

     То, что человек предлагает сам, включая перенесённое с чужих площадок.

     ПОЧЕМУ ПЕРЕНОС ЗДЕСЬ, А НЕ В РАЗГОВОРЕ. Ключи от кабинета Авито — это
     доступ к чужому бизнесу. Сказанное в разговоре уходит в подсказку модели
     и в журнал прогона; из этой формы ключи уходят прямо в дверь и модели не
     показываются ни разу. Ссылку спросить в разговоре было бы можно, но два
     пути к одному действию расходятся молча, и потому сведены сюда оба.

     ЧТО ПЕРЕНЕСЕНО — ЧЕРНОВИК. Публикует человек своей рукой. Разбор чужой
     страницы ошибается, и опубликованное сразу окажется объявлением, которого
     он не писал.  */

  /* ДЕНЬГИ. Единственное место, где число становится суммой.

     ДО 01.09.2026 ЗДЕСЬ СТОЯЛ `human` — ФОРМАТИРОВЩИК БАЙТОВ. Живьём это
     значило «8.6 КБ ₽» вместо «8 800 ₽» и «44 КБ ₽» вместо «45 000 ₽»: чем
     дороже вещь, тем безобиднее выглядела подпись. Поломка простояла долго,
     потому что проверки её не видели — стенд раздела подменял `human`
     заглушкой `String(n)`, и в проверках цены выглядели правильно. Заглушка
     закрывала собой ровно то, что проверяла.

     `human` остаётся и дальше делает своё дело — размеры файлов; звать его
     для денег нельзя, и об этом сказано в стенде отдельным сторожем.

     Разряды неразрывным пробелом: «8 800 ₽» не должно переноситься по строке
     так, чтобы «800 ₽» оказалось на следующей. Дробей нет намеренно — цены
     здесь целыми рублями (shared/schemas/cases.py про то же). */
  function деньгами(сумма, валюта) {
    var n = Math.round(Number(сумма) || 0);
    var знак = n < 0 ? "\u2212" : "";
    var число = String(Math.abs(n)).replace(/\B(?=(\d{3})+(?!\d))/g, "\u00A0");
    var ед = валюта === "RUB" || !валюта ? "\u20BD" : String(валюта);
    return знак + число + "\u00A0" + ед;
  }

  /* Цена словами. НАБОР целиком, а не одно число из него.

     Единица всегда словом: «45 000 ₽» без пометки «в месяц» — не краткость,
     а ложь, тот же ряд цифр значит и 45 тысяч за ночь, и 45 тысяч за год.
     Подпись приезжает из базы вместе с числом — своего словаря денег здесь
     нет и не должно быть, он бы разошёлся с базой.

     Залог отдельным куском и никогда не в сумме со ставкой: он
     возвращается. */
  function ценой(о) {
    /* Массив, а не «что пришло». Кодек jsonb на службе нигде не
       зарегистрирован, и набор цен приезжает СТРОКОЙ, если служба забыла его
       разобрать. Тогда .forEach бросит исключение и погасит весь раздел —
       человек увидит пустой экран вместо своих объявлений. Показать «цена не
       названа» неприятно, но это одна строка, а не пустой кабинет. */
    var цены = Array.isArray(о.prices) ? о.prices : [];
    if (!цены.length) return о.price_note || "цена не названа";
    var куски = [], залоги = [];
    цены.forEach(function (ц) {
      var кусок = деньгами(ц.amount, о.currency);
      if (ц.is_rate && ц.title) кусок += " " + ц.title;
      if (ц.min_units) кусок += T(", от ") + ц.min_units;
      if (ц.note) кусок += " (" + ц.note + ")";
      куски.push(кусок);
      if (ц.deposit != null && залоги.indexOf(ц.deposit) < 0) залоги.push(ц.deposit);
    });
    if (залоги.length) {
      куски.push(T("залог ") + залоги.map(function (з) {
        return деньгами(з, о.currency);
      }).join(" / "));
    }
    return куски.join(" · ");
  }

  //: Состояние словом. «draft» человеку не говорит ничего.
  var СОСТОЯНИЯ = { draft: "черновик", published: "на витрине", archived: "снято" };


  /* ── Витрина паков ───────────────────────────────────────────────────────

     Четвёртая витрина оболочки после доски, подбора агентов и окон. Здесь
     человек ВИДИТ, что пак попросит, ДО того как нажмёт: права словами, чьи
     ключи придётся привязать, чего площадка про пак не знает.

     Названо storefront, а не packs: «пак» в оболочке уже значит направление.  */

  var СПРАВОЧНИК_ВИТРИНЫ = null;

  async function renderStorefront() {
    var box = document.getElementById("storefront");
    var cnt = document.getElementById("storefrontcnt");
    var rows = document.getElementById("storefrontrows");
    var cat = document.getElementById("storefrontcat");
    if (!box || !rows) return;
    if (!state.principal) { box.hidden = true; return; }

    // Справочник — с площадки, а не свой список у нас. Вторая копия словаря
    // однажды разойдётся с первой, и человек прочтёт код вместо названия.
    if (!СПРАВОЧНИК_ВИТРИНЫ) {
      try {
        СПРАВОЧНИК_ВИТРИНЫ = await api("GET", "/storefront/form");
      } catch (e) {
        if (нуженВход(e)) { box.hidden = true; return; }
        СПРАВОЧНИК_ВИТРИНЫ = null;
      }
    }
    if (СПРАВОЧНИК_ВИТРИНЫ && cat && !cat.options.length) {
      // VALUE ЗАДАЁТСЯ ЯВНО. Без него браузер берёт value из текста пункта, и
      // «все рубрики» уезжает в запрос КАК НАЗВАНИЕ РУБРИКИ: витрина честно
      // отвечает «такой рубрики не бывает», человек видит отказ на первом же
      // экране. Поймано только живой проверкой — тесты службы были зелёные.
      var все = el("option", "", "все рубрики");
      все.value = "";
      cat.appendChild(все);
      (СПРАВОЧНИК_ВИТРИНЫ.categories || []).forEach(function (р) {
        var o = el("option", "", р.title);
        o.value = р.code;
        cat.appendChild(o);
      });
      cat.addEventListener("change", function () { renderStorefront(); });
    }

    var ответ;
    try {
      ответ = await api("POST", "/storefront/search",
                        { category: (cat && cat.value) || "", limit: 20 });
    } catch (e) {
      // Прячем только при 401/403: там раздела действительно нет. Сбой сети —
      // это «не пришло», а не «расширений нет», и молча прятать значит соврать.
      if (нуженВход(e)) { box.hidden = true; return; }
      box.hidden = false;
      rows.innerHTML = "";
      rows.appendChild(el("div", "casenote",
        "Витрина не пришла: " + reason(e) + ". Это не значит, что она пуста."));
      return;
    }

    var список = ответ.packs || [];
    box.hidden = false;
    cnt.textContent = ответ.total
      ? "расширения: " + ответ.total
      : "расширения";

    rows.innerHTML = "";
    if (!список.length) {
      // Пустая выдача объясняет себя словами площадки, а не нашими: причина
      // известна там, где считали.
      rows.appendChild(el("div", "casenote",
        ответ.why_empty || "Пока пусто."));
      return;
    }

    список.forEach(function (п) {
      var row = el("div", "doc1");
      row.appendChild(el("span", "dn", п.title || п.name));
      if (п.publisher_name) {
        row.appendChild(el("span", "dm", п.publisher_name));
      }
      // Приостановленный издатель ПОМЕЧЕН: «опубликованное остаётся» —
      // решение площадки, умолчание об отстранении — нет.
      if (п.publisher_suspended) {
        row.appendChild(el("span", "dm", "· издатель отстранён"));
      }
      if (п.on_canary) {
        row.appendChild(el("span", "dm", "· ограниченный круг"));
      }
      row.appendChild(el("div", "waynote", п.summary || ""));

      // ЧТО ПАК ПРОСИТ — на карточке в списке, а не за ссылкой. Права,
      // показанные после нажатия, человек уже не выбирает.
      // ОБЕ ПОЛОВИНЫ ПРАВА, каждое отдельной строкой. Склейка через «Просит: »
      // давала строку «Просит: ничего: площадка не выдаёт это право...» у пака,
      // который просит СЫРЫЕ ТРЕЙСЫ: человек, скользящий взглядом по списку,
      // читал «Просит: ничего». И терялась успокаивающая половина — та, ради
      // которой пара «сможет / не сможет» и заведена.
      var права = п.requested_capabilities || [];
      if (права.length) {
        row.appendChild(el("div", "waynote", "Пак просит прав: " + права.length));
        права.forEach(function (пр) {
          var стр = el("div", "waynote");
          стр.appendChild(el("span", "dn", пр.code));
          стр.appendChild(el("span", "dm", " сможет: " + (пр["сможет"] || "")));
          if (пр["не сможет"]) {
            стр.appendChild(el("span", "dm", " · не сможет: " + пр["не сможет"]));
          }
          row.appendChild(стр);
        });
      } else {
        row.appendChild(el("div", "waynote", "Ничего не просит."));
      }
      // Дорубричный пак: по рубрике он не найдётся никогда, и молчать об этом
      // значит оставить автора гадать, почему его не видно в разделе.
      if (п.unclassified) {
        row.appendChild(el("div", "waynote",
          "Без рубрики: пак подан до её появления и находится только словами."));
      }
      rows.appendChild(row);
    });

    // Неотключаемо и внизу списка: слово «принято» человек читает как
    // «проверено», и без этой оговорки витрина обманывает молчанием.
    var знаем = (СПРАВОЧНИК_ВИТРИНЫ && СПРАВОЧНИК_ВИТРИНЫ.we_do_not_know) || [];
    if (знаем.length) {
      var низ = el("div", "casenote", "Чего мы не знаем: " + знаем.join("; ") + ".");
      rows.appendChild(низ);
    }
    if (СПРАВОЧНИК_ВИТРИНЫ && СПРАВОЧНИК_ВИТРИНЫ.install_note) {
      rows.appendChild(el("div", "casenote", СПРАВОЧНИК_ВИТРИНЫ.install_note));
    }
  }

  async function renderBoard() {
    var box = document.getElementById("board");
    var cnt = document.getElementById("boardcnt");
    var rows = document.getElementById("boardrows");
    if (!box || !rows) return;
    if (!state.principal) { box.hidden = true; return; }

    var ответ;
    try {
      ответ = await api("GET", "/board/mine/" + encodeURIComponent(state.principal));
    } catch (e) {
      // Раздел прячем только при 401/403: там его действительно нет. Сбой
      // сети — это «не пришло», а не «нет объявлений», и молча прятать раздел
      // значит соврать.
      if (нуженВход(e)) { box.hidden = true; return; }
      box.hidden = false;
      rows.innerHTML = "";
      rows.appendChild(el("div", "casenote",
        T("Объявления не пришли: ") + reason(e) + T(". Это не значит, что их нет.")));
      return;
    }

    var список = ответ.listings || [];
    box.hidden = false;
    cnt.textContent = T(список.length
      ? T("мои объявления: ") + список.length
        + (ответ.drafts ? T(" · черновиков ") + ответ.drafts : "")
      : "мои объявления");

    rows.innerHTML = "";
    if (!список.length) {
      rows.appendChild(el("div", "casenote",
        "Пока пусто. Если ваша техника уже выставлена на Авито или Дроме — "
        + "нажмите «Перенести»: по ссылке заберём одно объявление, по ключам "
        + "кабинета — все сразу."));
      return;
    }

    список.forEach(function (о) {
      var row = el("div", "doc1");
      row.appendChild(el("span", "dn", о.title || "Без названия"));
      var под = ценой(о) + " · " + (СОСТОЯНИЯ[о.state] || о.state);
      if (о.source_platform) под += T(" · перенесено с ") + о.source_platform;
      row.appendChild(el("span", "dst", под));

      if (о.state === "draft") {
        var пуб = el("button", "addone dget", "Опубликовать"); пуб.type = "button";
        пуб.addEventListener("click", function () { решить(о, "publish", пуб); });
        row.appendChild(пуб);
      }
      if (о.state !== "archived") {
        var снять = el("button", "addone dget", "Снять"); снять.type = "button";
        снять.addEventListener("click", function () { решить(о, "archive", снять); });
        row.appendChild(снять);
      }
      rows.appendChild(row);
    });
  }

  async function решить(о, действие, кнопка) {
    кнопка.disabled = true;
    var было = кнопка.textContent;
    try {
      await api("POST", "/board/items/" + encodeURIComponent(о.id) + "/" + действие, {});
      await renderBoard();
    } catch (e) {
      // Причину показываем НА КНОПКЕ и оставляем: перерисовка списка стёрла бы
      // её раньше, чем человек прочитал.
      кнопка.textContent = T(было);
      кнопка.disabled = false;
      // Кладём ПОД строку, а не внутрь неё: .doc1 — это flex в одну линию,
      // и текст отказа в ней сожмётся до нечитаемого столбца букв.
      var строка = кнопка.parentNode;
      var беда = el("div", "fnote", reason(e));
      строка.parentNode.insertBefore(беда, строка.nextSibling);
    }
  }

  (function () {
    var b = document.getElementById("boardimport");
    if (!b) return;

    function закрыть() {
      var ф = document.getElementById("boardform");
      if (ф) ф.remove();
      b.textContent = T("Перенести");
    }

    function поле(ф, ключ, подпись, образец, тип) {
      var box = el("div", "orow");
      var под = el("label", "olabel", подпись);
      под.setAttribute("for", "bf_" + ключ);
      var вх = el("input", "ofield");
      вх.id = "bf_" + ключ;
      вх.type = тип || "text";
      if (образец) вх.placeholder = T(образец);
      box.appendChild(под); box.appendChild(вх);
      ф.appendChild(box);
      return вх;
    }

    b.addEventListener("click", function () {
      if (document.getElementById("boardform")) { закрыть(); return; }
      var rows = document.getElementById("boardrows");
      if (!rows) return;
      var направление = (state.practice && state.practice.domain) || state.domain;
      if (!направление) {
        rows.insertBefore(el("div", "casenote",
          "Сначала выберите направление — объявление должно знать, в чьей "
          + "выдаче ему стоять."), rows.firstChild);
        return;
      }

      var ф = el("form", "oform"); ф.id = "boardform";
      ф.appendChild(el("div", "oname", "Перенести свои объявления"));

      ф.appendChild(el("div", "ohint",
        "Всё перенесённое ложится черновиком: вы прочитаете и опубликуете сами. "
        + "Защиту площадок мы не обходим — если сайт нас не пустит, так и скажем."));

      // ── Путь первый: одна ссылка
      ф.appendChild(el("div", "oname opath", "По ссылке — одно объявление"));
      var ссылка = поле(ф, "url", "Адрес вашего объявления",
                        "https://www.avito.ru/…", "url");
      var кнС = el("button", "osubmit", "Перенести по ссылке"); кнС.type = "button";
      ф.appendChild(кнС);

      // ── Путь второй: весь кабинет
      ф.appendChild(el("div", "oname opath", "По ключам кабинета — все сразу"));
      ф.appendChild(el("div", "ohint",
        "Ключи из настроек вашего профиля продавца на Авито. Мы спросим ими "
        + "ваш же кабинет и перенесём объявления. Ключи используются один раз "
        + "и НЕ сохраняются: ни в базе, ни в журнале, ни в подсказке помощника."));
      var кид = поле(ф, "client_id", "client_id", "");
      var сек = поле(ф, "client_secret", "client_secret", "", "password");
      var кнК = el("button", "osubmit", "Перенести кабинет"); кнК.type = "button";
      ф.appendChild(кнК);

      var низ = el("div", "obtns");
      var нет = el("button", "ocancel", "Отмена"); нет.type = "button";
      нет.addEventListener("click", закрыть);
      низ.appendChild(нет);
      ф.appendChild(низ);

      var весть = el("div", "casenote"); весть.hidden = true;
      ф.appendChild(весть);

      function сказать(текст) { весть.textContent = T(текст); весть.hidden = false; }

      async function послать(кнопка, путь, тело, готово) {
        весть.hidden = true;
        кнопка.disabled = true;
        try {
          var о = await api("POST", путь, тело);
          сказать(готово(о));
          // Ключи стираем из формы сразу, не дожидаясь ухода со страницы:
          // введённое остаётся в поле, а страницу оставляют открытой.
          сек.value = ""; кид.value = "";
          await renderBoard();
        } catch (e) {
          сказать(reason(e));
        } finally {
          кнопка.disabled = false;
        }
      }

      кнС.addEventListener("click", function () {
        var url = ссылка.value.trim();
        if (!url) { сказать("Нужен адрес страницы объявления."); return; }
        послать(кнС, "/board/import/link",
                { url: url, domain: направление }, function (о) {
          if (о.already) return "Это объявление уже перенесено.";
          ссылка.value = "";
          return "Перенесено черновиком. Проверьте цену и описание — и "
               + "опубликуйте, когда всё верно.";
        });
      });

      кнК.addEventListener("click", function () {
        var id = кид.value.trim(), секрет = сек.value.trim();
        if (!id || !секрет) { сказать("Нужны оба ключа кабинета."); return; }
        послать(кнК, "/board/import/avito",
                { client_id: id, client_secret: секрет, domain: направление },
                function (о) {
          return T("Перенесено черновиками: ") + о.imported
               + (о.already ? T(", уже было ") + о.already : "")
               + T(" из ") + о.total_in_account + T(" в кабинете.")
               + (о.truncated ? T(" Перенесли не всё — повторите, чтобы забрать остальное.") : "")
               + T(" Ключи не сохранены.");
        });
      });

      // Enter в поле адреса — это «перенеси», а не «перезагрузи страницу».
      // Форма без обработчика submit уводит браузер на текущий адрес и
      // стирает всё введённое, включая набранные ключи.
      ф.addEventListener("submit", function (ev) {
        ev.preventDefault();
        if (кнС.disabled || кнК.disabled) return;
        кнС.click();
      });

      rows.parentNode.insertBefore(ф, rows);
      b.textContent = T("Свернуть");
      ссылка.focus();
    });
  })();

  async function renderClients() {
    var box = document.getElementById("clients");
    if (!box || !state.principal || !state.token) return;
    var rows = document.getElementById("clientrows");
    var head = document.getElementById("clientshead");
    // Кабинет спрашиваем САМИ, если его ещё не положили в состояние.
    // renderPanels зовёт renderPractice и renderClients подряд и БЕЗ await —
    // то есть на первом проходе state.practice ещё пуст, и картотека
    // пряталась целиком. Появлялась она только со второго вызова, и потому
    // выглядела «то есть, то нет».
    var каб = state.practice;
    if (!каб) {
      try {
        var список = (await api("GET", "/practice")).practices || [];
        каб = активныйКабинет(список);
        if (каб) state.practice = каб;
      } catch (e) { box.hidden = true; return; }
    }
    if (!каб) { box.hidden = true; return; }

    // Кабинет запоминаем СНИМКОМ и дальше пользуемся только им. Прежде строки
    // брались из захваченного, а заголовок — из state.practice уже ПОСЛЕ
    // ожиданий: переключив кабинет в этот промежуток, человек получал список
    // одного под названием другого.
    var карточки;
    try {
      карточки = (await api("GET", "/practice/clients?domain=" +
                            encodeURIComponent(каб.domain) + "&kind=" +
                            encodeURIComponent(каб.kind || ""))).clients || [];
    } catch (e) {
      // Кабинет не включён — дверь отвечает 403, и картотеки просто нет.
      box.hidden = true;
      return;
    }
    // Дела спрашиваем ОТДЕЛЬНЫМ try. Прежде обе двери стояли под одним, и
    // падение службы дел прятало уже полученную картотеку клиентов — то есть
    // отказ одного показывал отсутствие другого.
    var дела = [];
    var делаНеПришли = false;
    try {
      дела = (await api("GET", "/practice/" +
                        encodeURIComponent(state.principal) + "/cases")).cases || [];
    } catch (e) { делаНеПришли = true; }

    // Пока ждали — могли переключить кабинет. Тогда рисовать этот список уже
    // незачем: следующий вызов нарисует свой.
    if (state.practice && state.practice.id !== каб.id) return;

    box.hidden = false;
    rows.innerHTML = "";
    // Слово приходит с сервера вместе с кабинетом: у юриста клиенты, у
    // преподавателя ученики. Второй словарь в оболочке разошёлся бы с
    // первым на первом же направлении.
    var кого = каб.client_title || "Клиенты";
    // Заголовок называет КАБИНЕТ, когда их несколько: «картотека: 3 ·
    // наниматель» одинаково выглядит у риелтора и у собственника, а списки
    // за ней разные.
    var чей = каб.kind_title || "";
    head.textContent = T((карточки.length
      ? T("картотека: ") + карточки.length + " · " + кого.toLowerCase()
      : T("картотека")) + (чей ? " · " + чей.toLowerCase() : ""));

    if (делаНеПришли) {
      // Счёт дел у каждого клиента сейчас неверен, и молчать об этом нельзя:
      // «дел нет» и «дела не спросились» на экране выглядят одинаково, а
      // означают разное.
      rows.appendChild(el("div", "casenote",
        "Дела сейчас не спросились — у клиентов показано «дел нет», " +
        "и это про связь, а не про дела."));
    }
    var поКлиенту = {};
    var ничьи = [];
    // Дела ЭТОГО кабинета, а не все подряд. Список приходит по владельцу
    // целиком — вместе с личными делами и делами соседнего кабинета, — и
    // строка «клиент не назван» показывала их под заголовком активного:
    // человек видел в картотеке риелтора свою переписку про ремонт.
    дела.filter(function (d) { return !d.domain || d.domain === каб.domain; })
        .forEach(function (d) {
      if (!d.party_id) { ничьи.push(d); return; }
      (поКлиенту[d.party_id] = поКлиенту[d.party_id] || []).push(d);
    });

    карточки.forEach(function (c) {
      var row = el("div", "crow");
      row.appendChild(el("span", "cname", c.display_name));
      row.appendChild(el("span", "ccnt",
        c.cases ? c.cases + T(" дел") : "дел нет"));
      // ЗАВЕСТИ ДЕЛО ПРЯМО ОТСЮДА.
      //
      // Прежде из карточки нельзя было сделать ничего: строка клиента не
      // имела ни одного обработчика. Связь «дело → клиент» существовала, но
      // только с другой стороны — внутри уже открытого дела, выбором «за кем
      // оно». То есть завести дело для клиента, которого только что записал,
      // было нельзя: надо было пойти в общий разговор, написать что-то,
      // дождаться дела и вернуться назвать клиента.
      //
      // Дело здесь заводится ДВУМЯ вызовами, а не одним, и это не небрежность:
      // CaseCreate клиента не принимает (shared/schemas/cases.py), а
      // PUT /cases/{id}/client сверяет, что карточка лежит в ландшафте
      // владельца дела. Порядок обратный сломал бы проверку.
      var завести = el("button", "newcase", "Завести дело");
      завести.type = "button";
      завести.addEventListener("click", function () {
        заводитьДелоКлиенту(c, завести);
      });
      row.appendChild(завести);
      rows.appendChild(row);
      (поКлиенту[c.party_id] || []).forEach(function (d) {
        var line = el("div", "ccase");
        line.appendChild(el("span", "", d.title || "без названия"));
        line.appendChild(el("span", "cstate", d.state));
        rows.appendChild(line);
      });
    });

    if (ничьи.length) {
      var row = el("div", "crow");
      row.appendChild(el("span", "cname", "Клиент не назван"));
      row.appendChild(el("span", "ccnt", ничьи.length + T(" дел")));
      rows.appendChild(row);
      ничьи.forEach(function (d) {
        var line = el("div", "ccase");
        line.appendChild(el("span", "", d.title || "без названия"));
        line.appendChild(el("span", "cstate", d.state));
        rows.appendChild(line);
      });
    }
  }

  /* Завести дело для клиента из картотеки.

     ЗАЧЕМ ЭТО ЗДЕСЬ, А НЕ ТОЛЬКО В ПАНЕЛИ ДЕЛА. Связывать дело с клиентом
     оболочка умела всегда, но только изнутри открытого дела. Обратного хода
     не было ни одного: записав клиента, профессионал видел строку «Имя · дел
     нет» и ничего не мог с ней сделать. Дело приходилось заводить окольно —
     через общий разговор, — а потом возвращаться и называть клиента.

     ПОЧЕМУ НАЗВАНИЕ СПРАШИВАЕТСЯ. Дело без названия показывается обрезанным
     идентификатором, и картотека из десяти таких нечитаема. Имя клиента в
     название не подставляем: у одного доверителя дел бывает несколько, и
     «Иван Л.» трижды в списке — это не название, а путаница.

     НАПРАВЛЕНИЕ ЗДЕСЬ НЕ СТАВИТСЯ, и это стоит знать: CaseCreate его не
     принимает, а ручка маршрута наружу не открыта. Дело заведётся без
     направления, и назначит его первый ход разговора — как и у дела,
     заведённого из общего разговора. */
  async function заводитьДелоКлиенту(карточка, кнопка) {
    var что = window.prompt(
      T("Дело для «") + карточка.display_name + T("» — о чём оно?"));
    if (!что || !что.trim()) return;
    кнопка.disabled = true;
    var rows = document.getElementById("clientrows");
    try {
      var дело = await api("POST", "/cases", { title: что.trim() }, 60000);
      try {
        await api("PUT", "/cases/" + encodeURIComponent(дело.id) + "/client",
                  { party_id: карточка.party_id });
      } catch (e) {
        // Дело ЗАВЕЛОСЬ, а клиент не встал. Молчать нельзя: человек решит,
        // что не вышло ничего, и заведёт второе. Называем оба факта.
        rows.appendChild(el("div", "casenote",
          T("Дело завелось, но клиент к нему не встал: ") + reason(e) +
          T(". Назовите его в самом деле — строкой «за кем оно».")));
      }
      await renderClients();
      await openCase(дело.id);
    } catch (e) {
      rows.appendChild(el("div", "casenote", T("Дело не завелось: ") + reason(e)));
    } finally {
      кнопка.disabled = false;
    }
  }

  (function () {
    var b = document.getElementById("clientadd");
    if (!b) return;
    b.addEventListener("click", async function () {
      // Имя роли стоит ЯРЛЫКОМ, а не дополнением: «Как зовут клиент?»
      // выходило от подстановки именительного падежа в винительную
      // позицию, и у преподавателя читалось «Как зовут ученик?». Роль
      // приходит из пакета в одном падеже, склонять её код не умеет и
      // уметь не должен — значит фраза строится так, чтобы падеж не
      // менялся.
      var имя = window.prompt(
        ((state.practice || {}).client_title || T("Клиент")) + T(": как зовут?"));
      if (!имя || !имя.trim()) return;
      b.disabled = true;
      try {
        await api("POST", "/practice/clients",
                  { domain: (state.practice || {}).domain,
                    kind: (state.practice || {}).kind || "",
                    display_name: имя.trim() });
        await renderClients();
        renderObjects();
      } catch (e) {
        var rows = document.getElementById("clientrows");
        rows.appendChild(el("div", "casenote", T("Клиент не завёлся: ") + reason(e)));
      } finally {
        b.disabled = false;
      }
    });
  })();

  /* ── Календарь: ближайшее ──────────────────────────────────────────

     Показываем ближайшие тридцать дней, а не весь календарь: панель дела
     узкая, и список на год в ней нечитаем. Вид события назван словом и
     отмечен цветом — срок и заседание ведут себя по-разному, и на экране
     это должно быть видно раньше, чем человек прочтёт заголовок. */
  var КОГДА = { hearing: "заседание", deadline: "срок",
                meeting: "встреча", reminder: "напоминание" };

  function когда(iso) {
    var d = new Date(iso);
    if (isNaN(d)) return iso;
    var дни = ["вс", "пн", "вт", "ср", "чт", "пт", "сб"];
    return ("0" + d.getDate()).slice(-2) + "." + ("0" + (d.getMonth() + 1)).slice(-2) +
           " " + дни[d.getDay()] + " " + ("0" + d.getHours()).slice(-2) +
           ":" + ("0" + d.getMinutes()).slice(-2);
  }

  async function renderCalendar() {
    var box = document.getElementById("calendar");
    if (!box || !state.principal || !state.token) return;
    var rows = document.getElementById("calrows");
    var head = document.getElementById("calhead");
    var события;
    try {
      события = (await api("GET", "/calendar?days=30&past=1")).events || [];
    } catch (e) {
      box.hidden = true;
      return;
    }
    // Календарь есть у всех, но раздел — принадлежность кабинета: у человека
    // без практики он пуст всегда, и пустая коробка на экране только мешает.
    if (!события.length && !state.practice) { box.hidden = true; return; }
    box.hidden = false;
    rows.innerHTML = "";
    head.textContent = T(события.length
      ? T("ближайшее: ") + события.length
      : "ближайшее — ничего не назначено");

    события.forEach(function (e) {
      var row = el("div", "erow " + e.kind);
      row.appendChild(el("span", "ewhen", когда(e.at)));
      var t = el("span", "etitle", e.title);
      row.appendChild(t);
      row.appendChild(el("span", "ekind", КОГДА[e.kind] || e.kind));
      rows.appendChild(row);
      // Основание показываем строкой ниже: по нему видно, откуда взялся срок,
      // и это единственная защита от срока, придуманного из памяти.
      if (e.basis) rows.appendChild(el("div", "ccase", e.basis));
    });
  }

  (function () {
    var b = document.getElementById("calfeed");
    if (!b) return;
    b.addEventListener("click", async function () {
      // Ссылку показываем, а не открываем: адрес ленты И ЕСТЬ ключ, и
      // человек должен понимать, что он копирует, прежде чем вставит это
      // в чужую программу.
      var rows = document.getElementById("calrows");
      try {
        var мои = (await api("GET", "/practice")).practices || [];
        if (!мои.length) return;
        // Лента АКТИВНОГО кабинета, а не первого в списке. Токен и есть ключ:
        // выдать ключ от календаря риелтора тому, кто смотрит кабинет
        // собственника, — это не путаница на экране, это чужая ссылка,
        // уехавшая в чужой телефон.
        var чей = активныйКабинет(мои);
        var url = API + "/calendar/feed/" + чей.ics_token + ".ics";
        var note = el("div", "casenote",
          T("Ссылка на ленту (она же ключ — не пересылайте): ") + url);
        rows.appendChild(note);
      } catch (e) {
        rows.appendChild(el("div", "casenote", T("Ленту не получить: ") + reason(e)));
      }
    });
  })();

  /* ── Расклад: три зоны и створки ───────────────────────────────────

     Секции описаны в разметке по одному разу, а раскладывает их отсюда один
     список. Перекраивать разметку под каждую перестановку значило бы дважды
     отвечать на вопрос «где живёт раздел» — в HTML и в голове, — и однажды
     эти ответы разойдутся.

     СЛЕВА — «что у меня есть»: дела, картотека и настройки, которые
     открывают раз в неделю. СПРАВА — то, чем работают по открытому делу:
     переписка, бумаги, сроки, лента. В ЦЕНТРЕ остаётся разговор.

     Журнал обращений к моделям уехал в настройки намеренно. Он заработал
     своё место — именно им нашли, что один заводила съедал 84% нагрузки две
     недели, — но рядом с делами юриста это шум: расход смотрят раз в день, а
     дела открывают каждую минуту. */
  // Разделы, свёрнутые до первого касания. Список короткий намеренно: всё,
  // что относится к делу, остаётся раскрытым.
  /* Что сложено при первом открытии. «egress» отсюда УБРАН 04.09.2026: это
     две воли человека про то, куда уходит содержимое дела, и спрашиваются они
     В НАЧАЛЕ разговора. Сложенная панель означала, что до вопроса человек не
     доходит вовсе, а после первого хода спрашивать поздно — содержимое уже
     ушло туда, куда его пускали умолчания. */
  var СЛОЖЕНЫ_СНАЧАЛА = ["logins", "effort", "opspanel"];

  var РАСКЛАД = {
    sideleft:  ["caselist", "mkcase",
                // Ландшафт — РЯДОМ С КАРТОТЕКОЙ И ПЕРЕД НЕЙ: это свои объекты,
                // и они есть у всякого, а картотека только у владельца
                // кабинета. Не назвав его здесь, я получил ровно то, о чём
                // предупреждает список: раздел уехал вправо подметанием и
                // встал в конец колонки дела.
                "landscape",
                "clients", "scopes", "practice",
                "pickpage", "leads", "sites", "affil",
                // «Насколько стараться» — сразу за выносом: обе настройки про
                // ОДНО дело и обе решают, чем именно его читают.
                "calendar", "board", "storefront", "logins", "egress", "effort",
                "vaultplace",
                "crpanel", "expanel", "feed", "opspanel",
                // Выплаты, ждущие разрешения. СЛЕВА по тому же доводу, что
                // crpanel и opspanel: это операторская панель про хозяйство
                // площадки, а не про открытое дело. Рядом с ними ей и место.
                "paypanel", "signin"],
    // «Бумаги» и «лента» названы в описании выше, но в самом списке их не
    // было. Раздел, не упомянутый здесь, НЕ переезжает и остаётся в старой
    // панели дела — а она сносится только пустой. Двух забытых разделов
    // хватало, чтобы панель выжила и встала четвёртой зоной во всю ширину
    // под тремя колонками: на экране появлялся короб, которого в раскладке
    // нет. Отсюда же правило на будущее: добавил раздел в разметку — впиши
    // его сюда, иначе он всплывёт внизу сам по себе.
    // Названы ВСЕ до одного. Подметающий цикл ниже остаётся, но становится
    // тем, чем и задуман, — последней преградой, а не способом раскладки.
    sideright: ["where", "scheme", "casebody", "subject", "commission", "paperdraft",
                // Общие таблицы — СРАЗУ ЗА составлением проекта: обе панели
                // про содержимое дела, которое пишет сам человек, а не про
                // разговор и не про купленную работу. Добавлено 13.09.2026
                // по просьбе владельца («Бюджет семьи вдвоём»), см.
                // tests/test_shell_shared_tables.py.
                "sheets",
                // Приёмка — СРАЗУ ЗА поручением и составлением, до состояния
                // прогона: это решение по УЖЕ сделанной работе, и оно двигает
                // деньги. Ниже ленты его пришлось бы искать.
                "acceptwork",
                "runstate", "pending", "artifacts", "threads", "crew", "thrwin"]
  };

  /* ЧТО ЗДЕСЬ ПРОИЗОШЛО 23.08.2026 И ПОЧЕМУ СПИСОК СТАЛ КОРОЧЕ.

     Разбор живого экрана показал: правая колонка — не панель дела, а осадок.
     В ней лежало ДВАДЦАТЬ разделов, и ВОСЕМЬ из них попали туда не по этому
     списку, а подметающим циклом ниже. Раскладка отставала от разметки на 15
     разделов, поэтому каждая новая кнопка садилась справа сама.

     ЧТО УЕХАЛО ВЛЕВО и почему — все пять по одному доводу: это не про
     ОТКРЫТОЕ ДЕЛО, а про человека и его хозяйство.

       calendar   — про неделю человека, а не про это дело; его собственный
                    комментарий в разметке помещает его над картотекой, а
                    картотека слева;
       board      — «мои объявления»: узел ландшафта, показывался ВСЕГДА,
                    даже пустой, среди бумаг открытого дела;
       vaultplace — где лежат ВСЕ бумаги человека, стоял двадцатым в колонке
                    одного дела;
       crpanel    — расход кредитов, операторская панель, родная сестра
                    opspanel, который и так слева;
       mkcase     — форма заведения дела: кнопка её открывает СЛЕВА, а форма
                    открывалась внизу справа, без прокрутки и без фокуса, то
                    есть нажатие выглядело как «ничего не произошло».

     ЧТО СЛИЛОСЬ ОБРАТНО. docs, papers, files лежат в разметке ВНУТРИ короба
     "artifacts" — а прежний список выдёргивал их поимённо и расставлял
     позициями 7–9, оставляя выпотрошенный короб девятнадцатым. Теперь
     переезжает короб целиком, и его пустое состояние словами перестаёт
     врать. "finds" внутри него и так.

     ЧТО ПОДНЯЛОСЬ. commission («что искать» + «поручить агенту») — это
     единственное место правой колонки, где НАЧИНАЕТСЯ работа, а стояло оно
     восемнадцатым из двадцати: ниже бумаг, которые само же и производит, и
     на четырнадцать разделов ниже полосы состояния, которую само включает.

     ЧТО УЕХАЛО ВЛЕВО ЕЩЁ. feed («события») отвечает на тот же вопрос, ради
     которого в шапке стоит колокольчик, и стоял при этом в колонке открытого
     дела. Убрать его вовсе я сперва и хотел — но раздел, не названный в этом
     списке, не исчезает, а уезжает вправо подметанием. Названы теперь ВСЕ до
     одного, и подметание стало тем, чем задумано: последней преградой, а не
     способом раскладки.

     Правая колонка: 20 разделов → 8. Довод целиком — docs/SHELL_REDESIGN.md. */

  function layoutPanes() {
    // Заголовок «Дело» со значком переезжает в правую зону первым: он
    // единственное, что было в старой панели помимо разделов, и оставить
    // его там значило бы оставить на экране пустую коробку с заголовком.
    var правая = document.getElementById("sideright");
    var шапка = document.querySelector("#casepane > h2");
    if (правая && шапка) правая.appendChild(шапка);

    Object.keys(РАСКЛАД).forEach(function (зона) {
      var дом = document.getElementById(зона);
      if (!дом) return;
      РАСКЛАД[зона].forEach(function (id) {
        var узел = document.getElementById(id);
        // Раздела может не быть: разметка живёт своей жизнью, и падать из-за
        // переставленного блока экран не должен.
        if (узел) дом.appendChild(узел);
      });
    });
    // Опустевшую обёртку убираем: коробка без содержимого читается как
    // поломка, а не как «здесь ничего нет».
    // Раздел, забытый в списке выше, НЕ должен создавать четвёртую зону.
    // Так уже случалось дважды: сперва с «бумагами» и «лентой», потом с
    // «чем занят агент» — панель дела не пустела, выживала и вставала
    // полосой во всю ширину под тремя колонками. Комментария оказалось
    // мало, поэтому теперь забытое просто уезжает в правую зону: место
    // может выйти не лучшим, но раскладка остаётся целой.
    var брошенная = document.getElementById("casepane");
    var правая2 = document.getElementById("sideright");
    if (брошенная && правая2) {
      while (брошенная.firstElementChild) {
        правая2.appendChild(брошенная.firstElementChild);
      }
    }

    var старая = document.getElementById("casepane");
    if (старая && !старая.children.length) {
      старая.remove();
      // Кольцо «дело живое» рисовалось вокруг этой панели, и ссылка на неё
      // взята при загрузке — то есть ДО того, как панель отсюда уезжает.
      // Пока в ней оставались забытые разделы, она выживала и кольцо
      // работало; стоило списку разделов стать полным, панель снеслась, а
      // четыре вызова classList.add("live") стали молча делать ничего на
      // отцепленном узле. Знак переезжает на само дело.
      casePane = document.getElementById("casebody") || старая;
    }

    // Складывание отдельных разделов: заголовок работает кнопкой. Вешаем на
    // всю панель одним слушателем — разделы приходят и уходят, а слушатель
    // на каждом однажды остался бы на удалённом узле.
    document.querySelectorAll(".side").forEach(function (панель) {
      панель.addEventListener("click", function (ev) {
        var шапка = ev.target.closest(".caseshead, h3");
        if (!шапка || !панель.contains(шапка)) return;
        // Кнопка внутри шапки («Обновить», «Добавить клиента») — не складывание.
        if (ev.target.closest("button")) return;
        var раздел = шапка.parentElement;
        раздел.classList.toggle("shut");
        сохранить("fixar.shut." + раздел.id, раздел.classList.contains("shut") ? "1" : "0");
      });
    });
    // Что было сложено — таким и остаётся: человек складывает то, чем не
    // пользуется, и заново складывать это каждое утро не должен.
    //
    // Умолчание же зависит от роли раздела. Настройки — входы, вынос данных,
    // служебное — открывают раз в неделю, а место на экране занимают наравне
    // с делами, которые открывают каждую минуту. Свёрнутый раздел никуда не
    // делся: заголовок на месте, и один щелчок его возвращает. Выбор
    // человека сильнее умолчания в обе стороны, поэтому «раскрыто» тоже
    // записывается: пустое значение означает «не выбирал».
    document.querySelectorAll(".side .cases, .side .files, .side .crew").forEach(
      function (раздел) {
        раздел.classList.add("sect");
        if (!раздел.id) return;
        var выбор = localStorage.getItem("fixar.shut." + раздел.id);
        var сложен = выбор === null || выбор === ""
          ? СЛОЖЕНЫ_СНАЧАЛА.indexOf(раздел.id) >= 0
          : выбор === "1";
        if (сложен) раздел.classList.add("shut");
      });
  }

  function сохранить(ключ, значение) {
    try { значение ? localStorage.setItem(ключ, значение) : localStorage.removeItem(ключ); }
    catch (e) { /* приватный режим: складывание просто не переживёт заход */ }
  }

  //: Ширина, ниже которой боковые зоны — выезжающие ящики, а не колонки.
  //: То же число стоит в медиазапросе разметки; разъехаться им нельзя, иначе
  //: стрелка будет открывать то, что уже стоит в потоке.
  var УЗКО = 900;

  function узкий() { return window.innerWidth <= УЗКО; }

  function setupFolds() {
    var зоны = document.getElementById("panes");
    var затемнение = document.getElementById("scrim");
    var створки = {};
    [["foldleft", "nl", "showl", "edgeleft", "\u203a", "\u2039"],
     ["foldright", "nr", "showr", "edgeright", "\u2039", "\u203a"]].forEach(function (t) {
      var кнопка = document.getElementById(t[0]);
      if (!кнопка) return;
      var стрелка = document.getElementById(t[3]);
      // Умолчание зависит от ширины экрана, явный выбор человека — сильнее.
      // Но НА ТЕЛЕФОНЕ ящик всегда начинает закрытым, чем бы дело ни
      // кончилось в прошлый раз: раскрытая зона там лежит поверх разговора
      // во весь экран, и заход, начинающийся с закрытого ею разговора,
      // читается как поломка, а не как память о выборе.
      var выбор = localStorage.getItem("fixar." + t[1]);
      var сложена = узкий() || выбор === null || выбор === ""
        ? true
        : выбор === "1";
      // Первое применение — МОЛЧА. Иначе телефон, где сложено всегда,
      // записал бы «1» поверх выбора, сделанного на широком экране: человек
      // раскрыл зону за столом, открыл с телефона — и за столом она сложена.
      применить(сложена, true);
      кнопка.addEventListener("click", function () { переключить(); });
      if (стрелка) стрелка.addEventListener("click", function () { переключить(); });
      створки[t[1]] = применить;

      function переключить() {
        var складывать = !зоны.classList.contains(t[1]);
        // Два ящика поверх друг друга на телефоне не нужны и не помещаются:
        // открывая один, закрываем второй.
        if (!складывать && узкий()) {
          Object.keys(створки).forEach(function (к) {
            if (к !== t[1]) створки[к](true, false);
          });
        }
        применить(складывать, false);
      }

      function применить(складывать, молча) {
        zonesToggle(зоны, t[1], складывать);
        // На узком экране панели скрыты по умолчанию, и та же кнопка их
        // ПОКАЗЫВАЕТ. Иначе на телефоне она не делала бы ничего видимого.
        zonesToggle(зоны, t[2], !складывать);
        кнопка.setAttribute("aria-pressed", складывать ? "true" : "false");
        if (стрелка) {
          стрелка.setAttribute("aria-expanded", складывать ? "false" : "true");
          // Стрелка разворачивается: закрытая обещает «выеду отсюда»,
          // открытая — «задвинусь обратно». Одна кнопка, два обещания.
          стрелка.textContent = T(складывать ? t[4] : t[5]);
        }
        // Записываем и раскрытое состояние тоже: пустое значение означало бы
        // «человек не выбирал», и панель схлопнулась бы снова.
        //
        // НО НЕ С ТЕЛЕФОНА. Там это не выбор, а ящик: он всегда начинает
        // закрытым и закрывается сам — касанием мимо, клавишей выхода,
        // сужением окна. Записывать это значило бы стирать выбор, сделанный
        // за столом, каждым таким закрытием. Поймано живой проверкой:
        // раскрытые на широком экране зоны после сужения окна дали в
        // хранилище «сложены обе», и за столом они складывались.
        if (!молча && !узкий()) сохранить("fixar." + t[1], складывать ? "1" : "0");
        затемнить();
      }
    });

    function затемнить() {
      var открыт = узкий() &&
        (зоны.classList.contains("showl") || зоны.classList.contains("showr"));
      document.body.classList.toggle("drawer", открыт);
      if (!затемнение) return;
      if (открыт) {
        затемнение.hidden = false;
        // Перекомпоновка между снятием hidden и классом: без неё перехода
        // нет — браузер не анимирует то, что появилось и окрасилось разом.
        //
        // Именно перекомпоновка, а не requestAnimationFrame: кадры во
        // ВКЛАДКЕ НА ФОНЕ не идут вовсе, и затемнение осталось бы прозрачным
        // до возвращения на вкладку. Поймано живой проверкой — ящик выехал,
        // а под ним ничего.
        void затемнение.offsetWidth;
        затемнение.classList.add("on");
      } else {
        затемнение.classList.remove("on");
        затемнение.hidden = true;
      }
    }

    function закрыть_всё() {
      Object.keys(створки).forEach(function (к) { створки[к](true, false); });
    }
    if (затемнение) затемнение.addEventListener("click", закрыть_всё);
    // Клавиша выхода закрывает ящик — тем же движением, что и любое другое
    // наложение в оболочке.
    document.addEventListener("keydown", function (e) {
      if (e.key !== "Escape" || !document.body.classList.contains("drawer")) return;
      закрыть_всё();
    });
    // Пересечение порога ширины. Двумя движениями сразу:
    //
    // * стало УЗКО — закрываем оба ящика. На столе зоны стоят колонками
    //   рядом и раскрытыми обеими никому не мешают; сузив окно (или
    //   повернув телефон), человек получил бы их обе ПОВЕРХ разговора, не
    //   попросив об этом. Телефон всегда начинает с закрытых — переход
    //   через порог тот же случай, что и заход;
    // * стало ШИРОКО — снимаем замок прокрутки и затемнение: ящиков там
    //   нет, а оставленный замок запер бы страницу насовсем.
    var было_узко = узкий();
    window.addEventListener("resize", function () {
      var стало_узко = узкий();
      if (стало_узко && !было_узко) закрыть_всё();
      было_узко = стало_узко;
      затемнить();
    });
  }

  function zonesToggle(узел, класс, вкл) {
    if (вкл) узел.classList.add(класс); else узел.classList.remove(класс);
  }

  /* ── Переписка ─────────────────────────────────────────────────────

     Служба умела её с самого начала: нити по делам и прямые приходят одним
     списком, потому что человек ищет «где мне ответили», а не «в каком из
     двух разделов». В оболочке её не было ни разу — до сих пор о сообщении
     можно было узнать только из уведомления, а прочитать негде.

     Непрочитанное показано числом у нити: список без него заставляет
     открывать каждую, чтобы понять, где новое. */
  async function renderThreads() {
    var box = document.getElementById("threads");
    var rows = document.getElementById("threadrows");
    var head = document.getElementById("threadshead");
    if (!box || !state.principal) { if (box) box.hidden = true; return; }
    var нити;
    try {
      нити = (await api("GET", "/principals/" + encodeURIComponent(state.principal) +
                        "/threads")).threads || [];
    } catch (e) {
      box.hidden = true;
      return;
    }
    // Внутри открытого дела показываем ЕГО переписку, а не всю подряд.
    // Список без отбора отвечал на вопрос «где мне вообще писали», а человек
    // в деле спрашивает «что здесь», и чужие нити тут — шум.
    var видимые = state.caseId
      ? нити.filter(function (t) { return t.case_id === state.caseId; })
      : нити;
    // Кнопка «написать участникам» нужна и там, где нити ещё нет: до
    // 21.08.2026 создать её из оболочки было нечем вовсе, поэтому список
    // всегда оставался пуст, а пустой список прятал сам себя. Круг
    // размыкается здесь.
    if (!видимые.length && !state.caseId) { box.hidden = true; return; }
    box.hidden = false;
    var новых = видимые.reduce(function (s, t) { return s + (t.unread || 0); }, 0);
    head.textContent = T(новых ? T("переписка · новых ") + новых : "переписка");
    rows.innerHTML = "";
    видимые.forEach(function (t) {
      var row = el("div", "thr");
      row.appendChild(el("span", "tt", t.title || t.case_title || t.subject ||
                                       "Переписка"));
      if (t.unread) row.appendChild(el("span", "un", String(t.unread)));
      // ИМЯ ПОЛЯ РОВНО ТАКОЕ, КАКОЕ ОТДАЁТ СЛУЖБА. Здесь стояло `t.id`, а
      // служба кладёт `thread_id` (threads.py: "thread_id": r["id"]). Клик
      // уходил в GET /threads/undefined, то есть открыть нить было нельзя
      // никак — и незаметно, потому что список всё равно всегда был пуст.
      row.addEventListener("click", function () { openThread(t.thread_id); });
      rows.appendChild(row);
    });
    if (state.caseId) {
      var есть = видимые.length;
      var кн = el("div", "thr");
      var b = el("span", "tt", есть ? "Открыть переписку по делу"
                                    : "Написать участникам дела");
      кн.appendChild(b);
      кн.addEventListener("click", function () { startCaseThread(); });
      rows.appendChild(кн);
    }
  }

  /* Завести переписку по открытому делу. Повторный вызов нити не плодит —
     служба возвращает уже идущую (threads.py: "переписка по этому делу уже
     идёт"), поэтому кнопка безопасна при любом числе нажатий. */
  async function startCaseThread() {
    if (!state.caseId) return;
    var r;
    try {
      r = await api("POST", "/threads", { case_id: state.caseId });
    } catch (e) {
      сорвалось(T("Переписка не завелась: "), e);
      return;
    }
    await renderThreads();
    await openThread(r.thread_id);
  }

  /* ── Окно переписки ────────────────────────────────────────────────

     ОТДЕЛЬНОЕ ОТ ЛЕНТЫ РАЗГОВОРА. Прежний замысел был обратный — «у человека
     уже есть место, где он читает и пишет», — и он неверен: в общей ленте
     не видно, кому уходит написанное. Разговор с агентом и письмо живому
     участнику стоят разного, и складывать их в одну ленту значит утверждать,
     что не стоят. */

  var нитьОткрыта = null;

  function thrEl(id) { return document.getElementById(id); }

  function closeThread() {
    нитьОткрыта = null;
    var w = thrEl("thrwin");
    if (w) w.hidden = true;
  }

  async function openThread(id) {
    if (!id) {
      say("bot", "Ф", "Эта переписка без адреса — открыть нечего.");
      return;
    }
    var окно = thrEl("thrwin"), лента = thrEl("thrlog"), шапка = thrEl("thrtitle");
    if (!окно || !лента) return;
    var нить;
    try {
      нить = await api("GET", "/threads/" + encodeURIComponent(id));
    } catch (e) {
      сорвалось(T("Переписка не открылась: "), e);
      return;
    }
    нитьОткрыта = id;
    окно.hidden = false;
    шапка.textContent = T(нить.subject || нить.case_title || "Переписка участников");
    лента.innerHTML = "";
    var сообщения = нить.messages || [];
    if (!сообщения.length) {
      лента.appendChild(el("div", "thrnote",
        "Пока пусто. Напишите первым — увидят все участники дела."));
    }
    сообщения.forEach(function (m) { thrDraw(m); });
    лента.scrollTop = лента.scrollHeight;
    var последнее = сообщения.slice(-1)[0];
    if (последнее) {
      // Прочитанное отмечаем ПОСЛЕ показа: отметить и не показать — это
      // потерянное сообщение, о котором никто уже не узнает.
      try {
        await api("POST", "/threads/" + encodeURIComponent(id) + "/read",
                  { up_to: последнее.seq });
        await renderThreads();
      } catch (e) { /* отметка не критична: прочитано глазами */ }
    }
    var поле = thrEl("thrinput");
    if (поле) поле.focus();
  }

  /* Одно сообщение в окне. Автора подписываем ВСЕГДА, включая своё: лента,
     где подписаны только чужие, читается как «остальное сказал я», а в деле
     участников больше двух. */
  function thrDraw(m) {
    var лента = thrEl("thrlog");
    if (!лента) return;
    var своё = m.author_id === state.principal;
    var стр = el("div", "thrmsg" + (своё ? " mine" : ""));
    стр.appendChild(el("span", "thrwho", своё ? "Вы" : (m.author_name ||
                                                        m.author_id || "участник")));
    var тело = el("div", "thrbody");
    // Текст ставим как ТЕКСТ, а не разметкой: сюда пишет другой человек, и
    // его слова не должны превращаться в узлы страницы.
    тело.textContent = T(m.retracted_at ? "сообщение отозвано" : (m.body || ""));
    стр.appendChild(тело);
    лента.appendChild(стр);
  }

  /* ── Завести дело руками ───────────────────────────────────────────

     Дело до сих пор появлялось единственным способом: разговор предлагал,
     человек соглашался. Когда человек УЖЕ знает, что ему нужно, объяснять
     это разговору, чтобы тот догадался, дольше, чем заполнить четыре поля.

     Маршрут POST /cases открыт в двери давно и никем не звался. Ни одной
     правки на сервере эта форма не потребовала, кроме одной: список полей
     шаблона (GET /domains/{}/case-templates) наружу открыт не был, а без него
     форма не может нарисовать поля — и отправка вернула бы 422, которого
     человек не поймёт. */

  var мкШаблоны = [];

  function мк(id) { return document.getElementById(id); }

  function closeMake() {
    var b = мк("mkcase");
    if (b) b.hidden = true;
  }

  async function openMake() {
    var короб = мк("mkcase"), напр = мк("mkdomain");
    if (!короб || !напр) return;
    короб.hidden = false;
    if (!напр.options.length) {
      var паки = [];
      try {
        паки = ((await api("GET", "/packs")) || {}).packs || [];
      } catch (e) {
        мкСказать(T("Список направлений не пришёл: ") + reason(e) +
                  T(". Дело можно завести разговором."));
        return;
      }
      // Направления, у которых нет ни одного шаблона, в список не кладём:
      // выбрать такое значит упереться в пустой второй список и не понять,
      // почему.
      паки.filter(function (p) {
        return (p.case_templates || []).length;
      }).forEach(function (p) {
        var o = el("option", "", p.title || p.id);
        o.value = p.id;
        напр.appendChild(o);
      });
      if (!напр.options.length) {
        мкСказать("Ни в одном направлении нет объявленных видов дел.");
        return;
      }
      напр.addEventListener("change", мкШаблоныНаправления);
    }
    // Направление угадываем по открытому делу: чаще всего заводят соседнее.
    if (state.domain) напр.value = state.domain;
    await мкШаблоныНаправления();
  }

  function мкСказать(текст) {
    var n = мк("mknote");
    if (!n) return;
    n.hidden = !текст;
    n.textContent = T(текст || "");
  }

  async function мкШаблоныНаправления() {
    var напр = мк("mkdomain"), сп = мк("mktemplate");
    if (!напр || !сп || !напр.value) return;
    сп.innerHTML = "";
    мкСказать("");
    try {
      мкШаблоны = ((await api("GET", "/domains/" +
        encodeURIComponent(напр.value) + "/case-templates")) || {}).templates || [];
    } catch (e) {
      мкШаблоны = [];
      мкСказать(T("Виды дел этого направления не пришли: ") + reason(e));
      return;
    }
    мкШаблоны.forEach(function (t, i) {
      var o = el("option", "", t.title || t.id);
      o.value = String(i);
      сп.appendChild(o);
    });
    сп.onchange = мкПоля;
    мкПоля();
  }

  /* Поля шаблона рисуем по его описанию. Захардкодить их значило бы отменить
     обещание «ни строки кода на новое направление»: пакет объявляет поля, и
     оболочка обязана читать объявление, а не помнить его. */
  /* Поле анкеты рисуется ПО ВИДУ, объявленному в шаблоне.

     Здесь стояло `f.type` и `f.hint` — полей с такими именами схема не
     отдаёт вовсе (FieldSpec: kind, options, pattern_hint, unit). Оба
     читались как undefined, и это не давало ошибки: всё рисовалось простой
     строкой, а подсказка не показывалась никогда.

     Молчаливым дефект не был — он был ОТКАЗЫВАЮЩИМ. validate_brief на
     сервере проверяет вид строго (landscape.py:745-777): number и money
     обязаны быть числом, bool — булевым, enum — из списка, date — ISO 8601.
     Оболочка же складывала в brief всё подряд строкой. Значит любое
     нетекстовое поле означало 422 при заведении дела: в паках таких 14 из
     69, в девяти шаблонах из двадцати трёх.

     Виды перечислены ПОЛНОСТЬЮ, включая geo, которого сегодня нет ни в
     одном паке. Пропустить его значило бы оставить ту же мину следующему,
     кто его объявит: незнакомый вид молча стал бы текстовой строкой. */
  function мкПолеПоВиду(f) {
    var вид = String(f.kind || "text");
    var поле;
    if (вид === "enum") {
      поле = el("select");
      // Пустой первый вариант нужен даже обязательному полю: без него
      // первый вариант списка считается выбранным, хотя человек его не
      // выбирал, и «обязательное» проходит само собой.
      var пусто = el("option", null, f.required ? "— выберите —" : "— не указано —");
      пусто.value = "";
      поле.appendChild(пусто);
      (f.options || []).forEach(function (o) {
        var в = el("option", null, String(o));
        в.value = String(o);
        поле.appendChild(в);
      });
    } else if (вид === "bool") {
      поле = el("input");
      поле.type = "checkbox";
    } else if (вид === "date") {
      поле = el("input");
      поле.type = "date";        // браузер отдаёт ГГГГ-ММ-ДД — это и есть ISO
    } else if (вид === "number" || вид === "money") {
      поле = el("input");
      поле.type = "number";
      поле.step = вид === "money" ? "0.01" : "any";
      поле.inputMode = "decimal";
    } else if (вид === "geo") {
      поле = el("input");
      поле.placeholder = "широта, долгота";
    } else {
      поле = el("textarea");
      поле.rows = 2;
    }
    return поле;
  }

  function мкПоля() {
    var сп = мк("mktemplate"), место = мк("mkfields");
    if (!место) return;
    место.innerHTML = "";
    var t = мкШаблоны[Number(сп && сп.value) || 0];
    if (!t) return;
    (t.intake || []).forEach(function (f) {
      var вид = String(f.kind || "text");
      var row = el("label", "mkrow" + (вид === "bool" ? " mkflag" : ""));
      var подпись = f.title || f.key;
      if (f.unit) подпись += ", " + f.unit;
      // Обязательность показываем звёздочкой, а не молчаливым отказом при
      // отправке: узнать о требовании из сообщения об ошибке — узнать поздно.
      row.appendChild(el("span", "", подпись + (f.required ? " *" : "")));
      var поле = мкПолеПоВиду(f);
      поле.id = "mkf_" + f.key;
      поле.setAttribute("data-key", f.key);
      поле.setAttribute("data-kind", вид);
      // required у флажка означал бы «обязан быть включён» — а «нет» это
      // такой же ответ, как «да», и сервер его принимает (empty(False)
      // ложно). Ставим только там, где пусто действительно значит пусто.
      if (f.required && вид !== "bool") поле.required = true;
      if (f.pattern_hint) поле.placeholder = T(f.pattern_hint);
      row.appendChild(поле);
      место.appendChild(row);
    });
  }

  /* Значение поля в том виде, какого ждёт сервер. Возвращает undefined,
     когда отвечать нечем: пустое поле в brief не кладём вовсе, иначе
     empty() на сервере отличит «не заполнил» от «заполнил пустым», а
     человек этой разницы не задумывал. */
  function мкЗначение(f) {
    var поле = мк("mkf_" + f.key);
    if (!поле) return undefined;
    var вид = String(f.kind || "text");
    if (вид === "bool") return !!поле.checked;
    var сырое = (поле.value || "").trim();
    if (!сырое) return undefined;
    if (вид === "number" || вид === "money") {
      var ч = Number(сырое.replace(",", ".").replace(/\s/g, ""));
      return isFinite(ч) ? ч : undefined;
    }
    if (вид === "geo") {
      var части = сырое.split(/[,;\s]+/).filter(Boolean).map(Number);
      if (части.length !== 2 || !isFinite(части[0]) || !isFinite(части[1])) return undefined;
      return { lat: части[0], lon: части[1] };
    }
    return сырое;
  }

  async function мкЗавести(ev) {
    if (ev) ev.preventDefault();
    var сп = мк("mktemplate"), кнопка = мк("mkgo");
    var t = мкШаблоны[Number(сп && сп.value) || 0];
    if (!t) { мкСказать("Вид дела не выбран."); return; }
    var brief = {};
    var не_хватает = [];
    (t.intake || []).forEach(function (f) {
      var v = мкЗначение(f);
      if (v !== undefined) brief[f.key] = v;
      else if (f.required) не_хватает.push(f.title || f.key);
    });
    if (не_хватает.length) {
      // Называем ЧТО не заполнено. «Заполните обязательные поля» заставляет
      // искать их глазами, а звёздочка к этому моменту уже пролистана.
      мкСказать(T("Не заполнено: ") + не_хватает.join(", ") + ".");
      return;
    }
    var тело = {
      title: ((мк("mktitle") || {}).value || "").trim() || (t.title || "Дело"),
      side: (мк("mkside") || {}).value || "need_help",
      template_id: t.id,
      template_version: t.version
    };
    // goal у дела своё поле, а не часть брифа: шаблон может спрашивать его
    // под своим ключом, и тогда оно уезжает в оба места — так дело показывает
    // цель в карточке, не теряя её из брифа.
    if (brief.goal) тело.goal = String(brief.goal).slice(0, 2000);
    if (Object.keys(brief).length) тело.brief = brief;
    if (кнопка) кнопка.disabled = true;
    мкСказать("");
    var дело;
    try {
      дело = await api("POST", "/cases", тело);
    } catch (e) {
      мкСказать(T("Дело не завелось: ") + reason(e));
      return;
    } finally {
      if (кнопка) кнопка.disabled = false;
    }
    closeMake();
    await renderCases();
    await openCase(дело.id);
  }

  function setupMakeCase() {
    var закрыть = мк("mkclose"), форма = мк("mkform");
    if (закрыть) закрыть.addEventListener("click", closeMake);
    if (форма) форма.addEventListener("submit", мкЗавести);
  }

  function setupThreadWindow() {
    var кнопка = thrEl("thrsendbtn"), поле = thrEl("thrinput"),
        закрыть = thrEl("thrclose");
    if (закрыть) закрыть.addEventListener("click", closeThread);
    if (кнопка) кнопка.addEventListener("click", thrSend);
    if (!поле) return;
    поле.addEventListener("keydown", function (e) {
      // Enter отправляет, Shift+Enter переносит строку — как в поле разговора
      // рядом. Разные правила у двух полей на одном экране человек не
      // запоминает, он на них попадается.
      if (e.key === "Enter" && !e.shiftKey) { e.preventDefault(); thrSend(); }
    });
  }

  async function thrSend() {
    var поле = thrEl("thrinput"), кнопка = thrEl("thrsendbtn");
    if (!поле || !нитьОткрыта) return;
    var текст = (поле.value || "").trim();
    if (!текст) return;
    if (кнопка) кнопка.disabled = true;
    try {
      await api("POST", "/threads/" + encodeURIComponent(нитьОткрыта) +
                        "/messages", { body: текст });
      поле.value = "";
      // Перечитываем нить целиком, а не дорисовываем своё: пока мы печатали,
      // мог написать кто-то ещё, и дорисовка показала бы разговор с дырой.
      await openThread(нитьОткрыта);
    } catch (e) {
      сорвалось(T("Сообщение не ушло: "), e, T(". Текст остался в поле."));
    } finally {
      if (кнопка) кнопка.disabled = false;
    }
  }

  /* ── Лента кабинета ────────────────────────────────────────────────

     Отвечает на один вопрос: что изменилось, пока меня не было. Поэтому
     здесь только то, на что можно ответить действием, — сервер отбирает
     виды событий поимённо, а оболочка их не перетолковывает: слово для
     человека приходит вместе с событием, и второй словарь здесь разошёлся
     бы с первым на первом же пополнении. */
  async function renderFeed() {
    var box = document.getElementById("feed");
    var rows = document.getElementById("feedrows");
    var head = document.getElementById("feedhead");
    if (!box || !state.principal) { if (box) box.hidden = true; return; }
    var события;
    try {
      события = (await api("GET", "/practice/" +
                           encodeURIComponent(state.principal) + "/feed")).events || [];
    } catch (e) {
      // Ленты нет у того, кто не ведёт дел, и это не поломка.
      box.hidden = true;
      return;
    }
    if (!события.length) { box.hidden = true; return; }
    box.hidden = false;
    head.textContent = T("события");
    rows.innerHTML = "";
    события.slice(0, 30).forEach(function (e) {
      var row = el("div", "feed1");
      var что = el("span", "fw", e.what);
      row.appendChild(что);
      if (e.by_agent) row.appendChild(el("span", "fa", "агент"));
      row.appendChild(document.createElement("br"));
      row.appendChild(el("span", "fc",
        (e.title ? e.title + " · " : "") + e.case_title + " · " + when(e.at)));
      // Событие — повод открыть дело, поэтому оно и открывает дело.
      row.style.cursor = "pointer";
      row.addEventListener("click", function () { openCase(e.case_id); });
      rows.appendChild(row);
    });
  }

  (function () {
    var b = document.getElementById("feedrefresh");
    if (b) b.addEventListener("click", function () { renderFeed(); });
  })();

  /* Расклад применяется СРАЗУ, не дожидаясь связи. Это структура экрана, а
     не данные: когда служба не отвечает, человек всё равно должен видеть
     собранный интерфейс, а не рассыпанные коробки. Первая версия вызывала
     расклад внутри пуска — и при недоступной службе он не применялся вовсе;
     поймано живой проверкой в браузере. */
  layoutPanes();
  setupFolds();

  function setupMail() {
    var form = document.getElementById("bymail");
    var note = document.getElementById("signnote");
    var field = document.getElementById("email");
    var stage = "request";
    form.addEventListener("submit", async function (e) {
      e.preventDefault();
      note.hidden = false;
      try {
        if (stage === "request") {
          await api("POST", "/auth/email/request",
                    { email: field.value.trim(), anon_token: state.token || "" });
          // Ответ одинаков для существующей и несуществующей почты — служба
          // намеренно не говорит, зарегистрирован ли человек. Повторяем это
          // и здесь, а не выдумываем «письмо отправлено».
          note.textContent = T("Если такая почта принимает письма, код придёт. " +
            "Введите его тем же полем.");
          state.mail = field.value.trim();
          field.value = "";
          field.type = "text";
          field.placeholder = T("Код из письма");
          field.autocomplete = "one-time-code";
          stage = "verify";
        } else {
          var r = await api("POST", "/auth/email/verify",
                            { email: state.mail, code: field.value.trim() });
          // Токен обязательно перекладываем: при переносе дел прежняя
          // привязка погашена, и старый токен в браузере уже мёртв.
          if (r.token) {
            state.token = r.token;
            try { localStorage.setItem(KEY, r.token); } catch (e3) { /* приватный режим */ }
          }
          if (r.principal_id) state.principal = r.principal_id;
          note.textContent = T(T("Вход выполнен. Дело осталось вашим") +
            (r.cases_moved ? T(", перенесено дел: ") + r.cases_moved : "") + ".");
          document.getElementById("signin").hidden = true;
          await refreshWho();
          await afterSignin();
        }
      } catch (e2) {
        note.textContent = T(T("Не получилось: ") + reason(e2));
      }
    });
  }

  /* Вход по телефону — та же двухшаговая форма, что и почта, и намеренно
     отдельная от неё: телефон и почта это два канала одного субъекта, а не
     одно поле, в котором мы угадываем, что нам ввели.

     Формы на экране не будет, пока служба не скажет, что СМС настроены.
     Ручки /auth/phone/* на проде есть и работают, но отправка тёмная: в
     окружении не задан IDIGITAL_API_KEY, и /auth/providers честно отвечает
     phone:false. Показать форму раньше значило бы обещать код, который никуда
     не уйдёт. */
  function setupPhone() {
    var form = document.getElementById("byphone");
    var note = document.getElementById("signnote");
    var inp = document.getElementById("phone");
    var stage = "request";

    form.addEventListener("submit", async function (e) {
      e.preventDefault();
      note.hidden = false;
      try {
        if (stage === "request") {
          var сел = document.getElementById("phonechan");
          var sent = await api("POST", "/auth/phone/request",
                               { phone: inp.value.trim(),
                                 anon_token: state.token || "",
                                 channel: (сел && !сел.hidden) ? сел.value : "" });
          state.phone = inp.value.trim();
          // Ответ одинаков для известного и неизвестного номера — как у
          // почты: иначе форма входа становится способом проверить, есть ли
          // тут такой человек.
          var чем = (sent.channel_title || "").trim();
          note.textContent = T(T("Если такой номер принимает ") +
            (чем || T("сообщения")) + T(", код придёт. Введите его тем же полем.") +
            // Про несостоявшуюся отправку говорим прямо: молчание выглядит
            // как «СМС в пути», и человек будет ждать того, чего не будет.
            (sent.delivery && sent.delivery !== "ok"
              ? T(" Служба сообщила о доставке: ") + sent.delivery + "." : ""));
          inp.value = "";
          inp.type = "text";
          inp.placeholder = T("Код из сообщения");
          inp.autocomplete = "one-time-code";
          stage = "verify";
        } else {
          var r = await api("POST", "/auth/phone/verify",
                            { phone: state.phone, code: inp.value.trim() });
          // Та же тонкость, что и у почты: перенос дел гасит анонимную
          // привязку, и без нового токена вход обернулся бы выходом.
          if (r.token) {
            state.token = r.token;
            try { localStorage.setItem(KEY, r.token); } catch (e3) { /* приватный режим */ }
          }
          if (r.principal_id) state.principal = r.principal_id;
          note.textContent = T(T("Вход выполнен. Дело осталось вашим") +
            (r.cases_moved ? T(", перенесено дел: ") + r.cases_moved : "") + ".");
          document.getElementById("signin").hidden = true;
          await refreshWho();
          await afterSignin();
        }
      } catch (e2) {
        note.textContent = T(e2.status === 429 ? tooOften(e2)
                                             : T("Не получилось: ") + reason(e2));
      }
    });
  }

  /* ── Вход Телеграмом ───────────────────────────────────────────────

     ДВА ХОДА В ЧАТЕ, И ЭТО НЕ НЕДОДЕЛКА. Первый — код: он доказывает, что
     чат тот. Второй — «да»: оно доказывает, что человек этого хотел. Убери
     второй, и довольно прислать кому угодно ссылку: он её откроет, а сессию
     получит тот, кто прислал.

     Пара слов — то, чем человек это ловит. Она стоит на этом экране и её же
     показывает бот; не совпало — входит не он. */

  var TG_ОПРОС_МС = 2000;
  var tgОпрос = null;

  function tgСтоп() {
    if (tgОпрос) { clearTimeout(tgОпрос); tgОпрос = null; }
  }

  function wireTelegram() {
    var кнопка = document.getElementById("tggo");
    var ждём = document.getElementById("tgwait");
    var note = document.getElementById("signnote");
    if (!кнопка) return;

    кнопка.addEventListener("click", async function () {
      tgСтоп();
      note.hidden = false;
      note.textContent = T("Готовлю вход…");
      var начато;
      try {
        начато = await api("POST", "/auth/telegram/start", {});
      } catch (e) {
        note.textContent = T(e.status === 429 ? tooOften(e)
                                              : T("Не получилось: ") + reason(e));
        return;
      }

      document.getElementById("tgphrase").textContent = начато.phrase || "";
      document.getElementById("tgcode").textContent = начато.code || "";
      var ссылка = document.getElementById("tglink");
      // Ссылки может не быть: имя бота спрашивается у Telegram, и он мог не
      // ответить. Тогда остаётся код руками — это рабочий путь, а не отказ.
      ссылка.hidden = !начато.deep_link;
      if (начато.deep_link) ссылка.href = начато.deep_link;
      ждём.hidden = false;
      note.textContent = T("Отправьте код боту и подтвердите вход в чате.");

      // Собственный токен уезжает с человеком: разговор, начатый до входа,
      // принадлежит ему с первого сообщения.
      var анон = state.token || "";
      var тик = async function () {
        tgОпрос = null;
        var r;
        try {
          r = await api("POST", "/auth/telegram/poll", {
            request_id: начато.request_id, code: начато.code, anon_token: анон
          });
        } catch (e) {
          // 410 — заявка истекла или уже использована. Это конец опроса, а
          // не сбой связи: продолжать значит долбить дверь, которой нет.
          ждём.hidden = true;
          note.textContent = e.status === 410
            ? T("Заявка на вход истекла. Начните заново.")
            : T("Не получилось: ") + reason(e);
          return;
        }
        if (r.waiting) { tgОпрос = setTimeout(тик, TG_ОПРОС_МС); return; }

        ждём.hidden = true;
        if (r.state === "refused") {
          note.textContent = T("Вход отклонён в чате.");
          return;
        }
        if (r.token) {
          state.token = r.token;
          try { localStorage.setItem(KEY, r.token); } catch (e2) { /* приватный режим */ }
        }
        if (r.principal_id) state.principal = r.principal_id;
        note.textContent = T(T("Вход выполнен. Дело осталось вашим") +
          (r.cases_moved ? T(", перенесено дел: ") + r.cases_moved : "") + ".");
        document.getElementById("signin").hidden = true;
        await refreshWho();
        await afterSignin();
      };
      tgОпрос = setTimeout(тик, TG_ОПРОС_МС);
    });
  }

  /* Привязать Телеграм к УЖЕ ОТКРЫТОЙ записи. Зеркало входа выше, и стороны
     доказательства у них противоположные: там чат известен и согласие даёт
     владелец чата, здесь известна запись и согласие даёт её владелец — то
     есть здесь, на сайте, после того как бот увидел код.

     Согласие спрашивается с НАЗВАНИЕМ ЧАТА: без него человек подтверждает
     «какой-то чат», а подтверждать он должен свой. */

  async function linkTelegram(куда) {
    // КУДА ПИСАТЬ — ДОВОД, А НЕ ДОГАДКА. Списков входов в оболочке два, и
    // зашитый `#mepanel` означал бы, что из второго кнопка нажимается, а
    // ответ уходит в невидимое место.
    var панель = куда || document.getElementById("mepanel");
    var note = document.getElementById("signnote");
    var строка = el("div", "sub", T("Готовлю привязку…"));
    панель.appendChild(строка);

    var начато;
    try {
      начато = await api("POST", "/link/telegram/start", {});
    } catch (e) {
      // 409 — чат уже привязан к другой записи. Это САМЫЙ ЧАСТЫЙ случай у
      // того, кто пришёл двумя дверями, и молчаливое «не получилось» тут
      // бесполезно: человек не догадается, что делать.
      строка.textContent = e.status === 409
        ? T("Телеграм уже привязан к другой записи. Откройте бота, отправьте "
            + "ему /stop — он отвяжет чат, — и повторите здесь.")
        : T("Не получилось: ") + reason(e);
      return;
    }

    строка.textContent = "";
    строка.appendChild(document.createTextNode(
      T("Отправьте боту код ") + (начато.code || "") + T(". ")));
    if (начато.deep_link) {
      var a = el("a", "send", T("Открыть бота"));
      a.href = начато.deep_link;
      a.target = "_blank";
      a.rel = "noopener";
      строка.appendChild(a);
    }

    var ждём = el("div", "sub", T("Жду код от бота…"));
    панель.appendChild(ждём);

    var до = Date.now() + 6 * 60000;
    var тик = async function () {
      if (Date.now() > до) {
        ждём.textContent = T("Код истёк. Начните привязку заново.");
        return;
      }
      var r;
      try {
        r = await api("GET", "/link/telegram/pending/" + state.principal);
      } catch (e) { setTimeout(тик, 2500); return; }
      if (r.linked) { ждём.textContent = T("Телеграм привязан."); return; }
      var ждут = r.pending || [];
      if (!ждут.length) { setTimeout(тик, 2500); return; }

      ждём.textContent = "";
      ждут.forEach(function (з) {
        var row = el("div", "way");
        // НАЗВАНИЕ ЧАТА, А НЕ ЕГО НОМЕР: по названию человек узнаёт свой,
        // по номеру — нет. Номер служба наружу и не отдаёт.
        row.appendChild(el("span", "wn", T("Чат: ") + (з.chat || "")));
        var да = el("button", "addone", T("Это мой"));
        да.type = "button";
        да.addEventListener("click", async function () {
          try {
            await api("POST", "/link/telegram/decide",
                      { request_id: з.request_id, agree: true });
            ждём.textContent = T("Телеграм привязан.");
            await refreshWho();
            // Список перерисовывается целиком: строка сама станет
            // «привязан», и это лучшее подтверждение, чем надпись рядом с
            // кнопкой, которая всё ещё предлагает привязать.
            renderLogins();
          } catch (e) {
            ждём.textContent = T("Не получилось: ") + reason(e);
          }
        });
        var нет = el("button", "addone", T("Не мой"));
        нет.type = "button";
        нет.addEventListener("click", async function () {
          // Отказ — это ОТВЕТ, а не молчание: он оставляет след замеченной
          // попытки чужой привязки, которого «просто не подтвердил» не даёт.
          try {
            await api("POST", "/link/telegram/decide",
                      { request_id: з.request_id, agree: false });
            ждём.textContent = T("Отклонено.");
          } catch (e) {
            ждём.textContent = T("Не получилось: ") + reason(e);
          }
        });
        row.appendChild(да);
        row.appendChild(нет);
        ждём.appendChild(row);
      });
    };
    setTimeout(тик, 2500);
    if (note) note.hidden = true;
  }

  /* «Слишком часто» без числа — это «попробуйте когда-нибудь». Число берём
     из ответа; служба ещё не написана, и где именно она положит retry_after,
     мы не видели — поэтому смотрим оба места, а не найдя, так и говорим.
     Выдумать секунды тут значит соврать про то, что произойдёт. */
  function tooOften(e) {
    var d = (e && e.data) || {};
    var inner = (d.detail && typeof d.detail === "object") ? d.detail : {};
    var sec = parseInt(d.retry_after || inner.retry_after || 0, 10);
    if (sec > 0) {
      return T("Слишком часто. Повторить можно через ") +
        (sec >= 60 ? Math.ceil(sec / 60) + T(" мин") : sec + T(" с")) + ".";
    }
    return T("Слишком часто: ") + reason(e) +
      T(". Через сколько можно повторить, служба не сказала.");
  }

  /* После входа субъект другой: у вошедшего есть дела, о которых аноним не
     знал, и список на экране посчитан не от него. Открытое дело при этом
     остаётся своим — перенос отдал его тому же человеку, и обнулять его
     значило бы выкинуть разговор, который прямо сейчас на экране. */
  async function afterSignin() {
    // Пришедший из v2 вернётся к сохранённой анкете приглашения.
    try {
      if (sessionStorage.getItem("fixar.v2.login.return") === "1") {
        sessionStorage.removeItem("fixar.v2.login.return");
        location.replace("/v2/");
        return;
      }
    } catch (e) { /* продолжаем обычный вход */ }
    state.cases = [];
    await renderScopes();
    await restoreCase();
    await renderFiles();
    await renderDocs();
    await renderPapers();
    await renderFinds();
    renderArtifacts();
    // После входа субъект другой, а объявления его: остаток прежнего списка
    // показывал бы чужое.
    await renderBoard();
    // Субъект после входа может быть другим, а счёт — его: остаток анонима
    // рядом с именем вошедшего показывал бы чужие деньги.
    refreshCredits();
  }

  /* Перечитать, кто мы теперь. Зовётся после каждого входа: после привязки
     второго поставщика набор входов меняется, и шапка с блоком входа обязаны
     это отразить — иначе кнопка «добавить Google» останется висеть у того,
     кто Google только что добавил. */
  async function refreshWho() {
    try {
      var who = await прочитатьСессию(state.token);
      if (!who) return null;
      state.token = who.session_token || state.token;
      state.assurance = who.assurance;
      state.principal = who.principal_id || state.principal;
      showMe(who);
      await setupSignin(who);
      return who;
    } catch (e) { /* не критично */ }
  }

  /* ── Кредиты ──────────────────────────────────────────────────────── */

  /* Кредиты — счёт человека, а не разрешение. Сервер стартует в режиме учёта:
     он считает расход и дарит сотню, когда прежняя кончилась, но ничего не
     запрещает. Поэтому оболочка остаток только ПОКАЗЫВАЕТ и ничего по нему не
     решает: погасить кнопку отправки при нуле значило бы ввести запрет,
     которого на сервере нет, — и человек упёрся бы в стену, которой нет.

     Ручек может ещё не быть — их делают параллельно. Пока их нет, блока просто
     нет на экране. Показать «0» или «—» вместо неизвестного нельзя: и то и
     другое читается как «у меня кончилось», а выдуманный ноль про чужие деньги
     страшнее пустоты. */

  /* Ручки нет (404) — больше не спрашиваем: путь не откроется в середине
     сеанса, а спрашивали бы мы его после каждого хода. */
  var creditsOff = false;
  /* Последний прочитанный остаток целиком. Нужен истории: режим учёта и
     расхождение с кэшем служба называет при остатке, а объясняют они то, что
     человек видит в истории. */
  var lastCredits = null;

  /* Числом считаем только число. Строку «100» служба может прислать по
     невнимательности, а мы по ней покажем человеку его счёт. */
  function num(v) {
    return (typeof v === "number" && isFinite(v)) ? v : null;
  }

  /* Сколько подарков человек уже видел. Помним вместе с субъектом: после входа
     субъект другой, и его подарки не наши — объявить чужое начисление своим
     значит сказать про свой счёт неправду. */
  var GIFTS_KEY = "fixar.gifts";
  var giftsSeen = null;

  function readGifts() {
    if (giftsSeen) return giftsSeen;
    try { giftsSeen = JSON.parse(localStorage.getItem(GIFTS_KEY) || "null"); }
    catch (e) { giftsSeen = null; }
    return giftsSeen;
  }

  function rememberGifts(n) {
    giftsSeen = { p: state.principal, n: n };
    // В памяти помним всегда: в приватном режиме хранилище молча отказывает, а
    // повторять «начислили ещё 100» на каждое обновление нельзя и там.
    try { localStorage.setItem(GIFTS_KEY, JSON.stringify(giftsSeen)); }
    catch (e) { /* переживём до перезагрузки */ }
  }

  /* Подарок человек обязан УВИДЕТЬ. Молча выросший баланс — это перемена в его
     счёте, о которой ему не сказали; заметив однажды, он перестанет верить и
     самому числу.

     Отдельного признака «только что подарили» в ответе нет и быть не должно:
     чтение ничего не начисляет, подарок случается при расходе. Зато есть
     счётчик подарков — по нему и видно, что их стало больше. Говорим только про
     РОСТ, замеченный этим браузером: первый ответ лишь запоминает отметку.
     Сказать «начислили» про подарок, случившийся неизвестно когда до нашего
     прихода, — соврать про время; человек пойдёт искать, за что списалось
     только что. */
  function noteGifts(d) {
    var n = num(d && d.gifts_count);
    if (n === null) return;
    var seen = readGifts();
    if (!seen || seen.p !== state.principal) { rememberGifts(n); return; }
    if (n <= seen.n) {
      // Журнал не убывает; если число упало — это другой счёт или сброс, и
      // спорить с сервером мы не будем, просто выровняем отметку.
      if (n !== seen.n) rememberGifts(n);
      return;
    }
    var delta = n - seen.n;
    var was = seen.n;
    rememberGifts(n);
    // Сколько дарят за раз — со слов службы. Сотня названа владельцем, но живёт
    // в её коде, и вписать её сюда значило бы однажды назвать сумму, которой не
    // начисляли.
    var size = num(d.gift_size);
    if (was === 0 && n === 1) {
      // Первый подарок — стартовый запас. Сказать про него «кредиты кончились»
      // значит напугать человека тем, чего он не тратил: он тут впервые.
      say("bot", "Ф", size === null
        ? "Кредиты начислены в подарок — платить за них не надо."
        : T("Начислено кредитов: ") + size + T(" — это подарок, платить за него не " +
          "надо."));
      return;
    }
    if (delta === 1) {
      say("bot", "Ф", size === null
        ? "Кредиты кончились — начислили ещё. Сколько именно, служба не сказала."
        : T("Кредиты кончились — начислили ещё ") + size + ".");
      return;
    }
    // Между заходами кредиты кончались не один раз. Складывать подарки в один
    // нельзя: их было столько, сколько было.
    say("bot", "Ф", T("Кредиты кончались и раньше — подарков с прошлого раза: ") +
        delta + (size === null ? "." : T(", по ") + size + T(" каждый.")));
  }

  /* ── Колокольчик уведомлений ────────────────────────────────────────

     Отвечает на вопрос «что случилось, пока меня не было». Серверная часть
     была построена целиком и недостижима: переписка шлёт уведомление на
     каждое сообщение, служба входа его пишет и умеет отдавать вместе с числом
     непрочитанных, — а в шлюзе не было ни одного маршрута со словом notif.
     Переписка работала, и узнать о ней было нельзя. */

  var уведомленийНет = false;      // путь не открыт — больше не спрашиваем
  var уведомления = [];

  function колокол(id) { return document.getElementById(id); }

  async function обновитьКолокол() {
    var короб = колокол("bellwrap");
    if (!короб) return;
    if (уведомленийНет || !state.principal) { короб.hidden = true; return; }
    var d;
    try {
      d = await api("GET", "/principals/" + encodeURIComponent(state.principal) +
                    "/notifications?limit=30");
    } catch (e) {
      // 404 — путь ещё не открыт наружу: оболочка и шлюз выкладываются
      // раздельно, и минуту-другую после выкладки одного другого может не
      // быть. Прочие отказы бывают разовыми, и гаснуть от них насовсем нельзя.
      if (e.status === 404) уведомленийНет = true;
      короб.hidden = true;
      return;
    }
    уведомления = (d && d.notifications) || [];
    var новых = (d && d.unread) || 0;
    короб.hidden = false;
    var значок = колокол("bellnum");
    if (значок) {
      значок.hidden = !новых;
      // Больше 99 — «99+»: трёхзначное число не влезает в кружок, а точная
      // цифра здесь никому не нужна.
      значок.textContent = T(новых > 99 ? "99+" : String(новых));
    }
    var кнопка = колокол("bellall");
    if (кнопка) кнопка.disabled = !новых;
    рисоватьУведомления();
  }

  function рисоватьУведомления() {
    var список = колокол("belllist");
    if (!список) return;
    список.innerHTML = "";
    if (!уведомления.length) {
      список.appendChild(el("div", "bell1 flat",
        "Пока ничего. Здесь появятся сообщения от участников ваших дел " +
        "и события по обязательствам."));
      return;
    }
    уведомления.forEach(function (u) {
      var куда = кудаВедёт(u);
      var стр = el("div", "bell1" + (u.read ? "" : " new") + (куда ? "" : " flat"));
      стр.appendChild(el("span", "bt", u.title || "Уведомление"));
      if (u.body) стр.appendChild(el("span", "bb", u.body));
      стр.appendChild(el("span", "bw", when(u.created_at)));
      if (куда) {
        стр.setAttribute("role", "menuitem");
        стр.tabIndex = 0;
        var пойти = function () { открытьУведомление(u, куда); };
        стр.addEventListener("click", пойти);
        стр.addEventListener("keydown", function (e) {
          if (e.key === "Enter" || e.key === " ") { e.preventDefault(); пойти(); }
        });
      }
      список.appendChild(стр);
    });
  }

  /* Куда ведёт уведомление — и ведёт ли вообще.

     Ссылка у разных видов разная: у сообщения это нить, у календаря и
     присмотра — дело, у подарка кредитов открывать нечего вовсе. Сделать
     кликабельным всё подряд значит завести строки, по которым человек будет
     нажимать без ответа. */
  function кудаВедёт(u) {
    var ref = (u && u.ref) || {};
    if (ref.thread_id) return { вид: "нить", id: ref.thread_id };
    if (ref.case_id) return { вид: "дело", id: ref.case_id };
    return null;
  }

  async function открытьУведомление(u, куда) {
    закрытьКолокол();
    // Отмечаем прочитанным ПОСЛЕ перехода, а не вместо него: отметить и не
    // открыть — потерять уведомление, о котором никто уже не узнает.
    try {
      if (куда.вид === "нить") {
        await openThread(куда.id);
      } else {
        await openCase(куда.id);
      }
    } finally {
      await прочитано(u.id);
    }
  }

  async function прочитано(id) {
    if (!id) return;
    try {
      await api("POST", "/notifications/" + encodeURIComponent(id) + "/read", {});
      await обновитьКолокол();
    } catch (e) { /* отметка не критична: увидено глазами */ }
  }

  async function всеПрочитаны() {
    var кнопка = колокол("bellall");
    if (кнопка) кнопка.disabled = true;
    var непрочитанные = уведомления.filter(function (u) { return !u.read; });
    // По одному, а не пачкой: ручки «отметить всё» в службе нет, а выдумывать
    // её ради кнопки значит заводить вторую правду о том, что прочитано.
    for (var i = 0; i < непрочитанные.length; i++) {
      try {
        await api("POST", "/notifications/" +
                  encodeURIComponent(непрочитанные[i].id) + "/read", {});
      } catch (e) { /* одно не отметилось — остальные всё равно надо */ }
    }
    await обновитьКолокол();
  }

  function закрытьКолокол() {
    var короб = колокол("bellbox"), кнопка = колокол("bell");
    if (короб) короб.hidden = true;
    if (кнопка) кнопка.setAttribute("aria-expanded", "false");
  }

  /* ── Опрос: узнать о новом, не перезагружая страницу ────────────────

     ПОЧЕМУ ОПРОС, А НЕ ПОТОК. Ни одна служба не отдаёт события потоком: ни
     SSE, ни сокета в системе нет ни в одном сервисе. Опрос — единственный
     честный вариант сегодня; заводить поток ради двух панелей значит завести
     его в шлюзе, в службе и в оболочке разом.

     ЦЕПОЧКОЙ setTimeout, А НЕ setInterval. Интервал ставит запросы в очередь,
     если ответ идёт дольше периода, — при плохой связи это лавина. Цепочка
     заводит следующий тик после ответа на предыдущий.

     СПИТ В СКРЫТОЙ ВКЛАДКЕ. Без этого брошенная вкладка стучится вечно, и
     каждый её тик — четыре запроса наверх: шлюз спрашивает whoami на каждом
     непубличном обращении. Проверено чтением: visibilitychange в оболочке не
     слушал никто.

     ЧЕГО ОПРОС НЕ ДЕЛАЕТ. Он не перечитывает журнал открытого дела. Дорисовка
     реплик поверх идущего разговора — отдельная работа: replayDialog только
     добавляет и не чистит, а чистит openCase, который на том же деле делает
     ранний возврат. Обновлять дело тиком значит либо дублировать реплики,
     либо стирать разговор под руками. Поэтому опрос трогает ровно то, что
     безопасно перерисовать целиком: колокольчик и список переписки. */

  var ОПРОС_МС = 45000;
  var опросТаймер = null;

  function опросТик() {
    опросТаймер = null;
    if (document.hidden || !state.principal) { поставитьОпрос(); return; }
    Promise.resolve()
      .then(обновитьКолокол)
      .then(renderThreads)
      // Журнал открытого дела — только когда ход не идёт: дописывать под
      // руками у отвечающего значит показать ответ дважды, своим тиком и
      // возвратом хода.
      .then(function () { if (!state.busy) return дописатьЖурнал(false); })
      .catch(function () { /* разовый отказ не должен останавливать опрос */ })
      .then(поставитьОпрос);
  }

  function поставитьОпрос() {
    if (опросТаймер) clearTimeout(опросТаймер);
    опросТаймер = setTimeout(опросТик, ОПРОС_МС);
  }

  function setupPolling() {
    поставитьОпрос();
    // Вернулись на вкладку — спрашиваем сразу, а не ждём конца периода:
    // человек отвлёкся и вернулся именно затем, чтобы посмотреть, что нового.
    document.addEventListener("visibilitychange", function () {
      if (!document.hidden) опросТик();
    });
  }

  function setupBell() {
    var кнопка = колокол("bell"), короб = колокол("bellbox"),
        все = колокол("bellall");
    if (кнопка) {
      кнопка.addEventListener("click", function (e) {
        e.stopPropagation();
        var открыт = короб && короб.hidden === false;
        if (короб) короб.hidden = открыт;
        кнопка.setAttribute("aria-expanded", открыт ? "false" : "true");
        if (!открыт) обновитьКолокол();
      });
    }
    if (все) все.addEventListener("click", function (e) {
      e.stopPropagation();
      всеПрочитаны();
    });
    // Щелчок мимо закрывает. Без этого выпадашка остаётся висеть над тем, что
    // человек уже читает.
    document.addEventListener("click", function (e) {
      var w = колокол("bellwrap");
      if (w && !w.contains(e.target)) закрытьКолокол();
      // Кредиты закрываются тем же щелчком и той же клавишей. Две панели в
      // одной шапке, закрывающиеся по-разному, человек считает разными по
      // устройству и ищет у второй кнопку, которой нет.
      var к = document.getElementById("credwrap");
      if (к && !к.contains(e.target)) закрытьКредиты();
    });
    document.addEventListener("keydown", function (e) {
      if (e.key === "Escape") { закрытьКолокол(); закрытьКредиты(); }
    });
  }

  async function refreshCredits() {
    var box = document.getElementById("credits");
    if (!box) return;
    if (creditsOff || !state.principal) { box.hidden = true; return; }
    var d;
    try {
      d = await api("GET", "/principals/" + state.principal + "/credits");
    } catch (e) {
      // 404 — путь ещё не открыт наружу. Прочие отказы бывают разовыми, и
      // отключаться от них насовсем нельзя.
      if (e.status === 404) creditsOff = true;
      // Прячем и при разовом отказе: остаток — деньги, и число, про которое мы
      // знаем, что оно могло измениться, хуже пустого места.
      box.hidden = true;
      return;
    }
    var n = num(d && d.balance);
    if (n === null) { box.hidden = true; return; }
    lastCredits = d;
    box.className = "credits" + (n <= 0 ? " zero" : "");
    box.innerHTML = "";
    box.appendChild(el("span", null, "кредиты"));
    box.appendChild(el("b", null, String(n)));
    box.title = T("За что списано — нажмите");
    box.hidden = false;
    noteGifts(d);
  }

  /* Выпадающий список у кредитов: пополнить и обменять на рубли.

     ПОЧЕМУ РАЗБОР ОСТАТКА ЗДЕСЬ, А НЕ ОДНО ЧИСЛО. Кредит равен рублю, но не
     всякий кредит можно вывести: подарочные невыводимы и в обеспечение брони
     не годятся. Одно число «остаток» скрыло бы это, и человек узнал бы в ту
     минуту, когда ему отказали. Удержанное по броням тоже названо: тот, у кого
     «пропали» 750, обязан видеть, куда они делись.

     ПРО ОТСУТСТВИЕ ВЫПЛАТ ГОВОРИТСЯ ДО НАЖАТИЯ. Платёжного рельса нет —
     подключение упирается в юрлицо, договор и проверку. Обещать кнопкой то,
     чего нет, и объяснять после — хуже, чем сказать сразу. */
  function m_внутри(узел, цель) {
    for (var т = цель; т; т = т.parentNode) if (т === узел) return true;
    return false;
  }

  /* Щелчок пришёлся МИМО списка кредитов и мимо самой кнопки?

     ОТДЕЛЬНОЙ ФУНКЦИЕЙ, ЧТОБЫ ЭТО МОЖНО БЫЛО ПРОВЕРИТЬ. Пока решение жило
     условием внутри обработчика, его нельзя было позвать из проверки — и
     ошибка дожила до человека.

     ВХОЖДЕНИЕ, А НЕ РАВЕНСТВО. Здесь стояло `e.target.id === "credits"`, и
     меню было неоткрываемым пальцем: у чипа два потомка —
     `<span>кредиты</span>` и `<b>0</b>`, — щелчок попадает в них. Событие
     всплывало, меню открывалось, и тот же обработчик закрывал его обратно,
     потому что цель — потомок, а не узел. Снаружи: «щёлкаю по кредитам —
     ноль реакции»; работало только попадание в отступ вокруг надписи.

     Для самого списка вхождение проверялось с самого начала — ровно та же
     проверка нужна была и кнопке. */
  function щелчок_мимо_кредитов(цель) {
    var м = document.getElementById("credmenu");
    var чип = document.getElementById("credits");
    if (м && m_внутри(м, цель)) return false;
    if (чип && m_внутри(чип, цель)) return false;
    return true;
  }

  function closeCredMenu() {
    var м = document.getElementById("credmenu");
    if (м) м.remove();
  }

  function creditMenu() {
    if (document.getElementById("credmenu")) { closeCredMenu(); return; }
    var кнопка = document.getElementById("credits");
    if (!кнопка || !lastCredits) return;
    var д = lastCredits;
    var выводимо = num(д.withdrawable);
    var подарочных = num(д.gift_balance);
    var удержано = num(д.held_by_bookings);

    var м = el("div", "credmenu"); м.id = "credmenu";

    var разбор = el("div", "cmsplit");
    // КУРС НЕ ЗАШИТ ЧИСЛОМ. Стояло «1 кредит = 1 ₽» — правда до 30.08.2026,
    // ложь после: деноминация сделала кредит равным ДЕСЯТИ КОПЕЙКАМ, а
    // оболочка продолжала называть рубль. Человек читал вдесятеро завышенную
    // цену своего остатка — и читал это на живом сайте.
    //
    // Служба присылает курс в ответе (`kopecks_per_credit`); своего мнения о
    // нём у страницы быть не должно. Не прислала — молчим о курсе, а не
    // выдумываем: неверная цена хуже отсутствующей.
    var копеек = num(д.kopecks_per_credit);
    if (копеек !== null && копеек > 0) {
      // ПЕРЕВОД — ПО КУСКАМ, а не целой строкой. Словарь ключуется фразой
      // ЦЕЛИКОМ, а здесь в неё встроено число: собранное «1 кредит = 10 коп.»
      // в словаре не найдётся никогда, и англичанин читал бы русское.
      // Поэтому переводим неизменные части, а число подставляем между ними.
      разбор.appendChild(el("div", null,
        T("1 кредит = ") + (копеек % 100 === 0
          ? String(копеек / 100) + T(" ₽")
          : String(копеек) + T(" коп."))));
    }
    var строка = el("div", null, "можно вывести: ");
    строка.appendChild(el("b", null, String(выводимо === null ? "?" : выводимо)));
    разбор.appendChild(строка);
    if (подарочных) {
      var п = el("div", null, "подарочных (не выводятся): ");
      п.appendChild(el("b", null, String(подарочных)));
      разбор.appendChild(п);
    }
    if (удержано) {
      var у = el("div", null, "удержано по броням: ");
      у.appendChild(el("b", null, String(удержано)));
      разбор.appendChild(у);
    }
    м.appendChild(разбор);

    var пополнить = el("button", "cm1", "Пополнить");
    пополнить.type = "button";
    пополнить.addEventListener("click", function () {
      closeCredMenu();
      просить_пополнение();
    });
    м.appendChild(пополнить);

    var обменять = el("button", "cm1", "Обменять на рубли");
    обменять.type = "button";
    обменять.addEventListener("click", function () { closeCredMenu(); просить_вывод(); });
    м.appendChild(обменять);

    var история = el("button", "cm1", "За что списано");
    история.type = "button";
    история.addEventListener("click", function () { closeCredMenu(); showCreditsHistory(); });
    м.appendChild(история);

    // ОГОВОРКА ПЕРЕПИСАНА ВМЕСТЕ С КНОПКОЙ. Прежняя говорила «пополнение и
    // выплаты ещё не подключены» — с 03.09.2026 это неправда про пополнение,
    // и текст, переживший свою причину, врёт увереннее, чем ошибка.
    м.appendChild(el("div", "cmnote",
      "Пополнить можно и картой, и со счёта организации — спросим при "
      + "нажатии. Деньги приходят на расчётный счёт. Выплаты пока упираются "
      + "в договор: заявку подать можно, она встанет в очередь и ждёт, и её "
      + "можно отменить."));

    var где = кнопка.getBoundingClientRect();
    м.style.top = (где.bottom + window.scrollY) + "px";
    м.style.left = (где.left + window.scrollX) + "px";
    document.body.appendChild(м);
  }

  /* Купить кредиты. Ссылку выставляет банк, картинку рисует он же.

     СВОЙ QR НЕ РИСУЕМ. Сгенерированный у нас код — ещё одно место, где можно
     ошибиться реквизитами, и ошибка эта отправит деньги человека не туда. */

  async function просить_пополнение() {
    var сколько = prompt(T("Сколько кредитов купить? Кредит — 10 копеек, "
      + "то есть 1000 кредитов это 100 ₽."), "1000");
    if (сколько === null) return;
    var число = parseInt(String(сколько).replace(/\s/g, ""), 10);
    if (!(число > 0)) {
      say("bot", "Ф", T("Не понял количество. Нужно целое число кредитов."));
      return;
    }

    // КТО ПЛАТИТ — ОТДЕЛЬНЫЙ ВОПРОС, и его нельзя угадать. Организация платит
    // со счёта (дешевле и ей, и нам), частное лицо — картой или СБП. Ссылку
    // для бизнеса личной картой не оплатить: это устройство продукта банка, а
    // не наша настройка.
    var юрлицо = confirm(T("Платить будет организация со своего расчётного "
      + "счёта?\n\nОК — да, счёт юрлица или ИП.\nОтмена — плачу как "
      + "частное лицо, картой или СБП."));

    var р;
    try {
      р = await api("POST", "/credits/topup",
                    { credits: число, payer: юрлицо ? "company" : "person" });
    } catch (e) {
      // ЗАМЕТКОЙ, А НЕ ГОЛОСОМ ПОМОЩНИКА. Здесь стояло `say("bot", "Ф", …)`,
      // и сторож `TestНиОдногоСрываГолосомНеОсталось` покраснел правильно:
      // «Ф» говорит от лица собеседника, и человек читает отказ СЛУЖБЫ как
      // слова агента. `сорвалось` само решает по коду: 4xx — это ответ
      // человеку (его сумма, его кошелёк), 5xx — наша поломка и заметка.
      //
      // Какие именно 4xx тут бывают: 503 — приём не подключён, 422 — сумма вне
      // пределов, 409 — есть неоплаченные. Все три человек исправит сам, если
      // ему сказать, — потому они и должны доезжать словами.
      сорвалось(T("Пополнить не вышло: "), e);
      return;
    }

    say("bot", "Ф", T("Счёт на ") + р.roubles + T(" ₽ за ") + р.credits
      + T(" кредитов. ") + (р.note || ""));

    // Картинка приходит от банка в base64. Показываем её, а рядом — ссылку:
    // с телефона удобнее сканировать, с рабочего места — нажать.
    //
    // КЛАДЁМ В ЛЕНТУ РАЗГОВОРА, А НЕ В `#chat`. Здесь стояло
    // `getElementById("chat") || document.body`, и узла с таким именем НЕ
    // СУЩЕСТВУЕТ: лента зовётся `log`. Блок уходил в конец `<body>` — то есть
    // ниже всей страницы, за пределы взгляда. Снаружи это выглядело как
    // «нажимаю — тишина»: счёт выставлялся, QR приходил, и никто его не видел.
    //
    // Проверено на живой странице, а не чтением: `document.getElementById
    // ("chat")` вернул `null`.
    // ЗАПАСНОГО ПУТИ НЕТ НАМЕРЕННО. Здесь стояло `|| document.body`, и
    // именно оно спрятало счёт: узла `chat` не существовало, запасной путь
    // сработал молча, а QR уехал ниже всей страницы. Молчаливый запасной путь
    // не спасает — он превращает поломку в тишину.
    //
    // Ленты нет — значит сломано что-то крупнее нашего счёта. Говорим об этом
    // заметкой и не делаем вид, что показали.
    var где = document.getElementById("log");
    if (!где) {
      сорвалось(T("Счёт выставлен, но показать его негде: "), null,
                T("на странице нет ленты разговора. Ссылка на оплату: ")
                + (р.payment_url || р.qr_payload || ""));
      return;
    }
    var блок = el("div", "topup");
    if (р.qr_image) {
      var кар = document.createElement("img");
      кар.src = "data:" + (р.qr_media_type || "image/png") + ";base64,"
        + р.qr_image;
      кар.alt = T("QR для оплаты");
      кар.style.maxWidth = "240px";
      блок.appendChild(кар);
    }
    // У эквайринга картинки нет — банк отдаёт СТРОКУ СБП. Показываем её
    // ссылкой: с телефона она открывает приложение банка.
    if (!р.qr_image && р.qr_payload) {
      var сбп = el("a", "send", T("Оплатить через СБП"));
      сбп.href = р.qr_payload;
      сбп.target = "_blank";
      сбп.rel = "noopener";
      блок.appendChild(сбп);
    }
    if (р.payment_url) {
      var сс = el("a", "send", T("Открыть ссылку на оплату"));
      сс.href = р.payment_url;
      сс.target = "_blank";
      сс.rel = "noopener";
      блок.appendChild(сс);
    }
    // СРОК НАЗЫВАЕТСЯ СРАЗУ. Ссылка живёт считаные дни, и человек, вернувшийся
    // к ней через неделю, должен понимать, почему она не открылась.
    блок.appendChild(el("div", "sub",
      T("Ссылка действует до ") + (р.expires_at || "").slice(0, 10)
      + T(". Кредиты придут после того, как банк подтвердит оплату — обычно "
        + "в течение нескольких минут.")
      // СТАТИЧЕСКИЙ QR ЖДЁТ ДОЛЬШЕ, и молчать об этом нельзя: человек
      // заплатил и смотрит на пустой счёт. У него нет объекта платежа, о
      // котором можно спросить банк, — мы узнаём приход из выписки, а она
      // обновляется не мгновенно.
      + (р.rail === "static_qr"
         ? T(" По статическому QR это занимает дольше: мы узнаём платёж из "
             + "банковской выписки, а не по номеру заказа.") : "")));
    где.appendChild(блок);
    // Доводим до глаз: лента прокручена вниз, иначе счёт остаётся выше
    // видимого края ровно тогда, когда разговор длинный.
    где.scrollTop = где.scrollHeight;
  }

  async function просить_вывод() {
    var д = lastCredits || {};
    var можно = num(д.withdrawable) || 0;
    if (можно <= 0) {
      say("system", "Кредиты",
          "Выводить нечего: подарочные кредиты не выводятся. Выводимыми "
          + "становятся купленные и полученные по броням.");
      return;
    }
    var сколько = window.prompt(
      T("Сколько кредитов обменять на рубли? Доступно ") + можно, String(можно));
    if (сколько === null) return;
    var n = parseInt(String(сколько).replace(/\s/g, ""), 10);
    if (!n || n <= 0 || n > можно) {
      say("system", "Кредиты", T("Нужно число от 1 до ") + можно + ".");
      return;
    }
    try {
      var з = await api("POST", "/credits/payouts", { amount: n });
      say("system", "Заявка на вывод", з.note || "Заявка принята.");
      refreshCredits();
    } catch (e) {
      say("system", "Заявка на вывод", reason(e));
    }
  }

  function creditRow(it) {
    var row = el("div", "cred1");
    // За что — словами службы: note она пишет для человека, а reason это ключ
    // ставки и остаётся на случай, когда пояснения не написали. Своего словаря
    // причин здесь нет намеренно — вторая копия названий однажды покажет
    // «model_call», ровно как это было бы с областями жизни.
    var what = (it && (it.note || it.reason)) || "";
    row.appendChild(el("span", "cwhat", what || "без пояснения"));
    var w = when(it && it.at);
    if (w) row.appendChild(el("span", "cwhen", w));
    // Списание, не покрытое остатком, служба помечает сама. Прятать это нельзя:
    // человек работал в долг, и он вправе знать, что так было.
    if (it && it.unfunded) row.appendChild(el("span", "cwhen", "сверх остатка"));
    var n = num(it && it.amount);
    if (n !== null) {
      row.appendChild(el("span", "camt" + (n > 0 ? " plus" : ""),
                        (n > 0 ? "+" : "") + n));
    }
    return row;
  }

  /* За что списано и когда. Коротко: здесь отвечают на «куда ушло», а не выдают
     выписку — за выпиской человек придёт, когда усомнится, и тогда её надо
     будет показать целиком, а не двадцатью строками из середины.

     ВЫВОД ИДЁТ В ПАНЕЛЬ ПОД ЧИСЛОМ, А НЕ В ПЕРЕПИСКУ. Прежде эти строки
     дописывались в log — в тот же поток, где идёт разговор. Две беды сразу:
     служебная выписка вставала между вопросом человека и ответом
     собеседника, и оставалась там навсегда — перечитывая разговор через
     неделю, человек находил посреди него списания, которых в разговоре не
     было. Панель же закрывается, когда на неё посмотрели. */
  function закрытьКредиты() {
    var box = document.getElementById("credbox");
    var chip = document.getElementById("credits");
    if (box) box.hidden = true;
    if (chip) chip.setAttribute("aria-expanded", "false");
  }

  async function showCreditsHistory() {
    if (!state.principal) return;
    var box = document.getElementById("credbox");
    var body = document.getElementById("credlist");
    var chip = document.getElementById("credits");
    if (!box || !body) return;
    // Повторное нажатие закрывает. Иначе единственный способ убрать панель —
    // догадаться щёлкнуть мимо, а кнопка, которая только открывает, ощущается
    // сломанной.
    if (!box.hidden) { закрытьКредиты(); return; }
    box.hidden = false;
    if (chip) chip.setAttribute("aria-expanded", "true");
    body.innerHTML = "";
    body.appendChild(el("div", "waynote", "смотрю…"));

    var d;
    try {
      d = await api("GET", "/principals/" + state.principal + "/credits/history");
    } catch (e) {
      body.innerHTML = "";
      // Отсутствие истории и отказ в ней — разные вещи, и выглядеть одинаково
      // они не должны: в первом случае сам остаток при этом настоящий.
      body.appendChild(el("div", "waynote", e.status === 404
        ? "История расхода ещё не открыта на сервере. Остаток при этом " +
          "настоящий — его служба назвала."
        : T("История не прочиталась: ") + reason(e)));
      return;
    }
    // Служба зовёт строки журнала entries; голый список и items встречаются у
    // соседних ручек, и ломаться из-за обёртки незачем.
    var items = Array.isArray(d) ? d : ((d && (d.entries || d.items)) || []);
    body.innerHTML = "";
    if (!items.length) {
      // Пустое говорим словами: пустой блок человек прочитает как поломку и
      // пойдёт искать, что сломалось, вместо ответа «ничего не списано».
      body.appendChild(el("div", "waynote",
        "Списаний пока нет — за вами ничего не числится."));
    } else {
      items.forEach(function (it) { body.appendChild(creditRow(it)); });
    }
    // Почему на нуле всё продолжает работать — словами службы, а не нашими:
    // режим она называет сама, и пересказывать его своими значит однажды
    // пообещать запрет или свободу, которых у неё нет.
    var note = lastCredits ? lastCredits.mode_note : null;
    if (typeof note === "string" && note) {
      body.appendChild(el("div", "waynote", T("режим учёта: ") + note));
    }
    // Служба сверяет журнал со своим кэшем и говорит, когда они разошлись.
    // Промолчать об этом — показать число, про которое сами знаем, что оно
    // может быть неверным.
    if (lastCredits && lastCredits.cache_matches_journal === false) {
      body.appendChild(el("div", "waynote", "служба сообщает: её журнал и кэш " +
        "остатка разошлись — число может быть неточным, и это её забота, не " +
        "ваша."));
    }
  }

  /* ── Пилюли областей жизни ────────────────────────────────────────── */

  /* Ось человека, а не системы: направление отвечает «о чём дело», а это —
     «чьё оно в моей жизни». Неотнесённое остаётся неотнесённым: свалить всё
     в «личные» значит однажды показать рабочее дело тому, кто открыл вкладку
     «личные». */

  /* ОТБОРА ПО ОБЛАСТИ БОЛЬШЕ НЕТ: пилюли, которые его задавали, сняты с
     экрана 03.09.2026. Переменная убрана целиком, а не оставлена вечно
     пустой: постоянно ложная ветка читается следующим как живой отбор и
     переживает не одну правку. Ручка `?scope=` у службы жива. */
  /* Названия областей берём из ответа службы, а не из своей копии: список
     областей растёт там, и вторая копия здесь однажды покажет «hobby». */
  var scopeTitles = {};

  /* Панели, которым дела НЕ НУЖНЫ.
     Они висели хвостом renderScopes и потому появлялись только у того, у кого
     дело уже есть. Для кабинета это смертельно: психолог приходит ЗАВЕСТИ
     практику, дел у него нет по определению — и он не видел ни кабинета, ни
     картотеки, ни календаря. Не «нельзя», а пусто: жаловаться не на что,
     и поломка живёт долго.
     Здесь они собраны отдельно и зовутся на КАЖДОМ выходе из renderScopes,
     включая досрочные. Зависимость от числа дел осталась ровно у того, что от
     него и правда зависит, — у пилюль областей. */
  function renderPanels() {
    // Журнал — рядом, но не вместо: если человек не оператор, дверь ответит
    // 404 и панель останется скрытой.
    renderOps();
    // Выплаты, ждущие разрешения. Дверь решает, кому её показывать: не
    // оператору 404, и панель остаётся скрытой.
    renderPayouts();
    renderCredits();
    // Ландшафт — рядом с картотекой, но НЕ внутри неё: он есть у всякого, а
    // картотека только у владельца кабинета.
    renderLandscape();
    renderОбзорЦен();
    renderLogins();
    renderPractice();
    // Страница подбора и заявки — принадлежности кабинета, как календарь.
    // Обе сами решают, показываться ли: направление может страниц не вести.
    renderPickPage();
    renderLeads();
    // Партнёрские ссылки — принадлежность кабинета, как страница подбора.
    // Сама решает, показываться ли: направление может не иметь ни одной
    // партнёрской программы, и пустой раздел читался бы как поломка.
    renderAffiliate();
    renderSites();
    renderCalendar();
    renderClients();
    // Объявления смотрят на СУБЪЕКТА, а не на кабинет: техника продаётся и
    // без практики. Потому рисуются здесь, а не внутри renderPractice.
    renderBoard();
    // Витрина паков смотрит на субъекта, как и объявления: расширения нужны
    // и без единого дела.
    renderStorefront();
    renderThreads();
    renderFeed();
  }

  async function renderScopes() {
    if (!state.principal) return;
    var box = document.getElementById("scopes");
    var data;
    try {
      data = await api("GET", "/principals/" + state.principal + "/cases/scopes");
    } catch (e) {
      // Прежде здесь стоял голый `return`, и он выходил ДО renderCases(): у
      // человека оставалась стартовая заглушка «Дело появится, как только вы
      // начнёте», а панель дел не показывалась вовсе. Отказ службы выглядел
      // как «дел у вас ещё нет» — приглашением завести второе дело поверх
      // существующих.
      //
      // Пилюли областей без ответа службы не построить, но список дел живёт
      // отдельной ручкой: её и спрашиваем, а про неизвестное говорим вслух.
      box.hidden = true;
      box.innerHTML = "";
      сорвалось(T("Разделы по областям сейчас не показать: "), e, T(". Это не значит, что дел нет — список ниже я всё равно спрошу."));
      await renderCases();
      renderPanels();
      return;
    }
    // Сколько всего дел — нужно и здесь, и совету про второй вход: пустому
    // аккаунту он ни к чему, терять нечего.
    state.caseCount = data.all;
    data.scopes.forEach(function (s) { scopeTitles[s.scope] = s.title; });
    // Шесть нулей ничего не сообщают и занимают место. Пилюли появляются
    // вместе с первым делом — раньше фильтровать нечего.
    // Список ждём: по нему решается, можно ли вернуть сохранённое дело, и
    // пуск спрашивает об этом сразу за пилюлями.
    if (!data.all) {
      box.hidden = true; box.innerHTML = "";
      await renderCases();
      renderPanels();
      return;
    }
    /* ═══ ПИЛЮЛЬ ОБЛАСТЕЙ БОЛЬШЕ НЕТ ═══

       Здесь строились «Все · Я · Дом · Работа» с числами и, у открытого дела,
       пунктирные «→ отнести». Владелец снял эту ось с экрана 03.09.2026:
       «эти три сферы не должны быть снаружи — они для агента (его внутреннее
       знание)», и следом «и они задают температуру чата».

       ЧТО ОСТАЛОСЬ И ПОЧЕМУ ЭТА ФУНКЦИЯ ЖИВА. Она не только рисовала пилюли:
       из того же ответа берётся `state.caseCount` (по нему совет про второй
       вход решает, есть ли что терять), и она же зовёт `renderCases` и
       `renderPanels` — в том числе на КАЖДОМ досрочном выходе. Удалить её
       целиком значило бы погасить список дел и все панели кабинета; на этой
       грабле здесь уже стояли (довод — в комментарии к отказу выше).

       Ручки `POST /cases/{}/scope` и `POST /entities/{}/scope` живы. Отнимать
       их не за что: область ставится, просто не руками через экран. */
    box.hidden = true;
    box.innerHTML = "";

    // Пилюля обязана фильтровать, а не только считать: число без списка
    // сообщает, что дела есть, и не даёт до них добраться.
    await renderCases();
    renderPanels();
  }

  /* ── Операторские панели: дверь спрашивается ОДИН РАЗ НА ЧЕЛОВЕКА ───

     Обе панели ниже открыты не флагом в оболочке, а дверью, и это правильно.
     Неправильным было другое: вопрос задавался ЗАНОВО НА КАЖДОЙ ПЕРЕРИСОВКЕ
     панелей — то есть на каждый показ списка дел, каждое открытие и закрытие
     дела, каждый вход. Для того, кто оператором не является, ответ известен
     заранее и в пределах сессии не меняется: список операторов живёт в
     окружении шлюза, и попасть в него можно только правкой окружения с
     перезапуском службы.

     ЦЕНА БЫЛА НЕ В ТРАФИКЕ, А В ЖУРНАЛЕ ОТКАЗОВ. С 27.08.2026 каждый отказ
     двери пишется в журнал (shared/refusal_log.py) — кольцо на ДВАДЦАТЬ
     записей на человека, срок час. Журнал заведён ровно затем, чтобы человек
     и агент-администратор могли ответить на вопрос «почему меня не пустило
     только что». Две записи на каждую перерисовку вытесняли оттуда настоящие
     отказы: у первого же живого субъекта (prn_eea2e818a94b347d, обычный
     аноним, заведён 27.08 в 11:00) ВСЕ 12 записей журнала оказались нашим
     собственным опросом этих двух путей, и ни одной — его. Оболочка забивала
     своим шумом тот самый прибор, по которому разбирают её же неполадки.

     ПОЧЕМУ ОПЕРАТОРСТВО НЕ ПРОВЕРЯЕТСЯ ЗДЕСЬ. Соблазн очевидный: не
     спрашивать дверь у того, кто не вошёл. Обе доступные оболочке приметы
     врут в опасную сторону. `signed_in` у владельца площадки
     (prn_8c34678748514ce4) РАВНО false: он привязан телеграмом, а `tg` не
     входит в CONFIRMS_IDENTITY — такая проверка спрятала бы панель от
     настоящего оператора. Гадать по `assurance` не лучше: он приезжает из
     whoami, и пока тот не ответил, оператор неотличим от анонима — на этом
     уже обжигались, кабинет практики так исчезал у вернувшегося назавтра.
     Решает по-прежнему ДВЕРЬ. Здесь всего лишь не переспрашивают то, на что
     уже ответили.

     ЧЕГО ЭТО НЕ ЧИНИТ, И ЭТО НАДО НАЗВАТЬ. Первое: один опрос на человека
     всё равно остаётся — аноним получит два отказа в журнал за загрузку
     страницы вместо двух на каждую перерисовку. Убрать и их можно только
     признаком оператора со стороны сервера, а его нет, и заводить его ради
     двух панелей — отдельное решение. Второе: память ставится по ОТВЕТУ, а
     не по отправке, и две перерисовки в один тик успели бы спросить дважды.
     Общей заявки на лету здесь нет намеренно: она пережила бы смену субъекта
     и ответила бы новому человеку про прежнего. */

  /* null — не спрашивали; иначе {пускали, отказала} на каждый путь.
     Ответ привязан к СУБЪЕКТУ: сменился человек — прежний ответ про него и
     остался, к новому он не относится. */
  var дверьОпс = { subject: null, callers: null, credits: null, payouts: null };

  function памятьДвери(ключ) {
    if (дверьОпс.subject !== state.principal) {
      дверьОпс = { subject: state.principal, callers: null, credits: null, payouts: null };
    }
    if (!дверьОпс[ключ]) дверьОпс[ключ] = { пускали: false, отказала: false };
    return дверьОпс[ключ];
  }

  /* Имя панели читаем ИЗ РАЗМЕТКИ, и один раз.

     Своя копия строки здесь разошлась бы с index.html при первом же
     переименовании, а по-английски ещё и молча: разметку переводит `data-en`
     рядом с текстом, а не словарь, и вторая копия жила бы своей жизнью.

     ЖДЁМ ТОГО ЖЕ СОБЫТИЯ, ЧТО И lang.js, И ЭТО НЕ ПЕРЕСТРАХОВКА. Первая
     редакция читала имена сразу, полагая, что сценарий в конце body работает
     по готовой разметке. Это неверно: у обычного (не `defer`) сценария в
     конце body `readyState` ещё «loading» — разбор не кончился, — и lang.js
     по своей же проверке уходит на DOMContentLoaded вместе с переводом.
     Замерено в браузере на настоящих файлах: при захвате «loading» и «журнал
     обращений», после загрузки «complete» и «request log». То есть в
     английском режиме мы забирали РУССКОЕ имя, и упавшая панель писала
     «журнал обращений: could not be read» — ровно ту смесь языков, ради
     которой всё это и заведено.

     ПОРЯДОК ДЕРЖИТСЯ НА ПОРЯДКЕ ПОДКЛЮЧЕНИЯ: lang.js стоит в index.html ВЫШЕ
     app.js, значит его слушатель подписан раньше и сработает раньше нашего —
     слушатели одной цели вызываются в порядке подписки. Поменять эти две
     строки местами значит вернуть смесь языков, и молча.

     ОДИН РАЗ, А НЕ ПО ТРЕБОВАНИЮ: удачная отрисовка пишет в тот же узел
     «обращений за сутки: 5», и прочитанное позже было бы не именем панели, а
     прошлым ответом. */
  var именаПанелей = {};
  (function () {
    function снятьИмена() {
      ["opscount", "crcount"].forEach(function (id) {
        var н = document.getElementById(id);
        if (н) именаПанелей[id] = н.textContent;
      });
    }
    if (document.readyState === "loading") {
      document.addEventListener("DOMContentLoaded", снятьИмена);
    } else {
      снятьИмена();
    }
  })();

  /* Панель, которой не ответили, обязана СКАЗАТЬ ОБ ЭТОМ, а не исчезнуть.

     Прежде любая неудача — 502, обрыв связи, предел частоты — приводила туда
     же, куда и отказ по правам: panel.hidden = true. Для оператора это
     значило, что панель просто пропадала с экрана без единого слова, и
     «сегодня обращений не было» было неотличимо от «служба не ответила».
     Первое — знание, второе — его отсутствие, и решения по ним разные. */
  function панельНеОтветила(panel, rows, cnt, e) {
    panel.hidden = false;
    rows.innerHTML = "";
    cnt.textContent = (именаПанелей[cnt.id] || "") + T(": не прочитано");
    rows.appendChild(el("div", "casenote",
      T("Не удалось прочитать: ") + reason(e) +
      T(". Это не «пусто», а «неизвестно»: показывать нечего, потому что " +
        "ответа не было. Кнопка «Обновить» рядом.")));
  }

  /* ── Выплаты, ждущие разрешения: только оператору ─────────────────── */
  (function () {
    var b = document.getElementById("payrefresh");
    if (b) b.addEventListener("click", function () { renderPayouts(true); });
  })();

  /* ЭКРАН ОДОБРЕНИЯ ВЫПЛАТ.

     Одобряет НЕ получатель: `approval_not_self` в базе запрещает разрешать
     себе. Поэтому это не «мои заявки», а «чужие, которые я разрешаю», и
     ходит панель в операторскую ручку, а не в свою.

     Дверь решает, кому её показывать: не оператору шлюз отвечает 404, и
     панель не появляется. Оболочка операторство не угадывает — обе доступные
     ей приметы врут в опасную сторону (см. довод у `дверьОпс`).

     ЧТО ЧЕЛОВЕК ВИДИТ ПЕРЕД НАЖАТИЕМ. Кому, сколько, куда хвостом счёта.
     Одобрение — решение, а не нажатие: кнопка без имени получателя и суммы
     превратила бы явный акт в формальность, ради борьбы с которой он и
     заведён.

     «ОДОБРЕНО» И «ОДОБРЕНИЕ ДЕЙСТВУЕТ» — РАЗНОЕ. Реквизиты могли смениться
     после одобрения, и тогда прежнее согласие относится уже не к этому
     переводу. Служба считает это отпечатком и присылает отдельным полем;
     показать одно вместо другого значило бы соврать там, где решают. */
  async function renderPayouts(явно) {
    var panel = document.getElementById("paypanel");
    if (!panel) return;
    var rows = document.getElementById("payrows");
    var cnt = document.getElementById("paycount");
    var память = памятьДвери("payouts");

    if (память.отказала && !явно) { panel.hidden = true; return; }

    var свод;
    try {
      свод = await api("GET", "/ops/payouts");
    } catch (e) {
      if (e.status === 404) {
        память.отказала = true;
        panel.hidden = true;
        return;
      }
      память.отказала = false;
      if (!память.пускали) { panel.hidden = true; return; }
      панельНеОтветила(panel, rows, cnt, e);
      return;
    }
    память.пускали = true;
    память.отказала = false;

    var список = (свод && свод.payouts) || [];
    rows.textContent = "";
    cnt.textContent = T("выплаты ждут разрешения") + ": " + список.length;

    if (!список.length) {
      // ПУСТО — ЭТО ОТВЕТ, А НЕ ОТСУТСТВИЕ ОТВЕТА. Пустая панель без слов
      // читается как «не загрузилось».
      rows.appendChild(el("div", "cmnote", T("Заявок, ждущих разрешения, нет.")));
      panel.hidden = false;
      return;
    }

    список.forEach(function (з) { rows.appendChild(payoutRow(з)); });
    panel.hidden = false;
  }

  function payoutRow(з) {
    var row = el("div", "cred1");

    var сумма = el("b", null, String(з.amount_credits) + " " + T("кр."));
    row.appendChild(сумма);

    var р = з["реквизиты"];
    if (!р) {
      // Без реквизитов одобрять нечего: неизвестно, куда переводить. Служба
      // такое одобрение и не примет — говорим это до нажатия, а не после.
      row.appendChild(el("span", null, " — " + T("реквизиты не названы")));
      row.appendChild(el("div", "cmnote",
        T("Пока получатель не назвал счёт, разрешать нечего.")));
      return row;
    }

    row.appendChild(el("span", null,
      " — " + (р["имя"] || "?") + ", " + T("счёт …") + (р["хвост_счёта"] || "????")
      + (р["банк"] ? ", " + р["банк"] : "")));

    if (з["одобрено"] && з["одобрение_действует"]) {
      row.appendChild(el("div", "cmnote", T("Разрешено.")));
      return row;
    }
    if (з["одобрено"] && !з["одобрение_действует"]) {
      // РАЗРЕШЕНИЕ ЕСТЬ, НО НЕ К ЭТОМУ ПЕРЕВОДУ. Реквизиты сменились после
      // него. Молчаливое «разрешено» здесь было бы худшей из возможных
      // надписей: выплата не уйдёт, а человек будет думать, что всё сделано.
      row.appendChild(el("div", "cmnote",
        T("Разрешение больше не действует: реквизиты изменились после него. "
          + "Нужно разрешить заново.")));
    }

    var кнопка = el("button", "cm1", T("Разрешить выплату"));
    кнопка.type = "button";
    кнопка.addEventListener("click", function () {
      кнопка.disabled = true;
      одобрить_выплату(з, кнопка);
    });
    row.appendChild(кнопка);
    return row;
  }

  async function одобрить_выплату(з, кнопка) {
    var р = з["реквизиты"] || {};
    // СПРАШИВАЕМ, ГЛЯДЯ НА ТО ЖЕ, ЧТО УЙДЁТ В БАНК. Подтверждение без суммы и
    // получателя — кнопка «да», а привычка нажимать её не читая переносится
    // потом на ту, где читать надо.
    var да = window.confirm(
      T("Разрешить выплату") + " " + з.amount_credits + " " + T("кр.") + "\n"
      + (р["имя"] || "?") + ", " + T("счёт …") + (р["хвост_счёта"] || "????") + "\n\n"
      + T("Разрешение перестанет действовать, если сумма или реквизиты изменятся."));
    if (!да) { кнопка.disabled = false; return; }
    try {
      // `approved_by` не посылаем: его подставляет дверь. Пошли мы его сами —
      // и браузер называл бы, кто одобрил.
      await api("POST", "/credits/payouts/" + encodeURIComponent(з.payout_id)
                + "/approve", { note: "" });
      say("system", T("Выплата"), T("Разрешено."));
      renderPayouts(true);
    } catch (e) {
      кнопка.disabled = false;
      say("system", T("Выплата"), reason(e));
    }
  }


  /* ── Журнал обращений: только оператору ───────────────────────────── */
  (function () {
    var b = document.getElementById("opsrefresh");
    // Явный вопрос человека спрашивает дверь ЗАНОВО, минуя память: нажали
    // «Обновить» — значит хотят свежий ответ, а не пересказ прежнего.
    if (b) b.addEventListener("click", function () { renderOps(true); });
  })();


  /* Панель показывает НЕ СВОЁ: метки, дела и объёмы всех людей. Открыта она
     не флагом в оболочке — оболочке верить нельзя, — а дверью: тем, кто не
     оператор, шлюз отвечает 404, и панель просто не появляется. Здесь мы
     всего лишь не рисуем то, чего нам не дали.

     Зачем она вообще. Без неё «742 вызова наружу против 195 местных»
     выяснялось запросом в терминале и выяснилось поздно: один заводила
     стоил 84% нагрузки за две недели. Число, которое некому увидеть, не
     защищает ни от чего. */
  async function renderOps(явно) {
    var panel = document.getElementById("opspanel");
    if (!panel) return;
    var rows = document.getElementById("opsrows");
    var cnt = document.getElementById("opscount");
    var память = памятьДвери("callers");

    // Дверь этому человеку уже отказала. Второй раз не спрашиваем: ответ
    // тот же, а стоит он ему записи в журнале отказов.
    if (память.отказала && !явно) { panel.hidden = true; return; }

    var свод;
    try {
      свод = await api("GET", "/ops/callers?hours=24");
    } catch (e) {
      if (e.status === 404) {
        // Путь не для этого человека. 404 вместо 403 здесь намеренный — так
        // дверь не подтверждает существование операторских путей, — и трогать
        // это нельзя. Молчим, не рисуем и больше не спрашиваем.
        память.отказала = true;
        panel.hidden = true;
        return;
      }
      // Не отказ, а неполадка. Пробовать снова стоит, поэтому «отказала» не
      // ставим.
      память.отказала = false;
      // НО ГОВОРИМ О НЕЙ ТОЛЬКО ТОМУ, КОГО ДВЕРЬ УЖЕ ПУСКАЛА. Иначе во время
      // всякого сбоя случайный посетитель увидел бы операторскую панель с
      // сообщением о неполадке — то есть узнал бы о ней ровно то, чего ему не
      // говорит дверь.
      if (!память.пускали) { panel.hidden = true; return; }
      панельНеОтветила(panel, rows, cnt, e);
      return;
    }
    память.пускали = true;
    память.отказала = false;
    panel.hidden = false;
    rows.innerHTML = "";
    cnt.textContent = T(T("обращений за сутки: ") + свод.вызовов +
                      T(" · наружу: ") + свод.наружу);

    свод.строки.slice(0, 40).forEach(function (r) {
      var d = el("div", "opsrow");
      d.appendChild(el("span", "who", r.кто));
      // Тревожное — СРАЗУ за именем, а не в хвосте строки. В хвосте оно
      // уезжало за край окна, и невидимым оказывалось ровно то, ради чего
      // экран заведён.
      if (r.отказов) d.appendChild(el("span", "bad", T("отказов ") + r.отказов));
      if (r.без_полномочия) {
        // Держится на умолчании кода, а не на записанном решении человека.
        d.appendChild(el("span", "none", T("без полномочия ") + r.без_полномочия));
      }
      d.appendChild(el("span", "n", r.вызовов + " · " + r.доля + "%"));
      d.appendChild(el("span", r.вынос === "remote" ? "out" : "",
                       r.вынос === "remote" ? "наружу" : "местная"));
      d.appendChild(el("span", "", r.модель));
      d.appendChild(el("span", "", (r.токенов / 1000).toFixed(1) + "k"));
      rows.appendChild(d);
    });

    if (!свод.строки.length) {
      rows.appendChild(el("div", "casenote", "За сутки обращений не было."));
    }
    await показатьСчётПоломок();
  }

  /* Сколько сообщений о поломках ждёт разбора — числом, в операторской панели.

     ПОЧЕМУ ЧИСЛО, А НЕ ПРОСТО КНОПКА. Команда `/разбор` есть, но набрать её
     можно, только помня, что она есть, — а вспоминают о списке жалоб тогда,
     когда уже жалуются вслух. Число отвечает на вопрос, которого человек не
     задавал: тот же довод, что у журнала обращений рядом («число, которое
     некому увидеть, не защищает ни от чего»).

     У СПИСКА СВОЯ ДВЕРЬ. Панель открыта ответом на `/ops/callers`, а список —
     на `/ops/reports`; совпадать они не обязаны. Отказ здесь панель не ломает
     и ничего не говорит: она не про поломки, и молчание тут честнее шума.

     СЧИТАЕМ `open`, А НЕ `new`, и это не мелочь. С 02.09.2026 лекарь сам
     отмечает разобранное `taken`. Спрашивай мы по-прежнему только новые,
     число падало бы до нуля ровно тогда, когда жалобы РАЗОБРАНЫ, НО НЕ
     ЗАКРЫТЫ, — и «разбирать нечего» стало бы неправдой в самый неудачный
     миг. Список за той же кнопкой считает ту же пару; разойдись они, два
     узла одного экрана говорили бы разное.

     Ноль показываем тоже: «разбирать нечего» — это ответ, а не пустота. */
  var счётПоломокСпрошен = 0;

  async function показатьСчётПоломок() {
    var кн = document.getElementById("opsreports");
    if (!кн) return;
    // ОТВЕТ, ПРИШЕДШИЙ НЕ ПОСЛЕДНИМ, В УЗЕЛ НЕ ПИШЕМ. Два решения подряд
    // шлют два запроса; придёт первый ответ вторым — и панель покажет
    // большее, уже неверное число. Само оно исправится только со следующим
    // обновлением, а до тех пор врёт ровно там, где обещало не врать.
    var мой = ++счётПоломокСпрошен;
    var свод;
    try {
      свод = await api("GET", "/ops/reports?state=open&limit=1");
    } catch (e) {
      if (мой === счётПоломокСпрошен) кн.hidden = true;
      return;
    }
    if (мой !== счётПоломокСпрошен) return;
    // Строка целиком, а не склейка: число отдельным узлом, чтобы оно могло
    // быть моноширинным, а фраза до него — переводиться словарём как фраза.
    кн.innerHTML = "";
    кн.appendChild(el("span", null, "поломки без решения: "));
    кн.appendChild(el("b", null, String(свод.всего || 0)));
    кн.hidden = false;
    // Обработчик вешаем ОДИН раз: «Обновить» зовёт renderOps заново, и без
    // этой отметки каждое нажатие добавляло бы ещё один — список печатался бы
    // столько раз, сколько раз человек обновлял панель.
    if (!кн.getAttribute("data-bound")) {
      кн.setAttribute("data-bound", "1");
      кн.addEventListener("click", async function () {
        try { await командаРазбор(); }
        catch (e2) { сказатьКомандой(T("Не вышло: ") + reason(e2)); }
      });
    }
  }

  /* ── Обзор цен расширением браузера ───────────────────────────────────
     ПОЧЕМУ ЭТО ДЕЛАЕТ РАСШИРЕНИЕ, А НЕ МЫ. Наш сервер на площадки не ходит и
     не может: у него нет ни сессии человека, ни права ею пользоваться. А
     безголовый браузер витрина не пускает — замерено 23.08.2026, Вайлдберриз
     отвечает нашему контейнеру страницей «Проверяем браузер». Браузер человека
     она не отличит: отличать нечего.

     ПАНЕЛЬ ПОКАЗЫВАЕТСЯ, ТОЛЬКО ЕСЛИ РАСШИРЕНИЕ ОБЪЯВИЛОСЬ. Кнопка, которая
     ничего не сделает, хуже отсутствующей: человек нажмёт и решит, что сломан
     сервис. Расширение кладёт своё имя в атрибут корня (announce.js); нет
     атрибута — нет и панели. */
  async function renderОбзорЦен() {
    var panel = document.getElementById("expanel");
    if (!panel) return;
    var имяРасширения = document.documentElement.dataset.fixarExt || "";
    if (!имяРасширения || !window.chrome || !chrome.runtime) {
      panel.hidden = true;
      return;
    }
    panel.hidden = false;
  }

  (function () {
    var кнопка = document.getElementById("exrun");
    if (кнопка) кнопка.addEventListener("click", собратьПредложения);
  })();

  async function собратьПредложения() {
    var поле = document.getElementById("exquery");
    var заметка = document.getElementById("exnote");
    var строки = document.getElementById("exrows");
    var имяРасширения = document.documentElement.dataset.fixarExt || "";
    var запрос = (поле && поле.value || "").trim();
    строки.innerHTML = "";
    if (!запрос) { заметка.textContent = T("Напишите, что искать."); return; }
    if (!имяРасширения) { заметка.textContent = T("Расширение не установлено."); return; }

    заметка.textContent = T("Прошу задание…");
    var задание;
    try {
      // НАПРАВЛЕНИЕ НАЗВАНО, и от этого зависит судьба найденного: неличное
      // ляжет в свод ИМЕННО ЭТОГО направления и достанется следующему
      // спросившему. Без направления свода нет, и подбор пропадает вместе с
      // вкладкой — как было до 31.08.2026.
      задание = await api("POST", "/extension/job",
                          { query: запрос, platforms: ["wildberries"],
                            domain: "household" });
    } catch (e) {
      // Названо своим именем: без ключа подписи служба отвечает 503, и это не
      // «ничего не нашлось», а «мы не настроены».
      заметка.textContent = T(T("Задание не выдано: ") + (e && e.message || e));
      return;
    }

    заметка.textContent = T("Расширение открывает площадки…");
    var итог = await поручитьРасширению(имяРасширения, задание);
    if (итог && итог.ошибка) { заметка.textContent = T(итог.ошибка); return; }

    var улов;
    try {
      улов = await api("GET", "/extension/catch/" + задание.job_id);
    } catch (e) {
      // 404 здесь — «расширение ещё не принесло», и это НЕ «на рынке пусто».
      заметка.textContent = T(T("Расширение ничего не принесло: ") + (e && e.message || e));
      return;
    }
    показатьУлов(улов, заметка, строки);
  }

  function поручитьРасширению(имяРасширения, задание) {
    return new Promise(function (готово) {
      try {
        chrome.runtime.sendMessage(имяРасширения, {
          что: "собрать-предложения",
          payload: задание.payload,
          sig: задание.sig,
        }, function (ответ) {
          // lastError читаем и глотаем: «расширение не ответило» — обычное
          // состояние, а не поломка кабинета.
          var беда = chrome.runtime.lastError;
          готово(беда ? { ошибка: T("Расширение не ответило: ") + беда.message }
                      : (ответ || {}));
        });
      } catch (e) {
        готово({ ошибка: T("Расширение не отозвалось: ") + (e && e.message || e) });
      }
    });
  }

  function показатьУлов(улов, заметка, строки) {
    var состояния = улов.platform_status || {};
    var словами = Object.keys(состояния).map(function (п) {
      return п + ": " + названиеСостояния(состояния[п]);
    }).join(" · ");
    var предложения = улов.offers || [];

    // Состояние по КАЖДОЙ площадке, а не только число находок: «нигде нет» и
    // «две из четырёх не ответили» — разные ответы, и решать по ним разное.
    заметка.textContent = T(предложения.length
      ? T("Нашлось: ") + предложения.length + (словами ? " · " + словами : "")
      : (словами || "Ничего не собрано."));

    предложения.sort(function (a, b) { return a.total_price - b.total_price; });
    предложения.slice(0, 20).forEach(function (п) {
      var стр = document.createElement("div");
      стр.className = "crrow";
      var ссылка = document.createElement("a");
      ссылка.href = п.url;
      ссылка.target = "_blank";
      ссылка.rel = "noopener noreferrer";
      ссылка.textContent = T(п.title);
      var хвост = document.createElement("span");
      хвост.textContent = T(" — " + п.total_price + " ₽" +
        (п.seller_name ? " · " + п.seller_name : "") +
        (п.available ? "" : T(" · нет в наличии")));
      стр.appendChild(ссылка);
      стр.appendChild(хвост);
      строки.appendChild(стр);
    });

    // Порог совпадения — из shared/schemas/commerce.py. Ниже него объявлять
    // победителя нельзя: это может оказаться другой товар.
    var неуверенных = предложения.filter(function (п) {
      return (п.match_confidence || 0) < 0.7;
    }).length;
    if (неуверенных) {
      var о = document.createElement("div");
      о.className = "empty";
      о.textContent = T(T("Совпадение по названию, а не по штрихкоду: ") +
        неуверенных + T(" из ") + предложения.length +
        T(" могут оказаться другим товаром. Победителя не называем."));
      строки.appendChild(о);
    }
  }

  function названиеСостояния(с) {
    var словарь = {
      ok: "собрано", empty: "ничего нет", partial: "собрано не всё",
      captcha: "площадка просит подтвердить, что вы не робот",
      blocked: "площадка не пустила", unreachable: "не открылась",
      layout_changed: "разметка изменилась", not_built: "не поддерживается",
      unknown: "неизвестно",
    };
    return словарь[с] || с;
  }

  /* ── Расход кредитов по площадке: только оператору ────────────────── */
  (function () {
    var b = document.getElementById("crrefresh");
    if (b) b.addEventListener("click", function () { renderCredits(true); });
  })();

  /* Панель показывает НЕ СВОЁ: сколько потратил каждый человек. Открыта, как
     и соседняя, дверью — тому, кто не оператор, шлюз отвечает 404, и панель
     не появляется. Здесь мы всего лишь не рисуем то, чего нам не дали.

     Зачем она. Свой остаток человек видел давно, расход по делу — тоже.
     Сводного не было НИГДЕ: вопрос «кто сколько тратит» решался запросом в
     терминале, то есть каждый раз немного по-другому. */
  async function renderCredits(явно) {
    var panel = document.getElementById("crpanel");
    if (!panel) return;
    var rows = document.getElementById("crrows");
    var cnt = document.getElementById("crcount");
    var память = памятьДвери("credits");

    // Как и у соседней панели: отказ двери запоминается, и второй раз её об
    // одном и том же не спрашивают.
    if (память.отказала && !явно) { panel.hidden = true; return; }

    var свод;
    try {
      свод = await api("GET", "/ops/credits");
    } catch (e) {
      if (e.status === 404) {
        память.отказала = true;
        panel.hidden = true;
        return;
      }
      память.отказала = false;
      if (!память.пускали) { panel.hidden = true; return; }
      панельНеОтветила(panel, rows, cnt, e);
      return;
    }
    память.пускали = true;
    память.отказала = false;
    panel.hidden = false;
    rows.innerHTML = "";
    cnt.textContent = T(T("людей: ") + свод.людей + T(" · подарено: ") + свод.подарено +
                      T(" · потрачено: ") + свод.потрачено);

    // Счёт площадки — ОТДЕЛЬНОЙ строкой и первым. Он не человек: на него
    // ложится расход маршрутизатора, который работает до дела. Смешать его с
    // людьми значит получить «средний расход на человека», в котором главная
    // строка — не человек.
    var пл = el("div", "crrow head");
    пл.appendChild(el("span", "who", "счёт площадки"));
    пл.appendChild(el("span", "n", String(свод.площадка)));
    пл.appendChild(el("span", "note", "маршрутизация до дела; минус по замыслу"));
    rows.appendChild(пл);

    if (свод.непокрытых) {
      var д = el("div", "crrow");
      д.appendChild(el("span", "who", "непокрытых списаний"));
      д.appendChild(el("span", "bad", String(свод.непокрытых)));
      д.appendChild(el("span", "note",
        "учёт считает и не мешает: это долг, а не ошибки"));
      rows.appendChild(д);
    }

    (свод.статьи || []).forEach(function (с) {
      var д = el("div", "crrow");
      д.appendChild(el("span", "who", с.статья));
      д.appendChild(el("span", "n", String(с.кредитов)));
      д.appendChild(el("span", "note", T("списаний ") + с.списаний));
      rows.appendChild(д);
    });

    rows.appendChild(el("div", "crsep", "кто сколько потратил"));
    (свод.люди || []).forEach(function (ч) {
      var д = el("div", "crrow");
      д.appendChild(el("span", "who", ч.кто));
      д.appendChild(el("span", "n", String(ч.потрачено)));
      д.appendChild(el("span", "note", T("остаток ") + ч.остаток +
                                       T(" · начислено ") + ч.начислено));
      rows.appendChild(д);
    });

    // Обрезку НАЗЫВАЕМ. Молча показанные первые пятьдесят читаются как
    // «всего пятьдесят», и решение принимается по неполной картине, о
    // неполноте которой никто не знает.
    if (свод.показано < свод.людей) {
      rows.appendChild(el("div", "casenote",
        T("Показаны ") + свод.показано + T(" из ") + свод.людей +
        T(" — самые расходующие.")));
    }
    if (!свод.людей) {
      rows.appendChild(el("div", "casenote", "Пока никто ничего не потратил."));
    }
  }

  /* ── Проводник: показать, где что лежит ───────────────────────────────

     ЗАЧЕМ. Онбординга не было вовсе: новый человек видел пустой экран и
     строку «Дело появится, как только вы начнёте». Правда, но она не отвечает
     ни на один его вопрос — что это за место, кто с ним говорит и с чего
     начать. Цена видна в числах: на 21.08.2026 все 185 привязок входа сидят
     на нулевом уровне доверия, а подать объявление требует первого.

     НАЗВАНИЯ РАЗДЕЛОВ ЧИТАЮТСЯ СО СТРАНИЦЫ, а не хранятся здесь. Свой список
     имён разошёлся бы с настоящим на первом же переименовании — ровно как это
     уже было с формой объекта, где поля дублировались в оболочке.

     ШАГ, КОТОРОГО НЕТ НА ЭКРАНЕ, ПРОПУСКАЕТСЯ МОЛЧА. Подсказка, указывающая в
     пустоту, хуже отсутствующей: человек ищет то, чего нет, и решает, что
     сломался он. Разделы тут появляются по обстоятельствам — у юриста нет
     объектов, у гостя нет кабинета, — и это нормальное состояние. */

  //: К чему крепиться и что сказать. Имя раздела берётся из самого элемента.
  var ШАГИ_ПРОВОДНИКА = [
    {id: "me", что: "Здесь видно, кем вы вошли и насколько твёрдо это " +
       "подтверждено. Пока подтверждения нет, объявление можно написать, но " +
       "нельзя показать людям — иначе к вашим будущим клиентам вышел бы кто " +
       "угодно. Подтверждение разовое: телефон или Telegram, минута."},
    {id: "credits", что: "Разговор со мной стоит кредитов. Новым дарим 10 000 " +
       "один раз — этого хватает надолго; кончатся — пополните здесь же."},
    {id: "practicehead", что: "Кабинет — ваше рабочее место в направлении. В " +
       "нём живут клиенты, расписание и объявления. Направлений может быть " +
       "несколько, и они не смешиваются: юрист, который ещё и сдаёт " +
       "квартиру, заводит два кабинета."},
    {id: "objectshead", что: "Объект — то, вокруг чего собирается дело. " +
       "Квартира переживает всех своих жильцов: она сдавалась двадцать раз, и " +
       "каждый наём — отдельное дело. При заведении спрошу только " +
       "обязательное, остальное спрячу за «ещё поля»."},
    {id: "clientshead", что: "Картотека — люди, с которыми вы работаете. " +
       "Заводится сама из дел, но можно и руками."},
    {id: "boardcnt", что: "Объявление — то, что увидят люди: чем вы " +
       "занимаетесь, на каких условиях и чего не делаете. Последнее не " +
       "придирка: границы, названные заранее, избавляют вас от клиентов, " +
       "которым вы всё равно не подойдёте. Путь такой: черновик, подача, " +
       "проверка площадкой, публикация. Решение о публикации принимает " +
       "площадка — отказ придёт с причиной, и её можно исправить."},
    {id: "calhead", что: "Ближайшее — что у вас на днях: записи, сроки, " +
       "напоминания по делам."},
    {id: "composer", что: "А это главное место: расскажите своими словами, " +
       "что нужно. Дело соберётся из разговора само — заполнять ничего не " +
       "надо. Если застрянете, скажите «покажи ещё раз»."}
  ];

  var ПРОВОДНИК_ПОКАЗАН = "fixar.tour.shown";
  var проводникИдёт = false;

  //: Имя раздела — из самого элемента или из его заголовка. Пусто — значит
  //: назвать нечем, и подпись просто не печатается: выдумывать имя нельзя.
  function имяРаздела(эл) {
    var текст = (эл.textContent || "").trim();
    if (текст && текст.length <= 40) return текст;
    var шапка = эл.querySelector(".cnt");
    return шапка ? (шапка.textContent || "").trim() : "";
  }

  function виден(эл) {
    if (!эл) return false;
    var r = эл.getBoundingClientRect();
    return r.width > 0 && r.height > 0;
  }

  function закрытьПроводника() {
    проводникИдёт = false;
    var б = document.getElementById("tourbox");
    if (б) б.remove();
    var п = document.querySelector(".tourhi");
    if (п) п.classList.remove("tourhi");
  }

  async function проводник() {
    if (проводникИдёт) return;
    проводникИдёт = true;
    try { localStorage.setItem(ПРОВОДНИК_ПОКАЗАН, "1"); } catch (e) { /* переживём */ }

    // Отбираем ДО показа: так число «шаг N из M» честное, а не выдуманное.
    var годные = ШАГИ_ПРОВОДНИКА
      .map(function (ш) { return {ш: ш, эл: document.getElementById(ш.id)}; })
      .filter(function (п) { return виден(п.эл); });
    if (!годные.length) {
      say("bot", "Ф", "Показывать пока нечего: разделы появятся, когда " +
          "понадобятся. Расскажите словами, что нужно, — я разберусь.");
      проводникИдёт = false;
      return;
    }

    var i = 0;
    function шаг() {
      if (!проводникИдёт) return;
      закрытьПодсветку();
      if (i >= годные.length) { закрытьПроводника(); return; }
      var п = годные[i];
      п.эл.classList.add("tourhi");
      п.эл.scrollIntoView({block: "center", behavior: "smooth"});

      var б = document.getElementById("tourbox") || el("div", "tourbox");
      б.id = "tourbox";
      б.innerHTML = "";
      var имя = имяРаздела(п.эл);
      if (имя) б.appendChild(el("div", "tourname", имя));
      б.appendChild(el("div", "tourtext", п.ш.что));
      var низ = el("div", "tourbtns");
      низ.appendChild(el("span", "tourcount", (i + 1) + T(" из ") + годные.length));
      var дальше = el("button", "tournext",
                      i + 1 < годные.length ? "Дальше" : "Понятно");
      дальше.type = "button";
      дальше.addEventListener("click", function () { i += 1; шаг(); });
      var хватит = el("button", "tourstop", "Хватит");
      хватит.type = "button";
      хватит.addEventListener("click", закрытьПроводника);
      низ.appendChild(дальше);
      низ.appendChild(хватит);
      б.appendChild(низ);
      document.body.appendChild(б);

      // Возле раздела, а не поверх экрана: окно поверх работы превращает
      // объяснение в препятствие.
      var r = п.эл.getBoundingClientRect();
      var сверху = r.bottom + 8 + б.offsetHeight > window.innerHeight;
      б.style.top = (сверху ? Math.max(8, r.top - б.offsetHeight - 8)
                            : r.bottom + 8) + "px";
      б.style.left = Math.max(8, Math.min(r.left,
                     window.innerWidth - б.offsetWidth - 8)) + "px";
    }

    function закрытьПодсветку() {
      var п = document.querySelector(".tourhi");
      if (п) п.classList.remove("tourhi");
    }

    шаг();
  }

  /* ── Список дел ───────────────────────────────────────────────────── */

  /* Дело было одно: state.caseId держал последнее, и вернуться к прежнему
     разговору человек не мог. Список отдаёт служба, уже отсортированный по
     последнему изменению, — сортировать на странице значило бы отсортировать
     первые двести и назвать это порядком. */

  /* АДРЕС ДЕЛА.

     Маршрутизации в оболочке не было вовсе: адресная строка всегда говорила
     просто «agrigate.pro», какое бы дело ни было открыто. Из этого следовало
     три вещи. Делом нельзя поделиться ссылкой и нельзя положить его в
     закладки. Кнопка «Назад» не работала. И какое дело открыто, знал ОДИН
     ключ localStorage, общий на все вкладки: открыл дело Б во второй вкладке —
     перезагрузка первой открывала дело Б.

     Адрес чинит третье по сути, а не заплаткой: у вкладки появляется
     СОБСТВЕННАЯ память о том, где она была, и перезагрузка возвращает её
     туда, а не туда, куда ушла соседняя.

     РЕШЁТКА, А НЕ ПУТЬ. `#/case/…` не доезжает до сервера — значит ни Bunny,
     ни public_gateway, ни deploy-site.sh трогать не нужно. Путь `/case/{id}`
     потребовал бы правила переписывания в пул-зоне Bunny, а это конфигурация
     вне git: откатить её нечем и увидеть в истории нельзя. */
  var МАРШРУТ = /^#\/case\/([A-Za-z0-9_-]{1,120})$/;

  /* Адрес поменяли МЫ САМИ — разбирать его обратно незачем.

     Без этой отметки вышел бы круг: openCase → rememberCase → писатьАдрес →
     hashchange → openCase. Круг оборвался бы на раннем возврате по тому же
     делу, но полагаться на это нельзя: ранний возврат — про удобство, а не
     про целость. */
  var свойХод = false;

  function читатьАдрес() {
    var m = МАРШРУТ.exec(location.hash || "");
    return m ? m[1] : "";
  }

  function писатьАдрес(id) {
    var надо = id ? "#/case/" + encodeURIComponent(id) : "#/";
    if (location.hash === надо) return;
    свойХод = true;
    location.hash = надо;
  }

  /* Адрес поменяли снаружи: нажали ссылку, «Назад», закладку, вставили в
     строку. Открываем то, что там названо. */
  window.addEventListener("hashchange", function () {
    if (свойХод) { свойХод = false; return; }
    var id = читатьАдрес();
    // Сравнение с пустой строкой, а не с null: при отсутствии дела caseId
    // равен null, и без `|| ""` условие не сработало бы — «Назад» из дела в
    // общий разговор чистил бы ленту второй раз на ровном месте.
    if (id === (state.caseId || "")) return;
    if (id) openCase(id); else toGeneral();
  });

  function savedCase() {
    try { return localStorage.getItem(CASE_KEY) || ""; } catch (e) { return ""; }
  }

  function rememberCase(id) {
    try {
      if (id) localStorage.setItem(CASE_KEY, id);
      else localStorage.removeItem(CASE_KEY);
    } catch (e) { /* приватный режим — переживём, это удобство, а не данные */ }
    /* Адрес пишем ЗДЕСЬ ЖЕ, а не в шести местах смены дела по отдельности.
       Это единственная точка, где оболочка говорит «теперь открыто вот это», —
       значит и адрес разойтись с ней не может по устройству, а не по
       внимательности. */
    писатьАдрес(id);
  }

  /* Дело человека или он в нём лишь участник. Список отдаёт и то и другое —
     это многоучастниковость, — но ЧИТАТЬ дело шлюз даёт только владельцу.
     Обходить это нечем и не нужно: правило верное, врать о нём нельзя. */
  function isMine(c) {
    return c.owner_id === state.principal;
  }

  /* Пилюли списка дел: состояние и вид.
     
     Отбор идёт ПО УЖЕ ПОЛУЧЕННОМУ списку, а не запросом на сервер. Причина
     не в экономии: список у юриста — десятки дел, они уже в руках, и поход
     на сервер за каждой пилюлей превратил бы мгновенный отбор в ожидание.
     Область жизни (scope) осталась серверной — она пришла раньше и режет
     выдачу до сотен строк, а не до десятков.

     Число рядом с пилюлей считается по тому же списку: пилюля без числа
     заставляет нажать, чтобы узнать, есть ли за ней что-нибудь. */
  var СОСТОЯНИЯ = [
    { key: "", title: "Все" },
    { key: "active", title: "В работе" },
    { key: "waiting", title: "Ждут" },
    { key: "closed", title: "Закрытые" },
    { key: "archived", title: "Архив" }
  ];
  var ВИДЫ = {
    case: "дела", deal: "сделки", session: "сессии", task: "задачи",
    treatment: "лечение", course: "курсы", construction: "стройка",
    renovation: "ремонт", relocation: "переезды", trip: "поездки",
    dispute: "споры", administration: "приём", funeral: "похороны",
    seance: "сеансы"
  };
  var фильтр = { state: "", kind: "" };

  function отобрать(list) {
    return list.filter(function (c) {
      if (фильтр.state && (c.state || "active") !== фильтр.state) return false;
      if (фильтр.kind && (c.kind || "case") !== фильтр.kind) return false;
      return true;
    });
  }

  function renderPills(list) {
    var box = document.getElementById("casepills");
    if (!box) return;
    box.innerHTML = "";

    function пилюля(текст, число, включена, нажать) {
      var b = el("button", "pill" + (включена ? " on" : ""));
      b.type = "button";
      b.appendChild(document.createTextNode(текст));
      if (число !== null) b.appendChild(el("span", "n", String(число)));
      b.addEventListener("click", нажать);
      box.appendChild(b);
    }

    СОСТОЯНИЯ.forEach(function (с) {
      var n = с.key
        ? list.filter(function (c) { return (c.state || "active") === с.key; }).length
        : list.length;
      // Пустое состояние не показываем вовсе — кроме выбранного: иначе
      // человек не поймёт, почему список пуст, и не найдёт, чем это отменить.
      if (!n && с.key && фильтр.state !== с.key) return;
      пилюля(с.title, n, фильтр.state === с.key, function () {
        фильтр.state = фильтр.state === с.key ? "" : с.key;
        renderCases();
      });
    });

    // Виды показываем только те, что у человека есть, и только если их
    // больше одного: пилюля «дела», когда все дела и есть дела, ничего не
    // сообщает и занимает строку.
    var виды = {};
    list.forEach(function (c) { виды[c.kind || "case"] = (виды[c.kind || "case"] || 0) + 1; });
    var имена = Object.keys(виды);
    if (имена.length > 1) {
      имена.sort().forEach(function (k) {
        пилюля(ВИДЫ[k] || k, виды[k], фильтр.kind === k, function () {
          фильтр.kind = фильтр.kind === k ? "" : k;
          renderCases();
        });
      });
    }

    /* «Завести новое» — тоже пилюля, но ДЕЙСТВИЕ, а не отбор.
       Остальные пилюли сужают список; эта заводит дело. Стоять она может
       только в одном ряду с ними — так просил владелец, — и тогда единственное,
       что отличает действие от отбора, это вид. Поэтому она красноватая и
       стоит последней: нажать её вместо «Архив» не выйдет по цвету, а не по
       памяти о порядке. */
    var завести = el("button", "pill act");
    завести.type = "button";
    завести.appendChild(document.createTextNode("Завести новое"));
    завести.addEventListener("click", function () { openMake(); });
    box.appendChild(завести);
  }

  async function renderCases() {
    var box = document.getElementById("caselist");
    var rows = document.getElementById("caserows");
    var cnt = document.getElementById("casescount");
    if (!state.principal) { box.hidden = true; return; }

    var list;
    try {
      list = await api("GET", "/principals/" + state.principal + "/cases");
    } catch (e) {
      // Молчать нельзя: пустой список и несостоявшийся запрос выглядят
      // одинаково, а означают противоположное.
      state.casesOk = false;
      box.hidden = false;
      rows.innerHTML = "";
      cnt.textContent = T("дела");
      rows.appendChild(el("div", "casenote", T("Список дел не пришёл: ") + e.message));
      return;
    }

    // Список без фильтра — то, по чему потом сверяется сохранённое дело.
    // Отфильтрованный для этого не годится: дела вне выбранной области в нём
    // отсутствуют, и сохранённое было бы объявлено чужим.
    state.cases = list; state.casesOk = true;

    // Ни одного дела и ни одного открытого — списку нечего показывать, а
    // кнопке «новое дело» нечего создавать: разговор и так начнёт новое.
    if (!list.length && !state.caseId && !state.caseCount) {
      box.hidden = true;
      return;
    }
    box.hidden = false;
    rows.innerHTML = "";
    // Пилюли строятся по ПОЛНОМУ списку, а список рисуется по отобранному:
    // иначе числа на пилюлях менялись бы от собственного нажатия.
    renderPills(list);
    var видно = отобрать(list);
    cnt.textContent = T(T("дел: ") + видно.length +
                      (видно.length !== list.length ? T(" из ") + list.length : ""));

    if (!list.length) {
      rows.appendChild(el("div", "casenote",
        "В этой области дел нет. Пилюля «Все» вернёт остальные."));
      return;
    }
    if (!видно.length) {
      rows.appendChild(el("div", "casenote",
        "Под этот отбор дел нет — снимите пилюлю."));
      return;
    }

    видно.forEach(function (c) {
      var mine = isMine(c);
      /* НАСТОЯЩАЯ ССЫЛКА, А НЕ КНОПКА — и это приглашение во вторую вкладку.

         У <a href> браузер САМ даёт то, чего у <button> нет и чего нашим
         кодом не добыть: Cmd/Ctrl и средний щелчок открывают дело в соседней
         вкладке, правый — контекстное меню «Открыть в новой вкладке»,
         «Копировать ссылку». Плюс «Назад» и закладки. Нашего кода это не
         требует вовсе: щелчок меняет решётку в адресе, а слушатель
         hashchange открывает дело.

         Поэтому здесь НЕТ обработчика нажатия. Он был бы вторым путём к тому
         же — и первым же местом, где два пути разойдутся. */
      var b = el("a", "case1" + (c.id === state.caseId ? " on" : "") +
                      (mine ? "" : " alien"));
      b.href = "#/case/" + encodeURIComponent(c.id);
      /* Подсказка НАТИВНАЯ (title), а не своя. Владелец говорил: «при
         наведении ничего не всплывает» — своих всплывашек в оболочке нет, а
         эту рисует сам браузер, и она появляется всегда. */
      b.title = T("Открыть дело. Cmd (⌘) или Ctrl со щелчком — открыть в " +
                "соседней вкладке, чтобы вести два дела разом.");
      b.appendChild(el("span", "t", c.title || "Без названия"));
      // Области в пометках нет: ось снята с экрана 03.09.2026.
      var marks = [];
      if (c.state && c.state !== "active") marks.push(c.state);
      marks.push(when(c.updated_at));
      // Дело, заведённое другим, помечаем — но НЕ запираем. Прежде здесь
      // стоял отказ «читать дело шлюз даёт только владельцу»; это была
      // неправда: дверь пускает участника с правом читать, и проверено это
      // живым вызовом. Оболочка предсказывала отказ, которого не бывает, и
      // человек не мог открыть дело, которое ему открыто.
      if (!mine) marks.push("ведёт другой");
      b.appendChild(el("span", "m", marks.filter(Boolean).join(" · ")));
      rows.appendChild(b);
    });
  }

  /* Открыть дело: подставить его и восстановить разговор из журнала.
     Реплики берутся из событий kind="dialog" — того же журнала, из которого
     собеседник берёт нить. Чего в журнале нет, того мы не покажем: выдумать
     недостающую реплику значит показать разговор, которого не было. */
  /* УЙТИ С ДЕЛА — прежде чем войти в следующее.

     Уборка стояла В КОНЦЕ openCase, после того как новое дело уже прочитано и
     нарисовано. Поэтому она стирала не прежнее, а ТОЛЬКО ЧТО ПРОЧИТАННОЕ:

       • вид и стадию сделки, взятые из карточки сорока строками выше. Стадия
         была видна ровно до следующей перерисовки строки места — то есть до
         первого же ответа, — и исчезала навсегда. Ось стадий (docs/STAGE_AXIS.md)
         показывала себя на секунду и умолкала;

       • имя работника гасилось ПОСЛЕ renderWhere, а больше оно нигде не
         выставляется, кроме ответа хода. Значит строка «ведёт» при открытии
         дела Б печатала работника дела А — правдоподобно и неверно.

     И то, что не убиралось ВОВСЕ и уезжало в чужое дело:

       • приложенные файлы. Байты уже в хранилище, материал привязан к ПРЕЖНЕМУ
         делу, но ссылка vault:{id} уходила частью следующего сообщения — то
         есть в дело Б попадал документ дела А. Человек этого не видел: видимые
         строки живут в ленте, а лента при переходе очищается. Комментарий в
         toGeneral уверял, что приложенное убрал showEmpty; showEmpty прячет
         короб #files и к самому списку не прикасается;

       • намерение сменить направление. Гасилось ТОЛЬКО после удачного хода.
         Нажал «не то направление» в деле А, передумал, открыл дело Б — и
         первое же сообщение переводит дело Б, а в журнал ложится объяснение
         про дело А. Служба принимает молча: она требует причину, а не
         совпадение дела;

       • холст. Закрывался только крестиком и открытием следующего файла, а
         кнопка «Сохранить» на нём пишет по ТЕКУЩЕМУ делу. Документ дела А
         висел над разговором дела Б и сохранялся в Б с родословной из А;

       • счётчик ожидания очереди. Обнулялся только внутри renderRun, поэтому
         дело, открытое после долгого ожидания, начинало счёт не с нуля.

     ПОЧЕМУ НЕ ПЕРВОЙ СТРОКОЙ openCase. Там стоит ранний возврат по тому же
     делу и чтение карточки, отвечающее 403, 410 или 503 и выходящее, не сменив
     дела. Убравшись до них, мы стирали бы приложенное, холст и намерение у
     ТОГО ЖЕ САМОГО дела — от одного лишнего щелчка по уже открытой строке.
     Поэтому вызов стоит после удачного чтения, и только там.

     На одном деле всё это незаметно. Владелец назвал публику: практик, ведущий
     десять дел разом, — там переход между делами случается по десять раз на
     дню, и каждый из них тащил за собой хвост предыдущего. */
  function покинутьДело() {
    // Общие таблицы — тоже принадлежность ДЕЛА: грид и его частый опрос не
    // должны пережить переход в другое дело или в общий разговор.
    покинутьТаблицыДела();
    /* Окно переписки принадлежит ДЕЛУ, а не странице. Оставить его открытым
       при переходе — способ написать не туда: шапка сменится, нить нет. */
    closeThread();
    closeCanvas();
    pendingFiles = [];
    state.rerouteTo = null;
    state.rerouteWhy = "";
    state.agentTo = null;
    state.agentWhy = "";
    state.caseAgentTitle = "";
    state.dealKind = "";
    state.dealStage = "";
    state.dealStageBy = "default";
    state.runKind = null;
    state.очередьЖдём = 0;
    if (state.runWatch) { clearTimeout(state.runWatch); state.runWatch = null; }
    var полеЗапроса = document.getElementById("runquery");
    if (полеЗапроса) полеЗапроса.value = "";
    /* Панель схемы тоже принадлежит ДЕЛУ. В ней живёт разобранный план с
       кнопкой «Записать»: оставить её при переходе — способ записать план
       дела A в дело B, потому что дело кнопка берёт в момент нажатия.
       Кнопка теперь и сама сверяется (см. предложитьВетви), но панель, у
       которой шапка от прежнего дела, врёт и без нажатия. */
    var описаниеСхемы = document.getElementById("sxdesc");
    if (описаниеСхемы) { описаниеСхемы.textContent = ""; описаниеСхемы.hidden = true; }
    state.ветвиРаскрыты = undefined;
  }

  async function openCase(id) {
    if (id === state.caseId) return;
    var c;
    try {
      c = await api("GET", "/cases/" + id);
    } catch (e) {
      if (e.status === 403) {
        // Настоящий отказ бывает: участника могли вывести из дела или дать
        // ему право только комментировать. Причину называет дверь — её и
        // показываем, вместо того чтобы придумывать своё объяснение.
        сорвалось(T("Это дело сейчас не открыть: "), e);
      } else if (e.status === 410) {
        // Надгробие. Дело было и удалено — делать вид, что его не существовало,
        // перед человеком, который его читал, нельзя.
        say("bot", "Ф", "Это дело удалено навсегда. Восстановить его нечем.");
      } else if (e.status === 503) {
        // Соседняя ветка (410, «дело удалено навсегда») — ФАКТ О ДЕЛЕ, и
        // говорит его помощник. Эта — про нас, и говорит страница.
        сорвалось(T("Дело сейчас не открыть: служба дел не отвечает. " +
                    "Это не про ваши права и не значит, что дело пропало — " +
                    "попробуйте через минуту."), null);
      } else {
        сорвалось(T("Дело не открылось: "), e);
      }
      return;
    }

    // Дело прочитано — теперь и только теперь прежнее можно отпускать.
    покинутьДело();
    state.caseId = c.id;
    state.caseTitle = c.title || "";
    // Состав дела запоминаем: по нему подписываются чужие реплики в журнале.
    // Отсюда, а не отдельным запросом, — состав уже приехал в карточке дела.
    state.caseParticipants = c.participants || [];
    /* КТО ВЕДЁТ И НА КАКОМ ОСНОВАНИИ. Дело хранит и то и другое с самого
       начала, а человек не видел НИ РАЗУ: все ответы подписаны «Ф», и
       узнать, что работника вообще выбирали, было неоткуда.

       А выбор настоящий: у подтверждённого человека в 19 парах
       направление×сторона из 30 допущено больше одного, и между ними решает
       модель, читая обращение. Основание она записывает — «выбран по
       обращению: …», — и оно лежало в деле мёртвым полем. */
    state.caseAgentId = c.selected_agent_id || "";
    state.caseAgentWhy = c.selected_agent_reason || "";
    // Направление ДЛЯ ПОКАЗА и для стадии. Отдельно от state.domain, который
    // гасится намеренно и служит маршрутизации: смешать их значило бы вернуть
    // разговор агенту прежнего дела.
    state.caseDomain = c.domain || "";
    state.dealKind = c.deal_kind || "";
    state.dealStage = c.deal_stage || "";
    state.dealStageBy = c.deal_stage_source || "default";
    rememberCase(c.id);
    // Есть ли у дела ПЛАН: без закреплённого шаблона прогону нечего
    // исполнять, и предлагать поручение значило бы предлагать действие,
    // которое обязано не сработать. Такие дела на проде есть.
    state.caseHasPlan = !!c.template_version;
    /* КУПЛЕННАЯ РАБОТА. Держим целиком, а не один признак: короб приёмки
       говорит и цену, и исход — «принято и оплачено» отличается от «принято,
       а списание не прошло», и человеку надо видеть, какое из двух. */
    state.caseРабота = {
      charge_on: c.charge_on || "",
      kopecks: c.tariff_price_kopecks || 0,
      accepted_at: c.accepted_at || null,
      rejected_at: c.rejected_at || null,
      reject_note: c.reject_note || "",
      paid_at: c.paid_at || null
    };
    // Рядом с caseHasPlan и по той же причине: признак дела, от которого
    // зависит, показывать ли короб. Ставится ВЕЗДЕ, где ставится caseHasPlan,
    // иначе короб появится не на всех дорогах к делу.
    state.caseDraftSteps = (c.on_request_steps || []).filter(function (ш) {
      return ш && ш.step;
    });
    // Направление у каждого дела своё. Оставить прежнее — отдать разговор
    // агенту соседнего дела, у которого другие ограничения.
    state.domain = null;
    state.agent = null;
    chips.innerHTML = "";
    log.innerHTML = "";
    fieldsEl = null;
    caseBody.innerHTML = "";
    /* НАЗВАНИЕ ДЕЛА ЗДЕСЬ НЕ ПОВТОРЯЕМ.

       На одном экране оно стояло ЧЕТЫРЕ раза: заголовок «Дело», строка «где
       идёт разговор», это поле карточки и строка «Дело о: …». Строка «где
       идёт» его уже назвала сорока пикселями выше — в поле оставляем только
       то, чего там нет: когда заведено.

       Область туда же: одно слово, ради которого рисовалась отдельная
       строка, а строка выше и так перечисляет направление, работника и
       стадию. */
    field("Заведено", when(c.created_at),
          "");
    renderCaseClient(c.id);
    casePane.classList.add("live");
    renderCrew(c.participants);
    // Бумаги принадлежат ДЕЛУ, а не человеку: сменилось дело — сменился и
    // список. Перерисовку зовёт renderArtifacts ниже, вместе с остальными
    // тремя разрядами; отдельный вызов здесь был бы вторым запросом за тем же
    // самым.

    state.схемаДела = { закрыто: c.state !== "active", домен: c.domain || "",
                        агент: c.selected_agent_id || "" };
    var n = await replayDialog(c.id);
    отметкаДела(true);
    badge.textContent = T(n ? "идёт" : "черновик");
    // Разговор переехал в дело — строка «где я» обязана это сказать раньше,
    // чем человек напишет следующее сообщение.
    renderWhere();
    // Через пилюли, а не сразу списком: пилюли пунктиром («отнести это дело»)
    // относятся к ОТКРЫТОМУ делу, и после переключения они говорили бы про
    // прежнее. Список перерисуется следом — renderScopes зовёт его сам.
    renderScopes();
    // Четыре разряда — асинхронные, и общий короб обязан ждать их решения:
    // спросить раньше значит посчитать пустоту там, где ответ ещё едет.
    Promise.all([renderFiles(), renderDocs(), renderFinds(), renderPapers()])
      .then(renderArtifacts);
    renderPending();
    renderRun();
    renderCommission();
    renderPaperDraft();
    renderSheets();
    renderПриёмку();
    renderSubject();
  }

  /* ═══ ПРИЁМКА КУПЛЕННОЙ РАБОТЫ ═══════════════════════════════════════

     Деньги двигает акт человека, а не наступление срока и не наше мнение о
     том, что работа готова. Короб показывается только у дел с
     `charge_on: acceptance`: у прочих принимать нечего — заплачено при
     заказе, и кнопка «принять» там означала бы вторую оплату.

     ЦЕНУ БЕРЁМ ИЗ ДЕЛА, а не из прейскуранта: в деле она заморожена, в
     пакете сегодняшняя, и правка тарифа через месяц переписала бы человеку
     сумму, на которую он согласился. */
  function renderПриёмку() {
    var короб = document.getElementById("acceptwork");
    var подсказка = document.getElementById("accepthint");
    var строка = document.getElementById("acceptrow");
    if (!короб || !подсказка || !строка) return;
    var р = state.caseРабота || {};
    if (!state.caseId || р.charge_on !== "acceptance") {
      короб.hidden = true;
      return;
    }
    короб.hidden = false;
    строка.innerHTML = "";
    var цена = рубли(р.kopecks);

    if (р.rejected_at) {
      подсказка.textContent = T("Работа возвращена: ") + (р.reject_note || "") +
        ". " + T("Денег за неё не взяли.");
      return;
    }
    if (р.accepted_at) {
      /* ДВА РАЗНЫХ ИСХОДА, И ВТОРОЙ НАДО НАЗВАТЬ. Приёмка есть, а списание
         могло не пройти — сказать «оплачено» в этом случае значит скрыть
         долг, о котором человек узнает из другого места и не поймёт откуда. */
      подсказка.textContent = р.paid_at
        ? T("Работа принята. Списано ") + цена + "."
        : T("Работа принята, а списание не прошло. Мы это видим и вернёмся к вам.");
      return;
    }

    подсказка.textContent =
      T("За эту работу платят после приёмки: сейчас не списано ничего. ") +
      T("Получили результат — примите, и спишем ") + цена + ". " +
      T("Не подошло — верните с причиной, платить не придётся.");

    var да = el("button", "addone", T("Принять и оплатить ") + цена);
    да.type = "button";
    да.addEventListener("click", function () { решитьРаботу(true, ""); });

    var нет = el("button", "chip", T("Вернуть с причиной"));
    нет.type = "button";
    нет.addEventListener("click", function () {
      строка.innerHTML = "";
      var поле = el("input", "");
      поле.type = "text";
      поле.maxLength = 500;
      /* ПРИЧИНА ОБЯЗАТЕЛЬНА, и это не формальность: молча отклонённая работа
         неотличима от забытой — ни для нас, ни для человека через неделю.
         База запрещает отказ без причины; здесь мы говорим об этом ДО
         нажатия, а не показываем отказ службы. */
      поле.placeholder = T("что именно не подошло (обязательно)");
      var шли = el("button", "addone", T("Вернуть"));
      шли.type = "button";
      шли.addEventListener("click", function () {
        var причина = (поле.value || "").trim();
        if (причина.length < 3) {
          поле.focus();
          return;
        }
        решитьРаботу(false, причина);
      });
      строка.appendChild(поле);
      строка.appendChild(шли);
      поле.focus();
    });
    строка.appendChild(да);
    строка.appendChild(нет);
  }

  async function решитьРаботу(принять, причина) {
    var строка = document.getElementById("acceptrow");
    if (строка) {
      Array.prototype.forEach.call(строка.querySelectorAll("button"),
        function (b) { b.disabled = true; });
    }
    try {
      /* Причина едет полем `note` — так её называет служба. Поле с другим
         именем приехало бы пустым, и отказ сорвался бы на её же проверке. */
      var итог = await api("POST", "/cases/" + state.caseId + "/accept-work",
                           { accept: !!принять, note: причина || "" }, 30000);
      state.caseРабота.accepted_at = итог.accepted ? "принято" : null;
      state.caseРабота.rejected_at = итог.accepted ? null : "возвращено";
      state.caseРабота.reject_note = итог.accepted ? "" : причина;
      /* «Оплачено» говорит СЛУЖБА, а не мы по сумме. Приёмка засчитана, а
         списание могло не пройти — и тогда сказать «списано» значит скрыть
         долг, о котором человек узнает из другого места. */
      state.caseРабота.paid_at = итог.paid ? "оплачено" : null;
      renderПриёмку();
      say("bot", "Ф", итог.accepted
        ? (итог.paid
            ? T("Работа принята, списано ") + рубли(state.caseРабота.kopecks) + "."
            : T("Работа принята, а списание не прошло: ") +
              (итог.note || T("счёт не ответил")) + ". " +
              T("Мы это видим и вернёмся к вам."))
        : T("Работа возвращена. Денег за неё не взяли."));
    } catch (e) {
      renderПриёмку();
      /* Служба говорит человеку через `detail.message`; своих слов за неё не
         придумываем. */
      say("bot", "Ф", T("Не вышло: ") +
          (e && e.message ? e.message : T("служба дел не ответила")));
    }
  }

  /* Копейки в рубли одним местом: две разные округлялки на одном экране
     однажды покажут разные суммы за одну работу. */
  function рубли(копейки) {
    return String(Math.round((копейки || 0) / 100)) + " \u20BD";
  }

  /* Кто автор реплики в журнале дела.

     ТРИ ИСХОДА, А НЕ ДВА, и третий обязателен. До 21.08.2026 автор реплики
     человека не записывался вовсе, и оболочка подписывала ВСЕ такие реплики
     словом «Вы» — безусловно. В деле с двумя участниками это значит, что
     каждый читает слова другого как свои собственные.

     Старые записи так и останутся без автора: actor_id входит в тело хеша
     журнала, и дописать его задним числом значит сломать цепочку и получить
     доклад о порче. Поэтому «автор не записан» — отдельный, ЧЕСТНЫЙ исход:
     сказать «не знаю, кто это сказал» лучше, чем уверенно соврать «это вы». */
  function авторРеплики(e) {
    return (e && e.actor_kind === "principal" && e.actor_id) ? e.actor_id : "";
  }

  /* Как звать автора на экране. Имена берём из состава дела; их подставляет
     служба JOIN-ом, и у большинства людей их нет — вход по телефону и почте
     имени не даёт. Тогда показываем короткий идентификатор: он хотя бы
     постоянен, а придуманное «Участник 2» в разных делах пронумерует одного
     человека по-разному, и он перестанет узнаваться. */
  function имяАвтора(e, p) {
    var кто = авторРеплики(e);
    if (!кто) return "неизвестно кто";
    if (кто === state.principal) return "Вы";
    var сп = (state.caseParticipants || []);
    for (var i = 0; i < сп.length; i++) {
      if (сп[i].principal_id === кто) {
        return сп[i].display_name || (T("участник ") + кто.slice(4, 10));
      }
    }
    return T("участник ") + кто.slice(4, 10);
  }

  /* Две первые буквы для кружка. Кружок 26px — больше туда не влезает. */
  function значокАвтора(имя) {
    var t = String(имя || "").trim();
    if (!t || t === "неизвестно кто") return "?";
    return t.slice(0, 1).toUpperCase();
  }

  /* ── СХЕМА ДЕЛА ───────────────────────────────────────────────────────

     План дела одной картинкой: вехи вершинами, действия рёбрами, сверху
     пульс «что нужно сейчас». Ничего своего не спрашивает у служб: питается
     теми же событиями журнала, что уже приходят разговору (replayDialog и
     дописатьЖурнал складывают их в state.события), и меткой дела из openCase.

     ПУЛЬС БЬЁТСЯ ТОЛЬКО КОГДА ХОД ЗА ЧЕЛОВЕКОМ. «Дело живо» и «без вас
     стоит» — разные вещи; точка дышит на второй. Правила от сильного к
     слабому: шаг прогона ждёт подтверждения → прогон встал → прогон принёс
     варианты → последняя реплика от агента (ход ваш) → работает агент.

     ПЛАН СКЛАДЫВАЕТСЯ ИЗ ТОГО, ЧТО В ДЕЛЕ ЕСТЬ. У разговорного дела это
     заведение, работник и разговор; появились прогоны — встаёт цикл шагов с
     дугой «заново», появились варианты — дом со счётчиком. Рисовать всем
     делам одинаковую простыню значило бы врать пустыми вершинами. */
  var СХЕМА_ШАГИ = { search: "поиск", route: "маршрут", shortlist: "отбор" };

  function схемаСост() {
    var s = { реплик: 0, последняя: "", шаги: [], поШагу: {}, кругов: 0,
              встал: null, ждёт: null, пакетов: 0, успех: false,
              // Ветви плана и заведённые по ним дела. Читаются из журнала —
              // из того же места, что и всё остальное на этой схеме: второй
              // источник правды о плане расходился бы с первым.
              ветви: [], начатые: {}, поНазванию: {}, планИз: "", родитель: null,
              // Предложения, которые ещё ждут слова человека. Ключ — номер
              // предложения, значение — что оно делает.
              проекты: {},
              // Предложения, которые ещё ждут слова человека. Ключ — номер
              // предложения, значение — что оно делает.
              проекты: {},
              // Предложения, которые ещё ждут слова человека. Ключ — номер
              // предложения, значение — что оно делает.
              проекты: {},
              закрыто: !!(state.схемаДела && state.схемаДела.закрыто) };
    (state.события || []).forEach(function (e) {
      var k = e.kind || "";
      var p = e.payload || {};
      var шаг = String(p.step || "");
      if (k === "dialog" && p.text) { s.реплик++; s.последняя = p.role || ""; }
      if (k === "run.created") { s.кругов++; s.встал = null; s.успех = false; }
      if (k.indexOf("run.step.") === 0 && шаг && s.шаги.indexOf(шаг) < 0) {
        s.шаги.push(шаг); s.поШагу[шаг] = { ok: 0, fail: 0 };
      }
      if (k === "run.step.succeeded" && s.поШагу[шаг]) { s.поШагу[шаг].ok++; s.ждёт = null; }
      if (k === "run.step.failed" && s.поШагу[шаг]) { s.поШагу[шаг].fail++; s.встал = шаг; s.ждёт = null; }
      if (k === "run.step.waiting_approval") s.ждёт = шаг;
      if (k === "run.succeeded") { s.успех = true; s.встал = null; }
      if (k === "option.added") s.пакетов++;
      if (k === "case.state_changed") s.закрыто = true;
      /* СУДЬБА ПРЕДЛОЖЕНИЯ ЧИТАЕТСЯ ПО patch_id, А НЕ ПО ВИДУ СОБЫТИЯ.
         Отказ приходит как `patch.denied`, а вот ПРИМЕНЕНИЕ — доменным видом:
         подтверждённый проект бумаги ложится как `material.added` с тем же
         patch_id и outcome «applied». Следи мы за видами `patch.*` — узел
         «проект» остался бы на схеме навсегда после подтверждения. */
      if (p.patch_id) {
        if (k === "patch.proposed" && p.outcome === "pending_approval") {
          s.проекты[p.patch_id] = p.op || "";
        } else if (p.outcome && p.outcome !== "pending_approval") {
          delete s.проекты[p.patch_id];
        }
      }
      /* СУДЬБА ПРЕДЛОЖЕНИЯ ЧИТАЕТСЯ ПО patch_id, А НЕ ПО ВИДУ СОБЫТИЯ.
         Отказ приходит как `patch.denied`, а вот ПРИМЕНЕНИЕ — доменным видом:
         подтверждённый проект бумаги ложится как `material.added` с тем же
         patch_id и outcome «applied». Следи мы за видами `patch.*` — узел
         «проект» остался бы на схеме навсегда после подтверждения. */
      if (p.patch_id) {
        if (k === "patch.proposed" && p.outcome === "pending_approval") {
          s.проекты[p.patch_id] = p.op || "";
        } else if (p.outcome && p.outcome !== "pending_approval") {
          delete s.проекты[p.patch_id];
        }
      }
      /* СУДЬБА ПРЕДЛОЖЕНИЯ ЧИТАЕТСЯ ПО patch_id, А НЕ ПО ВИДУ СОБЫТИЯ.
         Отказ приходит как `patch.denied`, а вот ПРИМЕНЕНИЕ — доменным видом:
         подтверждённый проект бумаги ложится как `material.added` с тем же
         patch_id и outcome «applied». Следи мы за видами `patch.*` — узел
         «проект» остался бы на схеме навсегда после подтверждения. */
      if (p.patch_id) {
        if (k === "patch.proposed" && p.outcome === "pending_approval") {
          s.проекты[p.patch_id] = p.op || "";
        } else if (p.outcome && p.outcome !== "pending_approval") {
          delete s.проекты[p.patch_id];
        }
      }
      if (k === "plan.branches") {
        // Новый план заменяет прежний ЦЕЛИКОМ, вместе с привязками: номера
        // в нём другие, и «ветвь 3 → дело X» означала бы другую ветвь.
        s.ветви = p.branches || [];
        s.начатые = {};
        s.планИз = p.source || "";
      }
      if (k === "branch.started") {
        s.начатые[String(p.ord)] = p.child_case_id || "";
        // И по названию — привязка обязана пережить перекладку плана, иначе
        // уже заведённая ветвь снова покажется незаведённой, и щелчок по ней
        // заведёт второе дело о том же. Служба судит так же.
        if (p.title) s.поНазванию[String(p.title)] = p.child_case_id || "";
      }
      // Только указатель: названия родителя в этом событии НЕТ намеренно —
      // журнал дочернего дела читают люди, которых в родительском нет.
      if (k === "branch.parent") s.родитель = { id: p.parent_case_id || "" };
    });
    return s;
  }

  function обновитьСхему() {
    var короб = document.getElementById("scheme");
    if (!короб) return;
    if (!state.caseId) { короб.hidden = true; return; }
    короб.hidden = false;
    var s = схемаСост();

    // Пульс.
    var точка = document.getElementById("sxdot");
    var слова = document.getElementById("sxwhat");
    var цвет, текст, бьётся = true, текущий = null;
    if (s.закрыто) {
      цвет = "var(--ink-3)"; бьётся = false; текущий = "closed";
      текст = T("Дело закрыто — делать ничего не нужно.");
    } else if (s.ждёт) {
      цвет = "var(--brass)"; текущий = s.ждёт;
      текст = T("Шаг «") + T(СХЕМА_ШАГИ[s.ждёт] || s.ждёт) + T("» ждёт вашего подтверждения.");
    } else if (s.встал) {
      цвет = "var(--bad, #C25B4E)"; текущий = s.встал;
      текст = T("Прогон встал на шаге «") + T(СХЕМА_ШАГИ[s.встал] || s.встал) + T("».");
    } else if (s.успех && s.пакетов) {
      цвет = "var(--accent, #7fb597)"; текущий = "choice";
      текст = T("Прогон принёс варианты — выбор за вами.");
    } else if (s.реплик && s.последняя === "assistant") {
      цвет = "var(--brass)"; текущий = "talk";
      текст = T("Ход за вами: ответьте или дайте поручение.");
    } else if (s.реплик) {
      цвет = "var(--accent, #7fb597)"; бьётся = false; текущий = "talk";
      текст = T("Отвечает агент — ничего делать не нужно.");
    } else {
      цвет = "var(--brass)"; текущий = "created";
      текст = T("Дело заведено и пусто: расскажите, что нужно.");
    }
    точка.style.background = цвет;
    точка.style.setProperty("--sxcolor", цвет);
    точка.classList.toggle("beat", бьётся);
    слова.textContent = текст;

    рисоватьСхему(s, текущий, цвет);
  }

  //: Пиктограммы схемы. Рукописный SVG без библиотек: вершин на живом деле
  //: меньше десятка, и внешний движок графов был бы третьей зависимостью
  //: ради того, что умеют десять path-ов.
  function схЗначок(g, вид, x, y) {
    var st = { stroke: "var(--ink-2)", "stroke-width": 1.5, fill: "none",
               "stroke-linecap": "round", "stroke-linejoin": "round" };
    function add(тег, а) {
      var n = document.createElementNS("http://www.w3.org/2000/svg", тег);
      for (var k in st) n.setAttribute(k, st[k]);
      for (var k2 in а) n.setAttribute(k2, а[k2]);
      g.appendChild(n);
    }
    if (вид === "папка") add("path", { d: "M " + (x-8) + " " + (y-4.5) + " h 5.5 l 2.2 2.7 h 8.3 v 9 h -16 z" });
    else if (вид === "компас") {
      add("circle", { cx: x, cy: y, r: 7.5 });
      add("path", { d: "M " + (x+3) + " " + (y-3) + " L " + (x+0.8) + " " + (y+0.8) +
        " L " + (x-3) + " " + (y+3) + " L " + (x-0.8) + " " + (y-0.8) + " Z", fill: "var(--ink-2)" });
    } else if (вид === "речь") {
      add("path", { d: "M " + (x-8) + " " + (y-6) + " h 16 v 9 h -9 l -4 4 v -4 h -3 z" });
    } else if (вид === "лупа") {
      add("circle", { cx: x-2, cy: y-2, r: 5.4 });
      add("path", { d: "M " + (x+2) + " " + (y+2) + " L " + (x+7) + " " + (y+7) });
    } else if (вид === "развилка") {
      add("path", { d: "M " + x + " " + (y+7) + " V " + (y+1) });
      add("path", { d: "M " + x + " " + (y+1) + " C " + x + " " + (y-3.5) + ", " + (x-5) + " " + (y-3.5) + ", " + (x-5) + " " + (y-7) });
      add("path", { d: "M " + x + " " + (y+1) + " C " + x + " " + (y-3.5) + ", " + (x+5) + " " + (y-3.5) + ", " + (x+5) + " " + (y-7) });
    } else if (вид === "воронка") {
      add("path", { d: "M " + (x-8) + " " + (y-7) + " H " + (x+8) + " L " + (x+2) + " " + y +
        " V " + (y+7) + " H " + (x-2) + " V " + y + " Z" });
    } else if (вид === "дом") {
      add("path", { d: "M " + (x-11) + " " + (y+9) + " V " + (y-1) + " l 4.7 -4.3 l 4.7 4.3 V " + (y+9) + " Z" });
      add("rect", { x: x+0.5, y: y-10, width: 9.5, height: 19 });
    } else if (вид === "лист") {
      add("path", { d: "M " + (x-6.5) + " " + (y-9) + " h 8 l 5 5 v 13 h -13 z" });
      add("path", { d: "M " + (x+1.5) + " " + (y-9) + " v 5 h 5" });
      add("path", { d: "M " + (x-3.5) + " " + (y+1) + " h 7" });
      add("path", { d: "M " + (x-3.5) + " " + (y+5) + " h 7" });
    } else if (вид === "лист") {
      add("path", { d: "M " + (x-6.5) + " " + (y-9) + " h 8 l 5 5 v 13 h -13 z" });
      add("path", { d: "M " + (x+1.5) + " " + (y-9) + " v 5 h 5" });
      add("path", { d: "M " + (x-3.5) + " " + (y+1) + " h 7" });
      add("path", { d: "M " + (x-3.5) + " " + (y+5) + " h 7" });
    } else if (вид === "лист") {
      add("path", { d: "M " + (x-6.5) + " " + (y-9) + " h 8 l 5 5 v 13 h -13 z" });
      add("path", { d: "M " + (x+1.5) + " " + (y-9) + " v 5 h 5" });
      add("path", { d: "M " + (x-3.5) + " " + (y+1) + " h 7" });
      add("path", { d: "M " + (x-3.5) + " " + (y+5) + " h 7" });
    } else if (вид === "галочка") {
      add("path", { d: "M " + (x-6) + " " + y + " L " + (x-1.2) + " " + (y+4.8) + " L " + (x+7) + " " + (y-5) });
    } else if (вид === "флаг") {
      add("path", { d: "M " + (x-3.5) + " " + (y+8) + " V " + (y-8) });
      add("path", { d: "M " + (x-3.5) + " " + (y-8) + " h 10 l -2.6 3.5 l 2.6 3.5 h -10", fill: "var(--ink-2)" });
    }
  }

  function рисоватьСхему(s, текущий, цветПульса) {
    var svg = document.getElementById("sxg");
    if (!svg) return;
    var NS = "http://www.w3.org/2000/svg";
    function эл(тег, а, текст) {
      var n = document.createElementNS(NS, тег);
      for (var k in а) n.setAttribute(k, а[k]);
      if (текст != null) n.textContent = текст;
      return n;
    }
    // План: только то, что в деле есть.
    var П = [];
    if (s.родитель && s.родитель.id) {
      // ОТКУДА ЭТО ДЕЛО. Дитя ветви человек чаще открывает само по себе — из
      // списка, из уведомления, по ссылке, — и без этой вершины оно выглядит
      // заведённым ниоткуда: родителя ему искать негде.
      П.push({ id: "parent", вид: "развилка",
               имя: T("выросло из другого дела"),
               есть: true, готово: true, дело: s.родитель.id,
               суть: T("Это дело — ветвь другого. Кнопка ниже откроет родителя, " +
                       "если у вас есть к нему доступ.") });
    }
    П.push({ id: "created", вид: "папка", имя: T("заведено"), есть: true, готово: true,
               суть: T("Начало дела. Схема строится из его журнала — тех же событий, что видит разговор.") });
    if ((state.схемаДела || {}).домен) П.push({ id: "route", вид: "компас", имя: T("работник"),
      есть: true, готово: true,
      суть: T("Направление и работник выбраны") + ((state.схемаДела||{}).агент ? " — " + state.схемаДела.агент : "") + "." });
    if (s.реплик || !s.шаги.length) П.push({ id: "talk", вид: "речь",
      имя: T("разговор"), знак: s.реплик || "", есть: s.реплик > 0, готово: s.реплик > 0,
      суть: T("Реплик в деле: ") + s.реплик + ". " +
            (s.последняя === "assistant" ? T("Последняя — от агента: ход за вами.")
                                         : T("Последняя — ваша: отвечает агент.")) });
    s.шаги.slice(0, 4).forEach(function (шаг) {
      var ш = s.поШагу[шаг] || { ok: 0, fail: 0 };
      П.push({ id: "step:" + шаг,
        вид: шаг === "search" ? "лупа" : шаг === "route" ? "развилка" : "воронка",
        имя: T(СХЕМА_ШАГИ[шаг] || шаг), есть: true, готово: ш.ok > 0,
        упал: s.встал === шаг, ждёт: s.ждёт === шаг,
        суть: T("Шаг прогона. Прошёл ") + ш.ok + T(" раз") +
              (ш.fail ? T(", падал ") + ш.fail : "") +
              (s.ждёт === шаг ? T(", сейчас ждёт вашего подтверждения") : "") + "." });
    });
    var проектов = Object.keys(s.проекты).length;
    if (проектов) П.push({ id: "draft", вид: "лист", имя: T("проект бумаги"),
      знак: проектов > 1 ? проектов : "", есть: true, готово: false, ждёт: true,
      кПроектам: true,
      суть: T("Агент составил проект и ждёт вашего слова. В дело он ляжет "
              + "только после подтверждения — до него это ничей документ.") });
    var проектов = Object.keys(s.проекты).length;
    if (проектов) П.push({ id: "draft", вид: "лист", имя: T("проект бумаги"),
      знак: проектов > 1 ? проектов : "", есть: true, готово: false, ждёт: true,
      кПроектам: true,
      суть: T("Агент составил проект и ждёт вашего слова. В дело он ляжет "
              + "только после подтверждения — до него это ничей документ.") });
    var проектов = Object.keys(s.проекты).length;
    if (проектов) П.push({ id: "draft", вид: "лист", имя: T("проект бумаги"),
      знак: проектов > 1 ? проектов : "", есть: true, готово: false, ждёт: true,
      кПроектам: true,
      суть: T("Агент составил проект и ждёт вашего слова. В дело он ляжет "
              + "только после подтверждения — до него это ничей документ.") });
    if (s.пакетов) П.push({ id: "opts", вид: "дом", имя: T("варианты"), знак: "+" + s.пакетов,
      есть: true, готово: true,
      суть: T("Прогон принёс варианты — они лежат ниже, в разделе находок. Пакетов: ") + s.пакетов + "." });
    if (s.пакетов) П.push({ id: "choice", вид: "галочка", имя: T("ваш выбор"),
      есть: true, готово: s.закрыто,
      суть: T("Из принесённого выбираете вы: агент раскрывает, но не решает.") });
    if (s.ветви.length) {
      /* Название годится для привязки, только если оно в плане ОДНО. Два
         одинаковых — и по нему нельзя сказать, о которой ветви речь; служба
         судит так же. Старые планы с близнецами (записанные до запрета)
         поэтому не ломаются, а просто теряют привязку по названию. */
      var разНазвание = {};
      s.ветви.forEach(function (в) {
        разНазвание[в.title] = (разНазвание[в.title] || 0) + 1;
      });
      function делоВетви(в, i) {
        return s.начатые[String(i)] ||
               (разНазвание[в.title] === 1 ? s.поНазванию[в.title] : "") || "";
      }
      var заведено = 0;
      s.ветви.forEach(function (в, i) { if (делоВетви(в, i)) заведено++; });
      П.push({ id: "branches", вид: "развилка", имя: T("ветви"),
               знак: заведено ? заведено + "/" + s.ветви.length : s.ветви.length,
               есть: true, готово: заведено === s.ветви.length,
               складка: true,
               суть: T("План разложен на ветви: ") + s.ветви.length + ". " +
                     T("Заведено делами: ") + заведено + ". " +
                     (s.планИз ? T("Основание: ") + T(s.планИз) + ". " : "") +
                     T("Нажмите на ветвь, чтобы раскрыть её; дело заводится только вашим щелчком.") });
      if (state.ветвиРаскрыты !== false) s.ветви.forEach(function (в, i) {
        var дитя = делоВетви(в, i);
        П.push({ id: "branch:" + i, ветвь: true, номер: i, дело: дитя,
                 // Название ОТДЕЛЬНО от подписи: подпись бывает подставной
                 // («ветвь 3»), а согласие обязано назвать настоящее — то,
                 // что лежит в плане, иначе служба его не узнает.
                 название: в.title || "",
                 имя: в.title || T("ветвь ") + (i + 1),
                 пояснение: в.purpose || "",
                 есть: true, готово: !!дитя });
      });
    }
    П.push({ id: "closed", вид: "флаг", имя: T("итог"), есть: true, готово: s.закрыто,
      суть: s.закрыто ? T("Дело закрыто. Журнал остаётся в деле целиком.")
                      : T("Здесь дело закончится; журнал останется целиком.") });

    var ШАГ = 62, ВЕТКА = 38, X = 42, XR = X + 20, XB = X + 52, W = 320;
    // Высоты считаем построчно, а не одним шагом: ветвей бывает и полтора
    // десятка, и на общем шаге схема вырастала бы в полтора экрана.
    var Y = [], y0 = 30;
    П.forEach(function (n, i) {
      if (i) y0 += n.ветвь ? ВЕТКА : (П[i-1].ветвь ? 46 : ШАГ);
      Y.push(y0);
    });
    var H = (Y[Y.length - 1] || 30) + 30;
    svg.setAttribute("viewBox", "0 0 " + W + " " + H);
    svg.innerHTML = "";
    // Рёбра-хребет: между соседними вершинами хребта. Ветви его не рвут —
    // они висят сбоку, и линия проходит мимо них.
    var прошлый = -1;
    П.forEach(function (n, i) {
      if (n.ветвь) return;
      if (прошлый >= 0) svg.appendChild(эл("line",
        { x1: X, y1: Y[прошлый] + 21, x2: X, y2: Y[i] - 21,
          stroke: "var(--hair)", "stroke-width": 1.6 }));
      прошлый = i;
    });
    // Рейка ветвей и отводы к ним — так же, как рисуют дерево папок.
    var разв = -1, последняяВетвь = -1;
    П.forEach(function (n, i) {
      if (n.id === "branches") разв = i;
      if (n.ветвь) последняяВетвь = i;
    });
    if (разв >= 0 && последняяВетвь > разв) {
      svg.appendChild(эл("line", { x1: XR, y1: Y[разв] + 16, x2: XR, y2: Y[последняяВетвь],
        stroke: "var(--hair)", "stroke-width": 1.4 }));
      П.forEach(function (n, i) {
        if (!n.ветвь) return;
        svg.appendChild(эл("line", { x1: XR, y1: Y[i], x2: XB - 13, y2: Y[i],
          stroke: "var(--hair)", "stroke-width": 1.4 }));
      });
    }
    // Дуга «заново», если прогон падал.
    var первыйШаг = -1, последнийШаг = -1;
    П.forEach(function (n, i) { if (n.id.indexOf("step:") === 0) {
      if (первыйШаг < 0) первыйШаг = i; последнийШаг = i; } });
    var падений = 0;
    for (var к in s.поШагу) падений += s.поШагу[к].fail;
    if (первыйШаг >= 0 && последнийШаг > первыйШаг && падений) {
      var a = Y[последнийШаг], b = Y[первыйШаг];
      svg.appendChild(эл("path", { d: "M " + (X+18) + " " + a + " C " + (X+78) + " " + a +
        ", " + (X+78) + " " + b + ", " + (X+20) + " " + b,
        fill: "none", stroke: "var(--bad, #C25B4E)", "stroke-width": 1.2,
        "stroke-dasharray": "4 4" }));
      var подпись = эл("text", { x: X+80, y: (a+b)/2, "font-size": "10",
        fill: "var(--bad, #C25B4E)", "text-anchor": "middle",
        transform: "rotate(90 " + (X+80) + " " + ((a+b)/2) + ")" },
        T("заново") + " ×" + падений);
      svg.appendChild(подпись);
    }
    // Вершины.
    П.forEach(function (n, i) {
      var y = Y[i];
      if (n.ветвь) { ветвьНаСхеме(svg, эл, n, XB, y); return; }
      var g = эл("g", { class: "sxnode" + (
        (текущий === n.id || ("step:" + текущий) === n.id || n.ждёт) ? " current" : "") });
      g.appendChild(эл("circle", { cx: X, cy: y, r: 24, fill: "none",
        class: "sxhalo", stroke: цветПульса, "stroke-width": 2 }));
      g.appendChild(эл("circle", { cx: X, cy: y, r: 19,
        fill: "var(--panel-2, var(--panel))",
        stroke: n.упал ? "var(--bad, #C25B4E)" : n.ждёт ? "var(--brass)" :
                n.готово ? "var(--ok, #7fb597)" : "var(--hair)",
        "stroke-width": n.готово || n.упал || n.ждёт ? 2 : 1.4,
        "stroke-dasharray": n.готово || n.упал || n.ждёт ? "" : "4 4" }));
      схЗначок(g, n.вид, X, y);
      if (n.знак) {
        g.appendChild(эл("circle", { cx: X+16, cy: y-15, r: 10, fill: "var(--accent, #7fb597)" }));
        g.appendChild(эл("text", { x: X+16, y: y-11.5, "text-anchor": "middle",
          "font-size": "9.5", fill: "var(--panel)" }, String(n.знак)));
      }
      g.appendChild(эл("text", { x: X+34, y: y+4, "font-size": "12.5",
        fill: "var(--ink)" }, n.имя));
      g.addEventListener("click", function () {
        var о = document.getElementById("sxdesc");
        о.hidden = false;
        о.textContent = n.имя + ". " + n.суть;
        // «Ветви» складываются: на плане в полтора десятка пунктов схема
        // иначе заслоняет всё остальное, что в деле есть.
        if (n.складка) {
          state.ветвиРаскрыты = state.ветвиРаскрыты === false;
          обновитьСхему();
        }
        /* ДВЕРЬ К ПОСТРОЕННОМУ, а не второй показ того же. Проект живёт в
           коробе «Ждёт вашего слова» — там у него текст, пропуски и обе
           кнопки решения. Нарисовать его ещё и здесь значило бы завести две
           правды об одном документе; этот проект уже проходили. */
        if (n.кПроектам) {
          var короб = document.getElementById("pending");
          if (короб) {
            короб.hidden = false;
            короб.scrollIntoView({ block: "center", behavior: "smooth" });
          }
          /* И СРАЗУ ОТКРЫВАЕМ ПРОЕКТ НА ХОЛСТЕ, а не оставляем человека перед
             карточкой с ещё одной кнопкой. Щелчок по вершине «проект бумаги»
             означает ровно «покажи мне проект» — на второе нажатие ради того
             же он не подписывался.

             Открывает та же самая кнопка карточки, а не своя копия вызова:
             две двери к одному действию в этом проекте уже расходились. */
          renderPending().then(function () {
            var кнопка = document.querySelector("#pendinglist .pend1 .addone");
            if (кнопка) кнопка.click();
          });
        }
        /* ДВЕРЬ К ПОСТРОЕННОМУ, а не второй показ того же. Проект живёт в
           коробе «Ждёт вашего слова» — там у него текст, пропуски и обе
           кнопки решения. Нарисовать его ещё и здесь значило бы завести две
           правды об одном документе; этот проект уже проходили. */
        if (n.кПроектам) {
          var короб = document.getElementById("pending");
          if (короб) {
            короб.hidden = false;
            короб.scrollIntoView({ block: "center", behavior: "smooth" });
          }
          // И перечитываем: узел рисуется по журналу, а короб — по службе, и
          // на длинном деле они расходятся ровно на то время, что человек не
          // нажимал ничего.
          renderPending();
        }
        /* ДВЕРЬ К ПОСТРОЕННОМУ, а не второй показ того же. Проект живёт в
           коробе «Ждёт вашего слова» — там у него текст, пропуски и обе
           кнопки решения. Нарисовать его ещё и здесь значило бы завести две
           правды об одном документе; этот проект уже проходили. */
        if (n.кПроектам) {
          var короб = document.getElementById("pending");
          if (короб) {
            короб.hidden = false;
            короб.scrollIntoView({ block: "center", behavior: "smooth" });
          }
          // И перечитываем: узел рисуется по журналу, а короб — по службе, и
          // на длинном деле они расходятся ровно на то время, что человек не
          // нажимал ничего.
          renderPending();
        }
        // «Из дела «…»» — дверь к родителю, но не с первого щелчка: первый
        // объясняет, что это вообще такое.
        if (n.дело) {
          var кн = el("button", "addone", T("Открыть дело"));
          кн.type = "button";
          кн.addEventListener("click", function () { openCase(n.дело); });
          о.appendChild(document.createTextNode(" "));
          о.appendChild(кн);
        }
      });
      svg.appendChild(g);
    });
  }

  /* Ветвь плана на схеме. Заведённая — сплошная и зелёная, незаведённая —
     пунктиром и с плюсом: пунктир по всей этой схеме значит «этого ещё нет»,
     и ветвь плана — ровно такой случай. */
  function ветвьНаСхеме(svg, эл, n, x, y) {
    var g = эл("g", { class: "sxnode" });
    g.appendChild(эл("circle", { cx: x, cy: y, r: 13,
      fill: "var(--panel-2, var(--panel))",
      stroke: n.готово ? "var(--ok, #7fb597)" : "var(--hair)",
      "stroke-width": n.готово ? 2 : 1.4,
      "stroke-dasharray": n.готово ? "" : "4 4" }));
    if (n.готово) схЗначок(g, "галочка", x, y);
    else {
      var ш = { stroke: "var(--ink-3, var(--ink-2))", "stroke-width": 1.5,
                "stroke-linecap": "round" };
      ["M " + (x-4.5) + " " + y + " H " + (x+4.5),
       "M " + x + " " + (y-4.5) + " V " + (y+4.5)].forEach(function (d) {
        var л = эл("path", { d: d });
        for (var k in ш) л.setAttribute(k, ш[k]);
        g.appendChild(л);
      });
    }
    g.appendChild(эл("text", { x: x + 22, y: y + 4, "font-size": "11.5",
      fill: n.готово ? "var(--ink)" : "var(--ink-2)" },
      короткоДляСхемы(n.имя, 30)));
    g.addEventListener("click", function () { раскрытьВетвь(n); });
    svg.appendChild(g);
  }

  /* Обрезка подписи. Название ветви пишет модель, и длина у него любая, а
     ширина схемы — 320 единиц: без обрезки подпись уезжает за край SVG, где
     её не видно и не прокрутить. Полное название человек читает в пояснении
     под схемой — там места сколько угодно. */
  function короткоДляСхемы(текст, предел) {
    текст = String(текст || "");
    return текст.length > предел ? текст.slice(0, предел - 1) + "…" : текст;
  }

  /* Раскрыть ветвь: что это, зачем и что будет по нажатию.

     ДЕЛО ЗАВОДИТСЯ ТОЛЬКО ЗДЕСЬ, и это обещано человеку прямо в тексте
     оболочки: «дело без вашего согласия не заведётся в любом случае».
     Разложить план на ветви — не согласие; согласие — вот эта кнопка. */
  async function раскрытьВетвь(n) {
    var о = document.getElementById("sxdesc");
    if (!о) return;
    о.hidden = false;
    о.textContent = "";
    var шапка = el("div", "", n.имя);
    шапка.style.fontWeight = "600";
    о.appendChild(шапка);
    if (n.пояснение) о.appendChild(el("div", "", n.пояснение));

    if (n.дело) {
      var открыть = el("button", "addone", T("Открыть дело"));
      открыть.type = "button";
      открыть.addEventListener("click", function () { openCase(n.дело); });
      о.appendChild(открыть);
      // ДЕЛО ВЕТВИ МОГЛИ УДАЛИТЬ. Тогда «Открыть» отвечает «удалено навсегда»,
      // и ветвь остаётся мёртвой: путь завести по ней заново из оболочки
      // исчезал совсем. Служба это умеет — её проверка повтора возвращает
      // существующее дело и заводит новое, только если прежнего уже нет, —
      // поэтому нажатие здесь безопасно и в том случае, когда дело живо.
      о.appendChild(el("div", "fnote", T("Если это дело удалено, по ветви можно "
        + "завести новое — кнопка ниже. Пока дело цело, она просто откроет его.")));
    }
    if (!n.дело) о.appendChild(el("div", "", T("Дела по этой ветви ещё нет. " +
      "Оно заведётся по нажатию — и только по нему.")));
    var подпись = n.дело ? T("Завести заново, если удалено") : T("Завести дело");
    var завести = el("button", "addone", подпись);
    завести.type = "button";
    var дело = state.caseId;
    завести.addEventListener("click", async function () {
      if (state.caseId !== дело) {
        о.appendChild(el("div", "", T("Дело успели сменить — ветвь относится к "
          + "другому делу. Ничего не заведено.")));
        return;
      }
      завести.disabled = true;
      завести.textContent = T("Завожу…");
      var дитя;
      try {
        дитя = await api("POST", "/cases/" + encodeURIComponent(дело) +
                         "/branches/" + n.номер + "/start",
                         { expect_title: n.название });
      } catch (e) {
        завести.disabled = false;
        завести.textContent = подпись;
        if (e && e.status === 409) {
          // План перелёг между показом и нажатием. Повторять нечего —
          // человеку нужна свежая схема, а не второй такой же щелчок.
          await дописатьЖурнал(true);
          обновитьСхему();
          о.textContent = "";
          о.appendChild(el("div", "", T("План успели переложить, и по этому " +
            "месту теперь другая ветвь. Дело не заведено — схема обновлена, " +
            "посмотрите её заново.")));
          return;
        }
        о.appendChild(el("div", "", T("Дело по ветви не завелось: ") + reason(e) +
          T(" Ветвь при этом цела — попробуйте ещё раз.")));
        return;
      }
      // Журнал дочитываем, а не дорисовываем от себя: схема обязана
      // показывать то, что записано, иначе на перезагрузке всё пропадёт.
      await дописатьЖурнал(true);
      обновитьСхему();
      о.textContent = "";
      о.appendChild(el("div", "", T("Дело заведено: ") + (дитя.title || дитя.id)));
      var открыть2 = el("button", "addone", T("Открыть дело"));
      открыть2.type = "button";
      открыть2.addEventListener("click", function () { openCase(дитя.id); });
      о.appendChild(открыть2);
    });
    о.appendChild(завести);
  }

  /* Ветви из ответа агента.

     ЧТО ЗДЕСЬ РАЗБИРАЕТСЯ. Агент, прочитав приложенный план, отвечает
     списком: «1. Юридическое дело — Строители …». Разбираем СПИСОК, а не
     весь ответ: связный текст ветвями не бывает, а список — ровно то, что
     человек и называет «делами, которые он составил».

     Только верхний уровень: вложенные пункты — это шаги внутри ветви, и
     заводить по каждому отдельное дело значило бы разнести одно дело на
     пять. Человек всё равно правит список перед записью — см. ниже. */
  function ветвиИзОтвета(текст) {
    // CRLF СНИМАЕТСЯ ПЕРВЫМ ДЕЛОМ. В JS `\r` — конец строки, и точка его не
    // берёт: на ответе с CRLF `(.+)$` не доходит до конца строки, и не
    // разбирается НИ ОДИН пункт. Ответ приезжает и из почты, и из вставленного
    // человеком текста, где CRLF обычен.
    var строки = String(текст || "").replace(/\r\n?/g, "\n").split("\n");
    /* ОТСТУП МЕРЯЕТСЯ ОТ САМОГО СПИСКА, А НЕ ОТ КРАЯ СТРОКИ.

       Модели сплошь и рядом выравнивают список под вводную фразу: «Предлагаю
       завести дела:» и дальше пункты с двумя пробелами. При отсчёте от края
       КАЖДЫЙ такой пункт считался вложенным, разбор возвращал пустоту, и
       человек читал «в разговоре нет списка, который можно разложить» — про
       ответ, где список есть.

       За нулевой уровень берём наименьший отступ среди строк, которые вообще
       похожи на пункт списка. Вложенное — то, что отбито ОТ НЕГО. */
    var ЗНАЧОК = /^(?:\d{1,2}[.)]|[-*•])\s+(.+)$/;
    function отступПункта(строка) {
      var с_табами = строка.replace(/\t/g, "    ");
      var голая = с_табами.replace(/^\s+/, "");
      return { отступ: с_табами.length - голая.length, голая: голая,
               m: голая.match(ЗНАЧОК) };
    }
    var основание = null, вКодеП = false;
    строки.forEach(function (строка) {
      if (/^\s*(```|~~~)/.test(строка)) { вКодеП = !вКодеП; return; }
      if (вКодеП) return;
      var р = отступПункта(строка);
      if (!р.m) return;
      if (основание === null || р.отступ < основание) основание = р.отступ;
    });
    if (основание === null) основание = 0;
    var из = [];
    var вКоде = false;
    //: Была ли между пунктом и этой строкой пустая строка. Отбитый абзац
    //: после списка — уже не пояснение к последнему пункту, а сам по себе
    //: текст; приклеенный, он уезжает в цель заведённого дела.
    var пусто = false;
    строки.forEach(function (строка) {
      // Код-блок разбору не подлежит: «- name: …» в примере настройки не дело.
      if (/^\s*(```|~~~)/.test(строка)) { вКоде = !вКоде; return; }
      if (вКоде) return;
      // Табы РАЗВЁРНУТЫ до подсчёта: таб — один знак, и вложенный пункт,
      // отбитый табом, считался бы верхним уровнем.
      var р = отступПункта(строка);
      var голая = р.голая, m = р.m;
      if (р.отступ >= основание + 2) {
        // Отступ и БЕЗ значка списка — это перенос строки предыдущего
        // пункта, а не вложенный пункт: модели переносят длинные строки, и
        // без склейки пояснение обрывается на запятой. Склеиваем только
        // ПОДРЯД идущее (см. пусто ниже): абзац после пустой строки к пункту
        // уже не относится.
        if (!голая) { пусто = true; return; }   // строка из одних пробелов
        if (!m && из.length && !пусто) {
          из[из.length - 1].purpose =
            (из[из.length - 1].purpose + " " + голая.trim()).trim().slice(0, 2000);
        }
        пусто = false;
        return;                                   // вложенный пункт — не дело
      }
      if (!m) { пусто = пусто || !голая; return; }
      пусто = false;
      var пункт = m[1].replace(/^#+\s*/, "").trim();
      // Значок мог стоять дважды: «3. — Дело по охране труда».
      пункт = пункт.replace(/^(?:[-*•—–]\s+)+/, "").trim();
      // Чеклист markdown: «- [ ] Кадровое дело».
      пункт = пункт.replace(/^\[[ xX]\]\s*/, "").trim();
      if (пункт.length < 4) return;
      var имя, зачем;
      // ЖИРНОЕ — ЭТО НАЗВАНИЕ. Модели выделяют им именно название, и оно
      // надёжнее любого разделителя: «**Юридическое дело — Строители**»
      // разрезанное по тире дало бы «Юридическое дело» и потеряло, о ком.
      var ж = пункт.match(/^\*\*(.+?)\*\*\s*(.*)$/);
      if (ж) {
        имя = ж[1].trim();
        зачем = ж[2].replace(/^[\s—–:-]+/, "").trim();
      } else {
        пункт = пункт.replace(/\*\*/g, "");
        // «Название — пояснение»: по первому длинному тире или двоеточию.
        // Разделителя нет — пояснения просто не будет: выдумывать его за
        // модель нельзя.
        var р = пункт.search(/\s—\s|\s–\s|:\s/);
        имя = р > 0 ? пункт.slice(0, р).trim() : пункт;
        зачем = р > 0 ? пункт.slice(р).replace(/^[\s—–:]+/, "").trim() : "";
      }
      имя = имя.replace(/\*\*/g, "").trim();
      if (имя.length > 200) { зачем = имя.slice(180) + " " + зачем; имя = имя.slice(0, 180); }
      if (имя.length < 3) return;
      из.push({ title: имя, purpose: зачем.replace(/\*\*/g, "").slice(0, 2000) });
    });
    return из.slice(0, 30);
  }

  /* Откуда брать список: из последнего ответа агента, который вообще похож
     на список. Не из самого последнего безусловно: за разбором плана обычно
     идёт ещё пара реплик, и в них списка нет. */
  function последнийСписокАгента() {
    var события = (state.события || []).slice().reverse();
    for (var i = 0; i < события.length; i++) {
      var e = события[i], p = e.payload || {};
      if ((e.kind || "") !== "dialog" || p.role !== "assistant" || !p.text) continue;
      var в = ветвиИзОтвета(p.text);
      if (в.length >= 2) return { ветви: в, текст: p.text };
    }
    return null;
  }

  /* Предложить разложить дело на ветви.

     ЧЕЛОВЕК ВИДИТ СПИСОК ДО ТОГО, КАК ОН ЛЯЖЕТ В ГРАФ, и вычёркивает лишнее.
     Разбор списка — угадывание: в ответе рядом со списком дел бывают списки
     рисков и ролей, и отличить их наверняка нечем. Записанный план ничего не
     заводит, так что ошибка разбора не опасна, — но засоряет схему, а схема
     нужна как раз чтобы в ней было видно. */
  function предложитьВетви() {
    var о = document.getElementById("sxdesc");
    if (!о) return;
    о.hidden = false;
    о.textContent = "";
    if (!state.caseId) {
      о.appendChild(el("div", "", T("Ветви бывают у дела — сначала откройте его.")));
      return;
    }
    // Дело запоминается ЗДЕСЬ, а не читается при нажатии: между разбором и
    // записью человек успевает переключить дело — и план уехал бы не туда.
    var дело = state.caseId;
    var найдено = последнийСписокАгента();
    if (!найдено) {
      о.appendChild(el("div", "", T("В разговоре нет ответа со списком, который " +
        "можно разложить на ветви. Попросите агента перечислить дела списком — " +
        "по пунктам, — и нажмите сюда снова.")));
      return;
    }
    var ветви = найдено.ветви;
    о.appendChild(el("div", "", T("Что ляжет в граф ветвями. Дела при этом не " +
      "заводятся: каждое заводится отдельно, вашим щелчком по ветви.")));
    // ИЗ КАКОГО ИМЕННО ОТВЕТА. Берётся новейший ответ агента, где нашлось два
    // и более пунктов, — а это бывает и список оговорок, и список вопросов.
    // Человек обязан узнать промах ДО записи, а узнать его он может только по
    // началу того ответа.
    var начало = String(найдено.текст || "").replace(/\s+/g, " ").trim().slice(0, 70);
    // Без кавычек намеренно: открывающая пришла бы из словаря, закрывающая
    // осталась бы в коде ёлочкой, и парой они бы не сошлись.
    о.appendChild(el("div", "fnote", T("Взято из ответа агента — ") + начало + "…"));
    // ЗАПИСЬ ЗАМЕНЯЕТ ПРЕЖНИЙ ПЛАН ЦЕЛИКОМ — и человек обязан узнать об этом
    // ДО нажатия, а не по пропавшим из схемы ветвям. Заведённые дела при этом
    // остаются: они уже не ветви.
    var было = схемаСост().ветви.length;
    if (было) о.appendChild(el("div", "", T("Сейчас в схеме ветвей: ") + было +
      T(". Запись заменит их целиком; уже заведённые дела останутся.")));
    var список = el("div", "");
    список.style.margin = "6px 0";
    function обновитьКнопку() {
      var пустых = ветви.filter(function (в) { return !в.title.trim(); }).length;
      /* БЛИЗНЕЦЫ ЗАПРЕЩЕНЫ, и это не придирка к красоте.

         Разбор режет «Юридическое дело — Строители» и «Юридическое дело —
         Субподрядчики» по тире и даёт ДВА «Юридическое дело». В графе они
         неразличимы, а привязка «ветвь → дело» ищется в том числе по
         названию — и вторая ветвь показывается заведённой, хотя по ней не
         щёлкали: дело по ней не заведётся никогда, а её пояснение пропадёт.

         Человеку эти две строки тоже неразличимы, поэтому чинить надо здесь,
         пока он видит обе и может дописать, чем они отличаются. */
      var счёт = {}, близнецов = 0;
      ветви.forEach(function (в) {
        var к = в.title.trim();
        if (!к) return;
        счёт[к] = (счёт[к] || 0) + 1;
        if (счёт[к] === 2) близнецов++;
      });
      записать.disabled = !ветви.length || !!пустых || !!близнецов;
      записать.textContent = !ветви.length ? T("Нечего записывать")
        : пустых ? T("Есть ветви без названия: ") + пустых
        : близнецов ? T("Есть ветви с одинаковым названием: ") + близнецов
        : T("Записать ветвей: ") + ветви.length;
    }

    function перерисовать() {
      список.textContent = "";
      ветви.forEach(function (в, i) {
        var строка = el("div", "");
        строка.style.display = "flex";
        строка.style.gap = "6px";
        строка.style.alignItems = "baseline";
        var убрать = el("button", "addone", "×");
        убрать.type = "button";
        убрать.title = T("убрать из плана");
        убрать.addEventListener("click", function () {
          ветви.splice(i, 1); перерисовать();
        });
        строка.appendChild(убрать);
        строка.appendChild(el("span", "", (i + 1) + "."));
        // НАЗВАНИЕ ПРАВИТСЯ ЗДЕСЬ, а не только вычёркивается. Разрез
        // «название — пояснение» угадан по чужому тексту, и промах в нём
        // станет названием дела, которое человек потом читает в списке.
        var поле = document.createElement("input");
        поле.type = "text";
        поле.value = в.title;
        поле.style.flex = "1";
        поле.setAttribute("aria-label", T("название ветви"));
        поле.addEventListener("input", function () {
          в.title = поле.value.slice(0, 200);
          обновитьКнопку();
        });
        строка.appendChild(поле);
        список.appendChild(строка);
      });
      обновитьКнопку();
    }
    var записать = el("button", "addone", "");
    записать.type = "button";
    записать.addEventListener("click", async function () {
      записать.disabled = true;
      var было = записать.textContent;
      записать.textContent = T("Записываю…");
      if (state.caseId !== дело) {
        записать.disabled = true;
        о.appendChild(el("div", "", T("Дело успели сменить. План разбирался по "
          + "другому разговору и сюда не записан — откройте разложение заново.")));
        return;
      }
      try {
        await api("POST", "/cases/" + encodeURIComponent(дело) + "/branches",
                  { branches: ветви.map(function (в) {
                      // Название из одних пробелов длину имеет, а смысла нет:
                      // min_length=1 такое пропустит, и в картотеке появится
                      // дело без имени.
                      return { title: в.title.trim(), purpose: в.purpose };
                    }),
                    // БЕЗ T(): это уходит в журнал НАВСЕГДА, а журнал читают
                    // оба участника дела, и языки у них разные. Переводится
                    // при показе — см. «Основание: » в рисоватьСхему.
                    source: "из ответа агента в этом деле" });
      } catch (e) {
        записать.disabled = false;
        записать.textContent = было;
        о.appendChild(el("div", "", T("План не записался: ") + reason(e)));
        return;
      }
      await дописатьЖурнал(true);
      state.ветвиРаскрыты = true;
      обновитьСхему();
      о.textContent = "";
      о.appendChild(el("div", "", T("План лёг в схему. Нажмите на ветвь, чтобы " +
        "раскрыть её и завести по ней дело.")));
    });
    о.appendChild(список);
    о.appendChild(записать);
    перерисовать();
  }

  /* Пилюли схемы. НЕ новые пути, а двери к уже построенным: «участник»
     ведёт к форме приглашения (crew), «документ» — развилкой к черновику
     бумаги (paperdraft, проект придёт на подтверждение) или к скрепке
     (приложить готовый файл). Заводить здесь третий путь того же действия
     значило бы получить две правды об одном — как уже случалось. */
  (function схемаПилюли() {
    var кто = document.getElementById("sxaddwho");
    var док = document.getElementById("sxadddoc");
    var ветви = document.getElementById("sxbranches");
    var описание = document.getElementById("sxdesc");
    if (ветви) ветви.addEventListener("click", предложитьВетви);
    if (кто) кто.addEventListener("click", function () {
      var короб = document.getElementById("crew");
      var кнопка = document.getElementById("addone");
      if (короб) { короб.hidden = false; короб.scrollIntoView({ block: "center" }); }
      if (кнопка) кнопка.click();
    });
    if (док) док.addEventListener("click", function () {
      if (!описание) return;
      описание.hidden = false;
      описание.textContent = "";
      описание.appendChild(document.createTextNode(
        T("Проект пишется здесь и придёт на подтверждение; готовый файл — прикладывается. ")));
      var составить = el("button", "addone", T("Составить проект"));
      составить.type = "button";
      составить.addEventListener("click", function () {
        var короб = document.getElementById("paperdraft");
        if (короб) { короб.hidden = false; короб.scrollIntoView({ block: "center" }); }
        var поле = document.getElementById("draftask");
        if (поле) поле.focus();
      });
      var приложить = el("button", "addone", T("Приложить файл"));
      приложить.type = "button";
      приложить.addEventListener("click", function () {
        var f = document.getElementById("file");
        if (f) f.click();
      });
      описание.appendChild(составить);
      описание.appendChild(document.createTextNode(" "));
      описание.appendChild(приложить);
    });
  })();

  /* Докуда журнал дела уже нарисован на экране.

     null — дело не открыто или журнал ещё не читали. Число — наибольший seq
     события, которое либо нарисовано, либо учтено молча (см. дописатьЖурнал).
     Обнуляется вместе с чтением журнала: иначе в новое дело допишется хвост
     прежнего. */
  var лентаДо = null;

  async function replayDialog(id) {
    лентаДо = null;
    state.события = [];
    /* ЖУРНАЛ ЧИТАЕТСЯ СТРАНИЦАМИ, а не одним запросом. Служба отдаёт по 200
       событий (`LIMIT 200` в list_events), и один запрос приносил НАЧАЛО
       журнала. На деле практика — несколько прогонов и переписка — событий
       давно больше двухсот, и человек видел первые реплики, а последних не
       видел никогда. Схема дела молчала по той же причине: план ложится
       поздним событием и в первую страницу не попадает.

       Предел на число страниц есть: пять тысяч событий — уже не разговор, и
       бесконечно ходить за хвостом, которого не видно, незачем. Что дочитали
       не всё, говорим вслух: молчащий обрыв здесь — та же ложь, только тише. */
    var evs = [], СТРАНИЦ = 25, дочитали = false;
    try {
      var с_какого = 0;
      for (var стр = 0; стр < СТРАНИЦ; стр++) {
        var кусок = await api("GET", "/cases/" + id + "/events?since_seq=" + с_какого);
        кусок = кусок || [];
        evs = evs.concat(кусок);
        if (кусок.length < 200) { дочитали = true; break; }
        var край = с_какого;
        кусок.forEach(function (e) {
          if (typeof e.seq === "number" && e.seq > край) край = e.seq;
        });
        if (край < с_какого + 1) { дочитали = true; break; }   // служба не движется
        с_какого = край + 1;
      }
    } catch (e) {
      сорвалось(T("Журнал дела не прочитался: "), e,
                T(". Разговор при этом цел — он живёт в деле, а не на этой странице."));
      return 0;
    }
    if (!дочитали) say("bot", "Ф", T("Журнал этого дела длиннее, чем я показываю: "
      + "прочитаны первые пять тысяч записей. Дело от этого цело — просто "
      + "самое давнее осталось за краем."));
    var n = 0;
    (evs || []).forEach(function (e) {
      if (e.kind !== "dialog") return;
      var p = e.payload || {};
      if (!p.text) return;
      if (p.role === "assistant") {
        say("bot", "Ф", p.text);
      } else if (p.role === "user") {
        var кто = авторРеплики(e);
        if (кто && кто === state.principal) {
          say("you", "Вы", p.text);
        } else {
          // И чужая реплика, и реплика без автора идут сюда — но выглядят
          // по-разному: у второй пунктирный кружок и честная подпись.
          сказалДругой(e, p.text);
        }
      }
      n++;
    });
    /* Отметка ставится по ВСЕМ событиям, а не только по нарисованным
       репликам: между ними лежат выдача мандата, правки дела и прочее
       служебное. Считай отметку по репликам — и дорисовка приносила бы весь
       этот шум заново, чтобы каждый раз его отбросить.

       НОЛЬ, А НЕ null, КОГДА ЖУРНАЛ ПУСТ. Разница не бухгалтерская: null
       означает «где мы — неизвестно», и дорисовка при нём молчит. Пустой
       журнал — это ЗНАНИЕ: мы на нуле, спрашивать надо с первого события.
       Поймано живой проверкой 27.08.2026 на только что заведённом деле:
       ответ дописали в журнал со стороны службы, тик прошёл, на экране не
       появилось ничего. А пустой журнал — это как раз свежее дело, где
       первый ответ и приходит. */
    лентаДо = 0;
    (evs || []).forEach(function (e) {
      if (typeof e.seq === "number" && e.seq > лентаДо) лентаДо = e.seq;
    });
    state.события = evs || [];
    обновитьСхему();
    if (!n) {
      say("bot", "Ф", "В журнале этого дела реплик нет — продолжайте, " +
          "я подхвачу с того, что записано в самом деле.");
    }
    log.scrollTop = log.scrollHeight;
    return n;
  }


  /* ДОРИСОВКА ЖУРНАЛА ОТКРЫТОГО ДЕЛА.
     ═══════════════════════════════════════════════════════════════════════
     Опрос до 26.08.2026 журнал открытого дела не трогал, и оговорка рядом с
     ним называла причину: replayDialog только дописывает, а чистит openCase,
     который на том же деле делает ранний возврат. Обновлять дело тиком
     значило либо дублировать реплики, либо стирать разговор под руками.

     Обе беды лечит отметка. Служба дел умеет отдавать журнал с места —
     `since_seq` был в ручке с самого начала и оболочкой не использовался.
     Значит не «перерисовать всё», а «дописать то, чего нет».

     ЗАЧЕМ ЭТО ПОНАДОБИЛОСЬ. Дверь ждёт хода 60 секунд, dialog работает до
     180. Ход длиннее минуты человек видел как «связь оборвалась», а ответ
     дописывался в дело следом — замерено 26.08: дверь сдалась в 16:46:17,
     ответ лёг в 16:46:59. Дверь теперь говорит правду: «ответ ещё пишется,
     он появится в этом деле сам». Без дорисовки это обещание сбывалось лишь
     после перезагрузки страницы — то есть было неправдой.

     ЧЕГО НЕ РИСУЕМ И ПОЧЕМУ. Своей реплики: её оболочка нарисовала сама, в
     тот миг, когда человек нажал «отправить». Ответа, уже показанного по
     возвращении хода: для этого сразу после удачного хода отметка двигается
     МОЛЧА, без рисования. Оба случая — про «уже на экране», а не про «не
     важно».

     ЧЕГО ЭТО НЕ ЛЕЧИТ. Двух вкладок: реплика, отправленная в соседней
     вкладке, здесь не появится — по автору она своя, а на экране её нет.
     Прежде не появлялось вообще ничего, так что хуже не стало; лечится это
     не отметкой, а признаком «нарисовано в этой вкладке». */
  async function дописатьЖурнал(молча) {
    if (!state.caseId || лентаДо === null) return 0;
    var дело = state.caseId;
    var evs;
    try {
      evs = await api("GET", "/cases/" + encodeURIComponent(дело) +
                      "/events?since_seq=" + (лентаДо + 1));
    } catch (e) {
      // Разовый отказ молчит: журнал цел, он живёт в деле. Скажем следующим
      // тиком, а пугать человека посреди разговора нечем.
      return 0;
    }
    // Дело успело смениться, пока мы ходили за журналом: дописывать нечего и
    // некуда — это реплики одного разговора в другом.
    if (state.caseId !== дело) return 0;
    var n = 0;
    var край = лентаДо;
    /* ЖУРНАЛ — ЕДИНСТВЕННЫЙ ЗВОНОК О РАБОТЕ АГЕНТА, и до 28.08.2026 в него
       никто не звонил.

       Опрос раз в 45 секунд обновлял колокол, переписку и реплики — а
       разделы дела «Ждёт вашего слова» и «Работа» перерисовывались ТОЛЬКО
       при открытии дела и по нажатиям человека. Значит, после «Принял. Проект
       придёт вам на подтверждение» оболочка больше ни разу не спрашивала,
       пришёл ли он: проект лежал готовым в деле, а на экране не появлялось
       ничего, пока человек не догадается перезагрузить страницу.

       Так и вышло 28.08 с договором аренды: прогон в waiting_approval,
       предложение в pending_approval на 5773 знака — и пусто на экране.

       Будим по СОБЫТИЯМ прогона, а не по каждому тику: лишние два запроса
       каждые 45 секунд на всякое открытое дело — это то, ради чего схему
       когда-то и запретили спрашивать службы самой. */
    var работа = false;
    (evs || []).forEach(function (e) {
      if (typeof e.seq === "number" && e.seq > край) край = e.seq;
      (state.события = state.события || []).push(e);
      var вид = e.kind || "";
      if (вид.indexOf("run.") === 0 || вид.indexOf("patch.") === 0) работа = true;
      // Общие таблицы дела: событие несёт только номера и счёт (никогда
      // значения), и реакция всегда одна — перечитать таблицу или список.
      // Молчаливый тик её не глушит: список и открытая таблица обязаны
      // обновиться и тогда, когда журнал не дорисовывается на экране.
      if (вид.indexOf("table.") === 0) событиеТаблиц(e);
      if (молча || e.kind !== "dialog") return;
      var p = e.payload || {};
      if (!p.text) return;
      if (p.role === "assistant") {
        say("bot", "Ф", p.text);
        n++;
      } else if (p.role === "user") {
        var кто = авторРеплики(e);
        if (кто && кто === state.principal) return;   // своё уже на экране
        сказалДругой(e, p.text);
        n++;
      }
    });
    лентаДо = край;
    if (evs && evs.length) обновитьСхему();
    if (работа) { renderPending(); renderRun(); }
    if (n) log.scrollTop = log.scrollHeight;
    return n;
  }

  /* Реплика другого участника — со своей подписью над пузырём. */
  function сказалДругой(e, текст) {
    var имя = имяАвтора(e, e.payload || {});
    var неизвестен = !авторРеплики(e);
    var b = bubble("mate", значокАвтора(имя));
    var строка = b.parentNode;
    if (строка && неизвестен) строка.classList.add("unknown");
    if (строка && неизвестен) {
      строка.title = T("кто это сказал — в журнале дела не записано");
    }
    // Подпись СТАВИМ ТЕКСТОМ и перед содержимым: render() разбирает разметку
    // ответа, и имя, попавшее внутрь неё, стало бы частью разбираемого.
    var подпись = el("span", "mname", имя);
    b.appendChild(подпись);
    var тело = el("div");
    render(тело, текст);
    b.appendChild(тело);
    log.scrollTop = log.scrollHeight;
    return b;
  }

  /* Выйти из дела в общий разговор. Дела эта кнопка не заводит и не закрывает
     — она только отпускает открытое: в общем разговоре дело появляется по
     предложению сервера и подтверждению человека, а не по нажатию здесь.

     Пока Inbox закрыт флагом раскатки, кнопка означает прежнее «новое дело»:
     общего разговора нет, и первое же сообщение заведёт дело. Называть одним
     словом два разных исхода нельзя, поэтому и подпись, и объяснение разные. */
  function toGeneral() {
    // Дела больше нет — значит и хвоста от него быть не должно. Здесь уборка
    // идёт ПЕРВОЙ строкой, в отличие от openCase: читать нечего, отказу
    // взяться неоткуда, выхода на полпути нет.
    покинутьДело();
    state.caseId = null;
    обновитьСхему();
    // Состав чужого дела не должен пережить переход: иначе подписи чужих
    // реплик достанутся следующему делу.
    state.caseParticipants = [];
    // Дела нет — и бумаг дела на экране быть не должно. renderPapers сам
    // спрячет короб, увидев пустой caseId; звать его надо ПОСЛЕ сброса.
    setTimeout(renderPapers, 0);
    state.caseTitle = null;
    state.domain = null;
    state.agent = null;
    rememberCase("");
    log.innerHTML = "";
    // Три состояния, как в приветствии и в строке места. Прежде здесь их было
    // два, и неизвестность печаталась обещанием: при mode=live с процентной
    // раскаткой девять человек из десяти читали «дело здесь не заводится», а
    // следующее их сообщение уходило в 404 и откат.
    if (state.inbox === false) {
      showEmpty("Новое дело заведётся с первого сообщения — заполнять ничего " +
                "не нужно. Прежние дела остались в списке выше.");
      say("bot", "Ф", "Слушаю. Расскажите, что нужно, — заведу новое дело.");
    } else if (state.inbox === null) {
      showEmpty("Дело не выбрано. Включён ли для вас общий разговор — " +
                "выяснится на первом сообщении.");
      say("bot", "Ф", "Дело закрыто. Включён ли для вас общий разговор, я " +
          "пока не знаю — выяснится на первом сообщении. Без вашего согласия " +
          "дело не заведётся в любом случае.");
    } else {
      showEmpty("Дело не выбрано. Разговор сейчас общий: дело из него " +
                "само не заведётся — я предложу, а решите вы.");
      say("bot", "Ф", "Вы в общем разговоре. Дело здесь не заводится: если из " +
          "сказанного получится задача, я предложу завести — и заведётся оно " +
          "только после вашего согласия.");
    }
    startChips();
    // Тоже через пилюли: открытого дела больше нет, и «отнести это дело»
    // должно исчезнуть вместе с ним — иначе оно отнесёт прежнее.
    renderWhere();
    renderScopes();
    // Короба прежнего дела обязаны погаснуть вместе с ним. Без этого на
    // экране оставались полоса прогона и «Дело о: …» от дела, которого на
    // экране больше нет.
    renderRun();
    renderSubject();
    renderCommission();
    renderPending();
  }

  /* Сохранённое дело подставляем только если оно всё ещё в списке ЭТОГО
     человека. Иначе после выхода из аккаунта чужой ключ в браузере открыл бы
     чужое дело — точнее, попытался бы и получил отказ, что ещё хуже: похоже
     на поломку. */
  async function restoreCase() {
    /* АДРЕС СИЛЬНЕЕ СОХРАНЁННОГО КЛЮЧА. Он назван человеком — ссылкой,
       закладкой, вставкой в строку, — а ключ лишь помнит, где кто-то был
       последним. Ключ остаётся запасным: без решётки в адресе он и работает
       как прежде. */
    var id = читатьАдрес() || savedCase();
    if (!id || state.caseId) return;
    // Список не прочитался — проверить принадлежность нечем. Открыть вслепую
    // нельзя (после смены аккаунта это было бы чужое дело), но и забыть
    // нельзя: дело не виновато, что список не пришёл.
    if (!state.casesOk) return;
    /* УЧАСТНИК — ТОЖЕ ХОЗЯИН СВОЕГО ВОЗВРАЩЕНИЯ. Прежде здесь стояло
       `isMine(c)`, и дело, где человек участник, а не владелец, молча
       забывалось: он видел «дело не выбрано» и не понимал, куда оно делось.
       Это то же самое заблуждение, которое уже исправлено в строке списка:
       дверь ПУСКАЕТ участника с правом читать, проверено живым вызовом.
       Достаточно того, что дело есть в списке ЭТОГО человека — список ему и
       отдан по праву; а отказ, если он всё-таки будет, openCase разберёт
       словами (403, 410, 503 у него названы поимённо). */
    var found = state.cases.filter(function (c) { return c.id === id; })[0];
    if (!found) { rememberCase(""); return; }
    await openCase(id);
  }

  /* ── Приложенное к делу ───────────────────────────────────────────── */

  /* Файл кладётся в ЛИЧНОЕ хранилище человека, а к делу привязан тем, откуда
     пришёл (source_case_id). Поэтому «приложено к делу» — это прочитанная
     колонка, а не вторая копия файла где-то рядом с делом: документ остаётся
     у владельца и переживёт дело.

     Предел продублирован здесь ради ответа ДО чтения и отправки: узнать
     «нельзя» после того, как стомегабайтный файл уехал, — значит потратить
     чужое время впустую. Настоящий предел живёт на сервере (VAULT_MAX_BYTES)
     и может оказаться меньше нашего — тогда придёт 413, и его мы показываем
     словами, а не молчим. */
  var MAX_FILE = 64 * 1024 * 1024;


  /* Что ждёт слова человека.

     Ворота подтверждения построены давно (риск выше порога кладёт патч в
     ожидание, approve и reject открыты в шлюзе), но НАЖАТЬ их было нечем: ни
     одна страница их не вызывала. Пока так, «человек подтверждает» оставалось
     свойством схемы, а не свойством продукта.

     ГЛАВНОЕ ЗДЕСЬ — ПОКАЗАТЬ СОДЕРЖИМОЕ, А НЕ ФАКТ. Кнопка «подтвердить» под
     строкой «патч propose_outbound_message» — это подпись вслепую: человек
     согласится, потому что его спросили, а не потому, что он прочитал. Письмо
     постороннему отменить нельзя, поэтому текст показывается целиком и рядом
     с адресатом. */
  var pendingBusy = {};

  function describePatch(p) {
    var v = p.value || {};
    if (p.op === "propose_outbound_message") {
      return {
        what: "Письмо продавцу — уйдёт, только если вы подтвердите",
        who: v.recipient_ref || v.option_id || "",
        text: (v.subject ? v.subject + "\n\n" : "") + (v.body || ""),
      };
    }
    if (p.op === "reject_options") {
      var n = (v || []).length || 0;
      return {
        what: T("Отсев: убрать ") + n + " " + plural(n, "вариант", "варианта", "вариантов"),
        who: "",
        text: (v || []).map(function (x) {
          return "• " + (x.option_id || "") + " — " + (x.reason || T("без причины"));
        }).join("\n"),
      };
    }
    if (p.op === "add_panel") {
      /* Панель без этой ветки показывалась запасной: «Изменение в деле:
         add_panel» и следом четыре с половиной тысячи знаков разметки.
         Спрятана она не была — и это правильно, — но прочитать её было
         нельзя, а подтверждают именно прочитанное.

         Подписи берём из самой разметки. Разбирать HTML разбором строк
         обычно плохо, но эту разметку собрали МЫ (shared/panels.py), по
         одному шаблону: подписи всегда в <label>, всегда экранированы.
         Промах здесь стоит одной непоказанной строки, а не дыры. */
      var подписи = [];
      String(v.html || "").replace(/<label[^>]*>([\s\S]{1,120}?)<\/label>/g,
        function (_, кусок) {
          подписи.push(кусок.replace(/<[^>]+>/g, "").trim());
          return "";
        });
      if (!подписи.length) подписи = (v.fields || []).slice(0, 12);
      return {
        what: T("Форма к заполнению: ") + (v.title || T("без названия")),
        who: подписи.length + " " + plural(подписи.length, "поле", "поля", "полей"),
        text: подписи.map(function (x) { return "• " + x; }).join("\n")
            + T("\n\nПодтвердите — форма откроется на холсте. Заполненное "
            + "попадёт в поле ввода, и вы увидите его прежде, чем отправите."),
      };
    }
    if (p.op === "add_draft_document") {
      /* ПРОЕКТ ДОКУМЕНТА показывается ЦЕЛИКОМ. Под этой бумагой предстоит
         подписаться, и «подтвердить проект документа» без текста — это
         подпись вслепую в самом дорогом месте, какое у нас есть.

         Пропуски идут отдельным списком и ПЕРЕД текстом: то, чего в проекте
         не хватает, дороже того, что в нём есть, и внизу длинного документа
         оно не прочитается. */
      var пропуски = (v.gaps || []).map(function (g) { return "— " + g; });
      var шапка = пропуски.length
        ? "НЕ ЗАПОЛНЕНО (проверьте):\n" + пропуски.join("\n") + "\n\n"
        : "";
      var основание = v.basis ? "\n\nОснование: " + v.basis : "";
      return {
        what: "Проект документа: " + (v.title || "без названия"),
        who: пропуски.length
          ? пропуски.length + " " + plural(пропуски.length, "пропуск",
                                           "пропуска", "пропусков")
          : "заполнено полностью",
        // Пропуски ОТДЕЛЬНО от текста: их место — в карточке, рядом с
        // кнопками решения, а место самого документа — на холсте.
        пропуски: пропуски,
        наХолст: { title: v.title || "Проект документа", вид: "proposal" },
        text: шапка + (v.body || "") + основание
          + "\n\nПодтверждение кладёт текст в дело КАК ПРОЕКТ. Он не "
          + "подписан и не подан: выправить, подписать и подать — ваши "
          + "отдельные действия.",
      };
    }
    if (p.op === "propose_decision") {
      return { what: "Предложено решение", who: p.target || "",
               text: typeof v === "string" ? v : JSON.stringify(v, null, 2) };
    }
    // Незнакомая операция. Показываем как есть: молча спрятать то, что просят
    // подтвердить, — худшее из возможного.
    return { what: T("Изменение в деле: ") + p.op, who: p.target || "",
             text: typeof v === "string" ? v : JSON.stringify(v, null, 2) };
  }

  /* Число и форма слова.

     ПРАВИЛА У ЯЗЫКОВ РАЗНЫЕ, и одним словарём тут не обойтись. По-русски форм
     три и выбирает их остаток: «1 поле», «2 поля», «5 полей». По-английски их
     две, и правило другое — всё, кроме единицы, множественное.

     Если оставить русский выбор и просто перевести формы по отдельности,
     получится «21 time» вместо «21 times»: остаток от 21 равен единице, и
     русское правило возьмёт единственное число там, где английскому нужно
     множественное. Поломка тихая — читается как небрежность, а не как ошибка.

     Поэтому язык решает ПРАВИЛО, а словарь — только слова. Английскому
     достаётся `one` для единицы и `few` для всего остального: вторая форма в
     словаре и есть множественная. */
  function plural(n, one, few, many) {
    if (window.ЯЗЫК && window.ЯЗЫК.английский) {
      return T(Math.abs(n) === 1 ? one : few);
    }
    var a = Math.abs(n) % 100, b = a % 10;
    if (a > 10 && a < 20) return many;
    if (b > 1 && b < 5) return few;
    return b === 1 ? one : many;
  }

  /* Поручить агенту работу по делу.

     Кнопка появляется там, где план ЕСТЬ: у дел, чей шаблон его не объявил,
     поручать нечего, и предлагать это значило бы обещать работу, которая не
     начнётся. Что именно агент сделает — решено пакетом направления заранее,
     здесь человек говорит только «начинай». */
  var runBusy = false;

  /* ЧТО ИСКАТЬ — из заголовка дела, но БЕЗ ХВОСТА ПРО МЕСТО И ПОВОД.

     Замерено на живой витрине АгриФореста 21.08.2026, а не выведено из
     общих соображений:

       «Аренда экскаватора»                        → 10 находок
       «Аренда экскаватора в Ленинградской области» →  0
       «Копка траншеи»                             →  6
       «Копка траншеи под фундамент в Ленобласти»  →  0
       «Мини-экскаваторы»                          → 10

     Дело не в длине, а в хвосте: витрина ищет по названию услуги и на
     обстоятельствах промахивается. А ноль находок роняет шаг и весь прогон
     (run_executor.py: «источники не дали ни одной находки»), то есть
     неудачная формулировка выглядит как поломка системы.

     ЭТО ДОГАДКА, И ОНА ОБЪЯВЛЕНА ДОГАДКОЙ: строка ложится в поле, человек
     видит её до нажатия и правит. Тот же приём, что у панели на холсте —
     заполненное не уходит само. */
  function короткийЗапрос(заголовок) {
    var т = String(заголовок || "").trim();
    if (!т) return "";
    // Сперва отрезаем пояснение после двоеточия и тире.
    т = т.split(/[:—–]/)[0];
    // Затем хвост, начинающийся предлогом: место, повод, назначение.
    т = т.replace(/\s+(в|во|на|под|для|из|от|по|с|со)\s+.*$/i, "");
    т = т.replace(/[,;].*$/, "").trim();
    return т.slice(0, 120);
  }

  /* Показать поручение — и только когда поручать ЕСТЬ ЧТО.

     Без закреплённого шаблона у дела нет плана, а без плана прогону нечего
     исполнять. Показать кнопку в этом случае значило бы предложить действие,
     которое обязано не сработать: на проде такие дела есть — три штуки от
     20.08 с template_version = 0 и планом из нуля шагов. */
  function renderCommission() {
    var короб = document.getElementById("commission");
    var поле = document.getElementById("runquery");
    var подсказка = document.getElementById("runhint");
    if (!короб || !поле) return;
    if (!state.caseId) { короб.hidden = true; return; }
    if (!state.caseHasPlan) {
      короб.hidden = true;
      return;
    }
    короб.hidden = false;
    // Не затираем набранное человеком: он мог поправить строку и отвлечься.
    if (!поле.value) поле.value = короткийЗапрос(state.caseTitle);
    if (подсказка) {
      подсказка.textContent = T("Короткое название услуги ищется лучше: место и повод витрина не " +
        "понимает и отвечает пустотой.");
    }
  }

  /* ПРОСЬБА СОСТАВИТЬ ПРОЕКТ ДОКУМЕНТА.

     Короб показывается ТОЛЬКО когда шаблон дела объявил шаг по просьбе.
     Предлагать составление там, где его не объявлено, значит обещать отказ:
     служба ответит «в плане шаблона нет шагов», и человек решит, что сломано.

     Порог доверия шага сюда не дублируется намеренно. Решает служба, а
     оболочка называет её отказ словами: второй порог на экране разошёлся бы
     с настоящим при первой же правке пакета. */
  function renderPaperDraft() {
    var короб = document.getElementById("paperdraft");
    var поле = document.getElementById("draftask");
    var подсказка = document.getElementById("drafthint");
    if (!короб || !поле) return;
    var шаги = state.caseDraftSteps || [];
    if (!state.caseId || !шаги.length) { короб.hidden = true; return; }
    короб.hidden = false;
    var ярлык = document.querySelector('label[for="draftask"]');
    if (ярлык && шаги[0].title) ярлык.textContent = шаги[0].title;
    if (подсказка) {
      подсказка.textContent =
        "Проект соберётся из того, что названо в деле и в вашей просьбе. " +
        "Чего в деле нет — реквизитов, номеров, сумм — он не придумает, а " +
        "оставит пропуском. Готовое придёт вам на подтверждение.";
    }
  }

  /* ═══ ОБЩИЕ ТАБЛИЦЫ ДЕЛА ═════════════════════════════════════════════════
     Просьба владельца 13.09.2026 после живой пробы пака «Бюджет семьи
     вдвоём»: «надо добавить таблицы для общего доступа и редактирования».
     Служба — services/case_service/tables.py: версия у КАЖДОЙ ЯЧЕЙКИ
     отдельно, а не у документа целиком, — правки разных ячеек никогда не
     спорят, спорит только та, где двое написали в одну секунду.

     ДВЕ ДОРОГИ К ЖИВОМУ ОБНОВЛЕНИЮ. Общий 45-секундный опрос дописывает
     журнал дела и уже видит любое событие; здесь он вызывает событиеТаблиц —
     тот решает, перечитать ли список или открытую таблицу (см. правку
     дописатьЖурнал ниже). Пока грид открыт и вкладка видна, работает ЕЩЁ и
     частый опрос раз в 10 с — но только по `table.cells_updated`: состав
     строк меняется редко и его ловит общий опрос, а вот ЗНАЧЕНИЯ ячеек у
     таблицы, открытой на двух экранах разом, — это как раз то, что должно
     доезжать быстро.

     ГЛАВНОЕ ПРАВИЛО СЛИЯНИЯ, и оно одно на весь раздел: ячейку, которую
     человек сейчас правит (в фокусе) или уже поправил, но ещё не сохранил
     (грязная), СЮДА НЕ ПУСКАЕМ — ни при перечитывании по событию, ни при
     опросе. Слияние решает версией ответа службы, а не временем его
     прихода: старее локальной — не трогаем, новее — переносим на экран.

     СОСТОЯНИЕ ХРАНИТ DOM, А НЕ ВТОРАЯ КОПИЯ В JS. Текущая версия и значение
     ячейки живут в `td.dataset` (ключи латиницей camelCase — см.
     project-memory про «датасет на кириллице»): заводить рядом ещё и объект
     со строками означало бы держать две правды и однажды дать им разойтись. */

  var РОДА_ТАБЛИЦ = [                 // роды сведений, предлагаемые в форме
    { key: "normal",    title: "обычные сведения" },
    { key: "financial", title: "финансовые" },
    { key: "pii",       title: "личные" },
    { key: "medical",   title: "медицинские" },
    { key: "legal",     title: "юридические" },
    { key: "biometric", title: "биометрические" }
  ];
  var видСтолбцаСловом = { text: "текст", number: "число", date: "дата" };
  //: Ровно MAX_TABLE_CELLS_PER_PATCH из shared/schemas/cases.py — своей
  //: копией числа, а не тем же импортом: языки разные, файл один и тот же
  //: прочитать нельзя. Разойдись оно с сервером — сервер откажет лишним,
  //: и это будет 422, а не тихая потеря.
  var ЯЧЕЕК_ЗА_РАЗ = 25;

  // Список таблиц дела и допуск текущего участника — обновляются renderSheets.
  var списокТаблиц = [];
  var таблицыМожноПисать = false;
  var таблицыВидноРод = [];
  // Открытая таблица: вид, как его вернула служба (id, title, columns,
  // rows, totals, can_edit…). null — грид закрыт, виден список.
  var открытаяТаблица = null;
  var открытаяТаблицаId = null;
  // Несохранённые правки: "row_id|col_key" -> {rowId,colKey,value,expectVersion}.
  var грязныеЯчейки = {};
  // "row_id|col_key" ячейки, которая сейчас в фокусе, или null.
  var ячейкаВФокусе = null;
  var спорыТаблицы = [];              // текущие неразрешённые споры сохранения
  var таймерСохраненияЯчеек = null;
  var сохранениеЯчеекИдёт = null;     // Promise текущего сохранения, или null
  var счётчикКлючейСтолбца = 1;       // для новых ключей c1, c2… в форме
  var опросТаблицыТаймер = null;
  var опросТаблицыДо = null;

  // ── Список таблиц ──────────────────────────────────────────────────────

  async function renderSheets() {
    var box = document.getElementById("sheets");
    if (!box) return;
    if (!state.caseId) { box.hidden = true; return; }
    // Грид открыт — короб виден, а список ему не мешает: перечитывать его,
    // пока человек смотрит в таблицу, незачем, и звать сюда не должны те,
    // кто уже знает про открытую таблицу (событиеТаблиц зовёт её ветку сам).
    if (открытаяТаблицаId) { box.hidden = false; return; }
    var дело = state.caseId;
    var ответ;
    try {
      ответ = await api("GET", "/cases/" + encodeURIComponent(дело) + "/tables");
    } catch (e) {
      // Разовый отказ — короб прячем молча, как соседние разряды бумаг:
      // следующий опрос или открытие дела перечитают список заново.
      box.hidden = true;
      return;
    }
    if (state.caseId !== дело) return;   // дело сменилось, пока список ехал
    box.hidden = false;
    списокТаблиц = (ответ && ответ.tables) || [];
    таблицыМожноПисать = !!(ответ && ответ.can_edit);
    таблицыВидноРод = (ответ && ответ.may_see) || [];
    нарисоватьСписокТаблиц(списокТаблиц, (ответ && ответ.hidden) || 0);
  }

  function делоЗакрытоЛи() {
    return !!(state.схемаДела && state.схемаДела.закрыто);
  }

  function нарисоватьСписокТаблиц(таблицы, скрыто) {
    var список = document.getElementById("sheetlist");
    var скрытоСтрока = document.getElementById("sheethidden");
    var кнопкаНовая = document.getElementById("sheetnew");
    if (!список) return;
    список.innerHTML = "";
    if (!таблицы.length && !скрыто) {
      список.appendChild(el("div", "fnote",
        "Общих таблиц в этом деле пока нет."));
    }
    таблицы.forEach(function (t) {
      var row = el("div", "doc1");
      var имя = el("span", "dn", t.title || "Таблица");
      имя.style.cursor = "pointer";
      имя.title = T("Открыть таблицу");
      имя.tabIndex = 0;
      имя.addEventListener("click", function () { открытьТаблицу(t.id); });
      имя.addEventListener("keydown", function (e) {
        if (e.key === "Enter" || e.key === " ") { e.preventDefault(); открытьТаблицу(t.id); }
      });
      row.appendChild(имя);
      row.appendChild(el("span", "dst",
        (t.rows_total || 0) + " стр. · " + when(t.updated_at)));
      список.appendChild(row);
    });
    if (скрытоСтрока) {
      if (скрыто > 0) {
        скрытоСтрока.hidden = false;
        скрытоСтрока.textContent =
          T("Ещё таблиц, закрытых для вас: ") + скрыто;
      } else {
        скрытоСтрока.hidden = true;
      }
    }
    if (кнопкаНовая) {
      кнопкаНовая.hidden = !таблицыМожноПисать || делоЗакрытоЛи();
    }
  }

  // ── Форма новой таблицы ─────────────────────────────────────────────────

  function новыйКлючСтолбца() {
    return "c" + (счётчикКлючейСтолбца++);
  }

  function добавитьСтолбецФормы(key, label, kind) {
    var контейнер = document.getElementById("sheetcols");
    if (!контейнер) return;
    if (контейнер.children.length >= 20) return;   // предел службы — 20 столбцов
    var row = el("div", "stcolrow");
    row.dataset.colKey = key;
    var метка = document.createElement("input");
    метка.type = "text";
    метка.maxLength = 80;
    метка.className = "stcollabel";
    метка.placeholder = T("название столбца");
    метка.value = label || "";
    var вид = document.createElement("select");
    вид.className = "stcolkind";
    ["text", "number", "date"].forEach(function (k) {
      var o = document.createElement("option");
      o.value = k;
      o.textContent = T(видСтолбцаСловом[k]);
      if (k === (kind || "text")) o.selected = true;
      вид.appendChild(o);
    });
    var убрать = el("button", "addone stcolrm", "Убрать");
    убрать.type = "button";
    убрать.addEventListener("click", function () { row.remove(); });
    row.appendChild(метка);
    row.appendChild(вид);
    row.appendChild(убрать);
    контейнер.appendChild(row);
  }

  function применитьПресетБюджета() {
    var контейнер = document.getElementById("sheetcols");
    if (контейнер) контейнер.innerHTML = "";
    счётчикКлючейСтолбца = 1;
    добавитьСтолбецФормы(новыйКлючСтолбца(), "Дата", "date");
    добавитьСтолбецФормы(новыйКлючСтолбца(), "Статья", "text");
    добавитьСтолбецФормы(новыйКлючСтолбца(), "Сумма", "number");
    добавитьСтолбецФормы(новыйКлючСтолбца(), "Кто", "text");
  }

  function заполнитьВыборРода() {
    var выбор = document.getElementById("sheetsens");
    if (!выбор) return;
    выбор.innerHTML = "";
    var доступно = таблицыВидноРод.length ? таблицыВидноРод : ["normal"];
    РОДА_ТАБЛИЦ.forEach(function (р) {
      if (доступно.indexOf(р.key) < 0) return;
      var o = document.createElement("option");
      o.value = р.key;
      o.textContent = T(р.title);
      выбор.appendChild(o);
    });
    // Умолчание — финансовый род, раз он открыт: первый пользователь —
    // семейный бюджет, и почти всегда это он. Иначе — обычный.
    var предпочесть = доступно.indexOf("financial") >= 0 ? "financial"
                     : (доступно.indexOf("normal") >= 0 ? "normal" : доступно[0]);
    if (предпочесть) выбор.value = предпочесть;
  }

  function показатьФормуТаблицы() {
    var форма = document.getElementById("sheetform");
    var ошибка = document.getElementById("sheetformerr");
    var поле = document.getElementById("sheettitle");
    var столбцы = document.getElementById("sheetcols");
    if (!форма) return;
    if (поле) поле.value = "";
    if (ошибка) ошибка.textContent = "";
    if (столбцы) столбцы.innerHTML = "";
    счётчикКлючейСтолбца = 1;
    добавитьСтолбецФормы(новыйКлючСтолбца(), "", "text");
    заполнитьВыборРода();
    форма.hidden = false;
    if (поле) поле.focus();
  }

  function скрытьФормуТаблицы() {
    var форма = document.getElementById("sheetform");
    if (форма) форма.hidden = true;
  }

  function собратьСтолбцыФормы() {
    var строки = document.querySelectorAll("#sheetcols .stcolrow");
    var столбцы = [];
    for (var i = 0; i < строки.length; i++) {
      var row = строки[i];
      var метка = row.querySelector(".stcollabel");
      var видПоле = row.querySelector(".stcolkind");
      var label = метка ? String(метка.value || "").trim() : "";
      if (!label) continue;
      столбцы.push({ key: row.dataset.colKey, label: label,
                    kind: видПоле ? видПоле.value : "text" });
    }
    return столбцы;
  }

  async function создатьТаблицу() {
    if (!state.caseId) return;
    var кнопка = document.getElementById("sheetcreate");
    var ошибка = document.getElementById("sheetformerr");
    var полеНазвания = document.getElementById("sheettitle");
    var полеРода = document.getElementById("sheetsens");
    var название = полеНазвания ? String(полеНазвания.value || "").trim() : "";
    if (ошибка) ошибка.textContent = "";
    if (!название) {
      if (ошибка) ошибка.textContent = T("Назовите таблицу.");
      if (полеНазвания) полеНазвания.focus();
      return;
    }
    var столбцы = собратьСтолбцыФормы();
    if (!столбцы.length) {
      if (ошибка) ошибка.textContent = T("Нужен хотя бы один столбец с названием.");
      return;
    }
    var дело = state.caseId;
    if (кнопка) { кнопка.disabled = true; кнопка.textContent = T("Создаю…"); }
    try {
      var вид = await api("POST", "/cases/" + encodeURIComponent(дело) + "/tables", {
        title: название,
        sensitivity: полеРода ? полеРода.value : "normal",
        columns: столбцы
      });
      if (state.caseId !== дело) return;
      /* ПРОБЕЛ СЛУЖБЫ: `POST /tables` отдаёт вид таблицы БЕЗ `can_edit`
         (в отличие от `GET /tables/{id}`, который его считает). Заводить
         таблицу может только участник с правом `comment` — служба это уже
         проверила (иначе был бы 403) — поэтому здесь можно назвать
         `can_edit: true` не спрашивая: тот, кто её завёл, её и правит. */
      вид.can_edit = true;
      скрытьФормуТаблицы();
      открытаяТаблица = вид;
      открытаяТаблицаId = вид.id;
      грязныеЯчейки = {};
      сохранениеЯчеекИдёт = null;   // старое сохранение сюда больше не отчитается
      ячейкаВФокусе = null;
      спорыТаблицы = [];
      построитьСеткуТаблицы(вид);
      показатьГрид();
      поставитьОпросТаблицы();
    } catch (e) {
      if (ошибка) ошибка.textContent = reason(e);
    } finally {
      if (кнопка) { кнопка.disabled = false; кнопка.textContent = T("Создать таблицу"); }
    }
  }

  // ── Открытие и закрытие таблицы ─────────────────────────────────────────

  function показатьГрид() {
    var список = document.getElementById("sheetlist");
    var скрытоСтрока = document.getElementById("sheethidden");
    var кнопкаНовая = document.getElementById("sheetnew");
    var форма = document.getElementById("sheetform");
    var грид = document.getElementById("sheetgrid");
    if (список) список.hidden = true;
    if (скрытоСтрока) скрытоСтрока.hidden = true;
    if (кнопкаНовая) кнопкаНовая.hidden = true;
    if (форма) форма.hidden = true;
    if (грид) грид.hidden = false;
  }

  async function открытьТаблицу(id) {
    if (!state.caseId) return;
    var дело = state.caseId;
    var вид;
    try {
      вид = await api("GET", "/cases/" + encodeURIComponent(дело) +
                      "/tables/" + encodeURIComponent(id));
    } catch (e) {
      сорвалось(T("Таблица не открылась: "), e);
      return;
    }
    if (state.caseId !== дело) return;
    открытаяТаблица = вид;
    открытаяТаблицаId = вид.id;
    грязныеЯчейки = {};
    сохранениеЯчеекИдёт = null;   // старое сохранение сюда больше не отчитается
    ячейкаВФокусе = null;
    спорыТаблицы = [];
    построитьСеткуТаблицы(вид);
    показатьГрид();
    поставитьОпросТаблицы();
  }

  function закрытьТаблицу() {
    остановитьОпросТаблицы();
    открытаяТаблица = null;
    открытаяТаблицаId = null;
    грязныеЯчейки = {};
    сохранениеЯчеекИдёт = null;   // старое сохранение сюда больше не отчитается
    ячейкаВФокусе = null;
    спорыТаблицы = [];
    if (таймерСохраненияЯчеек) { clearTimeout(таймерСохраненияЯчеек); таймерСохраненияЯчеек = null; }
    var грид = document.getElementById("sheetgrid");
    if (грид) грид.hidden = true;
    renderSheets();
  }

  /* Дело меняется — грид чужому делу не должен пережить переход. Вызывается
     из покинутьДело() (см. правку там), которая сама не ждёт ничего: дело
     уже уходит, а несохранённое здесь долить хоть НЕ ДОЖИДАЯСЬ ответа лучше,
     чем не пытаться вовсе. Настоящая гарантия «не потеряно» — у кнопки
     «К списку таблиц» ниже, которая явно ждёт и явно спрашивает. */
  function покинутьТаблицыДела() {
    if (Object.keys(грязныеЯчейки).length) сохранитьЯчейкиСейчас();
    остановитьОпросТаблицы();
    открытаяТаблица = null;
    открытаяТаблицаId = null;
    грязныеЯчейки = {};
    сохранениеЯчеекИдёт = null;   // старое сохранение сюда больше не отчитается
    ячейкаВФокусе = null;
    спорыТаблицы = [];
    if (таймерСохраненияЯчеек) { clearTimeout(таймерСохраненияЯчеек); таймерСохраненияЯчеек = null; }
    списокТаблиц = [];
    var box = document.getElementById("sheets");
    if (box) box.hidden = true;
    var грид = document.getElementById("sheetgrid");
    if (грид) грид.hidden = true;
    var форма = document.getElementById("sheetform");
    if (форма) форма.hidden = true;
  }

  // ── Построение сетки ─────────────────────────────────────────────────────

  function обновитьШапкуСетки(вид) {
    var шапка = document.getElementById("sheetgridhead");
    var добавить = document.getElementById("sheetaddrow");
    var толькоЧтение = !вид.can_edit || делоЗакрытоЛи();
    if (шапка) {
      var текст = вид.title || "";
      if (вид.rows_total > вид.rows_shown) {
        текст += " — " + T("показаны первые ") + вид.rows_shown +
                 T(" из ") + вид.rows_total;
      }
      if (толькоЧтение) текст += " · " + T("Только просмотр");
      шапка.textContent = текст;
    }
    if (добавить) добавить.hidden = толькоЧтение;
  }

  function обновитьИтогиТаблицы(вид) {
    var таблица = document.getElementById("sheettable");
    if (!таблица) return;
    var старый = таблица.querySelector("tfoot");
    if (старый) старый.remove();
    var ключи = Object.keys(вид.totals || {});
    if (!ключи.length) return;
    var tfoot = document.createElement("tfoot");
    var tr = document.createElement("tr");
    // Подпись — в первый столбец без суммы: у таблицы, начатой числом, первый
    // столбец занят итогом, и «Итого» раньше просто пропадало.
    var подписан = false;
    (вид.columns || []).forEach(function (col) {
      var td = document.createElement("td");
      if (col.kind === "number" && вид.totals[col.key] != null) {
        td.textContent = вид.totals[col.key];
      } else if (!подписан) {
        td.textContent = T("Итого");
        подписан = true;
      }
      tr.appendChild(td);
    });
    if (вид.can_edit) tr.appendChild(document.createElement("td"));
    tfoot.appendChild(tr);
    таблица.appendChild(tfoot);
  }

  function строкаТаблицыDOM(row, columns, canEdit) {
    var tr = document.createElement("tr");
    tr.dataset.rowId = row.id;
    columns.forEach(function (col) {
      var td = document.createElement("td");
      td.dataset.rowId = row.id;
      td.dataset.colKey = col.key;
      var c = (row.cells || {})[col.key];
      td.textContent = c ? (c.value || "") : "";
      td.dataset.version = String(c ? c.version : 0);
      if (canEdit) {
        td.contentEditable = "true";
        td.tabIndex = 0;
        подключитьЯчейку(td);
      }
      tr.appendChild(td);
    });
    if (canEdit) {
      var действие = document.createElement("td");
      var кнопка = el("button", "addone rowrm", "Убрать строку");
      кнопка.type = "button";
      кнопка.addEventListener("click", function () { убратьСтрокуТаблицы(row.id); });
      действие.appendChild(кнопка);
      tr.appendChild(действие);
    }
    return tr;
  }

  function построитьСеткуТаблицы(вид) {
    var таблица = document.getElementById("sheettable");
    if (!таблица) return;
    таблица.innerHTML = "";
    var thead = document.createElement("thead");
    var заголовок = document.createElement("tr");
    (вид.columns || []).forEach(function (col) {
      var th = document.createElement("th");
      th.textContent = col.label || col.key;
      заголовок.appendChild(th);
    });
    if (вид.can_edit) заголовок.appendChild(document.createElement("th"));
    thead.appendChild(заголовок);
    таблица.appendChild(thead);
    var tbody = document.createElement("tbody");
    tbody.id = "sheettbody";
    (вид.rows || []).forEach(function (row) {
      tbody.appendChild(строкаТаблицыDOM(row, вид.columns || [], вид.can_edit));
    });
    таблица.appendChild(tbody);
    обновитьИтогиТаблицы(вид);
    обновитьШапкуСетки(вид);
    показатьСпорыЯчеек([]);
  }

  function найтиЯчейку(rowId, colKey) {
    var tbody = document.getElementById("sheettbody");
    if (!tbody) return null;
    var tr = tbody.querySelector('tr[data-row-id="' + rowId + '"]');
    if (!tr) return null;
    return tr.querySelector('td[data-col-key="' + colKey + '"]');
  }

  /* СЛИЯНИЕ. Вызывается и по событию журнала (перечитатьОткрытуюТаблицу), и
     после своих же записей (добавить/убрать строку, создать таблицу) — везде,
     где на руки пришёл свежий вид таблицы. Правило одно: ячейку в фокусе или
     ещё не сохранённую (грязную) не трогаем никогда, остальные — только если
     версия ответа старше версии на экране. */
  function слитьТаблицу(вид) {
    if (!открытаяТаблицаId || !вид || вид.id !== открытаяТаблицаId) return;
    if (вид.can_edit === undefined) {
      // Пробел службы: `POST rows` тоже не считает `can_edit` (см. созданиеТаблицу).
      вид.can_edit = открытаяТаблица ? открытаяТаблица.can_edit : false;
    }
    открытаяТаблица = вид;
    var tbody = document.getElementById("sheettbody");
    if (!tbody) return;
    var виденные = {};
    (вид.rows || []).forEach(function (row) {
      виденные[row.id] = true;
      var tr = tbody.querySelector('tr[data-row-id="' + row.id + '"]');
      if (!tr) {
        tbody.appendChild(строкаТаблицыDOM(row, вид.columns || [], вид.can_edit));
        return;
      }
      (вид.columns || []).forEach(function (col) {
        var td = tr.querySelector('td[data-col-key="' + col.key + '"]');
        if (!td) return;
        var ключ = row.id + "|" + col.key;
        if (ячейкаВФокусе === ключ || грязныеЯчейки[ключ]) return;
        var c = (row.cells || {})[col.key];
        var версия = c ? c.version : 0;
        var локВерсия = parseInt(td.dataset.version || "0", 10);
        if (версия > локВерсия) {
          td.textContent = c ? (c.value || "") : "";
          td.dataset.version = String(версия);
        }
      });
    });
    // Строки, снятые в другом месте, убираем — если по ним нет ни правки,
    // ни фокуса: тронуть их сейчас значило бы стереть то, что человек пишет.
    Array.prototype.slice.call(tbody.children).forEach(function (tr) {
      var rid = tr.dataset.rowId;
      if (виденные[rid]) return;
      var занята = Array.prototype.some.call(tr.children, function (td) {
        var ключ = rid + "|" + (td.dataset.colKey || "");
        return ячейкаВФокусе === ключ || грязныеЯчейки[ключ];
      });
      if (!занята) tr.remove();
    });
    обновитьИтогиТаблицы(вид);
    обновитьШапкуСетки(вид);
  }

  // ── Правка ячейки: клавиатура, фокус, автосохранение ────────────────────

  function фокусНаЯчейку(td) {
    td.focus();
    // Курсор — в конец текста: без этого Chrome ставит его в начало ячейки.
    try {
      var диапазон = document.createRange();
      диапазон.selectNodeContents(td);
      диапазон.collapse(false);
      var выделение = window.getSelection();
      выделение.removeAllRanges();
      выделение.addRange(диапазон);
    } catch (e) { /* старый браузер — фокуса достаточно */ }
  }

  function всеЯчейкиГрида() {
    var tbody = document.getElementById("sheettbody");
    return tbody
      ? Array.prototype.slice.call(tbody.querySelectorAll('td[contenteditable="true"]'))
      : [];
  }

  function перейтиКЯчейке(td, куда) {
    if (куда === "down") {
      var tr = td.parentNode;
      var следующая = tr && tr.nextElementSibling;
      if (!следующая) return;
      var цель = следующая.querySelector(
        'td[data-col-key="' + td.dataset.colKey + '"][contenteditable="true"]');
      if (цель) фокусНаЯчейку(цель);
      return;
    }
    var все = всеЯчейкиГрида();
    var i = все.indexOf(td);
    if (i < 0) return;
    var цель2 = все[куда === "prev" ? i - 1 : i + 1];
    if (цель2) фокусНаЯчейку(цель2);
  }

  function отменитьПравкуЯчейки(td) {
    var ключ = td.dataset.rowId + "|" + td.dataset.colKey;
    td.textContent = td.dataset.original || "";
    delete грязныеЯчейки[ключ];
    td.blur();
  }

  function подключитьЯчейку(td) {
    td.addEventListener("focus", function () {
      ячейкаВФокусе = td.dataset.rowId + "|" + td.dataset.colKey;
      td.dataset.original = td.textContent;
      td.dataset.expectVersion = td.dataset.version || "0";
    });
    td.addEventListener("input", function () {
      var ключ = td.dataset.rowId + "|" + td.dataset.colKey;
      грязныеЯчейки[ключ] = {
        rowId: td.dataset.rowId, colKey: td.dataset.colKey,
        value: td.textContent,
        expectVersion: parseInt(td.dataset.expectVersion || td.dataset.version || "0", 10)
      };
      статусСохранения(T("Сохраняю…"));
      запланироватьСохранениеЯчеек();
    });
    td.addEventListener("keydown", function (e) {
      if (e.key === "Enter") {
        e.preventDefault();
        перейтиКЯчейке(td, "down");
      } else if (e.key === "Escape") {
        e.preventDefault();
        отменитьПравкуЯчейки(td);
      } else if (e.key === "Tab") {
        e.preventDefault();
        перейтиКЯчейке(td, e.shiftKey ? "prev" : "next");
      }
    });
    td.addEventListener("blur", function () {
      ячейкаВФокусе = null;
      сохранитьЯчейкиСейчас();
    });
  }

  function статусСохранения(текст, плохо) {
    var поле = document.getElementById("sheetstatus");
    if (!поле) return;
    поле.textContent = текст || "";
    поле.classList.toggle("bad", !!плохо);
  }

  function запланироватьСохранениеЯчеек() {
    if (таймерСохраненияЯчеек) clearTimeout(таймерСохраненияЯчеек);
    // 700 мс тишины после последнего нажатия — не раньше: иначе каждая буква
    // уходит своим запросом, а служба режет частоту (см. PUBLIC_API_ENDPOINTS).
    таймерСохраненияЯчеек = setTimeout(function () { сохранитьЯчейкиСейчас(); }, 700);
  }

  function применитьСохранённуюЯчейку(rowId, colKey, value, version) {
    var td = найтиЯчейку(rowId, colKey);
    if (!td) return;
    td.dataset.version = String(version);
    var ключ = rowId + "|" + colKey;
    if (ячейкаВФокусе === ключ) {
      // Текст не трогаем — человек мог печатать дальше; но версию, с которой
      // сверится следующее сохранение, подвинуть надо, иначе она упрётся в
      // спор с собственной же только что принятой правкой.
      td.dataset.expectVersion = String(version);
      return;
    }
    if (грязныеЯчейки[ключ]) return;    // осталась несохранённая копия — не трогаем
    td.textContent = value || "";
  }

  /* Сохранение. Один вызов — один PUT максимум на ЯЧЕЕК_ЗА_РАЗ ячеек; если
     грязных больше, остаток дозапустит себя сам из finally. Совпадающие
     вызовы (клавиша и blur почти разом, или кнопка «назад») получают ОДИН И
     ТОТ ЖЕ Promise — а не второй параллельный запрос той же ячейки. */
  function сохранитьЯчейкиСейчас() {
    if (таймерСохраненияЯчеек) { clearTimeout(таймерСохраненияЯчеек); таймерСохраненияЯчеек = null; }
    if (сохранениеЯчеекИдёт) return сохранениеЯчеекИдёт;
    if (!открытаяТаблица || !Object.keys(грязныеЯчейки).length) {
      return Promise.resolve();
    }
    сохранениеЯчеекИдёт = сохранитьЯчейкиРаз().finally(function () {
      сохранениеЯчеекИдёт = null;
      if (Object.keys(грязныеЯчейки).length) запланироватьСохранениеЯчеек();
    });
    return сохранениеЯчеекИдёт;
  }

  async function сохранитьЯчейкиРаз() {
    var все = Object.keys(грязныеЯчейки);
    if (!все.length || !открытаяТаблица) return;
    var партияКлючи = все.slice(0, ЯЧЕЕК_ЗА_РАЗ);
    var снимки = снимкиПоКлючам(партияКлючи);
    var тело = партияКлючи.map(function (к) {
      var я = снимки[к];
      return { row_id: я.rowId, col_key: я.colKey, value: я.value,
               expect_version: я.expectVersion };
    });
    статусСохранения(T("Сохраняю…"));
    var дело = state.caseId, таблица = открытаяТаблица.id;
    try {
      var ответ = await api("PUT", "/cases/" + encodeURIComponent(дело) +
                            "/tables/" + encodeURIComponent(таблица) + "/cells",
                            { cells: тело });
      if (state.caseId !== дело || !открытаяТаблица || открытаяТаблица.id !== таблица) return;
      партияКлючи.forEach(function (к) {
        // Удаляем только то, что не переписали заново, пока запрос летел:
        // новый ввод в ТУ ЖЕ ячейку создал бы другой объект в грязныеЯчейки,
        // и сравнение по ссылке отличит его от только что отправленного.
        if (грязныеЯчейки[к] === снимки[к]) delete грязныеЯчейки[к];
      });
      var числа = {};
      (открытаяТаблица.columns || []).forEach(function (col) {
        if (col.kind === "number") числа[col.key] = true;
      });
      var итогСдвинулся = false;
      (ответ.saved || []).forEach(function (s) {
        применитьСохранённуюЯчейку(s.row_id, s.col_key, s.value, s.version);
        if (числа[s.col_key]) итогСдвинулся = true;
      });
      // Итог считает служба. Своя сохранённая сумма без перечитывания
      // оставляла «Итого» прежним до следующего тика опроса — до десяти секунд
      // человек видел сумму, которая с таблицей не сходится.
      if (итогСдвинулся) перечитатьОткрытуюТаблицу();
      показатьСпорыЯчеек(ответ.conflicts || []);
      if (!(ответ.conflicts && ответ.conflicts.length) && !Object.keys(грязныеЯчейки).length) {
        статусСохранения(T("Сохранено"));
      } else if (!(ответ.conflicts && ответ.conflicts.length)) {
        статусСохранения(T("Сохраняю…"));
      } else {
        статусСохранения("");
      }
    } catch (e) {
      // Грязные НЕ удаляем: следующая попытка (таймер, blur или явный уход)
      // отправит их снова — отказ здесь не должен тихо стереть правку.
      статусСохранения(T("Не сохранено: ") + reason(e), true);
    }
  }

  function снимкиПоКлючам(ключи) {
    var снимки = {};
    ключи.forEach(function (к) { снимки[к] = грязныеЯчейки[к]; });
    return снимки;
  }

  // ── Споры сохранения ─────────────────────────────────────────────────────

  function показатьСпорыЯчеек(споры) {
    спорыТаблицы = споры || [];
    Array.prototype.forEach.call(
      document.querySelectorAll("#sheettable td.tdconflict"),
      function (td) { td.classList.remove("tdconflict"); });
    var короб = document.getElementById("sheetconflicts");
    if (!короб) return;
    короб.innerHTML = "";
    if (!спорыТаблицы.length) { короб.hidden = true; return; }
    короб.hidden = false;
    спорыТаблицы.forEach(function (с) {
      var td = найтиЯчейку(с.row_id, с.col_key);
      if (td) td.classList.add("tdconflict");
      var строка = el("div", "stconflict1");
      строка.appendChild(document.createTextNode(
        (с.updated_by_kind === "agent"
          ? T("Агент успел сохранить: ")
          : T("Другой участник успел сохранить: ")) + (с.value || "—") +
        T(". Ваше: ") + (с.yours || "—") + "."));
      var оставить = el("button", "addone", "Оставить сохранённое");
      оставить.type = "button";
      оставить.addEventListener("click", function () { принятьЧужуюПравку(с); });
      var своё = el("button", "addone", "Записать моё");
      своё.type = "button";
      своё.addEventListener("click", function () { записатьСвоюПравку(с); });
      строка.appendChild(оставить);
      строка.appendChild(своё);
      короб.appendChild(строка);
    });
  }

  function убратьСпор(с) {
    показатьСпорыЯчеек(спорыТаблицы.filter(function (x) {
      return !(x.row_id === с.row_id && x.col_key === с.col_key);
    }));
  }

  function принятьЧужуюПравку(с) {
    var ключ = с.row_id + "|" + с.col_key;
    delete грязныеЯчейки[ключ];
    var td = найтиЯчейку(с.row_id, с.col_key);
    if (td) {
      td.classList.remove("tdconflict");
      td.textContent = с.value || "";
      td.dataset.version = String(с.version);
      td.dataset.expectVersion = String(с.version);
    }
    убратьСпор(с);
  }

  function записатьСвоюПравку(с) {
    var ключ = с.row_id + "|" + с.col_key;
    грязныеЯчейки[ключ] = { rowId: с.row_id, colKey: с.col_key,
                            value: с.yours, expectVersion: с.version };
    var td = найтиЯчейку(с.row_id, с.col_key);
    if (td) td.dataset.expectVersion = String(с.version);
    убратьСпор(с);
    статусСохранения(T("Сохраняю…"));
    сохранитьЯчейкиСейчас();
  }

  // ── Строки: добавить, убрать, скачать ────────────────────────────────────

  async function добавитьСтрокуТаблицы() {
    if (!открытаяТаблица || !state.caseId) return;
    var дело = state.caseId, таблица = открытаяТаблица.id;
    var кнопка = document.getElementById("sheetaddrow");
    if (кнопка) кнопка.disabled = true;
    try {
      var ответ = await api("POST", "/cases/" + encodeURIComponent(дело) +
                            "/tables/" + encodeURIComponent(таблица) + "/rows",
                            { rows: [{}] });
      if (state.caseId !== дело || !открытаяТаблица || открытаяТаблица.id !== таблица) return;
      слитьТаблицу(ответ);
      var новыйId = (ответ.added_row_ids || [])[0];
      var столбцы = открытаяТаблица.columns || [];
      if (новыйId && столбцы.length) {
        var td = найтиЯчейку(новыйId, столбцы[0].key);
        if (td) фокусНаЯчейку(td);
      }
    } catch (e) {
      статусСохранения(T("Строка не добавилась: ") + reason(e), true);
    } finally {
      if (кнопка) кнопка.disabled = false;
    }
  }

  async function убратьСтрокуТаблицы(rowId) {
    if (!открытаяТаблица || !state.caseId) return;
    if (!window.confirm(T("Убрать эту строку из таблицы?"))) return;
    var дело = state.caseId, таблица = открытаяТаблица.id;
    try {
      var ответ = await api("POST", "/cases/" + encodeURIComponent(дело) +
                            "/tables/" + encodeURIComponent(таблица) +
                            "/rows/" + encodeURIComponent(rowId) + "/remove", {});
      if (state.caseId !== дело || !открытаяТаблица || открытаяТаблица.id !== таблица) return;
      if (ответ && ответ.removed) {
        var tr = document.querySelector('#sheettbody tr[data-row-id="' + rowId + '"]');
        if (tr) tr.remove();
        Object.keys(грязныеЯчейки).forEach(function (к) {
          if (грязныеЯчейки[к].rowId === rowId) delete грязныеЯчейки[к];
        });
      }
    } catch (e) {
      статусСохранения(T("Строка не снялась: ") + reason(e), true);
    }
  }

  function скачатьТаблицу() {
    if (!открытаяТаблица || !state.caseId) return;
    скачатьЧерезДверь(
      "/cases/" + encodeURIComponent(state.caseId) + "/tables/" +
      encodeURIComponent(открытаяТаблица.id) + "/file",
      (открытаяТаблица.title || "таблица") + ".csv");
  }

  // ── Живое обновление: события журнала и частый опрос открытой таблицы ───

  /* Вызывается из дописатьЖурнал для ЛЮБОГО события с приставкой `table.`
     (создание, добавление/снятие строки, правка ячеек) — значений в
     событии нет никогда, только номера, поэтому реакция всегда одна:
     перечитать саму ручку и слить по версии. */
  function событиеТаблиц(e) {
    var p = e.payload || {};
    var tableId = p.table_id;
    if (!tableId) return;
    if (открытаяТаблицаId === tableId) {
      перечитатьОткрытуюТаблицу();
    } else if (!открытаяТаблицаId) {
      renderSheets();
    }
    // Иначе — событие про ДРУГУЮ таблицу дела, а грид сейчас открыт не на
    // ней: показывать здесь нечего.
  }

  async function перечитатьОткрытуюТаблицу() {
    if (!открытаяТаблицаId || !state.caseId) return;
    var дело = state.caseId, таблица = открытаяТаблицаId;
    try {
      var вид = await api("GET", "/cases/" + encodeURIComponent(дело) +
                          "/tables/" + encodeURIComponent(таблица));
      if (state.caseId !== дело || открытаяТаблицаId !== таблица) return;
      слитьТаблицу(вид);
    } catch (e) {
      // Разовый отказ молчит: следующее событие или частый опрос повторят.
    }
  }

  var ОПРОС_ТАБЛИЦЫ_МС = 10000;

  function опросТаблицыТик() {
    опросТаблицыТаймер = null;
    if (!открытаяТаблицаId || document.hidden || !state.caseId) {
      поставитьОпросТаблицы();
      return;
    }
    if (опросТаблицыДо === null) {
      опросТаблицыДо = (typeof лентаДо === "number") ? лентаДо : 0;
    }
    var дело = state.caseId, таблица = открытаяТаблицаId, с = опросТаблицыДо;
    Promise.resolve()
      .then(function () {
        return api("GET", "/cases/" + encodeURIComponent(дело) +
                   "/events?since_seq=" + (с + 1) + "&kind=table.cells_updated");
      })
      .then(function (evs) {
        if (state.caseId !== дело || открытаяТаблицаId !== таблица) return;
        var край = с, есть = false;
        (evs || []).forEach(function (e) {
          if (typeof e.seq === "number" && e.seq > край) край = e.seq;
          if ((e.payload || {}).table_id === таблица) есть = true;
        });
        опросТаблицыДо = край;
        if (есть) return перечитатьОткрытуюТаблицу();
      })
      .catch(function () { /* разовый отказ молчит — следующий тик повторит */ })
      .then(поставитьОпросТаблицы);
  }

  function поставитьОпросТаблицы() {
    if (опросТаблицыТаймер) clearTimeout(опросТаблицыТаймер);
    опросТаблицыТаймер = setTimeout(опросТаблицыТик, ОПРОС_ТАБЛИЦЫ_МС);
  }

  function остановитьОпросТаблицы() {
    if (опросТаблицыТаймер) { clearTimeout(опросТаблицыТаймер); опросТаблицыТаймер = null; }
    опросТаблицыДо = null;
  }

  // ── Кнопки короба, подключаются один раз при пуске ───────────────────────

  function setupSheets() {
    var новая = document.getElementById("sheetnew");
    if (новая) новая.addEventListener("click", показатьФормуТаблицы);
    var отмена = document.getElementById("sheetcancel");
    if (отмена) отмена.addEventListener("click", скрытьФормуТаблицы);
    var добСтолбец = document.getElementById("sheetaddcol");
    if (добСтолбец) добСтолбец.addEventListener("click", function () {
      добавитьСтолбецФормы(новыйКлючСтолбца(), "", "text");
    });
    var пресет = document.getElementById("sheetpreset");
    if (пресет) пресет.addEventListener("click", применитьПресетБюджета);
    var создать = document.getElementById("sheetcreate");
    if (создать) создать.addEventListener("click", создатьТаблицу);
    var добРяд = document.getElementById("sheetaddrow");
    if (добРяд) добРяд.addEventListener("click", добавитьСтрокуТаблицы);
    var скачать = document.getElementById("sheetdownload");
    if (скачать) скачать.addEventListener("click", скачатьТаблицу);
    var назад = document.getElementById("sheetback");
    if (назад) назад.addEventListener("click", async function () {
      await сохранитьЯчейкиСейчас();
      if (Object.keys(грязныеЯчейки).length) {
        var статус = document.getElementById("sheetstatus");
        var почему = (статус && статус.textContent) || T("связь не отвечает");
        if (!window.confirm(T("Не всё сохранено: ") + почему +
            T(". Уйти и потерять несохранённое?"))) {
          return;
        }
      }
      закрытьТаблицу();
    });
  }

  /* Что человек читает по исходу поручения.

     Ключи — значения CaseRunStatus из shared/schemas/case_runs.py. Каждый
     исход назван вслух: молчаливого «прочее» здесь быть не должно, потому что
     именно молчание и выдавало чужой исход за успех.

     ЗАЧЕМ ЭТО ВООБЩЕ. Ключ повтора у поручения — дело плюс минута, и служба по
     нему честно возвращает ТОТ ЖЕ прогон (services/case_service/runs.py,
     `return await _run(conn, existing)`). К этой секунде он мог уже кончиться,
     упасть или быть отменённым — а HTTP всё равно 201. Оболочка смотрела
     только на код и печатала «Поручил» над упавшей работой, помечая дело
     идущим; человек ждал того, что давно кончилось.

     Поле «вид» — то же служебное слово, что возвращает описатьПрогон, и уезжает
     оно в state.runKind: по нему renderRun решает, перечитывать ли находки.
     Переводить эти значения нельзя — их сравнивают (ловушка №1 в lang.js). */
  var ИСХОД_ПОРУЧЕНИЯ = {
    queued:           { вид: "идёт", свежий: true },
    running:          { вид: "идёт",
      слова: "Такая работа по делу уже идёт — второго прогона не завелось." },
    waiting_approval: { вид: "ждёт",
      слова: "Эта работа уже дошла до вашего слова: агент что-то приготовил, и оно " +
             "ждёт в разделе «Ждёт вашего слова»." },
    succeeded:        { вид: "кончилось",
      слова: "Эта работа уже выполнена — второго прогона не завелось. Что получилось, " +
             "показано ниже, в деле." },
    failed:           { вид: "не смог",
      слова: "Эту работу уже пробовали, и агент не смог. Дело цело — ничего не записано." },
    cancelled:        { вид: "не смог",
      слова: "Эту работу отменили. Дело цело — ничего не записано." },
  };

  function исходПоручения(прогон) {
    var исход = (прогон && прогон.status) || "";
    var з = ИСХОД_ПОРУЧЕНИЯ[исход];
    /* Исход, которого эта версия оболочки не знает, НЕ объявляем успехом и НЕ
       метим дело идущим. Служба старше или новее нас — но врать про работу от
       этого нельзя, а пустой вид renderRun переспросит у службы сам. */
    if (!з) {
      return { вид: null, свежий: false,
        слова: T("Служба ответила состоянием прогона, которого я не знаю") +
               " (" + (исход || "пусто") + "). " +
               T("Что с работой — смотрите в полосе состояния: я не берусь угадывать.") };
    }
    // Свежезаведённый прогон — единственный случай, когда фразу говорит сам
    // вызывающий: «поручил» и «принял проект» — разные вести о разной работе.
    if (з.свежий) return { вид: з.вид, свежий: true, слова: "" };
    return { вид: з.вид, свежий: false, слова: T(з.слова) + хвостОшибкиПрогона(прогон) };
  }

  //: Причину провала берём у службы дословно. Своими словами её не
  //: пересказываем: это была бы вторая правда о причине, и однажды они разойдутся.
  function хвостОшибкиПрогона(прогон) {
    var почему = (прогон && прогон.last_error) || "";
    return почему ? " " + T("Агент объясняет: ") + почему : "";
  }

  async function startDraft() {
    if (runBusy || !state.caseId) return;
    var шаги = state.caseDraftSteps || [];
    if (!шаги.length) return;
    var поле = document.getElementById("draftask");
    var просьба = поле ? String(поле.value || "").trim() : "";
    if (!просьба) {
      say("bot", "Ф", "Скажите, какая бумага нужна — претензия, ходатайство, " +
          "заявление. И к чему она: без этого проект собирать не из чего.");
      if (поле) поле.focus();
      return;
    }
    runBusy = true;
    var кнопка = document.getElementById("startdraft");
    if (кнопка) { кнопка.disabled = true; кнопка.textContent = "Составляю…"; }
    try {
      /* Ключ повтора — СЛУЧАЙНЫЙ, а не по минуте (как у поручения).
         Просьб о разных бумагах бывает две подряд, и «претензия», а следом
         «ходатайство» в ту же минуту слились бы в одну: вторая вернула бы
         первый прогон, и человек получил бы не то, что просил. */
      var прогон = await api("POST", "/cases/" + encodeURIComponent(state.caseId) + "/runs", {
        idempotency_key: state.caseId + ":draft:" + случайныйКлюч(),
        kind: "case.execute",
        steps: [шаги[0].step],
        input: { query: просьба },
      });
      /* Состояние прогона знает ТЕЛО ответа, а не то, что HTTP не отказал.
         Ключ здесь случайный, и вернуть чужой прогон служба не может — но
         строить весть о работе из кода ответа значит верить, что так будет
         всегда. Разбор стоит ДО фразы: после неё он ничего уже не решает. */
      var исход = исходПоручения(прогон);
      if (исход.свежий) {
        say("bot", "Ф", "Принял. Проект придёт вам на подтверждение — до вашего " +
            "слова он в дело не ляжет.");
      } else {
        say("bot", "Ф", исход.слова);
        // Вернулся не наш свежий прогон, а прежний, и он мог кончиться, пока
        // человек не смотрел. Сказать «что получилось, показано ниже» и не
        // перечитать — соврать второй раз, уже собственной правкой.
        Promise.all([renderFinds(), renderPapers()]).then(renderArtifacts);
      }
      state.runKind = исход.вид;
      if (поле) поле.value = "";
      renderPending();
      renderRun();
    } catch (e) {
      // Отказы здесь разные, и путать их нельзя: один чинится подтверждением
      // входа, другой ожиданием, третий — ничем.
      if (e.status === 403) {
        say("bot", "Ф", "Составление доступно после подтверждения личности. " +
                        "Нажмите своё имя вверху и привяжите Telegram или номер.");
      } else if (e.status === 409) {
        say("bot", "Ф", "По этому делу уже идёт работа — дождитесь её.");
      } else {
        // Третий — ничем не чинится и не про человека: идёт заметкой.
        //
        // Приставка и хвост переводятся ПООТДЕЛЬНОСТИ. Прежде вся склейка
        // вместе с причиной уходила в `say`, а тот прогонял её через словарь
        // целиком — совпасть такое не могло никогда, и место было
        // непереводимым молча.
        сорвалось(T("Составить не вышло: "), e,
                  T(". Дело цело, ничего не начато."));
      }
    } finally {
      runBusy = false;
      if (кнопка) { кнопка.disabled = false; кнопка.textContent = "Составить"; }
    }
  }

  function случайныйКлюч() {
    try {
      if (window.crypto && crypto.randomUUID) return crypto.randomUUID();
    } catch (e) { /* старый браузер — падаем на запасное */ }
    return String(Date.now()) + "-" + Math.random().toString(36).slice(2, 10);
  }

  async function startRun() {
    if (runBusy || !state.caseId) return;
    var поле = document.getElementById("runquery");
    var запрос = поле ? String(поле.value || "").trim() : "";
    if (!запрос) {
      // Пустой запрос воркер отвергает («шаг-опрос не получил запроса»), и
      // человек увидел бы отказ вместо простого «скажите, что искать».
      say("bot", "Ф", "Скажите, что искать — одним-двумя словами, названием " +
          "услуги. Место и повод витрина не понимает.");
      if (поле) поле.focus();
      return;
    }
    runBusy = true;
    var кнопка = document.getElementById("startrun");
    if (кнопка) { кнопка.disabled = true; кнопка.textContent = T("Поручаю…"); }
    try {
      // Ключ повтора привязан к делу и минуте: два нажатия подряд — одно
      // поручение, а не два прогона по одному делу.
      var прогон = await api("POST", "/cases/" + encodeURIComponent(state.caseId) + "/runs", {
        idempotency_key: state.caseId + ":" + Math.floor(Date.now() / 60000),
        kind: "case.execute",
        // Строка ЧЕЛОВЕКА, а не заголовок дела: см. довод у короткийЗапрос.
        input: { query: запрос, region: "" },
      });
      /* И ФРАЗА, И ПОМЕТКА — ИЗ ОТВЕТА СЛУЖБЫ, а не из того, что HTTP не отказал.
         Ключ повтора — дело плюс минута: два нажатия в одну минуту возвращают
         ТОТ ЖЕ прогон, и он к этой секунде мог уже кончиться или упасть.
         Разбор обязан стоять ДО фразы об успехе — после неё он ничего не решает. */
      var исход = исходПоручения(прогон);
      if (исход.свежий) {
        say("bot", "Ф", "Поручил. Агент работает по объявленному плану; всё, что " +
            "потребует вашего слова, появится в разделе «Ждёт вашего слова».");
      } else {
        say("bot", "Ф", исход.слова);
        // Вернулся прежний прогон, и он мог кончиться, пока человек не смотрел.
        // Сказать «что получилось, показано ниже» и не перечитать найденное —
        // соврать второй раз, уже собственной правкой.
        Promise.all([renderFinds(), renderPapers()]).then(renderArtifacts);
      }
      // Свежий прогон ещё «идёт» — отмечаем сразу, иначе первое перечитывание
      // не увидит перехода и находки не обновятся. Прежний помечаем тем, чем
      // он на деле стал.
      state.runKind = исход.вид;
      renderPending();
      renderRun();
    } catch (e) {
      // 409 — НЕ ПОЛОМКА. По делу правда идёт работа, и это ответ человеку на
      // его действие: голос помощника здесь верный. Всё прочее — срыв, и
      // приписывать его помощнику нельзя. Тройная развилка вместо тернарника
      // ровно потому, что ветви уходят теперь в РАЗНЫЕ каналы.
      if (e.status === 409) {
        say("bot", "Ф", "По этому делу уже идёт работа — дождитесь её или " +
                        "посмотрите, что ждёт подтверждения.");
      } else {
        сорвалось(T("Поручить не вышло: "), e,
                  T(". Дело цело, ничего не начато."));
      }
    } finally {
      runBusy = false;
      if (кнопка) { кнопка.disabled = false; кнопка.textContent = T("Поручить агенту"); }
    }
  }

  /* Чем занят агент.

     До этого прогон человеку не был виден ВОВСЕ: он нажимал «Поручить» и
     ждал, пока где-нибудь появится патч. Идёт работа, упала она или встала —
     отличить было нельзя. 19.08.2026 за этим состоянием сутки прятался
     неработающий case-worker: шаг числился идущим, потому что спросить было
     некому.

     ТРИ СОСТОЯНИЯ, И ТРЕТЬЕ — ГЛАВНОЕ. «Идёт» и «не смог» человек поймёт и
     так. А «встал» — это когда шаг числится идущим, но аренда его давно
     истекла и никто не подобрал: воркер умер. Снаружи это выглядит как
     работа и может выглядеть так вечно.

     Запас в пять минут не случаен: аренда истекает и в норме — между
     попытками, — и подхватывается следующим обходом. Молчание дольше
     нескольких обходов означает, что подхватывать некому. */
  var ЗАПАС_МОЛЧАНИЯ_МС = 5 * 60 * 1000;

  function описатьПрогон(run) {
    var шаги = run.steps || [];

    /* ИСХОД СПРАШИВАЕМ У ПРОГОНА, А НЕ ВЫВОДИМ ИЗ ШАГОВ.

       Прежде функция искала шаг в running, failed или waiting_approval — и
       только. У УДАЧНО кончившегося прогона все шаги в succeeded и skipped,
       значит не находилось ничего и возвращалась пустота. А пустоту renderRun
       понимает как «прогон есть, описать нечем» — то есть как ОЧЕРЕДЬ: он
       десять раз по три секунды перечитывал и печатал «Поручение принято, но
       за работу никто не взялся».

       То есть про КАЖДЫЙ удавшийся прогон оболочка говорила человеку, что за
       работу никто не взялся, и звала сменить направление — сломать то, что
       только что сработало. Хуже: перечитывание находок стоит НИЖЕ выхода из
       пустой ветки, поэтому найденное не появлялось вовсе. Человек поручал,
       ждал, получал «никто не взялся» и пустое «Найденное» — при том что
       работа была сделана и карточки лежали в деле.

       run.status — поле обязательное (shared/schemas/case_runs.py:316) и
       терминальное состояние в нём достоверно, потому что шаги к этому
       времени уже разошлись по succeeded и skipped. */
    var исход = run.status || "";
    if (исход === "succeeded") {
      var когда = when(run.finished_at);
      return {
        вид: "кончилось",
        текст: T("Агент закончил") + (когда ? " — " + когда : "") +
               T(". Что нашлось, лежит ниже, в «Найденном»."),
      };
    }
    if (исход === "cancelled") {
      return {
        вид: "не смог",
        текст: "Работу отменили. Дело цело — ничего не записано.",
      };
    }

    var идущий = шаги.filter(function (s) { return s.status === "running"; })[0];
    var упавший = шаги.filter(function (s) { return s.status === "failed"; })[0];
    var ждущий = шаги.filter(function (s) { return s.status === "waiting_approval"; })[0];

    if (ждущий) {
      return { вид: "ждёт", текст: "Агент подготовил и ждёт вашего слова — ниже." };
    }
    if (идущий) {
      var до = идущий.lease_until ? Date.parse(идущий.lease_until) : 0;
      if (до && Date.now() - до > ЗАПАС_МОЛЧАНИЯ_МС) {
        return {
          вид: "встал",
          текст: T("Агент молчит с ") + when(идущий.lease_until) + T(". Похоже, работа "
               + "прервалась — это не ваша ошибка.")
               + (идущий.error ? T(" Последняя причина: ") + идущий.error : ""),
        };
      }
      return {
        вид: "идёт",
        текст: T("Агент работает: шаг «") + (идущий.step || "?") + "»"
             + (идущий.attempt > 1 ? T(", попытка ") + идущий.attempt : "") + "."
             + (идущий.error ? T(" Прошлая попытка не удалась: ") + идущий.error : ""),
      };
    }
    if (упавший || исход === "failed") {
      // Прогон бывает провален и БЕЗ упавшего шага — если он не дожил до
      // первого шага. Тогда причину знает только сам прогон.
      var почему = (упавший && упавший.error) || run.last_error || "причина не названа";
      return {
        вид: "не смог",
        текст: T("Агент не смог: ") + почему + T(". Дело цело — ничего не записано."),
      };
    }
    return null;
  }

  /* Над чем идёт дело.

     Служба умела связывать дело с объектом с самого начала, наружу это не
     выпускалось ни разу: дела и объекты жили в одной базе и не встречались
     на экране. Кабинет собран вокруг объекта, и без этой связи он остаётся
     списком карточек.

     Показываем только когда объект указан ИЛИ когда указать есть что: строка
     «предмет не указан» под каждым делом была бы упрёком, а не сведением. */
  async function renderSubject() {
    var box = document.getElementById("subject");
    if (!box) return;
    // Прячем по той же причине, что и полосу прогона: «Дело о: …» от дела,
    // которого больше нет, — это не пустяк, а неверное имя на экране.
    if (!state.caseId) { box.hidden = true; return; }
    var предметы = [];
    try {
      предметы = await api("GET", "/cases/" + encodeURIComponent(state.caseId) + "/subjects");
    } catch (e) {
      box.hidden = true;
      return;
    }
    box.innerHTML = "";
    if (предметы.length) {
      box.hidden = false;
      box.appendChild(el("span", null, "Дело о: "));
      box.appendChild(el("span", "subj",
        предметы.map(function (п) { return п.title || п.entity_id; }).join(", ")));
      return;
    }

    // Объекта нет — предлагаем указать, но только если он у человека есть.
    var свои = [];
    try {
      свои = await api("GET", "/principals/" + encodeURIComponent(state.principal) + "/entities");
    } catch (e) { свои = []; }
    if (!свои.length) { box.hidden = true; return; }

    box.hidden = false;
    box.appendChild(el("span", null, "Дело ни к какому объекту не привязано."));
    var кнопка = el("button", "addone", "Указать объект");
    кнопка.type = "button";
    кнопка.addEventListener("click", async function () {
      var список = свои.map(function (о, i) {
        return (i + 1) + ". " + (о.title || о.id);
      }).join("\n");
      var выбор = window.prompt(T("Над каким объектом это дело?\n\n") + список
                                + T("\n\nНомер:"));
      var n = parseInt(выбор, 10);
      if (!n || n < 1 || n > свои.length) return;
      кнопка.disabled = true;
      try {
        await api("POST", "/cases/" + encodeURIComponent(state.caseId) + "/subjects",
                  { entity_id: свои[n - 1].id });
        await renderSubject();
      } catch (e) {
        box.appendChild(el("div", "casenote", T("Не вышло указать: ") + reason(e)));
      } finally {
        кнопка.disabled = false;
      }
    });
    box.appendChild(кнопка);
  }

  /* Сколько раз спрашивать про прогон, который ещё не взяли.

     Десять по три секунды — полминуты. Воркер берёт шаг раз в секунду, так
     что тридцать секунд молчания означают не занятость, а что брать некому. */
  var ПОПЫТОК_ОЧЕРЕДИ = 10;

  /* ЭТАПЫ ПРОГОНА ЛЕСТНИЦЕЙ.

     Прогон идёт долго: медиана по проду — 267 секунд, и лишь 3 из 19 уложились
     в минуту. Всё это время человек видел ОДНУ строку про текущий шаг: «Агент
     работает: шаг „search"». Строка правдива и бесполезна — по ней не понять,
     сколько уже сделано и сколько осталось, а четыре минуты неизвестности
     читаются как зависание.

     Показываем весь план: пройденное галочкой, текущее — точкой, впереди —
     тускло. Каждая строка проверяема, потому что берётся ИЗ ЗАПИСИ ПРОГОНА,
     а не со слов модели: статусы шагов ставит исполнитель.

     Ничего лишнего не спрашиваем: шаги приходят тем же ответом
     GET /cases/{id}/runs?limit=1, который уже читает renderRun. */
  var ЭТАП_ЗНАК = {
    succeeded: "✓", failed: "✗", running: "◆",
    waiting_approval: "!", skipped: "–", pending: "·",
  };
  var ЭТАП_СЛОВО = {
    failed: "не прошёл", running: "идёт",
    waiting_approval: "ждёт вас", skipped: "пропущен",
  };
  var ЭТАП_ИМЯ = { search: "поиск", route: "маршрут", shortlist: "отбор",
                   draft: "проект документа" };

  function нарисоватьЭтапы(box, run) {
    var шаги = (run && run.steps) || [];
    // Один шаг — лестницы нет: строка выше уже всё сказала, а «✓ поиск»
    // под «Агент работает: шаг поиск» — это то же самое дважды.
    if (шаги.length < 2) return;
    var лестница = el("div", "rssteps");
    шаги.forEach(function (ш) {
      var статус = ш.status || "pending";
      var строка = el("div", "rsstep " + статус);
      строка.appendChild(el("span", "rsmark", ЭТАП_ЗНАК[статус] || "·"));
      var имя = ЭТАП_ИМЯ[ш.step] ? T(ЭТАП_ИМЯ[ш.step]) : (ш.step || "?");
      var хвост = ЭТАП_СЛОВО[статус] ? " — " + T(ЭТАП_СЛОВО[статус]) : "";
      // Повторная попытка — правда о работе, и молчать о ней незачем:
      // человек видит, что шаг идёт дольше прочих, и вправе знать почему.
      if (статус === "running" && ш.attempt > 1) {
        хвост += T(", попытка ") + ш.attempt;
      }
      строка.appendChild(el("span", "rsname", имя + хвост));
      лестница.appendChild(строка);
    });
    box.appendChild(лестница);
  }

  async function renderRun() {
    var box = document.getElementById("runstate");
    if (!box) return;
    // ПРЯЧЕМ, А НЕ ПРОСТО ВЫХОДИМ. Прежде при пустом деле функция уходила,
    // оставив полосу на экране: после выхода в общий разговор и после
    // удаления дела человек видел состояние прогона того, чего уже нет.
    if (!state.caseId) { box.hidden = true; return; }
    var список;
    try {
      список = await api("GET", "/cases/" + encodeURIComponent(state.caseId) + "/runs?limit=1");
    } catch (e) {
      // Молчим: не показать состояние хуже, чем показать ложное, но пугать
      // человека отказом чтения тоже незачем — он ничего не поручал.
      box.hidden = true;
      return;
    }
    var run = (список || [])[0];
    var что = run ? описатьПрогон(run) : null;
    if (!что) {
      /* ПРОГОН ЕСТЬ, А ОПИСАТЬ ЕГО ПОКА НЕЧЕМ — и прежде здесь стоял просто
         выход, ДО постановки таймера.

         Сразу после «Поручить агенту» прогон лежит в очереди: шаг ещё
         pending, воркер берёт его раз в секунду, и описатьПрогон возвращает
         пустоту. Опрос при этом не заводился ВОВСЕ — ни полосы состояния, ни
         находок, и второе нажатие подряд выглядело как «ничего не
         происходит». Ровно на это и наткнулись при разборе живого пути.

         Теперь: описать нечем — полосу прячем, но если прогон в списке ЕСТЬ,
         продолжаем спрашивать. */
      box.hidden = true;
      /* ОПРОС ОЧЕРЕДИ ОГРАНИЧЕН, и это не осторожность.

         Первая редакция спрашивала, пока прогон не опишется, — то есть
         ВЕЧНО, если его никто не возьмёт. А это не выдуманный случай: прогон,
         заведённый в направлении без исполнимого плана, повисает в очереди
         навсегда, и каждая следующая попытка отвечает «по этому делу уже идёт
         работа». Вечный опрос грел бы службу и молчал бы о беде.

         Поймал это сторожевой тест соседа
         (test_оболочка_различает_идёт_и_встал_по_истёкшей_аренде): он требует,
         чтобы перечитывание прекращалось, когда прекращать пора. Требование
         верное, и моя правка его нарушала. */
      if (run && !state.runWatch) {
        state.очередьЖдём = (state.очередьЖдём || 0) + 1;
        if (state.очередьЖдём <= ПОПЫТОК_ОЧЕРЕДИ) {
          state.runWatch = setTimeout(function () {
            state.runWatch = null;
            renderRun();
          }, 3000);
        } else {
          // Молчать нельзя: человек нажал «Поручить», а работа не началась.
          state.очередьЖдём = 0;
          box.hidden = false;
          box.className = "runstate встал";
          box.textContent = T("Поручение принято, но за работу никто не взялся. "
            + "Так бывает, когда у направления нет исполнимого плана. "
            + "Попробуйте сменить направление или напишите мне.");
        }
      }
      return;
    }
    // Описали — значит взяли: счёт ожидания в очереди начинается заново.
    state.очередьЖдём = 0;
    box.hidden = false;
    box.className = "runstate " + что.вид.replace(/ /g, "-");
    box.innerHTML = "";
    box.appendChild(el("div", "rsline", T(что.текст)));
    нарисоватьЭтапы(box, run);
    /* ПРОГОН КОНЧИЛСЯ — ПЕРЕЧИТАТЬ НАЙДЕННОЕ.

       Прежде находки перечитывались только при открытии дела и после входа.
       Прогон, доложивший карточки посреди разговора, не менял на экране
       НИЧЕГО: полоса состояния просто исчезала, а раздел «Найденное»
       оставался пустым до перезагрузки. Человек поручал, дожидался — и
       видел ровно то же, что до поручения. */
    var прежний = state.runKind;
    state.runKind = что.вид;
    if (прежний === "идёт" && что.вид !== "идёт") {
      Promise.all([renderFinds(), renderPapers()]).then(renderArtifacts);
      renderPending();
    }
    /* Пока идёт — перечитываем. Встало или кончилось — перестаём.

       ШЕСТЬ СЕКУНД, А НЕ ДВАДЦАТЬ. При двадцати за средний прогон (267 с)
       выпадало тринадцать обновлений на весь план, и переход между этапами
       человек заставал через раз — лестница дёргалась рывками по три ступени.
       Смысл лестницы в том, чтобы этап загорался на глазах; на этом пути у
       двери предела частоты нет, а один запрос в шесть секунд для службы,
       держащей 1200 запросов в секунду, — ничто.

       В спрятанной вкладке НЕ ходим вовсе: там смотреть некому, а прогон
       живёт своей жизнью на сервере и от нашего молчания не пострадает.
       Вернулись на вкладку — перечитываем сразу, не дожидаясь срока. */
    if (что.вид === "идёт" && !state.runWatch) {
      if (document.hidden) {
        state.runWakeup = state.runWakeup || function () {
          if (document.hidden) return;
          document.removeEventListener("visibilitychange", state.runWakeup);
          state.runWakeup = null;
          renderRun();
        };
        document.addEventListener("visibilitychange", state.runWakeup);
        return;
      }
      state.runWatch = setTimeout(function () {
        state.runWatch = null;
        renderRun();
      }, 6000);
    }
  }

  async function renderPending() {
    var box = document.getElementById("pending");
    var list = document.getElementById("pendinglist");
    if (!box || !list) return;
    if (!state.caseId) { box.hidden = true; return; }
    var data;
    try {
      data = await api("GET", "/cases/" + encodeURIComponent(state.caseId) +
                       "/patches?status=pending_approval");
    } catch (e) {
      // «Не спросили» и «нечего подтверждать» выглядеть одинаково не должны:
      // во втором случае человек спокойно закроет страницу, а в первом
      // письмо будет ждать его молча.
      box.hidden = false;
      list.innerHTML = "";
      list.appendChild(el("div", "fnote",
        T("Что ждёт подтверждения — не прочиталось: ") + reason(e) +
        T(". Если агент что-то приготовил, оно не потерялось и ждёт в деле.")));
      return;
    }
    // Тела предложений служба отдаёт только тому, кто по ним решает (очередь
    // собрана из материалов дела и родом не гатится). Участнику без права
    // решать показывать нечего: карточка без тела — это не «подтвердите», а
    // «в деле что-то происходит, а что — не ваше дело». Такая строка тревожит
    // и ничего не даёт, поэтому короб просто не открываем.
    if (data.bodies_visible === false) { box.hidden = true; return; }
    var items = (data.patches || []).filter(function (p) {
      return p.status === "pending_approval";
    });
    list.innerHTML = "";
    if (!items.length) { box.hidden = true; return; }
    box.hidden = false;
    items.forEach(function (p) { list.appendChild(pendingCard(p)); });
  }

  /* Что человек читает по исходу решения о правке.

     Ключи — значения PatchOutcome из shared/schemas/cases.py. Каждый исход
     назван вслух: молчаливого «прочее» здесь быть не должно, потому что
     именно молчание и выдало отказ за успех. Поле «лёг» отвечает на
     единственный вопрос, от которого зависит экран: появилось ли в деле
     что-нибудь. Оно же решает, перерисовывать ли разделы. */
  var ИСХОД_ПРАВКИ = {
    applied:              { лёг: true },
    already_applied:      { лёг: true,
      слова: "Это уже было записано в дело раньше — второй записи не появилось." },
    denied_precondition:  { лёг: false,
      слова: "Не записал: дело успело измениться, и правка к нему больше не подходит. " +
             "В деле ничего не тронуто — попросите агента предложить заново." },
    denied_policy:        { лёг: false,
      слова: "Не записал: площадка отвергла содержимое правки." },
    denied_expired:       { лёг: false,
      слова: "Не записал: мандат агента истёк или отозван. Дело цело — поручите работу заново." },
    denied_limit:         { лёг: false,
      слова: "Не записал: у агента исчерпан лимит записей по этому мандату." },
    denied_no_permit:     { лёг: false,
      слова: "Не записал: мандата на это дело у агента нет." },
    denied_op_not_allowed: { лёг: false,
      слова: "Не записал: такая операция агенту не разрешена." },
    rejected_by_user:     { лёг: false,
      слова: "Отклонено — ничего не отправлено и в дело не записано." },
    pending_approval:     { лёг: false,
      слова: "Решение не принято: правка всё ещё ждёт подтверждения." },
  };

  function исходПравки(исход, action, d) {
    var з = ИСХОД_ПРАВКИ[исход];
    // Исход, которого эта версия оболочки не знает, НЕ объявляем успехом.
    // Служба старше или новее нас — но врать про дело от этого нельзя.
    if (!з) {
      return { лёг: false, слова: T("Служба ответила исходом, которого я не знаю") +
               " (" + (исход || "пусто") + "). " +
               T("В дело посмотрите сами — я не берусь угадывать, что в нём произошло.") };
    }
    if (исход === "applied") {
      return { лёг: true, слова: action === "approve"
        ? T("Подтверждено. ") + d.what.toLowerCase() + "."
        : T("Отклонено — ничего не отправлено и в дело не записано.") };
    }
    return { лёг: з.лёг, слова: T(з.слова) };
  }

  //: Причина отказа берётся из ответа службы дословно. Своими словами её не
  //: пересказываем: это была бы вторая правда о причине, и однажды они разойдутся.
  function хвостПричины(ответ) {
    var почему = (ответ && ответ.detail) || "";
    return почему ? " " + T("Служба объясняет: ") + почему : "";
  }

  function pendingCard(p) {
    var d = describePatch(p);
    var card = el("div", "pend1");
    card.appendChild(el("div", "pwhat", d.what));
    if (d.who) card.appendChild(el("div", "pwho", T("Кому: ") + d.who));
    /* ДОКУМЕНТ ЧИТАЮТ НА ХОЛСТЕ, А НЕ В БОКОВОЙ ПОЛОСЕ.

       Прежде текст проекта вываливался сюда целиком — с доводом «подтвердить
       проект без текста значит подписаться вслепую». Довод верен, место было
       неверным: в полосе шириной в треть экрана четыре тысячи знаков не
       читают, а прокручивают. То есть вслепую подписывались всё равно, только
       теперь это выглядело как чтение.

       Холст для документа и построен: там ширина, там же открываются
       принесённые бумаги и готовые проекты. Здесь остаются ПРОПУСКИ — то,
       чего в проекте не хватает, — потому что они короткие и важнее текста.

       И кнопка подтверждения ждёт, пока документ откроют. Это не придирка:
       единственный довод за показ целиком был про слепую подпись, и отвечать
       на него надо тем, что человек документ ВИДЕЛ, а не тем, что текст
       где-то на экране был. */
    var черновик = d.наХолст;
    if (черновик) {
      (d.пропуски || []).forEach(function (строка) {
        card.appendChild(el("div", "ptext", строка));
      });
    } else {
      card.appendChild(el("div", "ptext", d.text || "(пусто)"));
    }
    if (p.reason) card.appendChild(el("div", "pwhy", T("Агент объясняет: ") + p.reason));

    var acts = el("div", "pacts");
    var читать = null;
    if (черновик) {
      читать = el("button", "addone", T("Читать проект на холсте"));
      читать.type = "button";
      acts.appendChild(читать);
    }
    var yes = el("button", "pyes", "Подтвердить");
    var no = el("button", "pno", "Отклонить");
    acts.appendChild(yes);
    acts.appendChild(no);
    card.appendChild(acts);
    var видел = !черновик;
    if (черновик) {
      yes.disabled = true;
      yes.title = T("Сначала откройте проект — подтверждают прочитанное");
      var подсказка = el("div", "fnote",
        T("Подтверждение откроется, когда вы откроете проект: подтверждают "
          + "прочитанное."));
      card.appendChild(подсказка);
      читать.addEventListener("click", function () {
        openCanvas({
          id: p.id,
          title: черновик.title,
          вид: черновик.вид,
          откуда: T("проект агента, ещё не в деле"),
          text: d.text || "",
          // ПРАВИТЬ НЕЛЬЗЯ, и это не забывчивость: подтверждение кладёт в
          // дело то, что записано в предложении, а не то, что человек
          // поправил на экране. Дать правку значило бы обещать, что она
          // сохранится, — и потерять её молча.
          правится: false,
          подпись: T("Решение — в карточке «Ждёт вашего слова»: подтвердить "
                     + "или отклонить. Правка проекта возможна после того, "
                     + "как он ляжет в дело."),
        });
        видел = true;
        yes.disabled = false;
        yes.title = "";
        подсказка.remove();
      });
    }

    function decide(action, btn) {
      // Двойное нажатие не должно превращаться в два решения: подтверждение
      // необратимо, и «я нажал дважды» не значит «я согласен дважды».
      if (pendingBusy[p.id]) return;
      // Замок на двери не отменяет замка на калитке: кнопка и так погашена,
      // но подтверждение необратимо, и полагаться на одно disabled нельзя.
      if (action === "approve" && !видел) return;
      pendingBusy[p.id] = true;
      yes.disabled = true;
      no.disabled = true;
      btn.textContent = T(action === "approve" ? "Подтверждаю…" : "Отклоняю…");
      api("POST", "/patches/" + encodeURIComponent(p.id) + "/" + action, {})
        .then(function (ответ) {
          /* ИСХОД ЛЕЖИТ В ТЕЛЕ, А НЕ В КОДЕ ОТВЕТА.

             Ручка отвечает 200 и кладёт решение внутрь: {outcome, detail}.
             Прежде здесь стояло `.then(function () {` — без аргумента, — и
             оболочка печатала «Подтверждено» на ЛЮБОМ двухсотом.

             28.08.2026 человек утвердил проект договора аренды, увидел
             «Подтверждено. Добавить проект документа.» и пошёл искать его в
             артефактах. Договора там не было: служба ответила
             denied_precondition, приложив готовую человеческую причину, а
             оболочка эту причину выбросила. Три правки, ждавшие людей в тот
             день, были обречены тем же способом.

             Причину берём ИЗ ОТВЕТА и своими словами не переписываем: это
             была бы вторая правда о причине. */
          var исход = (ответ && ответ.outcome) || "";
          var разбор = исходПравки(исход, action, d);
          say("bot", "Ф", разбор.слова +
              (разбор.лёг ? "" : хвостПричины(ответ)));
          delete pendingBusy[p.id];
          renderPending();
          if (!разбор.лёг) return;   // в дело ничего не легло — нечего и перерисовывать
          /* Подтверждённый патч ЧТО-ТО в дело кладёт, и это что-то обязано
             появиться на экране сразу.

             Прежде перерисовывался только сам список ожидающих: панель
             ложилась в базу, а в «Документах» её не было до перезагрузки
             страницы. 19.08.2026 человек подтвердил новую форму, увидел
             прежнее «Документов — 1» и открыл старую — ту самую, у которой
             не работала кнопка. То есть несвежий экран не просто неудобен:
             он подсовывает вчерашнее вместо сегодняшнего.

             Перерисовываем ВСЁ, куда патч может попасть, а не угадываем по
             операции: список операций растёт, и угадывание отстанет молча.
             Каждая из этих функций дешёвая и умеет ничего не делать, если
             её разделу нечего показывать. */
          if (action === "approve") {
            try { renderDocs(); } catch (e) { /* раздела может не быть */ }
            try { renderFiles(); } catch (e) { /* и этого тоже */ }
            try { renderOps(); } catch (e) { /* и этого */ }
          }
        })
        .catch(function (e) {
          // Кнопки возвращаем: неудача — не решение, и человек должен иметь
          // возможность повторить.
          delete pendingBusy[p.id];
          yes.disabled = false;
          no.disabled = false;
          btn.textContent = T(action === "approve" ? "Подтвердить" : "Отклонить");
          var чужое = e.status === 403;
          card.appendChild(el("div", "fnote", чужое
            ? "Решать в этом деле может только тот, кому дано право decide."
            : T("Не получилось: ") + reason(e) + T(". Решение не принято.")));
        });
    }

    yes.onclick = function () { decide("approve", yes); };
    no.onclick = function () { decide("reject", no); };
    return card;
  }

  /* Воля человека про вынос: выпускать ли содержимое дела за периметр.

     Показывается только у выбранного дела и только тому, у кого есть право
     решения — остальным кнопка молча не рисуется, а не отказывает после
     нажатия. Состояние читаем из самого дела: догадка оболочки здесь была бы
     хуже отсутствия настройки, потому что выглядела бы как знание. */
  /* ── Где лежат бумаги человека ──────────────────────────────────────

     Настройка была построена целиком — три схемы, запись выбора с датой,
     маршрут открыт в двери — и оболочка её не показывала ни разу. На проде
     все 196 субъектов сидели на умолчании не потому, что выбрали площадку, а
     потому, что выбора им не показали.

     ПОСЛЕДСТВИЯ РЯДОМ С ВЫБОРОМ, а не в справке: решение о том, у кого
     физически лежат бумаги, принимают один раз и мельком. Настройка,
     последствий которой не видно в момент выбора, — это согласие, полученное
     невнимательно. */

  var местаХранения = null;

  async function renderVaultPlace() {
    var короб = document.getElementById("vaultplace");
    if (!короб || !state.principal) { if (короб) короб.hidden = true; return; }
    if (!местаХранения) {
      try {
        местаХранения = await api("GET", "/storage/places");
      } catch (e) {
        // Тихо: раздел про хранение важен, но пустая рамка с отказом на
        // главном экране пугает сильнее, чем помогает. Появится при следующем
        // заходе, а бумаги от этого никуда не денутся.
        короб.hidden = true;
        return;
      }
    }
    // ДВА РАЗНЫХ ВОПРОСА — две ручки. Какую схему человек выбрал, знает
    // /storage/place; сколько у нас лежит его бумаг — список документов.
    // Список схему не отдаёт, и попытка вычитать её оттуда молча дала бы
    // «у площадки» всякому, включая тех, кто выбрал другое.
    var выбор = null, опись = null;
    try {
      выбор = await api("GET", "/storage/place/" +
                        encodeURIComponent(state.principal));
    } catch (e) { короб.hidden = true; return; }
    try {
      опись = await api("GET", "/vault/" + encodeURIComponent(state.principal) +
                        "/documents?limit=1");
    } catch (e) { /* число документов не критично для показа выбора */ }

    короб.hidden = false;
    var где = (выбор && выбор.place) || "platform";
    var спрошен = !!(выбор && выбор.chosen);
    var сколько = (опись && опись.total) || 0;
    var подпись = document.getElementById("vpnow");
    var строки = document.getElementById("vprows");
    var тревога = document.getElementById("vpwarn");
    var стереть = document.getElementById("vperase");
    строки.innerHTML = "";

    (местаХранения.places || []).forEach(function (м) {
      var это_оно = м.place === где;
      var доступно = м.available !== false;
      var стр = el("div", "vp1" + (это_оно ? " on" : "") + (доступно ? "" : " off"));
      стр.appendChild(el("span", "vpn",
        (это_оно ? "● " : "○ ") + (м.title || м.place) +
        (доступно ? "" : T(" — пока не подключено"))));
      стр.appendChild(el("span", "vpw", м.what || ""));
      // Кто прочитает и что будет при уходе — это и есть последствия, ради
      // которых выбор делают. Прятать их за «подробнее» значит прятать суть.
      стр.appendChild(el("span", "vpr",
        T("читают: ") + (м.who_can_read || "—") +
        T(" · уйдёте: ") + (м.if_you_leave || "—")));
      if (доступно && !это_оно) {
        стр.addEventListener("click", function () { выбратьМесто(м); });
      }
      строки.appendChild(стр);
    });

    var нынешнее = ((местаХранения.places || []).filter(
      function (м) { return м.place === где; })[0] || {}).title || где;
    // «Выбрал у площадки» и «не спрашивали» — разное, и разница существенная:
    // во втором случае бумаги лежат у нас по умолчанию, а не по решению
    // человека. Служба это различает; скрыть различие здесь значило бы
    // выдать наше умолчание за его волю.
    подпись.textContent = T(спрошен
      ? (T("Сейчас: ") + нынешнее)
      : (T("Сейчас: ") + нынешнее + T(" — по умолчанию. Вы этот выбор не делали.")));

    // «Только на устройстве» при уже лежащих у нас файлах — состояние, в
    // котором обещание схемы неправда. Говорим об этом на экране, а не только
    // в ответе службы.
    var надо_стереть = где === "device" && сколько > 0;
    тревога.hidden = !надо_стереть;
    if (надо_стереть) {
      тревога.textContent = T(T("Новые бумаги мы больше не принимаем — но ") +
        сколько + T(" загруженных ранее по-прежнему лежат у нас. Смена схемы " +
        "файлов не стирает."));
    }
    стереть.hidden = !(сколько > 0);
    стереть.onclick = стеретьВсё;
  }

  async function выбратьМесто(м) {
    if (м.place === "device") {
      // Спрашиваем ДО, а не после: это единственная схема, при которой мы
      // перестаём принимать файлы, и узнать об этом из отказа при загрузке
      // было бы поздно.
      var ок = window.confirm(
        T("«Только на устройстве» значит, что мы перестанем принимать ваши " +
        "файлы: приложить бумагу к делу будет нельзя, агент её не увидит.\n\n" +
        "Уже загруженное при этом не стирается само — для этого есть " +
        "отдельная кнопка.\n\nВыбрать эту схему?"));
      if (!ок) return;
    }
    try {
      await api("POST", "/vault/place", { place: м.place });
    } catch (e) {
      сорвалось(T("Схему хранения сменить не вышло: "), e);
      return;
    }
    await renderVaultPlace();
    await renderFiles();
  }

  async function стеретьВсё() {
    var кнопка = document.getElementById("vperase");
    // Слово, а не нажатие: список человек видел, а отменить стирание нечем.
    var слово = window.prompt(
      T("Это уберёт ВСЁ ваше содержимое из нашего хранилища — файлы и копии, " +
      "без возможности вернуть.\n\nМатериалы дел останутся названием и " +
      "разобранным текстом; байтов за ними больше не будет.\n\n" +
      "Напишите «удалить», чтобы подтвердить:"));
    if (!сходится(слово, "удалить")) return;
    if (кнопка) кнопка.disabled = true;
    try {
      var r = await api("POST", "/vault/erase", { confirm: "удалить" });
      var хвост = (r.files_left || []).length
        ? T(" Не убрались файлы: ") + r.files_left.length + T(" — скажите, разберусь.")
        : "";
      say("bot", "Ф", T("Убрано документов: ") + (r.erased || 0) + "." + хвост +
                      " " + (r.note || ""));
    } catch (e) {
      сорвалось(T("Стереть не вышло: "), e);
    } finally {
      if (кнопка) кнопка.disabled = false;
      await renderVaultPlace();
      await renderFiles();
    }
  }

  /* ── Насколько стараться в этом деле ──────────────────────────────

     Модель до сих пор выбирал АВТОР ПАКА — одну на всех, кто пак поставил, —
     а у человека выбора не было вовсе. Автор при этом не знает ни цены
     ошибки в чужом деле, ни кошелька того, кто пак поставил.

     ЧТО ЗДЕСЬ ГОВОРИТСЯ ПРЯМО, И ПОЧЕМУ. Ступень, которая не сработает,
     человек обязан узнать ДО того, как понадеялся на неё: служба возвращает
     оговорку («выключен вынос», «нечем платить»), и она печатается тут же.
     Молчание читалось бы как «всё в порядке», и он считал бы, что читает
     ответ предельного уровня. */

  var СТУПЕНИ = null;

  async function renderEffort() {
    var box = document.getElementById("effort");
    var rows = document.getElementById("effortrows");
    var note = document.getElementById("effortnote");
    if (!box) return;
    if (!state.caseId) { box.hidden = true; return; }

    if (!СТУПЕНИ) {
      try {
        СТУПЕНИ = (await api("GET", "/effort/levels")).levels || [];
      } catch (e) {
        // Не рисуем выбор, которого не понимаем: пункт меню, за которым
        // отказ, отпугивает сильнее, чем отсутствие пункта.
        box.hidden = true;
        return;
      }
    }
    var дело;
    try {
      дело = await api("GET", "/cases/" + state.caseId);
    } catch (e) { box.hidden = true; return; }

    var сейчас = дело.effort || "basic";
    box.hidden = false;
    rows.innerHTML = "";
    note.textContent = "";

    СТУПЕНИ.forEach(function (с) {
      var row = el("div", "way");
      var имя = el("span", "wn", с["название"]);
      row.appendChild(имя);
      if (с["код"] === сейчас) {
        row.appendChild(el("span", "wnote", T("выбран")));
      } else {
        var b = el("button", "addone", T("Выбрать"));
        b.type = "button";
        b.addEventListener("click", function () { выбратьСтупень(с["код"], b); });
        row.appendChild(b);
      }
      rows.appendChild(row);
      // Чем ступень отличается — под ней, а не в подсказке: пункт меню без
      // объяснения это предложение заплатить неизвестно за что.
      rows.appendChild(el("div", "sub", с["чем"]));
    });
  }

  async function выбратьСтупень(код, кнопка) {
    var note = document.getElementById("effortnote");
    кнопка.disabled = true;
    try {
      var r = await api("PUT", "/cases/" + state.caseId + "/effort",
                        { effort: код });
      await renderEffort();
      // ОГОВОРКА ПЕЧАТАЕТСЯ ПОСЛЕ ПЕРЕРИСОВКИ, иначе её тут же стёрло бы.
      if (r && r.note) {
        document.getElementById("effortnote").textContent = r.note;
      }
    } catch (e) {
      note.textContent = T("Не вышло изменить: ") + reason(e);
    } finally { кнопка.disabled = false; }
  }

  /* ДВЕ ВОЛИ ЧЕЛОВЕКА ПРО СОДЕРЖИМОЕ ДЕЛА, и спрашиваются они В НАЧАЛЕ.

     Оси РАЗНЫЕ, и путать их нельзя. Вынос отвечает «покидает ли содержимое
     наш периметр вообще». Юрисдикция — «чей закон над тем местом, куда оно
     попало». Две облачные модели с одинаковым «покидает» могут стоять в
     Москве и в Сингапуре, и для человека это не одно и то же.

     ПОЧЕМУ ГАЛОЧКИ, А НЕ КНОПКА. Кнопка «Запретить вынос» показывает ДЕЙСТВИЕ
     и умалчивает СОСТОЯНИЕ: человек читает её как «вынос запрещён» ровно
     наоборот. Галочка показывает состояние, а действие — следствие.

     ПОЧЕМУ В НАЧАЛЕ РАЗГОВОРА. После первого хода содержимое уже ушло туда,
     куда его пускали умолчания. Спрашивать после — предлагать запереть дверь
     за вышедшим. */
  async function renderEgress() {
    var box = document.getElementById("egress");
    var note = document.getElementById("egressnote");
    var выносБокс = document.getElementById("egressbox");
    var юрБокс = document.getElementById("jurbox");
    if (!state.caseId) { box.hidden = true; return; }
    var дело;
    try {
      дело = await api("GET", "/cases/" + state.caseId);
    } catch (e) { box.hidden = true; return; }

    var можно = дело.egress_allowed !== false;
    // Пусто читаем как «куда угодно»: так стоит умолчание в базе, и врать о
    // более строгом состоянии, чем есть, нельзя.
    var предел = дело.max_jurisdiction || "foreign";
    // ДЕЙСТВУЕТ СТРОЖАЙШЕЕ ИЗ ДВУХ — предела дела и согласия ХОЗЯИНА дела. С
    // 13.09.2026 молчание — запрет: у неспрошенного хозяина шлюз режет
    // иностранные модели, что бы ни стояло в деле. Потолок считает служба
    // дел (`jurisdiction_ceiling`) — по хозяину, а не по тому, кто смотрит:
    // поднятие предела она сверяет именно с хозяином.
    var потолок = дело.jurisdiction_ceiling || "";
    var заграницаЗакрыта = !!потолок && потолок !== "foreign";
    var смотритХозяин = дело.owner_id === state.principal;
    box.hidden = false;
    выносБокс.checked = можно;
    юрБокс.checked = предел === "foreign" && !заграницаЗакрыта;
    // Вторая галочка бессмысленна при запрещённом выносе: не выпускаем вовсе —
    // значит и вопрос «куда» не стоит. И при закрытом потолке: поднять предел
    // дела выше согласия хозяина служба не даст (409). Гасим, а не прячем:
    // исчезнувший переключатель читается как «такой настройки нет».
    юрБокс.disabled = !можно || заграницаЗакрыта;

    note.textContent = T(!можно
      ? "Содержимое не покидает наш периметр. Собеседника на удалённой модели " +
        "делу не подберут — а сегодня на ней работают все направления, так " +
        "что разговор будет не с кем вести, пока вы не разрешите."
      : заграницаЗакрыта
        ? (смотритХозяин
          ? "Содержимое уходит только к российским моделям: передачу данных за " +
            "рубеж вы не разрешали. Изменить это можно переключателем вверху " +
            "главного экрана."
          : "Содержимое уходит только к российским моделям: хозяин дела не " +
            "разрешал передачу данных за рубеж.")
        : предел === "foreign"
          ? "Содержимое может уйти к иностранным моделям. Так отвечает " +
            "большинство направлений сегодня."
          : "Содержимое уходит только к российским моделям. Направления, у " +
            "которых российской модели нет, отвечать этому делу не смогут.");

    выносБокс.onchange = async function () {
      выносБокс.disabled = true;
      try {
        await api("PUT", "/cases/" + state.caseId + "/egress",
                  { allowed: выносБокс.checked });
        await renderEgress();
      } catch (e) {
        сорвалось(T("Не вышло изменить: "), e);
        await renderEgress();
      } finally { выносБокс.disabled = false; }
    };
    юрБокс.onchange = async function () {
      юрБокс.disabled = true;
      try {
        await api("PUT", "/cases/" + state.caseId + "/jurisdiction",
                  { max_jurisdiction: юрБокс.checked ? "foreign" : "ru" });
        await renderEgress();
      } catch (e) {
        сорвалось(T("Не вышло изменить: "), e);
        // Перерисовка обязательна и в отказе: иначе галочка осталась бы
        // стоять там, куда её щёлкнули, и врала бы о состоянии дела.
        await renderEgress();
      } finally { юрБокс.disabled = false; }
    };
  }

  /* Показать принесённый файл — рядом с разговором, а не в новой вкладке.

     Хранилище отдаёт содержимое base64-строкой в JSON, а не байтами
     (vault_service, /vault/{owner}/documents/{id}/content), поэтому ссылкой
     его не открыть: файл собирается здесь и живёт как blob до закрытия
     холста.

     ПОЧЕМУ НЕ НОВАЯ ВКЛАДКА. Проверено на живом 18.08: и window.open, и клик
     по якорю с target=_blank перехватываются — во встроенных браузерах и
     мобильных обёртках наглухо, в обычном Chrome по настроению, потому что
     право открыть вкладку живёт до первого ожидания, а мы ждём службу.
     Человек жмёт, всё «срабатывает», и ничего не появляется — ровно та
     жалоба, с которой начали. Холст не зависит ни от чего этого.

     Что нельзя показать — отдаём скачиванием: его блокировщики не трогают.
     Молчание в ответ на нажатие — худший из исходов. */

  /* Что браузер покажет сам. Остальное честнее отдать файлом, чем открывать
     пустой кадр: .docx в iframe — это белый лист, а не документ.

     SVG В ЭТОТ СПИСОК НЕ ВХОДИТ, И ЭТО НЕ НЕДОСМОТР. Кадр с blob: наследует
     наш origin — проверено: contentDocument из него доступен. А SVG браузер
     разбирает как документ, и <script> внутри выполняется. Присланная в дело
     картинка прочитала бы localStorage, где лежит токен входа: опробовано на
     живом, скрипт из SVG вернул 4 ключа.

     Песочница это лечит, но вместе с тем гасит просмотрщик PDF — проверено
     обе меры, и с sandbox="" и с "allow-scripts" кадр пустой, тогда как без
     песочницы тот же файл открывается. Поэтому лечим не кадр, а список:
     SVG уходит на скачивание, где ничего не исполняется.

     Остальные типы безопасны по разным причинам: JS внутри PDF Chrome крутит
     в своём отдельном просмотрщике, а не в нашем origin; png/jpeg/gif/webp
     раскодируются как пиксели и разбору не подлежат; text/plain показывается
     текстом, а не разбирается как разметка. */
  var ВИДИМЫЕ = /^(application\/pdf|image\/(png|jpeg|gif|webp)|text\/plain)$/;

  var документОткрывается = false;

  async function openDoc(d, row) {
    // Второе нажатие по той же строке тянуло бы файл заново.
    if (документОткрывается) return;
    документОткрывается = true;
    row.classList.add("busy");
    var url = null;
    try {
      var r = await api("GET", "/vault/" + encodeURIComponent(state.principal) +
                        "/documents/" + encodeURIComponent(d.id) + "/content");
      var b64 = (r || {}).content_b64;
      if (!b64) throw new Error("служба не вернула содержимое");
      var bin = atob(b64);
      var buf = new Uint8Array(bin.length);
      for (var i = 0; i < bin.length; i++) buf[i] = bin.charCodeAt(i);
      var mime = d.mime || "application/octet-stream";
      url = URL.createObjectURL(new Blob([buf], { type: mime }));

      if (ВИДИМЫЕ.test(mime)) {
        closeCanvas();              // отпустить прежний файл, если был
        openCanvas({
          вид: "file",
          id: d.id,
          title: d.title || "Файл",
          откуда: "принесено в дело",
          blobUrl: url,
          правится: false,
          подпись: "Это исходный файл, как его принесли. Правки он не " +
                   "принимает: агент работает с извлечённым текстом, а " +
                   "бумага остаётся какой была."
        });
        url = null;                 // теперь за отзыв отвечает холст
      } else {
        var a = el("a");
        a.href = url;
        a.download = d.title || "файл";
        document.body.appendChild(a);
        a.click();
        a.remove();
        // Скачивание уже началось; ссылка нужна лишь на время передачи.
        setTimeout(function (u) { return function () { URL.revokeObjectURL(u); }; }(url), 60000);
        url = null;
      }
    } catch (e) {
      if (нуженВход(e)) {
        say("bot", "Ф", T("Файл «") + (d.title || T("без имени")) + T("» не отдам, " +
            "пока вход не подтверждён. Это не про права на сам файл — он ваш; " +
            "это про то, что за учётной записью пока никто не стоит: " +
            "восстановить её будет нечем, и отвечать за выданное некому.\n\n" +
            "Подтвердить — нажмите своё имя вверху. Telegram бесплатно, " +
            "СМС платно."));
        позватьПодтвердиться(null);
      } else {
        сорвалось(T("Не вышло открыть «") + (d.title || T("файл")) +
            "»: ", e);
      }
    } finally {
      if (url) URL.revokeObjectURL(url);
      документОткрывается = false;
      row.classList.remove("busy");
    }
  }

  async function renderFiles() {
    var box = document.getElementById("files");
    var list = document.getElementById("filelist");
    if (!state.caseId || !state.principal) { box.hidden = true; return; }
    var data;
    try {
      data = await api("GET", "/vault/" + state.principal + "/documents?case_id=" +
                       encodeURIComponent(state.caseId));
    } catch (e) {
      // «Не пришло» и «ничего нет» — разные вещи, и выглядеть одинаково они
      // не должны: во втором случае человек пойдёт грузить файл заново.
      box.hidden = false;
      list.innerHTML = "";
      list.appendChild(el("div", "fnote",
        T("Что приложено — не прочиталось: ") + reason(e)));
      return;
    }
    var docs = data.documents || [];
    list.innerHTML = "";
    // Заголовок над пустотой ничего не сообщает и занимает место: раздел
    // появляется вместе с первым файлом.
    if (!docs.length) { box.hidden = true; return; }
    box.hidden = false;

    /* Состояние разбора берём из МАТЕРИАЛОВ дела, а не из хранилища.
       Хранилище знает про байты, дело — про то, прочитан ли текст, и это
       разные вопросы. Прежде здесь стояла надпись «содержимое агент пока не
       читает» — одна на все файлы и навсегда; она врала уже тогда, когда
       текст был извлечён, и продолжала бы врать после починки разбора. */
    var состояния = {};
    if (state.caseId) {
      try {
        var mats = await api("GET", "/cases/" +
                             encodeURIComponent(state.caseId) + "/materials");
        ((mats && mats.materials) || mats || []).forEach(function (m) {
          if (m.title) состояния[m.title] = m;
        });
      } catch (e) { /* без состояний покажем просто список файлов */ }
    }

    var СЛОВА = {
      ok: "прочитан", pending: "разбирается",
      failed: "текст не извлёкся", skipped: "не разбирался"
    };
    var ждут = 0;
    docs.forEach(function (d) {
      var row = el("div", "file1");
      row.appendChild(el("span", "fn", d.title || "Без названия"));
      row.appendChild(el("span", "fsz", human(d.bytes || 0)));
      var m = состояния[d.title];
      if (m) {
        var st = m.extract_status || "pending";
        if (st === "pending") ждут++;
        row.appendChild(el("span", "fst " + st, СЛОВА[st] || st));
      }
      /* Открыть принесённое. Раньше строка была надписью: человек по ней жал,
         а она не была ничем — ни ссылкой, ни кнопкой. Состояние разбора к
         этому отношения не имеет: «разбирается» говорит про извлечение
         ТЕКСТА для агента, а исходные байты лежат в хранилище с самого
         начала, и показать их можно сразу. */
      if (d.id && state.principal) {
        row.classList.add("can");
        row.tabIndex = 0;
        row.setAttribute("role", "button");
        row.title = T(T("Открыть «") + (d.title || T("файл")) + "»");
        (function (d, row) {
          function открыть() { openDoc(d, row); }
          row.addEventListener("click", открыть);
          row.addEventListener("keydown", function (e) {
            if (e.key === "Enter" || e.key === " ") { e.preventDefault(); открыть(); }
          });
        })(d, row);
      }
      list.appendChild(row);
    });

    /* Разбор идёт фоновым обходом с шагом в пять минут, поэтому «разбирается»
       живёт заметно долго. Перечитываем сами — но один раз и с запасом, а не
       по таймеру каждую секунду: страница, дёргающая службу без нужды, стоит
       дороже, чем минута ожидания. */
    if (ждут && !state.filesRecheck) {
      state.filesRecheck = setTimeout(function () {
        state.filesRecheck = null;
        renderFiles();
      }, 45000);
    }
  }

  /* ── Документы дела ────────────────────────────────────────────────

     Один раздел на две роли, и различает их СЛУЖБА, а не оболочка: владельцу
     дела она отдаёт все проекты, участнику — только выданные ему. Здесь мы
     лишь показываем то, что пришло, и не пытаемся угадать, кто мы: угадывание
     на клиенте и есть тот способ, каким показывают лишнее.

     Пропуски видны прямо в списке. Юрист должен наткнуться на «не заполнено»
     раньше, чем отправит документ в суд, — потом это уже определение об
     оставлении без движения. */
  /* ══════════════════════════════════════════════════════════════════════
     ХОЛСТ: документ открыт рядом с разговором.

     ЧТО ЗДЕСЬ ПРАВИТСЯ И ЧТО НЕТ. Правится ТЕКСТ — тот, что уже лежит у нас:
     тело проекта или разобранный текст принесённой бумаги. Исходный файл в
     хранилище не трогается вовсе: его принесли, и правкой на экране он не
     отменяется. Оформление .docx мы не сохраняем и не делаем вид, что
     сохраняем, — об этом сказано прямо в подписи под холстом.

     СОХРАНЕНИЕ НЕ ПЕРЕЗАПИСЫВАЕТ. Каждая правка ложится ОТДЕЛЬНЫМ проектом,
     и агентский исходник остаётся на месте: иначе через неделю нельзя
     ответить, что предложила машина, а что дописал человек.
     ══════════════════════════════════════════════════════════════════════ */

  var холст = null;   // что открыто: {вид, id, title, text, правится, откуда}

  /* Что панель прислала обратно.

     ЕДИНСТВЕННЫЙ путь наружу из песочницы, и потому здесь проверка, а не
     доверие. Сообщения postMessage приходят от кого угодно: любая вкладка,
     любой встроенный кадр, любое расширение. Совпадение по e.source — не
     формальность, а вся защита: без неё панель дела ничем не отличалась бы
     от чужого окна, приславшего «вот заполненная форма».

     ЗАПОЛНЕННОЕ НЕ УХОДИТ САМО. Оно ложится в поле ввода, и человек видит,
     что получилось, прежде чем нажмёт «Отправить». Тот же порядок, что у
     голоса, и по той же причине: ослышка и опечатка в цене или в диагнозе
     стоят дорого, а исправить отправленное нельзя. */
  window.addEventListener("message", function (e) {
    var кадр = document.getElementById("cvframe");
    // Не от нашей панели — не наше дело. Ни разбирать, ни отвечать.
    if (!кадр || !кадр.contentWindow || e.source !== кадр.contentWindow) return;
    var d = e.data;
    if (!d || typeof d !== "object") return;
    /* Реплика из полосы чата холста. Проверка на источник уже сделана выше и
       она та же самая: сообщение не от нашего кадра сюда не доходит. */
    if (d.kind === "fixar.chat") { изХолста(d.text); return; }
    if (d.kind === "fixar.open") { открытьИзХолста(d.url); return; }
    if (d.kind !== "fixar.panel") return;
    var значения = d.values;
    if (!значения || typeof значения !== "object") return;

    var строки = [];
    Object.keys(значения).slice(0, 25).forEach(function (k) {
      var v = значения[k];
      if (v === "" || v === false || v == null) return;
      if (v === true) v = "да";
      // Ключи и значения пришли из песочницы: кладём их ТЕКСТОМ в поле ввода,
      // а не в разметку. В value textarea разметка не разбирается.
      строки.push(String(k).slice(0, 64) + ": " + String(v).slice(0, 400));
    });

    var подпись = String((холст && холст.title) || d.title || "Форма").slice(0, 120);
    // Поле ввода однострочное, поэтому «; », а не перенос: перенос в нём
    // превратился бы в невидимый пробел, и пары «поле: значение» слиплись бы.
    var текст = строки.length
      ? подпись + " — " + строки.join("; ")
      : подпись + T(" — ничего не заполнено.");
    var поле = document.getElementById("input");
    if (поле) {
      поле.value = поле.value.trim() ? поле.value.trim() + " | " + текст : текст;
      поле.focus();
      // Курсор в конец: у длинной формы начало уезжает за край, и человек
      // решил бы, что не сработало.
      try { поле.setSelectionRange(поле.value.length, поле.value.length); }
      catch (err) { /* не всякий тип поля это умеет */ }
    }
  });

  /* Набранное, но не сохранённое — по документу.

     Холст закрывается тремя путями: крестиком, уходом из дела и открытием
     следующей бумаги. Все три стирали правку молча, а спросить было нечем:
     закрытие бывает и не по воле человека. Поэтому не спрашиваем, а
     ЗАПОМИНАЕМ: текст остаётся здесь и возвращается, когда тот же документ
     откроют снова. Ничья работа не пропадает, и ни одного лишнего вопроса.

     Живёт в памяти вкладки, а не в localStorage: черновик договора — это
     содержимое дела, и складывать его в хранилище браузера, откуда его
     достанет любой, кто сядет за этот компьютер, значило бы вынести дело
     наружу ради удобства. Перезагрузка страницы правку теряет — об этом
     честно предупреждает beforeunload ниже. */
  var несохранённое = {};

  function запомнитьНабранное() {
    if (!холст || !холст.правится || холст.вид !== "draft" || !холст.id) return;
    var поле = document.getElementById("cvbody");
    if (!поле) return;
    var текст = поле.value;
    if (текст && текст !== (холст.text || "")) несохранённое[холст.id] = текст;
    else delete несохранённое[холст.id];
  }

  //: Есть ли прямо сейчас несохранённая правка — для beforeunload.
  function естьНесохранённое() {
    запомнитьНабранное();
    for (var k in несохранённое) if (несохранённое[k]) return true;
    return false;
  }

  //: Перезагрузка и закрытие вкладки — единственный путь, на котором память
  //: не спасает. Здесь спросить можно и нужно: браузер сам покажет вопрос.
  window.addEventListener("beforeunload", function (e) {
    if (!естьНесохранённое()) return;
    e.preventDefault();
    e.returnValue = "";      // требование старых браузеров
    return "";
  });

  function closeCanvas() {
    запомнитьНабранное();
    // Файл, собранный в памяти, держится до отзыва — иначе десяток открытых
    // за сеанс бумаг остаётся в памяти вкладки до перезагрузки страницы.
    if (холст && холст.blobUrl) {
      var кадр = document.getElementById("cvframe");
      if (кадр) кадр.removeAttribute("src");
      URL.revokeObjectURL(холст.blobUrl);
    }
    холст = null;
    var box = document.getElementById("canvaspane");
    if (box) box.hidden = true;
  }

  /* Открыть ссылку, о которой попросил холст.

     ОТКРЫВАЕТ РОДИТЕЛЬ, А НЕ ПЕСОЧНИЦА. Кадру не выдано allow-popups, и
     выдавать нельзя: карточки собраны из чужих витрин, и право открывать
     окна у них было бы правом уводить человека куда угодно. Просьба приходит
     тем же каналом, что и реплики чата, и проверяется там же по e.source.

     ЧТО ПРОВЕРЯЕМ ЗДЕСЬ. Адрес пришёл из чужого объявления — значит это
     ЧУЖОЙ ТЕКСТ, а не наш. Пускаем только http и https: javascript: и data:
     в этом месте означали бы выполнение чужого кода нашими руками, а
     родитель — не песочница.

     ГОВОРИМ, КУДА ИДЁМ. Человек нажимает «карточка объявления», а уезжает на
     сайт, которого не называл. Имя узла в реплике — не вежливость: по нему
     видно, что открылось не то, ещё до того как открылось.

     noopener ОБЯЗАТЕЛЕН: без него открытая страница получает ссылку на наше
     окно и может им распоряжаться. */
  function открытьИзХолста(адрес) {
    var сырое = typeof адрес === "string" ? адрес.trim().slice(0, 2000) : "";
    var узел = "";
    try {
      var u = new URL(сырое);
      if (u.protocol !== "http:" && u.protocol !== "https:") throw 0;
      узел = u.host;
    } catch (e) {
      say("bot", "Ф", "Ссылку открыть не могу: в объявлении не адрес " +
          "страницы, а что-то другое. Открывать такое вслепую нельзя.");
      return;
    }
    var окно = window.open(сырое, "_blank", "noopener,noreferrer");
    if (!окно) {
      /* Браузер погасил окно — на телефонах это обычное дело. Молчать здесь
         значило бы вернуть ровно ту беду, которую чиним.

         АДРЕС КЛАДЁМ ГОЛЫМ НАРОЧНО. Переписка сама превращает голый https://
         в настоящую <a target="_blank" rel="noopener noreferrer"> — см.
         inline() и ссылкой(). Ссылка эта живёт в РОДИТЕЛЬСКОМ документе, не в
         песочнице, и нажатие по ней — обычный человеческий жест, который
         открывает вкладку всегда. Поэтому починка не висит на том, дойдёт ли
         до родителя активация от нажатия внутри кадра: не дойдёт — человек
         получит ссылку, по которой можно нажать. Проверено на живом 23.08:
         пузырь отказа содержит рабочую <a>. */
      say("bot", "Ф", T("Браузер не дал открыть вкладку сам — откройте " +
          "по ссылке: ") + сырое);
      return;
    }
    say("bot", "Ф", T("Открыл в соседней вкладке: ") + узел +
        T(". Это чужая площадка — за то, что там написано, отвечает она."));
  }

  /* Сказать что-то внутрь холста.

     Целевой origin "*" — не небрежность и не выбор: у песочницы с srcdoc
     origin непрозрачный, назвать его нечем. Обмен при этом остаётся закрытым
     с обеих сторон: ссылка на окно кадра есть только у нас, а кадр сверяет
     e.source с parent и чужое сообщение выбрасывает. Поэтому и кладём сюда
     ТОЛЬКО текст ответа — то, что человек читает в переписке. */
  function вХолст(сообщение) {
    var кадр = document.getElementById("cvframe");
    if (!кадр || !кадр.contentWindow) return;
    var отдать = function () {
      try { кадр.contentWindow.postMessage(сообщение, "*"); }
      catch (err) { /* кадр закрыли, пока считался ход */ }
    };
    // Не поднялся — ждём загрузки. Иначе ответ уходит в пустоту, и человек
    // видит свежий холст с пустой полосой: спросил и будто не спрашивал.
    if (кадр.поднялся) отдать();
    else кадр.addEventListener("load", отдать, { once: true });
  }

  /* Ход, начатый из холста, идёт ТЕМ ЖЕ send: реплика попадает в общую
     переписку и в журнал дела, ход считается один раз.

     Ответ ищется по журналу, а не приходит из send отдельным значением, и
     это намеренно: показать в полосе можно только то, что человек уже видит
     слева. Считать пузыри ДО хода обязательно — иначе «ответ не пришёл»
     неотличимо от «ответ был прежний», а прежним он бывает законно, когда
     повтор ушёл с тем же идентификатором. */
  async function изХолста(текст) {
    var т = (typeof текст === "string" ? текст : "").trim().slice(0, 2000);
    if (!т) return;
    if (state.busy) {
      // Молча проглотить значило бы потерять набранное: поле в полосе уже
      // очищено, и человек решил бы, что отправилось.
      вХолст({ kind: "fixar.error",
               text: "Предыдущий ход ещё считается — спросите, когда ответит." });
      return;
    }
    var было = log.querySelectorAll(".msg.bot").length;
    try {
      await send(т);
    } catch (err) {
      вХолст({ kind: "fixar.error", text: T("Не дошло: ") + err });
      return;
    }
    var все = log.querySelectorAll(".msg.bot");
    if (все.length <= было) {
      вХолст({ kind: "fixar.error",
               text: "Ответ пришёл в переписку — посмотрите слева." });
      return;
    }
    /* АВТОРА БЕРЁМ ИЗ САМОГО ПУЗЫРЯ, а не подписываем «Агент» на веру.
       Последним в ленте бывает не только ответ агента: служебное сообщение Ф
       или реплика другого, слепого к делу агента выглядят так же. Подписать
       их «Агент» значит соврать ровно там, где человек и решает, верить ли
       ответу. Метка эта уже нарисована слева — вниз едет то, что он видит. */
    var узел = все[все.length - 1];
    var поле = узел.querySelector(".bubble");
    var кто = узел.querySelector(".who");
    вХолст({
      kind: "fixar.reply",
      text: ((поле && поле.textContent) || "").trim().slice(0, 4000),
      who: (((кто && кто.textContent) || "Агент").trim() || "Агент").slice(0, 40)
    });
  }

  function openCanvas(предмет) {
    var box = document.getElementById("canvaspane");
    if (!box) return;
    холст = предмет;
    document.getElementById("cvtitle").textContent = T(предмет.title || "Документ");
    document.getElementById("cvfrom").textContent = T(предмет.откуда || "");
    var поле = document.getElementById("cvbody");
    var кадр = document.getElementById("cvframe");
    /* Принесённая бумага показывается сама, а не её пересказ. Место одно, и
       занято оно либо правимым текстом, либо исходным файлом: показать разом
       и то и другое значило бы предложить править то, что не правится. */
    /* Кадр пересоздаётся каждый раз — ради простоты, а не из необходимости.

       У кадра три взаимоисключающих состояния (srcdoc с песочницей, src на
       blob без неё, скрытый), и переключение между ними — это снять два
       атрибута и поставить третий в верном порядке. Свежий элемент делает
       порядок неважным: у него по определению нет ничего от предыдущего.

       ЧЕГО ЗДЕСЬ НЕТ. Это не обход того, что «sandbox не применяется к
       живому кадру»: применяется. Проверено на живом 18.08 — тот же элемент
       без песочницы прочитал 4 ключа localStorage, он же с выставленным
       sandbox и новым srcdoc получил отказ. Первоначально я решил иначе,
       потому что судил по снимку экрана, а снимок содержимое песочницы не
       захватывает вовсе: кадр выглядит пустым, когда он работает. */
    if (кадр) {
      var свежий = document.createElement("iframe");
      свежий.id = "cvframe";
      свежий.className = кадр.className;
      свежий.setAttribute("title", "Просмотр документа");
      /* Отметка «скрипт холста поднялся». srcdoc разбирается асинхронно, и
         ответ, посланный в кадр раньше этого, принять некому: слушателя в
         песочнице ещё нет. Случай не выдуманный — ответ на вопрос из полосы
         сам открывает новый холст, и реплика уходила бы в кадр, которому
         миллисекунда от роду. Свойство на элементе, а не data-атрибут:
         атрибут пережил бы подмену srcdoc, а свойство умирает с кадром. */
      свежий.addEventListener("load", function () { свежий.поднялся = true; });
      if (предмет.html) свежий.setAttribute("sandbox", "allow-scripts");
      кадр.replaceWith(свежий);
      кадр = свежий;
    }

    if (предмет.html) {
      /* ПАНЕЛЬ — единственное, что у нас исполняется, и потому единственное,
         что идёт в песочницу.

         sandbox="allow-scripts" БЕЗ allow-same-origin: скрипты работают, но
         origin у кадра непрозрачный, и до localStorage родителя — где лежит
         токен входа — ему не дотянуться. Проверено на живом 18.08: тот же
         скрипт без песочницы вернул 4 ключа, в песочнице не выполнился.

         Почему srcdoc, а не blob: у blob origin наследуется от нас, и тогда
         песочница остаётся единственной преградой. srcdoc в песочнице даёт
         непрозрачный origin сразу, без промежуточного состояния.

         allow-forms, allow-popups и allow-top-navigation НЕ выданы намеренно:
         панели не нужно уводить человека со страницы, а нужно вернуть
         заполненное — для этого есть postMessage. */
      поле.hidden = true;
      if (кадр) { кадр.hidden = false; кадр.srcdoc = предмет.html; }
    } else if (предмет.blobUrl) {
      /* Принесённая бумага. Песочницы здесь НЕТ, и это осознанно: с ней
         просмотрщик PDF показывает пустой лист (проверено и с sandbox="",
         и с allow-scripts). Взамен сужен список показываемого — см. ВИДИМЫЕ:
         в нём нет ни одного типа, который браузер разбирает как документ со
         скриптами. */
      поле.hidden = true;
      if (кадр) { кадр.hidden = false; кадр.src = предмет.blobUrl; }
    } else {
      if (кадр) кадр.hidden = true;
      поле.hidden = false;
      // Незаконченная правка этого же документа возвращается, а не пропадает.
      var отложенное = (предмет.вид === "draft" && предмет.id)
        ? несохранённое[предмет.id] : "";
      поле.value = отложенное || предмет.text || "";
      предмет.вернули = !!отложенное;
      поле.readOnly = !предмет.правится;
    }
    document.getElementById("cvnote").textContent = предмет.вернули
      ? T("Вернул вашу незаконченную правку — она не была сохранена.")
      : T(предмет.подпись || "");
    // Скачать можно только то, у чего файл уже есть: проект, лежащий на
    // сервере, или принесённую бумагу, собранную здесь. У правки, ещё не
    // сохранённой, файла нет, и кнопка, ведущая в никуда, хуже её отсутствия.
    document.getElementById("cvget").hidden =
      предмет.вид !== "draft" && !предмет.blobUrl;
    document.getElementById("cvsave").hidden = !предмет.правится;
    box.hidden = false;
    box.scrollIntoView({ block: "nearest" });
  }

  /* Скачать файл через дверь, с токеном. Отдельной функцией, потому что мест,
     где надо забрать байты, больше одного, и каждое из них без токена молча
     получает 401 вместо файла.

     ИМЯ ФАЙЛА ЗАДАЁМ ЗДЕСЬ. Content-Disposition, который собирает служба,
     до браузера не доезжает: дверь пересобирает ответ и заголовков не
     переносит. Полагаться на него значит отдать человеку файл со случайным
     именем. */
  /* ОТКРЫТЬ ИСХОДНИК БУМАГИ — на холсте и, если сказано, на нужной странице.

     ЧЕГО НЕ ХВАТАЛО. Нажатие на имя бумаги открывало РАЗОБРАННЫЙ ТЕКСТ, а сам
     файл доставался только из списка хранилища, где материал связывался с
     документом ПО НАЗВАНИЮ (`состояния[m.title] = m`): два одноимённых файла
     склеивались в один. Значит «открыть в источнике» — четвёртая строка
     карточки-цитаты — была обещанием без механизма: во всей оболочке не было
     ни одного «#page=».

     Здесь оно появляется. Берём байты своей ручкой по ИДЕНТИФИКАТОРУ
     материала, а не по названию: `/cases/{дело}/materials/{бумага}/content`
     проверяет и участие, и род сведений — то есть открывает ровно то, что
     человеку в этом деле и так открыто.

     СТРАНИЦА — ФРАГМЕНТОМ АДРЕСА. `#page=N` понимают встроенные просмотрщики
     PDF; для прочих видов он безвреден и просто игнорируется. Номер приходит
     оттуда же, где его посчитал сервер по найденной цитате, — оболочка его не
     выдумывает и не пересчитывает. */
  var исходникОткрывается = false;

  async function открытьИсходник(m, страница) {
    if (исходникОткрывается) return;
    if (!state.caseId || !m || !m.id) return;
    исходникОткрывается = true;
    var url = null;
    try {
      var opts = { method: "GET", headers: {} };
      if (state.token) opts.headers["Authorization"] = "Bearer " + state.token;
      var r = await fetch(API + "/cases/" + encodeURIComponent(state.caseId) +
                          "/materials/" + encodeURIComponent(m.id) + "/content", opts);
      if (!r.ok) {
        var почему = "";
        try { почему = (JSON.parse(await r.text()) || {}).detail || ""; } catch (e) {}
        // Здесь `fetch` сырой, без `api`, — значит ошибку с полями `status`
        // и `data` собираем сами: иначе `reason` не отличит поломку от отказа
        // и `detail` службы уехал бы человеку дословно.
        var беда = new Error(почему || ("HTTP " + r.status));
        беда.status = r.status;
        if (почему) беда.data = { detail: почему };
        сорвалось(T("Исходник не открылся: "), беда,
            T(". Разобранный текст бумаги при этом на месте — откройте его " +
              "нажатием на название."));
        return;
      }
      url = URL.createObjectURL(await r.blob());
      var мим = m.mime || "application/octet-stream";
      if (!ВИДИМЫЕ.test(мим)) {
        // Показать не можем — но и молчать нельзя: человек нажал и ждёт.
        say("bot", "Ф", T("Этот вид файла на холсте не показывается: ") + мим +
            T(". Он цел — его можно скачать."));
        URL.revokeObjectURL(url);
        url = null;
        return;
      }
      // Прежний файл отпускаем до открытия нового: иначе объект остаётся в
      // памяти вкладки до перезагрузки страницы.
      closeCanvas();
      openCanvas({
        вид: "file", id: m.id, title: m.title || T("Бумага"),
        откуда: T("исходный файл · принесено в дело"),
        // Фрагмент цепляем к адресу объекта: просмотрщик PDF откроет
        // названную страницу, остальные виды его не заметят.
        blobUrl: страница ? url + "#page=" + страница : url,
        правится: false,
        подпись: страница
          ? T("Открыто на странице ") + страница +
            T(" — там, где нашлась цитата. Это исходный файл, как его принесли.")
          : T("Это исходный файл, как его принесли. Правки он не принимает."),
      });
      url = null;                       // отпустит closeCanvas
    } catch (e) {
      сорвалось(T("Исходник не открылся: "), e);
    } finally {
      if (url) URL.revokeObjectURL(url);
      исходникОткрывается = false;
    }
  }

  async function скачатьЧерезДверь(путь, имя) {
    var opts = { method: "GET", headers: {} };
    if (state.token) opts.headers["Authorization"] = "Bearer " + state.token;
    var r;
    try {
      r = await fetch(API + путь, opts);
    } catch (e) {
      сорвалось(T("Файл не скачался: связь оборвалась."), null);
      return;
    }
    if (!r.ok) {
      var text = "";
      try { text = (JSON.parse(await r.text()) || {}).detail || ""; } catch (e) {}
      var беда = new Error(text || ("HTTP " + r.status));
      беда.status = r.status;
      if (text) беда.data = { detail: text };
      сорвалось(T("Файл не скачался: "), беда);
      return;
    }
    var blob = await r.blob();
    var url = URL.createObjectURL(blob);
    var a = el("a");
    a.href = url;
    a.download = имя;
    document.body.appendChild(a);
    a.click();
    a.remove();
    // Отпускаем не сразу: Safari успевает начать скачивание не всегда, и
    // отозванный тут же адрес даёт пустой файл.
    setTimeout(function () { URL.revokeObjectURL(url); }, 60000);
  }

  function setupCanvas() {
    var закрыть = document.getElementById("cvclose");
    if (закрыть) закрыть.addEventListener("click", closeCanvas);

    var скачать = document.getElementById("cvget");
    if (скачать) скачать.addEventListener("click", function () {
      if (!холст) return;
      if (холст.blobUrl) {
        // Своё же, уже в памяти — качаем без второго похода в службу.
        var a = el("a");
        a.href = холст.blobUrl;
        a.download = холст.title || "файл";
        document.body.appendChild(a);
        a.click();
        a.remove();
        return;
      }
      if (холст.вид !== "draft") return;
      // ЧЕРЕЗ fetch, А НЕ window.open. Переход верхнего уровня на чужой origin
      // не несёт заголовка Authorization — токен лежит в localStorage и в
      // навигацию не попадает, — а дверь для неанонимного пути отвечает 401
      // без него. Вкладка открывалась и показывала JSON с отказом; кнопка
      // «скачать» не работала ни разу. Образец рядом, двадцатью строками
      // выше: blob и <a download>.
      скачатьЧерезДверь("/drafts/" + encodeURIComponent(холст.id) + "/file?fmt=rtf",
                        (холст.title || T("документ")) + ".rtf");
    });

    var сохранить = document.getElementById("cvsave");
    if (сохранить) сохранить.addEventListener("click", async function () {
      if (!холст || !холст.правится) return;
      var поле = document.getElementById("cvbody");
      var текст = поле.value;
      var заметка = document.getElementById("cvnote");
      if (!текст.trim()) { заметка.textContent = T("Пустое не сохраняю."); return; }
      if (текст === (холст.text || "")) {
        заметка.textContent = T("Ничего не изменилось — сохранять нечего.");
        return;
      }
      сохранить.disabled = true;
      заметка.textContent = T("Сохраняю…");
      var созданный;
      try {
        созданный = await api("POST", "/cases/" +
          encodeURIComponent(state.caseId) + "/drafts", {
            title: холст.title || "Документ",
            body: текст,
            basis: холст.родословная || "",
            kind: холст.kind || "",
            // ИЗ ЧЕГО правили. Только когда на холсте лежал проект: правка
            // принесённой бумаги или текст с нуля родителя не имеют, и
            // приписать его значило бы объявить текст производным от чужого.
            parent_id: (холст.вид === "draft" && холст.id) ? холст.id : ""
          });
      } catch (e) {
        сохранить.disabled = false;
        // Текст человека остаётся в поле. Потерять набранное из-за отказа
        // сервера — худшее, что здесь можно сделать.
        заметка.textContent = T(T("НЕ сохранено: ") + reason(e) +
          T(". Текст остался в поле — попробуйте ещё раз."));
        return;
      }
      сохранить.disabled = false;
      // Правка легла в дело — держать её ещё и в памяти вкладки незачем:
      // иначе она вернётся поверх сохранённого и человек решит, что сохранение
      // не сработало.
      if (холст.id) delete несохранённое[холст.id];
      /* РАСХОЖДЕНИЕ. Служба считает, сколько версий уже выросло из того же
         текста, и говорит числом. Ни запрета, ни слияния тут нет и не будет:
         запретить значило бы потерять работу второго, слить — решить за
         обоих, чей абзац главнее. Наше дело — не дать человеку узнать об
         этом через неделю. */
      var сколько = созданный.diverged_from_parent || 0;
      заметка.textContent = T(сколько
        ? (T("Сохранено. Но от этой же версии уже правили ") + сколько + " " +
           plural(сколько, T("раз"), T("раза"), T("раз")) +
           T(" — в списке документов теперь несколько веток одного текста."))
        : "Сохранено отдельным документом. Исходник на месте.");
      // Теперь на холсте лежит сохранённый проект: его и качать, и править
      // дальше — уже как проект.
      холст = { вид: "draft", id: созданный.id, title: созданный.title,
                text: созданный.body, правится: true,
                откуда: "проект · составлен вами",
                родословная: T("правка проекта ") + созданный.id };
      document.getElementById("cvget").hidden = false;
      document.getElementById("cvfrom").textContent = T(холст.откуда);
      await renderDocs();
      // Агент узнаёт о правке ровно здесь — по кнопке, а не по каждой
      // набранной букве: каждый ход стоит денег и попадает в журнал
      // обращений, и незаметно тратить чужие деньги нельзя.
      await dialogTurn(
        T("Я выправил документ «") + (созданный.title || T("без названия")) +
        T("» и сохранил его. Вот текст целиком — посмотри, что изменилось по " +
        "сравнению с прежним, и скажи, что из этого важно:\n\n") + текст);
    });
  }

  /* Принесённое: список бумаг дела с открытием на холсте.

     ЧЕСТНОСТЬ ПРО РАЗБОР. У материала есть extract_status, и он бывает не
     только 'ok'. Показать пустой холст там, где текст ещё не извлечён или
     извлечь не удалось, значит соврать: человек прочтёт «в бумаге ничего
     нет». Поэтому у каждой строки написано, что с ней на самом деле. */
  var РАЗБОР = {
    pending: "ещё не разобрана",
    failed: "разобрать не удалось",
    skipped: "не разбиралась"
  };

  /* Общий короб артефактов. Зовётся ПОСЛЕ четырёх разрядов и смотрит на то,
     что они решили о себе: спрашивать службы второй раз значит удвоить запросы
     ради числа, которое уже посчитано.

     ПУСТОТА НАЗЫВАЕТСЯ СЛОВАМИ. Четыре самопрячущихся короба давали в сумме не
     экономию места, а невидимость: человек не знал, что место для бумаг
     вообще есть, и не понимал, куда попадёт загруженный файл. Пустое место,
     названное словами, отвечает на вопрос «а где это будет»; отсутствие места
     не отвечает ни на что. */
  function renderArtifacts() {
    var короб = document.getElementById("artifacts");
    var пусто = document.getElementById("artempty");
    var шапка = document.getElementById("artifactshead");
    if (!короб) return;
    if (!state.caseId) { короб.hidden = true; return; }
    короб.hidden = false;
    var разряды = ["files", "papers", "docs", "finds"];
    var видимых = разряды.filter(function (id) {
      var b = document.getElementById(id);
      return b && !b.hidden;
    }).length;
    if (шапка) шапка.textContent = T("Артефакты дела");
    // ПОРУЧЕНИЕ. Кнопка была написана и не подключена ни разу: startRun
    // существовала, элемента под неё в разметке не было, и запустить дело
    // из оболочки человек не мог никак.
    var поручить = document.getElementById("startrun");
    if (поручить) поручить.onclick = startRun;
    var строкаПоиска = document.getElementById("runquery");
    if (строкаПоиска) {
      // Enter в строке — привычное движение. Без него человек набирает,
      // жмёт Enter, и не происходит ничего.
      строкаПоиска.addEventListener("keydown", function (e) {
        if (e.key === "Enter") { e.preventDefault(); startRun(); }
      });
    }
    // ПРОСЬБА О ПРОЕКТЕ — рядом с поручением и по тому же уроку: кнопка,
    // написанная и не подключённая, выглядит как работающая ровно до нажатия.
    var составить = document.getElementById("startdraft");
    if (составить) составить.onclick = startDraft;
    var строкаПросьбы = document.getElementById("draftask");
    if (строкаПросьбы) {
      строкаПросьбы.addEventListener("keydown", function (e) {
        if (e.key === "Enter") { e.preventDefault(); startDraft(); }
      });
    }
    var разговорПдф = document.getElementById("talkpdf");
    if (разговорПдф) {
      разговорПдф.onclick = function () { сохранитьРазговорВPDF(разговорПдф); };
    }
    if (!пусто) return;
    if (видимых) { пусто.hidden = true; return; }
    пусто.hidden = false;
    // Перечисляем, ЧТО сюда попадает, а не извиняемся за пустоту: человек
    // спрашивает не «почему пусто», а «куда смотреть, когда появится».
    пусто.textContent = T("Пока пусто. Сюда попадут приложенные файлы, " +
      "бумаги дела, составленные документы и найденное на витрине.");
  }

  /* Разбор идёт ФОНОМ, и список к нему возвращается сам.

     Прежде `renderPapers` звалась один раз — сразу после загрузки, когда
     обходчик ещё не дошёл до файла. Строка честно говорила «ещё не
     разобрана»… и оставалась такой навсегда: перерисовать её было некому.
     Человек видел разобранный файл в одном списке и «Открыть нечем: текста из
     этой бумаги у нас пока нет» в другом — про тот же файл. Поймано на живом
     28.08.2026.

     ЛЕСЕНКА, А НЕ РОВНЫЙ ОПРОС. Разбор занимает секунды на текстовом PDF и
     минуты на большом: частые проверки в начале ловят первое, редкие в конце —
     второе, и всё это стоит четырёх запросов вместо тридцати.

     КОНЧАЕТСЯ ВСЕГДА. Не разобралось за две минуты — перестаём: строка при
     этом не врёт (там стоит настоящее состояние), а вечный опрос в оболочке
     запрещён и по уговору, и по здравому смыслу — вкладка живёт часами.

     setTimeout, а не setInterval: при медленном ответе интервал строит
     очередь запросов, и она не рассасывается. */
  var ждёмРазбора = null;
  var ЛЕСЕНКА_РАЗБОРА = [4000, 10000, 30000, 60000];

  function ждатьРазбора(шаг) {
    if (ждёмРазбора) { clearTimeout(ждёмРазбора); ждёмРазбора = null; }
    if (шаг >= ЛЕСЕНКА_РАЗБОРА.length) return;
    ждёмРазбора = setTimeout(function () {
      ждёмРазбора = null;
      renderPapers({ шагОжидания: шаг + 1 });
    }, ЛЕСЕНКА_РАЗБОРА[шаг]);
  }

  async function renderPapers(как) {
    var box = document.getElementById("papers");
    var list = document.getElementById("paperlist");
    var head = document.getElementById("papershead");
    if (!box || !state.caseId || !state.principal) {
      if (box) box.hidden = true;
      return;
    }
    var бумаги;
    try {
      бумаги = await api("GET", "/cases/" + encodeURIComponent(state.caseId) +
                         "/materials");
    } catch (e) {
      // Отказ службы — не «бумаг нет». Скажем вслух и не будем прятать короб.
      box.hidden = false;
      head.textContent = T("Бумаги дела");
      list.innerHTML = "";
      list.appendChild(el("div", "fnote", T("Список бумаг не пришёл: ") + reason(e)));
      return;
    }
    /* УРЕЗАНИЕ НАЗЫВАЕТСЯ ВСЛУХ.

       Служба режет список по роду сведений, а счётчик считал уже урезанное:
       «Бумаги дела: 3» человек читает как «их три», а не «вам показано три
       из пяти». Агенту про ту же границу говорят словами — «ещё N
       материал(ов) закрыты твоим допуском», — то есть машина о ней узнавала,
       а человек нет.

       Число, а не названия: имя закрытой бумаги — уже часть тайны. */
    var скрыто = (бумаги && typeof бумаги === "object" && !Array.isArray(бумаги))
      ? (бумаги.hidden || 0) : 0;
    бумаги = (бумаги && бумаги.materials) || бумаги || [];
    if (!Array.isArray(бумаги)) бумаги = [];
    if (!бумаги.length && !скрыто) { box.hidden = true; return; }
    box.hidden = false;
    head.textContent = T(скрыто
      ? T("Бумаги дела: показано ") + бумаги.length + T(" из ") + (бумаги.length + скрыто)
      : T("Бумаги дела: ") + бумаги.length);
    list.innerHTML = "";
    бумаги.forEach(function (m) {
      var row = el("div", "doc1");
      var имя = el("span", "dn", m.title || m.kind || "бумага");
      var готова = m.extract_status === "ok" && (m.extracted || "").trim();
      if (готова) {
        имя.style.cursor = "pointer";
        имя.title = T("Открыть на холсте");
        имя.addEventListener("click", function () {
          openCanvas({
            вид: "material", id: m.id, title: m.title || "Бумага",
            text: m.extracted, правится: true,
            откуда: T("принесённое · ") + (m.mime || m.kind || ""),
            родословная: T("из бумаги ") + m.id,
            подпись: "Правится РАЗОБРАННЫЙ текст. Исходный файл в хранилище " +
                     "не меняется, оформление не сохраняется. Сохранение " +
                     "заведёт отдельный документ."
          });
        });
      }
      row.appendChild(имя);
      /* ОТКРЫТЬ ИСХОДНИК. Отдельно от имени, и это не прихоть: имя открывает
         РАЗОБРАННЫЙ текст, который правится, а здесь — файл, как его принесли.
         Две разные вещи под одним нажатием читались бы как одна.

         Показываем только у того, что холст умеет показать: кнопка, ведущая к
         «этот вид не показывается», хуже её отсутствия. */
      if (ВИДИМЫЕ.test(m.mime || "")) {
        var исходник = el("button", "addone dget", T("Исходник"));
        исходник.type = "button";
        исходник.title = T("Открыть файл, как его принесли");
        // Без страницы: страница принадлежит ЦИТАТЕ, а не бумаге. Здесь
        // человек открывает файл целиком — с начала.
        исходник.addEventListener("click", function () { открытьИсходник(m, 0); });
        row.appendChild(исходник);
      }
      // РОД СВЕДЕНИЙ ВИДЕН. Без метки человек не знает, почему бумага не
      // дошла до агента и почему её не видит позванный коллега, — а причина
      // именно здесь. Обычное не подписываем: подпись у каждой строки, где
      // сказать нечего, перестаёт читаться вовсе.
      if (m.sensitivity && m.sensitivity !== "normal") {
        var род = el("span", "sens", родСловом(m.sensitivity));
        // ОТКУДА взялся род — в той же подсказке. Без этого «медицинское»
        // читается как решение, даже когда это грубая догадка по словам.
        var откуда = ОТКУДА_РОД[m.sensitivity_source] || "";
        род.title = T("Этот род сведений виден не всем участникам и не всякому " +
                  "помощнику. За пределы площадки такие бумаги не уходят.") +
                  (откуда ? T("\nОткуда: ") + откуда + "." : "");
        row.appendChild(род);
      }
      row.appendChild(правкаРода(m, renderPapers));
      row.appendChild(el("span", "dst", готова ? "разобрана"
                                               : (РАЗБОР[m.extract_status] ||
                                                  m.extract_status)));
      // ЗАБРАТЬ САМ ФАЙЛ. До 21.08.2026 это мог только тот, кто его приложил:
      // единственная ручка чтения байтов жила в личном хранилище и отвечала
      // по правилу «только своё». Участник видел строку и разобранный текст —
      // и не мог открыть документ ни при каких правах.
      //
      // Кнопка стоит у КАЖДОЙ бумаги, включая неразобранную: разбор — про
      // текст, а файл цел независимо от того, вынули из него текст или нет.
      var взять = el("button", "addone dget", "Скачать");
      взять.type = "button";
      взять.addEventListener("click", function () {
        скачатьЧерезДверь(
          "/cases/" + encodeURIComponent(state.caseId) + "/materials/" +
          encodeURIComponent(m.id) + "/content",
          m.title || (T("материал-") + m.id.slice(-6)));
      });
      row.appendChild(взять);
      list.appendChild(row);
      if (!готова) {
        // Причину говорим, если служба её назвала. «Разобрать не удалось» без
        // причины — правда, но бесполезная: скан это, битый файл или файл
        // пропал из хранилища, по такому ответу не понять, а делать надо
        // разное.
        list.appendChild(el("div", "fnote", m.extract_note
          ? T("Открыть нечем: ") + m.extract_note
          : "Открыть нечем: текста из этой бумаги у нас пока нет."));
      }
      if ((m.redactions || []).length) {
        list.appendChild(el("div", "fnote",
          T("В разобранном замаскировано: ") + m.redactions.join(", ")));
      }
    });

    /* Осталось неразобранное — вернёмся и посмотрим ещё раз.
       Только `pending`: «разобрать не удалось» и «не разбиралась» — состояния
       КОНЕЧНЫЕ, и ждать у них нечего. Ждать конечного состояния значит
       обещать человеку перемену, которой не будет. */
    var ждут = бумаги.some(function (m) {
      return (m.extract_status || "pending") === "pending";
    });
    if (ждут) {
      ждатьРазбора((как && как.шагОжидания) || 0);
    } else if (ждёмРазбора) {
      clearTimeout(ждёмРазбора);
      ждёмРазбора = null;
    }
  }

  /* ── Найденное на витрине ───────────────────────────────────────────

     Отдельно от бумаг и документов намеренно: бумага — то, что дали,
     документ — то, что мы составили, а это чужое объявление, за которое не
     отвечает никто из нас. И стареет оно иначе: цена в карточке верна минуту.

     ПОЧЕМУ РАЗМЕТКУ СОБИРАЕМ ЗДЕСЬ, А НЕ НА СЛУЖБЕ. Панели собирает
     shared/panels.py — потому что их описывает МОДЕЛЬ, и разметку ей писать
     нельзя. Здесь другое: данные пришли структурой (Option со своими полями),
     и собирать из них карточку — обычная отрисовка. Но заголовок и сводка
     всё равно ЧУЖИЕ, с витрины, поэтому экранируются все до одного.

     Кадр при этом остаётся в песочнице (sandbox="allow-scripts", без
     allow-same-origin), так что даже пробившийся скрипт до токена входа в
     localStorage родителя не дотянется — проверено на живом 18.08. */

  function экранировать(v) {
    return String(v == null ? "" : v)
      .replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;")
      .replace(/"/g, "&quot;").replace(/'/g, "&#39;");
  }

  //: Что означает происхождение картинки. Слово ЗДЕСЬ, а не на службе,
  //: потому что это подпись для глаза; сама пометка приходит полем origin.
  /* Подписи говорят про ЭКЗЕМПЛЯР, а не про «машину».
     Слова писались под экскаваторы, и «фото этой машины» под чайником с
     Авито не читается вовсе. Различие же везде одно и то же: сняли ту самую
     вещь, которую отдадут, или показали модель, а приедет другая. */
  var ОТКУДА_ФОТО = {
    own: "снято с этого экземпляра",
    catalog: "снимок из каталога модели — приедет другой экземпляр",
    type: "типовая иллюстрация — НЕ этот товар"
  };

  /* ── Сохранить найденное в PDF ──────────────────────────────────────

     Способ взят из АгриФореста, где он обкатан на коммерческих предложениях:
     документ собирает БРАУЗЕР через jsPDF, а не сервер.

     ПОЧЕМУ НЕ СЕРВЕР. В наших службах нет ни одной библиотеки сборки PDF —
     ни reportlab, ни weasyprint, ни fpdf, — и заводить её значит заводить
     шрифты, вёрстку и вес образа ради документа, который человек уносит себе.
     Браузер уже умеет всё, что нужно.

     ПОЧЕМУ СВОЙ ШРИФТ. Встроенные в jsPDF шрифты знают только latin-1, и это
     не настройка, а устройство формата: стандартные 14 шрифтов PDF физически
     не содержат кириллических глифов. Без PT Sans документ выходит
     кракозябрами — не «немного хуже», а нечитаемым.

     ПОЧЕМУ ПО ТРЕБОВАНИЮ. Библиотека и шрифт вместе весят под восемьсот
     килобайт. Грузить их при каждом открытии страницы ради кнопки, которую
     нажимают редко, — платить всем за нужное немногим. */

  var _пдфДок = null, _пдфШрифт = null;

  function _грузитьСкрипт(src) {
    return new Promise(function (ok, нет) {
      var s = document.createElement("script");
      s.src = src;
      s.onload = ok;
      s.onerror = function () { нет(new Error("не загрузилась библиотека PDF")); };
      document.head.appendChild(s);
    });
  }

  function _вБазу64(буфер) {
    var строка = "", b = new Uint8Array(буфер);
    // По кускам, а не одним apply: у больших шрифтов разворачивание в
    // аргументы переполняет стек вызовов и падает без внятной причины.
    for (var i = 0; i < b.length; i += 8192) {
      строка += String.fromCharCode.apply(null, b.subarray(i, i + 8192));
    }
    return btoa(строка);
  }

  async function пдфГотов() {
    if (_пдфДок && _пдфШрифт) return;
    if (!_пдфДок) {
      await _грузитьСкрипт("/vendor/jspdf.umd.min.js");
      _пдфДок = (window.jspdf && window.jspdf.jsPDF) || window.jsPDF;
      if (!_пдфДок) throw new Error("библиотека PDF загрузилась, но не нашлась");
    }
    if (!_пдфШрифт) {
      var r = await fetch("/vendor/PTSans-Regular.ttf");
      if (!r.ok) throw new Error(T("шрифт не загрузился (") + r.status + ")");
      _пдфШрифт = _вБазу64(await r.arrayBuffer());
    }
  }

  /* Лист бумаги, который сам считает, где кончается страница.

     ПЕРЕНОСИМ САМИ. У jsPDF перенос по maxWidth не считает высоту: длинный
     кусок молча уезжает за нижний край и пропадает. Этот урок взят у
     АгриФореста вместе с библиотекой — там на нём споткнулись первыми. */
  function пдфЛист(doc) {
    var W = doc.internal.pageSize.getWidth();
    var H = doc.internal.pageSize.getHeight();
    var M = 16, y = M;

    function место(нужно) {
      if (y + нужно > H - M) { doc.addPage(); y = M; }
    }
    return {
      W: W, H: H, M: M,
      get y() { return y; },
      отступ: function (n) { y += n; },
      строка: function (текст, размер, цвет, шаг) {
        doc.setFontSize(размер || 10);
        doc.setTextColor(цвет === undefined ? 25 : цвет);
        var куски = doc.splitTextToSize(String(текст || ""), W - 2 * M);
        var h = шаг || (размер >= 14 ? 7 : 5);
        куски.forEach(function (ln) {
          место(h);
          doc.text(ln, M, y);
          y += h;
        });
      },
      черта: function () {
        место(4);
        doc.setDrawColor(210);
        doc.line(M, y, W - M, y);
        y += 4;
      },
      разрыв: function () { doc.addPage(); y = M; }
    };
  }

  function _датаДляИмени() {
    var d = new Date();
    function два(n) { return (n < 10 ? "0" : "") + n; }
    return d.getFullYear() + "-" + два(d.getMonth() + 1) + "-" + два(d.getDate());
  }

  /* Сохранить находки дела в PDF. */
  async function сохранитьНаходкиВPDF(варианты, кнопка) {
    var подпись = кнопка ? кнопка.textContent : "";
    if (кнопка) { кнопка.disabled = true; кнопка.textContent = T("Собираю…"); }
    try {
      await пдфГотов();
      var doc = new _пдфДок({ unit: "mm", format: "a4" });
      doc.addFileToVFS("PTSans.ttf", _пдфШрифт);
      doc.addFont("PTSans.ttf", "PTSans", "normal");
      doc.setFont("PTSans");
      var л = пдфЛист(doc);

      л.строка(state.caseTitle || "Дело", 15, 20, 8);
      л.строка(T("Найденное на витрине · ") + _датаДляИмени(), 9, 120);
      л.черта();
      л.отступ(2);

      варианты.forEach(function (o, i) {
        л.строка((i + 1) + ". " + (o.title || T("Без названия")), 12, 20, 6);
        /* Цена на БУМАГЕ. Лист уносят, показывают и по нему решают; не
           добавить её сюда значит отдать человеку в руки список без цен. */
        var ценаЛиста = ценаВарианта(o);
        if (ценаЛиста) л.строка(ценаЛиста, 11, 20, 5);
        if (o.summary) л.строка(o.summary, 10, 60);
        (o.evidence || []).forEach(function (e) {
          var src = String(e.source || "");
          if (src.indexOf("http") === 0) л.строка(src, 8, 90, 4);
        });
        var оговорки = o.unverified || [];
        if (оговорки.length) {
          л.строка("Чего мы не проверяли:", 9, 140, 4.4);
          оговорки.slice(0, 8).forEach(function (u) {
            л.строка("— " + u, 9, 140, 4.4);
          });
        }
        л.отступ(4);
      });

      // ОГОВОРКА В САМОМ ДОКУМЕНТЕ, а не только на экране. Лист уносят,
      // показывают и по нему решают; экран с пояснением остаётся здесь.
      л.отступ(3);
      л.черта();
      л.строка("Это объявления с витрины, а не проверенные предложения. Цены и " +
               "наличие подтверждает продавец. Фотографии — с сайтов продавцов.",
               8, 130, 4);

      doc.save(T("Находки-") + _датаДляИмени() + ".pdf");
    } catch (e) {
      сорвалось(T("PDF не собрался: "), e,
                T(". Найденное при этом цело — оно в деле, а не в файле."));
    } finally {
      if (кнопка) { кнопка.disabled = false; кнопка.textContent = T(подпись); }
    }
  }

  /* Сохранить разговор по делу в PDF. */
  async function сохранитьРазговорВPDF(кнопка) {
    var подпись = кнопка ? кнопка.textContent : "";
    if (кнопка) { кнопка.disabled = true; кнопка.textContent = T("Собираю…"); }
    try {
      var события = await api("GET", "/cases/" +
                              encodeURIComponent(state.caseId) + "/events");
      var реплики = (события || []).filter(function (e) {
        return e.kind === "dialog" && (e.payload || {}).text;
      });
      if (!реплики.length) {
        say("bot", "Ф", "В журнале этого дела реплик нет — сохранять нечего.");
        return;
      }
      await пдфГотов();
      var doc = new _пдфДок({ unit: "mm", format: "a4" });
      doc.addFileToVFS("PTSans.ttf", _пдфШрифт);
      doc.addFont("PTSans.ttf", "PTSans", "normal");
      doc.setFont("PTSans");
      var л = пдфЛист(doc);

      л.строка(state.caseTitle || "Дело", 15, 20, 8);
      л.строка(T("Разговор по делу · ") + _датаДляИмени(), 9, 120);
      л.черта();
      л.отступ(2);

      реплики.forEach(function (e) {
        var p = e.payload || {};
        var кто = p.role === "assistant" ? "Агент" : имяАвтора(e, p);
        л.строка(кто, 9, 120, 4.4);
        л.строка(p.text, 10, 25);
        л.отступ(3);
      });

      doc.save(T("Разговор-") + _датаДляИмени() + ".pdf");
    } catch (e) {
      сорвалось(T("PDF не собрался: "), e);
    } finally {
      if (кнопка) { кнопка.disabled = false; кнопка.textContent = T(подпись); }
    }
  }

  /* Как назвать ссылку варианта.

     «Карточка объявления» — обещание человеческой страницы, и оно сплошь и
     рядом ложно. Проверено на живом 23.08.2026: все шесть ссылок находок
     АгриФореста ведут на api.agriforest.online/api/listings/… — машинную
     ручку, отдающую JSON. Человек нажимает «карточка объявления», а получает
     9 килобайт машинного текста в новой вкладке.

     Человеческой страницы у этой витрины, похоже, нет вовсе: корень отвечает
     лендингом с якорями, отдельных адресов у лотов не видно, а угадывать
     /listing/{id} нельзя — оно отвечает 404, и выдуманный адрес хуже
     честного машинного.

     Поэтому подпись говорит правду о том, куда ведёт. Узнаём по адресу:
     хост, начинающийся с api., или путь с /api/ — машинная ручка. */
  function подписьСсылки(адрес) {
    var машинная = /^https?:\/\/api\./i.test(адрес) || /\/api\//.test(адрес);
    return машинная ? "данные объявления (машинный вид)" : "карточка объявления";
  }

  /* ЦЕНА ВАРИАНТА СТРОКОЙ. Число приезжает ЦЕЛЫМИ рублями, подпись
     основания («в месяц») — вместе с ним из базы: своего словаря денег здесь
     нет и не должно быть, он живёт в own_price_bases.

     Своё разделение разрядов, а НЕ `деньгами` (3047): та зовёт `human`,
     форматировщик БАЙТОВ, и показывает 8800 как «8.6 КБ ₽». Поломку не видно,
     потому что стенд подменяет `human` заглушкой String(n). Чинить её здесь,
     мимоходом, значило бы чинить вслепую. */
  function ценаВарианта(o) {
    if (o.price === null || o.price === undefined) return "";
    /* Тем же `деньгами`, что и цена объявления на доске. Своё разделение
       разрядов стояло здесь ровно сутки — пока `деньгами` мерил деньги
       байтами; держать его дальше значило бы завести вторую правду о том, как
       выглядит сумма, и однажды показать одно число двумя способами. */
    var хвост = o.price_title ? " " + o.price_title : "";
    return (деньгами(o.price, o.currency) + хвост).trim();
  }

  function карточкаВарианта(o) {
    var фото = (o.pictures || []).slice(0, 4).map(function (p) {
      var подпись = ОТКУДА_ФОТО[p.origin] || "происхождение не названо";
      /* Пометка стоит ПОД каждым снимком, а не одной строкой на карточку:
         у объявления бывает своё фото и типовое рядом, и общая подпись
         соврала бы про оба. loading=lazy — витрина отдаёт до четырёх
         снимков на карточку, и грузить их все разом незачем. */
      return '<figure class="ph"><img src="' + экранировать(p.url) +
             '" alt="" loading="lazy" referrerpolicy="no-referrer">' +
             '<figcaption>' + экранировать(подпись) + '</figcaption></figure>';
    }).join("");

    var оговорки = (o.unverified || []).slice(0, 6).map(function (u) {
      return "<li>" + экранировать(u) + "</li>";
    }).join("");

    var ссылка = "";
    (o.evidence || []).forEach(function (e) {
      if (!ссылка && String(e.source || "").indexOf("http") === 0) {
        ссылка = String(e.source);
      }
    });

    var цена = ценаВарианта(o);

    return '<article class="opt">' +
      '<h2>' + экранировать(o.title || T("Без названия")) + '</h2>' +
      (цена ? '<p class="prc">' + экранировать(цена) + '</p>' : "") +
      (o.summary ? '<p>' + экранировать(o.summary) + '</p>' : "") +
      (фото ? '<div class="phs">' + фото + '</div>' : "") +
      (ссылка ? '<p class="src"><a href="' + экранировать(ссылка) +
                '" target="_blank" rel="noopener noreferrer">' +
                экранировать(подписьСсылки(ссылка)) + '</a></p>' : "") +
      (оговорки ? T('<p class="cav">Чего мы не проверяли:</p><ul>') + оговорки + "</ul>" : "") +
      "</article>";
  }

  /* ═══ ЧАТ ВНУТРИ ХОЛСТА ═══════════════════════════════════════════════

     ВТОРАЯ ДВЕРЬ В ТОТ ЖЕ РАЗГОВОР, А НЕ ВТОРОЙ РАЗГОВОР. Спрошенное отсюда
     уходит той же функцией send, что и набранное в поле слева: реплика
     ложится в общую переписку, ход считается один раз, кредиты списываются
     один раз. Заведи полоса собственную историю — у человека оказалось бы
     две версии сказанного, и обе неполные; какая из них попала в журнал
     дела, он бы не узнал.

     ЗАЧЕМ ТОГДА ПОЛОСА, ЕСЛИ ПОЛЕ УЖЕ ЕСТЬ. Затем, что спрашивают ПРО
     КАРТОЧКИ: «а вторая тише?», «почему первая дороже». Чтобы задать этот
     вопрос в поле слева, надо увести глаза с того, о чём спрашиваешь, и
     назвать вариант словами вместо того, чтобы на него смотреть.

     CLICK, А НЕ SUBMIT — тот же довод, что записан в shared/panels.py:
     песочница без allow-forms гасит отправку формы ДО обработчика, и
     привычное движение молча не даёт ничего. Разрешение не выдаём
     намеренно: карточки собраны из чужих витрин, и единственным выходом
     наружу обязан остаться postMessage родителю.

     ЧЕГО В ПЕСОЧНИЦУ НЕ КЛАДЁМ. Обратно уходит только текст ответа — то,
     что человек и так читает в переписке. Ни токена, ни номера дела, ни
     чего-либо, чего он на экране не видит: содержимое холста собрано из
     чужого текста, и знать больше человека оно не должно. */

  var ЧАТ_СТИЛЬ =
    "#fxc{position:sticky;bottom:0;margin:18px -12px -12px;padding:10px 12px;" +
      "background:#fbf9f5;border-top:1px solid #e3ded2}" +
    "#fxl{max-height:150px;overflow:auto;margin:0 0 8px;font-size:13px}" +
    "#fxl:empty{display:none}" +
    "#fxl div{margin:0 0 6px;white-space:pre-wrap;overflow-wrap:break-word}" +
    "#fxl .u{color:#6b6355}" +
    "#fxl .e{color:#b3402a}" +
    "#fxr{display:flex;gap:8px}" +
    "#fxi{flex:1;min-width:0;padding:8px 10px;border:1px solid #d6cfc0;" +
      "border-radius:8px;font:inherit;background:#fff;color:inherit}" +
    "#fxb{padding:8px 14px;border:0;border-radius:8px;background:#1a1712;" +
      "color:#fff;font:inherit;cursor:pointer}" +
    "#fxb[disabled]{opacity:.5;cursor:default}";

  var ЧАТ_РАЗМЕТКА =
    "<div id=\"fxc\"><div id=\"fxl\"></div><div id=\"fxr\">" +
    "<input id=\"fxi\" autocomplete=\"off\" maxlength=\"2000\" " +
    /* Надписи виджета переводятся ПОДСТАНОВКОЙ ЗНАЧЕНИЯ, а не переводом
       куска кода: сам код английскому не подлежит, а эти два слова человек
       читает. Экранируем — значение попадает внутрь разметки. */
    "placeholder=\"" + экранировать(T("Спросить про эти варианты…")) + "\">" +
    "<button id=\"fxb\" type=\"button\">" + экранировать(T("Спросить"))
    + "</button></div></div>";

  /* Единственный скрипт, который в холсте исполняется, и он наш — как у
     панели. Собран строкой здесь, а не принесён откуда-то: всё, что модель
     или витрина могут дать, попадает на холст ТЕКСТОМ через карточки. */
  var ЧАТ_СКРИПТ =
    "<script>(function(){" +
    "var поле=document.getElementById('fxi')," +
    "кнопка=document.getElementById('fxb')," +
    "лента=document.getElementById('fxl');" +
    "function строка(вид,кто,текст){" +
      "var d=document.createElement('div');d.className=вид;" +
      "if(кто){var b=document.createElement('b');b.textContent=кто+': ';" +
      "d.appendChild(b);}" +
      // Ответ приходит из переписки и вставляется УЗЛОМ ТЕКСТА: что бы в нём
      // ни было, разметкой оно не станет.
      "d.appendChild(document.createTextNode(текст));" +
      "лента.appendChild(d);лента.scrollTop=лента.scrollHeight;}" +
    "function занято(на){кнопка.disabled=на;поле.disabled=на;" +
      /* JSON.stringify, а не кавычки руками: перевод попадает ВНУТРЬ кода
         виджета, и любая кавычка в нём порвала бы скрипт. */
      "кнопка.textContent=на?'…':" + JSON.stringify(T("Спросить")) + ";" +
      // Курсор возвращается СЮДА. send в своём finally уводит фокус в поле
      // слева — правильно для хода, набранного слева, и обидно для набранного
      // здесь: следующий вопрос человек начал бы печатать не в том окне.
      "if(!на)поле.focus();}" +
    "function спросить(){" +
      "var т=String(поле.value||'').trim();if(!т||кнопка.disabled)return;" +
      "поле.value='';строка('u'," + JSON.stringify(T("Вы")) + ",т);занято(true);" +
      "parent.postMessage({kind:'fixar.chat',text:т.slice(0,2000)},'*');}" +
    "кнопка.addEventListener('click',спросить);" +
    /* ССЫЛКА В ПЕСОЧНИЦЕ НЕ ОТКРЫВАЕТСЯ САМА, и это не наша ошибка, а
       устройство: у кадра sandbox="allow-scripts" БЕЗ allow-popups, поэтому
       браузер гасит переход молча. Человек видел текст ссылки, нажимал — и
       не происходило ничего.

       Разрешение мы НЕ выдаём: содержимое холста собрано из чужих витрин, и
       право открывать окна у него было бы правом уводить человека куда
       угодно. Вместо этого просим РОДИТЕЛЯ — тем же каналом, что и реплики
       чата, и он же решает, открывать ли и куда. */
    "document.addEventListener('click',function(e){" +
      "var a=e.target&&e.target.closest?e.target.closest('a[href]'):null;" +
      "if(!a)return;" +
      "e.preventDefault();" +
      "parent.postMessage({kind:'fixar.open',url:String(a.href||'').slice(0,2000)},'*');" +
    "});" +
    "поле.addEventListener('keydown',function(e){" +
      "if(e.key==='Enter'){e.preventDefault();спросить();}});" +
    "addEventListener('message',function(e){" +
      // Не от нашего родителя — не наше дело. Зеркало проверки, которая
      // стоит наверху: там e.source сверяют с кадром, здесь — с parent.
      "if(e.source!==parent)return;" +
      "var d=e.data;if(!d||typeof d!=='object')return;" +
      "if(d.kind==='fixar.reply'){занято(false);" +
      "строка('a',String(d.who||" + JSON.stringify(T("Агент"))
      + ").slice(0,40),String(d.text||''));}" +
      "else if(d.kind==='fixar.error'){занято(false);" +
      "строка('e','',String(d.text||''));}});" +
    "})();</script>";

  function холстВариантов(варианты) {
    var стиль =
      "body{font:14px/1.5 system-ui,sans-serif;margin:0;padding:12px;color:#1b1b1b;background:#fff}" +
      ".opt{border:1px solid #ddd;border-radius:8px;padding:12px;margin:0 0 14px}" +
      "h2{font-size:15px;margin:0 0 6px}" +
      "p{margin:0 0 8px}" +
      ".phs{display:flex;gap:8px;flex-wrap:wrap;margin:8px 0}" +
      ".ph{margin:0;width:150px}" +
      ".ph img{width:150px;height:104px;object-fit:cover;border-radius:6px;display:block;background:#f2f2f2}" +
      ".ph figcaption{font-size:11px;color:#666;margin-top:3px}" +
      ".src a{color:#0a58ca}" +
      ".prc{font-size:17px;font-weight:600;margin:2px 0 6px}" +
      ".cav{font-size:12px;color:#8a5a00;margin:8px 0 2px}" +
      "ul{margin:0;padding-left:18px;font-size:12px;color:#555}";
    return "<!doctype html><meta charset=\"utf-8\">" +
           "<style>" + стиль + ЧАТ_СТИЛЬ + "</style>" +
           варианты.map(карточкаВарианта).join("") +
           ЧАТ_РАЗМЕТКА + ЧАТ_СКРИПТ;
  }

  async function renderFinds() {
    var box = document.getElementById("finds");
    var list = document.getElementById("findlist");
    if (!box || !list) return;
    if (!state.caseId) { box.hidden = true; return; }

    var варианты = [];
    try {
      var d = await api("GET", "/cases/" + encodeURIComponent(state.caseId) + "/options");
      варианты = (d && (d.options || d)) || [];
      if (!Array.isArray(варианты)) варианты = [];
    } catch (e) {
      /* Раздел появляется вместе с находками. Молчать о СБОЕ нельзя, но и
         пугать пустой рамкой не за чем: если находок никогда не было,
         человек про раздел и не знает. */
      box.hidden = true;
      return;
    }
    // Отсеянное агентом не показываем как находку: оно уже отвергнуто, и
    // строка о нём читалась бы как предложение.
    варианты = варианты.filter(function (o) { return o && !o.rejected; });
    if (!варианты.length) { box.hidden = true; return; }
    box.hidden = false;

    list.innerHTML = "";
    var скартинками = 0;
    варианты.forEach(function (o) {
      if ((o.pictures || []).length) скартинками++;
      var row = el("div", "file1 can");
      row.appendChild(el("span", "fn", o.title || "Без названия"));
      var сколько = (o.pictures || []).length;
      if (сколько) row.appendChild(el("span", "fsz", сколько + T(" фото")));
      row.tabIndex = 0;
      row.setAttribute("role", "button");
      row.title = T("Открыть найденное на холсте");
      function открыть() {
        openCanvas({
          вид: "finds",
          title: "Найденное на витрине",
          откуда: "объявления, а не проверенные предложения",
          html: холстВариантов(варианты)
        });
      }
      row.addEventListener("click", открыть);
      row.addEventListener("keydown", function (e) {
        if (e.key === "Enter" || e.key === " ") { e.preventDefault(); открыть(); }
      });
      list.appendChild(row);
    });

    // Сохранение в PDF. Кнопка живёт рядом с находками, а не в общем месте:
    // сохраняют то, на что смотрят.
    var пдф = document.getElementById("findspdf");
    if (пдф) {
      пдф.onclick = function () { сохранитьНаходкиВPDF(варианты, пдф); };
    }

    /* Ни у одной находки нет фото — это про витрину, а не про нас, и сказать
       это лучше, чем оставить человека гадать, почему холст без картинок. */
    if (!скартинками) {
      list.appendChild(el("div", "fnote",
        "Фотографий у этих объявлений нет — витрина их не дала."));
    }
  }

  async function renderDocs() {
    var box = document.getElementById("docs");
    var list = document.getElementById("doclist");
    var head = document.getElementById("docshead");
    if (!box || !state.caseId || !state.principal) {
      if (box) box.hidden = true;
      return;
    }
    var проекты;
    try {
      проекты = (await api("GET", "/cases/" + encodeURIComponent(state.caseId) +
                           "/drafts")).drafts || [];
    } catch (e) {
      box.hidden = true;
      return;
    }
    if (!проекты.length) { box.hidden = true; return; }
    box.hidden = false;
    head.textContent = T(T("Документы: ") + проекты.length);
    list.innerHTML = "";

    var СОСТОЯНИЕ = { draft: "на рассмотрении", accepted: "принят",
                      rejected: "отклонён" };

    /* РОДОСЛОВНАЯ ПРАВОК.

       Правка документа на холсте заводит ОТДЕЛЬНЫЙ проект с parent_id на
       прежний — так устроена служба, и правильно устроена: подписанное под
       рукой не переписывают. Но список рисовался плоским по времени, и
       parent_id не читался ни разу. Человек правил договор, сохранял — и
       получал две строки с одинаковым названием, ничем не отличимые. Правка
       на холсте работала и выглядела как ошибка.

       Считаем ветку от корня и расставляем: за каждым корнем сразу его
       правки. Ветвление НЕ считаем ошибкой и не прячем — служба его
       позволяет намеренно (двое правят от одного текста), и человек должен
       про это знать здесь, а не через неделю. */
    var поИд = {};
    проекты.forEach(function (d) { поИд[d.id] = d; });
    function родитель(d) {
      var p = d.parent_id ? поИд[d.parent_id] : null;
      return p === d ? null : p;          // сам себе родителем быть не может
    }
    var правок = {};                       // сколько правок пошло от документа
    проекты.forEach(function (d) {
      var p = родитель(d);
      if (p) правок[p.id] = (правок[p.id] || 0) + 1;
    });
    function ступень(d) {
      // Глубина от корня. Счётчик шагов — страховка от кольца в данных:
      // молчаливый вечный цикл здесь стоил бы человеку зависшей вкладки.
      var n = 0, т = d, шагов = 0;
      while (родитель(т) && шагов++ < 200) { т = родитель(т); n += 1; }
      return n;
    }
    function корень(d) {
      var т = d, шагов = 0;
      while (родитель(т) && шагов++ < 200) т = родитель(т);
      return т.id;
    }
    // Порядок службы (свежие выше) сохраняем МЕЖДУ ветками, а внутри ветки
    // идём от корня к правкам: иначе правка стоит выше того, что правили.
    var порядокКорней = [];
    проекты.forEach(function (d) {
      var к = корень(d);
      if (порядокКорней.indexOf(к) < 0) порядокКорней.push(к);
    });
    var разложены = [];
    порядокКорней.forEach(function (к) {
      проекты.filter(function (d) { return корень(d) === к; })
        .sort(function (a, b) { return ступень(a) - ступень(b); })
        .forEach(function (d) { разложены.push(d); });
    });

    разложены.forEach(function (d) {
      var row = el("div", "doc1");
      var шаг = ступень(d);
      if (шаг) row.classList.add("docrev");
      var имя = el("span", "dn", d.title || "Документ");
      имя.style.cursor = "pointer";
      имя.title = T("Открыть на холсте");
      имя.addEventListener("click", function () {
        /* Панель — не текст, и править её как текст нельзя: человек увидел бы
           разметку вместо формы и «исправил» бы её в мусор. Открывается она
           живой, в песочнице, и сохранять в ней нечего. */
        if ((d.kind || "") === "panel") {
          openCanvas({
            вид: "panel", id: d.id, title: d.title || "Форма",
            html: d.body || "", правится: false,
            откуда: "форма · составил агент",
            подпись: "Заполненное попадёт в поле ввода — вы увидите его прежде, "
                   + "чем отправите. Сама форма никуда ничего не шлёт."
          });
          return;
        }
        openCanvas({
          вид: "draft", id: d.id, title: d.title || "Документ",
          text: d.body || "", kind: d.kind || "",
          // Принятый и отданный клиенту не правится на месте: под ним уже
          // подписались. Правка заведёт отдельный документ — это видно.
          правится: d.state !== "rejected",
          откуда: T("проект · ") + (d.source === "human" ? T("составлен вами")
                                                      : T("составлен агентом")),
          родословная: T("правка проекта ") + d.id,
          подпись: (d.gaps || []).length
            ? T("В проекте не заполнено: ") + d.gaps.join("; ")
            : "Правка сохранится ОТДЕЛЬНЫМ документом; этот останется на месте."
        });
      });
      row.appendChild(имя);
      /* Чем эта строка приходится соседним. Ставим ПЕРЕД состоянием: сперва
         «какая это версия», потом «что с ней решили» — иначе две одинаково
         названные строки читаются как две разные бумаги. */
      if (шаг) {
        var чей = поИд[d.parent_id];
        var метка = el("span", "drev", T("правка ") + шаг +
          (правок[d.id] ? "" : " · " + T("последняя")));
        метка.title = T("Правка проекта «") + ((чей && чей.title) || "?") + "»";
        row.appendChild(метка);
      } else if (правок[d.id]) {
        row.appendChild(el("span", "drev", T("исходный")));
      }
      // Ветвление называем вслух: служба его позволяет, слить не берётся
      // никто, и узнать об этом через неделю хуже, чем сейчас.
      if (правок[d.id] > 1) {
        row.appendChild(el("span", "drev dfork",
          T("веток: ") + правок[d.id]));
      }
      /* ОТКУДА ЭТО ВЗЯТО — четвёртая строка карточки-цитаты, и до 28.08.2026
         она была обещанием без механизма: во всей оболочке не было ни одного
         «#page=», а нажатие на имя бумаги открывало разобранный текст.

         Ссылку строим ИЗ ЗАПИСИ, а не разбирая фразу основания. Фраза
         («дословно из vypiska.pdf, стр. 2») остаётся для чтения и для
         выгрузки; разбирать её обратно значило бы завести вторую правду об
         одном — сервер собирает, оболочка разбирает, и однажды они разойдутся.

         Запись есть тогда и только тогда, когда строка НАЙДЕНА в бумаге
         дословно: сверка идёт на сервере до записи патча, а не подтвердившаяся
         цитата записью не становится вовсе — она названа в пропусках. */
      var ссылка = d.cite && d.cite.material_id ? d.cite : null;
      if (ссылка) {
        var откуда = el("button", "addone dcite",
          T("дословно") + " · " + (ссылка.title || T("бумага")) +
          (ссылка.page ? " · " + T("стр. ") + ссылка.page
                       : " · " + T("страницы не размечены")));
        откуда.type = "button";
        откуда.title = (ссылка.quote ? "«" + ссылка.quote + "»\n\n" : "") +
          T("Открыть исходный файл") +
          (ссылка.page ? T(" на этой странице") : "") +
          (ссылка.through_boundary
            ? T(". Цитата переходит на следующую страницу.") : ".");
        откуда.addEventListener("click", function () {
          // Вид файла здесь неизвестен, и спрашивать его отдельным запросом
          // незачем: открытьИсходник сам скажет, если показать не сможет.
          открытьИсходник({ id: ссылка.material_id, title: ссылка.title,
                            mime: "application/pdf" }, ссылка.page || 0);
        });
        row.appendChild(откуда);
      }
      row.appendChild(el("span", "dst",
        d.shared ? "выдан" : (СОСТОЯНИЕ[d.state] || d.state)));

      var скачать = el("button", "addone dget", "Скачать");
      скачать.type = "button";
      скачать.addEventListener("click", function () {
        // ТОКЕН ДВЕРИ НУЖЕН. Прежний комментарий здесь утверждал обратное —
        // «файл отдаёт дверь с подставленным субъектом, и токен в адресе ей
        // не нужен», — и это неправда: субъекта дверь подставляет ИЗ токена,
        // а переход верхнего уровня заголовка Authorization не несёт. Дверь
        // отвечала 401, вкладка показывала JSON с отказом. Вторая такая же
        // кнопка была в холсте; чинить надо обе, иначе половина документов
        // качается, а половина нет.
        скачатьЧерезДверь("/drafts/" + encodeURIComponent(d.id) + "/file?fmt=rtf",
                          (d.title || T("документ")) + ".rtf");
      });
      row.appendChild(скачать);

      /* РЕШЕНИЕ ПО ПРОЕКТУ. Ручка `/drafts/{id}/decide` была построена и не
         вызывалась ниоткуда: состояние проекта навсегда оставалось
         «на рассмотрении», а «Отдать клиенту» — недостижимой, потому что она
         показывается только принятому.

         Два решения разведены намеренно и идут по возрастанию цены: взять в
         работу — своё дело; отдать клиенту — уже наружу. Слить их в одну
         кнопку значило бы отдать доверителю то, что юрист только что увидел
         впервые. */
      if (d.state === "draft") {
        var вработу = el("button", "addone dget", "Взять в работу");
        вработу.type = "button";
        вработу.addEventListener("click", async function () {
          вработу.disabled = true;
          try {
            await api("POST", "/drafts/" + encodeURIComponent(d.id) + "/decide",
                      { state: "accepted" });
            await renderDocs();
          } catch (e) {
            вработу.disabled = false;
            list.appendChild(el("div", "fnote", "Не вышло: " + reason(e)));
          }
        });
        row.appendChild(вработу);

        var отклонить = el("button", "addone danger", "Отклонить");
        отклонить.type = "button";
        отклонить.addEventListener("click", async function () {
          // ПРИЧИНА ОБЯЗАТЕЛЬНА, и это требование службы, а не вежливость:
          // отклонённый проект остаётся в деле, и через месяц «отклонён» без
          // причины не отвечает, чем он был плох и стоит ли просить снова.
          var почему = window.prompt(
            "Чем проект не годится? Причина останется в деле рядом с ним.");
          if (почему === null) return;
          почему = String(почему).trim();
          if (!почему) {
            list.appendChild(el("div", "fnote",
              "Без причины не отклоняю: через месяц «отклонён» сам по себе " +
              "ничего не объяснит."));
            return;
          }
          отклонить.disabled = true;
          try {
            await api("POST", "/drafts/" + encodeURIComponent(d.id) + "/decide",
                      { state: "rejected", note: почему });
            await renderDocs();
          } catch (e) {
            отклонить.disabled = false;
            list.appendChild(el("div", "fnote", "Не вышло: " + reason(e)));
          }
        });
        row.appendChild(отклонить);
      }

      // Отдать клиенту может только тот, кому служба показала непринятое:
      // у участника таких проектов в списке не будет вовсе.
      if (d.state === "accepted" && !d.shared) {
        var отдать = el("button", "addone dget", "Отдать клиенту");
        отдать.type = "button";
        отдать.addEventListener("click", async function () {
          отдать.disabled = true;
          try {
            await api("POST", "/drafts/" + encodeURIComponent(d.id) + "/share", {});
            await renderDocs();
          } catch (e) {
            отдать.disabled = false;
            list.appendChild(el("div", "fnote", T("Не отдалось: ") + reason(e)));
          }
        });
        row.appendChild(отдать);
      }
      list.appendChild(row);

      if ((d.gaps || []).length) {
        list.appendChild(el("div", "dgaps",
          T("Не заполнено: ") + d.gaps.join("; ")));
      }
      if (d.state === "rejected" && d.reject_note) {
        list.appendChild(el("div", "fnote", T("Отклонён: ") + d.reject_note));
      }
    });
  }

  /* Браузер читает файл в base64: тело ручки — JSON, и другого способа
     положить в него байты нет. readAsDataURL отдаёт «data:тип;base64,…» —
     заголовок отрезаем, служба ждёт только сами байты. */
  function readB64(file) {
    return new Promise(function (resolve, reject) {
      var fr = new FileReader();
      fr.onerror = function () {
        reject(new Error("браузер не смог прочитать файл"));
      };
      fr.onload = function () {
        var s = String(fr.result || "");
        var i = s.indexOf(",");
        resolve(i < 0 ? s : s.slice(i + 1));
      };
      fr.readAsDataURL(file);
    });
  }

  async function attachOne(file) {
    // Имя и размер видны ДО отправки: узнать, что послал не тот файл, уже
    // после отправки — значит узнать поздно.
    var row = el("div", "filerow");
    row.appendChild(el("span", "fn", file.name || "без имени"));
    row.appendChild(el("span", "fsz", human(file.size)));
    var st = el("span", "fst", "готовлю…");
    row.appendChild(st);
    log.appendChild(row);
    log.scrollTop = log.scrollHeight;

    if (file.size > MAX_FILE) {
      row.className = "filerow bad";
      st.textContent = T(T("больше предела ") + human(MAX_FILE) + T(" — не отправляю"));
      return false;
    }

    var b64;
    try {
      st.textContent = T("читаю…");
      b64 = await readB64(file);
    } catch (e) {
      row.className = "filerow bad";
      st.textContent = T(e.message);
      return false;
    }

    try {
      st.textContent = T("отправляю…");
      var r = await api("POST", "/vault/documents", {
        title: file.name || "Без названия",
        content_b64: b64,
        // Тип берёт браузер. У файла без расширения его не будет — и
        // выдумывать тип за него мы не станем.
        mime: file.type || "application/octet-stream",
        kind: "file",
        // Владельца подставляет шлюз: назвать его самим собой значит дать
        // возможность назвать чужого.
        source_case_id: state.caseId
      });
      // Байты остались в личном хранилище — там им и место: дело кончится, а
      // договор человеку ещё понадобится. Делу достаётся ссылка, и с ней файл
      // становится материалом дела, а не просто файлом рядом с ним. Без этого
      // раздел «Приложенное к делу» показывал файл, о котором ни журнал дела,
      // ни агент не знали ничего.
      var known = false;
      // ИДЕНТИФИКАТОР ЛЕЖИТ ВНУТРИ document, А НЕ СВЕРХУ. Здесь читали `r.id`
      // — поля, которого хранилище не отдаёт ни в одной ветке ответа, — и
      // ссылка выходила буквальной строкой "vault:undefined". Обходчик цеплял
      // такой материал по LIKE 'vault:%', получал от хранилища 404 и навсегда
      // метил его failed. На проде так побились ВСЕ файлы, приложенные из
      // браузера: два материала из шести, оба failed. Проверено запросом.
      var докид = (r && r.document && r.document.id) || "";
      if (!докид) {
        // Молчаливое "undefined" в ссылке хуже отсутствия ссылки: файл
        // выглядит приложенным и не читается никогда.
        throw new Error("хранилище не назвало идентификатор документа");
      }
      try {
        await api("POST", "/cases/" + state.caseId + "/materials", {
          kind: (file.type || "").indexOf("image/") === 0 ? "image" : "file",
          mime: file.type || "application/octet-stream",
          title: file.name || "Без названия",
          storage_ref: "vault:" + докид
        });
        known = true;
        // Бумаг стало больше — список обновляем здесь, где они и меняются.
        // Разобранной она станет позже: разбор идёт обходчиком, и до него
        // строка честно скажет «ещё не разобрана».
        await renderPapers();
        // И общий короб: без этого он держит «пока пусто» над строкой,
        // которая только что появилась.
        renderArtifacts();
      } catch (e3) {
        // Файл уже в хранилище и не потерян — молчать об этом нельзя, но и
        // выбрасывать его незачем.
        known = false;
      }
      // Разбор идёт фоновым обходом, а не в этом запросе: у скана с OCR он
      // занимает минуты, и держать ради него человека у экрана незачем.
      // Поэтому здесь сказано «встал в очередь», а настоящее состояние
      // приходит из материалов дела (renderFiles) — оно и есть правда.
      // ТОТ ЖЕ ИДЕНТИФИКАТОР, ЧТО ВЫШЕ, И ЭТО ВТОРОЕ МЕСТО ТОЙ ЖЕ ОШИБКИ.
      // 21.08.2026 чинили `r.id` в вызове материалов — и остановились на нём,
      // хотя восемью строками выше собственный комментарий объясняет, почему
      // поля `r.id` не существует. Отсюда `f.id` уезжает в partsOf и строит
      // `vault:undefined` для КАЖДОГО файла, приложенного в чате: путь другой,
      // ошибка та же, и починка одного места оставила второе живым.
      pendingFiles.push({ id: докид, name: file.name || "без имени",
                          mime: file.type || "", known: known });
      st.textContent = T(known
        ? "приложено к делу — текст извлекается, это займёт минуту"
        : "сохранено в хранилище, но к делу не привязалось");
      return true;
    } catch (e2) {
      row.className = "filerow bad";
      if (нуженВход(e2)) {
        row.className = "filerow";
        позватьПодтвердиться(st);
        return false;
      }
      // ОТКАЗ ПО ВЫБОРУ ЧЕЛОВЕКА — не поломка, и повторять нечего. Он выбрал
      // «только на устройстве», и служба честно перестала принимать файлы.
      // Показать здесь «не загрузилось» без объяснения значило бы оставить
      // человека думать, что у нас неисправность, и жать снова.
      var д = (e2 && e2.data && e2.data.detail) || {};
      if (e2.status === 409 && д.reason === "storage_is_device_only") {
        row.className = "filerow";
        st.textContent = T("не принимаем: вы выбрали «только на устройстве»");
        say("bot", "Ф", д.message || "Схема хранения не даёт нам принять файл.");
        return false;
      }
      st.textContent = T(T("не загрузилось: ") + reason(e2));
      return false;
    }
  }

  async function attach(files) {
    var list = Array.prototype.slice.call(files || []);
    if (!list.length) return;
    if (!state.caseId) {
      // Молча завести дело ради файла нельзя: дело — это то, о чём человек
      // сказал, а не побочный след загрузки. Он потом не узнает своё дело
      // по названию «скан_2.pdf».
      say("bot", "Ф", "Приложить некуда: дело не выбрано. Откройте его в " +
          "списке справа — или напишите в двух словах, о чём оно, и файлу " +
          "будет к чему приложиться.");
      return;
    }
    var any = false;
    for (var i = 0; i < list.length; i++) {
      if (await attachOne(list[i])) any = true;
    }
    if (any) await renderFiles();
  }

  function setupFiles() {
    var picker = document.getElementById("file");

    function hasFiles(e) {
      var t = e.dataTransfer && e.dataTransfer.types;
      return !!t && Array.prototype.indexOf.call(t, "Files") >= 0;
    }

    if (picker) {
      picker.addEventListener("change", function () {
        // Список забираем ДО обнуления: обнуление поля стирает и его. А
        // обнулить надо, иначе повторный выбор того же файла не даёт события
        // change, и кнопка выглядит сломанной.
        var chosen = Array.prototype.slice.call(picker.files || []);
        picker.value = "";
        attach(chosen);
      });
    }

    // Перетаскивание. Подсветка обязательна: без неё файл отпускают наугад и
    // не понимают, попали или нет.
    var depth = 0;
    function over(e) {
      if (!hasFiles(e)) return;
      e.preventDefault();
      log.classList.add("drop");
    }
    log.addEventListener("dragenter", function (e) { depth++; over(e); });
    log.addEventListener("dragover", over);
    log.addEventListener("dragleave", function () {
      // dragleave приходит и при переходе на вложенный узел, поэтому считаем
      // входы и выходы: иначе подсветка гаснет на первом же слове в пузыре.
      depth--;
      if (depth <= 0) { depth = 0; log.classList.remove("drop"); }
    });
    log.addEventListener("drop", function (e) {
      e.preventDefault();
      depth = 0;
      log.classList.remove("drop");
      attach(e.dataTransfer && e.dataTransfer.files);
    });

    // Файл, отпущенный мимо, браузер откроет ВМЕСТО страницы — и разговор с
    // экрана исчезнет. Поэтому перехватываем всё окно, а не только разговор,
    // и говорим, куда его отпустить.
    document.addEventListener("dragover", function (e) {
      if (hasFiles(e)) e.preventDefault();
    });
    document.addEventListener("drop", function (e) {
      if (!hasFiles(e)) return;
      e.preventDefault();
      if (log.contains(e.target)) return;   // это уже принято разговором
      say("bot", "Ф", "Файл нужно отпустить на разговоре — он приложится к " +
          "открытому делу. Или возьмите скрепку рядом с полем ввода.");
    });
  }

  /* ── Коворкинг: кто в деле и на каких условиях ────────────────────── */

  /* ── Роды сведений, словами ─────────────────────────────────────────

     Пяти уровней чувствительности не было названо ни разу за всю жизнь
     продукта: в коде они английские значения, а наружу не выходили вовсе,
     потому что каждая бумага лежала «обычной». Эти пять слов становятся
     словами продукта — их прочтёт психолог, решая, показывать ли выписку
     помощнику, и юрист, зовя коллегу в дело.

     Поэтому здесь названо не «что за код», а ЧТО ЭТО ЗНАЧИТ для человека, и
     примером, а не определением: определение прочитают невнимательно, пример
     узнают. Порядок — от самого частого к редкому, а не по строгости:
     строгости между ними нет, они несравнимы. */
  var РОДА = [
    { key: "normal",    title: "Обычное",
      what: "переписка, фотографии, всё, что не из списка ниже" },
    { key: "pii",       title: "Личные данные",
      what: "паспорт, СНИЛС, адрес, телефон" },
    { key: "medical",   title: "Медицинское",
      what: "диагнозы, выписки, назначения, записи сеанса" },
    { key: "financial", title: "Денежное",
      what: "счета, выписки, реквизиты, договоры займа" },
    { key: "legal",     title: "Правовое",
      what: "договоры, иски, доверенности, судебное" }
  ];

  /* ОТКУДА ВЗЯЛСЯ РОД. «Обычная» без этого значит сразу две разные вещи —
     «решено, что обычная» и «никто никогда не спрашивал», — и человеку, у
     которого бумага пропала из списка, ответить нечем.

     Значение приезжает из базы с 21.08, но до человека не доходило: у модели
     материала поля не было вовсе. */
  var ОТКУДА_РОД = {
    legacy: "досталось от старых записей — это не решение",
    "default": "никто не назвал: ни направление, ни текст",
    pack: "объявлено направлением",
    guess: "выведено из текста при разборе — грубо и намеренно широко",
    human: "названо человеком"
  };

  /* Правка рода — то самое недостающее «названо человеком».

     Писателей рода было три, и все машинные; значение human оборонялось в
     трёх местах и было закреплено тестами — защита значения, которое никто
     не мог поставить. Значит ЛЮБАЯ ошибка в роде была неисправима, а ошибка
     здесь особенная: роды несравнимы, и неверная метка не «закрывает
     лишнее», а отдаёт бумагу другой аудитории.

     Ставим на КАЖДУЮ строку, а не только на непростую. Довод про «обычное не
     подписываем» — про подпись, которой нечего сказать; здесь же действие, и
     ему всегда есть что сделать: поднять род у бумаги, которую машина сочла
     обычной, можно только отсюда. Держим тихим: мелкая кнопка у края. */
  function правкаРода(m, перерисовать) {
    var кнопка = el("button", "sensedit");
    кнопка.type = "button";
    кнопка.textContent = T("род…");
    кнопка.title = T("Назвать род сведений в этой бумаге");
    кнопка.addEventListener("click", function () {
      var выбор = document.createElement("select");
      выбор.className = "senspick";
      РОДА.forEach(function (р) {
        var o = document.createElement("option");
        o.value = р.key;
        o.textContent = T(р.title + " — " + р.what);
        if (р.key === (m.sensitivity || "normal")) o.selected = true;
        выбор.appendChild(o);
      });
      кнопка.replaceWith(выбор);
      выбор.focus();
      var ушло = false;
      выбор.addEventListener("change", async function () {
        if (ушло) return;
        ушло = true;
        выбор.disabled = true;
        try {
          await api("PUT", "/cases/" + encodeURIComponent(state.caseId) +
                    "/materials/" + encodeURIComponent(m.id) + "/sensitivity",
                    { sensitivity: выбор.value });
          // Род решает, кто бумагу видит: сказать об этом вслух обязательно,
          // иначе бумага молча пропадёт у части участников.
          say("bot", "Ф", T("Род бумаги «") + (m.title || m.id) + T("» назван: ") +
              родСловом(выбор.value) + T(". Это решает, кто её видит, и записано " +
              "в журнал дела."));
          if (перерисовать) перерисовать();
        } catch (e) {
          выбор.replaceWith(кнопка);
          сорвалось(T("Род поменять не вышло: "), e, T(". Бумага цела, род прежний."));
        }
      });
      // Ушёл, не выбрав — возвращаем кнопку, а не оставляем открытый список.
      выбор.addEventListener("blur", function () {
        if (!ушло && выбор.parentNode) выбор.replaceWith(кнопка);
      });
    });
    return кнопка;
  }

  function родСловом(ключ) {
    for (var i = 0; i < РОДА.length; i++) {
      if (РОДА[i].key === ключ) return РОДА[i].title;
    }
    // Незнакомое значение показываем как есть: выдумать ему название значит
    // однажды показать человеку «Обычное» там, где на деле лежит другое.
    return ключ || "";
  }

  var TERMS = [
    { key: "paid",      title: "За деньги",   why: "вам платят за участие" },
    { key: "volunteer", title: "По доброй воле", why: "бесплатно" },
    { key: "partner",   title: "В долю",      why: "общий интерес, не оплата" }
  ];
  var termSel = "volunteer";

  function renderCrew(participants) {
    var crew = document.getElementById("crew");
    var list = document.getElementById("crewlist");
    crew.hidden = false;
    list.innerHTML = "";
    (participants || []).forEach(function (p) {
      var row = el("div", "who1");
      row.appendChild(el("span", "nm",
        p.principal_id === state.principal
          ? "вы"
          : (p.display_name || (p.principal_id.slice(0, 12) + "…"))));
      row.appendChild(el("span", "rl", p.role));
      // ЧТО ЧЕЛОВЕК ВИДИТ В ДЕЛЕ. Позвали юриста ради договора, а он его не
      // видит, — и понять это было нельзя ниоткуда: список бумаг у него
      // просто короче, без объяснения. Строка состава — единственное место,
      // где это можно сказать заранее.
      var видит = (p.may_see || []).filter(function (у) { return у !== "normal"; });
      var метка;
      if (видит.length) {
        метка = el("span", "see", T("видит: ") + видит.map(родСловом).join(", "));
      } else {
        метка = el("span", "see dim", "только обычное");
        метка.title = T("Личных, медицинских, денежных и правовых бумаг дела " +
                      "этот человек не видит.");
      }
      // ПОМЕНЯТЬ МОЖНО. Пока было нельзя, лечение выглядело так: удалить
      // участника и позвать заново. Себе не меняем: круг своего видимого
      // расширить себе же значило бы обойти того, кто его назначал.
      if (p.principal_id !== state.principal) {
        метка.classList.add("edit");
        метка.tabIndex = 0;
        метка.title = T((метка.title ? метка.title + " " : "") + T("Нажмите, чтобы изменить."));
        var менять = function () { правитьВидимое(p); };
        метка.addEventListener("click", менять);
        метка.addEventListener("keydown", function (e) {
          if (e.key === "Enter" || e.key === " ") { e.preventDefault(); менять(); }
        });
      }
      row.appendChild(метка);
      var eng = el("span", "eng " + (p.engagement || "owner"));
      eng.appendChild(el("span", "dot"));
      eng.appendChild(el("span", null, {
        owner: "владелец", paid: "за деньги",
        volunteer: "по доброй воле", partner: "в долю"
      }[p.engagement] || p.engagement));
      row.appendChild(eng);
      if (p.terms_note) row.appendChild(el("span", "note", p.terms_note));
      list.appendChild(row);
    });
  }

  /* Что увидит приглашённый. Пусто — только обычное, и это правильное
     умолчание: закрытое. Выбор нужен потому, что без него юрист, позванный
     ради договора, договора и не видел — а понять это было нельзя ниоткуда. */
  var выбраноВидеть = [];

  /* Изменить круг видимого у участника. Отдельным действием, а не тихой
     правкой: расширение круга видящих отдаёт чужую тайну новому глазу, и у
     этого обязаны быть автор и время — служба пишет событие в журнал дела. */
  async function правитьВидимое(участник) {
    var было = (участник.may_see || []).filter(function (у) { return у !== "normal"; });
    var список = РОДА.filter(function (р) { return р.key !== "normal"; });
    var подсказка = список.map(function (р, i) {
      return (i + 1) + " — " + р.title + (было.indexOf(р.key) >= 0 ? T(" (сейчас видит)") : "");
    }).join("\n");
    var ответ = window.prompt(
      T("Что этот человек видит в деле, кроме обычного?\n\n") + подсказка +
      T("\n\nЧерез запятую, или пусто — только обычное:"),
      было.map(function (к) {
        return String(список.map(function (р) { return р.key; }).indexOf(к) + 1);
      }).join(","));
    if (ответ === null) return;
    var выбрано = [];
    ответ.split(",").forEach(function (ч) {
      var i = parseInt(ч.trim(), 10) - 1;
      if (i >= 0 && i < список.length && выбрано.indexOf(список[i].key) < 0) {
        выбрано.push(список[i].key);
      }
    });
    try {
      await api("PUT", "/cases/" + encodeURIComponent(state.caseId) +
                "/participants/" + encodeURIComponent(участник.principal_id) +
                "/may-see", { may_see: ["normal"].concat(выбрано) });
    } catch (e) {
      сорвалось(T("Изменить не вышло: "), e);
      return;
    }
    var дело = await api("GET", "/cases/" + encodeURIComponent(state.caseId));
    state.caseParticipants = дело.participants || [];
    renderCrew(дело.participants);
    // Список бумаг у этого человека изменился — но видит его он, не мы.
    // Себе перерисовываем состав, ему скажет его же экран при следующем заходе.
  }

  function рисоватьВыборВидимого() {
    var место = document.getElementById("invitesee");
    if (!место) return;
    место.innerHTML = "";
    РОДА.forEach(function (р) {
      if (р.key === "normal") return;   // обычное видно всегда, выбирать нечего
      var кн = el("button", "seeone" +
                  (выбраноВидеть.indexOf(р.key) >= 0 ? " on" : ""), р.title);
      кн.type = "button";
      // Что именно попадает в этот род — рядом, а не в справке: человек
      // решает, показывать ли чужую тайну, и решает один раз.
      кн.title = T(р.what);
      кн.addEventListener("click", function () {
        var i = выбраноВидеть.indexOf(р.key);
        if (i >= 0) выбраноВидеть.splice(i, 1);
        else выбраноВидеть.push(р.key);
        рисоватьВыборВидимого();
      });
      место.appendChild(кн);
    });
  }

  function setupCrew() {
    var btn = document.getElementById("addone");
    var form = document.getElementById("inviteform");
    var terms = document.getElementById("terms");
    var pay = document.getElementById("invitepay");
    var out = document.getElementById("invited");

    btn.addEventListener("click", function () {
      form.hidden = !form.hidden;
      if (!form.hidden) рисоватьВыборВидимого();
      if (form.hidden) return;
      terms.innerHTML = "";
      TERMS.forEach(function (t) {
        var b = el("button", "pill" + (termSel === t.key ? " on" : ""));
        b.type = "button";
        b.appendChild(el("span", null, t.title));
        b.title = T(t.why);
        b.addEventListener("click", function () {
          termSel = t.key;
          // Оплата названа отдельным полем: «платный участник» без ответа,
          // чем именно платят, — это видимость раскрытия, а не раскрытие.
          pay.hidden = termSel !== "paid";
          setupCrewTerms();
        });
        terms.appendChild(b);
      });
      pay.hidden = termSel !== "paid";
    });

    function setupCrewTerms() {
      Array.prototype.forEach.call(terms.children, function (b, i) {
        b.className = "pill" + (TERMS[i].key === termSel ? " on" : "");
      });
    }

    form.addEventListener("submit", async function (e) {
      e.preventDefault();
      if (!state.caseId) return;
      var body = {
        engagement: termSel,
        note: document.getElementById("invitenote").value.trim(),
        terms_note: pay.value.trim()
      };
      // Кто платит — сам зовущий: платить может только участник дела.
      if (termSel === "paid") body.paid_by = state.principal;
      // ЧТО ОН УВИДИТ. Обычное всегда — иначе позванный не увидит вообще
      // ничего и не поймёт, зачем его звали.
      body.may_see = ["normal"].concat(выбраноВидеть.slice());
      /* Срок участия — НЕ срок ссылки, и это разные вещи.
         Ссылка живёт трое суток (ttl_hours на стороне службы), а участие —
         до выезда, до сдачи, до выписки. Жилец получает ссылку за месяц до
         заезда: ссылка протухнет за трое суток, а участие продлится неделю.
         Пусто — бессрочно, и это большинство приглашений. */
      var досрок = document.getElementById("invitetill");
      if (досрок && досрок.value) {
        // Конец дня, а не полночь начала: «участвует до седьмого» человек
        // понимает как «седьмое включительно», и отобрать доступ утром
        // седьмого значило бы обмануть его же словами.
        body.participate_until = досрок.value + "T23:59:59Z";
      }
      try {
        var r = await api("POST", "/cases/" + state.caseId + "/invites", body);
        out.hidden = false;
        out.innerHTML = "";
        out.appendChild(el("div", null,
          T("Ссылка готова. Приглашённый увидит: «") + r.what_they_will_see +
          T("». Названия дела в ссылке нет.")
          + (body.participate_until
             ? T(" Участие закончится ") + досрок.value + T(" само — выводить не надо.")
             : "")));
        var link = location.origin + "/?invite=" + encodeURIComponent(r.code);
        out.appendChild(el("code", null, link));
        form.hidden = true;
      } catch (e2) {
        out.hidden = false;
        out.textContent = T(T("Не вышло: ") + e2.message);
      }
    });
  }

  /* Пришли по приглашению — показываем условия ДО согласия. */
  async function maybeInvite() {
    var code = new URLSearchParams(location.search).get("invite");
    if (!code) return false;
    try {
      var inv = await (await fetch(API + "/invites/" + encodeURIComponent(code))).json();
      if (inv.detail) throw new Error(inv.detail);
      var box = el("div", "ways");
      box.appendChild(el("div", "wayshead", "Вас зовут в дело"));
      var c = el("button", "way");
      c.type = "button";
      var t = el("div", "waytop");
      t.appendChild(el("div", "wayname", inv.terms));
      t.appendChild(el("div", "waygo", "→"));
      c.appendChild(t);
      if (inv.note) c.appendChild(el("div", "waysum", inv.note));
      var d = el("div", "disclose");
      d.appendChild(el("span", "dot" + (inv.engagement === "paid" ? " paid" : "")));
      d.appendChild(el("span", null, T("роль: ") + inv.role +
        T(" · права: ") + (inv.rights || []).join(", ")));
      if (inv.terms_note) d.appendChild(el("span", null, "· " + inv.terms_note));
      d.appendChild(el("span", null, "· " + inv.what_it_is));
      c.appendChild(d);
      // Что понадобится, чтобы вести это как РАБОТУ, — до согласия, а не
      // после. Иначе специалист соглашается, а преграду встречает на первом
      // же документе.
      if (inv.to_take_as_work) {
        c.appendChild(el("div", "waysum", inv.to_take_as_work));
      }
      c.addEventListener("click", async function () {
        try {
          await api("POST", "/invites/" + encodeURIComponent(code) + "/accept", {});
          box.remove();
          say("bot", "Ф", "Готово, вы в деле. Условия записаны в его журнал — " +
              "их видно всем участникам.");
        } catch (e) {
          сорвалось(T("Не вышло принять: "), e);
        }
      });
      box.appendChild(c);
      log.appendChild(box);
      return true;
    } catch (e) {
      сорвалось(T("Приглашение не открылось: "), e);
      return false;
    }
  }

  /* ── Где идёт разговор ────────────────────────────────────────────── */

  /* Раньше вопроса не было: разговор всегда шёл в деле, и другого места не
     существовало. Теперь мест два — общий разговор и открытое дело, — и
     человек обязан видеть, где он сейчас, ДО того как напишет: узнать это из
     ответа значит узнать поздно. */
  /* Направления для смены — спрашиваем один раз и держим.

     Список тот же, что видит маршрутизатор; берём его у службы, а не
     перечисляем в оболочке, иначе новое направление потребует правки
     оболочки — та же грабля, о которой предупреждает соседний комментарий
     про формы объектов. */
  var НАПРАВЛЕНИЯ = null;
  async function направления() {
    if (НАПРАВЛЕНИЯ) return НАПРАВЛЕНИЯ;
    try {
      НАПРАВЛЕНИЯ = ((await api("GET", "/packs")) || {}).packs || [];
    } catch (e) {
      НАПРАВЛЕНИЯ = null;
      throw e;
    }
    return НАПРАВЛЕНИЯ;
  }

  /* Увести дело в другое направление.

     НЕ ОТПРАВЛЯЕМ САМИ. Выбранное ложится в намерение и уезжает со
     СЛЕДУЮЩИМ сообщением человека — тот же приём, что у панели на холсте и
     у строки поиска: он видит, что получилось, прежде чем это чего-то
     стоит. Отправить самим значило бы потратить его кредиты на ход, которого
     он не просил, да ещё сочинив за него текст. */
  async function сменитьНаправление() {
    var короб = document.getElementById("where");
    var кнопка = document.getElementById("reroute");
    if (!короб || !кнопка || !state.caseId) return;
    var список;
    try {
      список = await направления();
    } catch (e) {
      сорвалось(T("Список направлений не пришёл: "), e, T(". Дело цело, направление прежнее."));
      return;
    }
    var выбор = document.createElement("select");
    выбор.className = "wpick";
    var пусто = document.createElement("option");
    пусто.value = "";
    пусто.textContent = T("куда увести дело…");
    выбор.appendChild(пусто);
    список.forEach(function (d) {
      // КЛЮЧ НАПРАВЛЕНИЯ — `id`, а не `domain`. Ландшафт отдаёт пакет с
      // полем id; поля domain в ответе /packs нет вовсе. Первая версия
      // читала d.domain, получала undefined на каждом пакете и строила
      // ПУСТОЙ список — кнопка открывалась и не предлагала ничего.
      // Проверено на живой двери: ключи ответа — id, title, description,
      // deal_kinds… и никакого domain.
      var ид = d && (d.id || d.domain);
      if (!ид || ид === state.domain) return;
      var o = document.createElement("option");
      o.value = ид;
      o.textContent = T(d.title || ид);
      выбор.appendChild(o);
    });
    кнопка.replaceWith(выбор);
    выбор.focus();
    var решено = false;
    выбор.addEventListener("change", function () {
      if (решено || !выбор.value) return;
      решено = true;
      state.rerouteTo = выбор.value;
      var имя = выбор.options[выбор.selectedIndex].textContent;
      state.rerouteWhy = T("человек увёл дело в «") + имя + "»";
      выбор.replaceWith(кнопка);
      renderWhere();
      // Говорим ВСЛУХ, что смена ещё не произошла: молчаливое намерение
      // человек прочтёт как сделанное и удивится прежнему ответу.
      say("bot", "Ф", T("Следующее ваше сообщение уйдёт в «") + имя +
          T("». Направление сменится вместе с ним, и агента подберу заново — " +
          "у направлений разные источники и разные границы."));
    });
    выбор.addEventListener("blur", function () {
      if (!решено && выбор.parentNode) выбор.replaceWith(кнопка);
    });
  }

  /* Сменить работника внутри направления.

     Тот же приём, что у смены направления и у строки поиска: выбранное
     ложится в намерение и уезжает со СЛЕДУЮЩИМ сообщением. Отправить самим
     значило бы потратить чужие кредиты на ход, которого не просили.

     Список берём у службы, а не собираем в оболочке: она спрашивает матчер
     ТЕМ ЖЕ запросом, каким выбирают по умолчанию — сторона дела, доверие
     спрашивающего, воля дела о выносе. Показать недопустимого значило бы
     предложить выбор, который потом отвергнут, а отказ человек прочтёт как
     поломку. */
  async function сменитьРаботника() {
    var кнопка = document.getElementById("swagent");
    if (!кнопка || !state.caseId) return;
    var данные;
    кнопка.disabled = true;
    try {
      данные = await api("POST", "/dialog/agents", { case_id: state.caseId });
    } catch (e) {
      сорвалось(T("Список работников не пришёл: "), e, T(". Дело цело, работник прежний."));
      return;
    } finally {
      кнопка.disabled = false;
    }
    var список = (данные && данные.agents) || [];
    if (список.length < 2) {
      // Не молчим: «кнопка нажалась и ничего» человек прочтёт как поломку.
      say("bot", "Ф", список.length === 1
        ? T("В этом направлении по вашему делу допущен только один работник — ") +
          (список[0].title || список[0].id) + T(". Выбирать не из кого.")
        : "Допущенных работников по этому делу сейчас нет.");
      return;
    }
    var выбор = document.createElement("select");
    выбор.className = "wpick";
    var пусто = document.createElement("option");
    пусто.value = "";
    пусто.textContent = T("кому передать дело…");
    выбор.appendChild(пусто);
    список.forEach(function (a) {
      var o = document.createElement("option");
      o.value = a.id;
      // ПРИЗНАК ЗРЯЧЕСТИ ВИДЕН И ЧЕЛОВЕКУ. Модели его показывают с 22.08 —
      // не показать человеку значило бы дать ему выбирать между двумя
      // названиями, не зная, что один из двоих слеп.
      o.textContent = T((a.title || a.id) + (a.current ? T(" — ведёт сейчас") : "") +
                      (a.sources ? " · " + a.sources : ""));
      o.disabled = !!a.current;
      выбор.appendChild(o);
    });
    кнопка.replaceWith(выбор);
    выбор.focus();
    var решено = false;
    выбор.addEventListener("change", function () {
      if (решено || !выбор.value) return;
      решено = true;
      var выбран = список.filter(function (a) { return a.id === выбор.value; })[0] || {};
      state.agentTo = выбор.value;
      state.agentWhy = T("человек передал дело работнику «") +
                       (выбран.title || выбор.value) + "»";
      выбор.replaceWith(кнопка);
      renderWhere();
      say("bot", "Ф", T("Следующее ваше сообщение возьмёт «") +
          (выбран.title || выбор.value) + "»" +
          (выбран.purpose ? ": " + выбран.purpose : "") +
          T(". У работников направления разные границы и разные источники."));
    });
    выбор.addEventListener("blur", function () {
      if (!решено && выбор.parentNode) выбор.replaceWith(кнопка);
    });
  }

  /* Назвать стадию дела.

     ПАРА ЗАДАЁТСЯ ЦЕЛИКОМ: вид сделки и стадия вместе. Стадия без вида не
     значит ничего — слово «запрос» есть у шести видов недвижимости и означает
     в каждом своё. Поэтому список строится как «вид → стадия», а не плоским
     перечнем.

     Виды берём из объявлений направления, а не перечисляем в оболочке: новое
     направление иначе потребует правки оболочки.

     В ОТЛИЧИЕ от смены направления и работника это НЕ намерение: стадия
     ничего не тратит и ни на что пока не влияет, поэтому уходит сразу.
     Влиять она начнёт отдельным решением — docs/STAGE_AXIS.md. */
  async function назватьСтадию() {
    var кнопка = document.getElementById("stage");
    if (!кнопка || !state.caseId) return;
    /* НАПРАВЛЕНИЕ БЕРЁМ У ДЕЛА, А НЕ ИЗ state.domain.

       openCase намеренно гасит state.domain — «направление у каждого дела
       своё, оставить прежнее значит отдать разговор агенту соседнего дела»,
       — и возвращается оно только с ответом первого хода. Значит на САМОМ
       ЧАСТОМ пути (открыл дело из левого списка) кнопка выходила первой же
       строкой и молчала. Нажал — не произошло ничего, и почему, узнать
       неоткуда. */
    var домен = state.domain || state.caseDomain || "";
    if (!домен) {
      say("bot", "Ф", "У этого дела пока нет направления — стадию взять " +
          "неоткуда. Напишите что-нибудь в деле, направление определится.");
      return;
    }
    var список;
    кнопка.disabled = true;
    try {
      список = await направления();
    } catch (e) {
      сорвалось(T("Объявления направления не пришли: "), e, ".");
      return;
    } finally {
      кнопка.disabled = false;
    }
    var пакет = список.filter(function (d) {
      return (d.id || d.domain) === домен;
    })[0];
    var виды = (пакет && пакет.deal_kinds) || [];
    if (!виды.length) {
      say("bot", "Ф", T("Направление «") + домен +
          T("» не объявляет видов сделки — стадии у него нет."));
      return;
    }
    var выбор = document.createElement("select");
    выбор.className = "wpick";
    var пусто = document.createElement("option");
    пусто.value = "";
    пусто.textContent = T("на какой стадии дело…");
    выбор.appendChild(пусто);
    виды.forEach(function (в) {
      var гр = document.createElement("optgroup");
      гр.label = в.title || в.kind;
      (в.stages || []).forEach(function (ст, i) {
        var o = document.createElement("option");
        o.value = в.kind + "|" + ст;
        // Номер по порядку: он объявлен, и без него не видно, что стадии
        // выстроены, а не насыпаны.
        o.textContent = T((i + 1) + ". " + ст);
        o.selected = (state.dealKind === в.kind && state.dealStage === ст);
        гр.appendChild(o);
      });
      выбор.appendChild(гр);
    });
    кнопка.replaceWith(выбор);
    выбор.focus();
    var решено = false;
    выбор.addEventListener("change", async function () {
      if (решено || !выбор.value) return;
      решено = true;
      выбор.disabled = true;
      var части = выбор.value.split("|");
      try {
        var дело = await api("PUT", "/cases/" + encodeURIComponent(state.caseId) +
                             "/deal-stage",
                             { deal_kind: части[0], deal_stage: части[1] });
        state.dealKind = (дело && дело.deal_kind) || части[0];
        state.dealStage = (дело && дело.deal_stage) || части[1];
        state.dealStageBy = (дело && дело.deal_stage_source) || "human";
        выбор.replaceWith(кнопка);
        renderWhere();
        // Говорим ВСЛУХ, что это пока ни на что не влияет: иначе человек
        // решит, что подвинул работу, а он подвинул отметку.
        say("bot", "Ф", T("Стадия дела: ") + части[1] + " (" + части[0] + T("). " +
            "Пока это только отметка — на то, кто ведёт дело, она не влияет."));
      } catch (e) {
        выбор.replaceWith(кнопка);
        сорвалось(T("Стадию поставить не вышло: "), e, T(". Дело цело, стадия прежняя."));
      }
    });
    выбор.addEventListener("blur", function () {
      if (!решено && выбор.parentNode) выбор.replaceWith(кнопка);
    });
  }

  function renderWhere() {
    var box = document.getElementById("where");
    var now = document.getElementById("wnow");
    var out = document.getElementById("togeneral");
    var legacy = state.inbox === false;
    box.hidden = false;
    if (state.caseId) {
      /* КТО ВЕДЁТ — В ТОЙ ЖЕ СТРОКЕ. Все ответы подписаны «Ф», и узнать,
         что работника вообще выбирали, человеку было неоткуда. Основание
         выбора дело хранит («выбран по обращению: …») и не показывало
         никогда — кладём его в подсказку, а не в строку: строка коротка, а
         основание длинное и нужно не всем и не всегда. */
      var ведёт = state.caseAgentTitle || state.caseAgentId || "";
      now.textContent = T(T("разговор идёт в деле: ") +
        (state.caseTitle || state.caseId.slice(0, 16) + "…") +
        (state.rerouteTo
          ? T(" · следующее сообщение уйдёт в другое направление")
          : (state.domain ? T(" · направление: ") + state.domain : "")) +
        (state.agentTo
          ? T(" · работника сменю со следующим сообщением")
          : (ведёт ? T(" · ведёт: ") + ведёт : "")) +
        /* СТАДИЯ ВИДНА, ПОКА НИ НА ЧТО НЕ ВЛИЯЕТ. Так и задумано: сперва
           человек должен её увидеть и подвигать, и только потом она пойдёт
           в подбор работника. Обратный порядок — молчаливая перестановка по
           полю, которого никто не трогал. */
        (state.dealStage ? T(" · стадия: ") + state.dealStage : ""));
      now.title = T(state.caseAgentWhy
        ? T("Почему выбран этот работник: ") + state.caseAgentWhy
        : "");
      // Увести дело можно только когда дело есть. Кнопку прячем не по праву,
      // а по смыслу: без дела уводить нечего.
      var уйти = document.getElementById("reroute");
      if (уйти) уйти.hidden = false;
      var сменить = document.getElementById("swagent");
      if (сменить) сменить.hidden = false;
      var стадияКн = document.getElementById("stage");
      if (стадияКн) стадияКн.hidden = false;
      // Выйти некуда, пока общего разговора нет: кнопка «в общий разговор»
      // при закрытом Inbox отправила бы человека в место, которого нет.
      out.hidden = legacy;
    } else {
      now.textContent = T(legacy
        ? "общий разговор пока не включён — сообщение заведёт или продолжит дело"
        : state.inbox === null
          // Ещё не выясняли. Обещание в этой строке стоит столько же, сколько
          // в приветствии, и по той же причине здесь его нет.
          ? "дело не выбрано; включён ли общий разговор — выяснится на первом сообщении"
          : "общий разговор — дело не выбрано и само не заведётся");
      out.hidden = true;
      var уйти2 = document.getElementById("reroute");
      if (уйти2) уйти2.hidden = true;
      var сменить2 = document.getElementById("swagent");
      if (сменить2) сменить2.hidden = true;
      var стадияКн2 = document.getElementById("stage");
      if (стадияКн2) стадияКн2.hidden = true;
    }
    // Свой идентификатор — мелко, но видимо. Без него «под кем я вошёл»
    // выяснялось запросом в базу: у одного человека здесь несколько
    // личностей (телеграм, google, yandex, телефон), пока каналы не связаны,
    // и понять, которая сейчас, было нечем.
    /* ДВЕ ПОДСКАЗКИ НА ОДНОМ ЭЛЕМЕНТЕ, И ОДНА ЗАТИРАЛА ДРУГУЮ.

       Выше в эту же строку пишется основание «почему дело ведёт этот
       работник», а здесь оно безусловно заменялось на «вы вошли как …» —
       у вошедшего principal есть ВСЕГДА, значит основание не показывалось
       ни разу. Владелец это и заметил: «при наведении ничего не всплывает».

       Обе нужны, и обе про разное: одна про дело, другая про личность.
       Складываем, а не выбираем.

       ЖИТЬ ЭТОМУ НЕДОЛГО. Правило, к которому идём: смысл живёт в постоянно
       видимом тексте, а всплывающая подсказка — только ускоритель поверх
       него. На телефоне наведения нет вовсе, и обе эти строки там не
       существуют. См. docs/SHELL_REDESIGN.md. */
    if (state.principal) {
      var кто = T("вы вошли как ") + state.principal;
      now.title = T(now.title ? now.title + "\n\n" + кто : кто);
    }
    input.placeholder = T(state.caseId
      ? "Пишете в деле…" : "Напишите или скажите…");
  }

  /* Подставить дело, не стирая разговор с экрана. Тем и отличается от
     openCase: тот показывает журнал выбранного дела вместо разговора, а здесь
     дело всплыло посреди общего разговора — стирать сказанное только что
     значит терять то, ради чего дело и появилось. */
  async function adoptCase(id) {
    if (id === state.caseId) return { id: id, title: state.caseTitle };
    var c;
    try {
      c = await api("GET", "/cases/" + id);
    } catch (e) {
      сорвалось(T("Сервер отнёс это к делу ") + id + T(", но открыть его не " +
          "вышло: "), e, T(". Разговор оставляю общим — подставлять " +
          "дело, которого не видно, нельзя."));
      return null;
    }
    // Дело прочитано — теперь и только теперь прежнее можно отпускать.
    покинутьДело();
    state.caseId = c.id;
    state.caseTitle = c.title || "";
    state.caseParticipants = c.participants || [];
    /* КТО ВЕДЁТ И НА КАКОМ ОСНОВАНИИ. Дело хранит и то и другое с самого
       начала, а человек не видел НИ РАЗУ: все ответы подписаны «Ф», и
       узнать, что работника вообще выбирали, было неоткуда.

       А выбор настоящий: у подтверждённого человека в 19 парах
       направление×сторона из 30 допущено больше одного, и между ними решает
       модель, читая обращение. Основание она записывает — «выбран по
       обращению: …», — и оно лежало в деле мёртвым полем. */
    state.caseAgentId = c.selected_agent_id || "";
    state.caseAgentWhy = c.selected_agent_reason || "";
    // Направление ДЛЯ ПОКАЗА и для стадии. Отдельно от state.domain, который
    // гасится намеренно и служит маршрутизации: смешать их значило бы вернуть
    // разговор агенту прежнего дела.
    state.caseDomain = c.domain || "";
    state.dealKind = c.deal_kind || "";
    state.dealStage = c.deal_stage || "";
    state.dealStageBy = c.deal_stage_source || "default";
    rememberCase(c.id);
    // Есть ли у дела ПЛАН: без закреплённого шаблона прогону нечего
    // исполнять, и предлагать поручение значило бы предлагать действие,
    // которое обязано не сработать. Такие дела на проде есть.
    state.caseHasPlan = !!c.template_version;
    // Рядом с caseHasPlan и по той же причине: признак дела, от которого
    // зависит, показывать ли короб. Ставится ВЕЗДЕ, где ставится caseHasPlan,
    // иначе короб появится не на всех дорогах к делу.
    state.caseDraftSteps = (c.on_request_steps || []).filter(function (ш) {
      return ш && ш.step;
    });
    // Направление у каждого дела своё: оставить прежнее — отдать разговор
    // агенту соседнего дела, у которого другие ограничения.
    state.domain = null;
    state.agent = null;
    fieldsEl = null;
    caseBody.innerHTML = "";
    /* НАЗВАНИЕ ДЕЛА ЗДЕСЬ НЕ ПОВТОРЯЕМ.

       На одном экране оно стояло ЧЕТЫРЕ раза: заголовок «Дело», строка «где
       идёт разговор», это поле карточки и строка «Дело о: …». Строка «где
       идёт» его уже назвала сорока пикселями выше — в поле оставляем только
       то, чего там нет: когда заведено.

       Область туда же: одно слово, ради которого рисовалась отдельная
       строка, а строка выше и так перечисляет направление, работника и
       стадию. */
    field("Заведено", when(c.created_at),
          "");
    renderCaseClient(c.id);
    casePane.classList.add("live");
    отметкаДела(true);
    badge.textContent = T("идёт");
    renderCrew(c.participants);
    renderWhere();
    renderScopes();
    /* КОРОБ АРТЕФАКТОВ ЗДЕСЬ ЖЕ, А НЕ ОДИН renderFiles.

       #files, #papers, #docs и #finds лежат ВНУТРИ короба #artifacts, а
       [hidden] стоит с !important — скрытый родитель прячет детей наглухо.
       renderArtifacts решает, показывать ли короб, и звался только из
       openCase. А это ГЛАВНЫЙ путь: так дело заводится из разговора. Значит
       согласившийся завести дело не видел ни файлов, ни бумаг, ни находок, ни
       кнопки «Разговор в PDF» — до тех пор, пока не откроет то же дело заново
       из списка. Ровно тот же недосмотр, что описан ниже про поручение. */
    Promise.all([renderFiles(), renderDocs(), renderFinds(), renderPapers()])
      .then(renderArtifacts);
    /* ПОРУЧЕНИЕ ПОКАЗЫВАЕМ И ЗДЕСЬ. Это второй путь к делу — и он ГЛАВНЫЙ:
       так дело заводится из разговора, когда человек согласился на
       предложение. Первая версия ставила флаг плана и здесь, а показ
       оставляла только в openCase, то есть согласившийся на дело не видел
       кнопки вовсе — до тех пор, пока не откроет то же дело заново из
       списка. Ровно тот же недосмотр, из-за которого кнопки не было
       вообще: код есть, вызвать некому. */
    renderCommission();
    renderRun();
    return c;
  }

  /* ── Общий разговор по контракту Inbox ────────────────────────────── */

  /* Разговор общий и делу не принадлежит. Что делать с сообщением, решает не
     оболочка: она отправляет его в Inbox и отрисовывает присланное решение —
     один из пяти видов, набор закрыт. Дело не заводится ни на одном из этих
     шагов; единственный способ его завести — отдельное подтверждение
     человеком показанного предложения.

     principal_id и channel отсюда не уезжают: их ставит шлюз из токена.
     Прислать их отсюда значило бы дать возможность назвать чужого. */

  /* Приложенное с прошлого хода едет вместе со следующим сообщением — по
     ссылке, не байтами. Байты уже лежат в хранилище: слать их второй раз
     значит гнать по проводу до 25 МБ ради того, что уже доехало.

     Без этого файл и сообщение уходили в разные двери и не встречались нигде:
     человек писал «я приложил снимок», а агент честно отвечал, что ничего не
     видит — потому что в его входе действительно не было ни следа файла. */
  var pendingFiles = [];

  function partsOf(text) {
    var parts = [{ type: "text", value: text }];
    pendingFiles.forEach(function (f) {
      parts.push({
        type: f.mime.indexOf("image/") === 0 ? "image" : "file",
        filename: f.name,
        mime: f.mime,
        // Байты сюда не кладём намеренно: value остаётся ссылкой на хранилище.
        value: "vault:" + f.id
      });
    });
    return parts;
  }

  /* Приложенное превращается в строку, которую видит агент. Раньше здесь
     подставлялось голое value, то есть для файла — ссылка на хранилище: агенту
     это ничего не говорило, а человеку в повторе показывало служебный мусор.

     СОСТОЯНИЕ РАЗБОРА ЗДЕСЬ НЕ НАЗЫВАЕТСЯ ВОВСЕ, и это главное.

     Эта строка ложится В ЖУРНАЛ ДЕЛА как текст сообщения человека — и остаётся
     там навсегда. Всякое сказанное о разборе устаревает через минуту, а из
     журнала не уходит: 28.08.2026 агент цитировал человеку «текст ещё
     извлекается, в этом ходе его нет» на следующий день после того, как текст
     извлекли. Он не выдумывал — он читал историю.

     Прежде тут стояло «содержимое пока не прочитано»; оговорку «в этом ходе»
     добавили, чтобы фраза не врала. Она и не врёт — в тот ход. А в журнале
     живёт вечно и врёт со второго же хода.

     Поэтому журнал записывает ФАКТ: файл приложен, вот его имя и род. Что с
     ним сейчас — знает исполнитель разговора и подаёт отдельным сводом бумаг,
     свежим на каждый ход. Одно место правды вместо двух, и то из них, которое
     умеет устаревать, молчит. */
  function textOf(parts) {
    return (parts || []).map(function (p) {
      if (!p.type || p.type === "text") return p.value || "";
      return T("Приложен файл: ") + (p.filename || T("без имени")) +
             (p.mime ? " (" + p.mime + ")" : "");
    }).join("\n");
  }

  var sentSeq = 0;

  function newMessageId() {
    sentSeq++;
    /* Разрешены только латиница, цифры и «._:-» — остальное шлюз отвергнет
       (^[A-Za-z0-9][A-Za-z0-9._:-]{0,199}$). Ничего о человеке в
       идентификатор не кладём: он уедет в журналы.

       ИМЯ ВКЛАДКИ ЗДЕСЬ — НЕ УКРАШЕНИЕ. Прежде идентификатор состоял из
       миллисекунд и счётчика, у КАЖДОЙ вкладки начинающегося с нуля: две
       вкладки, нажавшие отправку в одну миллисекунду, выдавали один и тот же
       web-<время>-1. Ключ повтора в службе дел — (владелец, канал,
       client_message_id), дела в нём нет, поэтому второе сообщение было бы
       принято за повтор первого и молча проглочено, а человек получил бы
       ответ по чужому делу. */
    return "web-" + Date.now().toString(36) + "-" + ВКЛАДКА + "-" + sentSeq;
  }

  /* Идентификатор выдаётся один раз на сообщение и переживает повтор. Если в
     хранилище лежит неотвеченная отправка с тем же payload — это она и есть,
     и повторять надо её, а не заводить второе сообщение.

     Выбранное дело и названная сторона входят в сравнение наравне с текстом:
     то же самое, но сказанное про другое дело или про другую сторону, — это
     другое сообщение, и слать его под прежним идентификатором значило бы
     прислать конфликт вместо уточнения. */
  function allSents() {
    var сырое;
    try { сырое = JSON.parse(localStorage.getItem(slot(SENT_PREFIX)) || "{}"); }
    catch (e) { return {}; }
    if (!сырое || typeof сырое !== "object") return {};
    /* Запись прежнего формата — одиночная, с полем id прямо в корне. Не
       выбрасываем: это чья-то незавершённая отправка, и потерять её значит
       превратить ближайший повтор во второе сообщение.

       ВРЕМЯ СТАВИМ ТЕПЕРЕШНЕЕ, А ВКЛАДКУ — ПУСТУЮ, и это не небрежность.
       Когда запись сделана, мы не знаем: прежний формат времени не хранил.
       Нулём её пометить нельзя — первая же запись сочтёт её протухшей суткам
       назад и выбросит, то есть перенос не состоится вовсе (моя же ошибка,
       поймана на чтении). А пустая вкладка означает «хозяина нет» — такую
       запись берёт кто спросит, без выдержки: ждать остывания от того, кто
       заведомо уже не ждёт ответа, незачем. */
    if (сырое.id && сырое.parts) {
      var одна = {};
      сырое.at = сырое.at || Date.now();
      сырое.tab = "";
      одна[сырое.id] = сырое;
      return одна;
    }
    return сырое;
  }

  function saveSents(map) {
    /* Записи не копятся вечно: сутки — предел, после которого повтор всё
       равно бессмыслен. Отдельно ограничено число: вкладка, падающая в цикле,
       иначе набьёт хранилище. Выбрасываем СТАРЕЙШИЕ — живая запись всегда
       самая свежая. */
    var теперь = Date.now(), ключи = [], k;
    for (k in map) {
      if (!Object.prototype.hasOwnProperty.call(map, k)) continue;
      if (теперь - (map[k].at || 0) > ОТПРАВКА_ЖИВЁТ_МС) { delete map[k]; continue; }
      ключи.push(k);
    }
    if (ключи.length > ОТПРАВОК_ПРЕДЕЛ) {
      ключи.sort(function (a, b) { return (map[a].at || 0) - (map[b].at || 0); });
      ключи.slice(0, ключи.length - ОТПРАВОК_ПРЕДЕЛ).forEach(function (с) {
        delete map[с];
      });
    }
    try { localStorage.setItem(slot(SENT_PREFIX), JSON.stringify(map)); }
    catch (e) { /* не запомнили — повтор после перезагрузки станет новым */ }
  }

  /* Своя ли это запись — и можно ли её брать.

     Своя находится всегда: имя вкладки переживает перезагрузку. Чужую берём
     только остывшую, то есть такую, чья вкладка заведомо уже не ждёт ответа.
     Взять свежую чужую значило бы отобрать работу у живой вкладки — ровно то,
     от чего и чиним. */
  function можноБрать(запись) {
    if (!запись) return false;
    if (запись.tab === ВКЛАДКА) return true;
    // Хозяина нет вовсе — запись прежнего формата, до того как у вкладок
    // появились имена. Ждать её остывания незачем: тот, кто её оставил, уже
    // не ждёт ответа ни в каком смысле.
    if (!запись.tab) return true;
    return Date.now() - (запись.at || 0) > ЧУЖОЕ_ОСТЫЛО_МС;
  }

  function beginSend(parts, hint, side) {
    hint = hint || "";
    side = side || "";
    var map = allSents(), k, з;
    for (k in map) {
      if (!Object.prototype.hasOwnProperty.call(map, k)) continue;
      з = map[k];
      if (!можноБрать(з)) continue;
      if (з.id && (з.hint || "") === hint && (з.side || "") === side &&
          JSON.stringify(з.parts) === JSON.stringify(parts)) {
        return з;
      }
    }
    var fresh = { id: newMessageId(), parts: parts, hint: hint, side: side,
                  tab: ВКЛАДКА, at: Date.now() };
    map[fresh.id] = fresh;
    saveSents(map);
    return fresh;
  }

  /* Точечно, по идентификатору: чужую запись сносить нечем. Прежде здесь
     стоял removeItem по всему ключу — то есть вкладка, дождавшаяся ответа,
     уносила с собой незавершённую отправку соседней. */
  function endSend(sent) {
    if (!sent || !sent.id) return;
    var map = allSents();
    if (!Object.prototype.hasOwnProperty.call(map, sent.id)) return;
    delete map[sent.id];
    saveSents(map);
  }

  /* Незавершённое подтверждение. Держим отдельно от отправки: у отправки
     повтор безобиден (сервер узнаёт тот же идентификатор), у подтверждения —
     это вопрос о том, завелось ли дело, и ответа на него у нас нет. */
  /* Незавершённые подтверждения хранятся СПИСКОМ по идентификатору сообщения,
     а не одним слотом.

     Одним слотом было так: два предложения подряд — и запись первого молча
     затиралась вторым. Оба подтверждения теряли ответ, дела на сервере
     заводились, а после перезагрузки оболочка предлагала повторить только
     второе и о первом не говорила ни слова. Человек писал первый текст
     заново — и получал третье дело на две просьбы. Тот же слот ломался и без
     перезагрузки: «не повторять» в одной карточке стирало запись другой. */
  function allConfirms() {
    try {
      var raw = JSON.parse(localStorage.getItem(slot(CONFIRM_PREFIX)) || "{}");
      if (!raw || typeof raw !== "object") return {};
      // Запись прежнего формата — одиночная, без ключа. Не выбрасываем её:
      // это чьё-то незавершённое подтверждение, и потерять его значит
      // потерять единственный след дела, о котором человек не знает.
      if (raw.token && raw.sent) {
        var one = {};
        one[raw.sent.id] = raw;
        return one;
      }
      return raw;
    } catch (e) { return {}; }
  }

  function saveConfirms(map) {
    try { localStorage.setItem(slot(CONFIRM_PREFIX), JSON.stringify(map)); }
    catch (e) { /* не запомнили — предложим повтор только в этой вкладке */ }
  }

  function beginConfirm(record) {
    // Чья это работа — записываем сразу: без имени вкладки любая соседняя при
    // ближайшем пуске разберёт живое, прямо сейчас идущее подтверждение как
    // осиротевшее.
    record.tab = ВКЛАДКА;
    var map = allConfirms();
    map[record.sent.id] = record;
    saveConfirms(map);
    /* ПЕРЕЧИТЫВАЕМ И ДОКЛАДЫВАЕМ. allConfirms/saveConfirms — это
       чтение-правка-запись без замка: два одновременных beginConfirm в двух
       вкладках теряют один из двух, и потерянный — это единственный след
       вопроса «завелось ли дело». Окно узкое, но цена потери высока, поэтому
       после записи проверяем, что запись на месте, и повторяем один раз. */
    var снова = allConfirms();
    if (!Object.prototype.hasOwnProperty.call(снова, record.sent.id)) {
      снова[record.sent.id] = record;
      saveConfirms(снова);
    }
  }

  /* Точечно, по идентификатору записи: чужую карточку закрывать нечем. */
  function endConfirm(record) {
    var map = allConfirms();
    delete map[record.sent.id];
    saveConfirms(map);
  }

  function pendingConfirms() {
    var map = allConfirms(), out = [], id;
    for (id in map) {
      if (Object.prototype.hasOwnProperty.call(map, id)) out.push(map[id]);
    }
    return out;
  }

  /* Чем сервер объяснил своё решение. Показываем всегда: человек должен
     видеть, ПОЧЕМУ сказанное отнесли туда, куда отнесли, — иначе выбор дела
     выглядит произволом машины. */
  function routeNote(route, head) {
    var bits = [head];
    if (route.reason) bits.push(route.reason);
    if (typeof route.confidence === "number") {
      bits.push(T("уверенность ") + Math.round(route.confidence * 100) + "%");
    }
    var n = el("div", "waynote", bits.filter(Boolean).join(" · "));
    log.appendChild(n);
    log.scrollTop = log.scrollHeight;
    return n;
  }

  /* Повтор — то же самое сообщение, а не второе. Кнопкой, а не автоматикой:
     дошло оно или нет, мы не знаем, и решать это человеку. */
  function offerRetry(sent, why) {
    var box = el("div", "ways");
    box.appendChild(el("div", "wayshead", "Ответ не пришёл"));
    box.appendChild(el("div", "waynote", why + T(". Повтор уйдёт тем же " +
      "идентификатором и с тем же текстом: сервер обязан узнать в нём то же " +
      "сообщение, а не завести второе.")));
    var b = el("button", "addone", "Повторить отправку");
    b.type = "button";
    b.addEventListener("click", async function () {
      box.remove();
      busy(true);
      // Повторяем сохранённую отправку целиком — вместе с выбранным делом.
      try { await inboxTurn(textOf(sent.parts), sent.hint, sent); }
      finally { busy(false); input.focus(); }
    });
    box.appendChild(b);
    log.appendChild(box);
    log.scrollTop = log.scrollHeight;
  }

  //: Просьбы, которые оболочка исполняет сама, не тратя вызов модели.
  //: Список короткий и точный: ловить намерение догадкой значило бы иногда
  //: съедать настоящую реплику человека вместо ответа на неё.
  var ПОКАЗАТЬ_ЕЩЁ = /^\s*(покажи(те)?( ещё раз| снова)?|проводник|подскажи, где что|что тут есть)\s*[.!?]*\s*$/i;

  //: Вставленный номер. Человеку выдают номера — дела, бумаги, сообщения, —
  //: и до сих пор вставить такой номер в разговор значило потратить вызов
  //: модели на то, что модель всё равно не знает: 30.08.2026 агент выдал
  //: `6800e33f-…` под видом «идентификатора разговора», а это был ключ
  //: повтора сообщения, и найти по нему было нечего и негде.
  //:
  //: Ловим ТОЛЬКО голый номер, без слов вокруг. Догадка по «найди то-то»
  //: съедала бы настоящие реплики — ровно то, от чего предостерегает список
  //: выше. Обратные кавычки снимаем: агент выдаёт номер в них, и человек
  //: копирует вместе с ними.
  var ГОЛЫЙ_НОМЕР = /^\s*`?\s*((?:case|doc|thr|prn|duty)_[A-Za-z0-9]{4,}|[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12})\s*`?\s*[.!?]*\s*$/;

  async function поНомеру(номер) {
    var о;
    try {
      о = await api("GET", "/lookup/" + encodeURIComponent(номер));
    } catch (e) {
      // Не выдумываем, чего не знаем: «не нашёл» и «не смог посмотреть» —
      // разные ответы, и второй не должен выглядеть как первый.
      сорвалось(T("Не вышло посмотреть номер: "), e, T(". Номер цел, попробуйте ещё раз."));
      return;
    }
    var строки = [о.note || ""];
    if (о.found === true && о.title) строки.push("«" + о.title + "»");
    say("bot", "Ф", строки.join(" "));
    // Нашлось своё дело — открываем его, а не оставляем человека со строкой.
    if (о.found === true && о.kind === "дело" && о.id) {
      try { await openCase(о.id); } catch (e) { /* останется строка выше */ }
    }
  }

  // Текстовое согласие — такое же явное действие человека, как кнопка. Оно
  // относится только к последнему показанному предложению этой вкладки:
  // угадывать, какое из старых дел имелось в виду, нельзя.
  var ПОДТВЕРДИТЬ_ДЕЛО = /^\s*(?:да[,\s:—-]*(?:создавай|заводи|начинай)|(?:создай|заведи|открой)\s+(?:это\s+)?дело)\s*[.!]*\s*$/i;
  var ожидающееПредложение = null;

  async function inboxTurn(text, hint, sent, side) {
    if (!hint && !sent && ожидающееПредложение &&
        ПОДТВЕРДИТЬ_ДЕЛО.test(text || "")) {
      var ожидающее = ожидающееПредложение;
      ожидающееПредложение = null;
      if (ожидающее.timer) clearTimeout(ожидающее.timer);
      if (ожидающее.box && ожидающее.box.parentNode) ожидающее.box.remove();
      await runConfirm(ожидающее.record);
      return;
    }
    if (ПОКАЗАТЬ_ЕЩЁ.test(text || "")) {
      say("me", "", text);
      проводник();
      return;
    }
    var номер = ГОЛЫЙ_НОМЕР.exec(text || "");
    if (номер) {
      say("me", "", text);
      await поНомеру(номер[1]);
      return;
    }
    sent = sent || beginSend(partsOf(text), hint, side);
    var thinking = думает();
    var res;
    try {
      var body = { client_message_id: sent.id, parts: sent.parts };
      // Дело называем только явно выбранное. Своих кандидатов оболочка не
      // придумывает: из каких дел выбирать, решает сервер.
      if (sent.hint) body.case_hint = sent.hint;
      /* РАЗГОВОР БЕЗ ДЕЛА ЕДЕТ ВМЕСТЕ С СООБЩЕНИЕМ.

         Без него маршрутизатор видит одну фразу и не узнаёт в «пвх» ответа на
         свой же вопрос «Какой тип лодки?» — так на живом разговоре 31.08.2026
         прошло семь уточнений подряд.

         ТОЛЬКО КОГДА ДЕЛА НЕТ. У выбранного дела своя память — журнал
         событий, и она полнее: подсовывать вместо неё обрывок общего
         разговора значило бы рассказывать про дело чужими репликами.

         Поле НЕОБЯЗАТЕЛЬНОЕ на той стороне: оболочки в браузерах кэшируются,
         и старая, ничего не присылающая, обязана работать как раньше. */
      if (!sent.hint && общаяПамять.length) {
        body.history = общаяПамять.slice(-10);
      }
      // Номер — и когда истории ещё нет: первая же реплика должна быть
      // найдена, а она как раз та, с которой всё пошло не так.
      if (!sent.hint) {
        var номер = номерРазговора();
        if (номер) body.talk_id = номер;
      }
      // Сторона едет только тогда, когда её назвал сам человек кнопкой.
      // Догадка оболочки здесь была бы хуже вопроса сервера.
      if (sent.side) body.side_hint = sent.side;
      res = await api("POST", "/inbox/messages", body, 60000);
      // Приложенное списываем ТОЛЬКО здесь — когда сервер сообщение принял.
      // Списать раньше значило бы вот что: обрыв связи, человек жмёт повтор,
      // partsOf собирает уже без файлов, состав частей не совпадает с
      // запомненным — и beginSend выдаёт НОВЫЙ идентификатор. Служба дел
      // перестаёт узнавать повтор и заводит второе дело. Ровно эту поломку
      // чинили однажды; вернуть её через список приложенного было бы обидно.
      pendingFiles = [];
    } catch (e) {
      thinking.parentNode.remove();
      if (e.status === 404) { await fallbackToCase(e, text, sent); return; }
      if (e.timeout) { offerRetry(sent, reason(e)); return; }
      if (e.status === 429) {
        // Кнопки повтора тут нет: повтор — ровно то, от чего отказали.
        // Но НАПЕЧАТАННОЕ ВОЗВРАЩАЕМ в поле ввода. Пузырь с текстом уже
        // висит в ленте, а самого текста нигде нет: заставлять человека
        // перенабирать длинное сообщение из-за нашего предела — это чинить
        // расход за его счёт.
        var ждать = (e.data && e.data.retry_after) || 0;
        say("bot", "Ф", ждать
          ? (T("Слишком часто — подождите ") + сколько(ждать) + T(" и напишите снова. "
             + "Текст вернул в поле ввода."))
          : "Слишком часто — сделайте паузу и напишите снова.");
        try {
          if (input && !input.value) { input.value = text; input.focus(); }
        } catch (err) { /* вернуть не вышло — сообщение всё равно сказано */ }
        return;
      }
      // ВОПРОС НЕ ОБЪЯВЛЯЕМ ПОЛОМКОЙ. Служба отвечает 502 и когда она правда
      // не ответила, и когда маршрут не собрался — а во втором случае она
      // присылает человеку годный вопрос («не понял, к чему отнести;
      // подскажите одним словом»). Приставка «не ответил» превращала бы этот
      // вопрос в отчёт о нашей поломке, и человек, которому есть что ответить,
      // решал бы, что отвечать некому.
      //
      // Различаем по самому тексту: он начинается с заглавной и кончается
      // знаком конца — значит написан человеку, а не нам. Наши причины
      // выглядят иначе: «model-service вернул HTTP 500», «connection reset».
      var причина = reason(e);
      var человеку = /^[А-ЯЁ][^]*[.!?]$/.test(String(причина || "").trim());
      сорвалось(человеку ? "" : T("Общий разговор не ответил: "), e);
      return;
    }
    thinking.parentNode.remove();
    // Общий разговор ответил — значит он для этого человека включён. Прежде
    // `state.inbox` выставлялся только в false, и третья ветка всех четырёх
    // мест («выясню на первом сообщении») была недостижима: человек навсегда
    // оставался в неизвестности, даже отправив десять сообщений подряд.
    if (state.inbox !== true) { state.inbox = true; renderWhere(); }
    // Ответ получен — повторять этот идентификатор больше нечего. Кроме
    // одного случая: показано предложение завести дело. Пока карточка висит,
    // подтверждение поедет ИМЕННО под этим идентификатором, и стереть его
    // сейчас значит потерять единственный ключ, по которому сервер узнаёт
    // повтор. Прежде запись стиралась здесь всегда, и человек, написавший
    // после обрыва тот же текст заново, получал второе дело.
    if ((res.route || {}).kind !== "propose_case" || res.created_case) endSend(sent);
    await showRoute(res, sent, text);
  }

  /* Пути Inbox закрыты флагом раскатки и отвечают 404 «путь пока не открыт».
     Это не поломка, и вести себя как при поломке нельзя: пустой экран человек
     прочитает как сломанный сервис. Откатываемся на прежний путь через дело —
     и говорим об этом ДО того, как дело заведётся, потому что человек писал в
     общий разговор, а сообщение уйдёт в дело. */
  async function fallbackToCase(e, text, sent) {
    var first = state.inbox !== false;
    state.inbox = false;
    renderWhere();
    // Гасим ИМЕННО свою запись: соседняя вкладка могла в этот момент ждать
    // ответа по своей, и снос по общему ключу унёс бы её.
    endSend(sent);
    if (!first) { await legacyTurn(text); return; }

    // ПЕРВЫЙ 404 ДЕЛА НЕ ЗАВОДИТ. Прежде откат молча уходил в legacyTurn, а
    // тот делает POST /cases с заголовком из первых 90 символов — то есть
    // ровно в том ходу, где человеку было обещано «дело само не заведётся»,
    // оно и заводилось. Обещание нарушалось тем же движением, каким было
    // дано, и человек об этом не спрашивал.
    //
    // Поэтому спрашиваем. Со следующего сообщения путь уже известен, и
    // прежний порядок работает как работал.
    var box = el("div", "ways");
    box.appendChild(el("div", "wayshead", "Общий разговор пока не включён"));
    box.appendChild(el("div", "waynote",
      T("Сервер отвечает «") + reason(e) + T("». Здесь работает прежний порядок: " +
      "сказанное заводит дело. Я обещал, что само оно не заведётся, — поэтому " +
      "спрашиваю, а не завожу.")));
    var yes = el("button", "send", "Тогда завести дело");
    yes.type = "button";
    yes.addEventListener("click", async function () {
      yes.disabled = true;
      box.remove();
      busy(true);
      try { await legacyTurn(text); }
      finally { busy(false); input.focus(); }
    });
    var no = el("button", "addone", "Не нужно");
    no.type = "button";
    no.addEventListener("click", function () {
      box.remove();
      say("bot", "Ф", "Хорошо, дела не завожу. Ничего не создано. Следующее " +
          "сообщение уже пойдёт прежним путём — про него я скажу заранее.");
    });
    var row = el("div", "prow");
    row.appendChild(yes);
    row.appendChild(no);
    box.appendChild(row);
    log.appendChild(box);
    log.scrollTop = log.scrollHeight;
  }

  /* Ответ вне дела.

     Память общего разговора держит ОБОЛОЧКА и шлёт её сюда: у дела память
     своя (журнал событий), а у общего разговора дела нет — и заводить его на
     сервере ради памяти значило бы завести дело, не спросив человека.

     Держим коротко, десять последних ходов: это разговор, а не архив, и
     длинная память здесь стоила бы токенов на каждом сообщении. */
  var общаяПамять = [];

  /* Assessment — проверенный машинный план, но не отладочный протокол.

     Прежний рендер вываливал в разговор `platform_fit`,
     `finance.budget`, имена capability, хэш снимка и даже
     «Человек хочет…». Это верно для аудита и неверно для личного
     помощника. В ленту идут только человеческое резюме, честная
     граница и один следующий вопрос. Полный план покажет карточка
     предложения, где он нужен. */
  function текстОценки(a, видМаршрута, название) {
    if (!a) return "";
    var резюме = String(a.summary || "").trim();
    var служебное = /^(?:человек|пользователь|сторона)(?:\s|$)/i.test(резюме)
      || /(?:platform_fit|template_id|capability|контур)/i.test(резюме);
    if (!резюме || служебное) {
      резюме = название
        ? T("Понял. Помогу с задачей: ") + название + T(". Проведу по шагам.")
        : "Понял вас. Помогу разобраться и организую работу по шагам.";
    }
    var строки = [резюме];
    if ((a.gaps || []).length && видМаршрута !== "clarify_side") {
      строки.push("", T("Сразу учту: ") + a.gaps.join("; ") + ".");
    }
    // clarify_side уже покажет один вопрос двумя кнопками. Второй
    // вопрос из assessment в том же ходу превращал помощь в анкету.
    if (a.next_question && видМаршрута !== "clarify_side") {
      строки.push("", a.next_question);
    }
    return строки.join("\n");
  }

  function показатьОценку(a, видМаршрута, название) {
    var сказано = текстОценки(a, видМаршрута, название);
    if (!сказано) return "";
    var b = bubble("bot", "Ф");
    render(b, сказано);
    озвучить(b, сказано, true);
    log.scrollTop = log.scrollHeight;
    return сказано;
  }

  function запомнитьОценку(text, сказано) {
    if (!сказано) return;
    общаяПамять.push({ role: "user", text: String(text || "") });
    общаяПамять.push({ role: "assistant", text: сказано });
    if (общаяПамять.length > 20) общаяПамять = общаяПамять.slice(-20);
  }

  //: Сколько раз подряд можно не отнести сказанное к направлению, прежде чем
  //: перестать спрашивать. Три — потому что два это ещё недоразумение, а
  //: четвёртый вопрос подряд человек уже читает как издевательство: в разборе
  //: живого разговора 31.08.2026 их было СЕМЬ, и каждый следующий звучал
  //: бодрее предыдущего.
  var УТОЧНЕНИЙ_ПОДРЯД = 3;
  var неОтнесли = 0;

  /* Перестать спрашивать и сказать прямо.

     Предел стоит В ОБОЛОЧКЕ, а не в службе, и это не от лени: служба каждый
     ход решает заново и по одной фразе — считать «подряд» ей нечем. Оболочка
     же видит весь разговор, потому что сама его и держит.

     Список берём у `/packs` — тот же, по которому заводят дело. Присланные
     службой `choices` тут не годятся: когда она СУМЕЛА спросить, там пара
     вариантов её вопроса, а нужно всё, что есть. */
  async function хватитСпрашивать(пузырь) {
    var короб = el("div", "cmdout");
    короб.appendChild(el("div", null,
      "Третий раз подряд не отношу сказанное ни к одному направлению. " +
      "Скорее всего вашей задачи у нас просто нет — вот всё, что есть:"));
    var имена = [];
    try {
      имена = (((await api("GET", "/packs")) || {}).packs || [])
        .map(function (п) { return п.title || п.id; }).filter(Boolean);
    } catch (e) { /* не пришёл — скажем без списка, это честнее молчания */ }
    if (имена.length) {
      var строка = el("div", "cmdnote");
      строка.textContent = имена.join(" · ");   // названия от службы, мимо словаря
      короб.appendChild(строка);
    }
    короб.appendChild(el("div", "cmdfoot",
      "Если вашей задачи здесь нет — она не «плохо сформулирована», её просто " +
      "некому выполнить. Дальше спрашивать не буду."));
    log.appendChild(короб);
    log.scrollTop = log.scrollHeight;
    // Считаем заново: сказали прямо — разговор начинается с чистого места, и
    // следующая фраза не должна упереться в тот же предел с ходу.
    неОтнесли = 0;
  }

  /* Что у нас вообще есть — словами, а не ещё одним вопросом.

     СПИСОК ПРИСЫЛАЕТ СЛУЖБА, а оболочка его выбрасывала: `r.choices`
     читался только внутри дела (`needs_direction`), и в общем разговоре
     терялся молча. Между тем это осознанная страховка службы, и довод записан
     у неё же: «Не решили — спрашиваем ОДНО, а не показываем пятнадцать. Не
     вышло спросить — показываем пятнадцать, как раньше». Пятнадцать до
     человека не доходили ни разу.

     ТЕКСТОМ, А НЕ КНОПКАМИ. Нажатие должно было бы отправить ход с выбранным
     направлением, а общий ход направления не принимает вовсе (`ОбщийХод`,
     `extra="forbid"`). Кнопка, которая ничего не делает, хуже её отсутствия —
     это правило в оболочке уже записано у панели расширений.

     Внутрь пузыря, а не отдельным коробом: это продолжение того же ответа
     службы, а не голос страницы. */
  function показатьНаправления(пузырь, варианты) {
    var список = (варианты || []).filter(function (в) { return в && в.title; });
    if (!список.length) return;
    var строка = el("div", "waynote");
    // Мимо словаря: названия направлений приходят от службы и переводятся
    // на её стороне, а не парой у текста.
    строка.textContent = T(список.length > 3 ? "что мы умеем: " : "ближе всего: ")
      + список.map(function (в) { return в.title; }).join(" · ");
    пузырь.appendChild(строка);
  }

  async function общийОтвет(text) {
    общаяПамять.push({ role: "user", text: String(text || "") });
    if (общаяПамять.length > 20) общаяПамять = общаяПамять.slice(-20);
    var b = bubble("bot", "Ф");
    b.textContent = T("…");
    try {
      var телоХода = { message: text, history: общаяПамять.slice(0, -1) };
      var номерХода = номерРазговора();
      if (номерХода) телоХода.talk_id = номерХода;
      var r = await api("POST", "/dialog/general", телоХода, 90000);
      var сказано = r.reply || (r.decided ? "" : "Не понял, к чему это относится.");
      b.textContent = "";
      render(b, сказано);
      озвучить(b, сказано, true);
      /* В ПАМЯТЬ — ОБЕИМИ ДОРОГАМИ, И ЭТО БЫЛА НАСТОЯЩАЯ ОШИБКА.

         Ветка «не отнесли к направлению» возвращалась ДО этой строки, а
         значит вопрос агента в память не ложился. Реплика человека при этом
         ложилась всегда (выше). Память набивалась подряд идущими фразами
         человека БЕЗ единого ответа между ними — то есть следующий ход
         получал не разговор, а монолог.

         Разобрано на живом 31.08.2026: десять ходов подряд, каждый
         `decided: false`, и «пвх» сразу после вопроса «Какой тип лодки?»
         разобрано как «бессмысленный набор букв».

         ЧЕГО ЭТО НЕ ЧИНИТ, и это надо назвать: историю получает только тот,
         кто СОЧИНЯЕТ ответ. Тот, кто ОТНОСИТ к направлению (`_route` в
         dialog_service), по-прежнему видит одну текущую фразу, а
         маршрутизатор Inbox не видит истории вовсе — её некуда положить,
         у запроса `extra="forbid"`. */
      общаяПамять.push({ role: "assistant", text: сказано });
      if (!r.decided) {
        неОтнесли += 1;
        if (неОтнесли >= УТОЧНЕНИЙ_ПОДРЯД) await хватитСпрашивать(b);
        else показатьНаправления(b, r.choices);
        return;
      }
      // Отнесли — счёт подряд идущих неудач обнуляется: он про ПОДРЯД, а не
      // про сумму за разговор.
      неОтнесли = 0;
    } catch (e) {
      b.textContent = "";
      if (e && e.status === 429) {
        // 429 — НЕ «про связь», и советовать «повторите» тут вредно: повтор
        // и есть то, от чего отказали. Говорим срок и молчим про причину —
        // человеку нужно знать когда, а не почему.
        var ждать = (e.data && e.data.retry_after) || 0;
        var отказ = ждать
          ? (T("Слишком часто — подождите ") + сколько(ждать) + T(" и спросите снова."))
          : "Слишком часто — сделайте паузу и спросите снова.";
        render(b, отказ);
        /* ОТКАЗ ЧИТАЕТСЯ ВСЛУХ, как и ответ, и это не вежливость.

           Слушающий человек на молчание отвечает повтором — то есть делает
           ровно то, от чего его и отказали. На экране «подождите 30 с», в
           наушниках тишина, и он жмёт снова.

           Правило самой озвучки это и предписывает: сам собой читается ОТВЕТ,
           а не служебное извещение. «Сейчас не отвечу» — ответ на сказанное
           только что, а не уведомление про кредиты. */
        озвучить(b, отказ, true);
        общаяПамять.pop();   // не сказанного не было: иначе память копит
                             // вопросы без ответов и врёт агенту про разговор
        log.scrollTop = log.scrollHeight;
        return;
      }
      // Отказ называем отказом. Молчаливый пустой пузырь читался бы как
      // «агенту нечего сказать», а это про связь.
      var беда = T("Ответить сейчас не вышло: ") + reason(e) +
                 T(". Это про связь, а не про вопрос — повторите.");
      render(b, беда);
      озвучить(b, беда, true);   // молчать про отказ — см. довод выше
    }
    log.scrollTop = log.scrollHeight;
  }

  async function showRoute(res, sent, text) {
    var r = res.route || {};
    var оценка = r.assessment || null;
    var сказано = показатьОценку(оценка, r.kind, r.proposed_title || "");
    if (оценка && !res.created_case && !sent.hint) {
      запомнитьОценку(text, сказано);
    }

    if (res.created_case) {
      routeNote(r, "ФиксАР сверил задачу с возможностями и принял явное поручение");
      await войтиВСозданноеДело(res.created_case, sent);
      return;
    }

    if (r.kind === "reply_general") {
      routeNote(r, "разговор остался общим — дело не заведено");
      // Assessment уже является содержательным ответом MiMo Pro и содержит
      // следующий вопрос. Второй модельный ответ здесь дублировал бы расход и
      // мог бы противоречить только что проверенному плану.
      if (!оценка) await общийОтвет(text);
      return;
    }

    if (r.kind === "propose_case") {
      // СНАЧАЛА ОТВЕТ, ПОТОМ ПРЕДЛОЖЕНИЕ. Прежде человек получал только
      // карточку «похоже на дело — завести?» и ни слова по существу: платой
      // за ответ было согласие на дело, которого он не просил. Спросить «где
      // купить» и получить в ответ предложение завести дело — это не разговор.
      //
      // Порядок именно такой: ответ первым, кнопка следом. Кнопка над
      // ответом читалась бы как условие — «сначала заведи».
      if (!оценка) await общийОтвет(text);
      showProposal(r, res, sent);
      return;
    }

    if (r.kind === "choose_case") {
      showChoices(r, res.case_choices || [], sent);
      return;
    }

    if (r.kind === "clarify_side") {
      // СНАЧАЛА ОТВЕТ, ПОТОМ ВОПРОС — как и у propose_case выше, и по той же
      // причине. Прежде человек, спросивший о деле, получал только допрос
      // «вам нужна помощь или вы её предлагаете?» и ни слова по существу.
      // Это второе место, где платой за ответ было согласие сначала
      // разобраться с нашим устройством; убрать его в одном месте и оставить
      // в другом значит починить наполовину.
      if (!оценка) await общийОтвет(text);
      showSideChoice(r, res, sent);
      return;
    }

    if (r.kind === "continue_case") {
      routeNote(r, "продолжаю уже идущее дело");
      if (!await adoptCase(r.case_id)) return;
      // Не text, а весь состав сообщения: приложенное иначе не доедет до
      // агента, и он ответит, что никакого файла не видит.
      await dialogTurn(textOf(sent.parts), sent.id);
      return;
    }

    if (r.kind === "case_command") { await showCommand(r); return; }

    if (r.kind === "cannot_do") { showCannotDo(r, text); return; }

    // Набор видов закрыт. Незнакомый вид — рассогласование версий, и догадка
    // о том, что с ним делать, однажды сделает не то.
    say("bot", "Ф", T("Сервер прислал решение вида «") + (r.kind || T("без вида")) +
        T("», которого эта страница не знает. Показывать его как разговор не " +
        "буду: набор видов закрыт, и догадка здесь дороже отказа."));
  }

  /* Сторона обмена, когда сервер не смог её назвать. Спрашиваем словами и
     ничего при этом не заводим.

     Почему вопрос, а не наиболее вероятная догадка: сторона решает, кого
     ищет агент и кто ему платит. Приняв «нужен психолог для сына» за «готов
     помочь», система предложила бы человеку разместить свои услуги — то есть
     заработать на своей беде. Ошибка стоит одной ветки в коде и очень дорого
     в разговоре, поэтому её нет.

     Варианты присылает сервер: своих оболочка не добавляет — то же правило,
     что у карточек дел. */
  function showSideChoice(route, res, sent) {
    routeNote(route, "нужно уточнить сторону — дело не заведено");
    var choices = res.side_choices || [];
    if (!choices.length) {
      say("bot", "Ф", "Сервер попросил уточнить сторону, но вариантов не " +
          "прислал. Придумывать их я не стану — напишите иначе, и я попробую " +
          "снова.");
      return;
    }
    var box = el("div", "ways");
    box.appendChild(el("div", "wayshead",
      res.side_question || "Уточните, пожалуйста, сторону"));
    if (route.proposed_title) {
      box.appendChild(el("div", "waynote",
        T("Речь про «") + route.proposed_title + T("». Дела пока нет и от ответа " +
        "оно не заведётся — ответ только уточняет, что вам нужно.")));
    }
    choices.forEach(function (c) {
      var b = el("button", "way");
      b.type = "button";
      var t = el("div", "waytop");
      t.appendChild(el("div", "wayname", c.button));
      t.appendChild(el("div", "waygo", "→"));
      b.appendChild(t);
      b.appendChild(el("div", "waysum", T("вы здесь — ") + c.owner_is));
      b.addEventListener("click", async function () {
        box.remove();
        busy(true);
        try {
          // Тот же текст, но теперь со стороной, названной человеком.
          // Идентификатор новый намеренно: payload изменился, а изменённый
          // payload под прежним идентификатором — конфликт, а не уточнение.
          await inboxTurn(textOf(sent.parts), sent.hint, null, c.side);
        } finally { busy(false); input.focus(); }
      });
      box.appendChild(b);
    });
    log.appendChild(box);
    log.scrollTop = log.scrollHeight;
  }

  /* Предложение завести дело. Дела ещё НЕТ — ни в списке, ни на сервере.
     Явное поручение сервер исполняет сразу; сюда попадает разговор, в котором
     требуется отдельное согласие. Его можно дать кнопкой или словами —
     состояние меняет согласие человека, а не форма элемента интерфейса. */
  function showProposal(route, res, sent) {
    var box = el("div", "ways");
    box.appendChild(el("div", "wayshead", "План готов — завести дело?"));

    var card = el("div", "way");
    var top = el("div", "waytop");
    top.appendChild(el("div", "wayname", route.proposed_title || "Без названия"));
    card.appendChild(top);
    card.appendChild(el("div", "waysum",
      "Дела ещё нет. Ответьте «да, создавай» или используйте кнопку — " +
      "оба способа означают одно явное согласие."));
    // Сторона обмена — на карточке, а не только в подписи предложения.
    // Согласие накрывает сторону: от неё зависит, кого агент будет искать и
    // кто ему платит. Соглашаться на это вслепую человек не должен, а прежде
    // карточка про сторону не говорила ни слова — при том, что код рядом
    // утверждал «согласие давали ровно на ту сторону, которую показали».
    var сторона = (res.side_choices || [])[0];
    card.appendChild(el("div", "waysum", сторона
      ? T("Вы здесь — ") + сторона.owner_is + "."
      // Молчание тут читалось бы как «сторона обычная». Она не обычная — она
      // не названа, и от неё зависит, кого агент будет искать. Говорим это
      // так же прямо, как в ветке вопроса о стороне.
      : "Сторона обмена не названа: кем вы окажетесь в этом деле, сервер не " +
        "сказал. Без вашего явного согласия дело не появится."));
    var d = el("div", "disclose");
    d.appendChild(el("span", "dot"));
    d.appendChild(el("span", null, T("почему: ") + (route.reason || T("не названо"))));
    if (typeof route.confidence === "number") {
      d.appendChild(el("span", null,
        T("· уверенность ") + Math.round(route.confidence * 100) + "%"));
    }
    var ttl = parseInt(res.proposal_expires_in || 0, 10);
    if (ttl > 0) {
      d.appendChild(el("span", null,
        T("· предложение действует ") + Math.max(1, Math.round(ttl / 60)) + T(" мин")));
    }
    card.appendChild(d);
    box.appendChild(card);

    var row = el("div", "prow");
    var ok = el("button", "send", "Завести дело");
    ok.type = "button";
    var no = el("button", "addone", "Не нужно");
    no.type = "button";
    row.appendChild(ok);
    row.appendChild(no);
    box.appendChild(row);

    var timer = null;
    var record = {
      token: res.proposal_token,
      sent: sent,
      title: route.proposed_title || "",
      at: Date.now(),
      ttl: parseInt(res.proposal_expires_in || 0, 10)
    };
    ожидающееПредложение = { record: record, box: box, timer: null };
    if (ttl > 0) {
      // Предложение подписано и протухает. Кнопка, которая после этого
      // отвечает отказом, выглядит поломкой — гасим её сами и говорим словами.
      timer = setTimeout(function () {
        ok.disabled = true;
        if (ожидающееПредложение &&
            ожидающееПредложение.record.sent.id === record.sent.id) {
          ожидающееПредложение = null;
        }
        box.appendChild(el("div", "waynote", "Предложение истекло. Напишите " +
          "то же самое ещё раз — сервер предложит заново."));
      }, Math.min(ttl, 3600) * 1000);
      ожидающееПредложение.timer = timer;
    }

    ok.addEventListener("click", async function () {
      ok.disabled = true;
      no.disabled = true;
      if (timer) clearTimeout(timer);
      if (ожидающееПредложение &&
          ожидающееПредложение.record.sent.id === record.sent.id) {
        ожидающееПредложение = null;
      }
      box.remove();
      // Подтверждение везёт ТОТ ЖЕ идентификатор и ТОТ ЖЕ payload: подпись
      // предложения накрывает и то и другое, и подменить между показом и
      // согласием ничего нельзя — иначе согласие перестало бы что-либо
      // подтверждать.
      await runConfirm(record);
    });

    no.addEventListener("click", function () {
      if (timer) clearTimeout(timer);
      if (ожидающееПредложение &&
          ожидающееПредложение.record.sent.id === record.sent.id) {
        ожидающееПредложение = null;
      }
      box.remove();
      // Карточка закрыта отказом — держать идентификатор больше не за чем.
      // Раньше он стирался сразу по ответу сервера, ещё до показа карточки, и
      // повторить подтверждение было уже нечем.
      endSend(sent);
      say("bot", "Ф", "Хорошо, дела не завожу. Разговор остаётся общим.");
    });

    log.appendChild(box);
    log.scrollTop = log.scrollHeight;
  }

  async function войтиВСозданноеДело(made, sent) {
    say("bot", "Ф", T("Завёл ") + (made.kind_accusative || T("дело")) +
        " «" + (made.title || T("без названия")) + "». План уже лежит в деле.");
    сказатьЧтоЭтоЗначит();
    await adoptCase(made.case_id);
    await dialogTurn(textOf(sent.parts), sent.id);
  }

  /* Отправить подтверждение и честно рассказать, чем оно кончилось.
     Отдельной функцией, потому что зовут её из двух мест: с кнопки «Завести
     дело» и с кнопки «Повторить подтверждение» — в том числе после
     перезагрузки страницы.

     ГЛАВНОЕ ЗДЕСЬ — РАЗЛИЧАТЬ «НЕ ЗАВЕЛОСЬ» И «НЕ ЗНАЮ». Прежде любая
     неудача печатала «Ничего не создано» — утверждение о чужом состоянии,
     которого оболочка не проверяла. А сервер к этому моменту мог уже сделать
     POST /cases: дело заводится ПЕРВЫМ, материалы грузятся после, и падение
     на материалах отвечает пятисоткой уже при заведённом деле. Человек читал
     «ничего не создано», жал «Не нужно», читал «дела не завожу» — и видел это
     дело в списке справа.

     Не создано ровно в двух случаях: 409 (предложение недействительно или
     содержимое изменилось) и 403 (предложение чужое) — обе проверки стоят ДО
     обращения к службе дел. Всё остальное — обрыв связи, наш предел ожидания,
     любая пятисотка — это «не знаю», и повтор безопасен: подпись живёт 15
     минут, а служба дел узнаёт тот же client_message_id и возвращает то же
     дело вместо второго. */
  async function runConfirm(record) {
    busy(true);
    // Запоминаем ДО отправки: если вкладка умрёт в этот момент, повторить
    // будет нечем — а именно в этот момент она и умирает.
    beginConfirm(record);
    var made;
    try {
      made = await api("POST", "/inbox/cases/confirm", {
        proposal_token: record.token,
        client_message_id: record.sent.id,
        parts: record.sent.parts,
        confirmed: true
      }, 60000);
    } catch (e) {
      busy(false);
      // 409 и 403 доказывают «не создано» только для ПЕРВОЙ попытки: обе
      // проверки стоят до обращения к службе дел. На повторе после
      // неизвестного исхода первая попытка могла дело завести, а подпись за
      // это время просрочиться — и тот же 409 означал бы уже другое.
      //
      // Прежде здесь печаталось «Ничего не создано» и стирался идентификатор.
      // Послушный человек писал то же самое заново, получал НОВЫЙ
      // идентификатор — и второе дело: ключ повтора в службе дел строится по
      // (владелец, канал, client_message_id), и совпасть ему было нечем.
      if ((e.status === 409 || e.status === 403) && !record.unknown) {
        endConfirm(record);
        endSend(record.sent);
        сорвалось(T("Дело не заведено: "), e, T(". Ничего не " +
            "создано — напишите то же самое ещё раз, и я предложу заново."));
        return null;
      }
      // Идентификатор НЕ стираем: пока он цел, повторная отправка того же
      // текста вернёт то же дело, а не заведёт второе.
      offerConfirmRetry(record, reason(e));
      return null;
    }
    // Дело есть — повторять нечего ни то, ни другое.
    endConfirm(record);
    endSend(record.sent);
    try {
      // Слово берём у сервера: склонять «курс» и «стройку» оболочке нечем, а
      // жёсткое «дело» здесь означало бы «Завёл дело» там, где завели курс.
      // Ход ещё не кончился: собеседник дела отвечает на то же сообщение.
      // Отпустить поле ввода здесь значило бы дать человеку отправить второе
      // сообщение поверх первого, на которое ещё не ответили.
      await войтиВСозданноеДело(made, record.sent);
    } finally {
      busy(false);
    }
    return made;
  }

  /* ЧТО ТОЛЬКО ЧТО ПРОИЗОШЛО — один раз, на первом деле.

     До 28.08.2026 заведение дела сообщалось распиской: «Завёл дело „X“». Это
     правда, но она ничего не объясняет: человек, впервые сюда попавший, читает
     её как «принял к сведению» и не узнаёт, чем это место отличается от чата.

     А отличие ровно одно и оно измеримо: разговор переезжает в дело и
     переживает вкладку. Это работает сегодня — журнал дела перечитывается при
     возврате, дело принадлежит человеку с первого сообщения. Никакого «я
     сохранил источник и находки» здесь не говорим: источников ещё нет, и
     обещать их значило бы начать знакомство с неправды.

     ТОЛЬКО ОДИН РАЗ. На втором деле это шум, а шум перестают читать за день.
     Признак первого дела берём из СПИСКА, а не из счётчика на странице: список
     мог не прийти, и тогда мы не знаем, первое ли это дело, — а не знаем,
     значит молчим. Несказанное один раз дешевле сказанного не тому.

     РАЗНЫЕ СЛОВА АНОНИМУ И ВОШЕДШЕМУ. Анониму дело доступно, пока цел этот
     браузер: токен лежит в его хранилище. Сказать ему «найдёте с любого
     устройства» было бы обещанием, которого никто не сдержит. */
  function сказатьЧтоЭтоЗначит() {
    if (!state.casesOk) return;              // список не пришёл — не знаем
    if ((state.cases || []).length) return;  // дело не первое
    var общее = T("Теперь разговор живёт в деле, а не на этой странице: "
               + "закроете вкладку — вернётесь и найдёте всё на месте.");
    var добавка = state.assurance
      ? T(" Дело откроется с любого вашего устройства.")
      : T(" Пока вы без входа, дело доступно из этого браузера; вход "
        + "открывает его и с других устройств — разговор при этом не теряется.");
    say("bot", "Ф", общее + добавка);
  }

  /* Честное «не знаю» с кнопкой. Автоматики нет намеренно: повторять или
     подождать — решает человек, а мы обязаны сказать, что именно неизвестно. */
  function offerConfirmRetry(record, why) {
    // С этого мгновения исход подтверждения неизвестен НАВСЕГДА — и на всех
    // следующих попытках тоже. Признак едет вместе с записью и переживает
    // перезагрузку: без него повтор, получивший 409 по просроченной подписи,
    // снова объявил бы «ничего не создано».
    record.unknown = true;
    beginConfirm(record);
    var box = el("div", "ways");
    box.appendChild(el("div", "wayshead", "Не знаю, завелось ли дело"));
    box.appendChild(el("div", "waynote",
      why + T(". Утверждать, что ничего не создано, я не буду: запрос мог " +
      "дойти. Повтор безопасен — он уйдёт тем же подтверждением, и сервер " +
      "вернёт то же дело, а не заведёт второе.")));
    var b = el("button", "addone", "Повторить подтверждение");
    b.type = "button";
    b.addEventListener("click", async function () {
      box.remove();
      await runConfirm(record);
      input.focus();
    });
    box.appendChild(b);
    var drop = el("button", "addone", "Посмотреть список дел");
    drop.type = "button";
    drop.addEventListener("click", async function () {
      drop.disabled = true;
      // Читаем ПОЛНЫЙ список сам, а не через renderScopes и state.cases.
      //
      // Через них выходило ложное «оно не завелось» сразу двумя путями:
      // renderScopes глотает свой отказ (`catch (e) { return; }`) и до чтения
      // списка не доходит — state.casesOk остаётся true с пуска; а если у
      // человека выбрана пилюля области, renderCases вообще не обновляет
      // state.cases. В обоих случаях сравнение шло против списка, прочитанного
      // при загрузке страницы, и оболочка советовала написать то же самое
      // заново — то есть завести второе дело.
      var список = null;
      try {
        список = await api(
          "GET", "/principals/" + state.principal + "/cases", undefined, 15000);
      } catch (e) { список = null; }
      box.remove();
      // Идентификатор и запись подтверждения оставляем, пока не убедились:
      // пока они целы, повтор остаётся повтором.
      if (список === null) {
        сорвалось(T("Список дел сейчас не пришёл, так что сказать, " +
                    "завелось ли дело, мне нечем. Повтор остаётся доступным — " +
                    "обновите страницу, и я предложу его снова."), null);
        return;
      }
      endConfirm(record);
      var нашлось = список.filter(function (c) {
        return c.id === record.case_id ||
               (record.title && c.title === record.title);
      }).length;
      if (нашлось) {
        say("bot", "Ф", T("Дело всё-таки завелось — «") +
            (record.title || T("без названия")) + T("» есть в списке справа. " +
            "Повторять ничего не нужно."));
      } else {
        say("bot", "Ф", "В списке дел нового дела нет — судя по всему, оно " +
            "не завелось. Напишите то же самое ещё раз, и я предложу заново.");
      }
      // Список прочитан — обновим и то, что на экране.
      renderScopes();
    });
    box.appendChild(drop);
    log.appendChild(box);
    log.scrollTop = log.scrollHeight;
  }

  /* После перезагрузки: если подтверждение осталось без ответа, сказать об
     этом первым делом. Молча забыть — значит оставить человека с делом,
     которого он не видел, или без дела, которое он просил. */
  function restorePendingConfirm() {
    // ВСЕ незавершённые, а не последнее. Одним слотом второе предложение
    // затирало первое, и о нём человек не узнавал никогда — при том что дело
    // по нему могло завестись.
    pendingConfirms().forEach(function (record) {
      if (!record || !record.token || !record.sent) return;
      /* ЖИВОЕ ЧУЖОЕ НЕ ТРОГАЕМ. Вкладка Б жмёт «Завести дело»; человек в этот
         момент перезагружает вкладку А. Прежде вкладка А читала чужую запись
         и говорила «страница перезагрузилась, пока шло подтверждение …» про
         дело, которого не заводила. Хуже: offerConfirmRetry тут же ставил
         record.unknown и переписывал запись, а этот признак НАВСЕГДА
         отключает честный ответ «ничего не создано» по 409 и 403 — уже и для
         настоящей вкладки. Своя запись переживает перезагрузку по имени
         вкладки; чужая дождётся, пока остынет. */
      if (!можноБрать(record)) return;
      var ttl = parseInt(record.ttl || 0, 10);
      var прошло = record.at ? (Date.now() - record.at) / 1000 : 0;
      if (ttl > 0 && прошло > ttl) {
        // Подпись заведомо просрочена: предлагать повтор, который ответит
        // отказом, значит обещать то, чего не будет. Но и «ничего не создано»
        // сказать нельзя — исход первой попытки так и остался неизвестным.
        endConfirm(record);
        say("bot", "Ф", T("Пока страница была закрыта, истекло подтверждение " +
            "«") + (record.title || T("без названия")) + T("». Завелось ли дело, я " +
            "не знаю: повторять уже нечем, подпись просрочена. Посмотрите " +
            "список дел справа — если оно завелось, оно там."));
        return;
      }
      offerConfirmRetry(record, T("страница перезагрузилась, пока шло " +
        "подтверждение «") + (record.title || T("без названия")) + "»");
    });
  }

  /* Карточки прислал сервер — из дел, к которым у человека есть доступ.
     Своих вариантов оболочка не добавляет и порядок не меняет: если выбирать
     можно из чего угодно, это уже не выбор из разрешённого. */
  function showChoices(route, choices, sent) {
    routeNote(route, "нужно выбрать дело");
    if (!choices.length) {
      say("bot", "Ф", "Сервер попросил выбрать дело, но карточек не прислал. " +
          "Придумывать варианты я не стану — выберите дело в списке справа.");
      return;
    }
    var box = el("div", "ways");
    box.appendChild(el("div", "wayshead", "К какому делу это относится?"));
    choices.forEach(function (c) {
      var b = el("button", "way");
      b.type = "button";
      var t = el("div", "waytop");
      t.appendChild(el("div", "wayname", c.title || "Без названия"));
      t.appendChild(el("div", "waygo", "→"));
      b.appendChild(t);
      var d = el("div", "disclose");
      d.appendChild(el("span", "dot"));
      d.appendChild(el("span", null, T("состояние: ") + (c.state || T("неизвестно")) +
        (c.domain ? T(" · направление: ") + c.domain : "")));
      b.appendChild(d);
      b.addEventListener("click", async function () {
        box.remove();
        busy(true);
        try {
          // Тот же текст, но теперь с явно названным делом. Идентификатор
          // новый намеренно: payload изменился, а изменённый payload под
          // прежним идентификатором — это конфликт, а не уточнение.
          await inboxTurn(textOf(sent.parts), c.id, null);
        } finally { busy(false); input.focus(); }
      });
      box.appendChild(b);
    });
    var no = el("button", "addone", "Ни к какому — это общий разговор");
    no.type = "button";
    no.addEventListener("click", function () {
      box.remove();
      say("bot", "Ф", "Хорошо, дело не выбираю. Ничего при этом не создано и " +
          "не изменено — скажите иначе, и я попробую снова.");
    });
    box.appendChild(no);
    log.appendChild(box);
    log.scrollTop = log.scrollHeight;
  }

  /* Распознанная команда — это ещё не право её выполнить. Inbox только
     слышит; исполняет отдельная авторизованная ручка Case Kernel, и нажимает
     её человек. Поэтому здесь всегда сначала вопрос, а не действие. */
  /* Удаление дела: сперва опись, потом набранное вручную название.

     Почему не «вы уверены?». Кнопка подтверждения останавливает случайное
     нажатие, но не останавливает решение, принятое не глядя. Здесь человек
     обязан прочитать, ЧТО именно исчезает (числами из живой базы), и
     набрать название дела руками — то есть посмотреть на него ещё раз.

     Три списка печатаются ЦЕЛИКОМ и не сворачиваются. Третий — «найти не
     могу» — самый неудобный и самый важный: он говорит, где содержимое
     может пережить удаление. Спрятать его ради опрятной карточки значит
     превратить честную ручку в обещание, которого система не выполняет. */
  async function askDelete(caseId) {
    if (!caseId) {
      say("bot", "Ф", "Понял: удалить дело. Но какое именно — не назвали. " +
          "Выберите его слева: удалять наугад я не буду.");
      return;
    }

    var prev;
    try {
      prev = await api("POST", "/cases/" + caseId + "/deletion-preview", {});
    } catch (e) {
      сорвалось(T("Опись не получилась: "), e, T(". Пока её нет, удалять нечего — я не удаляю вслепую."));
      return;
    }

    var box = el("div", "ways");
    box.appendChild(el("div", "waynote",
      T("Дело «") + (prev.title || T("без названия")) + T("». Вот что будет.")));

    // Предупреждения первыми: необратимость — не сноска.
    (prev.warnings || []).forEach(function (w) {
      box.appendChild(el("div", "waynote", "⚠ " + w));
    });

    function список(title, rows, empty) {
      box.appendChild(el("div", "waynote", title));
      if (!rows || !rows.length) {
        box.appendChild(el("div", "casenote", empty));
        return;
      }
      rows.forEach(function (r) {
        // n === null значит «сосчитать нечем», и это НЕ ноль. Показать здесь
        // ноль было бы враньём в самом опасном месте.
        var n = (r.n === null || r.n === undefined) ? "не сосчитать" : r.n;
        var line = "· " + r.what + ": " + n;
        if (r.bytes) line += " (" + Math.round(r.bytes / 1024) + T(" КБ)");
        if (r.note) line += " — " + r.note;
        if (r.why) line += " — " + r.why;
        box.appendChild(el("div", "casenote", line));
      });
    }
    список("Исчезнет навсегда:", prev.disappears, "ничего не нашлось");
    список("Останется у вас:", prev.stays, "ничего не остаётся");
    список("Найти не могу — и честно об этом говорю:", prev.unknown, "");

    var name = prev.title || "";
    var need = name || "удалить";

    /* КЛАВИШИ TAB НА ТЕЛЕФОНЕ НЕТ. Подсказка про неё там не подсказка, а
       насмешка: человек читает совет нажать то, чего у него не существует, и
       остаётся ровно там же, где был. Всплывающая подсказка на касании тоже не
       живёт — она показывается под указателем мыши, которого нет.

       Случай не редкий: кабинет мобильный всерьёз — есть viewport,
       медиа-запросы до 460px и значок для домашнего экрана.

       Поэтому подстановка висит КНОПКОЙ, которая работает везде, а Tab
       остаётся ускорителем для тех, у кого клавиатура есть. */
    var есть_клавиатура = true;
    try {
      есть_клавиатура =
        !window.matchMedia("(hover: none) and (pointer: coarse)").matches;
    } catch (e) { /* старый браузер — считаем, что клавиатура есть */ }
    var ПОДСКАЗКА = есть_клавиатура
      ? "Tab или кнопка подставят название целиком"
      : "Кнопка подставит название целиком";

    var строка = el("div", "waynote",
      name ? T("Наберите название дела, чтобы кнопка ожила: ") + name
           : "У дела нет названия — наберите слово удалить");
    строка.title = T(ПОДСКАЗКА);
    box.appendChild(строка);

    /* НАБРАТЬ НАЗВАНИЕ ВЫХОДИЛО НЕ ВСЯКОЕ, и выяснилось это на живом деле:
       «Покупка авиабилетов Москва —Бостон, сентябрь» содержит длинное тире,
       которого на клавиатуре нет. Преграда, задуманная как «убедись, что
       имеешь в виду именно это дело», обернулась «это дело не удалить вовсе»
       — то есть перестала быть преградой и стала поломкой. Причём поломкой
       молчаливой: кнопка просто не оживала, и человек не мог знать, что дело
       не в нём.

       Tab подставляет название целиком. Строгости это не убавляет: название
       написано строкой выше, и мышью его можно было выделить и вставить с
       первого дня — убавляет только мучение. Подтверждение остаётся
       подтверждением: опись прочитана, поле заполнено осознанным движением
       внутри этого самого окна. */
    var inp = el("input", "namecheck");
    inp.type = "text";
    inp.setAttribute("autocomplete", "off");
    inp.placeholder = T(need);
    inp.title = T(ПОДСКАЗКА);
    box.appendChild(inp);

    // Подстановка ВИДНА И НАЖИМАЕМА, а не спрятана в клавишу и всплывающую
    // подсказку: обе недоступны там, где пальцем по стеклу.
    var ряд = el("div", "fillrow");
    var подставить = el("button", "addone", "Подставить название");
    подставить.type = "button";
    подставить.title = T(ПОДСКАЗКА);
    подставить.addEventListener("click", function () {
      inp.value = T(need);
      сверить();
      // Возвращаем указатель в поле только там, где это ничего не заслоняет.
      // На телефоне фокус поднимает клавиатуру поверх кнопки «Удалить
      // навсегда» — то есть прячет ровно то, ради чего всё затевалось.
      if (есть_клавиатура) inp.focus();
    });
    ряд.appendChild(подставить);

    var намёк = el("div", "casenote", есть_клавиатура
      ? "⇥ или клавишей Tab — впишет название целиком"
      : "впишет название целиком, вместе со знаками, которых нет на клавиатуре");
    намёк.title = T(ПОДСКАЗКА);
    ряд.appendChild(намёк);
    box.appendChild(ряд);

    var b = el("button", "addone danger", "Удалить навсегда");
    b.type = "button";
    b.disabled = true;
    function сверить() {
      b.disabled = !сходится(inp.value, need);
    }
    inp.addEventListener("input", сверить);
    inp.addEventListener("keydown", function (e) {
      if (e.key !== "Tab" || e.shiftKey || e.ctrlKey || e.altKey || e.metaKey) {
        return;
      }
      // УЖЕ СОВПАЛО — Tab снова работает как Tab. Иначе тот, кто ходит по
      // странице с клавиатуры, застрял бы в этом поле насовсем: единственная
      // клавиша, которой из поля выходят, была бы навсегда занята подстановкой.
      var совпало = сходится(inp.value, need);
      if (!совпало) {
        e.preventDefault();
        inp.value = T(need);
      }
      // Сверяем В ОБОИХ случаях, а не только после подстановки. Ранний выход
      // молча полагался бы на то, что кнопку уже сверило событие input, — а
      // значение в поле может оказаться и не набранным руками. Обработчик,
      // верный лишь при чужом правильном поведении, однажды встретит другое.
      сверить();
    });

    var keep = el("button", "addone", "Оставить");
    keep.type = "button";
    keep.addEventListener("click", function () {
      box.remove();
      say("bot", "Ф", "Оставил как есть. Ничего не тронул.");
    });

    b.addEventListener("click", async function () {
      b.disabled = true; keep.disabled = true;
      try {
        var tomb = await api("POST", "/cases/" + caseId + "/deletion", {
          token: prev.token, preview_hash: prev.preview_hash,
          confirmed: true, reason_code: "owner_request"
        });
        box.remove();
        // Разговор мог сидеть в удалённом деле, а незавершённые подтверждения
        // и отправки дело ни с чем не сверяют и пережили бы его молча.
        if (state.caseId === caseId) {
          state.caseId = null; state.caseTitle = null;
          state.domain = null; state.agent = null;
          rememberCase("");
        }
        /* СНОСИМ ТОЛЬКО ОТНОСЯЩЕЕСЯ К ЭТОМУ ДЕЛУ.

           Прежде здесь стоял removeItem по обоим ключам целиком, и комментарий
           выше это оправдывал: «дело ни с чем не сверяют». Теперь сверяют — у
           записи отправки есть hint, и это и есть дело. А человек, удаливший
           дело А в первой вкладке, убивал незавершённое подтверждение по делу
           Б, висевшее во второй: после её перезагрузки она уже никогда не
           спросила бы «завелось ли дело Б», потому что единственный след
           стёрт.

           Подтверждения не трогаем вовсе: подтверждение СОЗДАЁТ дело, и к
           удаляемому оно отношения не имеет. Если же дело, о котором вопрос,
           и есть удаляемое, повтор получит отказ и разберётся честно. */
        var осталось = allSents(), ид;
        for (ид in осталось) {
          if (!Object.prototype.hasOwnProperty.call(осталось, ид)) continue;
          if ((осталось[ид].hint || "") === caseId) delete осталось[ид];
        }
        saveSents(осталось);
        var n = 0;
        Object.keys(tomb.taken || {}).forEach(function (k) { n += tomb.taken[k]; });
        say("bot", "Ф", T("Удалил дело «") + (prev.title || T("без названия")) + T("» — " +
            T("навсегда. Унесено записей: ")) + n + T(". " +
            "Что это дело было, система помнит одной строкой без содержимого: " +
            "иначе списания за него остались бы суммами без объяснения."));
        renderCases();
      } catch (e) {
        keep.disabled = false;
        // 410 — дело уже удалено. Не ошибка вовсе: у человека оборвалась
        // связь на первом нажатии, он нажал второй раз, и правильный ответ
        // ему — «уже сделано», а не пересказ надгробия в виде JSON (именно
        // им обернулось бы reason(), потому что в detail здесь предмет).
        if (e && e.status === 410) {
          box.remove();
          if (state.caseId === caseId) {
            state.caseId = null; state.caseTitle = null;
            state.domain = null; state.agent = null;
            rememberCase("");
          }
          say("bot", "Ф", "Это дело уже удалено — значит, первое нажатие " +
              "дошло, даже если ответа вы не увидели. Больше ничего делать " +
              "не нужно.");
          renderCases();
          return;
        }
        // 409 — опись разошлась с делом: не ошибка, а защита. Человеку нужно
        // не «повторить», а посмотреть заново.
        var m = reason(e);
        if (e && e.status === 409) {
          box.remove();
          say("bot", "Ф", T("Не удалил: ") + m + T(". Скажите ещё раз — покажу " +
              "свежую опись."));
        } else {
          b.disabled = false;
          сорвалось(T("Не удалил: "), e);
        }
      }
    });

    box.appendChild(b);
    box.appendChild(keep);
    log.appendChild(box);
    log.scrollTop = log.scrollHeight;
  }

  /* «Этого я не умею» — вслух и с разбором.

     Просьба стереть разговор приходила сюда тремя неправдами сразу: модель
     могла принять её за команду делу (а дела в общем разговоре нет), могла
     отболтаться, а на неудачном разборе человек получал 502 «маршрутизатор
     вернул недопустимое решение» — нашу поломку вместо ответа.

     Здесь не отказ ради отказа: человеку говорится, что можно сделать
     вместо. Экран очистить мы умеем — но и про то, что очистка экрана НЕ
     удаление, сказать обязаны, иначе пустой экран сам станет обещанием. */
  /* ПРЕЙСКУРАНТ НА ОТКАЗЕ. Решение владельца 06.09.2026: на просьбу, которой
     нет в направлениях, надо не отказывать глухо, а предложить работу с ценой
     и спросить согласия.

     ГРАНИЦА, КОТОРУЮ НЕЛЬЗЯ ПЕРЕЙТИ: обещание против сметы. Сказать «уже
     умеем» про то, чего нет, по-прежнему запрещено — из-за этого и написан
     жёсткий отказ ниже. Здесь говорится другое: вот работа, вот что получите,
     вот цена, решать вам.

     Предложения приходят ТОЛЬКО из объявленных в git тарифов направления —
     служба их не сочиняет (services/landscape_service/offers.py). Пусто —
     остаётся прежний отказ слово в слово: предложить нечего, и делать вид, что
     есть, нельзя. */
  async function предложитьВместоОтказа(просьба) {
    var ответ;
    try {
      ответ = await api("GET", "/offers?q=" + encodeURIComponent(просьба || ""), undefined, 8000);
    } catch (e) {
      return false;               // молча: отказ ниже сам по себе честен
    }
    var список = (ответ && ответ.offers) || [];
    if (!список.length) return false;

    say("bot", "Ф",
        T("Напрямую этого у нас нет. Но вот что мы делаем как работу — " +
        "с ценой и по вашему согласию:"));

    var короб = el("div", "chips");
    список.forEach(function (о) {
      var цена = (о.price === 0)
        ? T("бесплатно")
        : (String(о.price).replace(/\B(?=(\d{3})+(?!\d))/g, " ") + " " +
           (о.currency === "RUB" ? "₽" : о.currency));
      var b = el("button", "chip", о.title + " · " + цена);
      b.type = "button";
      b.title = о.deliverable;        // что именно получит — по наведению
      b.addEventListener("click", function () {
        подтвердитьРаботу(о, цена, просьба);
      });
      короб.appendChild(b);
    });
    log.appendChild(короб);

    // ЧТО ИМЕННО ПОЛУЧИТ — текстом, а не только подсказкой у кнопки: на
    // телефоне наведения нет, и цена без описания результата это ценник без
    // товара.
    список.forEach(function (о) {
      say("bot", "Ф", "— " + о.title + ": " + о.deliverable);
    });
    log.scrollTop = log.scrollHeight;
    return true;
  }

  /* ПОДТВЕРЖДЕНИЕ ПЕРЕД СПИСАНИЕМ. Нажатие на предложение НЕ открывает дело:
     сперва человек видит, за что именно платит и чего в работе НЕТ.

     Первая редакция (06.09.2026) отправляла согласие сообщением от человека —
     «ничего не заводится за спиной». Довод был верный, а исполнение половинчатым:
     согласие никуда не вело, человек оставался с текстом в разговоре. Заводить
     по одному нажатию нельзя, а вот по нажатию с ценой и границами перед
     глазами — можно; за спиной здесь ничего не происходит, потому что всё
     сказано до, а не после. */
  function подтвердитьРаботу(о, цена, просьба) {
    var короб = el("div", "chips");
    /* КОГДА ВОЗЬМУТ ДЕНЬГИ — ЧАСТЬ ОБЕЩАНИЯ, А НЕ ПОДРОБНОСТЬ. «Спишем 1900»
       и «спишем 1900 после того, как примете» — разные сделки. Работа, которая
       может не получиться (починка сбоя), оплачивается после приёмки, и
       сказать про неё «спишем» было бы неправдой в обе стороны: человек ждёт
       списания, которого нет, и не знает, что платит потом. */
    var потом = о.charge_on === "acceptance";
    say("bot", "Ф",
        T("Работа: ") + о.title + ". " +
        (потом
          ? T("Спишем ") + цена + T(" после того, как примете работу. Сейчас — ничего.")
          : T("Спишем ") + цена + ".") + "\n\n" +
        о.deliverable + "\n\n" +
        T("Что НЕ входит: ") + (о.excludes || []).join("; ") + ".\n\n" +
        (о.on_overrun === "finish_at_loss"
          ? T("Если работа окажется больше расчёта — доделаем себе в убыток.")
          : T("Если работа окажется больше расчёта — остановимся и вернём деньги.")));

    var да = el("button", "chip", потом
      ? T("Заказать, оплата после приёмки")
      : T("Открыть дело за ") + цена);
    да.type = "button";
    да.addEventListener("click", async function () {
      да.disabled = true;
      try {
        var итог = await api("POST", "/cases/from-offer", {
          domain: о.domain, tariff_id: о.id, request: просьба || "" }, 30000);
        /* ОТВЕТ СЛУЖБЫ, А НЕ НАШЕ ПРЕДПОЛОЖЕНИЕ. `charged` говорит, взяли
           ли деньги на самом деле; сказать «Списано» там, где не списано,
           значит соврать в единственном месте, где человек это проверяет. */
        say("bot", "Ф", T("Дело открыто: ") + (итог.title || о.title) + ". " +
            (итог.charged
              ? T("Списано ") + цена + "."
              : T("Пока не списано ничего — заплатите, когда примете работу.")));
        // `openCase` объявлена в этой же оболочке (строка ~8066). Проверка
        // типа здесь была бы не страховкой, а глушителем: пропади функция —
        // человек молча остался бы без дела, за которое заплатил.
        if (итог.case_id) openCase(итог.case_id);
      } catch (e) {
        да.disabled = false;
        /* Служба говорит человеку через `detail.message`; своих слов за неё
           не придумываем — НО И СЫРОЙ `e.message` НЕ ОТДАЁМ.

           Здесь стояло `e.message` напрямую, и это не то же самое: `api()` в
           этом файле кидает `new Error(data.detail || …)`, то есть `message`
           равен СЫРОМУ `detail` ответа службы. Через него наружу уезжает
           внутреннее — имена ручек, коды, устройство отказа, — а человек
           читает это как голос помощника.

           Граница одна и она общая: `reason()`, а зовут её через
           `сорвалось()`. Он же различает отказ (до 500) и сбой, чего голая
           склейка не делала вовсе.

           ЗАПАСНОЕ СЛОВО НЕ ПЕРЕДАЁМ, И ЭТО НЕ ПОТЕРЯ. Третий довод
           `сорвалось` — ХВОСТ, он ПРИКЛЕИВАЕТСЯ к причине, а не заменяет её:
           вышло бы «Не вышло: ‹причина›счёт не ответил». Пустого случая тут
           не бывает — `reason()` сам отвечает «причина не названа» или
           «служба не ответила (код)». */
        сорвалось(T("Не вышло: "), e);
      }
    });
    var нет = el("button", "chip", T("Не сейчас"));
    нет.type = "button";
    нет.addEventListener("click", function () { короб.remove(); });
    короб.appendChild(да);
    короб.appendChild(нет);
    log.appendChild(короб);
    log.scrollTop = log.scrollHeight;
  }

  async function showCannotDo(r, просьба) {
    if (r.what === "no_such_direction") {
      // Отказ на ВХОДЕ, до заведения дела. Прежде дело заводилось под любую
      // выполнимую задачу, подбор отдавал агента из чужой области, и человек,
      // спросивший про авиабилеты, получал совет проверить сантехнику. Ни одна
      // часть системы не срабатывала неправильно — неправильным было обещание.
      //
      // С 06.09.2026 сперва смотрим прейскурант: если объявленная работа
      // подходит, человек получает предложение вместо тупика. Не подошла
      // ничего — отказ остаётся прежним, слово в слово.
      if (await предложитьВместоОтказа(просьба)) return;
      say("bot", "Ф",
          T("Этого мы не делаем, и дела я заводить не буду — обещать работу, " +
          "которую некому выполнить, хуже, чем сказать «нет».\n\n") +
          (r.reason ? r.reason + "\n\n" : "") +
          T("Система собрана по направлениям, и агенты есть только в них. " +
          "Что покрыто, видно в списке областей слева; если вашей задачи там " +
          "нет, значит её нет вовсе, а не «надо поискать получше»."));
      var кнопка = el("button", "chip", "Показать направления");
      кнопка.type = "button";
      кнопка.addEventListener("click", function () {
        var scopes = document.getElementById("scopes");
        if (scopes) scopes.scrollIntoView({ block: "nearest" });
      });
      var короб = el("div", "chips");
      короб.appendChild(кнопка);
      log.appendChild(короб);
      log.scrollTop = log.scrollHeight;
      return;
    }
    if (r.what !== "delete_general_conversation") {
      say("bot", "Ф", T("Этого я не умею: ") + (r.reason || T("просьба мне не по силам")));
      return;
    }
    say("bot", "Ф",
        "Общий разговор удалить нельзя — и я не буду делать вид, что удалил. " +
        "Он не дело: у него нет ни описи, ни владельца, и стирать в нём нечего " +
        "так, как стирают дело.\n\n" +
        "Что останется в любом случае: запись о каждом обращении к модели — " +
        "когда, какой меткой и уходило ли наружу. Она хранится намеренно, " +
        "потому что только по ней и можно ответить, куда девались ваши данные. " +
        "Убрать её значило бы убрать сам ответ на этот вопрос.\n\n" +
        "Что можно на самом деле: очистить экран — это уберёт показанное " +
        "здесь и ничего не удалит на сервере; а если разговор шёл в деле, " +
        "дело удаляется целиком, с описью и подтверждением — скажите «удали " +
        "это дело», открыв его.");
    var кнопка = document.createElement("button");
    кнопка.className = "chip";
    кнопка.textContent = T("Очистить экран");
    кнопка.addEventListener("click", function () {
      log.innerHTML = "";
      say("bot", "Ф", "Экран очищен. На сервере ничего не удалено — " +
          "записи об обращениях остались там, где были.");
    });
    var короб = document.createElement("div");
    короб.className = "chips";
    короб.appendChild(кнопка);
    log.appendChild(короб);
    log.scrollTop = log.scrollHeight;
  }

  async function showCommand(route) {
    var word = { close: "закрыть дело", archive: "убрать дело в архив",
                 reopen: "открыть дело заново",
                 set_scope: "отнести дело к области жизни",
                 delete: "удалить дело навсегда"
               }[route.command] || route.command;
    routeNote(route, T("распознана команда: ") + word);

    // Удаление стоит ПЕРЕД остальными и отдельной веткой: оно единственное
    // необратимое, и подтверждение у него другого рода — сперва опись, потом
    // набранное вручную название. Сваливать его в общий поток трёх обратимых
    // команд значило бы однажды случайно дать ему их лёгкое «нажмите кнопку».
    if (route.command === "delete") { await askDelete(route.case_id); return; }

    // Дело подставляется ТОЛЬКО под set_scope: это единственная команда,
    // которой дело нужно активным, чтобы её выполнить. У остальных трёх ручка
    // тоже есть, но они зовут её по route.case_id и разговор не трогают.
    //
    // Прежде adoptCase звался для всех четырёх, и «закрой дело про ремонт»
    // приводило к обратному: разговор ПЕРЕЕЗЖАЛ в это дело, запоминался в
    // localStorage и утаскивал туда следующие сообщения — включая совсем
    // посторонние. Просьба закрыть дело делала его активным навсегда.
    // Три команды жизненного цикла исполняет ручка /cases/{id}/state. Дело
    // при этом НЕ подставляется намеренно: человек просил его закрыть, а не
    // открыть, и подстановка утащила бы разговор ровно туда, откуда его
    // уводят.
    var target = { close: "closed", archive: "archived", reopen: "active" }[route.command];
    if (target) {
      if (!route.case_id) {
        say("bot", "Ф", T("Команду понял — ") + word + T(", но какое именно дело, " +
            "не назвали. Выберите его слева: закрывать наугад я не буду."));
        return;
      }
      var name = caseTitleOf(route.case_id);
      var done = { close: "Закрыл дело", archive: "Убрал в архив дело",
                   reopen: "Вернул в работу дело" }[route.command];
      var box = el("div", "ways");
      box.appendChild(el("div", "waynote",
        T("Дело «") + name + "» — " + word + T("? Пока не нажмёте — не трону.")));
      var b = el("button", "addone", word.charAt(0).toUpperCase() + word.slice(1));
      b.type = "button";
      b.addEventListener("click", async function () {
        b.disabled = true;
        try {
          await api("POST", "/cases/" + route.case_id + "/state",
                    { target_state: target,
                      reason: T("человек попросил в разговоре: ") + word });
          box.remove();
          // ЕСЛИ ЗАКРЫВАЕМОЕ ДЕЛО СЕЙЧАС ОТКРЫТО — из него надо выйти, а не
          // сказать, что вышли. Прежде здесь стояло только сообщение
          // «Разговор остался общим»: обещание вместо действия. Дело
          // оставалось на панели справа, разговор — в окне, а следующая
          // реплика человека уходила в ТОЛЬКО ЧТО ЗАКРЫТОЕ дело.
          //
          // Для возврата в работу выходить, наоборот, незачем: человек
          // открывает дело, а не прощается с ним.
          var ушли = state.caseId === route.case_id && target !== "active";
          if (ушли) {
            toGeneral();
          }
          say("bot", "Ф", done + " «" + name + "»." +
              (ушли ? T(" Разговор вернулся в общий.") : ""));
          renderCases();
        } catch (e) {
          b.disabled = false;
          сорвалось(T("Не вышло: "), e);
        }
      });
      box.appendChild(b);
      log.appendChild(box);
      log.scrollTop = log.scrollHeight;
      return;
    }

    if (!await adoptCase(route.case_id)) return;

    if (route.scope) {
      // Единственная из четырёх команд, которую есть чем выполнить: ручка
      // «отнести дело к области» открыта наружу и работает — ею же пользуются
      // пилюли справа. Нажатие всё равно за человеком: распознали — не значит
      // разрешили.
      var title = scopeTitles[route.scope] || route.scope;
      var box = el("div", "ways");
      box.appendChild(el("div", "waynote",
        T("Отнести дело «") + (state.caseTitle || T("без названия")) + T("» к области " +
        "«") + title + T("»? Пока не нажмёте — не отнесу.")));
      var b = el("button", "addone", T("Отнести: ") + title);
      b.type = "button";
      b.addEventListener("click", async function () {
        b.disabled = true;
        try {
          await api("POST", "/cases/" + state.caseId + "/scope",
                    { scope: route.scope });
          box.remove();
          say("bot", "Ф", T("Отнёс это дело: ") + title.toLowerCase() + ".");
          renderScopes();
        } catch (e) {
          b.disabled = false;
          сорвалось(T("Не вышло отнести: "), e);
        }
      });
      box.appendChild(b);
      log.appendChild(box);
      log.scrollTop = log.scrollHeight;
      return;
    }

    // set_scope без области: сервер распознал команду, но не назвал, куда
    // относить. Выдумывать область за человека нечем и незачем.
    say("bot", "Ф", T("Команду понял — ") + word + T(", но область не названа. " +
        "Выберите её пилюлей справа: относить дело наугад я не буду."));
  }

  /* Название дела по идентификатору — из уже прочитанного списка. Ходить за
     ним в сеть ради одной строки незачем, а подставлять дело ради названия
     тем более: именно этим «закрой дело» и утаскивало разговор. */
  function caseTitleOf(id) {
    var found = (state.cases || []).filter(function (c) { return c.id === id; })[0];
    return (found && found.title) || (id ? id.slice(0, 16) + "…" : "без названия");
  }

  /* ── Разговор внутри дела ─────────────────────────────────────────── */

  /* Ответ по существу пишет собеседник дела: он читает журнал, знает
     направление и границы. Поэтому ход разговора в деле остался прежним — под
     Inbox поменялось то, КАК выбирается дело, а не то, кто отвечает. */
  async function dialogTurn(text, msgId) {
    var thinking = думает();
    try {
      // Идентификатор отправки едет с ходом: при обрыве связи повтор уйдёт с
      // тем же, и служба ответит уже посчитанным вместо того, чтобы считать
      // заново. Прежде повтор шёл полным кругом — человек ждал второй раз и
      // платил второй раз за уже сделанную работу.
      /* СМЕНА НАПРАВЛЕНИЯ ЕДЕТ С ХОДОМ.

         Домен заведённого дела не пересчитывался НИ РАЗУ: служба берёт
         сохранённый маршрут и до маршрутизатора не доходит. Что бы человек
         ни уточнял дальше, он остаётся там, куда попал первым сообщением, —
         а попасть можно и не туда. Живой случай 21.08: дело про новостройки
         сидело в аренде, и агент найма честно отвечал «у меня нет доступа»,
         потому что у него и правда нет ни одного подходящего источника. Для
         человека это неотличимо от свойства площадки.

         Служба смену УМЕЛА с самого начала — принимает domain вместе с
         reroute_reason и без него отвечает 409. Не было только рычага.

         Агента при смене НЕ шлём: он от прежнего направления, и в новом его
         нет. Пустой — значит «подбери заново». */
      var сменаНаправления = state.rerouteTo || "";
      // Смена работника — та же дорога, что и смена направления: служба
      // требует reroute_reason на любую перемену сохранённой пары. При смене
      // НАПРАВЛЕНИЯ выбранный работник не годится — он из прежнего.
      var сменаРаботника = сменаНаправления ? "" : (state.agentTo || "");
      var r = await api("POST", "/dialog", {
        case_id: state.caseId,
        domain: сменаНаправления || state.domain || "",
        agent: сменаНаправления ? "" : (сменаРаботника || state.agent || ""),
        message: text,
        reroute_reason: сменаНаправления
          ? (state.rerouteWhy || "человек сказал, что направление не то")
          : (сменаРаботника
              ? (state.agentWhy || "человек выбрал другого работника")
              : ""),
        client_message_id: msgId || ""
      });

      // Дошло — значит служба смену приняла. Гасим намерение здесь, а не
      // при нажатии: сорвись ход, смена должна остаться в силе, иначе
      // следующее сообщение молча уйдёт в прежнее направление.
      /* ПЛАН ДЕЛА ДОЧИТЫВАЕТСЯ. При заведении дела из разговора оболочка
         читает признак плана на мгновение раньше, чем сервер этот план
         ставит, — и панель «Что искать · Поручить агенту» не появлялась
         НИКОГДА за сессию: помогала только перезагрузка страницы, и узнать
         об этом было неоткуда.

         Спрашиваем ещё раз после хода, и только пока признака нет: у дела с
         планом лишнего запроса не будет. */
      if (state.caseId && !state.caseHasPlan) {
        try {
          var свежее = await api("GET", "/cases/" +
                                 encodeURIComponent(state.caseId));
          if (свежее && свежее.template_version) {
            state.caseHasPlan = true;
            // Третье место, где ставится признак плана. Комментарий выше — про
            // то, что панель не появлялась НИКОГДА за сессию; ровно та же
            // беда ждала бы короб просьбы, если забыть его здесь.
            state.caseDraftSteps = (свежее.on_request_steps || [])
              .filter(function (ш) { return ш && ш.step; });
            state.caseDomain = свежее.domain || state.caseDomain;
            renderCommission();
            renderPaperDraft();
          }
        } catch (e) { /* не вышло — панель появится при открытии дела */ }
      }
      // Имя работника приезжает с КАЖДЫМ ходом и до сих пор выбрасывалось.
      if (r.agent && r.agent.title) {
        state.caseAgentTitle = r.agent.title;
        state.caseAgentId = r.agent.id || state.caseAgentId;
        renderWhere();
      }
      if (сменаНаправления) {
        state.domain = сменаНаправления;
        state.agent = "";
        state.rerouteTo = null;
        state.rerouteWhy = "";
        // Работник прежнего направления в новом не годится: намерение о нём
        // гасим здесь же, иначе оно уедет со следующим ходом уже не туда.
        state.agentTo = null;
        state.agentWhy = "";
        renderWhere();
      } else if (сменаРаботника) {
        // Гасим ПОСЛЕ ответа, а не при нажатии: сорвись ход, смена обязана
        // остаться в силе — иначе следующее сообщение молча возьмёт прежний.
        state.agent = сменаРаботника;
        state.agentTo = null;
        state.agentWhy = "";
        renderWhere();
      }

      thinking.parentNode.remove();

      /* ПРЕЖНИЙ ОТВЕТ НАЗЫВАЕМ ПРЕЖНИМ. Служба отвечает уже посчитанным,
         когда повтор ушёл с тем же идентификатором. Молча отданный второй
         раз, он выглядел бы как новый — и человек решил бы, что его вопрос
         поняли иначе, чем в первый. Прочие поля у такого ответа не приходят
         вовсе, поэтому выходим сразу: разбирать нечего. */
      if (r.repeat) {
        say("bot", "Ф", r.reply);
        log.appendChild(el("div", "casenote",
          "Это ответ на прошлую отправку — он уже был посчитан, и второй раз " +
          "за него не списано."));
        log.scrollTop = log.scrollHeight;
        return;
      }

      /* Маскирование односторонне: номер, который человек дал специально,
         заменён в журнале псевдонимом безвозвратно. Промолчать значило бы
         соврать молчанием — он будет считать, что номер у нас, а его нет. */
      if ((r.redacted || []).length) {
        var чего = (r.redacted || []).map(function (x) {
          return x.label + (x.count > 1 ? " ×" + x.count : "");
        }).join(", ");
        say("bot", "Ф", T("Из сказанного я не сохранил: ") + чего + T(". В журнале " +
            "дела вместо этого стоит псевдоним — так сведения не уезжают к " +
            "модели и не остаются у нас потом. Если это было нужно для дела, " +
            "скажите словами, куда применить."));
      }

      if (r.needs_direction) {
        // Не угадываем: у направлений разные ограничения, и попав не туда,
        // человек получит совет от того, кому это запрещено.
        say("bot", "Ф", r.reply);
        if (r.ways && r.ways.length) showWays(r.ways, text);
        chips.innerHTML = "";
        (r.choices || []).forEach(function (c) {
          var b = el("button", "chip", c.title);
          b.type = "button";
          b.addEventListener("click", function () {
            state.domain = c.domain;
            state.agent = "";
            chips.innerHTML = "";
            // Дело уже выбрано, и спрашивать Inbox «в какое дело» второй раз
            // незачем: маршрут не изменился, изменилось направление внутри
            // него.
            sameCaseTurn(text);
          });
          chips.appendChild(b);
        });
        return;
      }

      if (r.routed && !document.getElementById("dirrow")) {
        state.domain = r.domain;
        var dr = field("Направление", r.routed.title,
                       T("определено по сказанному: ") + (r.routed.why || ""));
        dr.id = "dirrow";
      }
      if (r.agent && !document.getElementById("agentrow")) {
        // Название собеседника — да; модель и метка — нет. Человеку это ни
        // о чём не говорит, а место в карточке дела дорого.
        var ar = field("Собеседник", r.agent.title);
        ar.id = "agentrow";
        var nv = field("Не делает", (r.never || []).join("; "));
        nv.id = "neverrow";
        // Кто его оплачивает — рядом с границами и по той же причине. Агент
        // стороны «готов помочь» работает за деньги поставщика, и совет,
        // прочитанный без этого, читается не тем, чем он является.
        if (r.disclosure) {
          var dc = field("Кто оплачивает", r.disclosure);
          dc.id = "payrow";
        }
      }
      say("bot", "Ф", r.reply);

      badge.textContent = T("идёт");

      if (r.still_working) {
        /* Дверь не дождалась, а работа идёт: ответ ляжет в дело сам.
           Отметку НЕ двигаем — этот ответ ещё не нарисован, и дорисовка
           обязана его принести. Спрашиваем чаще обычного тика: минута
           ожидания и так уже прошла, ещё сорок пять секунд — перебор. */
        [8000, 20000, 45000].forEach(function (через) {
          setTimeout(function () {
            if (!document.hidden) дописатьЖурнал(false);
          }, через);
        });
      } else {
        /* Ответ и свою реплику оболочка нарисовала сама. Догоняем журнал
           молча, иначе дорисовка принесёт их вторыми экземплярами. */
        дописатьЖурнал(true);
      }
    } catch (e) {
      thinking.parentNode.remove();
      сорвалось(T("Не получилось: "), e);
    }
  }

  /* Повторить сказанное в уже открытом деле — после выбора направления. */
  async function sameCaseTurn(text) {
    if (state.busy) return;
    say("you", "Вы", text);
    busy(true);
    var parts = partsOf(text);
    try { await dialogTurn(textOf(parts)); pendingFiles = []; }
    finally { busy(false); input.focus(); }
  }

  /* Прежний порядок: дела нет — заводим первым сообщением. Остаётся живым,
     пока общий разговор не включён, и ровно поэтому не удалён. */
  /* Подпись содержимого для дедупликации в службе дел.

     Хеш считает браузер: сервер сравнивает присланное с сохранённым, а НЕ
     проверяет, что оно посчитано по его правилам, — ему важно лишь, что при
     повторе того же сообщения придёт то же значение. Канонизируем явно, чтобы
     значение не поехало от порядка полей.

     `crypto.subtle` живёт только на https (и на localhost). Если его нет —
     возвращаем пустое, и пара не отправляется вовсе: служба дел требует
     идентификатор и подпись ТОЛЬКО вместе, а прислать одно без другого значит
     получить 422 на ровном месте. Без пары путь работает как раньше, и это
     сказано человеку в ветке отказа. */
  async function caseRequestHash(id, title) {
    try {
      var канон = "case\u0000" + id + "\u0000" + title;
      var bytes = new TextEncoder().encode(канон);
      var digest = await crypto.subtle.digest("SHA-256", bytes);
      return Array.prototype.map.call(new Uint8Array(digest), function (b) {
        return ("0" + b.toString(16)).slice(-2);
      }).join("");
    } catch (e) { return ""; }
  }

  async function legacyTurn(text) {
    // Состав сообщения считаем один раз и здесь, а не в ветке заведения дела:
    // при уже открытом деле той ветки нет вовсе, и приложенное потерялось бы
    // ровно у тех, у кого дело уже идёт.
    var parts = partsOf(text);
    if (!state.caseId) {
      // Тот же идентификатор, что и у общего разговора: при повторе того же
      // текста beginSend отдаёт сохранённый, и служба дел узнаёт повтор.
      // Список приложенного здесь НЕ чистим: до успеха повтор обязан собрать
      // ровно тот же состав частей, иначе идентификатор станет новым.
      var sent = beginSend(parts, "");
      try {
        var тело = { title: text.slice(0, 90), goal: "" };
        // owner_id не шлём: шлюз подставит проверенного субъекта сам. Канал
        // (created_from) он же и называет — клиент объявлять себя каналом
        // права не имеет.
        //
        // А вот идентификатор сообщения и подпись его содержимого шлём: без
        // этой пары служба дел не умеет узнать повтор, и обрыв связи стоил
        // человеку второго дела. С ней ON CONFLICT (owner_id, created_from,
        // client_message_id) возвращает то же дело, и повтор становится
        // повтором.
        var подпись = await caseRequestHash(sent.id, тело.title);
        if (подпись) {
          тело.client_message_id = sent.id;
          тело.client_request_hash = подпись;
        }
        var c = await api("POST", "/cases", тело, 60000);
        state.caseId = c.id;
        state.caseTitle = c.title || "";
        state.caseParticipants = c.participants || [];
        // Дело есть — повторять этот идентификатор больше не за чем.
        endSend(sent);
        // Помним сразу: иначе перезагрузка страницы через минуту откроет
        // пустой экран, а дело останется лежать в списке неузнанным.
        rememberCase(c.id);
        fieldsEl = null;
        caseBody.innerHTML = "";
        field("Дело", c.title || (c.id.slice(0, 16) + "…"),
              "принадлежит вам с первого сообщения");
        // Дело только что заведено — самое время сказать, за кем оно. Пропусти
        // мы этот момент, связывать пришлось бы возвратом в дело позже, а
        // «позже» у только что заведённого дела не наступает почти никогда.
        renderCaseClient(c.id);
        // Дело появилось — появились и пилюли, и список участников: до этого
        // фильтровать и звать было некуда.
        renderWhere();
        renderScopes();
        renderCrew(c.participants);
        // Настройки принадлежат ДЕЛУ, а не экрану: не перерисовав их здесь,
        // человек увидел бы уровень и вынос от прежнего дела.
        renderEgress();
        renderEffort();
      } catch (e) {
        // То же различение, что и в подтверждении, и по той же причине.
        // Прежде здесь стояло «Дело не завелось» на ЛЮБОЙ отказ — утверждение
        // о чужом состоянии, которого оболочка не проверяла: при обрыве связи
        // дело на сервере заводилось, человек читал, что не завелось, писал то
        // же самое заново и получал второе.
        //
        // Отказ шлюза до создания (403, 422) — это правда «не завелось».
        // Обрыв, наш предел и пятисотка — «не знаю».
        if (e.status === 403 || e.status === 422) {
          endSend(sent);
          сорвалось(T("Дело не завелось: "), e, T(". Ничего не создано."));
          return;
        }
        // Идентификатор НЕ стираем: пока он цел, повтор остаётся повтором.
        offerLegacyRetry(text, reason(e));
        return;
      }
    }
    // Сюда доходим только успехом: неудача заведения дела уходит в
    // offerLegacyRetry с ранним возвратом, и приложенное там остаётся ждать
    // повтора.
    pendingFiles = [];
    await dialogTurn(textOf(parts));
  }

  /* Повтор прежнего пути. Безопасен ровно постольку, поскольку ушла пара
     (client_message_id, client_request_hash): служба дел узнаёт повтор по ней
     и возвращает то же дело вместо второго. Без подписи (нет crypto.subtle)
     пары нет, и повторять нечем — тогда честно говорим это словами. */
  function offerLegacyRetry(text, why) {
    var box = el("div", "ways");
    box.appendChild(el("div", "wayshead", "Не знаю, завелось ли дело"));
    var умеем = !!(window.crypto && window.crypto.subtle);
    box.appendChild(el("div", "waynote", умеем
      ? why + T(". Утверждать, что ничего не создано, я не буду: запрос мог " +
        "дойти. Повтор безопасен — он уйдёт тем же идентификатором, и сервер " +
        "вернёт то же дело, а не заведёт второе.")
      : why + T(". Утверждать, что ничего не создано, я не буду: запрос мог " +
        "дойти. Повторить за вас не могу — этот браузер не умеет подписать " +
        "сообщение, и повтор был бы неотличим от второго дела. Обновите " +
        "страницу и посмотрите список дел справа.")));
    if (умеем) {
      var b = el("button", "addone", "Повторить");
      b.type = "button";
      b.addEventListener("click", async function () {
        box.remove();
        busy(true);
        try { await legacyTurn(text); }
        finally { busy(false); input.focus(); }
      });
      box.appendChild(b);
    }
    log.appendChild(box);
    log.scrollTop = log.scrollHeight;
  }

  /* ── Команды со знака «/» ──────────────────────────────────────────────

     ЗАЧЕМ. Половина того, что оболочка умеет, лежит за нажатием, которого не
     видно. Выход из учётной записи — последняя строка раздела «входы», а сам
     раздел свёрнут по умолчанию. Выйти из дела в общий разговор можно ровно
     одной кнопкой в строке «где идёт». Проводник запускается тремя разными
     способами, и ни один из них не назван там, где человек печатает. Тот, кто
     уже знает, чего хочет, ищет это мышью — и не находит.

     ПОЧЕМУ ЗНАК, А НЕ СЛОВА. Догадка по словам здесь уже есть и намеренно
     узкая (ПОКАЗАТЬ_ЕЩЁ, ГОЛЫЙ_НОМЕР): широкая съедала бы настоящие реплики.
     Знак в начале строки однозначен — «покажи мои дела» остаётся разговором,
     «/дела» командой, и спутать их нельзя ни в какую сторону.

     ЧЕГО КОМАНДЫ НЕ ДЕЛАЮТ. Не меняют состояние дела (закрыть, в архив,
     удалить) и ничего не отправляют от имени человека молча. Смена состояния
     живёт за подтверждающей кнопкой; завести ей второй, более короткий вход
     значило бы обойти подтверждение, а не добавить удобства.

     ИМЕНА ЕСТЬ ПО-РУССКИ, И ЭТО НЕ УКРАШЕНИЕ. На русской раскладке `/report`
     набрать нельзя вовсе — выйдет `/кузщке`. Английское имя стоит рядом
     вторым, потому что английская версия оболочки живая; принимаются оба
     всегда, а показывается то, что человек может набрать не переключаясь.

     ЦЕНА НАЗВАНА: сам знак «/» на русской раскладке лежит не на своём месте
     (обратная косая с Shift). Одно переключение на команду — плата за то,
     чтобы догадка по словам осталась узкой. */

  //: Ровно одно написание: косая черта, сразу имя, дальше пробел и остаток.
  //: Второго способа нет намеренно — неоднозначный перехват съедает реплики.
  var ЗАПИСЬ_КОМАНДЫ = /^\/([A-Za-zА-Яа-яЁё][A-Za-zА-Яа-яЁё0-9_-]*)(?:\s+([\s\S]*))?$/;

  /* Спросили номер разговора СЛОВАМИ.

     ЗАЧЕМ ЭТО ТРЕТИЙ ПЕРЕХВАТ ПО СЛОВАМ, а не «наберите /номер». Человек
     31.08.2026 написал ровно «дай номер этого разговора» — и получил «с ходу
     не отнёс это ни к одному направлению». Команда есть, но чтобы про неё
     узнать, надо было её уже знать. Ответ здесь ничего не стоит: ни вызова
     модели, ни хода к службе, — а вопрос понятен без догадок.

     ФОРМА ЗАКРЫТА И ЯКОРИТСЯ НА ВСЁ СООБЩЕНИЕ, как у соседей: ловить намерение
     догадкой значило бы иногда съедать настоящую реплику вместо ответа на неё.
     «Номер разговора» — да; «номер дела», «мой номер», «номер разговора уточню
     позже» — нет, у дела номер свой, и подменять один другим хуже молчания. */
  //: Два порядка слов, потому что по-русски говорят обоими: «номер разговора»
  //: и «у разговора номер». Третьего не выдумываем — не пойманное человек
  //: поправит сам, а лишнее пойманное съест его реплику.
  var СПРОСИЛИ_НОМЕР = new RegExp(
    "^\\s*(?:"
    + "(?:дай(?:те)?|скажи(?:те)?|покажи(?:те)?|какой)?\\s*(?:мне\\s+)?"
    + "номер\\s+(?:у\\s+)?(?:этого\\s+|текущего\\s+|нашего\\s+)?"
    + "(?:разговора|беседы|чата)"
    + "|"
    + "какой\\s+у\\s+(?:этого\\s+|текущего\\s+|нашего\\s+)?"
    + "(?:разговора|беседы|чата)\\s+номер"
    + ")\\s*[?.!]*\\s*$", "i");

  //: Пока набирают ИМЯ — и ни знаком дальше. Появился пробел, значит имя
  //: кончилось и человек пишет довод: список над полем ему уже мешает.
  var НАБИРАЮТ_ИМЯ = /^\/([A-Za-zА-Яа-яЁё0-9_-]*)$/;

  //: Сколько последних неудач помним для сообщения о поломке. Десять — это
  //: примерно один эпизод: меньше не покрывает цепочку «отказ → повтор →
  //: отказ», больше в жалобу не нужно.
  var ОТКАЗОВ_ПОМНИМ = 10;
  var ПОСЛЕДНИЕ_ОТКАЗЫ = [];

  /* Что оболочка видела своими глазами.

     Ради этого кольца всё и заведено: без него «у меня не работает»
     неразбираемо, а с ним в сообщении едут путь, код и причина отказа.

     У ДВЕРИ ЕСТЬ СВОЙ ЖУРНАЛ ОТКАЗОВ, И ОН ЗДЕСЬ НИ ПРИ ЧЁМ. Он знает
     больше — там закрытые коды причин, — но наружу не открыт ни одной
     ручкой: `refusal_log.прочитать` написан, покрыт тестами и не зовётся
     ниоткуда. Открывать его — отдельное решение, а не побочный шаг этой
     работы.

     ЛИЧНОГО ЗДЕСЬ НЕТ И БЫТЬ НЕ ДОЛЖНО: путь без строки запроса, число и код
     причины. Кольцо целиком уезжает оператору, поэтому текст реплик и
     содержимое дела в него не попадают.

     ЧЕГО КОЛЬЦО НЕ ВИДИТ, и это надо знать читающему жалобу: писать в него
     умеет только `api`, а мимо него своим `fetch` ходят СЕМЬ вызовов —
     `whoami` при подхвате токена (три места), `/health`, приглашение и две
     выгрузки холста. Пустое кольцо значит «через api ничего не отказало», а
     не «ничего не ломалось». */
  function запомнитьОтказ(путь, код, причина) {
    try {
      ПОСЛЕДНИЕ_ОТКАЗЫ.push({
        path: String(путь || "").split("?")[0],
        status: String(код),
        reason: String(причина || ""),
        at: new Date().toISOString()
      });
      while (ПОСЛЕДНИЕ_ОТКАЗЫ.length > ОТКАЗОВ_ПОМНИМ) ПОСЛЕДНИЕ_ОТКАЗЫ.shift();
    } catch (e) { /* запись обстановки не смеет ломать сам запрос */ }
  }

  /* Обстановка для сообщения о поломке: техника, а не переписка.

     Состав закрыт и на той стороне тоже (КЛЮЧИ_ОБСТАНОВКИ в reports.py) —
     лишнее отбрасывается там молча. Здесь мы кладём ровно то, с чего
     начинается воспроизведение: какое дело открыто, какое направление, чем
     смотрят и что ломалось последним. */
  function обстановкаОболочки() {
    var о = {
      case: state.caseId || "",
      // Номер разговора — единственное, по чему жалобу на разговор БЕЗ ДЕЛА
      // можно связать с тем, что происходило. Пока его не было, оператор
      // читал жалобу и не мог найти сам разговор.
      talk: номерРазговора(),
      domain: state.domain || "",
      page: (location.pathname || "") + (location.hash || ""),
      lang: (window.ЯЗЫК && window.ЯЗЫК.код) || "",
      screen: (window.innerWidth || 0) + "x" + (window.innerHeight || 0),
      agent: (navigator && navigator.userAgent) || "",
      inbox: String(state.inbox),
      scenario: state.scenario || ""
    };
    if (ПОСЛЕДНИЕ_ОТКАЗЫ.length) о.errors = ПОСЛЕДНИЕ_ОТКАЗЫ.slice();
    return о;
  }

  /* ── Перечень команд ──────────────────────────────────────────────────

     Один список на всё: и подсказка над полем, и `/помощь`, и разбор
     набранного читают его. Три разрозненных места — регулярка, вторая
     регулярка и словарь подписей внутри showCommand — уже были, и именно
     поэтому «что оболочка умеет сама» нельзя было ни показать, ни проверить.

     `оператору: true` — команда, которую видит только тот, кого дверь уже
     пускала на операторские пути. Не флаг доверия: признака оператора у
     оболочки нет, и выдумывать его нельзя. Дверь отвечает неоператору 404
     именно затем, чтобы операторские пути не подтверждались, — назвать такую
     команду в общем перечне значило бы отменить это решение подписью. */
  var КОМАНДЫ = [
    { имя: "помощь", англ: "help", ещё: ["?"], довод: "",
      кратко: "что можно набрать со знака «/»",
      делать: командаПомощь },

    { имя: "ошибка", англ: "report", ещё: ["баг", "bug"],
      довод: "что сломалось",
      кратко: "сообщить о поломке — попадёт в список разбора",
      делать: командаОшибка },

    { имя: "дела", англ: "cases", ещё: ["картотека"], довод: "",
      кратко: "картотека: показать список дел",
      делать: командаДела },

    { имя: "новое", англ: "new", ещё: ["завести"], довод: "название",
      кратко: "открыть форму заведения дела",
      делать: командаНовое },

    { имя: "общий", англ: "general", ещё: ["выйти-из-дела"], довод: "",
      кратко: "выйти из дела в общий разговор",
      делать: командаОбщий },

    { имя: "номер", англ: "id", ещё: [], довод: "",
      кратко: "номер этого разговора — назвать его в жалобе",
      делать: командаНомер },

    { имя: "кредиты", англ: "credits", ещё: ["остаток"], довод: "",
      кратко: "остаток и на что он уходит",
      делать: командаКредиты },

    { имя: "раздел", англ: "go", ещё: [], довод: "имя раздела",
      кратко: "перейти к разделу; без имени — перечень",
      делать: командаРаздел },

    { имя: "проводник", англ: "tour", ещё: [], довод: "",
      кратко: "показать, что где на экране",
      делать: командаПроводник },

    { имя: "язык", англ: "lang", ещё: [], довод: "ru или en",
      кратко: "переключить язык оболочки",
      делать: командаЯзык },

    { имя: "очистить", англ: "clear", ещё: [], довод: "",
      кратко: "убрать ленту с экрана, ничего не удаляя",
      делать: командаОчистить },

    { имя: "выход", англ: "logout", ещё: [], довод: "",
      кратко: "выйти из учётной записи",
      делать: командаВыход },

    { имя: "разбор", англ: "reports", ещё: [], довод: "",
      кратко: "поломки от людей: прочитать и закрыть",
      оператору: true,
      делать: командаРазбор }
  ];

  function командаИз(текст) {
    var м = ЗАПИСЬ_КОМАНДЫ.exec(String(текст == null ? "" : текст).trim());
    if (!м) return null;
    return { имя: м[1].toLowerCase(), довод: (м[2] || "").trim() };
  }

  function доступныеКоманды() {
    var опс = памятьДвери("callers").пускали;
    return КОМАНДЫ.filter(function (к) { return !к.оператору || опс; });
  }

  function найтиКоманду(имя) {
    var список = доступныеКоманды();
    for (var i = 0; i < список.length; i++) {
      var к = список[i];
      if (имя === к.имя || имя === к.англ) return к;
      if ((к.ещё || []).indexOf(имя) >= 0) return к;
    }
    return null;
  }

  //: Показываем то, что человек может набрать НЕ ПЕРЕКЛЮЧАЯ РАСКЛАДКУ.
  //: Принимаются при этом оба имени всегда — см. найтиКоманду.
  function имяКоманды(к) {
    return (window.ЯЗЫК && window.ЯЗЫК.английский && к.англ) ? к.англ : к.имя;
  }

  function подходящиеКоманды(начало) {
    var н = String(начало || "").toLowerCase();
    if (!н) return доступныеКоманды();
    return доступныеКоманды().filter(function (к) {
      var все = [к.имя, к.англ].concat(к.ещё || []);
      for (var i = 0; i < все.length; i++) {
        if (все[i] && все[i].indexOf(н) === 0) return true;
      }
      return false;
    });
  }

  /* ── Как выглядит ответ команды ───────────────────────────────────────

     Пузырём его рисовать нельзя: подпись «Ф» означает, что говорила модель,
     а здесь ответила страница, не потратив ни кредита. Слева тоже нельзя —
     `.msg.me` и `.msg.system` стилей в разметке не имеют вовсе, и такая
     реплика выходит безымянной. Поэтому свой короб, как у карточек путей. */
  function коробКоманды() {
    var к = el("div", "cmdout");
    log.appendChild(к);
    log.scrollTop = log.scrollHeight;
    return к;
  }

  function сказатьКомандой(текст) {
    var к = коробКоманды();
    к.appendChild(el("div", null, текст));
    return к;
  }

  function перечислитьКоманды(куда) {
    доступныеКоманды().forEach(function (к) {
      var строка = el("div", "cmdrow");
      // Имя команды НЕ через el(): третий довод el прогоняется словарём, а
      // «/помощь» переводить нечем — имена подобраны так, что человек их
      // набирает, а не читает. Без этого каждая отрисовка списка копила бы
      // ложный промах в ЯЗЫК.пропущенные().
      var имяУзел = el("b", "cmdname");
      имяУзел.textContent = "/" + имяКоманды(к);
      строка.appendChild(имяУзел);
      if (к.довод) строка.appendChild(el("span", "cmdarg", к.довод));
      строка.appendChild(el("span", "cmdwhat", к.кратко));
      // Подставляет в поле, а не выполняет: то же правило, что у примеров
      // под полем. Человек читает, правит под себя и отправляет сам.
      строка.addEventListener("click", function () { подставитьКоманду(к); });
      куда.appendChild(строка);
    });
  }

  function подставитьКоманду(к) {
    var текст = "/" + имяКоманды(к) + (к.довод ? " " : "");
    input.value = текст;
    input.focus();
    try { input.setSelectionRange(текст.length, текст.length); }
    catch (e) { /* не всякое поле умеет */ }
    обновитьПодсказку();
  }

  /* ── Подсказка над полем ──────────────────────────────────────────────

     Появляется, пока набирают имя, и исчезает, как только пошёл довод.
     Живёт в своём коробе: класс `chips` переиспользуется прямо в ленте, и
     повесить позиционирование на него нельзя. */
  var подсказкаНаведена = -1;

  function коробПодсказки() { return document.getElementById("cmdhint"); }

  function закрытьПодсказку() {
    var к = коробПодсказки();
    подсказкаНаведена = -1;
    if (!к) return;
    к.hidden = true;
    к.innerHTML = "";
    input.setAttribute("aria-expanded", "false");
    input.removeAttribute("aria-activedescendant");
  }

  function рисоватьПодсказку(список) {
    var к = коробПодсказки();
    if (!к) return;
    if (!список.length) { закрытьПодсказку(); return; }
    if (подсказкаНаведена >= список.length) подсказкаНаведена = список.length - 1;
    к.innerHTML = "";
    список.forEach(function (команда, i) {
      var строка = el("div", "cmdrow");
      строка.id = "cmdrow-" + i;
      строка.setAttribute("role", "option");
      строка.setAttribute("aria-selected", i === подсказкаНаведена ? "true" : "false");
      if (i === подсказкаНаведена) строка.classList.add("on");
      var имяСтроки = el("b", "cmdname");   // мимо словаря, см. перечислитьКоманды
      имяСтроки.textContent = "/" + имяКоманды(команда);
      строка.appendChild(имяСтроки);
      if (команда.довод) строка.appendChild(el("span", "cmdarg", команда.довод));
      строка.appendChild(el("span", "cmdwhat", команда.кратко));
      // mousedown, а не click: click приходит ПОСЛЕ потери фокуса полем, и к
      // тому мигу список уже закрыт обработчиком blur — нажатие пропадало бы.
      строка.addEventListener("mousedown", function (e) {
        e.preventDefault();
        подставитьКоманду(команда);
      });
      к.appendChild(строка);
    });
    к.hidden = false;
    /* ПОЛЕ ОБЯЗАНО ОСТАТЬСЯ НА ЭКРАНЕ.

       Список встаёт НАД полем в общем потоке, то есть отодвигает его вниз
       ровно на свою высоту. На широком экране это незаметно: композер держит
       раскладка. На телефоне страница просто длинная — и замер на 375×812
       показал, что поле уезжает с 515-й точки на 872-ю, то есть за нижний
       край. Человек набирает «/» и печатает дальше в поле, которого не видит.

       `block: "nearest"` — наименьшая правка: когда поле и так видно, вызов
       не делает ничего и чужую прокрутку не перебивает. */
    try { input.scrollIntoView({ block: "nearest" }); }
    catch (e) { /* не всякий браузер принимает объект — тогда просто не двигаем */ }
    input.setAttribute("aria-expanded", "true");
    if (подсказкаНаведена >= 0) {
      input.setAttribute("aria-activedescendant", "cmdrow-" + подсказкаНаведена);
    } else {
      input.removeAttribute("aria-activedescendant");
    }
  }

  function обновитьПодсказку() {
    var м = НАБИРАЮТ_ИМЯ.exec(input.value);
    if (!м) { закрытьПодсказку(); return; }
    рисоватьПодсказку(подходящиеКоманды(м[1]));
  }

  function клавишаВПоле(e) {
    var к = коробПодсказки();
    // Список закрыт — поле работает ровно как раньше. Ни Enter, ни стрелки,
    // ни Escape здесь не трогаем: Enter отправляет нативно через форму, а
    // Escape слушают три обработчика на document.
    if (!к || к.hidden) return;
    var строк = к.children.length;
    if (!строк) return;

    if (e.key === "ArrowDown" || e.key === "ArrowUp") {
      e.preventDefault();
      var шаг = (e.key === "ArrowDown") ? 1 : -1;
      подсказкаНаведена = (подсказкаНаведена < 0)
        ? (шаг > 0 ? 0 : строк - 1)
        : (подсказкаНаведена + шаг + строк) % строк;
      обновитьПодсказку();
      return;
    }

    if (e.key === "Escape") {
      // Гасим И всплытие: по Escape три обработчика на document закрывают
      // панели, и человек, убравший подсказку, потерял бы заодно раскрытое.
      e.preventDefault();
      e.stopPropagation();
      закрытьПодсказку();
      return;
    }

    if (e.key !== "Enter" && e.key !== "Tab") return;

    var м = НАБИРАЮТ_ИМЯ.exec(input.value);
    var список = м ? подходящиеКоманды(м[1]) : [];
    if (!список.length) return;

    // Наведённое дополняем всегда: человек выбрал строку стрелками, и Enter
    // здесь означает «эту», а не «отправить».
    if (подсказкаНаведена >= 0) {
      e.preventDefault();
      подставитьКоманду(список[подсказкаНаведена]);
      return;
    }
    // Имя набрано целиком — Enter отправляет, как и всякий раз. Дополнять
    // тут нечего, а перехват сделал бы вторую отправку обязательной.
    var точная = м && найтиКоманду(м[1].toLowerCase());
    if (точная) {
      // Tab дополняет ТОЧНУЮ, а не первую подходящую: имя одной команды
      // однажды окажется началом другой, и первой в списке будет не та.
      if (e.key === "Tab") { e.preventDefault(); подставитьКоманду(точная); }
      else закрытьПодсказку();
      return;
    }
    // Набрано начало. Дополнить добрее, чем отправить: `/ош` службе не нужен.
    e.preventDefault();
    подставитьКоманду(список[0]);
  }

  function завестиПодсказку() {
    if (!input) return;
    input.setAttribute("role", "combobox");
    input.setAttribute("aria-expanded", "false");
    input.setAttribute("aria-controls", "cmdhint");
    input.addEventListener("input", обновитьПодсказку);
    input.addEventListener("keydown", клавишаВПоле);
    input.addEventListener("blur", function () { закрытьПодсказку(); });
  }

  /* ── Что делают команды ───────────────────────────────────────────── */

  function командаПомощь() {
    var короб = коробКоманды();
    короб.appendChild(el("div", "cmdhead",
      "Команды набираются со знака «/» прямо в поле разговора:"));
    перечислитьКоманды(короб);
    короб.appendChild(el("div", "cmdfoot",
      "Всё остальное — обычный разговор: расскажите словами, что нужно."));
  }

  async function командаОшибка(что) {
    if (!что) {
      var к = коробКоманды();
      к.appendChild(el("div", null,
        "Напишите после команды, что сломалось, — одной фразой:"));
      к.appendChild(el("div", "cmdsample",
        "/ошибка кнопка «Отправить» не гаснет после ответа"));
      return;
    }
    var ответ = await api("POST", "/reports",
                          { body: что, context: обстановкаОболочки() }, 20000);
    var короб = коробКоманды();
    короб.appendChild(el("div", null,
      "Записал. Это список для разбора, а не переписка: ответа на это " +
      "сообщение не будет."));
    var номер = el("div", "cmdnote", "номер записи: ");
    номер.appendChild(el("b", null, String(ответ.id || "")));
    короб.appendChild(номер);
    // Вместе с текстом уехало то, что видела страница: открытое дело,
    // направление, размер окна и последние отказы. Сказать об этом обязаны —
    // человек вправе знать, что отправил, а не только что написал.
    короб.appendChild(el("div", "cmdnote",
      "К сообщению приложено то, что видела страница: какое дело открыто, " +
      "чем вы смотрите и что не получалось последним."));
    if (ответ.masked) {
      короб.appendChild(el("div", "cmdnote",
        "Номера и адреса в тексте заменены метками: этот список разбирают " +
        "вне площадки."));
    }
  }

  function командаНомер() {
    var номер = номерРазговора();
    if (!номер) {
      сказатьКомандой("Номер не завёлся: браузер не дал сохранить его. " +
                      "Разговор от этого работает, но найти его потом будет нечем.");
      return;
    }
    var короб = коробКоманды();
    короб.appendChild(el("div", null, "Номер этого разговора:"));
    var н = el("div", "cmdsample");
    н.textContent = номер;
    короб.appendChild(н);
    короб.appendChild(el("div", "cmdfoot",
      "Назовите его в «/ошибка», если жалуетесь на этот разговор: по нему " +
      "разберут, что происходило. У дела номер свой — он виден в карточке."));
  }

  function командаДела() { открытьРаздел("caselist"); }

  async function командаНовое(название) {
    await openMake();
    var поле = document.getElementById("mktitle");
    if (поле && название) поле.value = название;
    if (!открытьРаздел("mkcase")) return;
    // Заводить молча нельзя: у дела есть направление, шаблон и сторона, и
    // выбрать их за человека значит завести не то дело за его деньги.
    if (поле) поле.focus();
  }

  function командаОбщий() {
    if (!state.caseId) {
      сказатьКомандой("Вы и так в общем разговоре — дело не открыто.");
      return;
    }
    toGeneral();
  }

  async function командаКредиты() {
    // Меню строится по последнему прочитанному остатку и молча не рисуется,
    // если тот ещё не приезжал. Спрашиваем сами: команда, не сделавшая
    // ничего и ничего не сказавшая, выглядит как поломка.
    await refreshCredits();
    /* СТРАХОВКА ВЫШЕ НЕ РАБОТАЛА, И ЭТО СТОИЛО ЖАЛОБЫ.
       31.08.2026: «написал слэш/кредиты а в ответ тишина!» (rep_d7426ea4aa61).
       `refreshCredits` молчит НА ВСЕХ своих отказах — нет входа, путь закрыт,
       ручка не ответила, остаток непонятен, — она прячет короб и выходит. За
       ней `creditMenu` не рисует ничего без `lastCredits`. Итого команда
       исполнялась и не говорила ни слова.

       Молчание там ВЕРНО: короб обновляется сам собой, и писать в ленту на
       каждое обновление незачем. Но команду набрал ЧЕЛОВЕК, и она обязана
       ответить всегда — хотя бы тем, почему показать нечего. Поэтому решает
       не `refreshCredits`, а место вызова. */
    if (!lastCredits) {
      сказатьКомандой(!state.principal
        ? "Остаток покажу после входа: кредиты принадлежат человеку, а не "
          + "странице. Нажмите своё имя вверху."
        : "Остаток сейчас не прочитался — это у нас, не у вас. Ничего с "
          + "кредитами не случилось; попробуйте через минуту.");
      return;
    }
    creditMenu();
  }

  function командаРаздел(имя) {
    var все = (РАСКЛАД.sideleft || []).concat(РАСКЛАД.sideright || []);
    var видимые = все.map(function (id) {
      return { id: id, эл: document.getElementById(id) };
    }).filter(function (п) { return виден(п.эл); });

    if (!имя) {
      var короб = коробКоманды();
      короб.appendChild(el("div", "cmdhead", "Разделы, которые сейчас на экране:"));
      if (!видимые.length) {
        короб.appendChild(el("div", null,
          "Ни одного: разделы появляются, когда в них что-то есть."));
        return;
      }
      видимые.forEach(function (п) {
        // Имя раздела читается ИЗ РАЗМЕТКИ, а её переводит data-en рядом с
        // текстом, а не словарь: прогонять прочитанное через T() значило бы
        // искать в словаре уже переведённое.
        var кн = el("button", "chip");
        кн.textContent = имяРаздела(п.эл) || п.id;
        кн.type = "button";
        кн.addEventListener("click", function () { открытьРаздел(п.id); });
        короб.appendChild(кн);
      });
      return;
    }

    var н = имя.toLowerCase();
    var нашли = видимые.filter(function (п) {
      return п.id === н || (имяРаздела(п.эл) || "").toLowerCase().indexOf(н) >= 0;
    })[0];
    if (!нашли) {
      сказатьКомандой("Такого раздела на экране нет. Наберите «/раздел» " +
                      "без имени — покажу, какие есть.");
      return;
    }
    открытьРаздел(нашли.id);
  }

  function командаПроводник() { проводник(); }

  function командаЯзык(какой) {
    if (!window.ЯЗЫК || !window.ЯЗЫК.выбрать) {
      сказатьКомандой("Переключатель языка не подключился — обновите страницу.");
      return;
    }
    var н = (какой || "").toLowerCase();
    if (н && н !== "ru" && н !== "en") {
      сказатьКомандой("Языка два: ru и en.");
      return;
    }
    // Без довода — на другой, как и кнопка в шапке. Переключение
    // перезагружает страницу: надписи расставлены по всему коду, и обойти
    // их на лету значит получить наполовину переведённый экран.
    window.ЯЗЫК.выбрать(н || (window.ЯЗЫК.английский ? "ru" : "en"));
  }

  function командаОчистить() {
    var короб = коробКоманды();
    короб.appendChild(el("div", null, state.caseId
      ? "Уберу ленту с экрана. В деле ничего не изменится: переписка вернётся, когда откроете дело снова."
      : "Уберу ленту с экрана. Общий разговор нигде не хранится — вернуть показанное будет нечем."));
    var кн = el("button", "addone", "Очистить");
    кн.type = "button";
    кн.addEventListener("click", function () { log.innerHTML = ""; });
    короб.appendChild(кн);
  }

  /* Выход — единственная команда, которая может отнять.

     КНОПКИ «ВЫЙТИ» У АНОНИМА НЕТ НАМЕРЕННО, и довод записан рядом с ней:
     ключ этой сессии у него единственный, и «выйти» значит не выйти, а
     потерять свои дела навсегда. Команда, не знающая этого правила, вернула
     бы анониму ровно ту дверь, которую от него убрали, — и короткой дорогой,
     в два нажатия из «/вы».

     Поэтому сперва спрашиваем, есть ли чем вернуться, и при отрицательном
     ответе НЕ ВЫХОДИМ, а говорим, что сделать. Служба такой выход тоже
     отклоняет, но команда, отвечающая отказом, — то же обещание, которого мы
     не держим, что и кнопка. */
  async function командаВыход() {
    var входы = [];
    try {
      входы = ((await api("POST", "/entry/logins", {})) || {}).входы || [];
    } catch (e) {
      // Неизвестно — значит не выходим. Ошибиться здесь можно только в одну
      // сторону: несделанный выход человек повторит, потерянные дела — нет.
      сказатьКомандой(T("Не смог проверить, чем вы входите: ") + reason(e) +
                      T(". Выход отменён — попробуйте ещё раз."));
      return;
    }
    if (!входы.length) {
      var короб = коробКоманды();
      короб.appendChild(el("div", null,
        "Выходить пока некуда: этот ключ у вас единственный, и без " +
        "привязанного входа вернуться к своим делам будет нечем."));
      короб.appendChild(el("div", "cmdfoot",
        "Привяжите вход — Telegram, почту или номер, — и выход появится."));
      открытьРаздел("logins");
      return;
    }
    // Дальше — та же функция, что и у кнопки: второй путь к одному действию
    // не должен вести себя иначе, чем первый.
    await выйти(null);
  }

  /* Разбор поломок: не только показать, но и ЗАКРЫТЬ.

     ЧЕГО ЗДЕСЬ НЕ БЫЛО. Ручка решения `/ops/reports/{id}/state` построена, и
     дверь под неё открыта, и лекарь ею пользуется, — а из оболочки её не
     звал НИКТО. Значит `done` и `dropped` не проставлялись ниоткуда, кроме
     как руками через curl: список умел только расти, и «разобрать» на деле
     означало прочитать и забыть.

     ПОКАЗЫВАЕМ `open`, А НЕ `new`. С 02.09.2026 лекарь отмечает разобранное
     `taken` и кладёт рядом свой разбор. Останься здесь `new`, эти жалобы
     пропадали бы с экрана ровно в тот миг, когда по ним появилось что
     читать, — а закрыть их было бы уже нечем. */
  async function командаРазбор() {
    var свод = await api("GET", "/ops/reports?state=open&limit=20");
    var короб = коробКоманды();
    var шапка = el("div", "cmdhead", "Поломки без решения: ");
    шапка.appendChild(el("b", null, String(свод.всего)));
    короб.appendChild(шапка);
    if (!свод.сообщения.length) {
      короб.appendChild(el("div", null, "Пусто — за этим и следим."));
      return;
    }
    свод.сообщения.forEach(function (с) {
      короб.appendChild(строкаПоломки(с));
    });
    // ЧИСЛО В ШАПКЕ ПОСЛЕ РЕШЕНИЙ НЕ ПРАВИМ, и это выбор, а не недосмотр.
    // Короб живёт В ЛЕНТЕ: это запись о том, что было в минуту вопроса.
    // Переписать её задним числом — подделать собственную переписку; что
    // изменилось, видно построчно («закрыто: починено») и по числу в панели,
    // которое спрашивает дверь заново.

    // Обрезка НАЗВАНА. Молча показанные двадцать читаются как «всего
    // двадцать», и разбор идёт по неполной картине.
    if (свод.всего > свод.показано) {
      короб.appendChild(el("div", "cmdfoot",
        "Показаны последние двадцать; остальные — в scripts/reports.py."));
    }
  }

  /* Одна поломка: что написали, что уже нашёл лекарь, и чем её закрыть.

     ОТДЕЛЬНОЙ ФУНКЦИЕЙ — чтобы строку можно было отрисовать в node и
     посмотреть глазами проверки, что человек видит рядом с кнопкой. Тот же
     довод, что у `payoutRow`: решение, при котором не видно, о чём оно, от
     кнопки «да» ничем не отличается.

     ЗАПИСАННОЕ ПОКАЗЫВАЕМ ЦЕЛИКОМ И СРАЗУ. Человек закрывает жалобу по
     тому, что о ней уже известно; спрятать это под раскрытие значило бы
     просить решения вслепую — то самое, от чего список и заведён.

     В поле `решение` пишут двое: лекарь, когда отмечает жалобу взятой, и
     человек из `scripts/reports.py --note`. Рисуем как есть, чей бы ни был:
     оболочка не знает автора и знать не должна — рядом стоит подпись.

     ДО 02.09.2026 ЛЕКАРЬ КЛАЛ ТУДА ПОСТОЯННУЮ МЕТКУ, а разбор оставлял
     только в Telegram: этот блок показывал бы у каждой взятой жалобы одну и
     ту же фразу без единой находки. Починено в `примечание_разбора`
     (scripts/ops/remedy.py) тем же заходом — иначе кнопка ниже просила бы
     решения ровно так же вслепую, только с виду наоборот. */

  /* Строки ОДНОЙ И ТОЙ ЖЕ жалобы в разных коробах ленты, по ид.

     `/разбор` набирают дважды — и оба короба остаются в ленте живыми.
     Закрыв жалобу во втором, человек видит первый: та же строка, те же
     кнопки, никакой пометки. Нажатие там ПЕРЕПИШЕТ принятое решение —
     сторожа «уже решено» у службы нет, `done` молча станет `dropped`, а
     примечание затрётся словом из второго окна. Обратный порядок хуже:
     «починено» шлёт пустое примечание, служба оставляет прежнее, и запись
     читается как «починено» с причиной отклонения внутри.

     Поэтому решение гасит ВСЕ строки этой жалобы, а не только свою. Соседи
     (`renderDocs`, `renderPayouts`) избавлены от этого даром: они живут в
     панелях и перерисовываются с ответа службы целиком. Короб в ленте так не
     умеет — он запись о минуте, и переписывать её нельзя. */
  var строкиПоломок = Object.create(null);

  function строкаПоломки(с) {
    var строка = el("div", "cmdreport");
    строка.appendChild(el("div", "cmdwhat", с.что));
    var низ = el("div", "cmdnote", when(с.когда) + " · ");
    низ.appendChild(el("span", null, с.id));
    var о = с.обстановка || {};
    if (о.case) низ.appendChild(el("span", null, " · " + о.case));
    if ((о.errors || []).length) {
      низ.appendChild(el("span", "bad",
        " · " + о.errors[о.errors.length - 1].status +
        " " + о.errors[о.errors.length - 1].path));
    }
    строка.appendChild(низ);

    // «Взято» БЕЗ ЗАПИСИ тоже бывает: взять могли руками. Тогда говорим
    // только это и пустой строки разбора не рисуем — пустая читается как
    // «разобрали и ничего не нашли», а это совсем другое сообщение.
    //
    // Подпись отдельным узлом, а не склейкой: словарь ключуется целой
    // фразой, и «взято в разбор · remedy:codex» не совпало бы ни с чем —
    // по-английски строка молча осталась бы русской.
    if (с.исход === "taken") {
      var кем = el("div", "cmdnote", "взято в разбор · ");
      кем.appendChild(el("span", null, с.разобрал || "без подписи"));
      строка.appendChild(кем);
      if (с.решение) строка.appendChild(el("div", "cmdsample", с.решение));
    }

    var ряд = el("div", "cmdacts");
    var починено = el("button", "addone", "Починено");
    починено.type = "button";
    var отклонить = el("button", "addone danger", "Отклонить");
    отклонить.type = "button";

    // Погасить ЭТУ строку. Отдельной функцией, потому что зовут её не только
    // отсюда: решение гасит все строки этой жалобы, включая нарисованные
    // прежними коробами. Строку не убираем — исчезнувшая неотличима от
    // «нажал не туда».
    function погасить(исход) {
      ряд.innerHTML = "";
      ряд.appendChild(el("span", "cmdnote",
        исход === "done" ? "закрыто: починено" : "закрыто: отклонено"));
    }
    (строкиПоломок[с.id] || (строкиПоломок[с.id] = [])).push(погасить);

    function решить(исход, примечание) {
      return async function () {
        починено.disabled = true;
        отклонить.disabled = true;
        try {
          // `principal_id` не шлём: его подставляет дверь. Пошли мы его сами —
          // и браузер называл бы, кто разобрал.
          await api("POST",
                    "/ops/reports/" + encodeURIComponent(с.id) + "/state",
                    { state: исход, note: примечание });
          (строкиПоломок[с.id] || [погасить]).forEach(function (гасить) {
            гасить(исход);
          });
          delete строкиПоломок[с.id];
          // Число в панели считает ту же пару — значит оно только что
          // изменилось. Оставить его прежним значило бы соврать на соседнем
          // узле того же экрана.
          показатьСчётПоломок();
        } catch (e) {
          починено.disabled = false;
          отклонить.disabled = false;
          // ПРИСТАВКА ПЕРЕВОДИТСЯ ОТДЕЛЬНО ОТ ПРИЧИНЫ. Склей их до `el` — и
          // словарь не совпадёт ни с чем: ключ там целая фраза, а не начало
          // строки. Причину же через словарь гнать незачем, она приходит от
          // службы: каждая новая копилась бы в `ЯЗЫК.пропущенные()` ложным
          // промахом — тем самым, от которого бережётся `перечислитьКоманды`.
          var беда = el("div", "cmdnote", "Не вышло: ");
          var почемуНе = el("span");
          почемуНе.textContent = reason(e);
          беда.appendChild(почемуНе);
          строка.appendChild(беда);
        }
      };
    }

    // Пустое примечание у «починено» — не забывчивость: служба при пустом
    // ОСТАВЛЯЕТ прежнее (`WHEN $3 = '' THEN note`), то есть разбор лекаря
    // переживает закрытие. Прислать сюда свои слова значило бы затереть его.
    починено.addEventListener("click", решить("done", ""));

    отклонить.addEventListener("click", function () {
      // ПРИЧИНА ОБЯЗАТЕЛЬНА, и это требование службы, а не вежливость: на
      // отклонение без причины она отвечает 422. Спросить здесь — показать
      // человеку правило до отказа, а не после него.
      var почему = window.prompt(
        T("Чем это не поломка? Причина останется в списке рядом с сообщением."));
      if (почему === null) return;
      почему = String(почему).trim();
      if (!почему) {
        строка.appendChild(el("div", "cmdnote",
          "Без причины не отклоняю: через месяц «отклонено» само по себе " +
          "ничего не объяснит."));
        return;
      }
      решить("dropped", почему)();
    });

    ряд.appendChild(починено);
    ряд.appendChild(отклонить);
    строка.appendChild(ряд);
    return строка;
  }

  /* Довести до раздела: раскрыть, если свёрнут, и подвести взгляд.

     Раздела может не быть на экране вовсе — разделы появляются, когда в них
     что-то есть. Молчать в этом случае нельзя: человек набрал команду и
     решит, что страница подвисла. */
  function открытьРаздел(id) {
    var э = document.getElementById(id);
    if (!виден(э)) {
      сказатьКомандой("Этого раздела сейчас нет на экране: разделы " +
                      "появляются, когда в них что-то есть.");
      return false;
    }
    if (э.classList.contains("shut")) {
      э.classList.remove("shut");
      // Раскрытие — выбор человека, и он сильнее умолчания: записываем его
      // тем же ключом, что и складывание мышью.
      сохранить("fixar.shut." + id, "0");
    }
    э.scrollIntoView({ block: "center", behavior: "smooth" });
    // Тот же способ подсветки, что у проводника: раздел на экране бывает не
    // один, и без метки «вот он» команда выглядит как ничего не сделавшая.
    э.classList.add("tourhi");
    setTimeout(function () { э.classList.remove("tourhi"); }, 1800);
    return true;
  }

  /* Неизвестная команда МОДЕЛИ НЕ УХОДИТ.

     Отправить её значило бы потратить кредит человека на строку, которая
     явно не была обращением к агенту. Но и съесть молча нельзя: строка,
     начатая с косой черты, бывает и настоящей репликой — поэтому рядом с
     перечнем стоит кнопка, отправляющая её как есть. */
  function нетТакойКоманды(исходный) {
    var короб = коробКоманды();
    короб.appendChild(el("div", "cmdhead", "Такой команды нет. Есть эти:"));
    перечислитьКоманды(короб);
    var кн = el("button", "addone", "Всё-таки отправить как сообщение");
    кн.type = "button";
    кн.addEventListener("click", async function () {
      кн.disabled = true;
      // Пузырь человека нарисовал send() — второй раз его печатать нельзя.
      busy(true);
      try { await отправитьСлужбе(исходный); }
      finally { busy(false); input.focus(); }
    });
    короб.appendChild(кн);
  }

  async function выполнитьКоманду(разбор, исходный) {
    var к = найтиКоманду(разбор.имя);
    if (!к) { нетТакойКоманды(исходный); return; }
    try {
      await к.делать(разбор.довод);
    } catch (e) {
      // reason(e), а не e.message: detail приходит то строкой, то предметом.
      сказатьКомандой(T("Не вышло: ") + reason(e));
    }
  }

  /* Куда уходит реплика. Одним местом, потому что зовущих теперь двое:
     обычная отправка и кнопка «всё-таки отправить» у неизвестной команды.
     Две копии этой развилки разошлись бы при первой же правке раскатки. */
  async function отправитьСлужбе(text) {
    if (state.inbox === false) {
      await legacyTurn(text);
    } else {
      // Открытое дело называем явно: тогда сервер продолжает именно его, а
      // не угадывает по похожести на соседнее.
      await inboxTurn(text, state.caseId || "", null);
    }
  }

  async function send(text) {
    if (state.busy || !text.trim()) return;
    say("you", "Вы", text);
    /* КОМАНДА — НЕ РЕПЛИКА. Она не идёт службе разговора и не тратит
       кредитов, поэтому перехват стоит ЗДЕСЬ.

       До развилки Inbox/дело — чтобы работать одинаково на обоих путях: оба
       существующих коротких перехвата живут внутри inboxTurn и при
       `state.inbox === false` не работают вовсе.

       И ПОСЛЕ пузыря человека — свой печатать не надо, он уже на экране.
       Этой ошибкой страдают оба соседних перехвата: на «покажи ещё раз»
       фраза видна дважды. */
    /* Номер разговора спросили словами — отвечаем тем же, чем и команда.

       ЗДЕСЬ, А НЕ В `inboxTurn` РЯДОМ С СОСЕДЯМИ: оба соседних перехвата
       живут внутри inboxTurn и при `state.inbox === false` не работают вовсе.
       Один и тот же вопрос не должен получать два разных ответа в зависимости
       от того, каким путём идут сообщения. */
    if (СПРОСИЛИ_НОМЕР.test(text)) {
      командаНомер();
      input.focus();
      return;
    }
    var разбор = командаИз(text);
    if (разбор) {
      закрытьПодсказку();
      busy(true);
      try { await выполнитьКоманду(разбор, text); }
      finally { busy(false); input.focus(); }
      return;
    }
    // ЗАНЯТОСТЬ — ДО ВОПРОСА, а не после: пока карточка ждёт ответа, второе
    // нажатие «Отправить» ушло бы вторым ходом (находка ревью 13.09.2026).
    busy(true);
    try {
      // Спросить про заграницу ДО того, как текст уйдёт службе: ответ модели и
      // есть передача. Знакомство уже спросило — здесь промис вернётся сразу.
      if (!(await спроситьПроЗаграницу(false, "send"))) {
        // Карточку убрали, не ответив: сообщение не ушло и возвращается в поле.
        say("system", "", "Сообщение не отправлено: сначала ответьте на вопрос о передаче за рубеж.");
        input.value = text;
        return;
      }
      await отправитьСлужбе(text);
    } finally {
      busy(false);
      input.focus();
    }
  }

  /* Пути показываются карточками, а выбирает человек. Решить за него значит
     потратить его время и деньги на путь, которого он не просил. */
  function showWays(ways, question) {
    var box = el("div", "ways");
    box.appendChild(el("div", "wayshead", "Могу пойти дальше так — выберите:"));
    ways.forEach(function (w) {
      var c = el("button", "way");
      c.type = "button";
      var t = el("div", "waytop");
      t.appendChild(el("div", "wayname", w.title));
      t.appendChild(el("div", "waygo", "→"));
      c.appendChild(t);
      c.appendChild(el("div", "waysum", w.summary));

      // Раскрытие обязательно и рядом: кто платит и чего не проверяли.
      var d = el("div", "disclose");
      d.appendChild(el("span", "dot" + (w.commercial === "sponsored" ? " paid" : "")));
      d.appendChild(el("span", null,
        w.commercial === "sponsored"
          ? T("оплаченное размещение · комиссия ") + (w.commission_bps / 100) + "%"
          : "органический · комиссии нет"));
      (w.unverified || []).forEach(function (u) {
        d.appendChild(el("span", null, "· " + u));
      });
      c.appendChild(d);

      c.addEventListener("click", function () {
        box.remove();
        goWay(w.way, question);
      });
      box.appendChild(c);
    });
    log.appendChild(box);
    log.scrollTop = log.scrollHeight;
  }

  async function goWay(way, question) {
    busy(true);
    var thinking = думает();
    try {
      var r = await api("POST", "/dialog/way", {
        case_id: state.caseId, way: way, question: question });
      thinking.parentNode.remove();
      say("bot", "Ф", r.reply);
      if (r.note) {
        var n = el("div", "waynote", r.note);
        log.appendChild(n);
      }
    } catch (e) {
      thinking.parentNode.remove();
      сорвалось(T("Не получилось: "), e);
    } finally {
      busy(false);
      input.focus();
    }
  }

  function currentTitle() {
    var s = START.filter(function (x) { return x.domain === state.domain; })[0];
    return s ? s.title : state.domain;
  }

  /* Примеры, а не выбор направления: направление определится само. Примеры
     нужны, чтобы человек понял, о чём тут вообще можно говорить. */
  /* Четвёртый пример — ПО-АНГЛИЙСКИ, и он стоит в каждом списке.

     Примеры не переводятся: они не идут через T() и не лежат в словаре —
     это живая речь человека, а не подпись оболочки. Значит английскую
     версию сайта встречали три русские строки, и пришедший по-английски
     читал их как «здесь говорят не на моём языке» — при том что служба
     отвечает на обоих.

     Один пример из четырёх снимает это, не переводя остальные три: он
     показывает, что войти можно с любой стороны. Строка ОДНА и та же в
     обеих версиях, а не подменяется по языку, — русскому читателю она
     говорит ровно то же самое про его англоязычных собеседников. */
  var EXAMPLES = [
    "Купил студию без отделки, надо сделать ремонт до сентября",
    "Ищу квартиру посуточно в Петербурге на три ночи",
    "Нужен курс по прикладной математике для сына",
    "Rent a flat in Moscow for a month"
  ];

  /* Примеры ПОД СЦЕНАРИЙ. Это и есть то, что читает сохранённый выбор
     онбординга при каждом входе: практику незачем примеры про поиск курса,
     а хозяину техники — про съём квартиры. Ключи обязаны совпадать со
     словарём сценариев службы — расхождение ловит тест, как у обещаний.

     Сценарий без своей строки здесь — законно: покажутся общие EXAMPLES. */
  var ПРИМЕРЫ_СЦЕНАРИЯ = {
    cases: [
      "Новый клиент: составить договор подряда до пятницы",
      "Напомни за три дня до срока по делу Ивановых",
      "Заведи дело: спор с поставщиком из-за просрочки",
      "Open a case: unpaid contractor invoice"
    ],
    find: EXAMPLES,
    offer: [
      "Сдаю экскаватор-погрузчик со сменой оператора",
      "Размещу объявление: ремонт квартир под ключ",
      "Сдаю студию посуточно у метро",
      "List a minibus for rent with a driver"
    ],
    guest: EXAMPLES
  };

  function примерыДляСценария() {
    return ПРИМЕРЫ_СЦЕНАРИЯ[state.scenario] || EXAMPLES;
  }

  /* Примеры СВЁРНУТЫ, и нажатие по ним НЕ отправляет.

     Прежде три примера лежали развёрнутыми прямо над полем ввода, а нажатие
     звало send() сразу. На телефоне это значит: задел большим пальцем —
     отправил чужой текст и завёл дело. Так за один вечер 18.08.2026
     появились дела «Купил студию без отделки…» и «Ремонт студии до
     сентября» — обе строки дословно из этого списка, человек их не писал.

     Поэтому две правки, и вторая важнее первой:

     1. свёрнуты за «Примеры» — случайно задеть теперь нечего;
     2. нажатие КЛАДЁТ ТЕКСТ В ПОЛЕ, а не отправляет. Тот же порядок, что у
        голоса и у панели: наружу уходит только то, что человек увидел и
        отправил сам. Одного сворачивания мало — развернув список, он снова
        оказался бы в одном касании от чужого сообщения. */
  function startChips() {
    chips.innerHTML = "";
    var раскрыто = false;

    var переключатель = el("button", "chip chip-more", "Примеры");
    переключатель.type = "button";
    переключатель.setAttribute("aria-expanded", "false");
    var короб = el("div", "chipbox");
    короб.hidden = true;

    примерыДляСценария().forEach(function (t) {
      var c = el("button", "chip", t.length > 46 ? t.slice(0, 44) + "…" : t);
      c.type = "button";
      c.title = T(T("Подставить в поле: ") + t);
      c.addEventListener("click", function () {
        // Не send. Человек прочтёт, поправит под себя и отправит сам.
        input.value = t;
        input.focus();
        try { input.setSelectionRange(t.length, t.length); } catch (e) { /* не всякое поле умеет */ }
      });
      короб.appendChild(c);
    });

    переключатель.addEventListener("click", function () {
      раскрыто = !раскрыто;
      короб.hidden = !раскрыто;
      переключатель.setAttribute("aria-expanded", раскрыто ? "true" : "false");
      переключатель.textContent = T(раскрыто ? "Скрыть примеры" : "Примеры");
    });

    chips.appendChild(переключатель);
    chips.appendChild(короб);
  }

  document.getElementById("composer").addEventListener("submit", function (e) {
    e.preventDefault();
    var t = input.value;
    /* ПОЛЕ ЧИСТИМ, ТОЛЬКО КОГДА ХОД ПРИНЯТ.

       Прежде чистили ДО `send()`, а тот на занятости выходил молча — и
       набранное пропадало без следа: поле пустое, в ленте ничего, человек
       уверен, что отправил. Правило против этого в оболочке уже записано, и
       записано теми же словами, — но у соседней двери, у холста:
       «Молча проглотить значило бы потерять набранное: поле в полосе уже
       очищено, и человек решил бы, что отправилось» (`изХолста`). К главному
       полю его не применили.

       Проверку занятости делаем ЗДЕСЬ, а не полагаемся на ту, что внутри
       `send()`: та асинхронная, а решение про поле — синхронное, и узнать
       ответ `send()` до чистки нельзя. Внутренняя при этом остаётся: у
       `send()` есть и второй звонящий (холст), у которого своего поля нет.

       НАСКОЛЬКО ЭТО ДОСТУПНО ЧЕЛОВЕКУ, СКАЗАНО ЧЕСТНО: на время хода
       `busy(true)` гасит и поле, и кнопку, так что обычным путём сюда почти
       не попасть. Но «почти» тут держится на одном свойстве разметки, а цена
       промаха — потерянная реплика. */
    if (state.busy) {
      if (!сказалиПроЗанятость) {
        сказалиПроЗанятость = true;
        сказатьКомандой("Предыдущий вопрос ещё в работе — отвечу и возьмусь " +
                        "за этот. Набранное осталось в поле, оно не пропало.");
      }
      return;
    }
    input.value = "";
    send(t);   // направление определится само по первому сообщению
  });

  /* ── Голос ────────────────────────────────────────────────────────── */

  /* Распознавание браузерное. Серверное сейчас невозможно: voice-service ходит
     к ASR напрямую по MIMO_API_KEY, а его в aiOS нет и быть не должно —
     ключ живёт только у AgriForest. Мост распознавание пока не отдаёт.
     Браузерное работает сегодня, ничего не стоит и не требует ключей.

     Распознанное попадает В ПОЛЕ, а не отправляется само: ослышка в вопросе о
     здоровье не должна уходить агенту, и человек обязан увидеть, что понято. */

  function setupVoice() {
    var Rec = window.SpeechRecognition || window.webkitSpeechRecognition;
    var btn = document.getElementById("mic");
    if (!Rec || !btn) {
      // Не показываем кнопку, которая не работает: молчащий микрофон хуже
      // отсутствующего.
      if (btn) btn.remove();
      return;
    }

    var rec = new Rec();
    rec.lang = "ru-RU";
    rec.continuous = false;
    rec.interimResults = true;
    var base = "", on = false;

    function stop() {
      on = false;
      btn.classList.remove("rec");
      btn.setAttribute("aria-label", "Сказать голосом");
      try { rec.stop(); } catch (e) { /* уже остановлено */ }
    }

    rec.onresult = function (e) {
      var text = "";
      for (var i = e.resultIndex; i < e.results.length; i++) {
        text += e.results[i][0].transcript;
      }
      input.value = (base + " " + text).trim();
    };
    rec.onerror = function (e) {
      stop();
      if (e.error === "not-allowed" || e.error === "service-not-allowed") {
        say("bot", "Ф", "Браузер не дал доступ к микрофону. " +
            "Разрешите его в настройках сайта — или просто напишите.");
      }
    };
    rec.onend = function () { stop(); input.focus(); };

    btn.addEventListener("click", function () {
      if (on) { stop(); return; }
      base = input.value.trim();
      on = true;
      btn.classList.add("rec");
      btn.setAttribute("aria-label", "Остановить запись");
      try { rec.start(); } catch (e) { stop(); }
    });
  }

  /* ── Онбординг: первый разговор, детерминированный ─────────────────────

     Один вопрос — «как вам удобнее начать?» — и рабочее место настраивается
     под ответ: примеры под полем становятся про его занятие, а подсказка
     говорит про его путь, а не про все сразу.

     НИ ОДНОГО ВЫЗОВА МОДЕЛИ, и это граница, а не экономия. Ёмкость: модель
     тянет считаные вызовы в минуту на всю площадку, знакомство новичка не
     имеет права её съедать. Периметр: первое обращение разговора читается
     облачной моделью, а онбординг — рассказ человека о себе; он не должен
     уезжать за периметр первым же сообщением.

     КНОПКИ РИСУЮТСЯ ПО СЛОВАРЮ СЛУЖБЫ, который приезжает с prefs: своего
     списка сценариев у оболочки нет, и разойтись со службой ему нечем.
     Подсказки под сценарий — здесь (они про наши разделы), и их ключи
     сверяет тест.

     Пропуск — тоже ответ и тоже закрывает онбординг: переспрашивать
     пропустившего при каждом входе значит наказывать за отказ отвечать. */

  //: Что сказать после выбора. Две-три строки про ЕГО путь; ключи обязаны
  //: совпадать со словарём службы (стережёт тест, как у обещаний).
  var ПОДСКАЗКИ_СЦЕНАРИЯ = {
    cases: "Дела собираются из разговора — заполнять формы не надо. Слева " +
      "будет список ваших дел: по отметкам видно, которое требует вас " +
      "сейчас. Расскажите про первое дело своими словами.",
    find: "Расскажите своими словами, что нужно, — я отнесу это к " +
      "направлению и позову подходящего собеседника. Дело заведётся только " +
      "после вашего согласия.",
    offer: "Ваше рабочее место — кабинет и объявления: что предлагаете, на " +
      "каких условиях и чего не делаете. Объявление идёт путём черновик → " +
      "подача → проверка площадкой; показать его людям можно после " +
      "подтверждения — телефон или Telegram, минута.",
    guest: "Осмотритесь спокойно: разговор ни к чему не обязывает, дело без " +
      "вашего согласия не заведётся. Могу показать, что тут есть."
  };

  async function онбординг(prefs) {
    say("bot", "Ф", "Как вам удобнее начать? Настрою рабочее место под ваш " +
        "ответ — это один вопрос, дальше просто разговариваем.");

    var ряд = el("div", "ways");
    var занято = false;

    async function выбрать(ключ, подпись) {
      if (занято) return;                       // двойное нажатие — один ответ
      занято = true;
      ряд.remove();
      if (подпись) say("me", "", подпись);
      // Выбор уходит на сервер: он должен пережить вкладку и устройство.
      // Не доехал — покажем вопрос в следующий раз; молча терять выбор
      // нельзя, но и останавливать человека из-за сети — тоже.
      try {
        var ответ = await api("PUT", "/workspace/prefs", { scenario: ключ });
        state.scenario = ключ;
        state.onboarded = true;
        // Раскладка приезжает тем же ответом — перечитывать рабочее место
        // ради того, что уже решено этим запросом, незачем.
        применитьРаскладку((ответ || {}).layout);
      } catch (e) { /* спросим в следующий раз */ }
      startChips();                             // примеры — уже под сценарий
      var текст = ПОДСКАЗКИ_СЦЕНАРИЯ[ключ];
      if (текст) say("bot", "Ф", текст);
      // ВТОРОЙ ВОПРОС ЗНАКОМСТВА — О ПЕРЕДАЧЕ ЗА РУБЕЖ, и задаётся явно
      // (решение владельца 13.09.2026). После ответа на первый, а не вместе с
      // ним: по одному вопросу за раз. Кнопки «дальше» — после ответа.
      await спроситьПроЗаграницу(false, "onboarding");
      // Два пути дальше — те же, что и всегда: словами или осмотреться.
      var хвост = el("div", "ways");
      var показать = el("button", "addone", "Покажите, что тут есть");
      показать.type = "button";
      показать.addEventListener("click", function () { проводник(); });
      var словами = el("button", "addone", "Расскажу словами");
      словами.type = "button";
      словами.addEventListener("click", function () {
        хвост.remove();
        input.focus();
      });
      хвост.appendChild(словами);
      хвост.appendChild(показать);
      log.appendChild(хвост);
      log.scrollTop = log.scrollHeight;
    }

    Object.keys(prefs.scenarios || {}).forEach(function (ключ) {
      var б = el("button", "addone", prefs.scenarios[ключ]);
      б.type = "button";
      б.addEventListener("click", function () {
        выбрать(ключ, prefs.scenarios[ключ]);
      });
      ряд.appendChild(б);
    });
    var мимо = el("button", "addone", "Просто расскажу словами");
    мимо.type = "button";
    мимо.addEventListener("click", function () {
      выбрать("", "");
      input.focus();
    });
    ряд.appendChild(мимо);
    log.appendChild(ряд);
    log.scrollTop = log.scrollHeight;
  }

  /* ── Передача за рубеж ────────────────────────────────────────────────
     Тот же вопрос, что на главном экране, тем же текстом службы и с той же
     записью ответа. Здесь он встаёт в двух местах: шагом знакомства — ПОСЛЕ
     вопроса «как вам удобнее начать», по одному вопросу за раз, — и перед
     первой отправкой у тех, кто знакомство уже прошёл. Отвечавший на этом
     языке не спрашивается. Служба молчит — разговор не держим: прежний
     порядок назван в шлюзе, а решать его в оболочке нельзя. */
  var ЗАГРАНИЦА = { прочитано: false, ответ: null, ждём: null };

  function языкЗаграницы() {
    return (window.ЯЗЫК && window.ЯЗЫК.английский) ? "en" : "ru";
  }

  async function прочитатьЗаграницу() {
    if (!state.principal) return null;
    try {
      var r = await api("GET", "/principals/" + encodeURIComponent(state.principal) +
                        "/cross-border");
      ЗАГРАНИЦА.прочитано = true;
      ЗАГРАНИЦА.ответ = r;
      return r;
    } catch (e) {
      return null;
    }
  }

  function спроситьПроЗаграницу(заново, повод) {
    if (ЗАГРАНИЦА.ждём) return ЗАГРАНИЦА.ждём;
    ЗАГРАНИЦА.ждём = (async function () {
      var r = (ЗАГРАНИЦА.прочитано && !заново) ? ЗАГРАНИЦА.ответ
        : await прочитатьЗаграницу();
      if (!r) return true;
      var по = r.current_by_lang;
      if (по && typeof по === "object" && по[языкЗаграницы()] && !заново) return true;
      var q = r.question || {};
      var в = q[языкЗаграницы()] || q.ru;
      if (!в) return true;
      return await new Promise(function (готово) {
        var пузырь = say("bot", "Ф", в.text);
        if (повод === "onboarding" && пузырь) пузырь.setAttribute("role", "alert");
        var ряд = el("div", "ways");
        // КНОПКИ СЛЕДЯТ ЗА СОБОЙ: ленту стирают при открытии дела и командой
        // «очистить», и висящий промис держал бы отправку вечно. Исчезли —
        // ожидание кончается ответом «не отвечено».
        var сторож = null;
        function завершить(итог) {
          if (сторож) { сторож.disconnect(); сторож = null; }
          готово(итог);
        }
        if (window.MutationObserver) {
          сторож = new MutationObserver(function () {
            if (!ряд.isConnected) завершить(false);
          });
          сторож.observe(log, { childList: true });
        }
        ["foreign", "ru"].forEach(function (ответ) {
          var б = el("button", "addone", в.answers[ответ]);
          б.type = "button";
          б.addEventListener("click", async function () {
            ряд.querySelectorAll("button").forEach(function (x) { x.disabled = true; });
            try {
              await api("PUT", "/principals/" + encodeURIComponent(state.principal) +
                        "/cross-border",
                        { max_jurisdiction: ответ, text_digest: в.digest,
                          context: повод || "send" });
              var новое = Object.assign({}, по || {});
              новое[языкЗаграницы()] = true;
              ЗАГРАНИЦА.ответ = Object.assign({}, r, { asked: true, current: true,
                current_by_lang: новое, max_jurisdiction: ответ });
              // ОТВЕЧЕННЫЙ ВОПРОС УХОДИТ ИЗ ЛЕНТЫ — остаётся одна строка о
              // записанном (владелец 13.09.2026: «окно чата не очищается»).
              // Сторож снимается ДО удаления, иначе примет его за «убрали».
              завершить(true);
              ряд.remove();
              var строка = пузырь && пузырь.parentNode;
              if (строка && строка.parentNode === log) строка.remove();
              say("system", "", T("Записано: ") + в.answers[ответ] + ". " +
                  T("Изменить решение можно переключателем вверху главного экрана."));
            } catch (e) {
              ряд.querySelectorAll("button").forEach(function (x) { x.disabled = false; });
              if (e.status === 409) {
                if (сторож) { сторож.disconnect(); сторож = null; }
                ряд.remove();
                ЗАГРАНИЦА.прочитано = false;
                ЗАГРАНИЦА.ждём = null;
                завершить(await спроситьПроЗаграницу(true, повод));
                return;
              }
              say("system", "", T("Ответ не записался. Попробуйте ещё раз."));
            }
          });
          ряд.appendChild(б);
        });
        log.appendChild(ряд);
        log.scrollTop = log.scrollHeight;
      });
    })();
    ЗАГРАНИЦА.ждём.then(function () { ЗАГРАНИЦА.ждём = null; },
                        function () { ЗАГРАНИЦА.ждём = null; });
    return ЗАГРАНИЦА.ждём;
  }

  /* ── Тема: расставить токены ──────────────────────────────────────────

     Тема приходит ДАННЫМИ — готовые значения переменных, посчитанные и
     проверенные службой. Оболочке считать нечего и решать нечего: она их
     только расставляет.

     ПОЧЕМУ ЗДЕСЬ ЕСТЬ СВОЙ СПИСОК ИМЁН, хотя служба уже проверила. Значение
     токена попадает в setProperty, то есть в CSS. Служба стережёт это своими
     проверками — но между службой и этой строкой лежит сеть, и доверять
     чужому ответу «он же проверенный» — то же самое, что не проверять.
     Незнакомое имя пропускается молча: служба может знать больше этой версии
     оболочки, и это не повод впускать неизвестное в стили.

     Значение сверяется образцом ЗДЕСЬ ЖЕ по той же причине: «#1a2b3c» — цвет,
     а «#fff; background:url(//чужой/х)» — уже не цвет, а правило. */

  //: Имена переменных, которые тема вправе задать. Закрытый список.
  var ТОКЕНЫ_ТЕМЫ = [
    "--ground", "--panel", "--panel-2", "--panel-side",
    "--hair", "--hair-soft", "--line", "--hair-side",
    "--ink", "--ink-2", "--ink-3", "--ink-3-side",
    "--brass", "--brass-dim", "--link", "--ok", "--you",
    "--sans", "--mono"
  ];

  //: Цвет — шесть шестнадцатных знаков. Шрифт — набор имён через запятую,
  //: без скобок и адресов: url() внутри font-family это загрузка с чужого
  //: сервера, то есть отпечаток посетителя на стороне автора темы.
  var ЦВЕТ_ТОКЕНА = /^#[0-9a-f]{6}$/i;
  var ШРИФТ_ТОКЕНА = /^[a-zA-Zа-яА-Я0-9 ,"'\-]{2,200}$/;

  function применитьТему(токены) {
    var корень = document.documentElement;
    if (!корень || !корень.style) return 0;
    // СНАЧАЛА СНИМАЕМ ПРЕЖНЕЕ. Иначе смена темы накладывается на старую:
    // новая не назвала --you — и он остаётся от прошлой, посреди чужой
    // палитры. Снимаем только СВОИ имена: чужого здесь не ставили.
    for (var i = 0; i < ТОКЕНЫ_ТЕМЫ.length; i++) {
      корень.style.removeProperty(ТОКЕНЫ_ТЕМЫ[i]);
    }
    if (!токены) return 0;                     // системная палитра
    var поставлено = 0;
    for (var j = 0; j < ТОКЕНЫ_ТЕМЫ.length; j++) {
      var имя = ТОКЕНЫ_ТЕМЫ[j];
      var знач = токены[имя];
      if (typeof знач !== "string") continue;
      var годно = (имя === "--sans" || имя === "--mono")
        ? ШРИФТ_ТОКЕНА.test(знач)
        : ЦВЕТ_ТОКЕНА.test(знач);
      if (!годно) continue;                    // не цвет и не шрифт — мимо
      корень.style.setProperty(имя, знач);
      поставлено += 1;
    }
    return поставлено;
  }

  /* ── Раскладка: порядок разделов приходит данными ─────────────────────

     Порядок в разметке выверен под ОДНО занятие — практика с кабинетом
     («ближайшее выше картотеки: пропущенный срок стоит дела»). Доводы верные,
     но верные именно для него: у хозяина техники объявления и есть его
     работа, а сроков и картотеки у него пока нет вовсе.

     РАСКЛАДКА ТОЛЬКО ПЕРЕСТАВЛЯЕТ, и это её главное свойство. Спрятать раздел
     она не может: что показать, решает наличие содержимого, и это правило
     старше раскладки. Раздел, не названный в раскладке, встаёт ПОСЛЕ
     названных — не исчезает; раздел, названный, но неизвестный оболочке,
     пропускается молча. Так служба, знающая больше или меньше нашей версии,
     не может ничего потерять.

     Переставляем УЗЛЫ, а не классы: у каждого раздела свой код показа и
     обновления, и он про порядок ничего не знает — и не должен. */
  //: Контейнеры разделов рабочего места. НАЗВАНЫ ЯВНО, а не выведены из
  //: первого названного узла: раскладка приходит от службы, и первым в ней
  //: может оказаться чужой узел — тогда переставлять начали бы чужую разметку
  //: по чужой просьбе. Поймано тестом.
  //:
  //: ЗДЕСЬ СТОЯЛ ОДИН КОНТЕЙНЕР — "casepane", — И ЭТО БЫЛА МЁРТВАЯ СТРОКА.
  //: 23.08.2026 раскладку переделали: layoutPanes при загрузке страницы
  //: раскидывает разделы по двум зонам, а опустевшую панель дела УДАЛЯЕТ
  //: (см. `старая.remove()`). С того дня и до 28.08 эта функция искала узел,
  //: которого в DOM нет, и молча возвращала ноль — то есть вопрос «Как вам
  //: удобнее начать? Настрою рабочее место под ваш ответ» не настраивал
  //: ничего. Проверено на живом agrigate.pro: getElementById("casepane")
  //: возвращает null. Ровно та болезнь, за которой мы охотились неделю:
  //: объявлено, выглядит рабочим, никем не проверено результатом.
  var КОНТЕЙНЕРЫ_РАЗДЕЛОВ = ["sideleft", "sideright"];

  function применитьРаскладку(порядок) {
    if (!порядок || !порядок.length) return 0;   // нечего переставлять
    var переставлено = 0;
    КОНТЕЙНЕРЫ_РАЗДЕЛОВ.forEach(function (имяЗоны) {
      var родитель = document.getElementById(имяЗоны);
      if (!родитель) return;
      var свои = РАСКЛАД[имяЗоны] || [];
      /* ОТКУДА НАЧИНАТЬ. Не с нуля: в правой зоне первым стоит заголовок
         «Дело» со значком живого дела — его layoutPanes кладёт туда раньше
         разделов. Вставив раздел на место 0, мы задвинули бы заголовок вниз,
         и колонка начиналась бы с середины. Поэтому место отсчитывается от
         ПЕРВОГО НАСТОЯЩЕГО РАЗДЕЛА, а всё, что стоит выше него, не трогается
         вовсе. */
      var место = 0;
      while (место < родитель.children.length &&
             свои.indexOf(родитель.children[место].id) < 0) {
        место += 1;
      }
      // Идём ВПЕРЁД и ставим каждый названный раздел на очередное место.
      // Узел уже там — не трогаем вовсе: перестановка на то же место дёргает
      // разметку и сбрасывает прокрутку внутри раздела.
      for (var i = 0; i < порядок.length; i++) {
        var узел = document.getElementById(порядок[i]);
        // Неизвестный раздел или чужой контейнер — пропускаем молча: служба
        // может знать больше или меньше этой версии оболочки, и ни то ни
        // другое не должно ничего терять или ломать. Раздел из СОСЕДНЕЙ зоны
        // тоже пропускается: раскладка переставляет внутри колонки, а не
        // перекидывает разделы между колонками — за это отвечает РАСКЛАД.
        if (!узел || узел.parentNode !== родитель) continue;
        var занятый = родитель.children[место] || null;
        if (занятый !== узел) родитель.insertBefore(узел, занятый);
        место += 1;
        переставлено += 1;
      }
    });
    return переставлено;
  }

  //: Прочитать рабочее место. Молчание службы — НЕ повод для онбординга:
  //: onboarded остаётся null, и вопрос не задаётся. Лучше не спросить один
  //: раз, чем спрашивать заново при каждом сбое сети.
  async function загрузитьРабочееМесто() {
    try {
      var p = await api("GET", "/workspace/prefs/" + state.principal);
      state.scenario = p.scenario || "";
      state.onboarded = !!p.onboarded;
      // Тема — ПЕРВОЙ и до раскладки: цвет страницы человек замечает раньше
      // порядка разделов, и менять его после того, как он начал читать,
      // неприятнее всего.
      применитьТему(p.theme_tokens);
      // Раскладка применяется СРАЗУ, до приветствия: переставлять разделы на
      // глазах у человека, уже начавшего читать, — хуже, чем не переставлять.
      применитьРаскладку(p.layout);
      return p;
    } catch (e) {
      return null;
    }
  }

  /* ── Пуск ─────────────────────────────────────────────────────────── */

  /* Включён ли общий разговор — спрашиваем службу, а не гадаем. В режиме
     shadow новых путей нет ни у кого, и узнать это до первого сообщения
     честнее, чем показать общий разговор и уронить его в 404. Точный ответ
     всё равно даёт первая отправка: cohort считается по субъекту, и режим
     live ещё не значит «включено вам». */
  async function probeInbox() {
    try {
      var h = await (await fetch(API + "/health")).json();
      var roll = (h || {}).inbox_rollout || {};
      var mode = roll.mode;
      // Молчание health-check не считаем разрешением: неизвестное остаётся
      // неизвестным, и выясняется оно на первой отправке.
      if (mode && mode !== "live") { state.inbox = false; return; }
      // mode=live ещё не значит «включено вам»: cohort считается по субъекту.
      // Но два числа рядом отвечают на это точно: при нулевом проценте и
      // пустом списке путь не открыт НИКОМУ, и обещать общий разговор в
      // приветствии — прямая неправда. Прежде читался только mode, и при
      // percent=10 оболочка обещала общий разговор девяти людям из десяти,
      // которым он закрыт.
      if (mode === "live" &&
          Number(roll.percent || 0) === 0 &&
          Number(roll.allowlist_count || 0) === 0) {
        state.inbox = false;
      }
    } catch (e) { /* не узнали — выяснится на первой отправке */ }
  }

  (async function () {
    // Заставка заводится ДО первого запроса и снимается в finally: пуск
    // кончается и успехом, и отказом, а закрыть её обязаны оба раза.
    var убратьЗаставку = пусковойЭкран();
    // Речь заводим ДО первого обращения к службе и вне try: голос живёт на
    // устройстве, шлюз ему не нужен, и молчать из-за оборванной связи ему
    // незачем. Стояло ниже — при недоступной службе кнопка не появлялась
    // вовсе, хотя читать было чем.
    речьЗавести();
    try {
      var me = await ensureSession();
      // Слоты стали именными — чужие прибираем сразу после того, как узнали
      // имя. Оставить их значит однажды предложить человеку повторить чужое
      // подтверждение.
      dropOtherSlots(SENT_PREFIX);
      dropOtherSlots(CONFIRM_PREFIX);
      await probeInbox();
      // Рабочее место читаем ДО приветствия: от него зависит, задавать ли
      // вопрос онбординга и какие примеры показать под полем.
      var место = await загрузитьРабочееМесто();
      stateEl.textContent = T("сервис отвечает");
      stateEl.className = "state live";
      notice.hidden = false;
      // Вошедшему нельзя говорить «вы вошли без регистрации»: это прямо
      // противоречит его же имени в шапке, и человек перестаёт верить обоим.
      notice.innerHTML = T(me.signed_in
        ? "<b>Вы вошли.</b> Дела и разговор — ваши, они были вашими с первого " +
          "сообщения. Теперь можно подписывать обязательства и звать людей в дело."
        : "<b>Разговор идёт по-настоящему.</b> Вы вошли без регистрации: " +
          "дело принадлежит вам с первого сообщения, а войти можно позже — " +
          "разговор при этом не потеряется. Пока без входа нельзя подписывать " +
          "обязательства и приглашать контрагентов.");
      // ФИКСАР НАЗЫВАЕТ СЕБЯ ПЕРВЫМ, до всякого вопроса. Человеку, которому
      // отвечает безымянный текст, неизвестно, с кем он имеет дело: с живым
      // сотрудником, с ботом, с рекламой. От этого зависит, что он расскажет
      // и чему поверит, — а мы спрашиваем у него о его деле. Значит первыми
      // называем себя.
      //
      // Перечня возможностей здесь нет намеренно: человек пришёл со своим
      // делом, а не выбирать из меню, и список заставил бы его переводить
      // своё дело на наш язык.
      say("bot", "Ф", "Здравствуйте. Я ФиксАР — помогаю довести дело до " +
          "конца: найти исполнителя, разместить свою услугу, собрать бумаги, " +
          "договориться о сроке.");

      // ПЕРВЫЙ РАЗГОВОР — ОДИН ВОПРОС ВМЕСТО ОБЪЯСНЕНИЙ. Если человек здесь
      // впервые (служба ответила и сказала «онбординга не было»), вместо
      // второго сообщения и двух кнопок задаётся вопрос сценария — и
      // рабочее место настраивается под ответ. Служба промолчала — идём
      // старым путём: лучше не спросить один раз, чем спрашивать при каждом
      // сбое сети.
      if (место && state.onboarded === false) {
        // ВМЕСТО, а не ПЕРЕД: вопрос сценария заменяет второе сообщение и
        // кнопки — три обращения подряд превратили бы знакомство в допрос.
        // Остальной пуск идёт как всегда: return здесь оборвал бы обработчики
        // и загрузку разделов, и новичок получил бы мёртвую страницу.
        онбординг(место);
      } else {
      // Приветствие говорит правду о том, куда попадёт сказанное: обещать
      // общий разговор там, где он закрыт флагом, значит соврать в первой же
      // строке.
      // Три состояния, а не два. Прежде их было два, и неизвестность
      // печаталась как обещание: при mode=live и percent=10 оболочка говорила
      // «дело само не заведётся» девяти людям из десяти, которым путь закрыт,
      // — а следующее их сообщение уходило в откат и заводило дело.
      say("bot", "Ф", state.inbox === false
        ? "Расскажите своими словами, что нужно — я пойму, к чему это " +
          "относится, и позову подходящего собеседника. Общий разговор пока " +
          "не включён, поэтому сказанное заведёт или продолжит дело."
        : state.inbox === null
          ? "Расскажите своими словами, что нужно — я пойму, к чему это " +
            "относится, и позову подходящего собеседника. Включён ли для вас " +
            "общий разговор, выяснится на первом сообщении: обещать заранее " +
            "не буду. Дело без вашего согласия не заведётся в любом случае."
          : "Расскажите своими словами, что нужно. Это общий разговор: дело из " +
            "него само не заведётся — если из сказанного получится задача, я " +
            "предложу завести, и заведётся она только после вашего согласия.");
      // Два пути, и выбор явный. По умолчанию человек рассказывает словами —
      // так он получает пользу, не изучая интерфейс. Но 185 привязок из 185
      // сидят на нулевом уровне доверия: интерфейс им незнаком, и тем, кто
      // хочет сперва осмотреться, надо дать это сделать, а не заставлять
      // угадывать.
      (function () {
        var ряд = el("div", "ways");
        ряд.appendChild(el("div", "waynote",
          "Расскажите словами — разберусь сам. Или сперва покажу, что тут есть."));
        var сам = el("button", "addone", "Покажите, что тут есть");
        сам.type = "button";
        сам.addEventListener("click", function () { проводник(); });
        var словами = el("button", "addone", "Расскажу словами");
        словами.type = "button";
        словами.addEventListener("click", function () {
          ряд.remove();
          input.focus();
        });
        ряд.appendChild(словами);
        ряд.appendChild(сам);
        log.appendChild(ряд);
        log.scrollTop = log.scrollHeight;
      })();
      }

      // Выход, который не доехал до службы, называется вслух — и ровно один
      // раз. Молчание здесь было бы худшим из вариантов: человек ушёл бы
      // уверенный, что сессия закрыта, а она осталась бы годной.
      try {
        var недовыход = localStorage.getItem("fixar.logout.warn");
        if (недовыход) {
          localStorage.removeItem("fixar.logout.warn");
          say("bot", "Ф", T("Из учётной записи вы вышли, и ключ в этом браузере " +
              "стёрт. Но службе о выходе сообщить не удалось (") + недовыход +
              T("), а значит на её стороне сессия могла остаться рабочей. " +
              "Если устройство не ваше — войдите с другого и выйдите ещё раз."));
        }
      } catch (e0) { /* хранилище закрыто — сказать нечего и негде */ }
      startChips();
      setupVoice();
      завестиПодсказку();
      // Где идёт разговор — до первого сообщения, а не после.
      renderWhere();
      document.getElementById("togeneral")
        .addEventListener("click", toGeneral);
      var уводДела = document.getElementById("reroute");
      if (уводДела) уводДела.addEventListener("click", сменитьНаправление);
      var сменаРабот = document.getElementById("swagent");
      if (сменаРабот) сменаРабот.addEventListener("click", сменитьРаботника);
      var стадияДела = document.getElementById("stage");
      if (стадияДела) стадияДела.addEventListener("click", назватьСтадию);
      // Порядок важен: сперва считаем дела, потом решаем, показывать ли
      // совет про второй вход — он смотрит на их число.
      showMe(me);
      document.getElementById("credits")
        .addEventListener("click", creditMenu);
      // Список закрывается щелчком мимо: открытый поверх страницы, он иначе
      // остаётся висеть и перекрывает то, ради чего его закрыли.
      document.addEventListener("click", function (e) {
        var м = document.getElementById("credmenu");
        if (!м) return;
        // СВЕРЯЕМ ВХОЖДЕНИЕ, А НЕ РАВЕНСТВО УЗЛУ. Здесь стояло
        // `e.target.id === "credits"`, и меню было НЕОТКРЫВАЕМЫМ пальцем:
        // у чипа два потомка — `<span>кредиты</span>` и `<b>0</b>`, — и
        // щелчок попадает в них, а не в саму кнопку. Событие всплывало,
        // меню открывалось, а этот сторож тут же его закрывал, потому что
        // цель — потомок, а не узел. Снаружи это выглядело как «щёлкаю по
        // кредитам — ноль реакции», и работало только попадание в отступ.
        //
        // Для меню вхождение проверялось с самого начала (`m_внутри(м, …)`) —
        // ровно та же проверка нужна была и кнопке.
        if (!щелчок_мимо_кредитов(e.target)) return;
        closeCredMenu();
      });
      // Без await намеренно: остаток — справка рядом с именем, и пуск не должен
      // ждать её ради разговора. Своих отказов эта функция наружу не выпускает,
      // поэтому упасть в «сервис недоступен» из-за неё нечему.
      refreshCredits();
      setupMail();
      setupPhone();
      wireTelegram();
      setupCrew();
      setupCanvas();
      setupFiles();
      setupSheets();
      // КНОПКА ТЕПЕРЬ ДЕЛАЕТ ТО, ЧТО НАПИСАНО НА НЕЙ. Прежде «Новое дело»
      // звало toGeneral — то есть выходило в общий разговор и не заводило
      // ничего; настоящего заведения руками в продукте не было вовсе. Выход
      // в общий разговор остаётся на своей кнопке, #togeneral.
      // Удаление из шапки ведёт В ТУ ЖЕ дорогу, что и слово «удали дело» в
      // разговоре: askDelete показывает опись и требует набрать название.
      // Второй путь к необратимому разошёлся бы с первым на первой же правке
      // правил — и разошёлся бы молча.
      if (casedrop) {
        casedrop.addEventListener("click", function () {
          if (state.caseId) askDelete(state.caseId);
        });
      }
      setupMakeCase();
      setupThreadWindow();
      setupBell();
      setupPolling();
      await renderScopes();
      await renderVaultPlace();
      // Прежнее дело возвращается только если оно всё ещё в списке ЭТОГО
      // человека — проверка внутри restoreCase.
      await restoreCase();
      // ОБЕ НАСТРОЙКИ ДЕЛА — ПОСЛЕ ВОЗВРАТА ДЕЛА, а не до него. Прежде
      // `renderEgress` стоял выше: на пуске `state.caseId` ещё пуст, панель
      // пряталась и больше не звалась ниоткуда — то есть тумблер выноса не
      // показывался вовсе до перезагрузки страницы с уже открытым делом.
      // Найдено, когда рядом встала вторая такая же панель.
      await renderEgress();
      await renderEffort();
      if (!state.caseId && state.caseCount) {
        // Дела есть, но ни одно не открыто. Оставить здесь «дело появится,
        // как только вы начнёте» значило бы прямо противоречить списку выше.
        showEmpty(state.inbox === false
          ? "Ни одно дело не открыто. Выберите его в списке выше — или просто " +
            "напишите, и заведётся новое."
          : state.inbox === null
            // То же третье состояние, что в приветствии: пока не проверено —
            // не обещаем. Прежде эта строка утверждала «дело само не
            // заведётся» на том же экране, где приветствие честно говорило,
            // что ещё не знает.
            ? "Ни одно дело не открыто. Выберите дело в списке выше — или " +
              "пишите сюда: включён ли общий разговор, выяснится на первом " +
              "сообщении."
            : "Ни одно дело не открыто, и разговор сейчас общий. Выберите дело " +
              "в списке выше — или пишите сюда, дело само не заведётся.");
      }
      // Дело могло восстановиться — строка «где я» обязана это учесть.
      renderWhere();
      // Подтверждение, оставшееся без ответа, — первое, о чём человек должен
      // узнать: список дел уже прочитан, и он видит его рядом с вопросом.
      restorePendingConfirm();
      await setupSignin(me);
      if (me && me.signed_in) {
        try {
          if (sessionStorage.getItem("fixar.v2.login.return") === "1") {
            sessionStorage.removeItem("fixar.v2.login.return");
            location.replace("/v2/");
            return;
          }
        } catch (e) { /* продолжаем обычный экран */ }
      }
      await maybeInvite();
    } catch (e) {
      stateEl.textContent = T("сервис недоступен");
      stateEl.className = "state demo";
      notice.hidden = false;
      /* Переводим фразу ЦЕЛИКОМ, одной обёрткой. Прицельный обход обернул
         только вторую половину, и полоса выходила наполовину русской: в
         английском другой порядок слов, и половинки порознь не собираются. */
      notice.innerHTML = T("<b>Сервис сейчас не отвечает.</b> " +
        "Это не демонстрация — что-то со связью: ") + T(e.message);
    } finally {
      убратьЗаставку();
    }
  })();


  /* ── Уведомление о хранении в браузере ────────────────────────────────────
   *
   * ПОЧЕМУ УВЕДОМЛЕНИЕ, А НЕ СОГЛАСИЕ. Сайт не ставит НИ ОДНОЙ cookie и не
   * держит ни одного чужого счётчика — соглашаться человеку не на что.
   * Баннер с кнопкой «отклонить», которая ничего не отключает, врёт дважды:
   * сообщает, что за человеком следят, и создаёт впечатление, будто он это
   * запретил. На это стоит сторож в tests/test_cookie_notice.py: появится
   * cookie или чужой скрипт — он покраснеет, и уведомление придётся
   * превратить в настоящее согласие с выбором.
   *
   * ОТМЕТКА О ПРОЧТЕНИИ ЛЕЖИТ ТАМ ЖЕ, ГДЕ ВСЁ ОСТАЛЬНОЕ, и это не небрежность:
   * хранить её в cookie значило бы завести первую cookie ради сообщения о том,
   * что их нет.
   *
   * КНОПКА «СТЕРЕТЬ» НАСТОЯЩАЯ. Она чистит своё — всё с приставкой `fixar.` в
   * обоих хранилищах, включая ключ сессии, — и перезагружает страницу. Чужого
   * в этих хранилищах может лежать сколько угодно (соседние поддомены, другие
   * наши страницы), и стирать чужое мы не вправе.
   */
  var УВЕДОМЛЕНИЕ = "fixar.notice.storage";
  /* Версия. Сменится состав хранимого — сменится и она, и уведомление
     покажется снова: человек согласился прочитать про ТО, что было. */
  var ВЕРСИЯ_УВЕДОМЛЕНИЯ = "2";

  function своиКлючи(хранилище) {
    var список = [], i, имя;
    try {
      for (i = 0; i < хранилище.length; i++) {
        имя = хранилище.key(i);
        if (имя && имя.indexOf("fixar.") === 0) { список.push(имя); }
      }
    } catch (e) { /* приватный режим: хранилища просто нет */ }
    return список;
  }

  function стеретьСвоё() {
    var i, ключи;
    ключи = своиКлючи(window.localStorage || {});
    for (i = 0; i < ключи.length; i++) {
      try { localStorage.removeItem(ключи[i]); } catch (e) { /* нечего */ }
    }
    ключи = своиКлючи(window.sessionStorage || {});
    for (i = 0; i < ключи.length; i++) {
      try { sessionStorage.removeItem(ключи[i]); } catch (e) { /* нечего */ }
    }
  }

  function уведомлениеОХранении() {
    var бар = document.getElementById("cookiebar");
    if (!бар) { return; }
    var прочитано = "";
    try { прочитано = localStorage.getItem(УВЕДОМЛЕНИЕ) || ""; } catch (e) { }
    if (прочитано !== ВЕРСИЯ_УВЕДОМЛЕНИЯ) { бар.hidden = false; }

    var ок = document.getElementById("cookieok");
    if (ок) {
      ок.addEventListener("click", function () {
        бар.hidden = true;
        /* Приватный режим: отметку сохранить негде, и уведомление покажется
           снова. Это верно — там и хранить-то нечего, о чём уведомлять. */
        try { localStorage.setItem(УВЕДОМЛЕНИЕ, ВЕРСИЯ_УВЕДОМЛЕНИЯ); } catch (e) { }
      });
    }
    var стереть = document.getElementById("cookiewipe");
    if (стереть) {
      стереть.addEventListener("click", function () {
        стеретьСвоё();
        /* Перезагрузка, а не «показать пустую оболочку»: половина состояния
           живёт в памяти страницы, и без перезагрузки человек увидел бы
           сайт, который помнит стёртое. */
        location.reload();
      });
    }
  }

  уведомлениеОХранении();
})();
